Object.assign(window.TEM8_DICTIONARY, {"consequence":{"media":{"uk":"media/uk/xconsequence__gb_1.mp3","us":"media/us/xconsequence__us_1.mp3"},"oxford":{"phon":"ˈkɒnsɪkwəns","pos":"noun","senses":[{"en":"a result of something that has happened, especially an unpleasant result","cn":"后果；结果","g":"[countable, usually plural]","ex":{"en":"Remember that actions have consequences.","cn":"记住，行为总会产生后果。"}},{"en":"importance","cn":"重要性","g":"[uncountable]","lab":"formal","ex":{"en":"Don't worry. It's of no consequence.","cn":"别担心，这无关紧要。"}},{"en":"a game in which each player writes the first line of a story on a piece of paper and then passes it to the next player who writes the second line, and so on. Each player folds the paper so that the next player cannot see what is already written. The result is a number of crazy and often funny stories. The stories follow a pattern that always begins with the names of two people and ends with the sentence 'And the consequence was…’","cn":"结果：一个游戏，其中每个玩家将故事的第一行写在纸上，然后将其传递给下一个写第二行的玩家，依此类推。每个玩家都折叠纸张，以便下一个玩家看不到已经写的内容。结果产生了许多疯狂且常常有趣的故事。故事遵循的模式总是以两个人的名字开头，以“结果是……”结尾。","g":"[uncountable]","lab":"British English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"结果;后果；影响","en":"The consequences of something are the results or effects of it.","ex":{"en":"Her lawyer said she understood the consequences of her actions and was prepared to go to jail","cn":"她的律师说她明白自己行为的后果，已有了入狱的心理准备。"}},{"pos":"PHRASE 短语","cn":"结果;因此","en":"If one thing happens and then another thing happens in consequence or as a consequence, the second thing happens as a result of the first.","ex":{"en":"His death was totally unexpected and, in consequence, no plans had been made for his replacement","cn":"他的死完全出乎意料，所以，根本没有安排替补人选。"}},{"pos":"PHRASE 短语","cn":"重要的;有价值的","en":"Something or someone of consequence is important or valuable. If something or someone is of no consequence, or of little consequence, they are not important or valuable.","ex":{"en":"As an overseer, he suddenly found himself a person of consequence","cn":"作为工头，他突然觉得自己是个重要人物。"}},{"pos":"PHRASE 短语","cn":"承担后果;自食其果","en":"If you tell someone that they must take the consequences or face the consequences, you warn them that something unpleasant will happen to them if they do not stop behaving in a particular way.","ex":{"en":"These pilots must now face the consequences of their actions and be brought to trial","cn":"这些飞行员现在必须为自己的行为承担后果，接受审判。"}}]},"examples":[{"en":"The child was born deformed in consequence of an injury to its mother.","cn":"由于母亲受过伤，这小孩生下来是畸形。"},{"en":"This decision could have serious consequences for the industry.","cn":"这项决定可能对该行业造成严重后果。"}]},"contrary":{"media":{"uk":"media/uk/xcontrary__gb_1.mp3","us":"media/us/xcontrary__us_1.mp3"},"oxford":{"phon":"ˈkɒntrəri","pos":"adjective","senses":[{"en":"different from something; against something","cn":"与之相异的；相对立的；相反的","ex":{"en":"Contrary to popular belief, many cats dislike milk.","cn":"与普遍的看法相反，许多猫不喜欢牛奶。"}},{"en":"completely different in nature or direction","cn":"（在性质或方向上）截然不同的，完全相反的","g":"[only before noun]","ex":{"en":"contrary advice/opinions/arguments","cn":"完全相反的建议／观点／论点"}},{"en":"the opposite fact, event or situation","cn":"相反的事实（或事情、情况）","ex":{"en":"In the end the contrary was proved true: he was innocent and she was guilty.","cn":"最后证明事实正好相反：他是无辜的，而她则有罪。"},"pos":"noun"},{"en":"behaving badly; choosing to do or say the opposite of what is expected","cn":"乖戾的；好与人作对的；逆反的；犟的","ex":{"en":"She was such a contrary child—it was impossible to please her.","cn":"这孩子老跟人作对，没法让她高兴。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"相反的;相对的","en":"Ideas, attitudes, or reactions that are contrary to each other are completely different from each other.","ex":{"en":"This view is contrary to the aims of critical social research for a number of reasons","cn":"之所以说此观点违背了批判性社会研究的宗旨，有几点理由。"}},{"pos":"PREP-PHRASE 短语介词","cn":"与…相反","en":"If you say that something is true contrary to other people's beliefs or opinions, you are emphasizing that it is true and that they are wrong.","ex":{"en":"Contrary to popular belief, moderate exercise actually decreases your appetite","cn":"与通常的看法相反，适度的运动事实上会降低食欲。"}},{"pos":"PHRASE 短语","cn":"相反地","en":"You use on the contrary when you have just said or implied that something is not true and are going to say that the opposite is true.","ex":{"en":"It is not an idea around which the Community can unite. On the contrary, I see it as one that will divide us.","cn":"这种想法并不能让欧共体团结一致。相反地，我认为它会导致我们的分裂。"}},{"pos":"PHRASE 短语","cn":"恰恰相反;正相反","en":"You can use on the contrary when you are disagreeing strongly with something that has just been said or implied, or are making a strong negative reply.","ex":{"en":"'People just don't do things like that.' — 'On the contrary, they do them all the time.'","cn":"“人们根本不会做那样的事情。”——“恰恰相反，他们一直在那样做。”"}},{"pos":"PHRASE 短语","cn":"完全相反;完全不同;根本不是","en":"You can use quite the contrary to emphasize a previous negative statement, or when you are making a strong negative reply.","ex":{"en":"I'm not a feminist, quite the contrary","cn":"我不是一个女权主义者，根本不是。"}},{"pos":"PHRASE 短语","cn":"相反地","en":"When a particular idea is being considered, evidence or statements to the contrary suggest that this idea is not true or that the opposite is true.","ex":{"en":"That does not automatically mean, however, that the money supply has been curbed, and there is considerable evidence to the contrary","cn":"然而，那并不一定意味着货币供应量受到了限制，有大量证据表明事实正好相反。"}}]},"examples":[{"en":"The contrary view is that prison provides an excellent education — in crime.","cn":"截然不同的看法是监狱在犯罪方面提供极好的教育。"},{"en":"In the end the contrary was proved true: he was innocent and she was guilty.","cn":"最后证明事实正好相反：他是无辜的，而她则有罪。"}]},"coconut":{"media":{"img":["media/pic/tropical_fruit_comp.jpg","media/thumb/coconut.jpg"],"uk":"media/uk/coconut__gb_1.mp3","us":"media/us/coconut__us_1.mp3"},"oxford":{"phon":"ˈkəʊkənʌt","pos":"noun","senses":[{"en":"the large nut of a tropical tree called a coconut palm. It grows inside a hard shell and contains a soft white substance that can be eaten and juice that can be drunk.","cn":"椰子","g":"[countable]","ex":{"en":"She broke open the coconut and drank its sweet milk.","cn":"她打开椰子喝里面的甜椰汁。"}},{"en":"the soft white substance inside a coconut, used in cooking, making soap, etc.","cn":"（用于烹调、制作肥皂等的）椰子肉，椰蓉","g":"[uncountable]","ex":{"en":"desiccated coconut","cn":"椰子干"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"椰子","en":"A coconut is a very large nut with a hairy shell, which has white flesh and milky juice inside it.","ex":{"en":"...the smell of roasted meats mingled with spices, coconut oil and ripe tropical fruits.","cn":"烤肉掺杂着香料、椰子油和熟透的热带水果的味道"}},{"pos":"N-UNCOUNT 不可数名词","cn":"椰肉","en":"Coconut is the white flesh of a coconut.","ex":{"en":"...desiccated coconut.","cn":"椰子干"}}]},"examples":[{"en":"coconut biscuits/cookies","cn":"椰蓉饼干"},{"en":"desiccated coconut","cn":"椰子干"}]},"competing":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"相互冲突的;相互矛盾的","en":"Competing ideas, requirements, or interests cannot all be right or satisfied at the same time.","ex":{"en":"They talked about the competing theories of the origin of life.","cn":"他们讨论了几种相互矛盾的生命起源理论。"}}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld42competing.mp3","us":"media/ldoce/hwd/ame/0/ld42competing.mp3"},"examples":[{"en":"Several people gave competing accounts of the accident.","cn":"几个人对这一事件的说法互相矛盾。"},{"en":"a compromise between competing interests within the organization","cn":"该团体内利益冲突的各方之间的妥协"}],"oxford":{"phon":"kəmˈpiːtɪŋ","pos":"adjective","senses":[{"en":"unable to exist or be true at the same time","cn":"相互矛盾的；抵触的","ex":{"en":"There were several competing accounts of what actually happened that night.","cn":"关于那天晚上究竟发生了什么，有几种相互矛盾的说法。"}},{"en":"each trying to get the attention of possible customers and be more successful than others","cn":"相互竞争的","ex":{"en":"competing brands of diet soda","cn":"无糖汽水的竞争品牌"}},{"en":"used to describe the different teams or players in a competition","cn":"（竞赛中的团队或选手）对抗的","ex":{"en":"Five competing teams will vie for the trophy.","cn":"将有五个参赛队争夺这一奖杯。"}}]},"base":"compete"},"completely":{"media":{"uk":"media/uk/completely__gb_1.mp3","us":"media/us/completely__us_1.mp3"},"oxford":{"phon":"kəmˈpliːtli","pos":"adverb","senses":[{"en":"in every way possible; in every part","cn":"彻底地；完全地；完整地","ex":{"en":"It was completely different from how I had imagined it.","cn":"这和我想象的完全不一样。"}}]},"examples":[{"en":"I've completely forgotten her name.","cn":"我完全把她的名字给忘了。"},{"en":"The explosion completely destroyed the building.","cn":"爆炸完全毁掉了那栋大楼。"}]},"convenience":{"media":{"uk":"media/uk/xconvenience__gb_1.mp3","us":"media/us/xconvenience__us_1.mp3"},"oxford":{"phon":"kənˈviːniəns","pos":"noun","senses":[{"en":"the quality of being useful, easy or suitable for somebody","cn":"方便；适宜；便利","g":"[uncountable]","ex":{"en":"We have provided seats for the convenience of our customers.","cn":"为方便顾客我们备有座位。"}},{"en":"something that is useful and can make things easier or quicker to do, or more comfortable","cn":"便利的事物（或设施）；方便的用具","g":"[countable]","ex":{"en":"It was a great convenience to have the school so near.","cn":"学校这么近真是太方便了。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"方便;便利;合宜","en":"If something is done for your convenience, it is done in a way that is useful or suitable for you.","ex":{"en":"He was happy to make a detour for her convenience.","cn":"为了她方便，他很乐意绕道。"}},{"pos":"N-COUNT 可数名词","cn":"带来方便的事物","en":"If you describe something as a convenience, you mean that it is very useful.","ex":{"en":"Mail order is a convenience for buyers who are too busy to shop.","cn":"邮购对于那些没有时间逛商店的购物者来说是一项非常方便的服务。"}},{"pos":"N-COUNT 可数名词","cn":"便利设施;便利装置","en":"Conveniences are pieces of equipment designed to make your life easier.","ex":{"en":"Some TVRs have power steering and conveniences such as central locking and powered windows.","cn":"一些特雷沃车型配有动力转向系统以及中央锁和电动窗之类的便利装置。"}},{"pos":"N-COUNT 可数名词","cn":"公共厕所","en":"A public convenience is a building containing toilets which is provided in a public place for anyone to use.","ex":{"en":"...the cubicles of a public convenience.","cn":"公共厕所的小隔间"}}]},"examples":[{"en":"In this resort you can enjoy all the comfort and convenience of modern tourism.","cn":"在这个度假胜地你可享受所有现代旅游的舒适与便利。"},{"en":"Can you telephone me at your convenience to arrange a meeting?","cn":"你能不能在你方便时给我来个电话，安排见一次面？"}]},"comp":{"oxford":{"phon":"kɒmp","pos":"noun","senses":[{"en":"a comprehensive (= a secondary school for young people of all levels of ability)","cn":"（英国为各种资质的学生设立的）综合中学","g":"[countable]","lab":"British English","ex":{"en":"Her children go to the local comp.","cn":"她的孩子们上当地的综合中学。"}},{"en":"a competition (= an event in which people compete with each other to find out who is the best at something)","cn":"比赛；竞赛","g":"[countable]","lab":"British English","ex":{"en":"To enter our comp answer this question.","cn":"要进入我们的比赛，请回答这个问题。"}},{"en":"a complimentary ticket, meal, etc. (= one that you do not have to pay for)","cn":"赠品（如入场券、膳食等）","g":"[countable]","lab":"North American English"},{"en":"compensation (= something, especially money, that somebody gives you because they have hurt you, or damaged something that you own; the act of giving this to somebody)","cn":"补偿（或赔偿）物；（尤指）赔偿金，补偿金；赔偿","g":"[uncountable]","lab":"North American English","ex":{"en":"comp time (= time off work given for working extra hours)","cn":"（加班后的）补休时间"}}]},"media":{"uk":"media/uk/comp__gb_1.mp3","us":"media/us/comp__us_1.mp3"},"examples":[{"en":"Her children go to the local comp.","cn":"她的孩子们上当地的综合中学。"},{"en":"comp time (= time off work given for working extra hours) （","cn":"加班后的）补休时间"}]},"convinces":{"lemma":"convince","media":{"uk":"media/uk/xconvince__gb_1.mp3","us":"media/us/xconvince__us_1.mp3"}},"coaster":{"media":{"uk":"media/uk/coaster__gb_1.mp3","us":"media/us/coaster__us_1.mp3"},"oxford":{"phon":"ˈkəʊstə(r)","pos":"noun","senses":[{"en":"a small flat object that you put under a glass to protect the top of a table","cn":"玻璃杯垫"},{"en":"a ship that sails from port to port along a coast","cn":"航行于沿海港口间的轮船"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"杯垫","en":"A coaster is a small mat that you put underneath a glass or cup to protect the surface of a table."},{"pos":"N-COUNT 可数名词","cn":"沿海港口间航行的货船","en":"A coaster is a ship that sails along the coast taking goods to ports."}]}},"conquest":{"media":{"uk":"media/uk/xconquest__gb_1.mp3","us":"media/us/xconquest__us_1.mp3"},"oxford":{"phon":"ˈkɒŋkwest","pos":"noun","senses":[{"en":"the act of taking control of a country, city, etc. by force","cn":"征服；占领","g":"[countable, uncountable]","ex":{"en":"the Norman Conquest (= of England in 1066)","cn":"诺曼征服（即 1066 年诺曼人征服英格兰）"}},{"en":"an area of land taken by force","cn":"占领（或征服）的地区","g":"[countable]","ex":{"en":"the Spanish conquests in South America","cn":"西班牙人在南美洲的占领地"}},{"en":"a person that somebody has persuaded to love them or to have sex with them","cn":"（爱情或性方面）被俘虏的人","g":"[countable]","lab":"usually humorous","ex":{"en":"I'm just one of his many conquests.","cn":"我仅仅是他的众多俘虏之一。"}},{"en":"the act of gaining control over something that is difficult or dangerous","cn":"（对困难、危险等的）控制","g":"[uncountable]","ex":{"en":"the conquest of inflation","cn":"对通货膨胀的控制"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"征服;占领","en":"Conquest is the act of conquering a country or group of people.","ex":{"en":"He had led the conquest of southern Poland in 1939","cn":"1939年，他指挥了攻占波兰南部的行动。"}},{"pos":"N-COUNT 可数名词","cn":"(战争中)征服的土地,占领地","en":"Conquests are lands that have been conquered in war.","ex":{"en":"He had realized that Britain could not have peace unless she returned at least some of her former conquests.","cn":"他意识到除非英国至少归还一部分以前的占领地，否则国无宁日。"}},{"pos":"N-COUNT 可数名词","cn":"（爱情或性关系方面的）俘虏，征服","en":"If someone makes a conquest, they succeed in attracting and usually sleeping with another person. You usually use conquest when you want to indicate that this relationship is not important to the person concerned.","ex":{"en":"Despite his conquests, he remains lonely and isolated.","cn":"尽管他俘获过很多女人的芳心，却依然孤单寂寞。"}},{"pos":"N-COUNT 可数名词","cn":"（爱情或性关系方面）被俘虏者","en":"You can refer to the person that someone has succeeded in attracting as their conquest.","ex":{"en":"Pushkin was a womaniser whose conquests included everyone from prostitutes to princesses.","cn":"普希金是个情场老手，各种各样的女性，从妓女到公主，都成了他的俘虏。"}},{"pos":"N-SING 单数名词","cn":"克服;攻克","en":"The conquest of something such as a problem is success in ending it or dealing with it.","ex":{"en":"The conquest of inflation has been the Government's overriding economic priority for nearly 15 years.","cn":"遏制通货膨胀是政府近15年来经济工作方面的头等大事。"}}]},"examples":[{"en":"the Norman Conquest (= of England in 1066)","cn":"诺曼征服（即 1066 年诺曼人征服英格兰）"},{"en":"I'm just one of his many conquests.","cn":"我仅仅是他的众多俘虏之一。"}]},"contribute":{"media":{"uk":"media/uk/xcontribute__gb_1.mp3","us":"media/us/xcontribute__us_1.mp3"},"oxford":{"phon":"kənˈtrɪbjuːt","pos":"verb","senses":[{"en":"to give something, especially money or goods, to help achieve or provide something","cn":"捐献，捐赠（尤指金钱或物品）；捐助","g":"[intransitive, transitive]","ex":{"en":"Do you wish to contribute?","cn":"你想捐助吗？"}},{"en":"to be one of the causes of something","cn":"是…的原因之一","g":"[intransitive]","ex":{"en":"Human error may have been a contributing factor.","cn":"人为过错可能是一个起作用的因素。"}},{"en":"to increase, improve or add to something","cn":"增加；增进；添加（到某物）","g":"[intransitive, transitive]","ex":{"en":"Immigrants have contributed to British culture in many ways.","cn":"移民在许多方面都对英国文化有所贡献。"}},{"en":"to write things for a newspaper, book, website, etc. or a radio or television programme; to speak during a meeting or conversation, especially to give your opinion","cn":"（为书报、网站、电台或电视节目等）撰稿；（在会议或会谈期间）讲话，（尤指）发表意见","g":"[intransitive, transitive]","ex":{"en":"The blog now has about 20 people contributing regularly.","cn":"这个博客现在有大约 20 人定期供稿。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(为…)做贡献","en":"If you contribute to something, you say or do things to help to make it successful.","ex":{"en":"The three sons also contribute to the family business","cn":"这3个儿子也为家族事业做出了贡献。"}},{"pos":"VERB 动词","cn":"捐献;捐助;援助","en":"To contribute money or resources to something means to give money or resources to help pay for something or to help achieve a particular purpose.","ex":{"en":"The US is contributing $4 billion in loans, credits and grants","cn":"美国将提供40亿美元的信贷和赠款。"}},{"pos":"VERB 动词","cn":"促成;促使；是导致…的原因之一","en":"If something contributes to an event or situation, it is one of the causes of it.","ex":{"en":"The report says design faults in both the vessels contributed to the tragedy","cn":"报告说两艘船存在的设计缺陷也促成了这场悲剧的发生。"}},{"pos":"VERB 动词","cn":"(为报刊、书籍等)撰稿","en":"If you contribute to a magazine, newspaper, or book, you write things that are published in it.","ex":{"en":"I was asked to contribute to a newspaper article making predictions for the new year","cn":"我受邀为报纸撰写一篇文章，对新的一年进行预测。"}}]},"examples":[{"en":"Medical negligence was said to have contributed to her death.","cn":"据说医务人员的玩忽职守是她死亡的原因之一。"},{"en":"We contributed £5 000 to the earthquake fund.","cn":"我们向地震基金捐赠了 5 000 英镑。"}]},"condenses":{"lemma":"condense"},"contented":{"media":{"uk":"media/uk/xcontented__gb_1.mp3","us":"media/us/xcontented__us_1.mp3"},"oxford":{"phon":"kənˈtentɪd","pos":"adjective","senses":[{"en":"showing or feeling happiness or pleasure, especially because your life is good","cn":"（尤指因生活好而）满意的，惬意的，满足的","ex":{"en":"a contented smile","cn":"惬意的微笑"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"满足的;满意的","en":"If you are contented, you are satisfied with your life or the situation you are in.","ex":{"en":"Whenever he returns to this place he is happy and contented","cn":"每次回到这个地方，他都十分快乐，心满意足。"}}]},"examples":[{"en":"He was a contented man.","cn":"他是个心满意足的人。"},{"en":"She smiled contentedly.","cn":"她心满意足地笑了。"}],"base":"content"},"collaboration":{"oxford":{"phon":"kəˌlæbəˈreɪʃn","pos":"noun","senses":[{"en":"the act of working with another person or group of people to create or produce something","cn":"合作；协作","g":"[uncountable, countable]","ex":{"en":"It was a collaboration that produced extremely useful results.","cn":"这是一次带来极其有益的成果的合作。"}},{"en":"a piece of work produced by two or more people or groups of people working together","cn":"合作成果（或作品）","g":"[countable]","ex":{"en":"The exhibition is a collaboration with the Australian Centre for the Moving Image.","cn":"该展览是与澳大利亚移动图像中心合作举办的。"}},{"en":"the act of helping the enemy during a war when they have taken control of your country","cn":"通敌；勾结敌人","g":"[uncountable]","lab":"disapproving","ex":{"en":"his wartime collaboration with the Nazis","cn":"他战时与纳粹的勾结"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(尤指在著书或研究方面的)合作，协作","en":"Collaboration is the act of working together to produce a piece of work, especially a book or some research.","ex":{"en":"There is substantial collaboration with neighbouring departments","cn":"与相邻的一些部门有大量的合作。"}},{"pos":"N-COUNT 可数名词","cn":"合作(或协作)的成果","en":"A collaboration is a piece of work that has been produced as the result of people or groups working together.","ex":{"en":"He was also a writer of beautiful stories, some of which are collaborations with his fiancee.","cn":"他还写了一些美妙的故事，其中有些是和他的未婚妻合著的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"通敌;勾结敌人","en":"Collaboration is the act of helping an enemy who is occupying your country during a war.","ex":{"en":"She faced charges of collaboration.","cn":"她面临通敌的指控。"}}]},"media":{"uk":"media/uk/collaboration__gb_1.mp3","us":"media/us/collaboration__us_1.mp3"},"examples":[{"en":"The government worked in close collaboration with teachers on the new curriculum.","cn":"政府和教师就新的课程进行了紧密协作。"},{"en":"She wrote the book in collaboration with one of her students.","cn":"她和她的一个学生合写了这本书。"}]},"comparable":{"media":{"uk":"media/uk/comparable__gb_1.mp3","us":"media/us/comparable__us_1.mp3"},"oxford":{"phon":"ˈkɒmpərəbl","pos":"adjective","senses":[{"en":"similar to somebody/something else and able to be compared","cn":"类似的；可比较的","ex":{"en":"A comparable house in the south of the city would cost twice as much.","cn":"一栋类似的房子位于城南就要贵一倍。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"类似的;同类的","en":"Something that is comparable to something else is roughly similar, for example in amount or importance.","ex":{"en":"...paying the same wages to men and women for work of comparable value","cn":"男女同工同酬"}},{"pos":"ADJ 形容词","cn":"可比的;可比较的","en":"If two or more things are comparable, they are of the same kind or are in the same situation, and so they can reasonably be compared.","ex":{"en":"In other comparable countries real wages increased much more rapidly","cn":"在其他具有可比性的国家，实际工资上涨更快。"}}]},"examples":[{"en":"Inflation is now at a rate comparable with that in other European countries.","cn":"现在通货膨胀率已经和欧洲其他国家的差不多了。"},{"en":"A comparable house in the south of the city would cost twice as much.","cn":"一栋类似的房子位于城南部就要贵一倍的价钱。"}]},"county":{"media":{"uk":"media/uk/county__gb_1.mp3","us":"media/us/county__us_1.mp3"},"oxford":{"phon":"ˈkaʊnti","pos":"noun","senses":[{"en":"one of a number of areas that some countries are divided into, each with its own local government","cn":"（英国、爱尔兰的）郡；（美国的）县","ex":{"en":"rural counties west of the Mississippi","cn":"密西西比西部的乡村县"}},{"en":"typical of English upper-class people","cn":"典型英格兰上流社会人物的；世家子弟的","pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(英国、爱尔兰的)郡;(美国的)县","en":"A county is a region of Britain, Ireland, or the USA which has its own local government.","ex":{"en":"He is living now in his mother's home county of Oxfordshire","cn":"他现在居住在他母亲的故乡牛津郡。"}}]},"examples":[{"en":"the southern counties","cn":"南部各郡"},{"en":"county boundaries","cn":"郡分界线"}]},"congruent":{"media":{"uk":"media/uk/xcongruent__gb_1.mp3","us":"media/us/xcongruent__us_1.mp3"},"oxford":{"phon":"ˈkɒŋɡruənt","pos":"adjective","senses":[{"en":"having the same size and shape","cn":"全等的；叠合的","lab":"geometry","ex":{"en":"congruent triangles","cn":"全等三角形"}},{"en":"in agreement with something; similar to something and not in conflict with it","cn":"一致的；相似的；协调的","lab":"formal","ex":{"en":"The measures are congruent with the changes in management policy.","cn":"这些措施与管理政策的变化是一致的。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"相似的;相称的;一致的","en":"If one thing is congruent with another thing, they are similar or fit together well.","ex":{"en":"They want to work in an organisation whose values are congruent with their own.","cn":"他们想在一个符合自己价值观的机构里工作。"}}]},"examples":[{"en":"congruent triangles","cn":"全等三角形"}]},"concise":{"media":{"uk":"media/uk/xconcise__gb_1.mp3","us":"media/us/xconcise__us_1.mp3"},"oxford":{"phon":"kənˈsaɪs","pos":"adjective","senses":[{"en":"giving only the information that is necessary and important, using few words","cn":"简明的；简练的；简洁的","ex":{"en":"a concise summary","cn":"简明扼要的总结"}},{"en":"shorter than the original book, on which it was based","cn":"简略的；简缩的；简明的","g":"[only before noun]","ex":{"en":"This is just a concise dictionary—you should get yourself something bigger.","cn":"这只是一本缩略版词典，你应该买一本更大部头的。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"简洁的;简明的","en":"Something that is concise says everything that is necessary without using any unnecessary words.","ex":{"en":"Burton's text is concise and informative","cn":"伯顿的文章语言简洁，信息丰富。"}},{"pos":"ADJ 形容词","cn":"(尤指词典)简明的，简缩的","en":"A concise edition of a book, especially a dictionary, is shorter than the original edition.","ex":{"en":"...Sotheby's Concise Encyclopedia of Porcelain.","cn":"《苏富比简明瓷器百科全书》"}}]},"examples":[{"en":"a concise summary","cn":"简明扼要的总结"},{"en":"clear concise instructions","cn":"言简意赅的说明"}]},"conservative":{"media":{"uk":"media/uk/xconservative__gb_1.mp3","us":"media/us/xconservative__us_1.mp3"},"oxford":{"phon":"kənˈsɜːvətɪv","pos":"adjective","senses":[{"en":"opposed to great or sudden social change; showing that you prefer traditional styles and values","cn":"保守的；守旧的","ex":{"en":"the conservative views of his parents","cn":"他父母的保守观念"}},{"en":"connected with the British Conservative Party","cn":"（英国）保守党的","ex":{"en":"Conservative members/supporters","cn":"保守党的党员／支持者"}},{"en":"lower than what is probably the real amount or number","cn":"低于实际数量的；保守的","ex":{"en":"At a conservative estimate, he'll be earning £50 000.","cn":"按照保守的估计，他会赚到 5 万英镑。"}},{"en":"a conservative person","cn":"保守者；因循守旧者","ex":{"en":"social/religious conservatives","cn":"社会／宗教保守派"},"pos":"noun"},{"en":"a member or supporter of the British Conservative Party","cn":"（英国）保守党党员，保守党支持者","ex":{"en":"Senior Conservatives are opposed to the change.","cn":"资深的保守党党员反对这项变革。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(英国)保守党的，支持保守党的","en":"A Conservative politician or voter is a member of or votes for the Conservative Party in Britain.","ex":{"en":"Most Conservative MPs appear happy with the government's reassurances.","cn":"大多数保守党下议院议员似乎都对政府的再三保证感到满意。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"持右翼观点的","en":"Someone who is conservative has right-wing views.","ex":{"en":"...counties whose citizens invariably support the most conservative candidate in any election.","cn":"其民众在任何选举中均铁定支持观点最右倾的候选人的几个郡"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"保守的;因循守旧的","en":"Someone who is conservative or has conservative ideas is unwilling to accept changes and new ideas.","ex":{"en":"People tend to be more aggressive when they're young and more conservative as they get older","cn":"人们年轻的时候往往较为激进，而随着年龄的增长会变得保守起来。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(衣着)传统的，保守的","en":"If someone dresses in a conservative way, their clothes are conventional in style.","ex":{"en":"The girl was well dressed, as usual, though in a more conservative style.","cn":"这个女孩穿得一如往日那样讲究，只是风格比平日更为传统。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(估计或猜测)保守的，稳妥的","en":"A conservative estimate or guess is one in which you are cautious and estimate or guess a low amount which is probably less that the real amount.","ex":{"en":"A conservative estimate of the bill, so far, is about £22,000","cn":"到目前为止，这笔账单保守估计为大约2.2万英镑。"}}]},"examples":[{"en":"At a conservative estimate, he'll be earning £50 000.","cn":"按照保守的估计，他会赚到 5 万英镑。"},{"en":"Her style of dress was never conservative.","cn":"她的服装式样一点儿也不保守。"}]},"contraception":{"oxford":{"phon":"ˌkɒntrəˈsepʃn","pos":"noun","senses":[{"en":"the practice of using artificial methods to avoid becoming pregnant when having sex; the methods of doing this","cn":"避孕（法）；节育（法）","ex":{"en":"to give advice about contraception","cn":"就避孕方法提供咨询"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"避孕法;节育法","en":"Contraception refers to methods of preventing pregnancy.","ex":{"en":"Use a reliable method of contraception.","cn":"采用安全的避孕方法。"}}]},"media":{"uk":"media/uk/xcontraception__gb_1.mp3","us":"media/us/xcontraception__us_1.mp3"},"examples":[{"en":"to give advice about contraception","cn":"就避孕方法提供咨询"},{"en":"The pill is a popular method of contraception.","cn":"服用避孕药是一种常用的避孕方法。"}]},"coin":{"media":{"img":["media/ldoce/img/coin.jpg","media/pic/money_comp.jpg"],"uk":"media/uk/coin__gb_1.mp3","us":"media/us/coin__us_1.mp3"},"oxford":{"phon":"kɔɪn","pos":"noun","senses":[{"en":"a small flat piece of metal used as money","cn":"（一枚）硬币；金属货币","g":"[countable]","ex":{"en":"gold coins","cn":"金币"}},{"en":"money made of metal","cn":"（统称）硬币","g":"[uncountable]","ex":{"en":"notes and coin","cn":"纸币和硬币"}},{"en":"to invent a new word or phrase that other people then begin to use","cn":"创造（新词语）","ex":{"en":"The term ‘cardboard city’ was coined to describe communities of homeless people living in cardboard boxes.","cn":"人们创造了 cardboard city 一词，用来指居住在纸板棚里的无家可归者聚集的地区。"},"pos":"verb"},{"en":"to make coins out of metal","cn":"铸（币）；造（硬币）","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"硬币","en":"A coin is a small piece of metal which is used as money.","ex":{"en":"...50 pence coins.","cn":"50便士的硬币"}},{"pos":"VERB 动词","cn":"新造，杜撰(单词、短语)","en":"If you coin a word or a phrase, you are the first person to say it.","ex":{"en":"Jaron Lanier coined the term 'virtual reality' and pioneered its early development","cn":"杰伦·拉尼尔创造了“虚拟现实”这个词，并成为推动其早期发展的先驱人物。"}},{"pos":"VERB 动词","cn":"暴富;很快地赚(钱)","en":"If you say that someone is coining it or is coining money, you are emphasizing that they are making a lot of money very quickly, often without really earning it.","ex":{"en":"Many private colleges are coining it","cn":"很多私立大学正在大发其财。"}},{"pos":"PHRASE 短语","cn":"用个双关语;套用句老话","en":"You say 'to coin a phrase' to show that you realize you are making a pun or using a cliché","ex":{"en":"Fifty local musicians have, to coin a phrase, banded together to form the Jazz Umbrella.","cn":"50名当地的音乐家，用个双关词，“联合起来”（band亦有“乐队”之意）组成了“爵士乐大联盟”。"}},{"pos":"PHRASE 短语","cn":"情况的另一面","en":"You use the other side of the coin to mention a different aspect of a situation.","ex":{"en":"These findings are a reminder that low pay is the other side of the coin of falling unemployment.","cn":"这些研究结果提醒人们，失业率下降的另一面是低薪。"}},{"pos":"PHRASE 短语","cn":"一个问题的两方面","en":"If you say that two things are two sides of the same coin, you mean that they are different ways of looking at or dealing with the same situation.","ex":{"en":"The minister reportedly stressed that economic and political reforms were two sides of the same coin.","cn":"据报道，部长强调经济改革和政治改革是一个问题的两个方面。"}}]},"examples":[{"en":"The term ‘cardboard city’ was coined to describe communities of homeless people living in cardboard boxes.","cn":"人们创造了 cardboard city 一词，用来指居住在纸板屋棚里无家可归者所聚集的地区。"},{"en":"Oh well, no news is good news, to coin a phrase.","cn":"噢，常言道，没有消息就是好消息。"}]},"combined":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"联合的;共同的","en":"A combined effort or attack is made by two or more groups of people at the same time.","ex":{"en":"These refugees are looked after by the combined efforts of the host countries and non-governmental organisations.","cn":"在几个接收国和一些非政府组织的共同努力下，这些难民得以安置。"}},{"pos":"ADJ 形容词","cn":"总计的;总共的","en":"The combined size or quantity of two or more things is the total of their sizes or quantities added together.","ex":{"en":"Such a merger would be the largest in US banking history, giving the two banks combined assets of some $146 billion.","cn":"这将是美国银行业历史上最大的一次合并，使两家银行的总资产达到1,460亿美元左右。"}}]},"media":{"uk":"media/ldoce/hwd/bre/e/combined0205.mp3","us":"media/ldoce/hwd/ame/9/laadcombined.mp3"},"examples":[{"en":"Dinner was a combined effort.","cn":"晚餐是大家一起做的。"},{"en":"Her records have sold a combined total of 14 million copies.","cn":"她的唱片总计销量为1,400万张。"}],"oxford":{"phon":"kəmˈbaɪnd","pos":"adjective","senses":[{"en":"put, added or joined together","cn":"结合的；联合的","ex":{"en":"The German team scored a combined total of 652 points.","cn":"德国队综合得分为 652 分。"}}]},"base":"combine"},"contractor":{"media":{"uk":"media/uk/xcontractor__gb_1.mp3","us":"media/us/xcontractor__us_1.mp3"},"oxford":{"phon":"kənˈtræktə(r)","pos":"noun","senses":[{"en":"a person or company that has a contract to do work or provide goods or services for another company","cn":"承包人；承包商；承包公司","ex":{"en":"a building/roofing/electrical contractor","cn":"建筑／屋顶修建／电气承包商"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"订约人;立约人;承包商","en":"A contractor is a person or company that does work for other people or organizations.","ex":{"en":"We told the building contractor that we wanted a garage big enough for two cars.","cn":"我们告诉建筑承包商，我们需要一个能容得下两辆车的车库。"}}]},"examples":[{"en":"a building/haulage, etc. contractor","cn":"建筑、货运等承包商"},{"en":"to employ an outside contractor","cn":"雇用外来承包商"}]},"convergence":{"media":{"uk":"media/uk/xconvergence__gb_1.mp3","us":"media/us/xconvergence__us_1.mp3"},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(不同思想、群体或社会的)趋同，融合","en":"The convergence of different ideas, groups, or societies is the process by which they stop being different and become more similar.","ex":{"en":"...the need to move towards greater economic convergence","cn":"朝着经济进一步融合发展的需要"}}]},"oxford":{"phon":"kənˈvɜːdʒəns","pos":"noun","senses":[{"en":"the process of moving together from different directions and meeting; the point where this happens","cn":"会聚，会聚点","g":"[uncountable]","ex":{"en":"The city was a natural point of convergence for river-based traffic.","cn":"这座城市是河流交通的天然交汇点。"}},{"en":"the process of becoming very similar or the same","cn":"趋同","g":"[uncountable, countable]","ex":{"en":"The convergence of mobile technology and the internet will continue to revolutionize the way businesses interact with consumers.","cn":"手机技术与互联网的趋同将持续改变企业与消费者互动的方式。"}}]}},"contradict":{"oxford":{"phon":"ˌkɒntrəˈdɪkt","pos":"verb","senses":[{"en":"to say that something that somebody else has said is wrong, and that the opposite is true","cn":"反驳；驳斥；批驳","ex":{"en":"All evening her husband contradicted everything she said.","cn":"整个晚上她说什么丈夫都反驳。"}},{"en":"to be so different from each other that one of them must be wrong","cn":"相抵触；相矛盾；相反","ex":{"en":"The two stories contradict each other.","cn":"这两种说法相互抵触。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"反驳;否认;驳斥","en":"If you contradict someone, you say that what they have just said is wrong, or suggest that it is wrong by saying something different.","ex":{"en":"She dared not contradict him","cn":"她不敢反驳他。"}},{"pos":"VERB 动词","cn":"与…矛盾;同… 抵触","en":"If one statement or piece of evidence contradicts another, the first one makes the second one appear to be wrong.","ex":{"en":"Her version contradicted the Govern-ment's claim that they were shot after being challenged","cn":"政府声称他们是在受到盘问后被开枪射杀的，而她的说法却与此相矛盾。"}},{"pos":"VERB 动词","cn":"违背;与…背道而驰","en":"If one policy or situation contradicts another, there is a conflict between them, and they cannot both exist or be successful.","ex":{"en":"Mr Grant feels that the cutbacks contradict the Government's commitment to better educational standards.","cn":"格兰特先生感觉这些缩减措施和政府提高教育水平的承诺背道而驰。"}}]},"media":{"uk":"media/uk/xcontradict__gb_1.mp3","us":"media/us/xcontradict__us_1.mp3"},"examples":[{"en":"All evening her husband contradicted everything she said.","cn":"整个晚上她说什么丈夫都跟她拌嘴。"},{"en":"‘No, it's not,’ she contradicted (him). “","cn":"不，不是的。”她反驳（他）说。"}]},"confidence":{"media":{"uk":"media/uk/xconfidence__gb_1.mp3","us":"media/us/xconfidence__us_1.mp3"},"oxford":{"phon":"ˈkɒnfɪdəns","pos":"noun","senses":[{"en":"the feeling that you can trust, believe in and be sure about the abilities or good qualities of somebody/something","cn":"信心；信任；信赖","g":"[uncountable]","sc":"belief in others","ex":{"en":"The president's actions hardly inspire confidence.","cn":"总统的行为很难激起人们的信心。"}},{"en":"a belief in your own ability to do things and be successful","cn":"自信心；把握","g":"[uncountable]","sc":"belief in yourself","ex":{"en":"People often lose confidence when they are criticized.","cn":"人受到批评时经常会失去信心。"}},{"en":"the feeling that you are certain about something","cn":"把握；肯定","g":"[uncountable]","sc":"feeling certain","ex":{"en":"He said he wished that he shared her confidence.","cn":"他说，他希望和她一样有信心。"}},{"en":"a feeling of trust that somebody will keep information private","cn":"（对某人会保守秘密的）信任，信赖","g":"[uncountable]","sc":"trust","ex":{"en":"It took a long time to gain her confidence (= make her feel she could trust me).","cn":"我花了很长的时间才赢得她的信任。"}},{"en":"a secret that you tell somebody","cn":"（向某人透露的）秘密，机密","g":"[countable]","lab":"formal","sc":"a secret","ex":{"en":"The girls exchanged confidences.","cn":"女孩子们相互吐露自己的心事。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"信任;信赖","en":"If you have confidence in someone, you feel that you can trust them.","ex":{"en":"I have every confidence in you","cn":"我完全相信你。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"自信;信心","en":"If you have confidence, you feel sure about your abilities, qualities, or ideas.","ex":{"en":"The band is on excellent form and brimming with confidence","cn":"这支乐队状态极佳，自信满满。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"肯定;把握","en":"If you can say something with confidence, you feel certain it is correct.","ex":{"en":"I can say with confidence that such rumors were totally groundless.","cn":"我可以肯定地说这样的谣言完全没有根据。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"私下;秘密","en":"If you tell someone something in confidence, you tell them a secret.","ex":{"en":"We told you all these things in confidence","cn":"我们告诉你的这些事都需要保密。"}},{"pos":"N-COUNT 可数名词","cn":"秘密;知心话","en":"A confidence is a secret that you tell someone.","ex":{"en":"Gregory shared confidences with Carmen.","cn":"格雷戈里和卡门说了知心话。"}}]},"examples":[{"en":"She took me into her confidence and told me about the problems she was facing.","cn":"她把我当成知己，把她面临的种种难题都向我和盘托出。"},{"en":"While girls lack confidence , boys often overestimate their abilities.","cn":"女孩通常缺乏自信，而男孩则往往会高估自己的能力。"}]},"corps":{"media":{"uk":"media/uk/corps__gb_1.mp3","us":"media/us/corps__us_1.mp3"},"oxford":{"phon":"kɔː(r)","pos":"noun","senses":[{"en":"a large unit of an army, consisting of two or more divisions","cn":"（由两个或以上师组成的）军，兵团","ex":{"en":"the commander of the third army corps","cn":"陆军第三军团的指挥官"}},{"en":"one of the groups of an army with a special responsibility","cn":"（陆军）特种部队","ex":{"en":"He's in the Royal Army Medical Corps.","cn":"他在英国皇家陆军医疗队工作。"}},{"en":"a group of people involved in a particular job or activity","cn":"（从事某工作或活动的）一群人，一组人","ex":{"en":"a corps of trained and experienced doctors","cn":"一队训练有素并富有经验的医生"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"(陆军)特种部队","en":"A corps is a part of the army which has special duties.","ex":{"en":"...the Army Medical Corps.","cn":"陆军医疗队"}},{"pos":"N-COUNT 可数名词","cn":"(美国)海军陆战队","en":"The Corps is the United States Marine Corps.","ex":{"en":"...seventy-five men, all combat veterans, all members of The Corps' most exclusive unit.","cn":"75名队员，个个作战经验丰富，全都来自海军陆战队的精锐分队"}},{"pos":"N-COUNT 可数名词","cn":"(从事某种特殊工作的)一组人，一群人","en":"A corps is a small group of people who do a special job.","ex":{"en":"...the diplomatic corps.","cn":"外交使节团"}}]},"examples":[{"en":"a corps of trained and experienced doctors","cn":"一队训练有素并富有经验的医生"},{"en":"the commander of the third army corps","cn":"陆军第三军团的指挥官"}]},"commitments":{"lemma":"commitment","media":{"uk":"media/uk/commitment__gb_1.mp3","us":"media/us/commitment__us_1.mp3"}},"congregate":{"media":{"uk":"media/uk/xcongregate__gb_1.mp3","us":"media/us/xcongregate__us_1.mp3"},"oxford":{"phon":"ˈkɒŋɡrɪɡeɪt","pos":"verb","senses":[{"en":"to come together in a group","cn":"群集；聚集；集合","ex":{"en":"Young people often congregate in the main square in the evenings.","cn":"年轻人傍晚时经常聚集在大广场上。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"集合;聚集","en":"When people congregate, they gather together and form a group.","ex":{"en":"Youngsters love to congregate here in the evenings outside cinemas showing American films","cn":"晚上，年轻人喜欢聚集在放映美国电影的电影院外面。"}}]},"examples":[{"en":"Young people often congregate in the main square in the evenings.","cn":"年轻人傍晚时经常聚集在大广场上。"},{"en":"Crowds began to congregate to hear the president’s speech.","cn":"人群开始聚拢﹐来聆听总统的演讲。"}]},"continents":{"lemma":"continent","media":{"uk":"media/uk/xcontinent__gb_2.mp3","us":"media/us/xcontinent__us_2.mp3"}},"confused":{"media":{"uk":"media/uk/xconfused__gb_1.mp3","us":"media/us/xconfused__us_1.mp3"},"oxford":{"phon":"kənˈfjuːzd","pos":"adjective","senses":[{"en":"unable to think clearly or to understand what is happening or what somebody is saying","cn":"糊涂的；迷惑的","ex":{"en":"I'm confused—say all that again.","cn":"我被搞糊涂了，把那件事从头到尾再说一遍吧。"}},{"en":"not clear or easy to understand","cn":"不清楚的；混乱的；难懂的","ex":{"en":"The children gave a confused account of what had happened.","cn":"孩子们把发生的事叙述得颠三倒四。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"困惑的;糊涂的","en":"If you are confused, you do not know exactly what is happening or what to do.","ex":{"en":"A survey showed people were confused about what they should eat to stay healthy","cn":"一项调查表明，人们对该吃什么才能保持健康这个问题感到困惑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"混乱的;难懂的","en":"Something that is confused does not have any order or pattern and is difficult to understand.","ex":{"en":"The situation remains confused as both sides claim success.","cn":"由于双方均宣称获胜，形势依然不明朗。"}}]},"examples":[{"en":"People are confused about all the different labels on food these days.","cn":"人们如今被那些五花八门的食物标签搞得稀里糊涂。"},{"en":"I'm confused — say all that again.","cn":"我被搞糊涂了，把那件事从头到尾再说一遍吧。"}],"base":"confuse"},"confined":{"media":{"uk":"media/uk/xconfined__gb_1.mp3","us":"media/us/xconfined__us_1.mp3"},"oxford":{"phon":"kənˈfaɪnd","pos":"adjective","senses":[{"en":"small and surrounded by walls or sides","cn":"狭窄而围起来的","ex":{"en":"It is cruel to keep animals in confined spaces.","cn":"把动物关在狭小的空间里是残忍的。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"受限制的；被限定的","en":"If something is confined to a particular place, it exists only in that place. If it is confined to a particular group, only members of that group have it.","ex":{"en":"The problem is not confined to Germany","cn":"问题不仅限于德国。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(空间或面积)有限的，狭小的","en":"A confined space or area is small and enclosed by walls.","ex":{"en":"His long legs bent up in the confined space.","cn":"他的两条长腿蜷在狭小的空间里。"}},{"pos":"ADJ 形容词","cn":"(因残疾或生病)受困于…的","en":"If someone is confined to a wheelchair, bed, or house, they have to stay there, because they are disabled or ill.","ex":{"en":"He had been confined to a wheelchair since childhood.","cn":"他打小就只能坐轮椅。"}}]},"examples":[{"en":"It is cruel to keep animals in confined spaces.","cn":"把动物关在狭小的空间里是残酷的。"},{"en":"The risk of infection is confined to medical personnel.","cn":"只有医务人员有受感染的风险。"}],"base":"confine"},"column":{"oxford":{"phon":"ˈkɒləm","pos":"noun","senses":[{"en":"one of the straight sections from top to bottom into which text on a page or screen is divided","cn":"（印刷页或屏幕上的）栏","ex":{"en":"a dictionary with two columns per page","cn":"每页有两栏正文的词典"}},{"en":"a series of numbers or words arranged one under the other down a page","cn":"纵行（数字或字）","ex":{"en":"to add up a column of figures","cn":"把纵行数字相加"}},{"en":"a part of a newspaper, magazine or website that appears regularly and deals with a particular subject or is written by a particular writer","cn":"（报刊、网站的）专栏，栏目","ex":{"en":"She writes a monthly column for a leading national newspaper.","cn":"她为一家全国性大报撰写每月专栏。"}},{"en":"a tall, solid post, usually round and made of stone, that supports or decorates a building or stands alone as a monument","cn":"柱；（通常为）圆形石柱；纪念柱","ex":{"en":"The temple is supported by marble columns.","cn":"这座庙宇由大理石柱支撑。"}},{"en":"a thing that is like a column in shape","cn":"圆柱状物；柱形物","ex":{"en":"a column of smoke (= smoke rising straight up)","cn":"烟柱"}},{"en":"a long, moving line of people or vehicles","cn":"（人或车辆排成行移动的）长列，纵队","ex":{"en":"a long column of troops and tanks","cn":"部队和坦克的长列纵队"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"柱;圆形石柱;纪念柱","en":"A column is a tall, often decorated cylinder of stone which is built to honour someone or forms part of a building.","ex":{"en":"...a London landmark, Nelson's Column in Trafalgar Square.","cn":"伦敦的标志性建筑，特拉法尔加广场上的纳尔逊将军纪念柱"}},{"pos":"N-COUNT 可数名词","cn":"柱状物","en":"A column is something that has a tall narrow shape.","ex":{"en":"The explosion sent a column of smoke thousands of feet into the air.","cn":"爆炸在空中形成了几千英尺高的烟柱。"}},{"pos":"N-COUNT 可数名词","cn":"(人或动物排成的)队，纵行","en":"A column is a group of people or animals which moves in a long line.","ex":{"en":"There were reports of columns of military vehicles appearing on the streets.","cn":"有报道说几队军用车辆出现在街头。"}},{"pos":"N-COUNT 可数名词","cn":"(字典、报纸或图表的)栏","en":"On a printed page such as a page of a dictionary, newspaper, or printed chart, a column is one of two or more vertical sections which are read downwards.","ex":{"en":"We had stupidly been looking at the wrong column of figures","cn":"我们稀里糊涂，看串了数字栏。"}},{"pos":"N-COUNT 可数名词","cn":"(报纸或杂志的)专栏","en":"In a newspaper or magazine, a column is a section that is always written by the same person or is always about the same topic.","ex":{"en":"His name features frequently in the social columns of the tabloid newspapers","cn":"他的名字频繁地出现在各种小报社会专栏的显著位置上。"}}]},"media":{"img":["media/ldoce/img/column.jpg","media/pic/architecture_comp.jpg"],"uk":"media/uk/column__gb_1.mp3","us":"media/us/column__us_1.mp3"},"examples":[{"en":"Their divorce filled a lot of column inches in the national papers (= got a lot of attention).","cn":"他们的离婚引起了多家全国性报纸的关注。"},{"en":"I always read her column in the local paper.","cn":"我一直读她在当地报纸上的专栏文章。"}]},"correspondence":{"media":{"uk":"media/uk/correspondence__gb_1.mp3","us":"media/us/correspondence__us_1.mp3"},"oxford":{"phon":"ˌkɒrəˈspɒndəns","pos":"noun","senses":[{"en":"the letters, emails, etc. a person sends and receives","cn":"来往信件；往来电子邮件","g":"[uncountable]","ex":{"en":"personal/private correspondence","cn":"私人来往信件"}},{"en":"the activity of writing letters","cn":"通信；通信联系","g":"[uncountable, countable]","ex":{"en":"I refused to enter into any correspondence (= to exchange letters) with him about it.","cn":"我拒绝就此问题与他通信联系。"}},{"en":"a connection between two things; the fact of two things being similar","cn":"相关；相似","g":"[countable, uncountable]","ex":{"en":"There is a close correspondence between the two extracts.","cn":"这两段摘录如出一辙。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"通信","en":"Correspondence is the act of writing letters to someone.","ex":{"en":"The judges' decision is final and no correspondence will be entered into","cn":"法官的裁决是最终裁决，再写信也不会予以审议。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"往来书信","en":"Some-one's correspondence is the letters that they receive or send.","ex":{"en":"He always replied to his correspondence","cn":"来信他总是会回。"}},{"pos":"N-COUNT 可数名词","cn":"相似;关联","en":"If there is a correspondence between two things, there is a close similarity or connection between them.","ex":{"en":"In African languages there is a close correspondence between sounds and letters.","cn":"非洲语言中的发音与字母关系密切。"}}]},"examples":[{"en":"The editor welcomes correspondence from readers on any subject.","cn":"编辑欢迎读者有关任何问题的来信。"},{"en":"I refused to enter into any correspondence (= to exchange letters) with him about it.","cn":"我拒绝就此问题与他通信联系。"}]},"combed":{"lemma":"comb"},"compounds":{"lemma":"compound"},"conduit":{"media":{"uk":"media/uk/xconduit__gb_1.mp3","us":"media/us/xconduit__us_1.mp3"},"oxford":{"phon":"ˈkɒndjuɪt","pos":"noun","senses":[{"en":"a pipe, channel or tube through which liquid, gas or electrical wire can pass","cn":"（液体、气体或电线的）管道，导管","lab":"specialist"},{"en":"a person, an organization or a country that is used to pass things or information to other people or places","cn":"中转人；中转机构；中转国","lab":"formal","ex":{"en":"The organization had acted as a conduit for money from the arms industry.","cn":"那家机构充当了从军工业向他处中转资金的渠道。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(水或布设电线的)管道，导管","en":"A conduit is a small tunnel, pipe, or channel through which water or electrical wires go."},{"pos":"N-COUNT 可数名词","cn":"（联系的）渠道，通道","en":"A conduit is a person or country that links two or more other people or countries.","ex":{"en":"Pakistan became a conduit for drugs produced in Afghanistan.","cn":"巴基斯坦成了阿富汗毒品的贩运通道。"}}]},"examples":[{"en":"The organization had acted as a conduit for money from the arms industry.","cn":"那家机构充当了从军火工业向他处中转资金的渠道。"},{"en":"Drug traffickers have used the country as a conduit for shipments to the U.S.","cn":"毒品贩子利用这个国家作为把毒品运往美国的通道。"}]},"coward":{"media":{"uk":"media/uk/coward__gb_1.mp3","us":"media/us/coward__us_1.mp3"},"oxford":{"phon":"ˈkaʊəd","pos":"noun","senses":[{"en":"a person who is not brave or who does not have the courage to do things that other people do not think are especially difficult","cn":"胆小鬼；懦夫；胆怯者","ex":{"en":"You coward! What are you afraid of?","cn":"你这胆小鬼！你怕什么呢？"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"胆小鬼;懦夫;胆怯者","en":"If you call someone a coward, you disapprove of them because they are easily frightened and avoid dangerous or difficult situations.","ex":{"en":"She accused her husband of being a coward.","cn":"她指责丈夫胆小懦弱。"}}]},"examples":[{"en":"a cowardly attack on a defenceless man","cn":"欺负一个没有自卫能力的人的不光彩行为"},{"en":"You coward! What are you afraid of?","cn":"你这胆小鬼！你怕什么呢？"}]},"coursework":{"oxford":{"phon":"ˈkɔːswɜːk","pos":"noun","senses":[{"en":"work that students do during a course of study, not in exams, that is included in their final mark","cn":"（计入最终成绩的）课程作业","ex":{"en":"Coursework accounts for 40 per cent of the final marks.","cn":"课程作业占最后总成绩的 40%。"}}]},"media":{"uk":"media/uk/coursework__gb_1.mp3","us":"media/us/coursework__us_1.mp3"},"examples":[{"en":"Coursework accounts for 40% of the final marks.","cn":"课程作业占最后总成绩的 40%。"}]},"conquered":{"lemma":"conquer"},"convenient":{"media":{"uk":"media/uk/xconvenient__gb_1.mp3","us":"media/us/xconvenient__us_1.mp3"},"oxford":{"phon":"kənˈviːniənt","pos":"adjective","senses":[{"en":"useful, easy or quick to do; not causing problems","cn":"实用的；便利的；方便的；省事的","lab":"disapproving","ex":{"en":"Fruit is a convenient source of vitamins and energy.","cn":"水果是维生素和能量的便利来源。"}},{"en":"near to a particular place; easy to get to","cn":"附近的；近便的；容易到达的","lab":"British English","ex":{"en":"The office is just five minutes from the station, so it's very convenient.","cn":"办公室离车站只有五分钟的路程，所以很方便。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"方便的;便利的","en":"If a way of doing something is convenient, it is easy, or very useful or suitable for a particular purpose.","ex":{"en":"...a flexible and convenient way of paying for business expenses","cn":"灵活而方便的业务费用支付方式"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"附近的;方便到达的;近便的","en":"If you describe a place as convenient, you are pleased because it is near to where you are, or because you can reach another place from there quickly and easily.","ex":{"en":"The town is well placed for easy access to London and convenient for Heathrow Airport","cn":"这座城市地理位置优越，到伦敦和希思罗机场都很方便。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(时间)方便的，合适的，合宜的","en":"A convenient time to do something, for example to meet someone, is a time when you are free to do it or would like to do it.","ex":{"en":"She will try to arrange a mutually convenient time and place for an interview","cn":"她会尽力安排一个双方都方便的时间和地点进行面试。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(态度、行为等)方便的，省力的，省事的","en":"If you describe someone's attitudes or actions as convenient, you think they are only adopting those attitudes or performing those actions in order to avoid something difficult or unpleasant.","ex":{"en":"We cannot make this minority a convenient excuse to turn our backs","cn":"我们不能拿少数这几个人作为一种方便的借口而对此置之不理。"}}]},"examples":[{"en":"( disapproving ) He used his wife's birthday as a convenient excuse for not going to the meeting.","cn":"他说要给妻子过生日，利用这个借口，就不去参加会议了。"},{"en":"She conveniently forgot to mention that her husband would be at the party, too (= because it suited her not to say).","cn":"她没有提她丈夫也要参加聚会，她觉得还是不提为好。"}]},"communicative":{"media":{"uk":"media/uk/communicative__gb_1.mp3","us":"media/us/communicative__us_1.mp3"},"oxford":{"phon":"kəˈmjuːnɪkətɪv","pos":"adjective","senses":[{"en":"willing to talk and give information to other people","cn":"乐意沟通的","ex":{"en":"I don't find him very communicative.","cn":"我发觉他不太爱说话。"}},{"en":"connected with the ability to communicate in a language, especially a foreign language","cn":"语言交际能力的（尤指用外语）","ex":{"en":"communicative skills","cn":"语言交际能力"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"健谈的;善于言谈的","en":"Someone who is communicative talks to people, for example about their feelings, and tells people things.","ex":{"en":"She has become a lot more tolerant and communicative.","cn":"她变得宽容多了，也爱说话了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"交际能力的;表达能力的","en":"Communicative means relating to the ability to communicate.","ex":{"en":"...the notion of communicative competence","cn":"交际能力的概念"}}]},"examples":[{"en":"I don't find him very communicative.","cn":"我发觉他不太爱说话。"},{"en":"communicative skills","cn":"语言交际能力"}]},"compromising":{"media":{"uk":"media/uk/compromising__gb_1.mp3","us":"media/us/compromising__us_1.mp3"},"oxford":{"phon":"ˈkɒmprəmaɪzɪŋ","pos":"adjective","senses":[{"en":"if something is compromising, it shows or tells people something that you want to keep secret, because it is wrong or embarrassing","cn":"有失体面的；不宜泄露的","ex":{"en":"compromising photos","cn":"不宜公开的照片"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"使人难堪的;有失体面的","en":"If you describe information or a situation as compromising, you mean that it reveals an embarrassing or guilty secret about someone.","ex":{"en":"How had this compromising picture come into the possession of the press?","cn":"这张令人难堪的照片是怎么落到媒体手中的？"}}]},"examples":[{"en":"They were discovered together in a compromising situation.","cn":"他们被人发现在一起，场面有伤风化。"},{"en":"compromising photos","cn":"不宜公开的照片"}],"base":"compromise"},"comprehensible":{"oxford":{"phon":"ˌkɒmprɪˈhensəbl","pos":"adjective","senses":[{"en":"that can be understood by somebody","cn":"可理解的；能懂的","ex":{"en":"easily/readily comprehensible to the average reader","cn":"一般读者容易懂的"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"能懂的;可以理解的","en":"Something that is comprehensible can be understood.","ex":{"en":"He spoke abruptly, in barely comprehensible Arabic.","cn":"他突然开口了，说的却是几乎听不懂的阿拉伯语。"}}]},"media":{"uk":"media/uk/comprehensible__gb_1.mp3","us":"media/us/comprehensible__us_1.mp3"},"examples":[{"en":"easily/readily comprehensible to the average reader","cn":"一般读者容易懂的"},{"en":"Her speech was slurred and barely comprehensible.","cn":"她说话含混不清﹐几乎无法听懂。"}]},"companion":{"media":{"uk":"media/uk/companion__gb_1.mp3","us":"media/us/companion__us_1.mp3"},"oxford":{"phon":"kəmˈpænjən","pos":"noun","senses":[{"en":"a person or an animal that travels with you or spends a lot of time with you","cn":"旅伴；伴侣","lab":"figurative","ex":{"en":"travelling companions","cn":"旅伴"}},{"en":"a person who shares your experiences, especially when these are particularly pleasant or unpleasant","cn":"同甘共苦的人；伙伴","ex":{"en":"She was a charming dinner companion.","cn":"与她同桌进餐使人感到十分高兴。"}},{"en":"a person, usually a woman, employed to live with and help somebody, especially somebody old or ill","cn":"陪护（通常受雇照料老人或病人）","ex":{"en":"She lived in the house as a companion to our grandmother.","cn":"她住在这栋房子里给我们的祖母作伴。"}},{"en":"one of a pair of things that go together or can be used together","cn":"成对的物品之一；一副物品中的一个","ex":{"en":"A companion volume is soon to be published.","cn":"这卷书的姊妹篇即将问世。"}},{"en":"used in book titles to describe a book giving useful facts and information on a particular subject","cn":"（用于书名）指南，手册","ex":{"en":"A Companion to French Literature","cn":"《法国文学指南》"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同伴;伴侣;同行者","en":"A companion is someone who you spend time with or who you are travelling with.","ex":{"en":"Fred had been her constant companion for the last six years of her life","cn":"在她生命的最后6年，弗莱德一直是她忠实的伴侣。"}}]},"examples":[{"en":"She was a charming dinner companion.","cn":"与她同桌进餐使人感到十分高兴。"},{"en":"His younger brother is not much of a companion for him.","cn":"他的弟弟和他志趣不太相投。"}]},"colonial":{"media":{"uk":"media/uk/colonial__gb_1.mp3","us":"media/us/colonial__us_1.mp3"},"oxford":{"phon":"kəˈləʊniəl","pos":"adjective","senses":[{"en":"connected with or belonging to a country that controls another country","cn":"殖民的；殖民国家的","ex":{"en":"a colonial power","cn":"殖民强国"}},{"en":"typical of or connected with the US at the time when it was still a British colony","cn":"（美国）具有英属殖民地时期特色的，英属殖民地时期的","ex":{"en":"life in colonial times","cn":"英属殖民地时期的美国生活"}},{"en":"a person who lives in a colony and who comes from the country that controls it","cn":"生活在殖民地的宗主国居民","ex":{"en":"British colonials in India","cn":"生活在印度这块殖民地上的英国人"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"殖民地的;殖民主义的","en":"Colonial means relating to countries that are colonies, or to colonialism.","ex":{"en":"...the 31st anniversary of Jamaica's independence from British colonial rule.","cn":"牙买加脱离英国殖民统治独立31周年纪念"}},{"pos":"N-COUNT 可数名词","cn":"生活在殖民地的宗主国居民","en":"People who have lived for a long time in a colony but who belong to the colonizing country are sometimes referred to as colonials .","ex":{"en":"...a group of ex-colonials.","cn":"一群前殖民地居民"}},{"pos":"ADJ 形容词","cn":"(建筑或家具)具有英属殖民地时期特色的，美洲殖民地时期的","en":"A Colonial building or piece of furniture was built or made in a style that was popular in America in the 17th and 18th centuries.","ex":{"en":"...the white colonial houses on the north side of the campus","cn":"校园北边几幢殖民地时期风格的白房子"}}]},"examples":[{"en":"Tunisia achieved independence from French colonial rule in 1956.","cn":"突尼斯于 1956 年从法国的殖民统治下获得独立。"},{"en":"British colonials in India","cn":"生活在印度这块殖民地上的英国人"}]},"condition":{"media":{"uk":"media/uk/xcondition__gb_1.mp3","us":"media/us/xcondition__us_1.mp3"},"oxford":{"phon":"kənˈdɪʃn","pos":"noun","senses":[{"en":"the state that something is in","cn":"状态；状况","g":"[uncountable, singular]","sc":"state of something","ex":{"en":"to be in pristine/excellent/perfect condition","cn":"处于原始的／极佳的／完美的状态"}},{"en":"the state of somebody’s health or how fit they are","cn":"健康状况","g":"[uncountable, singular]","lab":"informal","sc":"medical","ex":{"en":"He is overweight and out of condition (= not physically fit).","cn":"他体重超重，健康状况不佳。"}},{"en":"an illness or a medical problem that you have for a long time because it is not possible to cure it","cn":"（因不可能治愈而长期患有的）疾病","g":"[countable]","sc":"medical","ex":{"en":"Does your child have any kind of medical condition that we should know about?","cn":"你的孩子患有我们应该知晓的长期疾病吗？"}},{"en":"the circumstances or situation in which people live, work or do things","cn":"（居住、工作或做事情的）环境，境况，条件","g":"[plural]","sc":"circumstances","ex":{"en":"working/living conditions","cn":"工作／生活条件"}},{"en":"the physical situation that affects how something happens","cn":"（影响某事发生的）物质环境，状态，条件","g":"[plural]","sc":"circumstances","ex":{"en":"The plants grow best in cool, damp conditions.","cn":"这种植物最适合在阴凉、潮湿的环境下生长。"}},{"en":"a rule or decision that you must agree to, sometimes forming part of a contract or an official agreement","cn":"条件；条款；要件","g":"[countable]","lab":"especially North American English","sc":"rule","ex":{"en":"The offer is subject to certain conditions.","cn":"此项优惠受制于某些条件。"}},{"en":"a situation that must exist in order for something else to happen","cn":"（先决）条件；前提","g":"[countable]","sc":"necessary situation","ex":{"en":"Stable political leadership is a necessary condition for economic growth.","cn":"稳定的政治领导是经济增长的必要条件。"}},{"en":"the state of a particular group of people because of their situation in life, their problems, etc.","cn":"（某群体的）生存状态，处境","g":"[singular]","lab":"formal","sc":"state of group","ex":{"en":"He spoke angrily about the condition of the urban poor.","cn":"他愤怒地谈论城市贫民的处境。"}},{"en":"to train somebody/something to behave in a particular way or to become used to a particular situation","cn":"训练；使习惯于；使适应","g":"[usually passive]","ex":{"en":"Patients can become conditioned to particular forms of treatment.","cn":"病人会习惯某些治疗方式。"},"pos":"verb"},{"en":"to have an important effect on somebody/something; to influence the way that something happens","cn":"对…具有重要影响；影响（某事发生的方式）","g":"[usually passive]","ex":{"en":"Gender roles are often conditioned by cultural factors.","cn":"文化因素常常对性别的角色有着重要的影响。"},"pos":"verb"},{"en":"to keep something such as your hair or skin healthy","cn":"保持（头发或皮肤等的）健康；养护","ex":{"en":"a shampoo that cleans and conditions hair","cn":"具养护功能的洗发剂"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"状况;状态","en":"If you talk about the condition of a person or thing, you are talking about the state that they are in, especially how good or bad their physical state is.","ex":{"en":"He remains in a critical condition in a California hospital","cn":"他在加州的一家医院里，病情仍然十分危急。"}},{"pos":"N-PLURAL 复数名词","cn":"(某事完成或发生的)环境，条件","en":"The conditions under which something is done or happens are all the factors or circumstances which directly affect it.","ex":{"en":"This change has been timed under laboratory conditions","cn":"在实验室条件下测得了这一变化所需的时间。"}},{"pos":"N-PLURAL 复数名词","cn":"(生活或工作的)条件，环境","en":"The conditions in which people live or work are the factors which affect their comfort, safety, or health.","ex":{"en":"People are living in appalling conditions","cn":"人们的居住条件极其恶劣。"}},{"pos":"N-SING 单数名词","cn":"(某一群人的)生活状况，境况;(尤指)艰难处境","en":"The condition of a group of people is their situation in life, especially with regard to the difficulties they have.","ex":{"en":"The condition of the people could be elevated by a programme of social reform","cn":"人们的生活状况可以通过社会改革方案得到改善。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指写入合同或法律的)条件，条款","en":"A condition is something which must happen or be done in order for something else to be possible, especially when this is written into a contract or law.","ex":{"en":"...economic targets set as a condition for loan payments.","cn":"作为贷款偿还条件所设定的经济目标"}},{"pos":"N-COUNT 可数名词","cn":"疾病;健康问题","en":"If someone has a particular condition, they have an illness or other medical problem.","ex":{"en":"Doctors suspect he may have a heart condition.","cn":"医生怀疑他可能有心脏病。"}},{"pos":"VERB 动词","cn":"(经历或环境)影响，使适应","en":"If someone is conditioned by their experiences or environment, they are influenced by them over a period of time so that they do certain things or think in a particular way.","ex":{"en":"We are all conditioned by early impressions and experiences","cn":"我们都受到早年印象和经历的影响。"}},{"pos":"VERB 动词","cn":"保养，护理(头发或皮肤)","en":"To condition your hair or skin means to put something on it which will keep it in good condition.","ex":{"en":"...a protein which is excellent for conditioning dry and damaged hair.","cn":"对干燥、受损的头发有极佳护理效果的蛋白质"}},{"pos":"PHRASE 短语","cn":"(因病重、烦乱或酒醉而)不能(做某事)","en":"If you say that someone is in no condition to do something, you mean that they are too ill, upset, or drunk to do it.","ex":{"en":"She was clearly in no condition to see anyone.","cn":"很显然，她谁都不能见。"}},{"pos":"PHR-CONJ-SUBORD","cn":"在…条件下;条件是","en":"When you agree to do something on condition that something else happens, you mean that you will only do it if this other thing also happens.","ex":{"en":"He spoke to reporters on condition that he was not identified.","cn":"在不披露身份的条件下，他接受了记者的采访。"}},{"pos":"PHRASE 短语","cn":"(由于缺乏锻炼而)身体状况不佳","en":"If someone is out of condition, they are unhealthy and unfit, because they do not do enough exercise.","ex":{"en":"He was too out of condition to clamber over the top.","cn":"他体质太差，爬不到山顶。"}},{"pos":"","cn":"","en":"in mint condition→see: ;"}]},"examples":[{"en":"They will give us the money on one condition — that we pay it back within six months.","cn":"他们给我们提供资金有一个条件，即我们在六个月以内偿还。"},{"en":"They have agreed to the ceasefire provided their conditions are met.","cn":"他们已经同意停火，只要他们提出的条件得到满足。"}]},"connection":{"media":{"uk":"media/uk/xconnection__gb_1.mp3","us":"media/us/xconnection__us_1.mp3"},"oxford":{"phon":"kəˈnekʃn","pos":"noun","senses":[{"en":"something that connects two facts, ideas, etc.","cn":"（两种事实、想法等的）联系，关联","g":"[countable]","sc":"link","ex":{"en":"Scientists have established a connection between cholesterol levels and heart disease.","cn":"科学家已证实胆固醇含量与心脏病之间有关联。"}},{"en":"the act of connecting or the state of being connected","cn":"联结；接通；连接","g":"[uncountable, countable]","sc":"being connected","ex":{"en":"a broadband/wireless/Wi-Fi/network connection","cn":"宽带／无线／Wi-Fi／网络连接"}},{"en":"a point, especially in an electrical system, where two parts connect","cn":"连接点；（尤指电力系统的）接头","g":"[countable]","sc":"in electrical system","ex":{"en":"A faulty connection caused the machine to stop.","cn":"线路接错导致机器停止运转。"}},{"en":"a train, bus or plane at a station or an airport that a passenger can take soon after getting off another in order to continue their journey","cn":"转车；转机；联运","g":"[countable]","sc":"train/bus/plane","ex":{"en":"I missed the connection by five minutes.","cn":"我晚了五分钟，没有赶上转机。"}},{"en":"a means of travelling to another place","cn":"旅行交通工具","g":"[countable, usually plural]","sc":"train/bus/plane","ex":{"en":"There are good bus and train connections between the resort and major cities.","cn":"在度假胜地与主要城市之间有着便利的公共汽车和火车运输。"}},{"en":"a person or an organization that you know and that can help or advise you in your social or professional life","cn":"有社交或业务关系的人（或机构）","g":"[countable, usually plural]","sc":"person/organization","ex":{"en":"One of my business connections gave them my name.","cn":"我生意上的一个关系户向他们提供了我的名字。"}},{"en":"people who are your relatives, but not members of your close family","cn":"亲戚；旁系亲属","g":"[plural]","sc":"distant relatives","ex":{"en":"She is British but also has German connections.","cn":"她是英国人，但也有德国亲戚。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"关系;联系","en":"A connection is a relationship between two things, people, or groups.","ex":{"en":"There was no evidence of a connection between BSE and the brain diseases recently confirmed in cats","cn":"没有证据表明疯牛病与最近确诊的猫类脑病有关联。"}},{"pos":"N-COUNT 可数名词","cn":"(电线或管道的)连接部分，接头","en":"A connection is a joint where two wires or pipes are joined together.","ex":{"en":"Check all radiators for small leaks, especially round pipework connections.","cn":"检查所有的暖气片，看有没有小裂缝，尤其是管道连接处附近。"}},{"pos":"N-COUNT 可数名词","cn":"(公路、铁路或空中的)交通连接，交通线","en":"If a place has good road, rail, or air connections, many places can be directly reached from there by car, train, or plane.","ex":{"en":"Fukuoka has excellent air and rail connections to the rest of the country.","cn":"福冈与国内其他城市之间有非常便捷的空运和铁路运输系统。"}},{"pos":"N-COUNT 可数名词","cn":"联运;转车;转机","en":"If you get a connection at a station or airport, you catch a train, bus, or plane, after getting off another train, bus, or plane, in order to continue your journey.","ex":{"en":"My flight was late and I missed the connection.","cn":"航班晚点，我没赶上转机。"}},{"pos":"N-PLURAL 复数名词","cn":"关系;人脉","en":"Your connections are the people who you know or are related to, especially when they are in a position to help you.","ex":{"en":"She used her connections to full advantage.","cn":"她充分利用了自己的人脉。"}},{"pos":"PREP-PHRASE 短语介词","cn":"关于;与…有关","en":"If you write or talk to someone in connection with something, you write or talk to them about that thing.","ex":{"en":"I am writing in connection with Michael Shower's letter","cn":"关于迈克尔·肖尔的来信，现复信如下。"}},{"pos":"PHRASE 短语","cn":"关于这/那一点;在这/那方面","en":"You say in this connection or in that connection to indicate that what you are talking about is related to what you have just mentioned.","ex":{"en":"It is the 100th anniversary of his death. We here are having very great celebrations in this connection.","cn":"今天是他逝世100周年纪念日，我们为此在这里举行盛大的纪念活动。"}}]},"examples":[{"en":"There are good bus and train connections between the resort and major cities.","cn":"在度假胜地与主要城市之间有着便利的公车和火车运输。"},{"en":"Scientists have established a connection between cholesterol levels and heart disease.","cn":"科学家已证实胆固醇含量与心脏病之间有关联。"}]},"core":{"media":{"uk":"media/uk/core__gb_1.mp3","us":"media/us/core__us_1.mp3"},"oxford":{"phon":"kɔː(r)","pos":"noun","senses":[{"en":"the most important or central part of something","cn":"最重要的部分；核心；要点；精髓","ex":{"en":"This report goes to the core of the argument.","cn":"这篇报道直指争论的核心。"}},{"en":"the central part of an object","cn":"（物体的）中心部分","ex":{"en":"the earth’s core","cn":"地核"}},{"en":"the hard central part of a fruit such as an apple, that contains the seeds","cn":"（水果的）果心，核儿","ex":{"en":"an apple core","cn":"苹果核"}},{"en":"the muscles of the lower back and stomach area which help you to maintain good balance, etc.","cn":"核心肌群（下背和腹部肌肉，起平衡身体作用）","ex":{"en":"Your posture will improve as your core becomes stronger.","cn":"当你的核心变得更强时，你的姿势将会改善。"}},{"en":"a small group of people who take part in a particular activity","cn":"（参加某项活动的）一小群人","ex":{"en":"He gathered a small core of advisers around him.","cn":"他的周围聚集了一帮谋士。"}},{"en":"most important; main or essential","cn":"最重要的；主要的；基本的","ex":{"en":"core subjects (= subjects that all the students have to study) such as English and mathematics","cn":"诸如英语和数学等核心科目"},"pos":"adjective"},{"en":"used to describe the most important or central beliefs, etc. of a person or group","cn":"（信念、价值、原则等）最重要的，核心的","ex":{"en":"core beliefs/principles","cn":"核心信念／原则"},"pos":"adjective"},{"en":"used to describe the most important members of a group","cn":"核心成员的；骨干的","ex":{"en":"The team is built around a core group of players.","cn":"这个队是以几名骨干队员为核心构建的。"},"pos":"adjective"},{"en":"to take out the core of a fruit","cn":"去掉（水果）的果心；去（水果）的核儿","ex":{"en":"You need four cooking apples, cored and sliced.","cn":"您需要四个烹饪苹果，去核并切片。"},"pos":"verb"},{"en":"Congress of Racial Equality","cn":"核心：种族平等大会","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"果心;核儿","en":"The core of a fruit is the central part of it. It contains seeds or pips.","ex":{"en":"Someone threw an apple core","cn":"有人扔了一个苹果核。"}},{"pos":"VERB 动词","cn":"去掉…的果心;给（水果）去核","en":"If you core a fruit, you remove its core.","ex":{"en":"...machines for peeling and coring apples.","cn":"苹果削皮去核机"}},{"pos":"N-COUNT 可数名词","cn":"(物体、建筑物或城市的)中心部分","en":"The core of an object, building, or city is the central part of it.","ex":{"en":"...the earth's core","cn":"地核"}},{"pos":"N-SING 单数名词","cn":"(问题的)核心，要点","en":"The core of something such as a problem or an issue is the part of it that has to be understood or accepted before the whole thing can be understood or dealt with.","ex":{"en":"...the ability to get straight to the core of a problem","cn":"直击问题要害的能力"}},{"pos":"N-SING 单数名词","cn":"精髓;骨干","en":"A core team or a core group is a group of people who do the main part of a job or piece of work. Other people may also help, but only for limited periods of time.","ex":{"en":"We already have our core team in place","cn":"我们的骨干团队已经就位了。"}},{"pos":"N-SING 单数名词","cn":"基础（课);核心（科目）","en":"In a school or college, core subjects are a group of subjects that have to be studied.","ex":{"en":"The core subjects are English, mathematics and science","cn":"基础课是英文、数学和科学。"}},{"pos":"N-SING 单数名词","cn":"主要业务;主要活动","en":"The core businesses or the core activities of a company or organization are their most important ones.","ex":{"en":"The core activities of local authorities were reorganised","cn":"地方政府的主要事务进行了调整。"}},{"pos":"PHRASE 短语","cn":"彻底的;十足的","en":"You can use to the core to describe someone who is a very strong supporter of someone or something and will never change their views. For example, you can say that someone is Republican to the core .","ex":{"en":"The villagers are royalist to the core.","cn":"那些村民是十足的保皇主义者。"}},{"pos":"PHRASE 短语","cn":"十分地;极为","en":"If someone is shaken to the core or shocked to the core, they are extremely shaken or shocked.","ex":{"en":"Leonard was shaken to the core; he'd never seen or read anything like it.","cn":"伦纳德极为震惊;他从未看过或读过这样的东西。"}}]},"examples":[{"en":"The team is built around a core group of players.","cn":"这个队是以几名骨干队员为核心构建的。"},{"en":"The party is losing touch with its core values.","cn":"这个党正在逐渐偏离其核心价值观。"}]},"cot":{"media":{"img":["media/ldoce/img/cot.jpg","media/pic/beds_comp.jpg"],"uk":"media/uk/cot__gb_1.mp3","us":"media/us/cot__us_1.mp3"},"oxford":{"phon":"kɒt","pos":"noun","senses":[{"en":"a small bed with high sides for a baby or young child","cn":"（有围栏的）婴儿床，幼儿床","lab":"British English","ex":{"en":"a travel cot (= one that can be moved around easily, used when travelling)","cn":"旅行幼儿床"}},{"en":"a light narrow bed that you can fold up and carry easily","cn":"折叠床；行军床","lab":"North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"婴儿床","en":"A cot is a bed for a baby, with bars or panels round it so that the baby cannot fall out."},{"pos":"N-COUNT 可数名词","cn":"(可折叠的)行军床，帆布床","en":"A cot is a narrow bed, usually made of canvas fitted over a frame which can be folded up."}]},"examples":[{"en":"a travel cot (= one that can be moved around easily, used when travelling)","cn":"旅行幼儿床"}]},"contracts":{"lemma":"contract","media":{"uk":"media/uk/xcontract__gb_1.mp3","us":"media/us/xcontract__us_1.mp3"}},"convincing":{"media":{"uk":"media/uk/xconvincing__gb_1.mp3","us":"media/us/xconvincing__us_1.mp3"},"oxford":{"phon":"kənˈvɪnsɪŋ","pos":"adjective","senses":[{"en":"that makes somebody believe that something is true","cn":"令人信服的；有说服力的","ex":{"en":"a convincing argument/explanation/case","cn":"有说服力的论点／解释／事例"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人信服的;使人心悦诚服的;有说服力的","en":"If you describe someone or something as convincing, you mean that they make you believe that a particular thing is true, correct, or genuine.","ex":{"en":"Scientists say there is no convincing evidence that power lines have anything to do with cancer","cn":"科学家们说，并没有确凿的证据表明输电线和癌症之间有什么联系。"}}]},"examples":[{"en":"She sounded very convincing to me (= I believed what she said).","cn":"我觉得她的话很有说服力。"},{"en":"Her case was convincingly argued.","cn":"她的辩词很有说服力。"}],"base":"convince"},"consensual":{"media":{"uk":"media/uk/xconsensual__gb_1.mp3","us":"media/us/xconsensual__us_1.mp3"},"oxford":{"phon":"kənˈsenʃuəl","pos":"adjective","senses":[{"en":"that people in general agree with","cn":"一致同意的","ex":{"en":"a consensual approach","cn":"一致赞成的方法"}},{"en":"which the people taking part have agreed to","cn":"（参与者）同意的，赞同的","ex":{"en":"consensual sex","cn":"两厢情愿的性行为"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"一致同意的;全体赞成的","en":"A consensual approach, view, or decision is one that is based on general agreement among all the members of a group.","ex":{"en":"Consultation is traditional in the consensual Belgian system of labour relations.","cn":"协商是建立在意见一致基础上的比利时劳资关系体系的传统做法。"}},{"pos":"ADJ 形容词","cn":"(性行为)双方自愿的，两厢情愿的","en":"If sexual activity is consensual, both partners willingly take part in it.","ex":{"en":"Consensual sexual contact between two males can be a criminal activity.","cn":"两名男性之间发生的双方自愿的性接触可能会构成犯罪。"}}]},"examples":[{"en":"consensual sex","cn":"两厢情愿的性行为"},{"en":"a consensual approach","cn":"一致赞成的方法"}]},"coquette":{"oxford":{"phon":"kɒˈket","pos":"noun","senses":[{"en":"a person, usually a woman, who behaves in a way that is intended to be sexually attractive but is not very serious","cn":"卖弄风情的女人"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"卖弄风情的女人","en":"A coquette is a woman who behaves in a coquettish way."}]},"media":{"uk":"media/uk/coquette__gb_1.mp3","us":"media/us/coquette__us_1.mp3"},"examples":[{"en":"a coquettish smile","cn":"卖弄风骚的微笑"}]},"continually":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"continuing for a long time without stopping, or happening many times in a way that is annoying or causes problems","cn":""},{"en":"continuing without stopping","cn":""}]},"examples":[{"en":"the Japanese business philosophy of continual improvement","cn":"","src":"ld"},{"en":"She has endured house arrest and continual harassment by the police.","cn":"","src":"ld"}],"media":{"uk":"media/uk/xcontinually__gb_1.mp3","us":"media/us/xcontinually__us_1.mp3"},"oxford":{"phon":"kənˈtɪnjuəli","pos":"adverb","senses":[{"en":"in a way that is repeated many times so that it is annoying","cn":"（令人厌烦地）反复地，频繁地","ex":{"en":"They argue continually about money.","cn":"他们没完没了地为钱争吵。"}},{"en":"in a way that continues without a break","cn":"不断地；持续地；连续地","ex":{"en":"the need to adapt to new and continually changing circumstances","cn":"适应不断变化的新形势的需要"}}]}},"confident":{"media":{"uk":"media/uk/xconfident__gb_1.mp3","us":"media/us/xconfident__us_1.mp3"},"oxford":{"phon":"ˈkɒnfɪdənt","pos":"adjective","senses":[{"en":"feeling sure about your own ability to do things and be successful","cn":"自信的；有自信心的","ex":{"en":"She was in a relaxed, confident mood.","cn":"她的心态从容而自信。"}},{"en":"feeling certain that something will happen in the way that you want or expect","cn":"肯定的；确信的；有把握的","ex":{"en":"The Democrats were confident of victory.","cn":"民主党对胜利充满信心。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚信的;有信心的","en":"If you are confident about something, you are certain that it will happen in the way you want it to.","ex":{"en":"I am confident that everything will come out right in time","cn":"我坚信一切终究都会好起来。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自信的;充满信心的","en":"If a person or their manner is confident, they feel sure about their own abilities, qualities, or ideas.","ex":{"en":"In time he became more confident and relaxed","cn":"过了一段时间，他变得更加自信、更为放松。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"肯定的;有把握的","en":"If you are confident that something is true, you are sure that it is true. A confident statement is one that the speaker is sure is true.","ex":{"en":"She is confident that everybody is on her side","cn":"她确信所有人都站在她这边。"}}]},"examples":[{"en":"The teacher wants the children to feel confident about asking questions when they don't understand.","cn":"教师要孩子们遇到不懂的问题就大胆提问。"},{"en":"I'm confident that you will get the job.","cn":"我肯定你能得到那份工作。"}]},"conduct":{"media":{"uk":"media/uk/xconduct__gb_1.mp3","us":"media/us/xconduct__us_1.mp3"},"oxford":{"phon":"kənˈdʌkt","pos":"verb","senses":[{"en":"to organize and/or do a particular activity","cn":"组织；安排；实施；执行","g":"[transitive]","lab":"formal","ex":{"en":"to conduct an experiment/inquiry/investigation/interview","cn":"进行实验／询问／调查／面谈"}},{"en":"to direct a group of people who are singing or playing music","cn":"指挥（歌唱或音乐演奏）","g":"[transitive, intransitive]","ex":{"en":"a concert by the London Philharmonic Orchestra, conducted by Marin Alsop","cn":"由马林·阿尔索普指挥、伦敦爱乐乐团演出的音乐会"}},{"en":"to lead or guide somebody through or around a place","cn":"带领；引导；为（某人）导游","g":"[transitive]","lab":"formal","ex":{"en":"a conducted tour of Athens (= one with a guide, giving information about it)","cn":"有导游陪同的雅典之行"}},{"en":"to behave in a particular way","cn":"举止；表现","g":"[transitive]","lab":"formal","ex":{"en":"He conducted himself far better than expected.","cn":"他表现得比预料的要好得多。"}},{"en":"to allow heat or electricity to pass along or through it","cn":"传导（热或电等能量）","g":"[transitive]","lab":"specialist","ex":{"en":"Copper conducts electricity well.","cn":"铜的导电性能好。"}},{"en":"a person’s behaviour in a particular place or in a particular situation","cn":"（人在某地或某种情况下的）行为，举止","ex":{"en":"The sport has a strict code of conduct.","cn":"这种体育运动有严格的行为规范。"},"pos":"noun"},{"en":"the way in which a business or an activity is organized and managed","cn":"经营方式；管理方法；实施办法","ex":{"en":"There was growing criticism of the government's conduct of the war.","cn":"政府的作战方式受到越来越多的指责。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"进行;组织;实施","en":"When you conduct an activity or task, you organize it and carry it out.","ex":{"en":"I decided to conduct an experiment","cn":"我决定进行一次实验。"}},{"pos":"N-SING 单数名词","cn":"(任务或活动的)组织方式，实施办法","en":"The conduct of a task or activity is the way in which it is organized and carried out.","ex":{"en":"Also up for discussion will be the conduct of free and fair elections","cn":"同样提出来进行讨论的还有如何进行自由公正的选举。"}},{"pos":"VERB 动词","cn":"表现;举止","en":"If you conduct yourself in a particular way, you behave in that way.","ex":{"en":"The way he conducts himself reflects on the party and will increase criticisms against him","cn":"他个人的行事方式给该党招来非议，也会招致更多对他个人的批评。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"行为;举止","en":"Someone's conduct is the way they behave in particular situations.","ex":{"en":"For Europeans, the law is a statement of basic principles of civilised conduct","cn":"对于欧洲人来说，法律是对基本文明行为准则的表述。"}},{"pos":"VERB 动词","cn":"指挥(管弦乐队或合唱团)","en":"When someone conducts an orchestra or choir, they stand in front of it and direct its performance.","ex":{"en":"Dennis had recently begun a successful career conducting opera in Europe","cn":"丹尼斯最近开始在欧洲担任歌剧指挥，事业发展得很成功。"}},{"pos":"VERB 动词","cn":"传导(热或电)","en":"If something conducts heat or electricity, it allows heat or electricity to pass through it or along it.","ex":{"en":"Water conducts heat faster than air.","cn":"水的导热速度比空气快。"}},{"pos":"VERB 动词","cn":"陪伴;引导;带领","en":"If you conduct someone to a place, you go there with them.","ex":{"en":"He asked if he might conduct us to the ball which was to bring the proceedings to an end.","cn":"他问是否可以带我们去舞会现场，整个仪式将在那儿结束。"}}]},"examples":[{"en":"a concert by the Philharmonic Orchestra, conducted by Sir Colin Davis","cn":"由科林 · 戴维斯爵士指挥、爱乐交响乐团演出的音乐会"},{"en":"There was growing criticism of the government's conduct of the war.","cn":"政府对战争的指挥方式受到越来越多的指责。"}]},"combination":{"media":{"uk":"media/uk/combination__gb_1.mp3","us":"media/us/combination__us_1.mp3"},"oxford":{"phon":"ˌkɒmbɪˈneɪʃn","pos":"noun","senses":[{"en":"two or more things joined or mixed together to form a single unit","cn":"结合体；联合体；混合体","g":"[countable]","ex":{"en":"The tragedy was due to a combination of factors.","cn":"几种因素叠加，酿成了悲剧。"}},{"en":"the act of joining or mixing together two or more things to form a single unit","cn":"结合；联合；混合","g":"[uncountable]","ex":{"en":"The firm is working on a new product in combination with several overseas partners.","cn":"这家公司与几家海外合伙人在联合开发新产品。"}},{"en":"a series of numbers or letters used to open a combination lock","cn":"（用于开密码锁的）数码组合，字码组合","g":"[countable]","ex":{"en":"I can't remember the combination.","cn":"我不记得密码锁的密码了。"}},{"en":"a piece of underwear covering the body and legs, worn in the past","cn":"（旧时的）连裤内衣","g":"[plural]","lab":"British English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"结合;联合;混合","en":"A combination of things is a mixture of them.","ex":{"en":"...a fantastic combination of colours.","cn":"多种颜色的绝妙混合"}}]},"examples":[{"en":"The firm is working on a new product in combination with several overseas partners.","cn":"这家公司与几家海外合伙人在联合开发新产品。"},{"en":"His treatment was a combination of surgery, radiation and drugs.","cn":"对他的治疗是把手术、放射和药物结合起来。"}]},"conversation":{"media":{"uk":"media/uk/xconversation__gb_1.mp3","us":"media/us/xconversation__us_1.mp3"},"oxford":{"phon":"ˌkɒnvəˈseɪʃn","pos":"noun","senses":[{"en":"an informal talk involving a small group of people or only two; the activity of talking in this way","cn":"（非正式）交谈，谈话","lab":"British English","ex":{"en":"a phone conversation","cn":"电话交谈"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"交谈;谈话;会话","en":"If you have a conversation with someone, you talk with them, usually in an informal situation.","ex":{"en":"He's a talkative guy, and I struck up a conversation with him","cn":"他是一个健谈的人，于是我开始和他攀谈起来。"}},{"pos":"PHRASE 短语","cn":"正在谈话;正在交谈","en":"If you say that people are in conversation, you mean that they are talking together.","ex":{"en":"When I arrived I found her in conversation with Mrs Williams.","cn":"我到的时候，发现她正在和威廉斯夫人谈话。"}},{"pos":"PHRASE 短语","cn":"搭话;找话说;说应酬话","en":"If you make conversation, you talk to someone in order to be polite and not because you really want to.","ex":{"en":"He had been trying to make conversation.","cn":"他一直在尽量找话说。"}}]},"examples":[{"en":"The main topic of conversation was the likely outcome of the election.","cn":"谈话的主题是选举可能产生的结果。"},{"en":"Don was deep in conversation with the girl on his right.","cn":"唐与他右边的女孩在专心交谈。"}]},"comparative":{"oxford":{"phon":"kəmˈpærətɪv","pos":"adjective","senses":[{"en":"measured or judged by how similar or different it is to something else","cn":"比较而言的；相对的","ex":{"en":"Then he was living in comparative comfort (= compared with others or with his own life at a previous time).","cn":"他那时生活比较舒适。"}},{"en":"connected with studying things to find out how similar or different they are","cn":"比较的；相比的","ex":{"en":"a comparative study of the educational systems of two countries","cn":"两国教育制度的比较研究"}},{"en":"relating to adjectives or adverbs that express more in amount, degree or quality, for example better, worse, slower and more difficult","cn":"（形容词或副词）比较级的（如 better、worse、slower 和 more difficult）","lab":"grammar"},{"en":"the form of an adjective or adverb that expresses more in amount, degree or quality","cn":"（形容词或副词的）比较级形式","ex":{"en":"‘Better’ is the comparative of ‘good’ and ‘more difficult’ is the comparative of ‘difficult’.","cn":"better 是 good 的比较级；more difficult 是 difficult 的比较级。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(状态)相对的，比较而言的","en":"You use comparative to show that you are judging something against a previous or different situation. For example, comparative calm is a situation which is calmer than before or calmer than the situation in other places.","ex":{"en":"...those who manage to reach the comparative safety of Fendel","cn":"达到“芬司匹利”药品相对安全标准的那些药"}},{"pos":"ADJ 形容词","cn":"(研究)比较的","en":"A comparative study is a study that involves the comparison of two or more things of the same kind.","ex":{"en":"...a comparative study of the dietary practices of people from various regions of India.","cn":"对印度各地区的人饮食习惯的比较研究"}},{"pos":"ADJ 形容词","cn":"(形容词或副词)比较级的","en":"In grammar, the comparative form of an adjective or adverb shows that something has more of a quality than something else has. For example, 'bigger' is the comparative form of 'big', and 'more quickly' is the comparative form of 'quickly'.","ex":{"en":"The comparative of 'pretty' is 'prettier'.","cn":"pretty的比较级形式是prettier。"}}]},"media":{"uk":"media/uk/comparative__gb_1.mp3","us":"media/us/comparative__us_1.mp3"},"examples":[{"en":"‘Better’ is the comparative of ‘good’ and ‘more difficult’ is the comparative of ‘difficult’. * better","cn":"是 good 的比较级； more difficult 是 difficult 的比较级。"},{"en":"The company is a comparative newcomer to the software market (= other companies have been in business much longer).","cn":"就软件市场来说，这家公司相对而言就是新手了。"}]},"comprehend":{"oxford":{"phon":"ˌkɒmprɪˈhend","pos":"verb","senses":[{"en":"to understand something fully","cn":"理解；领悟；懂","ex":{"en":"He stood staring at the dead body, unable to comprehend.","cn":"他站在那里，盯着那具尸体，弄不明白是怎么回事。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"理解;领悟","en":"If you cannot comprehend something, you cannot understand it.","ex":{"en":"I just cannot comprehend your attitude","cn":"我就是无法理解你的态度。"}}]},"media":{"uk":"media/uk/comprehend__gb_1.mp3","us":"media/us/comprehend__us_1.mp3"},"examples":[{"en":"He stood staring at the dead body, unable to comprehend.","cn":"他站在那里，盯着那具尸体，弄不明白是怎么回事。"},{"en":"She could not comprehend how someone would risk people's lives in that way.","cn":"她不明白怎么会有人竟拿人民的生命那样去冒险。"}]},"corned":{"lemma":"corn","media":{"img":["media/pic/cereals_comp.jpg","media/thumb/maize.jpg"],"uk":"media/uk/corn__gb_1.mp3","us":"media/us/corn__us_1.mp3"}},"concepts":{"lemma":"concept","media":{"uk":"media/uk/xconcept__gb_1.mp3","us":"media/us/xconcept__us_1.mp3"}},"countless":{"oxford":{"phon":"ˈkaʊntləs","pos":"adjective","senses":[{"en":"very many; too many to be counted or mentioned","cn":"无数的；数不胜数的；数不尽的","ex":{"en":"I've warned her countless times.","cn":"我警告过她无数次了。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无数的;数不尽的","en":"Countless means very many.","ex":{"en":"She brought joy to countless people through her music","cn":"她用音乐给无数的人带来欢乐。"}}]},"media":{"uk":"media/uk/countless__gb_1.mp3","us":"media/us/countless__us_1.mp3"},"examples":[{"en":"The new treatment could save Emma's life and the lives of countless others.","cn":"新的疗法可拯救埃玛的生命以及无数其他人的生命。"},{"en":"I've warned her countless times.","cn":"我警告过她无数次了。"}]},"contain":{"media":{"uk":"media/uk/xcontain__gb_1.mp3","us":"media/us/xcontain__us_1.mp3"},"oxford":{"phon":"kənˈteɪn","pos":"verb","senses":[{"en":"if something contains something else, it has that thing inside it or as part of it","cn":"包含；含有；容纳","ex":{"en":"This drink doesn't contain any alcohol.","cn":"这种饮料不含任何酒精。"}},{"en":"to keep your feelings under control","cn":"控制，克制，抑制（感情）","ex":{"en":"She was unable to contain her excitement.","cn":"她无法抑制内心的激动。"}},{"en":"to prevent something harmful from spreading or getting worse","cn":"防止…蔓延（或恶化）","ex":{"en":"to contain an epidemic","cn":"防止流行病的蔓延"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"装有;容纳","en":"If something such as a box, bag, room, or place contains things, those things are inside it.","ex":{"en":"The bag contained a Christmas card","cn":"这个包里装着一张圣诞卡。"}},{"pos":"VERB 动词","cn":"包含;含有","en":"If a substance contains something, that thing is a part of it.","ex":{"en":"Greek yogurt contains much less fat than double cream","cn":"希腊酸奶比高脂浓奶油所含脂肪要少得多。"}},{"pos":"VERB 动词","cn":"(著作、讲话或电影中)包括，包含","en":"If writing, speech, or film contains particular information, ideas, or images, it includes them.","ex":{"en":"This sheet contained a list of problems a patient might like to raise with the doctor","cn":"这张单子列出了病人可能会向医生提出的一系列问题。"}},{"pos":"VERB 动词","cn":"(团体或组织中)有，包括","en":"If a group or organization contains a certain number of people, those are the people that are in it.","ex":{"en":"The committee contains 11 Democrats and nine Republicans.","cn":"这个委员会包括11名民主党人和9名共和党人。"}},{"pos":"VERB 动词","cn":"控制;遏制;防止…蔓延","en":"If you contain something, you control it and prevent it from spreading or increasing.","ex":{"en":"More than a hundred firemen are still trying to contain the fire at the plant","cn":"上百名消防队员仍在试图控制工厂的火势。"}},{"pos":"VERB 动词","cn":"控制，抑制(感情)","en":"If you cannot contain a feeling such as excitement or anger, or if you cannot contain yourself, you cannot prevent yourself from showing your feelings.","ex":{"en":"But he was bursting with curiosity, and one day he just couldn't contain himself. 'What are you going to do?' he asked","cn":"但他满心好奇，一天，他真的忍不住了。“你打算做什么？”他问道。"}}]},"examples":[{"en":"I was so furious I just couldn't contain myself (= I had to express my feelings).","cn":"我气愤极了，简直无法克制自己。"},{"en":"Her statement contained one or two inaccuracies.","cn":"她的陈述有一两处不准确。"}]},"cork":{"media":{"uk":"media/uk/cork__gb_1.mp3","us":"media/us/cork__us_1.mp3","img":["media/ldoce/img/cork.jpg"]},"oxford":{"phon":"kɔːk","pos":"noun","senses":[{"en":"a light, soft material that is the thick bark of a type of Mediterranean oak tree","cn":"栓皮，木栓，软木（一种地中海橡树皮）","g":"[uncountable]","ex":{"en":"a cork mat","cn":"软木垫"}},{"en":"a small round object made of cork or plastic, that is used for closing bottles, especially wine bottles","cn":"（尤指酒瓶的）软木塞，塑料塞","g":"[countable]","ex":{"en":"to draw the cork","cn":"绘制软木塞"}},{"en":"to close a bottle with a cork","cn":"用软木塞封（瓶）","pos":"verb"},{"en":"the second largest city in the Republic of Ireland. Cork is a port and the capital of County Cork.","cn":"科克（爱尔兰共和国第二大城市，港口，科克郡首府）","pos":""}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"木栓，软木(一种地中海树皮)","en":"Cork is a soft, light substance which forms the bark of a type of Mediterranean tree.","ex":{"en":"...cork floors.","cn":"软木地板"}},{"pos":"N-COUNT 可数名词","cn":"软木塞;塑料瓶塞","en":"A cork is a piece of cork or plastic that is pushed into the opening of a bottle to close it."}]},"examples":[{"en":"cork tiles","cn":"软木薄砌块"},{"en":"a cork mat","cn":"软木垫"}]},"condense":{"oxford":{"phon":"kənˈdens","pos":"verb","senses":[{"en":"to change from a gas into a liquid; to make a gas change into a liquid","cn":"（由气体）冷凝；（使气体）凝结","g":"[intransitive, transitive]","ex":{"en":"Steam condenses into water when it cools.","cn":"蒸汽冷却时凝结为水。"}},{"en":"if a liquid condenses or you condense it, it becomes thicker and stronger because it has lost some of its water","cn":"（使）浓缩，变浓，变稠","g":"[intransitive, transitive]","ex":{"en":"Condense the soup by boiling it for several minutes.","cn":"煮几分钟把汤熬浓。"}},{"en":"to put something such as a piece of writing into fewer words; to put a lot of information into a small space","cn":"简缩；压缩（文字、信息等）","g":"[transitive]","ex":{"en":"The article was condensed into just two pages.","cn":"这篇文章被简缩成仅两页。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"压缩,精简(尤指文章或讲话)","en":"If you condense something, especially a piece of writing or speech, you make it shorter, usually by including only the most important parts.","ex":{"en":"We have learnt how to condense serious messages into short, self-contained sentences","cn":"我们已经学会了如何把重要的信息压缩成简短独立的句子。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)冷凝;(使)凝结","en":"When a gas or vapour condenses, or is condensed, it changes into a liquid.","ex":{"en":"Water vapour condenses to form clouds","cn":"水蒸气凝结形成云。"}}]},"media":{"uk":"media/uk/xcondense__gb_1.mp3","us":"media/us/xcondense__us_1.mp3"},"examples":[{"en":"The author has condensed a great deal of material into just 100 pages.","cn":"作者在短短 100 页中浓缩了大量信息。"},{"en":"The steam was condensed rapidly by injecting cold water into the cylinder.","cn":"由于气缸中注入了冷水，蒸汽迅速凝结了。"}]},"contributes":{"lemma":"contribute","media":{"uk":"media/uk/xcontribute__gb_1.mp3","us":"media/us/xcontribute__us_1.mp3"}},"confession":{"media":{"uk":"media/uk/xconfession__gb_1.mp3","us":"media/us/xconfession__us_1.mp3"},"oxford":{"phon":"kənˈfeʃn","pos":"noun","senses":[{"en":"a statement that a person makes, admitting that they are guilty of a crime; the act of making such a statement","cn":"供词；供状；认罪；供认","g":"[countable, uncountable]","ex":{"en":"After hours of questioning by police, she made a full confession.","cn":"经过警察数小时的审问，她供认了全部罪行。"}},{"en":"a statement admitting something that you are ashamed or embarrassed about; the act of making such a statement","cn":"（对使自己羞愧或尴尬的事的）表白，承认","g":"[countable, uncountable]","ex":{"en":"I've a confession to make—I lied about my age.","cn":"我有错要承认，我谎报了年龄。"}},{"en":"a private statement to a priest about the bad things that you have done; an occasion when you make such a statement","cn":"（向神父做的）告罪，告解，忏悔","g":"[uncountable, countable]","ex":{"en":"The priest heard her confession and granted absolution.","cn":"神父聆听了她的告解并给予她宽赦。"}},{"en":"a statement of your religious beliefs, principles, etc.","cn":"（宗教的）信仰表白","g":"[countable]","lab":"formal","ex":{"en":"a confession of faith","cn":"宗教信仰表白"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"供状;供词","en":"A confession is a signed statement by someone in which they admit that they have committed a particular crime.","ex":{"en":"They forced him to sign a confession.","cn":"他们强迫他在一份供词上签名。"}},{"pos":"N-VAR 可变名词","cn":"(对使自己羞愧或尴尬之事的)承认，坦白","en":"Confession is the act of admitting that you have done something that you are ashamed of or embarrassed about.","ex":{"en":"The diaries are a mixture of confession and observation","cn":"这些日记既有自白，也有评论。"}},{"pos":"N-VAR 可变名词","cn":"声明;告白;表白","en":"If you make a confession of your beliefs or feelings, you publicly tell people that this is what you believe or feel.","ex":{"en":"...Tatyana's confession of love.","cn":"塔季扬娜爱的告白"}},{"pos":"N-VAR 可变名词","cn":"(天主教会等的)忏悔，告解，办神工","en":"In the Catholic church and in some other churches, if you go to confession, you privately tell a priest about your sins and ask for forgiveness.","ex":{"en":"He never went to Father Porter for confession again.","cn":"他再也没有向波特神甫作过告解。"}}]},"examples":[{"en":"After hours of questioning by police, she made a full confession.","cn":"经过警察数小时的审问，她才供认了全部罪行。"},{"en":"I've a confession to make — I lied about my age.","cn":"我有错要承认 — 我谎报了年龄。"}]},"connected":{"media":{"uk":"media/uk/xconnected__gb_2.mp3","us":"media/us/xconnected__us_2.mp3"},"oxford":{"phon":"kəˈnektɪd","pos":"adjective","senses":[{"en":"(of two or more things or people) having a link between them","cn":"（两个或以上的事物或人）有联系的，相关的","ex":{"en":"We do not believe that the incidents are connected.","cn":"我们认为这些事件之间没有关联。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有关的;有联系的","en":"If one thing is connected with another, there is a link or relationship between them.","ex":{"en":"Have you ever had any skin problems connected with exposure to the sun?","cn":"你曾因日晒出现过皮肤问题吗？"}}]},"examples":[{"en":"market prices and other connected matters","cn":"市场价格及其他相关事宜"},{"en":"The two issues are closely connected.","cn":"这两个问题紧密相关。"}],"base":"connect"},"cottage":{"oxford":{"phon":"ˈkɒtɪdʒ","pos":"noun","senses":[{"en":"a small house, especially in the country","cn":"小屋；（尤指）村舍，小别墅","lab":"British English","ex":{"en":"a thatched cottage","cn":"茅舍"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"(乡间)小屋;村舍","en":"A cottage is a small house, usually in the country.","ex":{"en":"They used to have a cottage in N.W. Scotland","cn":"他们原来在苏格兰西北部有一间小屋。"}}]},"media":{"img":["media/pic/homes_comp.jpg","media/thumb/thatchedcottage.jpg"],"uk":"media/uk/cottage__gb_1.mp3","us":"media/us/cottage__us_1.mp3"},"examples":[{"en":"a charming country cottage with roses around the door","cn":"门口四周开着玫瑰花的迷人的乡村小屋"},{"en":"( BrE ) a holiday cottage","cn":"度假小别墅"}]},"converse":{"media":{"uk":"media/uk/xconverse__gb_1.mp3","us":"media/us/xconverse__us_1.mp3"},"oxford":{"phon":"kənˈvɜːs","pos":"verb","senses":[{"en":"to have a conversation with somebody","cn":"交谈；谈话","ex":{"en":"She conversed with the Romanians in French.","cn":"她用法语与罗马尼亚人交谈。"}},{"en":"opposite","cn":"相反","ex":{"en":"the converse effect","cn":"相反的效果"},"pos":"adjective"},{"en":"the opposite of a fact or statement","cn":"相反的事物；（事实或陈述的）反面","ex":{"en":"Building new roads increases traffic and the converse is equally true: reducing the number and size of roads means less traffic.","cn":"修筑新的道路会增加交通流量，反过来也是同样的道理：减少道路的数量和规模就意味着减少交通流量。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"(与…)交谈;(和…)说话","en":"If you converse with someone, you talk to them. You can also say that two people converse .","ex":{"en":"Luke sat directly behind the pilot and conversed with him","cn":"卢克就坐在飞行员后面，并且和他说着话。"}},{"pos":"N-SING 单数名词","cn":"相反的声明;相反的话;相反的言论","en":"The converse of a statement is its opposite or reverse.","ex":{"en":"What you do for a living is critical to where you settle and how you live — and the converse is also true.","cn":"一个人的谋生手段对于其居住地的选择和生活方式来说有着至关重要的影响，反之亦然。"}}]},"examples":[{"en":"Building new roads increases traffic and the converse is equally true: reducing the number and size of roads means less traffic.","cn":"修筑新的道路会增加交通流量，反过来也是同样的道理：减少道路的数量和规模就意味着减少交通流量。"},{"en":"the converse effect","cn":"相反的效果"}]},"countryside":{"media":{"img":["media/pic/countryside_labels_comp.jpg","media/thumb/countryside.jpg"],"uk":"media/uk/countryside__gb_1.mp3","us":"media/us/countryside__us_1.mp3"},"oxford":{"phon":"ˈkʌntrisaɪd","pos":"noun","senses":[{"en":"land outside towns and cities, with fields, woods, etc.","cn":"乡村；农村","lab":"especially North American English","ex":{"en":"The surrounding countryside is windswept and rocky.","cn":"这周围的乡村风多石头多。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"乡村;农村","en":"The countryside is land which is away from towns and cities.","ex":{"en":"I've always loved the English countryside","cn":"一直以来我都很喜欢英国的乡间。"}}]},"examples":[{"en":"Everyone should enjoy the right of access to the countryside.","cn":"人人都应享有进入乡村的权利。"},{"en":"The surrounding countryside is windswept and rocky.","cn":"这周围的乡村风多石头多。"}]},"compulsory":{"oxford":{"phon":"kəmˈpʌlsəri","pos":"adjective","senses":[{"en":"that must be done because of a law or a rule","cn":"（因法律或规则而）必须做的，强制的，强迫的","ex":{"en":"English is a compulsory subject at this level.","cn":"英语在这一级别是必修科目。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"强制性的;强迫的；义务的","en":"If something is compulsory, you must do it or accept it, because it is the law or because someone in a position of authority says you must.","ex":{"en":"In East Germany learning Russian was compulsory","cn":"在东德，俄语是必修课。"}}]},"media":{"uk":"media/uk/compulsory__gb_1.mp3","us":"media/us/compulsory__us_1.mp3"},"examples":[{"en":"It is compulsory for all motorcyclists to wear helmets.","cn":"所有骑摩托车的人都必须戴头盔，这是强制性的。"},{"en":"English is a compulsory subject at this level.","cn":"英语在这一级次是必修科目。"}]},"communion":{"oxford":{"phon":"kəˈmjuːniən","pos":"noun","senses":[{"en":"the state of sharing or exchanging thoughts and feelings; the feeling of being part of something","cn":"（思想感情的）交流，交融","g":"[uncountable]","lab":"formal","ex":{"en":"poets living in communion with nature","cn":"与大自然情感交融的诗人"}},{"en":"a ceremony in the Christian Church during which people eat bread and drink wine in memory of the last meal that Christ had with his disciples","cn":"（基督教教会的）圣餐仪式，领受圣体","g":"[uncountable]","ex":{"en":"to go to Communion (= attend church for this celebration)","cn":"去参加圣餐仪式"}},{"en":"a group of people with the same religious beliefs","cn":"教派；教会；宗教团体","g":"[countable]","lab":"specialist","ex":{"en":"the Anglican communion","cn":"圣公会"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(思想或情感的)交流，交融","en":"Communion with nature or with a person is the feeling that you are sharing thoughts or feelings with them.","ex":{"en":"...communion with nature.","cn":"与大自然的交融"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(基督教的)圣餐仪式","en":"Communion is the Christian ceremony in which people eat bread and drink wine in memory of Christ's death.","ex":{"en":"Most villagers took communion only at Easter.","cn":"大部分村民只在复活节的时候领受圣餐。"}}]},"media":{"uk":"media/uk/communion__gb_1.mp3","us":"media/us/communion__us_1.mp3"},"examples":[{"en":"poets living in communion with nature","cn":"与大自然情感交融的诗人"},{"en":"to go to Communion (= attend church for this celebration)","cn":"去参加圣餐仪式"}]},"commercialization":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be more concerned with making money from something than about its quality – used to show disapproval","cn":""},{"en":"to sell something completely new to the public for the first time","cn":""}]},"examples":[{"en":"Christmas has become so commercialized.","cn":"","src":"ld"},{"en":"Some space launches will be commercialized to help pay for more space research.","cn":"","src":"ld"}],"media":{"uk":"media/uk/commercialization__gb_1.mp3","us":"media/us/commercialization__us_1.mp3"},"oxford":{"phon":"kəˌmɜːʃəlaɪˈzeɪʃn","pos":"noun","senses":[{"en":"the act of using something to try to make a profit, especially in a way that other people do not approve of","cn":"商业化","ex":{"en":"to complain about the commercialization of Christmas","cn":"抱怨圣诞节的商业化"}}]}},"communication":{"media":{"uk":"media/uk/communication__gb_1.mp3","us":"media/us/communication__us_1.mp3"},"oxford":{"phon":"kəˌmjuːnɪˈkeɪʃn","pos":"noun","senses":[{"en":"the activity or process of expressing ideas and feelings or of giving people information","cn":"表达；交流；交际；传递","g":"[uncountable]","ex":{"en":"Good communication between team leaders and members is essential.","cn":"团队领导和成员之间的良好沟通至关重要。"}},{"en":"methods of sending information, especially phones, radio, computers, etc. or roads and railways","cn":"通信；交通联系","g":"[uncountable]","ex":{"en":"communications technology","cn":"通信技术"}},{"en":"a message, letter or phone call","cn":"信息；书信；电话","g":"[countable]","lab":"formal","ex":{"en":"a communication from the leader of the party","cn":"来自该党领袖的信息"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"(尤指依靠电或无线电波的)通信系统，通信","en":"Communications are the systems and processes that are used to communicate or broadcast information, especially by means of electricity or radio waves.","ex":{"en":"...a communications satellite.","cn":"通讯卫星"}},{"pos":"N-COUNT 可数名词","cn":"消息;信息","en":"A communication is a message.","ex":{"en":"The ambassador has brought with him a communication from the President.","cn":"大使带来了总统的口信。"}}]},"examples":[{"en":"Snow has prevented communication with the outside world for three days.","cn":"大雪使得与外界的通信联系中断了三天。"},{"en":"Speech is the fastest method of communication between people.","cn":"说话是人与人之间最快捷的沟通方法。"}]},"college":{"media":{"uk":"media/uk/college__gb_1.mp3","us":"media/us/college__us_1.mp3"},"oxford":{"phon":"ˈkɒlɪdʒ","pos":"noun","senses":[{"en":"(in the UK) a place where students go to study or to receive training after they have left school","cn":"（英国）学院，职业学校，技术学校","g":"[countable, uncountable]","ex":{"en":"a secretarial college","cn":"文秘职业学校"}},{"en":"(in the US) a university where students can study for a degree after they have left school","cn":"（美国）大学","g":"[countable, uncountable]","lab":"British English","ex":{"en":"She was the first in her family to attend college.","cn":"她是家里的第一个大学生。"}},{"en":"a place where you can study for higher or more specialist qualifications after you finish high school","cn":"高等专科学校；高等职业学院","g":"[countable, uncountable]","lab":"Canadian English"},{"en":"one of the separate institutions that some British universities, such as Oxford and Cambridge, are divided into","cn":"（英国大学如牛津和剑桥中独立的）学院","g":"[countable, uncountable]","ex":{"en":"King’s College, Cambridge","cn":"剑桥大学的国王学院"}},{"en":"(in the US) one of the main divisions of some large universities","cn":"（美国一些规模大的大学的）学院","ex":{"en":"The history department is part of the College of Arts and Sciences.","cn":"历史系是文理学院的一部分。"}},{"en":"the teachers and/or students of a college","cn":"（学院的）师生，教师，学生","g":"[countable + singular or plural verb]"},{"en":"a secondary school, especially one where you must pay","cn":"（尤指必须交费的）中学，公学","g":"[countable]","ex":{"en":"Eton College","cn":"伊顿公学"}},{"en":"an organized group of professional people with special interests, duties or powers","cn":"学会；协会；社团","g":"[countable]","ex":{"en":"the Royal College of Physicians","cn":"皇家医师协会"}}]},"collins":{"senses":[{"pos":"N-VAR; N-IN-NAMES 可变名词；名称名词","cn":"大学;学院;专科学校","en":"A college is an institution where students study after they have left school.","ex":{"en":"Their daughter Joanna is doing business studies at a local college","cn":"他们的女儿乔安娜在当地的一所学院念商科。"}},{"pos":"N-COUNT 可数名词","cn":"(英国某些大学设立的)学院","en":"A college is one of the institutions which some British universities are divided into.","ex":{"en":"He was educated at Balliol College, Oxford.","cn":"他上的是牛津大学的贝利奥尔学院。"}},{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"(美国某些大学的专科)学院","en":"At some universities in the United States, colleges are divisions which offer degrees in particular subjects.","ex":{"en":"...a professor at the University of Florida College of Law.","cn":"佛罗里达大学法学院的一位教授"}},{"pos":"N-IN-NAMES 名称名词","cn":"(用于英国某些收费中学的名称中)中学，公学","en":"College is used in Britain in the names of some secondary schools which charge fees.","ex":{"en":"In 1854, Cheltenham Ladies' College became the first girls' public school.","cn":"1854年，切尔滕纳姆女子中学成为第一所女子公学。"}},{"pos":"N-COUNT 可数名词","cn":"学会;协会;社团","en":"A college of a particular kind is an organized group of people who have special duties and powers.","ex":{"en":"He is a member of the Royal College of Physicians","cn":"他是皇家内科医师协会的成员。"}}]},"examples":[{"en":"‘Where did you go to college?’ ‘Ohio State University.’ “","cn":"你在什么地方上的大学？” “俄亥俄州立大学”"},{"en":"He got interested in politics when he was in college.","cn":"他在上大学时就开始对政治感兴趣了。"}]},"contrast":{"media":{"uk":"media/uk/xcontrast__gb_1.mp3","us":"media/us/xcontrast__us_1.mp3"},"oxford":{"phon":"ˈkɒntrɑːst","pos":"noun","senses":[{"en":"a difference between two or more people or things that you can see clearly when they are compared or put close together; the fact of comparing two or more things in order to show the differences between them","cn":"明显的差异；对比；对照","g":"[countable, uncountable]","ex":{"en":"The two cities make an interesting contrast.","cn":"这两个城市形成有趣的对比。"}},{"en":"a person or thing that is clearly different from somebody/something else","cn":"明显不同的人（或事物）","g":"[countable, usually singular]","ex":{"en":"The work you did today is quite a contrast to (= very much better/worse than) what you did last week.","cn":"你今天的表现与上周截然不同。"}},{"en":"differences in colour or in light and dark, used in photographs and paintings to create a special effect","cn":"（摄影或绘画中的）颜色反差，明暗对比","g":"[uncountable]","ex":{"en":"The artist's use of contrast is masterly.","cn":"这位艺术家娴熟地运用了明暗对比。"}},{"en":"the amount of difference between light and dark in a photograph or the picture on a television screen","cn":"（照片或电视图像的）明暗对比度，反差","g":"[uncountable]","ex":{"en":"Use this button to adjust the contrast.","cn":"用此按钮调节图像明暗的对比度。"}},{"en":"to compare two things in order to show the differences between them","cn":"对比；对照","g":"[transitive]","ex":{"en":"The poem contrasts youth and age.","cn":"这首诗对比了青年与老年。"},"pos":"verb"},{"en":"to show a clear difference when close together or when compared","cn":"（靠近或作比较时）显出明显的差异，形成对比","g":"[intransitive]","ex":{"en":"Her actions contrasted sharply with her promises.","cn":"她的行为与她的诺言相差甚远。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"差异;差别;悬殊","en":"A contrast is a great difference between two or more things which is clear when you compare them.","ex":{"en":"...the contrast between town and country","cn":"城乡差别"}},{"pos":"PHRASE 短语","cn":"相比之下;与…相反","en":"You say by contrast or in contrast, or in contrast to something, to show that you are mentioning a very different situation from the one you have just mentioned.","ex":{"en":"The private sector, by contrast, has plenty of money to spend","cn":"相比之下，私营部门就有很多钱可供开销。"}},{"pos":"PHRASE 短语","cn":"与…截然不同;与…对比鲜明","en":"If one thing is in contrast to another, it is very different from it.","ex":{"en":"His public statements have always been in marked contrast to those of his son","cn":"他和他儿子在公开场合的言论总是截然不同。"}},{"pos":"N-COUNT 可数名词","cn":"截然不同的事物;差异明显的事物","en":"If one thing is a contrast to another, it is very different from it.","ex":{"en":"The boy's room is a complete contrast to the guest room.","cn":"这个男孩的房间和客房截然不同。"}},{"pos":"VERB 动词","cn":"对比;对照","en":"If you contrast one thing with another, you point out or consider the differences between those things.","ex":{"en":"She contrasted the situation then with the present crisis","cn":"她将当时的情况和目前的危机进行对比。"}},{"pos":"V-RECIP 相互动词","cn":"截然不同;有明显差异;对比鲜明","en":"If one thing contrasts with another, it is very different from it.","ex":{"en":"Johnson's easy charm contrasted sharply with the prickliness of his boss","cn":"约翰逊的亲和力和他老板易怒的性格形成了鲜明的对比。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(照片、电视图像、画作等的)颜色反差，明暗对比","en":"Contrast is the degree of difference between the darker and lighter parts of a photograph, television picture, or painting.","ex":{"en":"...a television with brighter colours, better contrast, and digital sound.","cn":"颜色更为鲜艳、图像对比度更高、具备数字音响效果的电视"}}]},"examples":[{"en":"The company lost $7 million this quarter in contrast to a profit of $6.2 million a year earlier.","cn":"这家公司本季度亏损了 700 万元，与去年同期 620 万元的盈利形成了对照。"},{"en":"The poverty of her childhood stands in total contrast to her life in Hollywood.","cn":"她孩提时的贫困处境与她在好莱坞的生活有着天壤之别。"}]},"contradictory":{"media":{"uk":"media/uk/xcontradictory__gb_1.mp3","us":"media/us/xcontradictory__us_1.mp3"},"oxford":{"phon":"ˌkɒntrəˈdɪktəri","pos":"adjective","senses":[{"en":"containing or showing a lack of agreement between statements, facts, opinions or actions","cn":"相互矛盾的；对立的；不一致的","ex":{"en":"We are faced with two apparently contradictory statements.","cn":"我们面前这两种说法显然是矛盾的。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"互相矛盾的;相互对立的","en":"If two or more facts, ideas, or statements are contradictory, they state or imply that opposite things are true.","ex":{"en":"Customs officials have made a series of contradictory statements about the equipment","cn":"海关官员们对这种设备作出了一系列互相矛盾的陈述。"}}]},"examples":[{"en":"We are faced with two apparently contradictory statements.","cn":"我们面前这两种说法显然是矛盾的。"},{"en":"The advice I received was often contradictory.","cn":"我所得到的建议常常是相互矛盾的。"}]},"consumer":{"media":{"uk":"media/uk/xconsumer__gb_1.mp3","us":"media/us/xconsumer__us_1.mp3"},"oxford":{"phon":"kənˈsjuːmə(r)","pos":"noun","senses":[{"en":"a person who buys goods or uses services","cn":"消费者；顾客；用户","ex":{"en":"consumer spending/demand","cn":"消费支出／需求"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"消费者;顾客;客户","en":"A consumer is a person who buys things or uses services.","ex":{"en":"...claims that tobacco companies failed to warn consumers about the dangers of smoking.","cn":"声称烟草公司未能警示消费者吸烟的危害"}}]},"examples":[{"en":"Health-conscious consumers want more information about the food they buy.","cn":"注重身体健康的消费者想得到更多有关他们所购买的食物的信息。"},{"en":"Tax cuts will boost consumer confidence after the recession.","cn":"减税将增强消费者在经济衰退后的信心。"}]},"commits":{"lemma":"commit"},"coverage":{"media":{"uk":"media/uk/coverage__gb_1.mp3","us":"media/us/coverage__us_1.mp3"},"oxford":{"phon":"ˈkʌvərɪdʒ","pos":"noun","senses":[{"en":"the reporting of news and sport in the media","cn":"新闻报道","g":"[uncountable]","ex":{"en":"media/newspaper/press coverage","cn":"媒体／报纸／报刊的报道"}},{"en":"the range or quality of information that is included in a book or course of study, on television, etc.","cn":"（书、课程学习、电视等的）信息范围，信息质量","g":"[uncountable]","ex":{"en":"magazines with extensive coverage of diet and health topics","cn":"包含大量饮食与健康话题的杂志"}},{"en":"the amount of something that something provides; the extent to which something covers an area or a group of people","cn":"提供的数量；覆盖范围","g":"[uncountable, countable, usually singular]","ex":{"en":"Immunization coverage against fatal diseases has increased to 99 per cent in some countries.","cn":"有些国家针对致命疾病的免疫接种率已提高到 99%。"}},{"en":"protection that an insurance company provides by promising to pay you money if a particular event happens","cn":"（保险公司的）保险","g":"[uncountable]","lab":"North American English","ex":{"en":"insurance coverage","cn":"保险范围"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"新闻报道；采访","en":"The coverage of something in the news is the reporting of it.","ex":{"en":"Now a special TV network gives live coverage of most races","cn":"现在有一个专门的电视网络对大部分比赛进行现场直播。"}}]},"examples":[{"en":"Immunization coverage against fatal diseases has increased to 99% in some countries.","cn":"在一些国家致命疾病免疫注射的覆盖面已达到 99%。"},{"en":"magazines with extensive coverage of diet and health topics","cn":"包含大量饮食与健康话题的杂志"}]},"commission":{"media":{"uk":"media/uk/commission__gb_1.mp3","us":"media/us/commission__us_1.mp3"},"oxford":{"phon":"kəˈmɪʃn","pos":"noun","senses":[{"en":"an official group of people who have been given responsibility to control something, or to find out about something, usually for the government","cn":"（通常为政府管控或调查某事的）委员会","g":"[countable]","lab":"British English","sc":"official group","ex":{"en":"The commission is expected to report its findings next month.","cn":"预计委员会将在下个月报告调查结果。"}},{"en":"an amount of money that is paid to somebody for selling goods and that increases with the amount of goods that are sold","cn":"佣金；回扣","g":"[uncountable, countable]","sc":"money","ex":{"en":"You get a 10 per cent commission on everything you sell.","cn":"你可从你售出的每件商品中获得 10% 的佣金。"}},{"en":"an amount of money that is charged by a bank, etc. for providing a particular service","cn":"（银行等的）手续费","g":"[uncountable, singular]","sc":"money","ex":{"en":"1 per cent commission is charged for exchanging foreign currency.","cn":"换外币收取 1% 的手续费。"}},{"en":"a formal request to somebody to design or make a piece of work such as a building or a painting; the fact of making such a request","cn":"（请某人作建筑设计或作画等的）正式委托","g":"[countable]","sc":"for art/music, etc.","ex":{"en":"Eventually she agreed to accept the commission.","cn":"最后她同意接受委托。"}},{"en":"the position of an officer in the armed forces, typically with the rank of lieutenant or higher","cn":"（通常指陆军中尉、海军上尉、空军上尉及以上的）军衔","g":"[countable]","sc":"in armed forces","ex":{"en":"He resigned his commission when he got married.","cn":"结婚后，他辞去了佣金。"}},{"en":"the act of doing something wrong or illegal","cn":"做错事；犯罪","g":"[uncountable]","lab":"formal","sc":"of crime","ex":{"en":"the commission of a crime","cn":"犯罪"}},{"en":"to officially ask somebody to write, make or create something or to do a task for you","cn":"正式委托（谱写、制作、创作或完成）","sc":"piece of art/music, etc.","ex":{"en":"She has been commissioned to write a new national anthem.","cn":"她已受委托谱写新国歌。"},"pos":"verb"},{"en":"to choose somebody as an officer in one of the armed forces","cn":"任命…为军官","g":"[usually passive]","sc":"in armed forces","ex":{"en":"She was commissioned in 2014.","cn":"她于 2014 年被任命为军官。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"正式委托;委托(做)","en":"If you commission something or commission someone to do something, you formally arrange for someone to do a piece of work for you.","ex":{"en":"The Ministry of Agriculture commissioned a study into low-input farming","cn":"农业部委托对低投入耕作进行研究。"}},{"pos":"N-COUNT 可数名词","cn":"受托之事;(接受报酬的)任务","en":"A commission is a piece of work that someone is asked to do and is paid for.","ex":{"en":"Just a few days ago, I finished a commission.","cn":"就在几天前，我完成了一项委托创作任务。"}},{"pos":"N-VAR 可变名词","cn":"佣金;回扣","en":"Commission is a sum of money paid to a salesperson for every sale that he or she makes. If a salesperson is paid on commission, the amount they receive depends on the amount they sell.","ex":{"en":"The salesmen work on commission only","cn":"销售人员只根据销售量提取佣金。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(银行或公司收取的)服务费，手续费","en":"If a bank or other company charges commission, they charge a fee for providing a service, for example for exchanging money or issuing an insurance policy.","ex":{"en":"Travel agents charge 1 per cent commission on sterling cheques","cn":"旅行社对英镑支票收取1%的服务费。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"委员会;调查团","en":"A commission is a group of people who have been appointed to find out about something or to control something.","ex":{"en":"The authorities have been asked to set up a commission to investigate the murders.","cn":"当局被敦促成立一个委员会负责调查这些谋杀案。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"犯(罪)","en":"The commission of a crime is the act of committing a crime.","ex":{"en":"If a person uses a gun in the commission of a crime, then he should be given an additional penalty.","cn":"如果使用枪支进行犯罪，就应该受到额外的惩罚。"}},{"pos":"N-COUNT 可数名词","cn":"(军队的)任职令","en":"If a member of the armed forces receives a commission, he or she becomes an officer.","ex":{"en":"He accepted a commission as a naval officer.","cn":"他接受任命成为一名海军军官。"}},{"pos":"VERB 动词","cn":"委任;任命…为军官","en":"If a member of the armed forces is commissioned, he or she is made an officer.","ex":{"en":"He was commissioned as second lieutenant in the Air Force","cn":"他被任命为空军少尉。"}},{"pos":"PHRASE 短语","cn":"(船、设备等)坏了的，不能使用的","en":"If something, for example a ship or a piece of equipment, is out of commission, it is broken and cannot be used until it is repaired.","ex":{"en":"The operator expects the ship to be out of commission until the end of September.","cn":"技工预计这艘船到9月底才能修好。"}}]},"examples":[{"en":"Several of the airline's planes are temporarily out of commission and undergoing safety checks.","cn":"这家航空公司有几架飞机暂时不能使用，正在接受安全检查。"},{"en":"You get a 10% commission on everything you sell.","cn":"你可从你售出的每件商品中获得 10% 的佣金。"}]},"coldly":{"media":{"uk":"media/uk/coldly__gb_1.mp3","us":"media/us/coldly__us_1.mp3"},"oxford":{"phon":"ˈkəʊldli","pos":"adverb","senses":[{"en":"without any emotion or warm feelings; in a way that is unfriendly","cn":"冷淡地；冷漠地；不友好地","ex":{"en":"to stare/smile/reply coldly","cn":"冷漠地盯；冷冷地笑；冷淡地回答"}}]}},"continent":{"media":{"uk":"media/uk/xcontinent__gb_2.mp3","us":"media/us/xcontinent__us_2.mp3"},"oxford":{"phon":"ˈkɒntɪnənt","pos":"adjective","senses":[{"en":"connected with the control of your feelings, especially your desire to have sex","cn":"节欲的：与控制你的情绪有关，特别是你对性的渴望","lab":"formal"},{"en":"able to control the bladder and bowels","cn":"（大小便的）自控能力，节制力"},{"en":"one of the large land masses of the earth such as Europe, Asia or Africa","cn":"大陆；陆地；洲","g":"[countable]","ex":{"en":"the continent of Africa","cn":"非洲大陆"},"pos":"noun"},{"en":"the main part of the continent of Europe, not including Britain or Ireland","cn":"欧洲大陆（不包括英国和爱尔兰）","g":"[singular]","lab":"British English, old-fashioned，，","ex":{"en":"They planned to spend the summer on the Continent.","cn":"他们计划在欧洲大陆度过夏天。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大陆;洲","en":"A continent is a very large area of land, such as Africa or Asia, that consists of several countries.","ex":{"en":"She loved the African continent","cn":"她热爱非洲大陆。"}},{"pos":"N-PROPER 专有名词","cn":"(指英国之外的)欧洲大陆","en":"People sometimes use the Continent to refer to the continent of Europe except for Britain.","ex":{"en":"Its shops are among the most stylish on the Continent.","cn":"其店铺跻身欧陆最时尚的店铺之列。"}}]},"examples":[{"en":"We're going to spend a weekend on the Continent.","cn":"我们要去欧洲大陆度周末。"},{"en":"the continent of Africa","cn":"非洲大陆"}]},"coma":{"media":{"uk":"media/uk/coma__gb_1.mp3","us":"media/us/coma__us_1.mp3"},"oxford":{"phon":"ˈkəʊmə","pos":"noun","senses":[{"en":"a deep unconscious state, usually lasting a long time and caused by serious illness or injury","cn":"昏迷","ex":{"en":"to go into/be in a coma","cn":"陷入／处于昏迷状态"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"昏迷","en":"Someone who is in a coma is in a state of deep unconsciousness.","ex":{"en":"She was in a coma for seven weeks","cn":"她已经昏迷7个星期了。"}}]},"examples":[{"en":"to go into/be in a coma","cn":"陷入/处于昏迷状态"}]},"conscience":{"media":{"uk":"media/uk/xconscience__gb_1.mp3","us":"media/us/xconscience__us_1.mp3"},"oxford":{"phon":"ˈkɒnʃəns","pos":"noun","senses":[{"en":"the part of your mind that tells you whether your actions are right or wrong","cn":"良心；良知","g":"[countable, uncountable]","ex":{"en":"to have a clear/guilty conscience (= to feel that you have done right/wrong)","cn":"问心无愧／有愧"}},{"en":"a guilty feeling about something you have done or failed to do","cn":"内疚；愧疚","g":"[uncountable, countable]","ex":{"en":"She was seized by a sudden pang of conscience.","cn":"她突然感到一阵内疚。"}},{"en":"the fact of behaving in a way that you feel is right even though this may cause problems","cn":"凭良心","g":"[uncountable]","ex":{"en":"freedom of conscience (= the freedom to do what you believe to be right)","cn":"凭良心行事的自由"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"良心;良知","en":"Your conscience is the part of your mind that tells you whether what you are doing is right or wrong. If you have a guilty conscience, you feel guilty about something because you know it was wrong. If you have a clear conscience, you do not feel guilty because you know you have done nothing wrong.","ex":{"en":"I have battled with my conscience over whether I should actually send this letter","cn":"我备受良心的煎熬，不知是否真的应该把这封信寄出去。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"信仰；凭良心行事","en":"Conscience is doing what you believe is right even though it might be unpopular, difficult, or dangerous.","ex":{"en":"He refused for reasons of conscience to sign a new law legalising abortion.","cn":"他出于信仰，拒绝签署使堕胎合法化的新法。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"内疚;良心不安","en":"Conscience is a feeling of guilt because you know you have done something that is wrong.","ex":{"en":"I'm so glad he had a pang of conscience","cn":"我很高兴他会有负疚感。"}},{"pos":"PHRASE 短语","cn":"凭良心;出于公道","en":"If you say that you cannot do something in all conscience ,in good conscience, or in conscience, you mean that you cannot do it because you think it is wrong.","ex":{"en":"She could not, in good conscience, back out on her deal with him.","cn":"凭良心她不能背弃与他达成的协议。"}},{"pos":"PHRASE 短语","cn":"内疚;良心不安","en":"If you have something on your conscience, you feel guilty because you know you have done something wrong.","ex":{"en":"Now the murderer has two deaths on his conscience.","cn":"现在，这个杀人犯背着两条人命，受到了良心的谴责。"}}]},"examples":[{"en":"I'll write and apologize. I've had it on my conscience for weeks.","cn":"我要写信赔礼道歉。几个星期以来我都为此而良心不安。"},{"en":"Emilia is the voice of conscience in the play.","cn":"伊米莉亚在这出戏剧中代表良知的一面。"}]},"correct":{"media":{"uk":"media/uk/correct__gb_1.mp3","us":"media/us/correct__us_1.mp3"},"oxford":{"phon":"kəˈrekt","pos":"adjective","senses":[{"en":"accurate or true, without any mistakes","cn":"准确无误的；精确的；正确的","ex":{"en":"Do you have the correct time?","cn":"你的表走得准吗？"}},{"en":"right and suitable, so that something is done as it should be done","cn":"恰当的；合适的","ex":{"en":"the correct procedure/approach","cn":"正确的程序／方法"}},{"en":"taking care to speak or behave in a way that follows the accepted standards or rules","cn":"（言谈举止）符合公认准则的，得体的","ex":{"en":"a correct young lady","cn":"举止得体的年轻女士"}},{"en":"to make something right or accurate, for example by changing it or removing mistakes","cn":"改正；纠正；修正","ex":{"en":"to correct an error","cn":"改正错误"},"pos":"verb"},{"en":"to mark the mistakes in a piece of work (and sometimes give a mark to the work)","cn":"批改；改","ex":{"en":"I spent all evening correcting essays.","cn":"我整个晚上都在批改论文。"},"pos":"verb"},{"en":"to tell somebody that they have made a mistake","cn":"指出错误","lab":"North American English, informal，，","ex":{"en":"Correct me if I'm wrong, but isn't this last year's brochure?","cn":"这不是去年的小册子吗？若是我说错了就请指出。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"准确无误的;正确的","en":"If something is correct, it is in accordance with the facts and has no mistakes.","ex":{"en":"The correct answers can be found at the bottom of page 8","cn":"正确答案在第8页末尾。"}},{"pos":"ADJ 形容词","cn":"(说法或想法)对的，正确的","en":"If someone is correct, what they have said or thought is true.","ex":{"en":"You are absolutely correct. The leaves are from a bay tree","cn":"你说得很对，这是月桂树的叶子。"}},{"pos":"ADJ 形容词","cn":"恰当的;合适的","en":"The correct thing or method is the thing or method that is required or is most suitable in a particular situation.","ex":{"en":"The use of the correct materials was crucial","cn":"使用恰当的材料至关重要。"}},{"pos":"ADJ 形容词","cn":"(行为)被人认可的，赞许的","en":"If you say that someone is correct in doing something, you approve of their action.","ex":{"en":"You are perfectly correct in trying to steer your mother towards increased independence","cn":"你试图让自己的母亲变得越来越独立，这样做很正确。"}},{"pos":"VERB 动词","cn":"纠正(问题);改正，修正(错误)","en":"If you correct a problem, mistake, or fault, you do something which puts it right.","ex":{"en":"He may need surgery to correct the problem","cn":"要解决这个问题，他可能需要做外科手术。"}},{"pos":"VERB 动词","cn":"纠正;指出…的错误","en":"If you correct someone, you say something which you think is more accurate or appropriate than what they have just said.","ex":{"en":"'Actually, that isn't what happened,' George corrects me","cn":"“实际上，并不是那样，”乔治纠正我。"}},{"pos":"VERB 动词","cn":"批改，修改(文章等)","en":"When someone corrects a piece of writing, they look at it and mark the mistakes in it.","ex":{"en":"It took an extraordinary effort to focus on preparing his classes or correcting his students' work.","cn":"备课和批改学生的作业花费了他很多精力。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(行为)符合社会公认标准的，得体的","en":"If a person or their behaviour is correct, their behaviour is in accordance with social or other rules.","ex":{"en":"I think English men are very polite and very correct","cn":"我认为英国人很有礼貌，举止非常得体。"}},{"pos":"CONVENTION 惯用语","cn":"若是我说错了就请指出","en":"You say 'correct me if I'm wrong' to indicate that you are not entirely sure that what you are about to say is true.","ex":{"en":"As I recall, but correct me if I'm wrong, it was in a car park in Carmarthen.","cn":"如果我没记错的话，那是在卡马森的一个停车场内。"}}]},"examples":[{"en":"‘It's Yates, not Wates,’ she corrected him. “","cn":"那是 Yates 而不是 Wates。”她纠正他道。"},{"en":"Read through your work and correct any mistakes that you find.","cn":"从头至尾看一遍你们的作业，发现的错误都要改正过来。"}]},"computing":{"media":{"img":["media/pic/computing_equipment_comp.jpg","media/thumb/pc.jpg"],"uk":"media/uk/computing__gb_1.mp3","us":"media/us/computing__us_1.mp3"},"oxford":{"phon":"kəmˈpjuːtɪŋ","pos":"noun","senses":[{"en":"the fact of using computers","cn":"计算；计算机技术；信息处理技术","ex":{"en":"to work in computing","cn":"从事信息处理"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"计算机操作;计算机应用","en":"Computing is the activity of using a computer and writing programs for it.","ex":{"en":"Courses range from cookery to computing.","cn":"课程多种多样，从烹调到计算机操作应有尽有。"}},{"pos":"ADJ 形容词","cn":"计算机的;计算机应用的","en":"Computing means relating to computers and their use.","ex":{"en":"Many graduates are employed in the electronics and computing industries.","cn":"很多毕业生就职于电子和计算机行业。"}}]},"examples":[{"en":"computing power/services/skills/systems","cn":"数据处理能力/服务/技术/系统"},{"en":"educational/network/scientific computing","cn":"教育/网络/科学信息处理技术"}]},"continued":{"media":{"uk":"media/uk/xcontinued__gb_1.mp3","us":"media/us/xcontinued__us_1.mp3"},"oxford":{"phon":"kənˈtɪnjuːd","pos":"adjective","senses":[{"en":"existing in the same state without change or a break","cn":"继续不变的；连续不断的","ex":{"en":"We are grateful for your continued/continuing support.","cn":"我们对你们始终不渝的支持不胜感激。"}}]},"examples":[{"en":"We are grateful for your continued/continuing support.","cn":"我们对你们始终不渝的支持不胜感激。"},{"en":"continued interest","cn":"持久的兴趣"}],"base":"continue"},"commodity":{"media":{"uk":"media/uk/commodity__gb_1.mp3","us":"media/us/commodity__us_1.mp3"},"oxford":{"phon":"kəˈmɒdəti","pos":"noun","senses":[{"en":"a product or a raw material that can be bought and sold","cn":"商品","lab":"economics","ex":{"en":"rice, flour and other basic commodities","cn":"稻米、面粉和其他基本商品"}},{"en":"a thing that is useful or has a useful quality","cn":"有用的东西；有使用价值的事物","lab":"formal","ex":{"en":"Water is a precious commodity that is often taken for granted in the West.","cn":"水很宝贵，但在西方国家人们往往意识不到这一点。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"商品","en":"A commodity is something that is sold for money.","ex":{"en":"The government increased prices on several basic commodities like bread and meat.","cn":"政府提高了面包、肉类等几种基本商品的价格。"}}]},"examples":[{"en":"Water is a precious commodity that is often taken for granted in the West.","cn":"水很宝贵，但在西方国家人们往往意识不到这一点。"},{"en":"Crude oil is the world's most important commodity.","cn":"原油是世界上最重要的商品。"}]},"councils":{"lemma":"council","media":{"uk":"media/uk/council__gb_1.mp3","us":"media/us/council__us_1.mp3"}},"conspiracy":{"media":{"uk":"media/uk/xconspiracy__gb_1.mp3","us":"media/us/xconspiracy__us_1.mp3"},"oxford":{"phon":"kənˈspɪrəsi","pos":"noun","senses":[{"en":"a secret plan by a group of people to do something harmful or illegal","cn":"密谋策划；阴谋","ex":{"en":"a conspiracy to overthrow the government","cn":"颠覆政府的阴谋"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"密谋;阴谋","en":"Conspiracy is the secret planning by a group of people to do something illegal.","ex":{"en":"Seven men, all from Bristol, admitted conspiracy to commit arson","cn":"7个人都来自布里斯托尔，他们承认了合谋纵火。"}},{"pos":"N-COUNT 可数名词","cn":"阴谋","en":"A conspiracy is an agreement between a group of people which other people think is wrong or is likely to be harmful.","ex":{"en":"It's all part of a conspiracy to dispense with the town centre all together and move everything out to Meadowhall","cn":"彻底抛开市中心而把所有东西都搬到梅多霍尔购物中心，这完全是一场阴谋的一部分。"}},{"pos":"PHRASE 短语","cn":"（为了私利）保持缄默的密约","en":"If there is a conspiracy of silence about something, people who know about it have agreed that they will not talk publicly about it, although it would probably be a good thing if people in general knew about it.","ex":{"en":"Detectives have run into a conspiracy of silence in the tight-knit communities of the peninsula.","cn":"侦探们犯了难，半岛上各个群体抱成一团，达成了保持缄默的密约。"}}]},"examples":[{"en":"a conspiracy of silence (= an agreement not to talk publicly about sth which should be made public)","cn":"保持缄默的密约（对该公开的事情不公开谈论的约定）"},{"en":"a conspiracy theory (= the belief that a secret conspiracy is responsible for a particular event)","cn":"阴谋论（认为某事件背后有阴谋）"}]},"collar":{"media":{"uk":"media/uk/collar__gb_1.mp3","us":"media/us/collar__us_1.mp3","img":["media/ldoce/img/greyhound.jpg"]},"oxford":{"phon":"ˈkɒlə(r)","pos":"noun","senses":[{"en":"the part around the neck of a shirt, jacket or coat that usually folds down","cn":"衣领；领子","ex":{"en":"a coat with a fur collar","cn":"毛皮领大衣"}},{"en":"a band of leather or plastic put around the neck of an animal, especially a dog","cn":"（动物，尤指狗的）颈圈","ex":{"en":"a collar and lead/leash","cn":"颈圈和系带"}},{"en":"a band made of a strong material that is put round something, such as a pipe or a machine, to make it stronger or to join two parts together","cn":"（管子或机器的）圈，箍","lab":"specialist"},{"en":"to capture somebody and hold them tightly so that they cannot escape from you","cn":"抓住；捉住；揪住；逮住","ex":{"en":"Police collared the culprit as he was leaving the premises.","cn":"罪犯正离开现场时，警察逮住了他。"},"pos":"verb"},{"en":"to stop somebody in order to talk to them","cn":"拦住（某人以与其）谈话","ex":{"en":"I was collared in the street by a woman doing a survey.","cn":"我在大街上被一个做民意调查的女人拦住问话。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"衣领;领子","en":"The collar of a shirt or coat is the part which fits round the neck and is usually folded over.","ex":{"en":"His tie was pulled loose and his collar hung open.","cn":"他的领带扯松了，领口也敞着。"}},{"pos":"N-COUNT 可数名词","cn":"(狗或猫的)颈圈，项圈","en":"A collar is a band of leather or plastic which is put round the neck of a dog or cat."},{"pos":"VERB 动词","cn":"抓住;逮住;揪住","en":"If you collar someone who has done something wrong or who is running away, you catch them and hold them so that they cannot escape.","ex":{"en":"As Kerr fled towards the exit, Boycott collared him at the ticket barrier.","cn":"克尔往出口方向逃窜，博伊科特在验票口逮住了他。"}},{"pos":"VERB 动词","cn":"拦住（某人）与其谈话","en":"If you collar someone, you stop them and make them listen to you.","ex":{"en":"Beattie managed to collar Atkins in a hallway","cn":"贝蒂设法在走廊里拦住了阿特金斯，和他谈了几句话。"}},{"pos":"PHRASE 短语","cn":"生气;愤怒;激动","en":"If someone gets hot under the collar about something, they get very annoyed, angry, or excited about it.","ex":{"en":"Some of you were getting very hot under the collar about Royals.","cn":"你们当中有些人对皇室成员非常恼火。"}}]},"examples":[{"en":"I was collared in the street by a woman doing a survey.","cn":"我在大街上给一个做民意调查的女人拦住问话。"},{"en":"Police collared the culprit as he was leaving the premises.","cn":"罪犯正离开现场时，警察逮住了他。"}]},"counter-espionage":{"oxford":{"phon":"ˌkaʊntər ˈespiənɑːʒ","pos":"noun","senses":[{"en":"secret action taken by a country to prevent an enemy country from finding out its secrets","cn":"反间谍活动"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同 counter-intelligence","en":"Counter-espionage is the same as counter-intel-ligence ."}]},"media":{"uk":"media/uk/counter_espionage_1_gb_1.mp3","us":"media/us/counter_espionage_1_us_1.mp3"}},"countenance":{"media":{"uk":"media/uk/countenance__gb_1.mp3","us":"media/us/countenance__us_1.mp3"},"oxford":{"phon":"ˈkaʊntənəns","pos":"noun","senses":[{"en":"a person’s face or their expression","cn":"面容；脸色；面部表情","ex":{"en":"her calmly smiling countenance","cn":"她平静微笑的面容"}},{"en":"to support something or agree to something happening","cn":"支持；赞成；同意","ex":{"en":"The committee refused to countenance his proposals.","cn":"委员会拒不同意他的方案。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"支持;赞同;同意","en":"If someone will not countenance something, they do not agree with it and will not allow it to happen.","ex":{"en":"Jake would not countenance Janis's marrying while still a student.","cn":"杰克不会同意贾尼斯还在上学就结婚。"}},{"pos":"N-COUNT 可数名词","cn":"脸庞;面容","en":"Someone's countenance is their face.","ex":{"en":"He met each inquiry with an impassive countenance.","cn":"他面无表情地接受每一个盘问。"}}]},"examples":[{"en":"The committee refused to countenance his proposals.","cn":"委员会拒不同意他的方案。"},{"en":"All colour drained from her countenance.","cn":"她面无血色。"}]},"copyright":{"media":{"uk":"media/uk/copyright__gb_1.mp3","us":"media/us/copyright__us_1.mp3"},"oxford":{"phon":"ˈkɒpiraɪt","pos":"noun","senses":[{"en":"if a person or an organization holds the copyright on a piece of writing, music, etc., they are the only people who have the legal right to publish, broadcast, perform it, etc., and other people must ask their permission to use it or any part of it","cn":"版权；著作权","ex":{"en":"Copyright expires seventy years after the death of the author.","cn":"版权在作者去世七十年后期满无效。"}},{"en":"protected by copyright; not allowed to be copied without permission","cn":"受版权保护的；未经准许不得复制的","ex":{"en":"copyright material","cn":"版权资料"},"pos":"adjective"},{"en":"to get the copyright for something","cn":"获得…的版权","pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"版权;著作权","en":"If someone has copyright on a piece of writing or music, it is illegal to reproduce or perform it without their permission.","ex":{"en":"To order a book one first had to get permission from the monastery that held the copyright","cn":"要想订购书，必须先得到持有该书版权的修道院的许可。"}}]},"examples":[{"en":"Copyright expires seventy years after the death of the author.","cn":"版权在作者去世七十年后期满无效。"},{"en":"Who owns the copyright on this song?","cn":"谁拥有这首歌曲的版权？"}]},"come":{"media":{"uk":"media/uk/come__gb_1.mp3","us":"media/us/come__us_1.mp3"},"oxford":{"phon":"kʌm","pos":"verb","senses":[{"en":"to move to or towards a person or place","cn":"来","g":"[intransitive]","lab":"North American English","sc":"to a place","ex":{"en":"He left and said he was never coming back.","cn":"他走了，并且说再也不回来了。"}},{"en":"to arrive at or reach a place","cn":"来到；到达，抵达（某地）","g":"[intransitive]","sc":"to a place","ex":{"en":"They continued until they came to a river.","cn":"他们继续往前一直来到河边。"}},{"en":"to arrive somewhere in order to do something or get something","cn":"来做；来取；来拿","g":"[intransitive]","sc":"to a place","ex":{"en":"I've come for my book.","cn":"我来拿我的书。"}},{"en":"to move or travel, especially with somebody else, to a particular place or in order to be present at an event","cn":"（尤指与某人）去（某处或出席某项活动）","g":"[intransitive]","sc":"to a place","ex":{"en":"I've only come for an hour.","cn":"我来了才一个小时。"}},{"en":"to travel a particular distance","cn":"走过，旅行过（一段路程）","g":"[intransitive]","lab":"figurative","sc":"travel","ex":{"en":"We've come 50 miles this morning.","cn":"我们今天上午走了 50 英里。"}},{"en":"to move in a particular way or while doing something else","cn":"（以某种方式）移动；边…边来","g":"[intransitive]","lab":"figurative","sc":"running/hurrying etc.","ex":{"en":"A car came flying round the corner.","cn":"一辆汽车从拐角处飞驰而来。"}},{"en":"to happen","cn":"发生","g":"[intransitive]","lab":"informal","sc":"happen","ex":{"en":"The agreement came after several hours of negotiations.","cn":"协议经过几小时的谈判后才达成。"}},{"en":"used in questions to talk about how or why something happened","cn":"（用于疑问句，表示怎么或为什么）","g":"[transitive]","sc":"happen","ex":{"en":"How did he come to break his leg?","cn":"他怎么把腿弄断的？"}},{"en":"to have a particular position","cn":"位于，处于（某位置）","g":"[intransitive]","sc":"to a position/state","ex":{"en":"That comes a long way down my list of priorities.","cn":"在我的优先事项中，那事远没那么紧要。"}},{"en":"used in many expressions to show that something has reached a particular state","cn":"（用于许多表达）达到，进入（某种状态）","g":"[intransitive]","sc":"to a position/state","ex":{"en":"At last winter came to an end.","cn":"冬天终于结束了。"}},{"en":"to be available or to exist in a particular way","cn":"可提供；有（货）","g":"[intransitive]","lab":"informal","sc":"to a position/state","ex":{"en":"This dress comes in black and red.","cn":"这款连衣裙有黑、红两种颜色。"}},{"en":"to become","cn":"成为；变成；变得","g":"[intransitive, transitive]","sc":"to a position/state","ex":{"en":"The handle came loose.","cn":"这把手松了。"}},{"en":"to reach a point where you realize, understand or believe something","cn":"达到（认识、理解或相信的程度）","g":"[transitive]","sc":"to a position/state","ex":{"en":"In time she came to love him.","cn":"她终于爱上了他。"}},{"en":"to have an orgasm","cn":"达到性高潮","g":"[intransitive]","lab":"informal","sc":"sex"},{"en":"when the time mentioned comes","cn":"（提及的时间）到来","ex":{"en":"They would have been married forty years come this June.","cn":"到今年六月他们结婚就有四十年了。"},"pos":"preposition"},{"en":"used when encouraging somebody to be sensible or reasonable, or when making a slight criticism","cn":"（劝某人理智、讲理，或表示略有不满）嗨，得啦，好啦","ex":{"en":"Oh come now, things aren't as bad as all that.","cn":"哦，好啦，情况并不是那么糟。"},"pos":"exclamation"},{"en":"semen","cn":"精液","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"来;来到","en":"When a person or thing comes to a particular place, especially to a place where you are, they move there.","ex":{"en":"Two police officers came into the hall","cn":"两位警官走进大厅。"}},{"pos":"VERB 动词","cn":"来(做某事)(除了用 come to do something 表达此意，英国英语中也用 come and do something，美国英语中也用 come do something，但表示过去动作时一定要用 came and did something)","en":"When someone comes to do something, they move to the place where someone else is in order to do it, and they do it. In British English, someone can also come and do something and in American English, someone can come do something. However, you always say that someone came and did something.","ex":{"en":"Eleanor had come to visit her","cn":"埃莉诺来看过她了。"}},{"pos":"VERB 动词","cn":"抵达;到达","en":"When you come to a place, you reach it.","ex":{"en":"He came to a door that led into a passageway.","cn":"他来到一扇门前，这扇门通往一条走廊。"}},{"pos":"VERB 动词","cn":"达到;至;及","en":"If something comes up to a particular point or down to it, it is tall enough, deep enough, or long enough to reach that point.","ex":{"en":"The water came up to my chest","cn":"水淹到了我的胸部。"}},{"pos":"VERB 动词","cn":"破裂;破碎;脱落;脱离","en":"If something comes apart or comes to pieces, it breaks into pieces. If something comes off or comes away, it becomes detached from something else.","ex":{"en":"The pistol came to pieces, easily and quickly","cn":"手枪很快就被拆得七零八落。"}},{"pos":"V-LINK 连系动词","cn":"达到，进入(某种状态或境地)","en":"You use come in expressions such as come to an end or come into operation to indicate that someone or something enters or reaches a particular state or situation.","ex":{"en":"The summer came to an end","cn":"夏天结束了。"}},{"pos":"VERB 动词","cn":"(经历漫长的过程或时间后)开始(做某事)","en":"If someone comes to do something, they do it at the end of a long process or period of time.","ex":{"en":"She said it so many times that she came to believe it","cn":"这件事她说了太多遍，以至自己都开始相信了。"}},{"pos":"VERB 动词","cn":"(如何)发生，出现","en":"You can ask how something came to happen when you want to know what caused it to happen or made it possible.","ex":{"en":"How did you come to meet him?","cn":"你是怎么碰到他的？"}},{"pos":"VERB 动词","cn":"(事件)发生;(时间)到来","en":"When a particular event or time comes, it arrives or happens.","ex":{"en":"The announcement came after a meeting at the Home Office","cn":"内政部会议结束后，声明随即发表。"}},{"pos":"PREP 介词","cn":"(用于日期、时间或事件之前)当…到来时","en":"You can use come before a date, time, or event to mean when that date, time, or event arrives. For example, you can say come the spring to mean 'when the spring arrives'.","ex":{"en":"Come the election on the 20th of May, we will have to decide","cn":"到5月20日选举的那一天，我们必须作出决定。"}},{"pos":"VERB 动词","cn":"突然被…意识到;突然被…想起","en":"If a thought, idea, or memory comes to you, you suddenly think of it or remember it.","ex":{"en":"He was about to shut the door when an idea came to him","cn":"他正准备关门，突然想到一个主意。"}},{"pos":"VERB 动词","cn":"由…继承;归…所有","en":"If money or property is going to come to you, you are going to inherit or receive it.","ex":{"en":"The fortune will come to you","cn":"这一大笔钱将归你所有。"}},{"pos":"VERB 动词","cn":"(案件)提交…审理，送交…进行处理","en":"If a case comes before a court or tribunal or comes to court, it is presented there so that the court or tribunal can examine it.","ex":{"en":"The membership application came before the Council of Ministers in September","cn":"会员申请书于9月提交部长会议审议。"}},{"pos":"VERB 动词","cn":"总共;共计","en":"If something comes to a particular number or amount, it adds up to it.","ex":{"en":"Lunch came to $80.","cn":"午餐总共80美元。"}},{"pos":"VERB 动词","cn":"来自;始于","en":"If someone or something comes from a particular place or thing, that place or thing is their origin, source, or starting point.","ex":{"en":"Nearly half the students come from abroad","cn":"将近一半的学生来自国外。"}},{"pos":"VERB 动词","cn":"由…引起;是…的结果","en":"Something that comes from something else or comes of it is the result of it.","ex":{"en":"There is a feeling of power that comes from driving fast","cn":"开快车会让人觉得自己有一种主宰之力。"}},{"pos":"VERB 动词","cn":"出身于;来自","en":"If someone comes of a particular family or type of family, they are descended from them.","ex":{"en":"She comes of a very good family.","cn":"她的家庭出身非常好。"}},{"pos":"VERB 动词","cn":"(表示顺序或名次)处于，位列","en":"If someone or something comes first, next, or last, they are first, next, or last in a series, list, or competition.","ex":{"en":"The two countries have been unable to agree which step should come next","cn":"接下来该走哪一步，这两个国家还未能就此达成一致意见。"}},{"pos":"VERB 动词","cn":"有，可提供(某种颜色、形状、款式或尺寸)","en":"If a type of thing comes in a particular range of colours, forms, styles, or sizes, it can have any of those colours, forms, styles, or sizes.","ex":{"en":"Bikes come in all shapes and sizes","cn":"各种外形和尺寸的自行车都有。"}},{"pos":"VERB 动词","cn":"(用于表示对某事的反应)让人…","en":"You use come in expressions such as it came as a surprise when indicating a person's reaction to something that happens.","ex":{"en":"Major's reply came as a complete surprise to the House of Commons","cn":"梅杰的回答让众议院大吃一惊。"}},{"pos":"VERB 动词","cn":"谈论;谈到","en":"The next subject in a discussion that you come to is the one that you talk about next.","ex":{"en":"Finally in the programme, we come to the news that the American composer and conductor, Leonard Bernstein, has died","cn":"节目的最后，我们来看一则新闻，美国作曲家兼指挥家伦纳德·伯恩斯坦去世。"}},{"pos":"CONVENTION 惯用语","cn":"(用以鼓励或安慰)好了，得啦","en":"People say 'Come' to encourage or comfort someone.","ex":{"en":"'Come, eat!' the old woman urged.","cn":"“好了，吃吧！”老太太催促道。"}},{"pos":"VERB 动词","cn":"达到性高潮","en":"To come means to have an orgasm."},{"pos":"CONVENTION 惯用语","cn":"再说一遍？你说什么来着？","en":"Some people say 'Come again?' when they want you to repeat what you have just said."},{"pos":"PHRASE 短语","cn":"极…的;非常…的","en":"If you say that someone is, for example, as good as they come, or as stupid as they come, you are emphasizing that they are extremely good or extremely stupid.","ex":{"en":"The new finance minister was educated at Oxford and is as traditional as they come.","cn":"新财政部长曾就读于牛津大学，是个极为传统的人。"}},{"pos":"CONVENTION 惯用语","cn":"(表示不赞成或不同意)哦，不，别这样","en":"People say 'Come, come' to indicate that they disapprove of or disagree with what someone has just said or done.","ex":{"en":"'You hope for something in Mrs Zuckerman's will?' — 'Come, come, Mr Trethowan. Of course not.'","cn":"“你希望朱克曼太太在遗嘱里给你留点什么？”“哦，不，特里索恩先生。当然不是。”"}},{"pos":"PHRASE 短语","cn":"归结为;归根结底","en":"You can use the expression when it comes down to it or when you come down to it for emphasis, when you are giving a general statement or conclusion.","ex":{"en":"When you come down to it, however, the basic problems of life have not changed","cn":"然而，归根结底，生活中一些基本的问题还是没有变。"}},{"pos":"PHRASE 短语","cn":"自作自受;活该","en":"If you say that someone has it coming to them, you mean that they deserve everything bad that is going to happen to them, because they have done something wrong or are a bad person. If you say that someone got what was coming to them, you mean that they deserved the punishment or bad experience that they have had.","ex":{"en":"He was pleased that Brady was dead because he probably had it coming to him.","cn":"他很高兴布雷迪死了，因为他可能纯粹是自找的。"}},{"pos":"PHRASE 短语","cn":"突然想起来;突然明白过来","en":"You use the expression come to think of it to indicate that you have suddenly realized something, often something obvious.","ex":{"en":"He was his distant relative, as was everyone else on the island, come to think of it","cn":"哦，对了，他是他的远亲，岛上的其他人也是。"}},{"pos":"PHRASE 短语","cn":"(时间或事件)未来的，接下来的","en":"When you refer to a time or an event to come or one that is still to come, you are referring to a future time or event.","ex":{"en":"The War will remain a heated topic of debate for some time to come","cn":"这场战争在未来的一段时间内仍将是人们热议的话题。"}},{"pos":"PHRASE 短语","cn":"谈到;涉及","en":"You can use the expression when it comes to or when it comes down to in order to introduce a new topic or a new aspect of a topic that you are talking about.","ex":{"en":"Most of us know we should cut down on fat. But knowing such things isn't much help when it comes to shopping and eating","cn":"我们大多数人都知道应该减少脂肪的摄入量。但是在购物和吃东西的时候，这些常识就丢到一边去了。"}},{"pos":"PHRASE 短语","cn":"我明白你的意思/你可以看出她的态度","en":"You can use expressions like I know where you're coming from or you can see where she's coming from to say that you understand someone's attitude or point of view.","ex":{"en":"To understand why they are doing it, it is necessary to know where they are coming from","cn":"要弄清楚他们这样做的原因，必须要了解他们的意图。"}},{"pos":"","cn":"","en":"相关词组：come about come across come along come around come at come back come back to come between come by come down come down on come down to come down with come for come forward come in come in for come into come off come on come on to come out come out in come out with come over come round come through come to come under come up come up against come up for come upon come up to come up with"}]},"examples":[{"en":"‘She's an entomologist.’ ‘Come again?’ ‘An entomologist — she studies insects.’ “","cn":"她是昆虫学家。” “请再说一遍？” “昆虫学家 — 她是研究昆虫的。”"},{"en":"( figurative ) United came back from being two goals down to win 3–2.","cn":"联队在先失两球的情况下将比分扳回，最终以 3:2 取胜。"}]},"continuity":{"media":{"uk":"media/uk/xcontinuity__gb_1.mp3","us":"media/us/xcontinuity__us_1.mp3"},"oxford":{"phon":"ˌkɒntɪˈnjuːəti","pos":"noun","senses":[{"en":"the fact of not stopping or not changing","cn":"连续性；持续性","g":"[uncountable]","ex":{"en":"to ensure/provide/maintain continuity of fuel supplies","cn":"确保／提供／保持燃料供给的连续性"}},{"en":"a logical connection between the parts of something, or between two things","cn":"（逻辑上的）连接，联结","g":"[uncountable, countable]","ex":{"en":"The novel fails to achieve narrative continuity.","cn":"这部小说叙述不连贯。"}},{"en":"the organization of a film or television programme, especially making sure that people’s clothes, objects, etc. are the same from one scene to the next","cn":"（电影或电视节目前后场景中服装、物品等的）一致性，衔接","g":"[uncountable]","lab":"specialist"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"连续性;连贯性","en":"Continuity is the fact that something continues to happen or exist, with no great changes or interruptions.","ex":{"en":"A historical awareness also imparts a sense of continuity.","cn":"历史意识也显示了一种连贯性。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(电影)剪辑","en":"In film making, continuity is the way that things filmed at different times are made to look as if they were filmed at the same time or in the right sequence.","ex":{"en":"Walt and I referred to a video cassette of the original footage to check continuity and lighting.","cn":"我和沃尔特参照着一盘原始电影胶片录像带来检查镜头的剪辑和灯光。"}}]},"examples":[{"en":"There are obvious continuities between diet and health.","cn":"日常饮食与健康之间有着明显的逻辑关联。"},{"en":"to ensure/provide/maintain continuity of fuel supplies","cn":"确保/提供/保持燃料供给的连续性"}]},"consultant":{"media":{"uk":"media/uk/xconsultant__gb_1.mp3","us":"media/us/xconsultant__us_1.mp3"},"oxford":{"phon":"kənˈsʌltənt","pos":"noun","senses":[{"en":"a person who knows a lot about a particular subject and is employed to give advice about it to other people","cn":"顾问","ex":{"en":"a technology/design consultant","cn":"技术／设计顾问"}},{"en":"a hospital doctor of the highest rank who is a specialist in a particular area of medicine","cn":"高级顾问医师；会诊医师","lab":"British English","ex":{"en":"a consultant in obstetrics","cn":"产科顾问医师"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"高级顾问医师;会诊医师","en":"A consultant is an experienced doctor with a high position, who specializes in one area of medicine.","ex":{"en":"Shirley's brother is now a consultant heart surgeon in Sweden.","cn":"雪利的兄弟现在在瑞典做心脏外科高级顾问医师。"}},{"pos":"N-COUNT 可数名词","cn":"顾问","en":"A consultant is a person who gives expert advice to a person or organization on a particular subject.","ex":{"en":"He was a consultant to the Swedish government.","cn":"他是瑞典政府顾问。"}}]},"examples":[{"en":"the President's consultant on economic affairs","cn":"总统的经济事务顾问"},{"en":"a firm of management consultants","cn":"管理咨询公司"}]},"coastal":{"media":{"uk":"media/uk/coastal__gb_1.mp3","us":"media/us/coastal__us_1.mp3"},"oxford":{"phon":"ˈkəʊstl","pos":"adjective","senses":[{"en":"of or near a coast","cn":"沿海的；靠近海岸的","ex":{"en":"coastal waters/resorts/scenery","cn":"沿海水域；海滨胜地／风景"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"近海的;沿海的","en":"Coastal is used to refer to things that are in the sea or on the land near a coast.","ex":{"en":"Local radio stations serving coastal areas often broadcast forecasts for yachtsmen","cn":"服务沿海地区的地方广播电台经常为驾驶游艇出海的人播报天气预报。"}}]},"examples":[{"en":"a coastal path (= one that follows the line of the coast)","cn":"滨海小道"},{"en":"coastal waters/resorts/scenery","cn":"沿海水域；海滨胜地/风景"}]},"contrasting":{"media":{"uk":"media/uk/xcontrasting__gb_1.mp3","us":"media/us/xcontrasting__us_1.mp3"},"oxford":{"phon":"kənˈtrɑːstɪŋ","pos":"adjective","senses":[{"en":"very different in style, colour or attitude","cn":"（在式样、颜色或态度上）极不相同的，差异大的","ex":{"en":"bright, contrasting colours","cn":"鲜艳斑斓的色彩"}}]},"examples":[{"en":"The book explores contrasting views of the poet's early work.","cn":"此书探讨了人们对这位诗人早期作品截然不同的观点。"},{"en":"bright, contrasting colours","cn":"鲜艳斑斓的色彩"}],"base":"contrast"},"cools":{"lemma":"cool","media":{"uk":"media/uk/cool__gb_1.mp3","us":"media/us/cool__us_1.mp3"}},"compete":{"media":{"uk":"media/uk/compete__gb_1.mp3","us":"media/us/compete__us_1.mp3"},"oxford":{"phon":"kəmˈpiːt","pos":"verb","senses":[{"en":"to take part in a contest or game","cn":"参加比赛（或竞赛）","g":"[intransitive]","ex":{"en":"The games were an outstanding success, with almost 2 400 athletes competing.","cn":"比赛取得了巨大成功，有近 2400 名运动员参赛。"}},{"en":"to try to be more successful or better than somebody else who is trying to do the same as you","cn":"竞争；对抗","g":"[intransitive]","ex":{"en":"They simply cannot compete in the international market.","cn":"他们根本没有能力在国际市场上竞争。"}}]},"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"竞争","en":"When one firm or country competes with another, it tries to get people to buy its own goods in preference to those of the other firm or country. You can also say that two firms or countries compete .","ex":{"en":"The banks have long competed with American Express's charge cards and various store cards","cn":"长久以来，这些银行一直在与美国运通公司的信用卡以及各式各样的商场赊购卡竞争。"}},{"pos":"V-RECIP 相互动词","cn":"（与…）争夺（以获取）","en":"If you compete with someone for something, you try to get it for yourself and stop the other person getting it. You can also say that two people compete for something.","ex":{"en":"Kangaroos compete with sheep and cattle for sparse supplies of food and water","cn":"袋鼠与牛羊争夺稀少的食物和水。"}},{"pos":"VERB 动词","cn":"参加(比赛)","en":"If you compete in a contest or a game, you take part in it.","ex":{"en":"He will be competing in the London-Calais-London race","cn":"他将参加伦敦至加来的航海往返赛。"}}]},"examples":[{"en":"Small traders cannot compete in the face of cheap foreign imports.","cn":"面对廉价的外国进口商品，经营规模小的商人无法与之抗衡。"},{"en":"Several companies are competing for the contract.","cn":"为得到那项合同，几家公司正在竞争。"}]},"contradiction":{"oxford":{"phon":"ˌkɒntrəˈdɪkʃn","pos":"noun","senses":[{"en":"a lack of agreement between facts, opinions, actions, etc.","cn":"（事实、看法、行动等的）不一致，矛盾，对立","g":"[countable, uncountable]","ex":{"en":"There is a contradiction between the two sets of figures.","cn":"这两组数据相互矛盾。"}},{"en":"the act of saying that something that somebody else has said is wrong or not true; an example of this","cn":"反驳；驳斥","g":"[uncountable, countable]","ex":{"en":"I think I can say, without fear of contradiction, that…","cn":"就算有人反驳，我也敢说…"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"矛盾;不一致","en":"If you describe an aspect of a situation as a contradiction, you mean that it is completely different from other aspects, and so makes the situation confused or difficult to understand.","ex":{"en":"...the contradictions between her private life and the public persona","cn":"她的私生活与公众形象之间的巨大反差"}},{"pos":"PHRASE 短语","cn":"自相矛盾的说法","en":"If you say that something is a contradiction in terms, you mean that it is described as having a quality that it cannot have.","ex":{"en":"A public service run for profit — a contradiction in terms if there ever was one.","cn":"以营利为目的的公共服务机构——这是典型的用词上的自相矛盾（如果真有这种说法的话）。"}}]},"media":{"uk":"media/uk/xcontradiction__gb_1.mp3","us":"media/us/xcontradiction__us_1.mp3"},"examples":[{"en":"Now you say you both left at ten — that's a contradiction of your last statement.","cn":"你现在说你们俩是十点钟离开的，这可和你上次的说法不一致。"},{"en":"His public speeches are in direct contradiction to his personal lifestyle.","cn":"他的公开言论与他本人的生活方式恰恰相反。"}]},"considerable":{"media":{"uk":"media/uk/xconsiderable__gb_1.mp3","us":"media/us/xconsiderable__us_1.mp3"},"oxford":{"phon":"kənˈsɪdərəbl","pos":"adjective","senses":[{"en":"great in amount, size, importance, etc.","cn":"相当多（或大、重要等）的","ex":{"en":"The project wasted a considerable amount of time and money.","cn":"那项工程耗费了相当多的时间和资金。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"相当多的;相当大的","en":"Considerable means great in amount or degree.","ex":{"en":"To be without Pearce would be a considerable blow","cn":"失去皮尔斯将是一个巨大的打击。"}}]},"examples":[{"en":"The project wasted a considerable amount of time and money.","cn":"那项工程耗费了相当多的时间和资金。"},{"en":"Damage to the building was considerable.","cn":"对这栋建筑物的损坏相当严重。"}]},"commercial":{"media":{"uk":"media/uk/commercial__gb_1.mp3","us":"media/us/commercial__us_1.mp3"},"oxford":{"phon":"kəˈmɜːʃl","pos":"adjective","senses":[{"en":"connected with the buying and selling of goods and services","cn":"贸易的；商业的","g":"[usually before noun]","lab":"especially North American English","ex":{"en":"residential and commercial properties","cn":"住宅和商业地产"}},{"en":"making or intended to make a profit","cn":"赢利的；以获利为目的的","g":"[only before noun]","ex":{"en":"The movie was not a commercial success (= did not make money).","cn":"这部电影票房收入不佳。"}},{"en":"more interested in profit and being popular than in quality","cn":"商业化的；热衷于名利的","lab":"disapproving","ex":{"en":"Their more recent music is far too commercial.","cn":"他们最近的音乐过分商业化了。"}},{"en":"paid for by the money charged for broadcasting advertisements","cn":"由广告收入支付的；商业性的","ex":{"en":"a commercial radio station/TV channel","cn":"商业电台／电视频道"}},{"en":"an advertisement on television, on the radio or on a website","cn":"（电视、电台或网站上播放的）广告","lab":"especially British English","ex":{"en":"a TV/television commercial","cn":"电视广告片"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"商业的;贸易的","en":"Commercial means involving or relating to the buying and selling of goods.","ex":{"en":"Docklands in its heyday was a major centre of industrial and commercial activity","cn":"港区在其最繁荣的时期曾是主要的工商业活动中心。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(组织、活动)营利的，商业化的，偏重利润的","en":"Commercial organizations and activities are concerned with making money or profits, rather than, for example, with scientific research or providing a public service.","ex":{"en":"British Rail has indeed become more commercial over the past decade","cn":"过去10年来，英国铁路确实变得更加商业化了。"}},{"pos":"ADJ 形容词","cn":"(产品)商品化的，供市场出售的","en":"A commercial product is made to be sold to the public.","ex":{"en":"They are the leading manufacturer in both defence and commercial products.","cn":"在军工产品和民用产品的制造方面，他们都处于领先地位。"}},{"pos":"ADJ 形容词","cn":"(车辆)商用的","en":"A commercial vehicle is a vehicle used for carrying goods, or passengers who pay.","ex":{"en":"Commercial vehicles, coaches and lorries are required by law to be fitted with tachographs.","cn":"法律规定商用车辆、长途汽车和卡车要安装转速计。"}},{"pos":"ADJ 形容词","cn":"(电视、广播)靠广告收入维持的，商业性的","en":"Commercial television and radio are paid for by the broadcasting of advertisements, rather than by the government.","ex":{"en":"...Classic FM, the first national commercial radio station.","cn":"国内首家商业广播电台——经典调频"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(电影或音乐)商业化的，迎合大众口味的","en":"Commercial is used to describe something such as a film or a type of music that it is intended to be popular with the public, and is not very original or of high quality.","ex":{"en":"There's a feeling among a lot of people that music has become too commercial.","cn":"很多人都觉得音乐变得过于商业化了。"}},{"pos":"N-COUNT 可数名词","cn":"(电视或电台的)商业广告","en":"A commercial is an advertisement that is broadcast on television or radio.","ex":{"en":"The government has launched a campaign of television commercials and leaflets.","cn":"政府通过电视广告和传单的形式发起了宣传活动。"}}]},"examples":[{"en":"His invention was not commercially successful.","cn":"他的发明从营利角度看并不成功。"},{"en":"Their more recent music is far too commercial.","cn":"他们最近的音乐过分商业化了。"}]},"contentment":{"media":{"uk":"media/uk/xcontentment__gb_1.mp3","us":"media/us/xcontentment__us_1.mp3"},"oxford":{"phon":"kənˈtentmənt","pos":"noun","senses":[{"en":"a feeling of being happy or satisfied","cn":"满意；满足","ex":{"en":"He has found contentment at last.","cn":"他最终得到了满足。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"满意;满足","en":"Contentment is a feeling of quiet happiness and satisfaction.","ex":{"en":"I cannot describe the feeling of contentment that was with me at that time.","cn":"我无法描述当时我满足的感觉。"}}]},"examples":[{"en":"He has found contentment at last.","cn":"他最终得到了满足。"},{"en":"a sigh of contentment","cn":"满足地舒一口气"}]},"conscious":{"media":{"uk":"media/uk/xconscious__gb_1.mp3","us":"media/us/xconscious__us_1.mp3"},"oxford":{"phon":"ˈkɒnʃəs","pos":"adjective","senses":[{"en":"aware of something; noticing something","cn":"意识到；注意到","g":"[not before noun]","ex":{"en":"She's very conscious of the problems involved.","cn":"她完全意识到了所涉及的问题。"}},{"en":"able to use your senses and mental powers to understand what is happening","cn":"神志清醒的；有知觉的；有意识的","ex":{"en":"A patient who is not fully conscious should never be left alone.","cn":"神志并非完全清醒的病人必须时刻有人照料。"}},{"en":"deliberate; done in a careful way","cn":"有意的；慎重的","ex":{"en":"a conscious choice","cn":"有意识的选择"}},{"en":"being particularly interested in something","cn":"特别感兴趣的；关注的","ex":{"en":"to be environmentally/politically conscious","cn":"具有环保/政治意识"}},{"en":"directly under the control of the person concerned","cn":"受控制的；受约束的","ex":{"en":"When you go to sleep, it is only the conscious mind that shuts down.","cn":"人睡觉时，停止活动的仅仅是能感知到的意识。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"注意到的;意识到的","en":"If you are conscious of something, you notice it or realize that it is happening.","ex":{"en":"He was conscious of the faint, musky aroma of after-shave","cn":"他注意到了须后水淡淡的麝香味。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(尤指由于不满或自觉重要而)注意的，关注的","en":"If you are conscious of something, you think about it a lot, especially because you are unhappy about it or because you think it is important.","ex":{"en":"I'm very conscious of my weight","cn":"我很在意自己的体重。"}},{"pos":"ADJ 形容词","cn":"(决定、行动等)有意的，刻意的","en":"A conscious decision or action is made or done deliberately with you giving your full attention to it.","ex":{"en":"I don't think we ever made a conscious decision to have a big family","cn":"我觉得我们没有刻意地决定要生很多孩子。"}},{"pos":"ADJ 形容词","cn":"清醒的;有知觉的","en":"Someone who is conscious is awake rather than asleep or unconscious.","ex":{"en":"She was fully conscious all the time and knew what was going on.","cn":"她一直都很清醒，知道是怎么回事。"}},{"pos":"ADJ 形容词","cn":"(记忆或想法)有意识的，意识到的","en":"Conscious memories or thoughts are ones that you are aware of.","ex":{"en":"He had no conscious memory of his four-week stay in hospital","cn":"他对自己住院的4个星期没有任何有意识的记忆。"}}]},"examples":[{"en":"A patient who is not fully conscious should never be left alone.","cn":"神志并非完全清醒的病人必须时刻有人照料。"},{"en":"Consciously or unconsciously, you made a choice.","cn":"不管是有意还是无意，你已作出了选择。"}]},"comfortable":{"media":{"uk":"media/uk/comfortable__gb_1.mp3","us":"media/us/comfortable__us_1.mp3"},"oxford":{"phon":"ˈkʌmftəbl","pos":"adjective","senses":[{"en":"making you feel physically relaxed; pleasant to wear, sit on, etc.","cn":"使人舒服的；舒适的","sc":"clothes/furniture","ex":{"en":"It's such a comfortable bed.","cn":"这床真舒服。"}},{"en":"feeling physically relaxed in a pleasant way; warm enough, without pain, etc.","cn":"愉快放松的；舒服的；安逸的","sc":"physically relaxed","ex":{"en":"Are you comfortable?","cn":"你感觉舒服吗？"}},{"en":"confident about something and not worried or afraid","cn":"自信而无惧的；自在的","sc":"confident","ex":{"en":"She was clearly quite comfortable and relaxed.","cn":"她显然感到非常舒服和放松。"}},{"en":"having enough money to buy what you want without worrying about the cost","cn":"富裕的；宽裕的","sc":"having money","ex":{"en":"They're not millionaires, but they're certainly very comfortable.","cn":"他们不是百万富翁，但也很富足。"}},{"en":"quite large; allowing you to win easily","cn":"相当大的；轻松取胜的","sc":"victory","ex":{"en":"The party won with a comfortable majority.","cn":"该政党以明显的多数票获胜。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(家具、衣服等)让人舒服的，舒适的","en":"If a piece of furniture or an item of clothing is comfortable, it makes you feel physically relaxed when you use it, for example because it is soft.","ex":{"en":"...a comfortable fireside chair","cn":"舒适的炉边座椅"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(建筑物或房间)令人放松的，安逸的，舒适的","en":"If a building or room is comfortable, it makes you feel physically relaxed when you spend time in it, for example because it is warm and has nice furniture.","ex":{"en":"A home should be comfortable and friendly.","cn":"家应该让人觉得舒服、亲切。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)愉快放松的，舒服的","en":"If you are comfortable, you are physically relaxed because of the place or position you are sitting or lying in.","ex":{"en":"Lie down on your bed and make yourself comfortable","cn":"躺在床上，身体放松。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"宽裕的;小康的","en":"If you say that someone is comfortable, you mean that they have enough money to be able to live without financial problems.","ex":{"en":"'Is he rich?' — 'He's comfortable.'","cn":"“他很有钱吗？”“他生活挺宽裕的。”"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"轻松领先的;易获胜的","en":"In a race, competition, or election, if you have a comfortable lead, you are likely to win it easily. If you gain a comfortable victory or majority, you win easily.","ex":{"en":"By half distance we held a comfortable two-lap lead","cn":"到半程时，我们轻松领先两圈。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自信的;放心的;自在的","en":"If you feel comfortable with a particular situation or person, you feel confident and relaxed with them.","ex":{"en":"Nervous politicians might well feel more comfortable with a step-by-step approach","cn":"神经脆弱的政治家们似乎更容易接受一种循序渐进的做法。"}},{"pos":"ADJ 形容词","cn":"(病人或受伤者)情况稳定的，状况良好的","en":"When a sick or injured person is said to be comfortable, they are in a stable physical condition.","ex":{"en":"He was described as comfortable in hospital last night.","cn":"据说昨晚他在医院状况良好。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(生活、工作或所处的环境)轻松的，无忧无虑的","en":"A comfortable life, job, or situation does not cause you any problems or worries.","ex":{"en":"...a comfortable teaching job at a university","cn":"在大学教书的轻松工作"}}]},"examples":[{"en":"He's more comfortable with computers than with people.","cn":"比起与人相处，他和电脑打交道更能应付自如。"},{"en":"She shifted into a more comfortable position on the chair.","cn":"她换了一个更舒适的姿势坐在椅子上。"}]},"coincidentally":{"media":{"uk":"media/uk/coincidentally__gb_1.mp3","us":"media/us/coincidentally__us_1.mp3"},"collins":{"senses":[{"pos":"ADV 副词","cn":"巧得很;凑巧","en":"You use coincidentally when you want to draw attention to a coincidence.","ex":{"en":"Coincidentally, I had once found myself in a similar situation","cn":"巧得很，我曾经碰到过类似的情况。"}}]},"examples":[{"en":"Coincidentally, they had both studied in Paris.","cn":"碰巧的是，他们俩都在巴黎学习过。"}],"oxford":{"phon":"kəʊˌɪnsɪˈdentəli","pos":"adverb","senses":[{"en":"in a way that is not planned, but happens by chance","cn":"巧合地；碰巧地","ex":{"en":"Coincidentally, they had both studied in Paris.","cn":"碰巧的是，他们俩都在巴黎学习过。"}}]}},"constant":{"media":{"uk":"media/uk/xconstant__gb_1.mp3","us":"media/us/xconstant__us_1.mp3"},"oxford":{"phon":"ˈkɒnstənt","pos":"adjective","senses":[{"en":"happening all the time or repeatedly","cn":"连续发生的；不断的；重复的","g":"[usually before noun]","ex":{"en":"There were constant interruptions.","cn":"干扰不断。"}},{"en":"that does not change","cn":"不变的；固定的；恒定的","ex":{"en":"The car was travelling at a constant speed of 50 mph.","cn":"汽车以每小时 50 英里的恒定速度行驶。"}},{"en":"a number or quantity that does not vary","cn":"常数；常量","ex":{"en":"fundamental physical constants","cn":"基本物理常数"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"持续不断的;重复的;一直存在的","en":"You use constant to describe something that happens all the time or is always there.","ex":{"en":"She suggests that women are under constant pressure to be abnormally thin","cn":"她暗示说女性总是处在保持身材异常瘦削的压力之下。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"恒定的;不变的","en":"If an amount or level is constant, it stays the same over a particular period of time.","ex":{"en":"The average speed of the winds remained constant.","cn":"平均风速保持稳定。"}},{"pos":"N-COUNT 可数名词","cn":"恒定物;常数；常量；常项","en":"A constant is a thing or value that always stays the same.","ex":{"en":"In the world of fashion it sometimes seems that the only constant is ceaseless change","cn":"在时装界，有时似乎唯一永恒不变的东西就是不断的变化。"}}]},"examples":[{"en":"travelling at a constant speed of 50 m.p.h.","cn":"以每小时 50 英里的恒定速度行驶"},{"en":"Babies need constant attention.","cn":"婴儿一刻也离不开人。"}]},"cost":{"media":{"uk":"media/uk/cost__gb_1.mp3","us":"media/us/cost__us_1.mp3"},"oxford":{"phon":"kɒst","pos":"noun","senses":[{"en":"the amount of money that you need in order to buy, make or do something","cn":"费用；花费；价钱","g":"[countable, uncountable]","ex":{"en":"the high/low cost of housing","cn":"住宅的高昂／低廉费用"}},{"en":"the total amount of money that needs to be spent by a business","cn":"成本","g":"[plural]","lab":"North American English","ex":{"en":"The use of cheap labour helped to keep costs down.","cn":"使用廉价劳动力有助于降低成本。"}},{"en":"the effort, loss or damage that is involved in order to do or achieve something","cn":"（为做某事涉及的）努力，代价，损失","g":"[uncountable, singular]","ex":{"en":"the terrible cost of the war in death and suffering","cn":"这场战争造成的死亡与苦难的惨重代价"}},{"en":"the sum of money that somebody is ordered to pay for lawyers, etc. in a legal case","cn":"诉讼费用","g":"[plural]","ex":{"en":"He was ordered to pay £2 000 costs.","cn":"他被责令缴纳 2 000 英镑诉讼费。"}},{"en":"if something costs a particular amount of money, you need to pay that amount in order to buy, make or do it","cn":"需付费；价钱为","ex":{"en":"How much did it cost?","cn":"这东西要多少钱？"},"pos":"verb"},{"en":"to cause the loss of something","cn":"使丧失；使损失","ex":{"en":"That one mistake almost cost him his life.","cn":"那一个差错几乎使他丧命。"},"pos":"verb"},{"en":"to involve you in making an effort or doing something unpleasant","cn":"使付出努力；使做不愉快的事","ex":{"en":"The accident cost me a visit to the doctor.","cn":"那事故害得我去看了一趟医生。"},"pos":"verb"},{"en":"to estimate how much money will be needed for something or the price that should be charged for something","cn":"估算成本；估价","ex":{"en":"The project needs to be costed in detail.","cn":"这项工程需要作详细的成本估算。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"费用;花费;价钱","en":"The cost of something is the amount of money that is needed in order to buy, do, or make it.","ex":{"en":"The cost of a loaf of bread has increased five-fold","cn":"一条面包的价钱增长了4倍。"}},{"pos":"VERB 动词","cn":"需付费;价钱为","en":"If something costs a particular amount of money, you can buy, do, or make it for that amount.","ex":{"en":"This course is limited to 12 people and costs £50","cn":"该课程只招收12人，学费为50英镑。"}},{"pos":"N-PLURAL 复数名词","cn":"成本","en":"Your costs are the total amount of money that you must spend on running your home or business.","ex":{"en":"Costs have been cut by 30 to 50 per cent","cn":"成本降低了30%到50%。"}},{"pos":"VERB 动词","cn":"估算成本;估价","en":"When something that you plan to do or make is costed, the amount of money you need is calculated in advance.","ex":{"en":"Everything that goes into making a programme, staff, rent, lighting, is now costed.","cn":"制作节目的所有成本：人工、租用场地、灯光现在都已经估算了。"}},{"pos":"N-PLURAL 复数名词","cn":"诉讼费用","en":"If someone is ordered by a court of law to pay costs, they have to pay a sum of money towards the expenses of a court case they are involved in.","ex":{"en":"He was jailed for 18 months and ordered to pay £550 costs.","cn":"他被监禁了18个月，还责令他支付550英镑的诉讼费。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"成本价","en":"If something is sold at cost, it is sold for the same price as it cost the seller to buy it.","ex":{"en":"...a store that provided cigarettes and candy bars at cost.","cn":"按成本价出售香烟和糖果的商店"}},{"pos":"N-SING 单数名词","cn":"代价;损失","en":"The cost of something is the loss, damage, or injury that is involved in trying to achieve it.","ex":{"en":"In March Mr Salinas shut down the city's oil refinery at a cost of $500 million and 5,000 jobs.","cn":"3月份，萨利纳斯先生关闭了该市的炼油场，造成5亿美元的损失，并使5,000人失去了工作。"}},{"pos":"VERB 动词","cn":"使丧失;使损失","en":"If an event or mistake costs you something, you lose that thing as the result of it.","ex":{"en":"...a six-year-old boy whose life was saved by an operation that cost him his sight","cn":"手术救了一名6岁男孩的命，却使他失明了"}},{"pos":"PHRASE 短语","cn":"不惜任何代价","en":"If you say that something must be avoided at all costs, you are emphasizing that it must not be allowed to happen under any circumstances.","ex":{"en":"They told Jacques Delors a disastrous world trade war must be avoided at all costs.","cn":"他们告诉雅克·德洛尔必须不惜任何代价避免一场毁灭性的世界贸易战。"}},{"pos":"PHRASE 短语","cn":"无论如何;在任何代价下","en":"If you say that something must be done at any cost, you are emphasizing that it must be done, even if this requires a lot of effort or money.","ex":{"en":"This book is of such importance that it must be published at any cost","cn":"这本书非常重要，无论如何也要出版。"}},{"pos":"PHRASE 短语","cn":"计算代价;考虑后果","en":"If someone counts the cost of something that has happened or will happen, they consider how the consequences of that action or event affect them.","ex":{"en":"Several countries in eastern Europe are counting the cost of yesterday's earthquake","cn":"东欧的几个国家正在计算昨天的地震带来的损失。"}},{"pos":"PHRASE 短语","cn":"需付钱的;价格昂贵的","en":"If you say that something costs money, you mean that it has to be paid for, and perhaps cannot be afforded.","ex":{"en":"Well-designed clothes cost money.","cn":"设计精美的服装价格昂贵。"}},{"pos":"PHRASE 短语","cn":"付出代价;吃了苦头","en":"If you know something to your cost, you know it because of an unpleasant experience that you have had.","ex":{"en":"Kathryn knows to her cost the effect of having served a jail sentence","cn":"凯瑟琳吃了苦头才知道服过刑会给一个人带来什么影响。"}},{"pos":"","cn":"","en":"to cost someone dear→see: ;"},{"pos":"","cn":"","en":"相关词组：cost out"}]},"examples":[{"en":"The closure of the factory is likely to cost 1 000 jobs.","cn":"那家工厂一关闭，很可能 1 000 个工作岗位就没有了。"},{"en":"I felt a need to please people, whatever the cost in time and energy.","cn":"我感到一定要使人们满意，耗费多少时间和精力都在所不惜。"}]},"combustion":{"media":{"uk":"media/uk/combustion__gb_1.mp3","us":"media/us/combustion__us_1.mp3"},"oxford":{"phon":"kəmˈbʌstʃən","pos":"noun","senses":[{"en":"the process of burning","cn":"燃烧","ex":{"en":"Poisonous gases are produced during fossil fuel combustion.","cn":"化石燃料在燃烧过程中会产生有毒气体。"}},{"en":"a chemical process in which substances combine with the oxygen in the air to produce heat and light","cn":"（快速）氧化","lab":"specialist","ex":{"en":"The ratio must be correct in order to achieve complete combustion.","cn":"比例必须正确才能实现完全燃烧。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"燃烧;燃烧过程","en":"Combustion is the act of burning something or the process of burning.","ex":{"en":"The energy is released by combustion on the application of a match","cn":"火柴点燃后在燃烧过程中释放能量。"}}]}},"coal":{"media":{"uk":"media/uk/coal__gb_1.mp3","us":"media/us/coal__us_1.mp3"},"oxford":{"phon":"kəʊl","pos":"noun","senses":[{"en":"a hard black mineral that is found below the ground and burnt to produce heat","cn":"煤","g":"[uncountable]","ex":{"en":"I put more coal on the fire.","cn":"我往火里加了些煤。"}},{"en":"a piece of coal, especially one that is burning","cn":"（尤指燃烧着的）煤块","g":"[countable]","ex":{"en":"A hot coal fell out of the fire and burnt the carpet.","cn":"一块燃烧着的煤块从火炉里掉出来把地毯烧了。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"煤","en":"Coal is a hard black substance that is extracted from the ground and burned as fuel.","ex":{"en":"Gas-fired electricity is cheaper than coal","cn":"天然气发电比煤便宜。"}},{"pos":"N-PLURAL 复数名词","cn":"(燃烧着的)煤块","en":"Coals are burning pieces of coal.","ex":{"en":"The iron teakettle was hissing splendidly over live coals","cn":"煤火烧得正旺，上面的铁茶壶嘶嘶地响个不停。"}},{"pos":"PHRASE 短语","cn":"申斥;严厉责备","en":"If a person in authority hauls or drags someone over the coals, they speak to them severely about something foolish or wrong that they have done.","ex":{"en":"I heard later that Uncle Jim had been hauled over the coals for not letting anyone know where we were","cn":"后来，我听说吉姆叔叔因为不告诉别人我们在哪儿而受到了严厉斥责。"}},{"pos":"PHRASE 短语","cn":"多此一举;徒劳无功","en":"If someone is taking coals to Newcastle, they are trying to give or sell someone something that they already have a lot of.","ex":{"en":"Taking a gun to the United States would be like taking coals to Newcastle.","cn":"带把枪去美国简直是多此一举。"}}]},"examples":[{"en":"A hot coal fell out of the fire and burnt the carpet.","cn":"一块燃烧着的煤块从火炉里掉出来把地毯烧了。"},{"en":"I put more coal on the fire.","cn":"我往火里再加了些煤。"}]},"consequential":{"media":{"uk":"media/uk/xconsequential__gb_1.mp3","us":"media/us/xconsequential__us_1.mp3"},"oxford":{"phon":"ˌkɒnsɪˈkwenʃl","pos":"adjective","senses":[{"en":"happening as a result or an effect of something","cn":"随之而来的；相应发生的；作为结果的","ex":{"en":"retirement and the consequential reduction in income","cn":"退休与随之而来的收入减少"}},{"en":"important; that will have important results","cn":"重要的；将产生重大结果的","ex":{"en":"The report discusses a number of consequential matters that are yet to be decided.","cn":"这份报告讨论了许多有待决定的重大问题。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"同 consequent","en":"Consequential means the same as consequent .","ex":{"en":"The actual estimate for extra staff and consequential costs such as accommodation was an annual £9.18m.","cn":"额外聘请员工以及随之发生的食宿费用等实际估算下来为每年918万英镑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"重要的;意义重大的","en":"Something that is consequential is important or significant.","ex":{"en":"This new transformation is at least as consequential as that one was","cn":"这一新的转变至少和那次一样重要。"}}]},"examples":[{"en":"The report discusses a number of consequential matters that are yet to be decided.","cn":"这份报告讨论了许多有待决定的重大问题。"},{"en":"retirement and the consequential reduction in income","cn":"退休与随之而来的收入减少"}]},"colonies":{"lemma":"colony"},"computationally":{"oxford":{"phon":"ˌkɒmpjuˈteɪʃənl","pos":"adj.","senses":[{"en":"using or connected with computers","cn":"使用计算机的；与计算机有关的"}]},"media":{"uk":"media/uk/computational__gb_1.mp3","us":"media/us/computational__us_1.mp3"}},"considers":{"lemma":"consider","media":{"uk":"media/uk/xconsider__gb_1.mp3","us":"media/us/xconsider__us_1.mp3"}},"communal":{"media":{"uk":"media/uk/communal__gb_1.mp3","us":"media/us/communal__us_1.mp3"},"oxford":{"phon":"kəˈmjuːnl","pos":"adjective","senses":[{"en":"shared by, or for the use of, a number of people, especially people who live together","cn":"（尤指居住在一起的人）共享的，共有的，共用的","ex":{"en":"a communal kitchen/garden, etc.","cn":"共用的厨房、花园等"}},{"en":"involving different groups of people in a community","cn":"（集体中）不同群体的，各团体的","ex":{"en":"communal violence between religious groups","cn":"不同教派之间的暴力冲突"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"群体的;社区的;团体的","en":"Communal means relating to particular groups in a country or society.","ex":{"en":"Communal violence broke out in different parts of the country.","cn":"在该国不同的地区发生了群体暴力事件。"}},{"pos":"ADJ 形容词","cn":"公共的;公用的","en":"You use communal to describe something that is shared by a group of people.","ex":{"en":"The inmates ate in a communal dining room.","cn":"囚犯们在公共餐厅吃饭。"}}]},"examples":[{"en":"As a student he tried communal living for a few years.","cn":"当学生时他尝试过几年集体生活。"},{"en":"a communal kitchen/garden, etc.","cn":"共用的厨房、花园等"}]},"cold":{"media":{"uk":"media/uk/cold__gb_1.mp3","us":"media/us/cold__us_1.mp3"},"oxford":{"phon":"kəʊld","pos":"adjective","senses":[{"en":"having a lower than usual temperature; having a temperature lower than the human body","cn":"寒冷的；冷的","lab":"British English","sc":"low temperature","ex":{"en":"I'm cold. Turn the heating up.","cn":"我觉得冷，把暖气温度调高一点。"}},{"en":"not heated; cooled after being cooked","cn":"未热过的；已凉的；冷却的","sc":"food/drink","ex":{"en":"a cold drink","cn":"冷饮"}},{"en":"without emotion; not friendly","cn":"冷漠的；不友好的","sc":"not friendly","ex":{"en":"to give somebody a cold look/stare","cn":"冷冷地看某人一眼／瞪着某人"}},{"en":"seeming to lack any warm feeling, in an unpleasant way","cn":"冷的；冷色的；寒色的","sc":"light/colours","ex":{"en":"clear cold light","cn":"清寒的光"}},{"en":"not easy to find","cn":"不易发现的","sc":"route","ex":{"en":"The police followed the robbers to the airport but then the trail went cold.","cn":"警察追踪抢劫犯到了机场，但是后来却失去了他们的踪迹。"}},{"en":"used in children’s games to say that the person playing is not close to finding a person or thing, or to guessing the correct answer","cn":"（儿童游戏中）离目标远的，未猜中的","sc":"in games"},{"en":"unconscious","cn":"失去知觉","g":"[not before noun]","lab":"informal","sc":"unconscious","ex":{"en":"He was knocked out cold in the second round.","cn":"他在第二轮中被击倒，失去了知觉。"}},{"en":"facts with nothing added to make them more interesting or pleasant","cn":"真实的；客观的","sc":"facts"},{"en":"a common illness that affects the nose and/or throat, making you cough, sneeze, etc.","cn":"感冒；伤风；着凉","g":"[countable]","lab":"less frequent","sc":"illness","ex":{"en":"I've got a cold.","cn":"我感冒了。"},"pos":"noun"},{"en":"a lack of heat or warm air; a low temperature, especially in the atmosphere","cn":"冷；寒冷；（尤指）低气温","g":"[uncountable]","sc":"low temperature","ex":{"en":"He shivered with cold.","cn":"他冻得发抖。"},"pos":"noun"},{"en":"suddenly and completely","cn":"突然且彻底","lab":"North American English","ex":{"en":"His final request stopped her cold.","cn":"他最后的请求突然阻止了她。"},"pos":"adverb"},{"en":"without preparing","cn":"毫无准备地","ex":{"en":"I can't just walk in there cold and give a speech.","cn":"我不能什么准备都没有，进去就发表演讲。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冷的;冰凉的","en":"Something that is cold has a very low temperature or a lower temperature than is normal or acceptable.","ex":{"en":"Rinse the vegetables under cold running water","cn":"用凉的自来水清洗这些蔬菜。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(天气或地方)冷的，寒冷的","en":"If it is cold, or if a place is cold, the temperature of the air is very low.","ex":{"en":"It was bitterly cold","cn":"天冷得刺骨。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"冷;寒冷","en":"Cold weather or low temperatures can be referred to as the cold .","ex":{"en":"He must have come inside to get out of the cold","cn":"他肯定是进来避寒的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）感觉冷的，寒冷的","en":"If you are cold, your body is at an unpleasantly low temperature.","ex":{"en":"I was freezing cold","cn":"我快冻僵了。"}},{"pos":"ADJ 形容词","cn":"(食物)凉的，冷的","en":"Cold food, such as salad or meat that has been cooked and cooled, is not intended to be eaten hot.","ex":{"en":"A wide variety of hot and cold snacks will be available.","cn":"会有各种冷热小吃。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(色彩或光)冷的，冷色调的","en":"Cold colours or cold light give an impression of coldness.","ex":{"en":"Generally, warm colours advance in painting and cold colours recede.","cn":"通常，绘画中暖色调为近感色，而冷色调为远感色。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冷淡的;冷酷的;不热情的","en":"A cold person does not show much emotion, especially affection, and therefore seems unfriendly and unsympathetic. If someone's voice is cold, they speak in an unfriendly unsympathetic way.","ex":{"en":"What a cold, unfeeling woman she was","cn":"她真是个冷酷无情的女人！"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(痕迹或气味)已变淡的","en":"A cold trail or scent is one which is old and therefore difficult to follow.","ex":{"en":"He could follow a cold trail over hard ground and even over stones.","cn":"他能循着地面上甚至是石头上留下的淡淡的痕迹展开追踪。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"远未猜中的","en":"If you say that someone is cold when they are trying to guess the answer to a question or puzzle, you mean that they are thinking about it in the wrong way and are going to give a wrong answer."},{"pos":"N-COUNT 可数名词","cn":"感冒;伤风","en":"If you have a cold, you have a mild, very common illness which makes you sneeze a lot and gives you a sore throat or a cough."},{"pos":"PHRASE 短语","cn":"患感冒","en":"If you catch cold, or catch a cold, you become ill with a cold.","ex":{"en":"Let's dry our hair so we don't catch cold.","cn":"我们把头发吹干，这样就不会感冒。"}},{"pos":"PHRASE 短语","cn":"未能打动;未能激起…的兴趣","en":"If something leaves you cold, it fails to excite or interest you.","ex":{"en":"Lawrence is one of those writers who either excite you enormously or leave you cold.","cn":"劳伦斯是那种要么让人激动不已，要么让人觉得索然无味的作家。"}},{"pos":"PHRASE 短语","cn":"昏迷的;失去知觉的;睡得很沉的","en":"If someone is out cold, they are unconscious or sleeping very heavily.","ex":{"en":"She was out cold but still breathing.","cn":"她处于昏迷状态，但还有呼吸。"}},{"pos":"PHRASE 短语","cn":"被忽视;受冷落","en":"If you say that a person, group, or country has been left out in the cold, you mean that they have been ignored by others rather than being invited to take part in some activity with them.","ex":{"en":"Developing countries might be left out in the cold in current world trade talks.","cn":"在目前的世界贸易洽谈中，发展中国家可能会受到冷落。"}},{"pos":"","cn":"","en":"in cold blood→see: ; to get cold feet→see: ; to blow hot and cold→see: ; to pour cold water on something→see: ;"}]},"examples":[{"en":"The police followed the robbers to the airport but then the trail went cold.","cn":"警察追踪抢劫犯到了机场，但是后来却失去了他们的踪迹。"},{"en":"He was going to ask her but he got cold feet and said nothing.","cn":"他本来是想问她的，可事到临头他却胆怯得什么也没有说。"}]},"compost":{"oxford":{"phon":"ˈkɒmpɒst","pos":"noun","senses":[{"en":"a mixture of decayed (= destroyed by natural processes) plants, food, etc. that can be added to soil to help plants grow","cn":"混合肥料；堆肥","ex":{"en":"potting compost (= a mixture of soil and compost that you can buy to grow new plants in)","cn":"盆栽混合肥料"}},{"en":"to make something into compost","cn":"把…制成堆肥","ex":{"en":"Cover the area with composted bark or peat.","cn":"用堆肥树皮或泥炭覆盖该区域。"},"pos":"verb"},{"en":"to put compost on or in something","cn":"施堆肥于","pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"堆肥;混合肥料","en":"Compost is a mixture of decayed plants and vegetable waste which is added to the soil to help plants grow.","ex":{"en":"...a small compost heap.","cn":"一小堆堆肥"}},{"pos":"N-MASS 物质名词","cn":"(在花盆中栽培用的)特制土","en":"Compost is specially treated soil that you buy and use to grow seeds and plants in pots."},{"pos":"VERB 动词","cn":"把…制成堆肥","en":"To compost things such as unwanted bits of plants means to make them into compost.","ex":{"en":"Cut down and compost spent cucumbers, tomatoes and other crops","cn":"将已收获过的黄瓜、西红柿和其他作物的秧蔓割下，制成堆肥。"}}]},"media":{"uk":"media/uk/compost__gb_1.mp3","us":"media/us/compost__us_1.mp3"},"examples":[{"en":"potting compost (= a mixture of soil and compost that you can buy to grow new plants in)","cn":"盆栽混合肥料"}]},"compares":{"lemma":"compare","media":{"uk":"media/uk/compare__gb_1.mp3","us":"media/us/compare__us_1.mp3"}},"convention":{"media":{"uk":"media/uk/xconvention__gb_1.mp3","us":"media/us/xconvention__us_1.mp3"},"oxford":{"phon":"kənˈvenʃn","pos":"noun","senses":[{"en":"the way in which something is done that most people in a society expect and consider to be polite or the right way to do it","cn":"习俗；常规；惯例","g":"[countable, uncountable]","ex":{"en":"the rigid social conventions of Victorian Britain","cn":"英国维多利亚时期僵化的社会习俗"}},{"en":"a large meeting of the members of a profession, a political party, etc.","cn":"（从业者、政党成员等的）大会，集会","g":"[countable]","ex":{"en":"to hold a convention","cn":"召开大会"}},{"en":"an official agreement between countries or leaders","cn":"（国家或首脑间的）公约，协定，协议","g":"[countable]","ex":{"en":"the Geneva convention","cn":"日内瓦公约"}},{"en":"a traditional method or style in literature, art or the theatre","cn":"（文学、艺术或戏剧的）传统手法，传统风格","g":"[countable, uncountable]","ex":{"en":"the conventions of Greek tragedy","cn":"希腊悲剧的传统手法"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"习俗;惯例;常规","en":"A convention is a way of behaving that is considered to be correct or polite by most people in a society.","ex":{"en":"It's just a social convention that men don't wear skirts","cn":"男人不穿裙子只是一种社会习俗。"}},{"pos":"N-COUNT 可数名词","cn":"(艺术、文学、戏剧中的)传统做法，传统风格","en":"In art, literature, or the theatre, a convention is a traditional method or style.","ex":{"en":"We go offstage and come back for the convention of the encore.","cn":"按照加演的传统做法，我们走到后台后又再次返场。"}},{"pos":"N-COUNT 可数名词","cn":"(国家或组织间的)公约，协定，协约","en":"A convention is an official agreement between countries or groups of people.","ex":{"en":"...the UN convention on climate change.","cn":"联合国有关气候变化的公约"}},{"pos":"N-COUNT 可数名词","cn":"(组织、政治团体的)大会，大型会议","en":"A convention is a large meeting of an organization or political group.","ex":{"en":"...the annual convention of the Society of Professional Journalists.","cn":"职业新闻工作者协会年度大会"}}]},"examples":[{"en":"By convention the deputy leader was always a woman.","cn":"按惯例，这一领导职务的副职总是由女性担任。"},{"en":"She is a young woman who enjoys flouting conventions.","cn":"她是一位喜欢无视传统习俗的年轻女子。"}]},"cooper":{"media":{"uk":"media/uk/cooper__gb_1.mp3","us":"media/us/cooper__us_1.mp3"},"oxford":{"phon":"ˈkuːpə(r)","pos":"noun","senses":[{"en":"a person who makes barrels","cn":"制桶工人；箍桶匠"},{"en":"a British company that made successful racing cars in the 1950s and 1960s. It is best known for the Mini Cooper, a sports car version of the original Mini.","cn":"库珀：一家在1950年代和1960年代成功制造赛车的英国公司。最著名的是Mini Cooper，它是原始Mini的跑车版本。","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"箍桶匠;制桶工匠","en":"A cooper is a person who makes barrels."}]}},"complaint":{"media":{"uk":"media/uk/complaint__gb_1.mp3","us":"media/us/complaint__us_1.mp3"},"oxford":{"phon":"kəmˈpleɪnt","pos":"noun","senses":[{"en":"a reason for not being satisfied; a statement that somebody makes saying that they are not satisfied","cn":"不满的原因；抱怨；埋怨；投诉；控告","g":"[countable]","lab":"formal","ex":{"en":"a formal complaint","cn":"正式控告"}},{"en":"the act of complaining","cn":"抱怨；埋怨；投诉","g":"[uncountable]","ex":{"en":"I can see no grounds for complaint.","cn":"我找不到抱怨的理由。"}},{"en":"an illness, especially one that is not serious, and often one that affects a particular part of the body","cn":"（尤指不严重、常影响身体某部位的）疾病","g":"[countable]","ex":{"en":"He has a minor skin complaint.","cn":"他有轻微的皮肤病。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"投诉;意见;抱怨","en":"A complaint is a statement in which you express your dissatisfaction with a particular situation.","ex":{"en":"There's been a record number of complaints about the standard of service on Britain's railways","cn":"有关英国铁路服务水平的投诉空前的多。"}},{"pos":"N-COUNT 可数名词","cn":"投诉的原因;不满的原因","en":"A complaint is a reason for complaining.","ex":{"en":"If you have a complaint about shoes bought from a shop covered by the Footwear Code, there are several ways of putting the matter right","cn":"如果对在Footwear Code旗下零售店里买的鞋有不满意的地方，有几种解决问题的方式。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指不严重的)疾病","en":"You can refer to an illness as a complaint, especially if it is not very serious.","ex":{"en":"Eczema is a common skin complaint which often runs in families.","cn":"湿疹是一种常见的皮肤病，通常具遗传性。"}}]},"examples":[{"en":"We received a number of complaints from customers about the lack of parking facilities.","cn":"我们收到了来自顾客的许多投诉，抱怨缺乏停车设施。"},{"en":"I believe you have a complaint against one of our nurses.","cn":"我认为你对我们的一位护士有怨言。"}]},"company":{"media":{"uk":"media/uk/company__gb_1.mp3","us":"media/us/company__us_1.mp3"},"oxford":{"phon":"ˈkʌmpəni","pos":"noun","senses":[{"en":"a business organization that makes money by producing or selling goods or services","cn":"公司；商号；商行","g":"[countable + singular or plural verb]","lab":"North American English","sc":"business","ex":{"en":"insurance/oil/tech/technology/pharmaceutical companies","cn":"保险／石油／技术／制药公司"}},{"en":"a group of people who work or perform together","cn":"剧团；演出团","g":"[countable + singular or plural verb]","sc":"theatre/dance","ex":{"en":"a theatre/dance, etc. company","cn":"剧团、舞蹈团等"}},{"en":"the fact of being with somebody else and not alone","cn":"陪伴；做伴","g":"[uncountable]","sc":"being with somebody","ex":{"en":"I enjoy Jo's company (= I enjoy being with her).","cn":"我喜欢和乔在一起。"}},{"en":"guests in your house","cn":"宾客；来宾","g":"[uncountable]","lab":"formal","sc":"guests","ex":{"en":"I didn't realize you had company.","cn":"我不知道你有客人。"}},{"en":"a group of people together","cn":"在一起的一群人","g":"[uncountable]","lab":"formal","sc":"group of people","ex":{"en":"She told the assembled company what had happened.","cn":"她把发生的事告诉了聚会的人。"}},{"en":"a group of soldiers that is part of a battalion","cn":"连队","g":"[countable + singular or plural verb]","sc":"soldiers"}]},"collins":{"senses":[{"pos":"N-COUNT-COLL; N-IN-NAMES 可数集合名词；名称名词","cn":"公司","en":"A company is a business organization that makes money by selling goods or services.","ex":{"en":"Sheila found some work as a secretary in an insurance company.","cn":"希拉在一家保险公司找到一份当秘书的工作。"}},{"pos":"N-COUNT-COLL; N-IN-NAMES 可数集合名词；名称名词","cn":"剧团;歌舞团","en":"A company is a group of opera singers, dancers, or actors who work together.","ex":{"en":"...the Phoenix Dance Company.","cn":"凤凰舞蹈团"}},{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"连","en":"A company is a group of soldiers that is usually part of a battalion or regiment, and that is divided into two or more platoons.","ex":{"en":"The division will consist of two tank companies and one infantry company","cn":"这个师的组成部队将包括两个坦克连和一个步兵连。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"陪伴;陪同","en":"Company is having another person or other people with you, usually when this is pleasant or stops you feeling lonely.","ex":{"en":"'I won't stay long.' — 'No, please. I need the company'","cn":"“我不会呆很久。”“别这样，求你了。我需要有人陪。”"}},{"pos":"PHRASE 短语","cn":"(用于某人的名字之后表示)及其同伴，一伙","en":"You can say and company after mentioning a person's name, to refer also to the people who are associated with that person.","ex":{"en":"Keegan and company approached the game with understandable caution.","cn":"基根一伙人小心谨慎地对待这场比赛，这是可以理解的。"}},{"pos":"PHRASE 短语","cn":"(不必为错误自责，因为)大人物们也犯过同样的错","en":"If you say that someone is in good company, you mean that they should not be ashamed of a mistake or opinion, because some important or respected people have made the same mistake or have the same opinion.","ex":{"en":"Mr Koo is in good company. The prime minister made a similar slip a couple of years back.","cn":"库先生的错大人物也犯过。几年前首相就有过类似的疏漏。"}},{"pos":"PHRASE 短语","cn":"有客人(或朋友)在","en":"If you have company, you have a visitor or friend with you.","ex":{"en":"He didn't say he had had company.","cn":"他没说当时有客人在。"}},{"pos":"PHRASE 短语","cn":"（与别人）在一起","en":"When you are in company, you are with a person or group of people.","ex":{"en":"When they were in company she always seemed to dominate the conversation","cn":"他们在一起的时候，她好像总是操纵着话语权。"}},{"pos":"PREP-PHRASE 短语介词","cn":"和…有同样的想法(或感觉、认识)","en":"If you feel, believe, or know something in company with someone else, you both feel, believe, or know it.","ex":{"en":"Saudi Arabia, in company with some other Gulf oil states, is concerned to avoid any repetition of the two oil price shocks of the 1970s.","cn":"避免20世纪70年代两次石油价格冲击的情形再次出现，这是沙特阿拉伯和其他一些海湾石油国家一致关心的问题。"}},{"pos":"PHRASE 短语","cn":"陪伴;给…做伴","en":"If you keep someone company, you spend time with them and stop them feeling lonely or bored.","ex":{"en":"Why don't you stay here and keep Emma company?","cn":"你为什么不呆在这儿，陪陪埃玛？"}},{"pos":"PHRASE 短语","cn":"与…交朋友;与…为伍","en":"If you keep company with a person or with a particular kind of person, you spend a lot of time with them.","ex":{"en":"He keeps company with all sorts of lazy characters.","cn":"他与形形色色的懒人为伍。"}},{"pos":"PHR-RECIP 相互短语","cn":"分手;分离","en":"If two or more people part company, they go in different directions after going in the same direction together.","ex":{"en":"The three of them parted company at the bus stop.","cn":"他们三个在公共汽车站分了手。"}},{"pos":"PHR-RECIP 相互短语","cn":"(通常因有分歧)与…断绝关系","en":"If you part company with someone, you end your association with them, often because of a disagreement.","ex":{"en":"The tennis star has parted company with his Austrian trainer","cn":"这位网球明星与他的奥地利教练分道扬镳。"}},{"pos":"PHRASE 短语","cn":"与…有分歧","en":"If you part company with someone on a particular subject, you disagree with them on it.","ex":{"en":"Where I part company with him, however, is over the link he forges between science and liberalism.","cn":"然而，我与他产生分歧的地方是，他把科学与自由主义联系了起来。"}},{"pos":"PHRASE 短语","cn":"在座诸位除外.","en":"If you are making a general, unfavourable comment about a particular type of person, and you are with people of that type, you can say 'present company excepted' as a way of making your comment sound more polite."}]},"examples":[{"en":"Judging by the company he kept, Mark must have been a wealthy man.","cn":"根据马克所交往的人来判断，他一定是位富翁。"},{"en":"It is bad manners to whisper in company (= in a group of people).","cn":"在众人面前窃窃私语是不礼貌的行为。"}]},"continental":{"media":{"uk":"media/uk/xcontinental__gb_1.mp3","us":"media/us/xcontinental__us_1.mp3"},"oxford":{"phon":"ˌkɒntɪˈnentl","pos":"adjective","senses":[{"en":"of or in the continent of Europe, not including Britain and Ireland","cn":"欧洲大陆的（不包括英国和爱尔兰）","g":"[only before noun]","lab":"British English","ex":{"en":"a popular continental holiday resort","cn":"受欢迎的欧洲大陆度假胜地"}},{"en":"following the customs of countries in western and southern Europe","cn":"随（西、南欧国家）大陆风俗的","lab":"British English","ex":{"en":"a continental lifestyle","cn":"西、南欧大陆的生活方式"}},{"en":"connected with the main part of the North American continent","cn":"北美大陆的","g":"[only before noun]","ex":{"en":"Prices are often higher in Hawaii than in the continental United States.","cn":"夏威夷的物价常常比美国大陆高。"}},{"en":"forming part of, or typical of, any of the seven main land masses of the earth","cn":"大洲的；大陆的","ex":{"en":"continental Antarctica/Asia/Europe","cn":"南极洲／亚洲／欧洲大陆"}},{"en":"a person who lives in the continent of Europe","cn":"欧洲大陆人","ex":{"en":"The continentals have never understood our preference for warm beer.","cn":"欧洲大陆人根本不理解我们为什么喜欢喝温啤酒。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(除英国之外)欧洲大陆的","en":"Continental means situated on or belonging to the continent of Europe except for Britain.","ex":{"en":"He sees no signs of improvement in the UK and continental economy.","cn":"他看不到英国与欧洲大陆经济好转的迹象。"}},{"pos":"N-COUNT 可数名词","cn":"欧洲大陆人","en":"A continental is someone who comes from the continent of Europe."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"典型欧洲大陆的;具欧洲大陆特征的","en":"If you describe someone or something as continental, you think that they are typical of the continent of Europe.","ex":{"en":"He's very continental","cn":"他非常欧陆化。"}},{"pos":"ADJ 形容词","cn":"大洲的;大陆的","en":"Continental is used to refer to something that belongs to or relates to a continent.","ex":{"en":"The most ancient parts of the continental crust are 4000 million years old.","cn":"大陆地壳最古老的部分有40亿年历史。"}},{"pos":"ADJ 形容词","cn":"(除夏威夷、美属维尔京群岛等之外)美国大陆的，美国本土的","en":"The continental United States consists of all the states which are situated on the continent of North America, as opposed to Hawaii and territories such as the Virgin Islands.","ex":{"en":"Shipping is included on orders sent within the continental U.S.","cn":"美国本土订单已含运费。"}},{"pos":"ADJ 形容词","cn":"(美国革命时期)发生(或存在)于美洲殖民地的，美洲大陆的","en":"Continental means existing or happening in the American colonies during the American Revolution.","ex":{"en":"...George Washington, Commander of the Continental Army","cn":"乔治·华盛顿——大陆军总司令"}},{"pos":"N-COUNT 可数名词","cn":"(美国革命时期的)大陆军士兵","en":"Continentals were soldiers who fought in the Continental Army against the British in the American Revolution."}]},"examples":[{"en":"The shutters and the balconies make the street look almost continental.","cn":"活动护窗和阳台使这条街看起来颇具欧洲大陆风格。"},{"en":"The continentals have never understood our preference for warm beer.","cn":"欧洲大陆人根本不理解我们为什么喜欢喝温啤酒。"}]},"cow":{"media":{"uk":"media/uk/cow__gb_1.mp3","us":"media/us/cow__us_1.mp3","img":["media/ldoce/img/cow.jpg"]},"oxford":{"phon":"kaʊ","pos":"noun","senses":[{"en":"a large animal kept on farms to produce milk or beef","cn":"母牛；奶牛；菜牛；肉牛","ex":{"en":"to milk a cow","cn":"挤牛奶"}},{"en":"the female of the elephant, whale and some other large animals","cn":"雌象；雌鲸；大型雌性动物"},{"en":"an offensive word for a woman who you do not like","cn":"讨厌的女人，过度肥胖的女人","lab":"slang"},{"en":"an unpleasant person, thing or situation","cn":"讨厌的人（或事物、情况）","lab":"Australian English, New Zealand English，，"},{"en":"to frighten somebody in order to make them obey you","cn":"恐吓；吓唬；威胁；胁迫","ex":{"en":"She was easily cowed by people in authority.","cn":"她很容易被有权势的人吓住。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"母牛;奶牛；（有时统称）牛","en":"A cow is a large female animal that is kept on farms for its milk. People sometimes refer to male and female animals of this species as cows .","ex":{"en":"He kept a few dairy cows","cn":"他养了几头奶牛。"}},{"pos":"N-COUNT 可数名词","cn":"雌性动物(如雌象、雌鲸等)","en":"Some female animals, including elephants and whales, are called cows .","ex":{"en":"...a cow elephant.","cn":"雌象"}},{"pos":"N-COUNT 可数名词","cn":"婆娘;娘儿们","en":"If someone describes a woman as a cow, they dislike her and think that she is unpleasant or stupid."},{"pos":"VERB 动词","cn":"恐吓;威胁;把…吓住","en":"If someone is cowed, they are made afraid, or made to behave in a particular way because they have been frightened or badly treated.","ex":{"en":"The government, far from being cowed by these threats, has vowed to continue its policy.","cn":"该政府丝毫没有被这些威胁吓住，发誓要继续执行其政策。"}},{"pos":"PHRASE 短语","cn":"很长时间;长期","en":"If you say that someone can do something until the cows come home, but it will have no effect, you are emphasizing that it will have no effect even if they do it for a very long time.","ex":{"en":"You can initiate policies until the cows come home, but unless they're monitored at a senior level, you won't get results.","cn":"你可以花很长时间来制定政策，但除非高层对之进行监管，否则不会有效果。"}}]},"examples":[{"en":"She was easily cowed by people in authority.","cn":"她很容易被有权势的人吓住。"},{"en":"Don't have a cow — it's no big deal.","cn":"别发火，没什么大不了。"}]},"colour":{"oxford":{"phon":"ˈkʌlə(r)","pos":"noun","senses":[{"en":"the appearance that things have that results from the way in which they reflect light. Red, orange and green are colours.","cn":"颜色；色彩","g":"[countable, uncountable]","sc":"red, green, etc.","ex":{"en":"What's your favourite colour?","cn":"你最喜欢的颜色是什么？"}},{"en":"the use of all the colours, not only black and white","cn":"彩色","g":"[uncountable]","sc":"red, green, etc.","ex":{"en":"the introduction of colour television in the UK in 1967","cn":"1967 年彩色电视进入英国"}},{"en":"the colour of a person’s skin, seen as showing that they belong to a particular race","cn":"（人种的）肤色","g":"[uncountable, countable]","sc":"of skin","ex":{"en":"Discrimination on the grounds of race, religion or colour was outlawed.","cn":"以种族、宗教信仰或肤色为理由的歧视是违法的。"}},{"en":"a red or pink colour in somebody’s face, especially when it shows that they look healthy or that they are embarrassed","cn":"（尤指脸色的）红润，粉红；（尴尬时的）脸红","g":"[uncountable]","sc":"of face","ex":{"en":"The fresh air brought colour to their cheeks.","cn":"新鲜空气使他们的脸颊红润。"}},{"en":"a substance that is used to give colour to something","cn":"颜料；染料","g":"[countable, uncountable]","sc":"substance","ex":{"en":"a semi-permanent hair colour that lasts six to eight washes","cn":"经得起洗涤六至八次的半永久性染发剂"}},{"en":"interesting and exciting details or qualities","cn":"趣味；乐趣","g":"[uncountable]","sc":"interesting details","ex":{"en":"The old town is full of colour and attractions.","cn":"这座古城姿彩纷呈，引人入胜。"}},{"en":"the particular colours that are used on clothes, flags, etc. to represent a team, school, political party or country","cn":"（用于服装、旗帜等代表团队、学校、政党或国家的）色彩","g":"[plural]","lab":"figurative","sc":"of team/country, etc.","ex":{"en":"Red and white are the team colours.","cn":"红白两色是这支队的队服色。"}},{"en":"a flag, badge, etc. that represents a team, country, ship, etc.","cn":"（代表团队、国家、船等的）旗帜，徽章","g":"[plural]","lab":"especially British English","sc":"of team/country, etc.","ex":{"en":"Most buildings had a flagpole with the national colours flying.","cn":"大多数的建筑物都有悬挂着国旗的旗杆。"}},{"en":"to put colour on something using paint, coloured pencils, etc.","cn":"（用颜料、彩色笔等）为…着色","g":"[intransitive, transitive]","sc":"put colour on something","ex":{"en":"The children love to draw and colour.","cn":"儿童喜欢画画和涂色。"},"pos":"verb"},{"en":"to become red because the person is embarrassed","cn":"（因尴尬而）脸红","g":"[intransitive]","sc":"of face","ex":{"en":"Everyone in the room stared at Gerry, and he coloured slightly.","cn":"房间里的每个人都盯着格里看，他的脸微微地红了。"},"pos":"verb"},{"en":"to affect something, especially in a negative way","cn":"（尤指负面地）影响","g":"[transitive]","sc":"affect","ex":{"en":"This incident coloured her whole life.","cn":"这事件影响了她的一生。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"颜色；色彩","en":"The colour of something is the appearance that it has as a result of the way in which it reflects light. Red, blue, and green are colours.","ex":{"en":"'What colour is the car?' — 'Red.'","cn":"“车是什么颜色？”“红色。”"}},{"pos":"N-VAR 可变名词","cn":"颜料;染料","en":"A colour is a substance you use to give something a particular colour. Dyes and make-up are sometimes referred to as colours .","ex":{"en":"...The Body Shop Herbal Hair Colour","cn":"美体小铺草本染发剂"}},{"pos":"VERB 动词","cn":"(用染料、颜料等)给…着色(或染色)","en":"If you colour something, you use something such as dyes or paint to change its colour.","ex":{"en":"Many women begin colouring their hair in their mid-30s","cn":"很多女人在三十五岁左右开始染发。"}},{"pos":"VERB 动词","cn":"(通常指因尴尬而)脸红","en":"If someone colours, their face becomes redder than it normally is, usually because they are embarrassed.","ex":{"en":"Andrew couldn't help noticing that she coloured slightly.","cn":"安德鲁不禁注意到她有点脸红了。"}},{"pos":"N-COUNT 可数名词","cn":"(不同人种的)肤色","en":"Someone's colour is the colour of their skin. People often use colour in this way to refer to a person's race.","ex":{"en":"I don't care what colour she is","cn":"我不在乎她的肤色。"}},{"pos":"ADJ 形容词","cn":"(电视、照片或图片)彩色的","en":"A colour television, photograph, or picture is one that shows things in all their colours, and not just in black, white, and grey.","ex":{"en":"In Japan 99 per cent of all households now have a colour television set.","cn":"现在，日本99%的家庭都拥有彩色电视机。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"生动;趣味","en":"Colour is a quality that makes something especially interesting or exciting.","ex":{"en":"She had resumed the travel necessary to add depth and colour to her novels.","cn":"她重新开始了旅行，那是增加自己小说的深度和趣味性所必不可少的。"}},{"pos":"VERB 动词","cn":"影响(某人的观点)","en":"If something colours your opinion, it affects the way that you think about something.","ex":{"en":"All too often it is only the negative images of Ireland that are portrayed, colouring opinions and hiding the true nature of the country","cn":"媒体往往描绘的只是爱尔兰的负面形象，影响了大家的看法，掩盖了这个国家的真实面貌。"}},{"pos":"N-PLURAL 复数名词","cn":"国旗的颜色","en":"A country's national colours are the colours of its national flag.","ex":{"en":"The Opera House is decorated with the Hungarian national colours: green, red and white.","cn":"歌剧院是以匈牙利国旗的颜色——绿、红、白三色装饰的。"}},{"pos":"N-PLURAL 复数名词","cn":"军旗;国旗","en":"People sometimes refer to the flag of a particular part of an army, navy, or air force, or the flag of a particular country as its colours .","ex":{"en":"Troops raised the country's colors in a special ceremony.","cn":"部队在一个特殊的仪式上升起了国旗。"}},{"pos":"N-PLURAL 复数名词","cn":"(运动队的)队服颜色","en":"A sports team's colours are the colours of the clothes they wear when they play.","ex":{"en":"I was wearing the team's colours.","cn":"我穿着该队队衣。"}},{"pos":"PHRASE 短语","cn":"(考试考得)极好地，成绩出色地","en":"If you pass a test with flying colours, you have done very well in the test.","ex":{"en":"So far McAllister seemed to have passed all the tests with flying colors.","cn":"到目前为止，麦卡利斯特似乎所有的考试都考得非常好。"}},{"pos":"PHRASE 短语","cn":"(电影或电视节目)彩色的","en":"If a film or television programme is in colour, it has been made so that you see the picture in all its colours, and not just in black, white, or grey.","ex":{"en":"Was he going to show the film? Was it in colour?","cn":"他会放那部电影吗？是彩色的吗？"}},{"pos":"PHRASE 短语","cn":"阐明观点;明确表态","en":"If someone nails their colours to the mast, they say what they really think about something.","ex":{"en":"I shall nail my colours firmly to the mast on this subject — as a feminist I find movies like this offensive.","cn":"我要非常明确地表明自己对这个主题的看法：作为一名女权主义者我认为这类电影是对女性的侮辱。"}},{"pos":"PHRASE 短语","cn":"表明对…的支持","en":"If you nail your colours to someone's mast, or if you nail your colours to a particular mast, you show that you support a particular person or issue.","ex":{"en":"He has nailed his colours firmly to Mr Dobson's mast","cn":"他表示坚决支持多布森先生。"}},{"pos":"PHRASE 短语","cn":"看(某人)有没有足够的支付能力","en":"If you say that you want to see the colour of someone's money, you mean that you are not prepared to sell them something or do something for them until they have proved that they have the money to pay for it.","ex":{"en":"He made a mental note never to enter into conversation with a customer until he'd at least seen the colour of his money.","cn":"他心里暗暗记住，顾客至少要看上去能付得起钱，他才会去和他们搭话。"}},{"pos":"PHRASE 短语","cn":"(人种)有色的","en":"People of colour are people who belong to a race with dark skins.","ex":{"en":"Black communities spoke up to defend the rights of all people of color.","cn":"黑人群体大声疾呼，要求维护有色人种的权利。"}},{"pos":"PHRASE 短语","cn":"(看到)…的真面目;露出…的真面目","en":"If you see someone in their true colours or if they show their true colours, you realize what they are really like.","ex":{"en":"The children are seeing him in his true colours for the first time now","cn":"现在，孩子们第一次看到他的真面目。"}},{"pos":"","cn":"","en":"相关词组：colour in"}]},"media":{"uk":"media/uk/colour__gb_1.mp3","us":"media/us/colour__us_1.mp3"},"examples":[{"en":"Foods which go through a factory process lose much of their colour, flavour and texture.","cn":"经过工厂加工的食品会失去许多色泽、味道和质地。"},{"en":"a semi-permanent hair colour that lasts six to eight washes","cn":"经得起连续洗涤六至八次的非永久性染发剂"}]},"community":{"media":{"uk":"media/uk/community__gb_1.mp3","us":"media/us/community__us_1.mp3"},"oxford":{"phon":"kəˈmjuːnəti","pos":"noun","senses":[{"en":"all the people who live in a particular area, country, etc. when talked about as a group","cn":"社区；社会","g":"[countable, usually singular]","lab":"North American English","ex":{"en":"The local community supported us from the start.","cn":"当地社区从一开始就支持我们。"}},{"en":"a group of people who share the same religion, race, job, etc.","cn":"团体；社团；界","g":"[countable + singular or plural verb]","ex":{"en":"the Polish community in London","cn":"在伦敦的波兰侨民团体"}},{"en":"the feeling of sharing things and belonging to a group in the place where you live","cn":"共享；共有","g":"[uncountable]","lab":"especially North American English","ex":{"en":"There is a strong sense of community here.","cn":"这里有一种强烈的社区意识。"}},{"en":"a group of people who live together and all equally own and share what they have","cn":"社区","g":"[countable]","ex":{"en":"The nuns live in a closed community.","cn":"修女们住在一个封闭的社区里。"}},{"en":"a group of plants and animals growing or living in the same place or environment","cn":"（动植物的）群落","g":"[countable]","lab":"biology","ex":{"en":"a community fish tank","cn":"社区鱼缸"}}]},"collins":{"senses":[{"pos":"N-SING-COLL 单数集合名词","cn":"(同住一地的人所构成的)社区","en":"The community is all the people who live in a particular area or place.","ex":{"en":"He's well liked by people in the community","cn":"社区的人都非常喜欢他。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"群体;团体","en":"A particular community is a group of people who are similar in some way.","ex":{"en":"The police haven't really done anything for the black community in particular.","cn":"警方并未真正特意为黑人群体做什么。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(不同人士、团体之间的)友谊，伙伴关系","en":"Community is friendship between different people or groups, and a sense of having something in common.","ex":{"en":"A supportive house for eight to ten older people, each with his or her own room, provides privacy and a sense of community","cn":"一幢扶助性住宅可供8至10位老人居住，每个人都有自己单独的房间，在这里，他们既能独处，又有社区归属感。"}}]},"examples":[{"en":"The local community was shocked by the murders.","cn":"当地社会对这些谋杀案感到震惊。"},{"en":"There is a strong sense of community in this town.","cn":"这个镇上有一种强烈的社区意识。"}]},"coast":{"media":{"img":["media/pic/coast_labels_comp.jpg","media/thumb/coast.jpg"],"uk":"media/uk/coast__gb_1.mp3","us":"media/us/coast__us_1.mp3"},"oxford":{"phon":"kəʊst","pos":"noun","senses":[{"en":"the land next to or near to the sea or ocean","cn":"海岸；海滨","lab":"especially British English","ex":{"en":"a trip to the coast","cn":"海滨旅游"}},{"en":"to move, especially down a hill, without using any power","cn":"（尤指不用动力向山坡下）滑行，惯性滑行","g":"[intransitive]","ex":{"en":"The car coasted along until it stopped.","cn":"汽车随惯性而下直至滑行停止。"},"pos":"verb"},{"en":"to move quickly and smoothly, without using much power","cn":"（不用多少动力）快速平稳地移动","g":"[intransitive]","ex":{"en":"The plane coasted down the runway.","cn":"飞机顺着跑道平稳滑行。"},"pos":"verb"},{"en":"to be successful at something without having to try hard","cn":"不费力地取得成功","g":"[intransitive]","ex":{"en":"He coasted through his final exams.","cn":"他毫不费劲地通过了期终考试。"},"pos":"verb"},{"en":"to put very little effort into something","cn":"（做事）不出力","g":"[intransitive]","lab":"disapproving","ex":{"en":"You're just coasting—it's time to work hard now.","cn":"你根本是在应付，现在该努力干了。"},"pos":"verb"},{"en":"to stay close to land while sailing around the coast","cn":"沿海岸航行","g":"[intransitive]","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"海岸;海滨","en":"The coast is an area of land that is next to the sea.","ex":{"en":"Camp sites are usually situated along the coast, close to beaches.","cn":"野营地一般都位于海滨，靠近沙滩。"}},{"pos":"VERB 动词","cn":"(车辆熄火后或不用动力)靠惯性滑行","en":"If a vehicle coasts somewhere, it continues to move there with the motor switched off, or without being pushed or pedalled.","ex":{"en":"I switched off the engine and coasted round the corner.","cn":"我熄掉引擎，靠惯性转过弯去。"}},{"pos":"VERB 动词","cn":"毫不费力地做;(尤指)轻松获胜","en":"If a person or a team is coasting, they are doing something easily, especially winning a competition.","ex":{"en":"Ivan Lendl coasted to a 6-3, 6-2, 6-3 victory over Roger Rasheed","cn":"伊万·伦德尔以6:3，6:2和6:3的比分轻松战胜了罗杰·拉希德。"}},{"pos":"VERB 动词","cn":"不够努力;应付","en":"If you say that someone is coasting, you are emphasizing that they are not putting enough effort into what they are doing.","ex":{"en":"There was a time when Charles was coasting at school and I should have told him to buckle down.","cn":"有一段时间查尔斯在学校不太用功，我当时应该让他加把劲的。"}},{"pos":"PHRASE 短语","cn":"没有被发现(或捉住)的危险;危险已过","en":"If you say that the coast is clear, you mean that there is nobody around to see you or catch you.","ex":{"en":"'You can come out now,' he called. 'The coast is clear. She's gone.'","cn":"“你现在可以出来了。”他喊道，“没危险了，她已经走了。”"}}]},"examples":[{"en":"She took her feet off the pedals and coasted downhill.","cn":"她从自行车的踏板上松开脚，沿山坡滑行而下。"},{"en":"As soon as the coast was clear he climbed in through the window.","cn":"等到四下无人，他便从窗户爬了进去。"}]},"countess":{"media":{"uk":"media/uk/countess__gb_1.mp3","us":"media/us/countess__us_1.mp3"},"oxford":{"phon":"ˈkaʊntəs","pos":"noun","senses":[{"en":"a woman who has the rank of a count or an earl","cn":"女伯爵"},{"en":"the wife of a count or an earl","cn":"伯爵夫人","ex":{"en":"the Earl and Countess of Rosebery","cn":"罗斯伯里伯爵及夫人"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-TITLE; N-VOC可数名词；头衔名词；称呼名词","cn":"女伯爵;伯爵夫人","en":"A countess is a woman who has the same rank as a count or earl, or who is married to a count or earl.","ex":{"en":"...the Countess of Lichfield.","cn":"利奇菲尔德女伯爵"}}]},"examples":[{"en":"the Earl and Countess of Rosebery","cn":"罗斯伯里伯爵及夫人"}]},"comment":{"media":{"uk":"media/uk/comment__gb_1.mp3","us":"media/us/comment__us_1.mp3"},"oxford":{"phon":"ˈkɒment","pos":"noun","senses":[{"en":"something that you say or write that gives an opinion on or explains somebody/something","cn":"议论；评论；解释","g":"[countable, uncountable]","lab":"especially British English","ex":{"en":"She made helpful comments on my work.","cn":"她对我的工作提出了有益的意见。"}},{"en":"criticism that shows the faults of something","cn":"批评；指责","g":"[singular, uncountable]","ex":{"en":"The results are a clear comment on government education policy.","cn":"这些结果是对政府教育政策明显的批评。"}},{"en":"to express an opinion about something","cn":"表达意见","ex":{"en":"He refused to comment until after the trial.","cn":"他拒绝在审判前作任何评论。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"发表意见;作出评论","en":"If you comment on something, you give your opinion about it or you give an explanation for it.","ex":{"en":"So far, Mr Cook has not commented on these reports","cn":"到目前为止，库克先生仍未就这些报道发表评论。"}},{"pos":"N-VAR 可变名词","cn":"评论;意见","en":"A comment is something that you say which expresses your opinion of something or which gives an explanation of it.","ex":{"en":"He made his comments at a news conference in Amsterdam","cn":"他在阿姆斯特丹的记者招待会上发表了意见。"}},{"pos":"N-SING 单数名词","cn":"(通常是不好的事的)体现，写照","en":"If an event or situation is a comment on something, it reveals something about that thing, usually something bad.","ex":{"en":"He argues that family problems are typically a comment on some unresolved issues in the family.","cn":"他认为各种家庭问题通常都反映出家庭内部存在一些有待解决的矛盾。"}},{"pos":"CONVENTION 惯用语","cn":"无可奉告(通常用于回答记者的提问)","en":"People say 'no comment' as a way of refusing to answer a question, usually when it is asked by a journalist.","ex":{"en":"No comment. I don't know anything.","cn":"无可奉告。我什么都不知道。"}}]},"examples":[{"en":"‘Not his best performance,’ she commented to the woman sitting next to her. “","cn":"这不是他的最佳表现。”她对坐在她旁边的女士议论道。"},{"en":"He noted in passing that the company's record on safety issues was not good.","cn":"他顺便提到该公司在安全方面的记录不好。"}]},"confirm":{"oxford":{"phon":"kənˈfɜːm","pos":"verb","senses":[{"en":"to state or show that something is definitely true or correct, especially by providing evidence","cn":"（尤指提供证据来）证实，证明，确认","ex":{"en":"His guilty expression confirmed my suspicions.","cn":"他内疚的表情证实了我的猜疑。"}},{"en":"to make a position, an agreement, etc. more definite or official; to establish somebody/something clearly","cn":"批准（职位、协议等）；确认；认可","ex":{"en":"Please write to confirm your reservation (= say that it is definite).","cn":"预订后请来函确认。"}},{"en":"to make somebody feel or believe something even more strongly","cn":"使感觉更强烈；使确信","ex":{"en":"The walk in the mountains confirmed his fear of heights.","cn":"在山里步行使他更加确信自己有恐高症。"}},{"en":"to perform the Christian or Jewish ceremony of confirmation","cn":"（在基督教或犹太教仪式中给某人）施放坚振，施坚信礼","g":"[usually passive]","ex":{"en":"She was baptized when she was a month old and confirmed when she was thirteen.","cn":"她出生一个月时受洗礼，十三岁时受坚信礼。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"证实，证明(情况属实)","en":"If something confirms what you believe, suspect, or fear, it shows that it is definitely true.","ex":{"en":"X-rays have confirmed that he has not broken any bones","cn":"X光片证实他没有骨折。"}},{"pos":"VERB 动词","cn":"（某人）证实，肯定，确认","en":"If you confirm something that has been stated or suggested, you say that it is true because you know about it.","ex":{"en":"The spokesman confirmed that the area was now in rebel hands","cn":"这位发言人证实该地区现已落入叛乱分子手中。"}},{"pos":"VERB 动词","cn":"(通常指通过信件或电话)确定，确认(安排或预约)","en":"If you confirm an arrangement or appointment, you say that it is definite, usually in a letter or on the telephone.","ex":{"en":"You make the reservation, and I'll confirm it in writing.","cn":"你来预订，我会去函确认。"}},{"pos":"VERB 动词","cn":"为…施坚振礼（或坚信礼）(从而正式成为基督教会的成员)","en":"If someone is confirmed, they are formally accepted as a member of a Christian church during a ceremony in which they say they believe what the church teaches.","ex":{"en":"He was confirmed as a member of the Church of England.","cn":"他领受了坚振礼，成为英国国教会的一员。"}},{"pos":"VERB 动词","cn":"使坚定，使确信(自己的决定、信仰或观点)","en":"If something confirms you in your decision, belief, or opinion, it makes you think that you are definitely right.","ex":{"en":"It has confirmed me in my decision not to become a nun.","cn":"这使我更加坚定了不做修女的决心。"}},{"pos":"VERB 动词","cn":"加强，巩固(地位、角色或权力)","en":"If someone confirms their position, role, or power, they do something to make their power, position, or role stronger or more definite.","ex":{"en":"Williams has confirmed his position as the world's number one snooker player.","cn":"威廉姆斯巩固了自己世界头号斯诺克选手的地位。"}},{"pos":"VERB 动词","cn":"巩固，确保(某人的名声、角色或地位)","en":"If something confirms you as something, it shows that you definitely deserve a name, role, or position.","ex":{"en":"His new role could confirm him as one of our leading actors.","cn":"他的新角色会确保他跻身我们的一流演员之列。"}}]},"media":{"uk":"media/uk/xconfirm__gb_1.mp3","us":"media/us/xconfirm__us_1.mp3"},"examples":[{"en":"He was confirmed as captain for the rest of the season.","cn":"他被正式任命在这个赛季剩下的一段时间内担任队长。"},{"en":"After a six-month probationary period, her position was confirmed.","cn":"经过六个月的试用期后，她获准正式担任该职。"}]},"controversial":{"media":{"uk":"media/uk/xcontroversial__gb_1.mp3","us":"media/us/xcontroversial__us_1.mp3"},"oxford":{"phon":"ˌkɒntrəˈvɜːʃl","pos":"adjective","senses":[{"en":"causing a lot of angry public discussion and disagreement","cn":"引起争论的；有争议的","ex":{"en":"a highly controversial topic","cn":"颇有争议的话题"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有争议的;引发争论的","en":"If you describe something or someone as controversial, you mean that they are the subject of intense public argument, disagreement, or disapproval.","ex":{"en":"Immigration is a controversial issue in many countries","cn":"在很多国家，移民都是一个颇有争议的问题。"}}]},"examples":[{"en":"Winston Churchill and Richard Nixon were both controversial figures.","cn":"温斯顿 · 丘吉尔和理查德 · 尼克松都是有争议的人物。"},{"en":"a controversial plan to build a new road","cn":"有争议的修建新道路计划"}]},"conducive":{"media":{"uk":"media/uk/xconducive__gb_1.mp3","us":"media/us/xconducive__us_1.mp3"},"oxford":{"phon":"kənˈdjuːsɪv","pos":"adjective","senses":[{"en":"making it easy, possible or likely for something to happen","cn":"有助于；便于","ex":{"en":"Chairs in rows are not as conducive to discussion as chairs arranged in a circle.","cn":"椅子成排摆放不如成圈摆放便于讨论。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有助(于…)的;有益(于…)的","en":"If one thing is conducive to another thing, it makes the other thing likely to happen.","ex":{"en":"Make your bedroom as conducive to sleep as possible","cn":"尽量把卧室布置得适宜睡眠。"}}]},"examples":[{"en":"Chairs in rows are not as conducive to discussion as chairs arranged in a circle.","cn":"椅子成排摆放不如成圈摆放便于讨论。"},{"en":"an environment conducive to learning","cn":"有助于学习的环境"}]},"counterbalance":{"oxford":{"phon":"ˌkaʊntəˈbæləns","pos":"verb","senses":[{"en":"to have an equal but opposite effect to something else","cn":"抗衡；抵消；对…起平衡作用","ex":{"en":"Parents' natural desire to protect their children should be counterbalanced by the child's need for independence.","cn":"父母保护孩子的本能愿望应当与孩子独立的需要相平衡。"}},{"en":"a thing that has an equal but opposite effect to something else and can be used to limit the bad effects of something","cn":"平衡抵消物；平衡重（或块、锤）","ex":{"en":"The accused's right to silence was a vital counterbalance to the powers of the police.","cn":"被告人的沉默权对警方的权力是一种至关重要的抗衡。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"对…起平衡作用;抗衡;抵消","en":"To counterbalance something means to balance or correct it with something that has an equal but opposite effect.","ex":{"en":"Add honey to counterbalance the acidity","cn":"加点蜂蜜来调和酸味。"}},{"pos":"N-COUNT 可数名词","cn":"起平衡作用的事物;抗衡力；抵消因素","en":"Something that is a counterbalance to something else counter-balances that thing.","ex":{"en":"...organisations set up as a counterbalance to groups allied to the ANC.","cn":"为抗衡非国大联盟而成立的一些组织"}}]},"media":{"uk":"media/uk/counterbalance__gb_1.mp3","us":"media/us/counterbalance__us_1.mp3"},"examples":[{"en":"Parents' natural desire to protect their children should be counterbalanced by the child's need for independence.","cn":"父母保护孩子的本能愿望应当与孩子独立的需要相平衡。"},{"en":"The accused's right to silence was a vital counterbalance to the powers of the police.","cn":"被告人的沉默权对警方的权力是一种至关重要的抗衡。"}]},"conductor":{"oxford":{"phon":"kənˈdʌktə(r)","pos":"noun","senses":[{"en":"a person who stands in front of an orchestra, a group of singers etc., and directs their performance, especially somebody who does this as a profession","cn":"（管弦乐队、合唱队等的）指挥；职业指挥","ex":{"en":"the principal conductor of the San Francisco Symphony","cn":"旧金山交响乐团的首席指挥"}},{"en":"a person who is in charge of a train and travels with it, but does not drive it","cn":"列车长","lab":"British English also"},{"en":"a person whose job is to collect money from passengers on a bus or train or check their tickets","cn":"（公共汽车）售票员；（火车）检票员","lab":"British English","ex":{"en":"a bus conductor","cn":"公共汽车售票员"}},{"en":"a substance that allows electricity or heat to pass along it or through it","cn":"导体（导电或导热等的物质）","lab":"physics","ex":{"en":"Wood is a poor conductor.","cn":"木头是不良导体。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(管弦乐队或合唱团的)指挥","en":"A conductor is a person who stands in front of an orchestra or choir and directs its performance."},{"pos":"N-COUNT 可数名词","cn":"公交车售票员","en":"On a bus, the conductor is the person whose job is to sell tickets to the passengers."},{"pos":"N-COUNT 可数名词","cn":"列车员","en":"On a train, a conductor is a person whose job is to travel on the train in order to help passengers and check tickets."},{"pos":"N-COUNT 可数名词","cn":"导体","en":"A conductor is a substance that heat or electricity can pass through or along."}]},"media":{"uk":"media/uk/xconductor__gb_1.mp3","us":"media/us/xconductor__us_1.mp3"},"examples":[{"en":"Wood is a poor conductor.","cn":"木头不是良好的导体。"},{"en":"a bus conductor","cn":"公共汽车售票员"}]},"courtship":{"media":{"uk":"media/uk/courtship__gb_1.mp3","us":"media/us/courtship__us_1.mp3"},"oxford":{"phon":"ˈkɔːtʃɪp","pos":"noun","senses":[{"en":"the time when two people have a romantic relationship before they get married; the process of developing this relationship","cn":"求爱期；求爱；追求","g":"[countable, uncountable]","lab":"old-fashioned","ex":{"en":"They married after a short courtship.","cn":"他们恋爱不久便结婚了。"}},{"en":"the special way animals behave in order to attract a mate (= sexual partner)","cn":"（动物的）求偶","g":"[uncountable]","ex":{"en":"courtship displays","cn":"求偶的炫耀行为"}},{"en":"the process or act of attracting a business partner, etc.","cn":"招商","g":"[uncountable]","lab":"formal","ex":{"en":"the company’s courtship by the government","cn":"政府向公司献殷勤"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"求爱;恋爱;求爱(或恋爱)期","en":"Courtship is the activity of courting or the time during which a man and a woman are courting.","ex":{"en":"They were more interested in courtship and cars than in school","cn":"比起上学，他们对谈恋爱和汽车更感兴趣。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(动物的)求偶","en":"The courtship of male and female animals is their behaviour before they have sex.","ex":{"en":"Courtship is somewhat vocal with a lot of displaying by the male.","cn":"雄性动物在求偶时会尽量展示自己，并发出一些声响。"}}]},"examples":[{"en":"They married after a short courtship.","cn":"他们恋爱不久便结婚了。"},{"en":"the company's courtship by the government","cn":"政府向公司献殷勤"}]},"common":{"media":{"uk":"media/uk/common__gb_1.mp3","us":"media/us/common__us_1.mp3"},"oxford":{"phon":"ˈkɒmən","pos":"adjective","senses":[{"en":"happening often; existing in large numbers or in many places","cn":"常见的；通常的；普遍的","ex":{"en":"a common problem/occurrence/practice","cn":"常见问题／事件／做法"}},{"en":"shared by or belonging to two or more people or by the people in a group","cn":"共有的；共享的；共同的","g":"[usually before noun]","ex":{"en":"They share a common interest in photography.","cn":"他们在摄影方面兴趣相投。"}},{"en":"ordinary; not unusual or special","cn":"普通的；平常的；寻常的；平凡的","g":"[only before noun]","ex":{"en":"Shakespeare's work was popular among the common people in his day.","cn":"莎士比亚的作品在他那个年代很受平民百姓的欢迎。"}},{"en":"found or living in quite large numbers; not rare","cn":"常见的；非珍稀的","ex":{"en":"the common garden frog","cn":"园地里常见的青蛙"}},{"en":"typical of somebody from a low social class and not having good manners","cn":"粗俗的；庸俗的","lab":"British English, disapproving，，","ex":{"en":"She thought he was very common and uneducated.","cn":"她认为他很粗俗且无教养。"}},{"en":"an area of open land in a town or village that anyone may use","cn":"公共用地；公地","g":"[countable]","ex":{"en":"We went for a walk on the common.","cn":"我们在公地上散步。"},"pos":"noun"},{"en":"a large room where students can eat in a school, college, etc.","cn":"（学校、大学等的）学生公共食堂","g":"[singular]","lab":"US English","ex":{"en":"The commons is next to the gym.","cn":"学生公共食堂在体育馆的旁边。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"常见的;普遍的","en":"If something is common, it is found in large numbers or it happens often.","ex":{"en":"His name was Hansen, a common name in Norway","cn":"他的名字叫汉森，在挪威是一个常见的名字。"}},{"pos":"ADJ 形容词","cn":"共有的;共同的","en":"If something is common to two or more people or groups, it is done, possessed, or used by them all.","ex":{"en":"Moldavians and Romanians share a common language","cn":"摩尔达维亚人和罗马尼亚人使用同一种语言。"}},{"pos":"ADJ 形容词","cn":"(物种)常见的","en":"When there are more animals or plants of a particular species than there are of related species, then the first species is called common .","ex":{"en":"...the common house fly.","cn":"常见的家蝇"}},{"pos":"ADJ 形容词","cn":"寻常的;普通的","en":"Common is used to indicate that someone or something is of the ordinary kind and not special in any way.","ex":{"en":"Democracy might elevate the common man to a position of political superiority","cn":"民主也许能提升普通人的政治地位，让他们产生优越感。"}},{"pos":"ADJ 形容词","cn":"(礼貌等)通常的，起码的","en":"Common decency or common courtesy is the decency or courtesy which most people have. You usually talk about this when someone has not shown these characteristics in their behaviour to show your disapproval of them.","ex":{"en":"It is common decency to give your seat to anyone in greater need","cn":"给更有需要的人让座是最起码的礼貌。"}},{"pos":"ADJ 形容词","cn":"(知识等)众所周知的，共有的，共识的","en":"You can use common to describe knowledge, an opinion, or a feeling that is shared by people in general.","ex":{"en":"It is common knowledge that swimming is one of the best forms of exercise.","cn":"大家都知道游泳是最好的锻炼方式之一。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"粗俗的;缺乏教养的","en":"If you describe someone or their behaviour as common, you mean that they show a lack of taste, education, and good manners.","ex":{"en":"She might be a little common at times, but she was certainly not boring.","cn":"她有时候可能有点粗俗，但绝对不会让人生厌。"}},{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"(通常指村庄、小镇或其附近的)公共草地","en":"A common is an area of grassy land, usually in or near a village or small town, where the public is allowed to go.","ex":{"en":"We are warning women not to go out on to the common alone.","cn":"我们告诫女性不要独自去公共草地。"}},{"pos":"N-PROPER-COLL 专有集合名词","cn":"同 the House of Commons;(亦指)下议员议员们","en":"The Commons is the same as the House of Commons. The members of the House of Commons can also be referred to as the Commons .","ex":{"en":"The Prime Minister is to make a statement in the Commons this afternoon","cn":"今天下午首相将在下议院发表声明。"}},{"pos":"PHRASE 短语","cn":"共有的;相同的","en":"If two or more things have something in common, they have the same characteristic or feature.","ex":{"en":"The oboe and the clarinet have got certain features in common","cn":"双簧管和单簧管有些相似之处。"}},{"pos":"PHRASE 短语","cn":"(兴趣或经历)共同的，相同的","en":"If two or more people have something in common, they share the same interests or experiences.","ex":{"en":"He had very little in common with his sister.","cn":"他和姐姐几乎没有什么共同语言。"}},{"pos":"","cn":"","en":"to make common cause with someone→see: ; the common good→see: ; common ground→see: ; the common touch→see: ;"}]},"examples":[{"en":"Britain, in common with many other industrialized countries, has experienced major changes over the last 100 years.","cn":"与许多其他工业化国家一样，英国在过去 100 年里经历了重大的变化。"},{"en":"Shakespeare's work was popular among the common people in his day.","cn":"莎士比亚的作品在他那个年代很受平民百姓的欢迎。"}]},"computational":{"media":{"uk":"media/uk/computational__gb_1.mp3","us":"media/us/computational__us_1.mp3"},"oxford":{"phon":"ˌkɒmpjuˈteɪʃənl","pos":"adjective","senses":[{"en":"using or connected with computers","cn":"使用计算机的；与计算机有关的","ex":{"en":"computational methods","cn":"用计算机做的方法"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"计算机的","en":"Computational means using computers.","ex":{"en":"Students may pursue research in any aspect of computational linguistics.","cn":"学生可以就计算语言学的任何一个方面展开研究。"}}]},"examples":[{"en":"computational methods","cn":"用计算机做的方法"},{"en":"a computational approach","cn":"通过计算机进行"}]},"conformity":{"media":{"uk":"media/uk/xconformity__gb_1.mp3","us":"media/us/xconformity__us_1.mp3"},"oxford":{"phon":"kənˈfɔːməti","pos":"noun","senses":[{"en":"behaviour or actions that follow the accepted rules of society","cn":"（对社会规则的）遵从，遵守","ex":{"en":"a society of outward religious conformity","cn":"表面上宗教信仰一致的社会"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(对法律、个人意愿等的)遵从，遵守","en":"If something happens in conformity with something such as a law or someone's wishes, it happens as the law says it should, or as the person wants it to.","ex":{"en":"The prime minister is, in conformity with the constitution, chosen by the president.","cn":"依照宪法，首相由总统选定。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"墨守成规;循规蹈矩","en":"Conformity means behaving in the same way as most other people.","ex":{"en":"Excessive conformity is usually caused by fear of disapproval","cn":"过于墨守成规通常都是由于担心得不到认可。"}}]},"examples":[{"en":"regulations that are in conformity with European law","cn":"符合欧洲法律的条例"},{"en":"an emphasis on conformity and control","cn":"对遵从和控制的重视"}]},"constantly":{"media":{"uk":"media/uk/xconstantly__gb_1.mp3","us":"media/us/xconstantly__us_1.mp3"},"oxford":{"phon":"ˈkɒnstəntli","pos":"adverb","senses":[{"en":"all the time; repeatedly","cn":"始终；一直；重复不断地","ex":{"en":"Fashion is constantly changing.","cn":"时尚总是日新月异。"}}]},"examples":[{"en":"Heat the sauce, stirring constantly.","cn":"加热调味汁并不停地搅动。"},{"en":"Fashion is constantly changing.","cn":"时尚总是日新月异。"}]},"cornerstone":{"media":{"uk":"media/uk/cornerstone__gb_1.mp3","us":"media/us/cornerstone__us_1.mp3"},"oxford":{"phon":"ˈkɔːnəstəʊn","pos":"noun","senses":[{"en":"a stone at the corner of the base of a building, often laid in a special ceremony","cn":"基石；奠基石"},{"en":"the most important part of something that the rest depends on","cn":"最重要部分；基础；柱石","ex":{"en":"This study is the cornerstone of the whole research programme.","cn":"此项研究是整个研究计划的基础。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"基石;基础;最重要的部分","en":"The cornerstone of something is the basic part of it on which its existence, success, or truth depends.","ex":{"en":"Research is the corner-stone of the profession.","cn":"研究是这一职业的基础。"}}]},"examples":[{"en":"This study is the cornerstone of the whole research programme.","cn":"此项研究是整个研究计划的基础。"},{"en":"The magazine became the cornerstone of McFadden’s publishing empire.","cn":"这本杂志成了麦克法登出版帝国的支柱。"}]},"coastline":{"media":{"uk":"media/uk/coastline__gb_1.mp3","us":"media/us/coastline__us_1.mp3"},"oxford":{"phon":"ˈkəʊstlaɪn","pos":"noun","senses":[{"en":"the land along a coast, especially when you are thinking of its shape or appearance","cn":"海岸线；海岸地形（或轮廓）；沿海地带","lab":"especially British English","ex":{"en":"a rugged/rocky/beautiful coastline","cn":"崎岖的／多岩石的／美丽的海岸线"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"海岸线","en":"A country's coastline is the outline of its coast.","ex":{"en":"This is some of the most exposed coastline in the world","cn":"这里的海岸线属于世界上最无遮蔽的一段了。"}}]},"examples":[{"en":"to protect the coastline from oil spillage","cn":"保护海岸线不受石油泄漏的污染"},{"en":"a rugged/rocky/beautiful coastline","cn":"崎岖的/多岩石的/美丽的海岸线"}]},"conveniently":{"oxford":{"phon":"kənˈviːniəntli","pos":"adverb","senses":[{"en":"in a way that is useful, easy or quick to do; in a way that does not cause problems","cn":"实用的；便利的；方便的；省事的","ex":{"en":"The report can be conveniently divided into three main sections.","cn":"报告很容易就可以分成三个主要部分。"}},{"en":"in a way that is near to a particular place or easy to get to","cn":"附近的；近便的；容易到达的","ex":{"en":"The hotel is conveniently situated close to the beach.","cn":"宾馆离海滩很近，位置非常便利。"}}]},"media":{"uk":"media/uk/xconveniently__gb_1.mp3","us":"media/us/xconveniently__us_1.mp3"},"examples":[{"en":"She conveniently forgot to mention that her husband would be at the party, too (= because it suited her not to say).","cn":"她没有提她丈夫也要参加聚会，她觉得还是不提为好。"},{"en":"The report can be conveniently divided into three main sections.","cn":"这份报告不用费事就可划分为三个主要部分。"}]},"complaining":{"lemma":"complain","media":{"uk":"media/uk/complain__gb_1.mp3","us":"media/us/complain__us_1.mp3"}},"comforts":{"lemma":"comfort","media":{"uk":"media/uk/comfort__gb_1.mp3","us":"media/us/comfort__us_1.mp3"}},"confectionery":{"media":{"uk":"media/uk/xconfectionery__gb_1.mp3","us":"media/us/xconfectionery__us_1.mp3"},"oxford":{"phon":"kənˈfekʃənəri","pos":"noun","senses":[{"en":"sweets, chocolate, etc.","cn":"甜食（糖果、巧克力等）","ex":{"en":"Confectionery is a multimillion-pound business.","cn":"糖果业是一项价值数百万英镑的业务。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"甜食；糖果","en":"Confectionery is sweets and chocolates.","ex":{"en":"...hand-made confectionery.","cn":"手工制作的甜食"}}]}},"consequently":{"media":{"uk":"media/uk/xconsequently__gb_1.mp3","us":"media/us/xconsequently__us_1.mp3"},"oxford":{"phon":"ˈkɒnsɪkwəntli","pos":"adverb","senses":[{"en":"as a result; therefore","cn":"因此；所以","ex":{"en":"This poses a threat to agriculture and the food chain, and consequently to human health.","cn":"这会对农业和食物链造成威胁，因而危及人的健康。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"所以;结果","en":"Consequently means as a result.","ex":{"en":"Grandfather Dingsdale had sustained a broken back while working in the mines. Consequently, he spent the rest of his life in a wheelchair","cn":"丁斯戴尔爷爷在矿井里工作时被压断了脊骨，结果，下半辈子都与轮椅为伴了。"}}]},"examples":[{"en":"This poses a threat to agriculture and the food chain, and consequently to human health.","cn":"这会对农业和食物链造成威胁，由此而危及人的健康。"},{"en":"Most computer users have never received any formal keyboard training. Consequently, their keyboard skills are inefficient.","cn":"大多数的电脑使用者都没有经过正规的键盘操作训练﹐因此他们的键盘技巧不够熟练。"}]},"conductors":{"lemma":"conductor"},"corporations":{"lemma":"corporation","media":{"uk":"media/uk/corporation__gb_1.mp3","us":"media/us/corporation__us_1.mp3"}},"concrete":{"media":{"uk":"media/uk/xconcrete__gb_1.mp3","us":"media/us/xconcrete__us_1.mp3","img":["media/ldoce/img/concrete.jpg"]},"oxford":{"phon":"ˈkɒŋkriːt","pos":"adjective","senses":[{"en":"made of concrete","cn":"混凝土制的","ex":{"en":"a concrete floor","cn":"混凝土地面"}},{"en":"based on facts, not on ideas or guesses","cn":"确实的，具体的（而非想象或猜测的）","ex":{"en":"concrete evidence/proposals/proof","cn":"确凿的证据；具体的建议；确实的证明"}},{"en":"a concrete object is one that you can see and feel","cn":"有形的；实在的"},{"en":"building material that is made by mixing together cement, sand, small stones and water","cn":"混凝土","lab":"figurative","ex":{"en":"a slab of concrete","cn":"混凝土板"},"pos":"noun"},{"en":"to cover something with concrete","cn":"用混凝土覆盖","ex":{"en":"The garden had been concreted over.","cn":"花园里铺设了混凝土。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"混凝土","en":"Concrete is a substance used for building which is made by mixing together cement, sand, small stones, and water.","ex":{"en":"The posts have to be set in concrete","cn":"这些柱子必须用混凝土固定。"}},{"pos":"VERB 动词","cn":"用混凝土浇筑(或覆盖)","en":"When you concrete something such as a path, you cover it with concrete.","ex":{"en":"He merely cleared and concreted the floors.","cn":"他只是把地面清理之后浇上了混凝土。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"具体的;确实的","en":"You use concrete to indicate that something is definite and specific.","ex":{"en":"He had no concrete evidence","cn":"他没有确凿的证据。"}},{"pos":"ADJ 形容词","cn":"实在的;有形的","en":"A concrete object is a real, physical object.","ex":{"en":"...using concrete objects to teach addition and subtraction.","cn":"用实物来教加减法"}},{"pos":"ADJ 形容词","cn":"(名词)具体的","en":"A concrete noun is a noun that refers to a physical object rather than to a quality or idea."},{"pos":"PHRASE 短语","cn":"(计划或观点)固定的，不变的","en":"If a plan or idea is set in concrete or embedded in concrete, it is fixed and cannot be changed.","ex":{"en":"As Mr Blunkett emphasised, nothing is yet set in concrete.","cn":"正如布伦基特先生所强调的，一切都还没有定下来。"}}]},"examples":[{"en":"‘It's only a suspicion,’ she said, ‘nothing concrete.’ “","cn":"那只是怀疑，”她说，“没有任何确实的依据。”"},{"en":"It is easier to think in concrete terms rather than in the abstract.","cn":"结合具体的事物来思考要比抽象思考容易些。"}]},"constituency":{"oxford":{"phon":"kənˈstɪtʃuənsi","pos":"noun","senses":[{"en":"a district that elects its own representative to parliament","cn":"（选举议会议员的）选区","g":"[countable]","lab":"especially British English","ex":{"en":"Unemployment is high in her constituency.","cn":"她的选区失业人数众多。"}},{"en":"the people who live in and vote in a particular district","cn":"选区的选民","g":"[countable + singular or plural verb]","ex":{"en":"constituency opinion","cn":"选区选民的意见"}},{"en":"a particular group of people in society who are likely to support a person, an idea or a product","cn":"（统称）支持者","g":"[countable + singular or plural verb]","ex":{"en":"There is a strong constituency of support for his proposal.","cn":"他的提议得到了很多选民的支持。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(选举议员或政府代表的)选区","en":"A constituency is an area for which someone is elected as the representative in a parliament or government."},{"pos":"N-COUNT 可数名词","cn":"(政党或政治家的)支持者群体，拥护者群体","en":"A particular constituency is a section of society that may give political support to a particular party or politician.","ex":{"en":"Mr Jackson had a natural constituency among American blacks","cn":"杰克逊先生在美国黑人中拥有自发的支持。"}}]},"media":{"uk":"media/uk/xconstituency__gb_1.mp3","us":"media/us/xconstituency__us_1.mp3"},"examples":[{"en":"He owns a house in his Darlington constituency.","cn":"他在自己的选区达灵顿拥有一座房子。"},{"en":"Unemployment is high in her constituency.","cn":"她的选区的失业人数居高不下。"}]},"container":{"oxford":{"phon":"kənˈteɪnə(r)","pos":"noun","senses":[{"en":"a box, bottle, etc. in which something can be stored or transported","cn":"容器","ex":{"en":"a plastic container","cn":"塑料容器"}},{"en":"a large metal or wooden box of a standard size in which goods are packed so that they can easily be lifted onto a ship, train, etc. to be transported","cn":"集装箱；货柜","ex":{"en":"a shipping container","cn":"集装箱"}},{"en":"a box or pot made of wood, clay, plastic, etc. for growing plants in","cn":"花盆","ex":{"en":"Planting bulbs in containers is a great alternative if you don't have a garden.","cn":"如果没有花园，在花盆里种植球茎是一个很棒的选择。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"容器","en":"A container is something such as a box or bottle that is used to hold or store things in.","ex":{"en":"...the plastic containers in which fish are stored and sold.","cn":"储藏、出售鱼的塑料容器"}},{"pos":"N-COUNT 可数名词","cn":"集装箱;货柜","en":"A container is a very large metal or wooden box used for transporting goods so that they can be loaded easily onto ships and lorries."}]},"media":{"img":["media/pic/shipsandboats_comp.jpg","media/thumb/container.jpg"],"uk":"media/uk/xcontainer__gb_1.mp3","us":"media/us/xcontainer__us_1.mp3"},"examples":[{"en":"Food will last longer if kept in an airtight container.","cn":"如果贮藏在密封的容器里，食物能保存比较久的时间。"},{"en":"a container ship (= one designed to transport such containers)","cn":"集装箱船"}]},"commerce":{"oxford":{"phon":"ˈkɒmɜːs","pos":"noun","senses":[{"en":"trade, especially between countries; the buying and selling of goods and services","cn":"（尤指国家间的）贸易；商业；商务","ex":{"en":"Leaders of industry and commerce met at the summit in Paris.","cn":"工商界领导人在巴黎首脑会议上会面。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"商业;贸易","en":"Commerce is the activities and procedures involved in buying and selling things.","ex":{"en":"They have made their fortunes from industry and commerce.","cn":"他们靠工商业发了财。"}}]},"media":{"uk":"media/uk/commerce__gb_1.mp3","us":"media/us/commerce__us_1.mp3"},"examples":[{"en":"leaders of industry and commerce","cn":"工商界领导人"},{"en":"measures promoting local commerce and industry","cn":"促进地方工商业发展的措施"}]},"covering":{"media":{"uk":"media/uk/covering__gb_1.mp3","us":"media/us/covering__us_1.mp3"},"oxford":{"phon":"ˈkʌvərɪŋ","pos":"noun","senses":[{"en":"a layer of something that covers something else","cn":"（一层）覆盖层，遮盖物","ex":{"en":"a thick covering of snow on the ground","cn":"地上厚厚的一层积雪"}},{"en":"a layer of material such as carpet or wallpaper, used to cover, decorate and protect floors, walls, etc.","cn":"装饰（或保护）性覆盖物","ex":{"en":"floor/wall coverings","cn":"地板／墙壁覆盖物"}},{"en":"a piece of material that covers something","cn":"覆盖某物的一块（或一片）材料","ex":{"en":"He pulled the plastic covering off the dead body.","cn":"他拉掉了盖在尸体上的塑料布。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(用来保护或隐藏的)覆盖物，遮盖物","en":"A covering is a layer of something that protects or hides something else.","ex":{"en":"Leave a thin covering of fat","cn":"留下薄薄一层脂肪。"}}]},"examples":[{"en":"He pulled the plastic covering off the dead body.","cn":"他拉掉了盖在尸体上的塑料布。"},{"en":"a thick covering of snow on the ground","cn":"地上厚厚的一层积雪"}],"base":"cover"},"consider":{"media":{"uk":"media/uk/xconsider__gb_1.mp3","us":"media/us/xconsider__us_1.mp3"},"oxford":{"phon":"kənˈsɪdə(r)","pos":"verb","senses":[{"en":"to think about something carefully, especially in order to make a decision","cn":"（尤指为作出决定而）仔细考虑，细想","g":"[intransitive, transitive]","ex":{"en":"I'd like some time to consider.","cn":"我希望有些时间考虑一下。"}},{"en":"to think of somebody/something in a particular way","cn":"把…看作；认为","g":"[transitive]","ex":{"en":"I consider her a friend.","cn":"我把她当朋友。"}},{"en":"to think about something, especially the feelings of other people, and be influenced by it when making a decision, etc.","cn":"体谅；考虑到；顾及","g":"[transitive]","ex":{"en":"You should consider other people before you act.","cn":"你在行动之前应当考虑到别人。"}},{"en":"to look carefully at somebody/something","cn":"端详；注视","g":"[transitive]","lab":"formal","ex":{"en":"He stood there, considering the painting.","cn":"他站在那里，凝视着那幅画。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"认为;看待","en":"If you consider a person or thing to be something, you have the opinion that this is what they are.","ex":{"en":"We don't consider our customers to be mere consumers; we consider them to be our friends","cn":"我们没有把客户仅仅看作是消费者;我们还把他们当作朋友。"}},{"pos":"VERB 动词","cn":"考虑;斟酌","en":"If you consider something, you think about it carefully.","ex":{"en":"The government is being asked to consider a plan to fix the date of the Easter break","cn":"人们要求政府考虑确定复活节假期日期的计划。"}},{"pos":"VERB 动词","cn":"打算;考虑","en":"If you are considering doing something, you intend to do it, but have not yet made a final decision whether to do it.","ex":{"en":"I had seriously considered telling the story from the point of view of the wives","cn":"我认真考虑过从为人妻者的视角来讲述这个故事。"}},{"pos":"PHRASE 短语","cn":"通盘考虑;从各方面考虑","en":"You say all things considered to indicate that you are making a judgment after taking all the facts into account.","ex":{"en":"All things considered, I think you have behaved marvellously in coming here.","cn":"从各方面考虑，我认为你来这儿是一个非常明智的举动。"}}]},"examples":[{"en":"She's had a lot of problems since her husband died but she seems quite cheerful, all things considered.","cn":"自从丈夫死后，她面临很多困难，但总的来说她看上去情绪还是满乐观的。"},{"en":"It is considered that the proposed development would create much-needed jobs.","cn":"人们认为所提出的发展计划将创造急需的就业机会。"}]},"containers":{"lemma":"container"},"count":{"media":{"uk":"media/uk/count__gb_1.mp3","us":"media/us/count__us_1.mp3"},"oxford":{"phon":"kaʊnt","pos":"verb","senses":[{"en":"to say numbers in the correct order","cn":"（按顺序）数数","g":"[intransitive]","sc":"say numbers","ex":{"en":"Billy can't count yet.","cn":"比利还不会数数。"}},{"en":"to calculate the total number of people, things, etc. in a particular group","cn":"计算（或清点）总数","g":"[transitive, intransitive]","sc":"find total","ex":{"en":"They're still counting votes in Texas.","cn":"得克萨斯州还在计票。"}},{"en":"to include somebody/something when you calculate a total","cn":"把…算入；包括","g":"[transitive]","sc":"include","ex":{"en":"We have invited 50 people, not counting the children.","cn":"不算小孩，我们邀请了 50 人。"}},{"en":"to be important","cn":"重要","g":"[intransitive]","sc":"matter","ex":{"en":"It is going to be a close election, so every vote counts.","cn":"这将是一场势均力敌的选举，所以每一张选票都很重要。"}},{"en":"to be officially accepted; to accept something officially","cn":"（被）正式接纳，正式认可","g":"[intransitive, transitive]","sc":"accept officially","ex":{"en":"Don't go over that line or your throw won't count.","cn":"别越过那条线，否则你的投掷就会被判无效。"}},{"en":"to consider somebody/something in a particular way; to be considered in a particular way","cn":"认为；看作；算作；被视为","g":"[intransitive, transitive]","sc":"consider","ex":{"en":"For tax purposes that money counts/is counted as income.","cn":"那笔钱算作收入，需要纳税。"}},{"en":"an act of counting to find the total number of somebody/something","cn":"数出总数","g":"[usually singular]","sc":"total","ex":{"en":"If the election result is close, there will be a second count.","cn":"如果选举结果很接近，将进行第二次计票。"},"pos":"noun"},{"en":"an act of saying numbers in order beginning with 1","cn":"（按顺序的）数数，点数","g":"[usually singular]","sc":"saying numbers","ex":{"en":"Raise your leg and hold for a count of ten.","cn":"抬起一条腿，保持这一姿势，直至数到十。"},"pos":"noun"},{"en":"a measurement of the amount of something contained in a particular substance or area","cn":"（某物质在某物或面积中）量的计数","g":"[usually singular]","lab":"specialist","sc":"measurement","ex":{"en":"a raised white blood cell count","cn":"升高了的白血球数"},"pos":"noun"},{"en":"a crime that somebody is accused of committing","cn":"（被指控的）罪状，事项","lab":"law","sc":"crime","ex":{"en":"They were found guilty on all counts.","cn":"他们被判各项罪名成立。"},"pos":"noun"},{"en":"a point made during a discussion or an argument","cn":"（讨论或争论的）论点，观点，问题，事项","g":"[usually plural]","sc":"in discussion/argument","ex":{"en":"I disagree with you on both counts.","cn":"我对你的两个观点均不敢苟同。"},"pos":"noun"},{"en":"a nobleman of high rank, similar to an earl in the UK","cn":"伯爵（相当于英国 earl 的贵族封号）","sc":"rank/title","ex":{"en":"Count Tolstoy","cn":"托尔斯泰伯爵"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT; N-TITLE; N-VOC可数名词；头衔名词；称呼名词","cn":"(欧洲的)伯爵","en":"A Count is a European nobleman with the same rank as an English earl.","ex":{"en":"Her father was a Polish Count.","cn":"她的父亲是波兰的一位伯爵。"}}]},"examples":[{"en":"The movie's ticket sales add up to $39 million, and counting.","cn":"这部电影的票房共 3 900 万元，还在继续上升。"},{"en":"I hear you're organizing a trip to the game next week? Count me in!","cn":"我听说你们将在下周组织旅行去看比赛？把我也算上！"}]},"coach":{"media":{"img":["media/pic/buses_comp.jpg","media/thumb/bus.jpg"],"uk":"media/uk/coach__gb_1.mp3","us":"media/us/coach__us_1.mp3"},"oxford":{"phon":"kəʊtʃ","pos":"noun","senses":[{"en":"a person who trains a person or team in sport","cn":"（体育运动的）教练","g":"[countable]","ex":{"en":"the head/assistant coach","cn":"主教练；助理教练"}},{"en":"a person who gives private lessons to somebody, often to prepare them for an exam","cn":"私人教师；（多指）考前辅导教师","g":"[countable]","ex":{"en":"a maths coach","cn":"数学应试辅导教师"}},{"en":"a person who is employed by somebody to give them advice about how to achieve the things they want in their life and work","cn":"人生教练，生涯顾问（受雇帮助他人实现人生和工作目标）","g":"[countable]"},{"en":"a comfortable bus for carrying passengers over long distances","cn":"长途汽车；长途客车","g":"[countable]","lab":"British English","ex":{"en":"to take/get a coach","cn":"乘长途汽车"}},{"en":"a separate section of a train for carrying passengers","cn":"（火车的）客车厢","g":"[countable]","lab":"both British English","ex":{"en":"a railway coach","cn":"火车车厢"}},{"en":"a large closed vehicle with four wheels, pulled by horses, used in the past for carrying passengers","cn":"（旧时载客的）四轮大马车","g":"[countable]","ex":{"en":"This is the old coach road.","cn":"这是旧时的马车道。"}},{"en":"the cheapest seats in a plane","cn":"（客机的）经济舱","g":"[uncountable]","lab":"North American English","ex":{"en":"to fly coach","cn":"坐飞机经济舱"}},{"en":"to train somebody to play a sport, to do a job better, or to improve a skill","cn":"（对体育运动、工作或技能进行）训练，培训，指导","ex":{"en":"He has coached the team for five years.","cn":"他执教这个队已经五年了。"},"pos":"verb"},{"en":"to give a student extra teaching in a particular subject especially so that they will pass an exam","cn":"辅导（尤指为让学员通过考试）","lab":"especially British English","pos":"verb"},{"en":"to give somebody special instructions for what they should do or say in a particular situation","cn":"指示；特殊指导；专门传授","ex":{"en":"They believed the witnesses had been coached on what to say.","cn":"他们认为证人所作的证词是别人教他们那样说的。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"教练","en":"A coach is someone who trains a person or team of people in a particular sport.","ex":{"en":"Tony Woodcock has joined German amateur team SC Brueck as coach.","cn":"托尼·伍德科克加盟德国业余队SC布吕克队担任教练。"}},{"pos":"VERB 动词","cn":"为…当教练;训练;指导","en":"When someone coaches a person or a team, they help them to become better at a particular sport.","ex":{"en":"Beckenbauer coached the West Germans to success in the World Cup final in Italy","cn":"贝肯鲍尔执教西德队，带领他们在意大利世界杯决赛中获胜。"}},{"pos":"N-COUNT 可数名词","cn":"(体育队的)主教练","en":"A coach is a person who is in charge of a sports team."},{"pos":"N-COUNT 可数名词","cn":"(棒球运动中，站在一垒或三垒附近，给其他选手信号的)跑垒指挥员","en":"In baseball, a coach is a member of a team who stands near the first or third base, and gives signals to other members of the team who are on bases and are trying to score."},{"pos":"N-COUNT 可数名词","cn":"(尤指辅导备考的)私人教师，辅导教师","en":"A coach is someone who gives people special teaching in a particular subject, especially in order to prepare them for an examination.","ex":{"en":"What you need is a drama coach.","cn":"你需要的是一位戏剧辅导老师。"}},{"pos":"VERB 动词","cn":"给…补习;(尤指)为…辅导备考","en":"If you coach someone, you give them special teaching in a particular subject, especially in order to prepare them for an examination.","ex":{"en":"He gently coached me in French.","cn":"他为我补习法语，态度十分温和。"}},{"pos":"N-COUNT 可数名词","cn":"长途汽车;长途大巴","en":"A coach is a large, comfortable bus that carries passengers on long journeys.","ex":{"en":"As we headed back to Calais, the coach was badly delayed by roadworks","cn":"返回加来时，由于道路施工，我们乘坐的长途大巴严重误点。"}},{"pos":"N-COUNT 可数名词","cn":"(火车的)旅客车厢","en":"A coach is one of the separate sections of a train that carries passengers.","ex":{"en":"The train was an elaborate affair of sixteen coaches.","cn":"这列火车由16节车厢组成，设计复杂精巧。"}},{"pos":"N-COUNT 可数名词","cn":"四轮大马车，公共马车(旧时用于载客，现在英国等国仍用于庆典场合)","en":"A coach is an enclosed vehicle with four wheels which is pulled by horses, and in which people used to travel. Coaches are still used for ceremonial events in some countries, such as Britain."}]},"examples":[{"en":"They believed the witnesses had been coached on what to say.","cn":"他们认为证人所作的证词是别人教他们那样说的。"},{"en":"Her father coached her for the Olympics.","cn":"她的父亲训练她准备参加奥林匹克运动会。"}]},"couch":{"media":{"uk":"media/uk/couch__gb_1.mp3","us":"media/us/couch__us_1.mp3","img":["media/ldoce/img/sofa.jpg"]},"oxford":{"phon":"kaʊtʃ","pos":"noun","senses":[{"en":"a long comfortable seat for two or more people to sit on","cn":"长沙发；长榻","ex":{"en":"He was sprawled on the living-room couch watching TV.","cn":"他四肢舒展地躺在客厅沙发上看电视。"}},{"en":"a long piece of furniture like a bed, especially in a doctor’s office","cn":"（尤指诊室内的）诊察台","ex":{"en":"He spends several hours a week on the therapist's couch.","cn":"他每周在治疗师的沙发上度过几个小时。"}},{"en":"to say or write words in a particular style or manner","cn":"（用某种文体或方式）表达，措辞","ex":{"en":"The letter was deliberately couched in very vague terms.","cn":"这封信故意写得含糊其词。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"长沙发;长榻","en":"A couch is a long, comfortable seat for two or three people."},{"pos":"N-COUNT 可数名词","cn":"(病人接受检查或治疗时的)诊察台","en":"A couch is a narrow bed which patients lie on while they are being examined or treated by a doctor."},{"pos":"VERB 动词","cn":"(以某种语言风格)表达，措词","en":"If a statement is couched in a particular style of language, it is expressed in that style of language.","ex":{"en":"The new centre-right government's radical objectives are often couched in moderate terms","cn":"新的中右翼政府经常以温和的语言表述其激进的目标。"}}]},"examples":[{"en":"The letter was deliberately couched in very vague terms.","cn":"这封信故意写得含糊其词。"},{"en":"on the psychiatrist's couch","cn":"在精神病医生的诊察台上"}]},"conjure":{"media":{"uk":"media/uk/xconjure__gb_1.mp3","us":"media/us/xconjure__us_1.mp3"},"oxford":{"phon":"ˈkʌndʒə(r)","pos":"verb","senses":[{"en":"to do clever tricks such as making things seem to appear or disappear as if by magic","cn":"变魔术；变戏法；使…变戏法般地出现（或消失）","ex":{"en":"Her grandfather taught her to conjure.","cn":"她的祖父教她变魔术。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"变魔术般地创造出","en":"If you conjure something out of nothing, you make it appear as if by magic.","ex":{"en":"Thirteen years ago she found herself having to conjure a career from thin air","cn":"13年前，她认识到自己得白手起家创造出一番事业来。"}},{"pos":"PHRASE 短语","cn":"重要人物(或组织)的名字;有影响力的名字","en":"If you say that the name of a particular person or organization is a name to conjure with, you mean that that person or organization is very important and influential in the field you are discussing.","ex":{"en":"By 1920, Fox and Universal were already names to conjure with.","cn":"到1920年，福克斯和环球已经声名显赫。"}},{"pos":"","cn":"","en":"相关词组：conjure up"}]},"examples":[{"en":"That smell always conjures up memories of holidays in France.","cn":"那种气味总是令人勾起在法国度假那段日子的回忆。"},{"en":"He conjured a delicious meal out of a few leftovers.","cn":"他居然用几样吃剩的东西做出了可口的一餐。"}]},"covered":{"media":{"uk":"media/uk/covered__gb_1.mp3","us":"media/us/covered__us_1.mp3"},"oxford":{"phon":"ˈkʌvəd","pos":"adjective","senses":[{"en":"having a layer or amount of something on it","cn":"盖着一层；盖满","g":"[not before noun]","ex":{"en":"His face was covered in blood.","cn":"他满脸是血。"}},{"en":"having a roof over it","cn":"有顶的","ex":{"en":"a covered walkway/bridge","cn":"有顶篷的人行道；廊桥"}},{"en":"having a layer of the thing mentioned on or around something","cn":"被…覆盖的","ex":{"en":"chocolate-covered banana slices","cn":"巧克力香蕉片"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有顶的","en":"A covered area is an area that has a roof.","ex":{"en":"There are 40 shops, cafes and restaurants in a covered mall.","cn":"这家室内购物中心里有40家商店、咖啡馆和饭店。"}}]},"examples":[{"en":"a covered area of the stadium with seats","cn":"体育场有顶的座席区域"},{"en":"The walls were covered with pictures.","cn":"这些墙上挂满了画。"}],"base":"cover"},"complete":{"media":{"uk":"media/uk/complete__gb_1.mp3","us":"media/us/complete__us_1.mp3"},"oxford":{"phon":"kəmˈpliːt","pos":"adjective","senses":[{"en":"including all the parts, etc. that are necessary; whole","cn":"全部的；完整的；整个的","ex":{"en":"a complete list/sequence/picture/profile","cn":"完整列表／序列／图片／介绍"}},{"en":"finished","cn":"完成；结束","g":"[not before noun]","ex":{"en":"The job is almost complete.","cn":"工作即将完成。"}},{"en":"used when you are emphasizing something, to mean ‘to the greatest degree possible’","cn":"（用以强调）完全的，彻底的","g":"[usually before noun]","ex":{"en":"We were in complete agreement.","cn":"我们意见完全一致。"}},{"en":"including something as an extra part or feature","cn":"包括，含有（额外部分或特征）","g":"[not before noun]","ex":{"en":"The furniture comes complete with tools and instructions for assembly.","cn":"这件家具备有组装工具和说明书。"}},{"en":"to finish making or doing something","cn":"完成；结束","ex":{"en":"to complete a course/project","cn":"完成课程／项目"},"pos":"verb"},{"en":"to write all the information you are asked for on a form","cn":"填写（表格）","ex":{"en":"2 000 shoppers completed our questionnaire.","cn":"2 000 名顾客填写了我们的调查表。"},"pos":"verb"},{"en":"to make something whole or perfect","cn":"使完整；使完美","ex":{"en":"I only need one more card to complete the set.","cn":"我只差一张卡片就配齐全套了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"完全的;十足的","en":"You use complete to emphasize that something is as great in extent, degree, or amount as it possibly can be.","ex":{"en":"The rebels had taken complete control","cn":"叛乱分子完全控制了局面。"}},{"pos":"ADJ 形容词","cn":"完整的;全部的;整个的","en":"You can use complete to emphasize that you are referring to the whole of something and not just part of it.","ex":{"en":"A complete tenement block was burnt to the ground","cn":"整幢公寓大楼被付之一炬。"}},{"pos":"ADJ 形容词","cn":"齐全的;完整的","en":"If something is complete, it contains all the parts that it should contain.","ex":{"en":"The list may not be complete.","cn":"这个单子可能不全。"}},{"pos":"VERB 动词","cn":"使齐全;使完整","en":"To complete a set or group means to provide the last item that is needed to make it a full set or group.","ex":{"en":"Children don't complete their set of 20 baby teeth until they are two to three years old.","cn":"小孩要到两三岁才会长齐20颗乳牙。"}},{"pos":"ADJ 形容词","cn":"(作品)全部的，完整的","en":"The complete works of a writer are all their books or poems published together in one book or as a set of books.","ex":{"en":"...the Complete Works of William Shakespeare.","cn":"《威廉·莎士比亚全集》"}},{"pos":"PREP-PHRASE 短语介词","cn":"配有…的;兼有…的","en":"If one thing comes complete with another, it has that thing as an extra or additional part.","ex":{"en":"The diary comes complete with a gold-coloured ballpoint pen.","cn":"这个日记本配有一支金色的圆珠笔。"}},{"pos":"ADJ 形容词","cn":"完成的;结束的","en":"If something is complete, it has been finished.","ex":{"en":"The work of restoring the farmhouse is complete","cn":"修复农舍的工作已经完成。"}},{"pos":"VERB 动词","cn":"结束;完成","en":"If you complete something, you finish doing, making, or producing it.","ex":{"en":"Peter Mayle has just completed his first novel.","cn":"彼得·梅尔刚刚完成他的第一部小说。"}},{"pos":"VERB 动词","cn":"全部完成","en":"If you complete something, you do all of it.","ex":{"en":"She completed her degree in two years","cn":"她用两年的时间修完了课程，拿到了学位。"}},{"pos":"VERB 动词","cn":"填写(表格或问卷)","en":"If you complete a form or questionnaire, you write the answers or information asked for in it.","ex":{"en":"Simply complete the coupon below","cn":"填写下面的订货单即可。"}},{"pos":"ADJ 形容词","cn":"全面的;全能的","en":"You can use complete to emphasize that someone is skilled at all aspects of a particular activity and is therefore the best example of that kind of person.","ex":{"en":"He was the complete all-round journalist.","cn":"他是一名全能的记者。"}}]},"examples":[{"en":"You will receive payment for each complete day that you work.","cn":"你将按你每一整天的工作领取报酬。"},{"en":"The book, complete with CD, costs £35.","cn":"此书包括光盘，售价 35 英镑。"}]},"complementary":{"media":{"uk":"media/uk/complementary__gb_1.mp3","us":"media/us/complementary__us_1.mp3"},"oxford":{"phon":"ˌkɒmplɪˈmentri","pos":"adjective","senses":[{"en":"two people or things that are complementary are different but together form a useful or attractive combination of skills, qualities or physical features","cn":"互补的；补充的；相互补足的","ex":{"en":"The school's approach must be complementary to that of the parents.","cn":"学校与家长的教育方法必须相辅相成。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"相互补充的;相辅相成的","en":"Complementary things are different from each other but make a good combination.","ex":{"en":"To improve the quality of life through work, two complementary strategies are necessary","cn":"想通过工作提高生活质量，需要两个相辅相成的策略。"}},{"pos":"ADJ 形容词","cn":"补充医学的(不同于西医的治疗方法，如针灸、顺势疗法)","en":"Complementary medicine refers to ways of treating patients which are different from the ones used by most Western doctors, for example acupuncture and homoeopathy.","ex":{"en":"...combining orthodox treatment with a wide range of complementary therapies.","cn":"把传统的治疗方法与各种补充疗法结合"}}]},"examples":[{"en":"The school's approach must be complementary to that of the parents.","cn":"学校与家长的教育方法必须相辅相成。"},{"en":"The computer and the human mind have different but complementary abilities.","cn":"电脑与人脑各不相同﹐却又互为补充。"}]},"convinced":{"media":{"uk":"media/uk/xconvinced__gb_1.mp3","us":"media/us/xconvinced__us_1.mp3"},"oxford":{"phon":"kənˈvɪnst","pos":"adjective","senses":[{"en":"completely sure about something","cn":"坚信；深信；确信","g":"[not before noun]","ex":{"en":"Sam nodded but he didn't look convinced.","cn":"萨姆点了点头，可他看起来并没有信服。"}},{"en":"believing strongly in a particular religion or set of political ideas","cn":"坚信不移的；有坚定宗教信仰（或政治信念）的","g":"[only before noun]","ex":{"en":"a convinced Christian","cn":"虔诚的基督徒"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"确信的;深信的;坚信的","en":"If you are convinced that something is true, you feel sure that it is true.","ex":{"en":"He was convinced that I was part of the problem","cn":"他确信我就是问题的一部分。"}}]},"examples":[{"en":"Sam nodded but he didn't look convinced.","cn":"萨姆点了点头，可他看起来并没有信服。"},{"en":"I am convinced of her innocence.","cn":"我坚信她是清白无辜的。"}],"base":"convince"},"confine":{"oxford":{"phon":"kənˈfaɪn","pos":"verb","senses":[{"en":"to keep somebody/something inside the limits of a particular activity, subject, area, etc.","cn":"限制；限定","g":"[often passive]","ex":{"en":"The work will not be confined to the Glasgow area.","cn":"此项工作不会局限于格拉斯哥地区。"}},{"en":"to keep a person or an animal in a small or closed space","cn":"监禁；禁闭","g":"[usually passive]","ex":{"en":"Keep the dog confined in a suitable travelling cage.","cn":"把狗关进适于旅行的笼子里。"}},{"en":"to have to stay in bed, in a wheelchair, etc.","cn":"使离不开（或受困于床、轮椅等）","ex":{"en":"She was confined to bed with the flu.","cn":"她因患流感卧病在床。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"限制，限定（防止扩散蔓延）","en":"To confine something to a particular place or group means to prevent it from spreading beyond that place or group.","ex":{"en":"Health officials have successfully confined the epidemic to the Tabatinga area","cn":"卫生官员成功地将疫情控制在塔巴廷加地区。"}},{"pos":"VERB 动词","cn":"限制(自己或自己的活动);使受局限","en":"If you confine yourself or your activities to something, you do only that thing and are involved with nothing else.","ex":{"en":"He did not confine himself to the one language","cn":"他没把自己局限于这一门语言。"}},{"pos":"VERB 动词","cn":"监禁;关押；禁闭","en":"If someone is confined to a mental institution, prison, or other place, they are sent there and are not allowed to leave for a period of time.","ex":{"en":"The woman will be confined to a mental institution","cn":"这个女人将被关进精神病院。"}},{"pos":"N-PLURAL 复数名词","cn":"边界;界限;范围","en":"Something that is within the confines of an area or place is within the boundaries enclosing it.","ex":{"en":"The movie is set entirely within the confines of the abandoned factory.","cn":"电影的拍摄完全是在这个废弃的工厂厂区内进行。"}},{"pos":"N-PLURAL 复数名词","cn":"限制;局限","en":"The confines of a situation, system, or activity are the limits or restrictions it involves.","ex":{"en":"...away from the confines of the British class system","cn":"超越英国社会等级制度的限制"}}]},"media":{"uk":"media/uk/xconfine__gb_1.mp3","us":"media/us/xconfine__us_1.mp3"},"examples":[{"en":"I will confine myself to looking at the period from 1900 to 1916.","cn":"我将把自己考察的范围限定在 1900 年至 1916 年这段时间以内。"},{"en":"The soldiers concerned were confined to barracks (= had to stay in the barracks , as a punishment).","cn":"有关的士兵已受到禁闭在营房的处分。"}]},"coins":{"lemma":"coin","media":{"img":["media/pic/money_comp.jpg","media/thumb/coin.jpg"],"uk":"media/uk/coin__gb_1.mp3","us":"media/us/coin__us_1.mp3"}},"cooker":{"oxford":{"phon":"ˈkʊkə(r)","pos":"noun","senses":[{"en":"a large piece of equipment for cooking food, containing an oven and gas or electric rings on top","cn":"（带烤箱、燃气炉或电炉的）厨灶，炉具","ex":{"en":"a gas cooker","cn":"燃气厨灶"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"炉灶;灶具","en":"A cooker is a large metal device for cooking food using gas or electricity. A cooker usually consists of a grill, an oven, and some gas or electric rings.","ex":{"en":"...a gas cooker.","cn":"煤气灶"}}]},"media":{"uk":"media/uk/cooker__gb_1.mp3","us":"media/us/cooker__us_1.mp3"},"examples":[{"en":"a gas cooker","cn":"燃气厨灶"},{"en":"an electric cooker","cn":"电灶"}]},"coquetry":{"media":{"uk":"media/uk/coquetry__gb_1.mp3","us":"media/us/coquetry__us_1.mp3"},"oxford":{"phon":"ˈkɒkɪtri","pos":"noun","senses":[{"en":"behaviour that is intended to be sexually attractive but is not very serious","cn":"卖弄风情，调情"}]}},"complimentary":{"media":{"uk":"media/uk/complimentary__gb_1.mp3","us":"media/us/complimentary__us_1.mp3"},"oxford":{"phon":"ˌkɒmplɪˈmentri","pos":"adjective","senses":[{"en":"given free","cn":"免费的；赠送的","ex":{"en":"complimentary tickets for the show","cn":"演出赠券"}},{"en":"expressing approval, praise, etc.","cn":"表示钦佩的；赞美的","ex":{"en":"After one or two complimentary remarks about her hosts, she got to the main part of her speech.","cn":"在对东道主说了一两句赞美之后，她就进入了演讲的主要部分。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"赞美的;赞扬的","en":"If you are complimentary about something, you express admiration for it.","ex":{"en":"The staff have been very complimentary, and so have the customers","cn":"员工们对此大加赞扬，顾客们也一样。"}},{"pos":"ADJ 形容词","cn":"(座位、票或书)免费赠送的","en":"A complimentary seat, ticket, or book is given to you free.","ex":{"en":"He had complimentary tickets to take his wife to see the movie.","cn":"他有几张赠票，可以带妻子去看电影。"}}]},"examples":[{"en":"She was extremely complimentary about his work.","cn":"她对他的工作给予了高度评价。"},{"en":"a complimentary remark","cn":"赞美的言辞"}]},"compass":{"oxford":{"phon":"ˈkʌmpəs","pos":"noun","senses":[{"en":"an instrument for finding direction, with a needle that always points to the north","cn":"罗盘；罗经；指南针；罗盘仪","g":"[countable]","ex":{"en":"a map and compass","cn":"地图和指南针"}},{"en":"an instrument with two long thin parts joined together at the top, used for drawing circles and measuring distances on a map","cn":"圆规；两脚规","g":"[countable]","ex":{"en":"a pair of compasses","cn":"一副圆规"}},{"en":"a range or an extent, especially of what can be achieved in a particular situation","cn":"范围；范畴；界限","g":"[singular]","lab":"formal","ex":{"en":"the compass of a singer’s voice (= the range from the lowest to the highest note that they can sing)","cn":"歌手的音域"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"指南针;罗盘","en":"A compass is an instrument that you use for finding directions. It has a dial and a magnetic needle that always points to the north.","ex":{"en":"We had to rely on a compass and a lot of luck to get here.","cn":"我们不得不依靠指南针和不错的运气找到这儿来。"}},{"pos":"N-PLURAL 复数名词","cn":"圆规","en":"Compasses are a hinged V-shaped instrument that you use for drawing circles."},{"pos":"N-COUNT 可数名词","cn":"界限;范围","en":"If something is within the compass of something or someone, it is within their limits or abilities.","ex":{"en":"Within the compass of a normal sized book such a comprehensive survey was not practicable.","cn":"在通常一本书的篇幅中要作如此全面的调查不太实际。"}}]},"media":{"img":["media/ldoce/img/compass.jpg","media/pic/compasses.jpg"],"uk":"media/uk/compass__gb_1.mp3","us":"media/us/compass__us_1.mp3"},"examples":[{"en":"the points of the compass (= N, S, E, W, etc.)","cn":"罗经方位点（东、南、西、北等）"},{"en":"the compass of a singer's voice (= the range from the lowest to the highest note that he or she can sing)","cn":"歌手的音域"}]},"comedian":{"media":{"uk":"media/uk/comedian__gb_1.mp3","us":"media/us/comedian__us_1.mp3"},"oxford":{"phon":"kəˈmiːdiən","pos":"noun","senses":[{"en":"a person whose job is to make people laugh by giving a funny performance, for example by telling jokes or funny stories","cn":"（讲笑话或趣事的）滑稽演员","ex":{"en":"He started out as a stand-up comedian in Liverpool.","cn":"他在利物浦出道时是一个单口喜剧演员。"}},{"en":"a person who is funny or thinks they are funny","cn":"（讲笑话或趣事的）滑稽演员","lab":"often ironic","ex":{"en":"The speaker was a bit of a comedian, so it was an amusing session.","cn":"演讲者有点喜剧演员的味道，所以会议很有趣。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"滑稽演员;喜剧演员","en":"A comedian is an entertainer whose job is to make people laugh, by telling jokes or funny stories."}]},"examples":[{"en":"He started as a stand-up comedian (= someone who tells jokes to an audience ) .","cn":"他最初是一名单口喜剧演员。"},{"en":"You’ll like Matt. He’s a real comedian.","cn":"你会喜欢马特的﹐他这人非常有趣。"}]},"coke":{"media":{"uk":"media/uk/coke__gb_1.mp3","us":"media/us/coke__us_1.mp3"},"oxford":{"phon":"kəʊk","pos":"noun","senses":[{"en":"cocaine (= a powerful drug that some people take illegally for pleasure and can become addicted to. Doctors sometimes use it as an anaesthetic.)","cn":"可卡因","lab":"informal"},{"en":"a black substance that is produced from coal and burnt to provide heat","cn":"焦炭"},{"en":"a popular type of cola drink","cn":"可口可乐（饮料）","ex":{"en":"Can I have a Diet Coke?","cn":"能给我来一罐低热量可乐吗？"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"焦炭;焦煤","en":"Coke is a solid black substance that is produced from coal and is burned as a fuel.","ex":{"en":"...a coke-burning stove.","cn":"烧焦炭的炉子"}},{"pos":"N-UNCOUNT 不可数名词","cn":"同 cocaine","en":"Coke is the same as cocaine ."}]},"examples":[{"en":"Can I have a Diet Coke?","cn":"能给我来一罐低热量可乐吗？"}]},"consumers":{"lemma":"consumer","media":{"uk":"media/uk/xconsumer__gb_1.mp3","us":"media/us/xconsumer__us_1.mp3"}},"corner":{"media":{"uk":"media/uk/corner__gb_1.mp3","us":"media/us/corner__us_1.mp3"},"oxford":{"phon":"ˈkɔːnə(r)","pos":"noun","senses":[{"en":"a part of something where two or more sides, lines or edges join","cn":"角","sc":"of building/object/shape","ex":{"en":"the four corners of a square","cn":"正方形的四个角"}},{"en":"with the number of corners mentioned; involving the number of groups mentioned","cn":"有…角的；涉及…群体的","sc":"-cornered","ex":{"en":"a three-cornered hat","cn":"三角帽"}},{"en":"the place inside a room or a box where two sides join; the area around this place","cn":"角；墙角；壁角","sc":"of room/box","ex":{"en":"A large desk occupies another corner of the room.","cn":"一张大桌子占据了房间的另一个角落。"}},{"en":"a place where two streets join","cn":"街角；拐角","sc":"of roads","ex":{"en":"The wind hit him as he turned the corner.","cn":"他一拐过街角，狂风就向他袭来。"}},{"en":"a sharp bend in a road","cn":"（道路的）急转弯","sc":"of roads","ex":{"en":"The car was taking the corners too fast.","cn":"那车急转弯时开得太快。"}},{"en":"a region or an area of a place (sometimes used for one that is far away or difficult to reach)","cn":"（有时指偏僻或难以到达的）区域，地区","sc":"area/region","ex":{"en":"She lives in a quiet corner of rural Yorkshire.","cn":"她居住在约克郡乡间一个僻静的地方。"}},{"en":"a difficult situation","cn":"困境；窘境","g":"[usually singular]","sc":"difficult situation","ex":{"en":"to back/drive/force somebody into a corner","cn":"把某人逼入困境"}},{"en":"a free kick or hit that you take from the corner of your opponent’s end of the field","cn":"角球","sc":"in sport","ex":{"en":"Moore took the corner.","cn":"穆尔发角球。"}},{"en":"any of the four corners of a ring; the supporters who help in the corner","cn":"场角；（场角处的）辅助人员","sc":"in sport"},{"en":"to get a person or an animal into a place or situation from which they cannot escape","cn":"使（人或动物）走投无路；逼…入绝境","g":"[transitive, often passive]","sc":"trap somebody","ex":{"en":"The man was finally cornered by police in a garage.","cn":"那男人最终被警方逼到了车库里。"},"pos":"verb"},{"en":"to go towards somebody in a determined way, because you want to speak to them","cn":"硬要走近想与（某人）说话","g":"[transitive]","sc":"trap somebody","ex":{"en":"I found myself cornered by her on the stairs.","cn":"我发觉她在楼梯上迎面过来非要与我说话。"},"pos":"verb"},{"en":"to get control of the trade in a particular type of goods","cn":"垄断（某种货品的交易）","g":"[transitive]","sc":"the market","ex":{"en":"They've cornered the market in silver.","cn":"他们垄断了白银市场。"},"pos":"verb"},{"en":"to go around a corner","cn":"转弯；拐弯","g":"[intransitive]","sc":"of vehicle/driver","ex":{"en":"The car corners well (= it is easy to go around corners in it).","cn":"这辆汽车的转弯性能良好。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"角","en":"A corner is a point or an area where two or more edges, sides, or surfaces of something join.","ex":{"en":"He saw the corner of a magazine sticking out from under the blanket","cn":"他看见杂志的一角从毯子下露了出来。"}},{"pos":"N-COUNT 可数名词","cn":"角;墙角;壁角","en":"The corner of a room, box, or similar space is the area inside it where its edges or walls meet.","ex":{"en":"...a card table in the corner of the living room","cn":"起居室角落里的牌桌"}},{"pos":"N-COUNT 可数名词","cn":"（嘴）角;（眼）角","en":"The corner of your mouth or eye is the side of it.","ex":{"en":"She flicked a crumb off the corner of her mouth","cn":"她擦掉嘴角的面包屑。"}},{"pos":"N-COUNT 可数名词","cn":"街角;拐角","en":"The corner of a street is the place where one of its sides ends as it joins another street.","ex":{"en":"She would spend the day hanging round street corners","cn":"她会整天在街角附近游荡。"}},{"pos":"N-COUNT 可数名词","cn":"(道路的)转弯处","en":"A corner is a bend in a road.","ex":{"en":"...a sharp corner","cn":"急转弯"}},{"pos":"N-COUNT 可数名词","cn":"(遥远或难以到达的)角落，偏远处","en":"If you talk about the corners of the world, a country, or some other place, you are referring to places that are far away or difficult to get to.","ex":{"en":"Buyers came from all corners of the world","cn":"买主来自世界各地。"}},{"pos":"N-COUNT 可数名词","cn":"(足球、曲棍球等的)角球","en":"In football, hockey, and some other sports, a corner is a free shot or kick taken from the corner of the pitch."},{"pos":"VERB 动词","cn":"将…逼入死角；使走投无路","en":"If you corner a person or animal, you force them into a place they cannot escape from.","ex":{"en":"A police motorcycle chased his car twelve miles, and cornered him near Rome","cn":"一辆摩托警车跟在他的车后追了12英里，最后在快到罗马时将他截住。"}},{"pos":"VERB 动词","cn":"截住…与其说话","en":"If you corner someone, you force them to speak to you when they have been trying to avoid you.","ex":{"en":"Golan managed to corner the young producer-director for an interview.","cn":"戈兰设法截住了那位兼任制片人的年轻导演，对其进行了采访。"}},{"pos":"VERB 动词","cn":"垄断","en":"If a company or place corners an area of trade, they gain control over it so that no one else can have any success in that area.","ex":{"en":"This restaurant has cornered the Madrid market for specialist paellas","cn":"这家餐馆垄断了马德里的特色肉菜饭市场。"}},{"pos":"VERB 动词","cn":"转弯；拐弯","en":"If a car, or the person driving it, corners in a particular way, the car goes round bends in roads in this way.","ex":{"en":"Peter drove jerkily, cornering too fast and fumbling the gears.","cn":"彼得转弯太急，换挡不利索，车开得一颠一颠的。"}},{"pos":"PHRASE 短语","cn":"即将发生","en":"If you say that something is around the corner, you mean that it will happen very soon. In British English, you can also say that something is round the corner .","ex":{"en":"The Chancellor of the Exchequer says that economic recovery is just around the corner.","cn":"财政大臣说经济即将复苏。"}},{"pos":"PHRASE 短语","cn":"在附近;在近处","en":"If you say that something is around the corner, you mean that it is very near. In British English, you can also say that something is round the corner .","ex":{"en":"My new place is just around the corner.","cn":"我的新家就在附近。"}},{"pos":"PHRASE 短语","cn":"图省事;走捷径","en":"If you cut corners, you do something quickly by doing it in a less thorough way than you should.","ex":{"en":"Take your time, don't cut corners and follow instructions to the letter.","cn":"慢慢来，不要图省事，要严格按照说明去做。"}},{"pos":"PHRASE 短语","cn":"天涯海角;世界各个角落","en":"You can use expressions such as the four corners of the world to refer to places that are a long way from each other.","ex":{"en":"They've combed the four corners of the world for the best accessories","cn":"为了找到最好的配件，他们寻遍了每个地方。"}},{"pos":"PHRASE 短语","cn":"身处困境","en":"If you are in a corner or in a tight corner, you are in a situation which is difficult to deal with and get out of.","ex":{"en":"The government is in a corner on interest rates","cn":"政府在利率问题上陷入了困境。"}}]},"examples":[{"en":"They had got her in a corner, and there wasn't much she could do about it.","cn":"他们把她逼得走投无路，而且她也没有什么办法脱身。"},{"en":"There was a television in the far corner of the room.","cn":"房间那一头的墙角里摆着一台电视机。"}]},"course":{"media":{"uk":"media/uk/course__gb_1.mp3","us":"media/us/course__us_1.mp3"},"oxford":{"phon":"kɔːs","pos":"noun","senses":[{"en":"a series of lessons or lectures on a particular subject","cn":"（有关某学科的系列）课程，讲座","g":"[countable]","lab":"British English","sc":"education","ex":{"en":"a French/chemistry course","cn":"法语课；化学课"}},{"en":"a period of study at a college or university that leads to an exam or a qualification","cn":"（大学中要进行考试或取得资格的）课程","g":"[countable]","lab":"especially British English","sc":"education","ex":{"en":"What degree course did you choose?","cn":"你选择了什么学位课程？"}},{"en":"a large area of land that is designed for playing golf on","cn":"高尔夫球场","g":"[countable]","sc":"for golf","ex":{"en":"He set a new course record.","cn":"他创下了高尔夫球的新纪录。"}},{"en":"an area of land or water where races are held","cn":"比赛场地；跑道；赛船水道；泳道","g":"[countable]","sc":"for races","ex":{"en":"She was overtaken on the last stretch of the course.","cn":"她在最后一个直道上被超过。"}},{"en":"any of the separate parts of a meal","cn":"一道菜","g":"[countable]","lab":"especially British English","sc":"part of meal","ex":{"en":"a four-course dinner","cn":"有四道菜的正餐"}},{"en":"a direction or route followed by a ship or an aircraft","cn":"（船或飞机的）航向，航线","g":"[uncountable, countable, usually singular]","sc":"direction","ex":{"en":"He radioed the pilot to change course.","cn":"他用无线电通知飞行员改变航向。"}},{"en":"the general direction in which somebody’s ideas or actions are moving or in which things are developing","cn":"方针；行动方向；发展方向","g":"[countable, usually singular]","sc":"direction","ex":{"en":"The president appears likely to change course on some key issues.","cn":"总统看起来可能要在某些重要问题上改变方针。"}},{"en":"a way of acting in or dealing with a particular situation","cn":"行动方式；处理方法","g":"[countable]","sc":"action","ex":{"en":"There are various courses open to us.","cn":"我们有多种处理方法可采取。"}},{"en":"the way something develops or should develop","cn":"进展；进程","g":"[singular]","sc":"development","ex":{"en":"This was an event that changed the course of history.","cn":"这是一次改变了历史进程的事件。"}},{"en":"the direction a river moves in","cn":"江河流向","g":"[countable, usually singular]","sc":"of river","ex":{"en":"The path follows the course of the river.","cn":"小路沿河道延伸。"}},{"en":"a series of medical treatments, tablets, etc.","cn":"（医疗、服药等的）疗程","g":"[countable]","sc":"medical treatment","ex":{"en":"to prescribe a course of antibiotics","cn":"开一个疗程抗生素的处方"}},{"en":"a continuous layer of brick, stone or other building material in a wall","cn":"（砖、石等墙的）层","g":"[countable]","sc":"in wall","ex":{"en":"A new damp-proof course could cost £1 000 or more.","cn":"新的防潮层可花掉 1 000 英镑以上。"}},{"en":"to move or flow quickly","cn":"快速地流动；奔流","ex":{"en":"He stopped talking and tears coursed down his cheeks.","cn":"他不再说话，泪水顺着脸颊流下来。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"","cn":"当然(在英语口语中常用于代替 of course)","en":"Course is often used in the expression 'of course', or instead of 'of course' in informal spoken English. See 见 of course ."},{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指船或飞机的)航向，航线，路线","en":"The course of a vehicle, especially a ship or aircraft, is the route along which it is travelling.","ex":{"en":"Aircraft can avoid each other by going up and down, as well as by altering course to left or right","cn":"飞机可以通过上下升降和左右移动改变航线来避免相撞。"}},{"pos":"N-COUNT 可数名词","cn":"行为方式;处理方式","en":"A course of action is an action or a series of actions that you can do in a particular situation.","ex":{"en":"My best course of action was to help Gill by being loyal, loving and endlessly sympathetic","cn":"我能给吉尔的最大帮助就是对他忠诚、关爱他并且永远满怀同情之心。"}},{"pos":"N-SING 单数名词","cn":"进程;发展的方向","en":"You can refer to the way that events develop as, for example, the course of history or the course of events .","ex":{"en":"...a series of decisive naval battles which altered the course of history","cn":"改变历史进程的一系列决定性的海战"}},{"pos":"N-COUNT 可数名词","cn":"(某科目的)课程，讲座","en":"A course is a series of lessons or lectures on a particular subject.","ex":{"en":"...a course in business administration","cn":"企业管理课程"}},{"pos":"N-COUNT 可数名词","cn":"疗程","en":"A course of medical treatment is a series of treatments that a doctor gives someone.","ex":{"en":"Treatment is supplemented with a course of antibiotics to kill the bacterium","cn":"治疗期间辅以一个疗程的抗生素注射来杀灭细菌。"}},{"pos":"N-COUNT 可数名词","cn":"一道菜","en":"A course is one part of a meal.","ex":{"en":"The lunch was excellent, especially the first course.","cn":"午餐很棒，尤其是第一道菜。"}},{"pos":"N-COUNT 可数名词","cn":"(体育)比赛场地;高尔夫球场","en":"In sport, a course is an area of land where races are held or golf is played, or the land over which a race takes place.","ex":{"en":"Only 12 seconds separated the first three riders on the Bickerstaffe course","cn":"比科斯达夫赛场上的前3名骑手之间只差12秒。"}},{"pos":"N-COUNT 可数名词","cn":"河道","en":"The course of a river is the channel along which it flows.","ex":{"en":"Romantic chateaux and castles overlook the river's twisting course.","cn":"富有浪漫气息的庄园和城堡俯瞰着蜿蜒的河道。"}},{"pos":"VERB 动词","cn":"快速地流动;奔流","en":"If a liquid courses somewhere, it flows quickly.","ex":{"en":"The tears coursed down his cheeks","cn":"他泪如雨下。"}},{"pos":"PREP-PHRASE 短语介词","cn":"在…过程中","en":"If something happens in the course of a particular period of time, it happens during that period of time.","ex":{"en":"In the course of the 1930s steel production in Britain approximately doubled","cn":"在20世纪30年代，英国的钢铁产量几乎翻了一番。"}},{"pos":"PHRASE 短语","cn":"照例;自然;理所当然","en":"If you do something as a matter of course, you do it as part of your normal work or way of life.","ex":{"en":"If police are carrying arms as a matter of course then doesn't it encourage criminals to carry them?","cn":"如果警察每天理所当然地携带武器，这难道不会促使罪犯也持械吗？"}},{"pos":"PHRASE 短语","cn":"在正确航道(或航线)上/偏离航道(或航线)","en":"If a ship or aircraft is on course, it is travelling along the correct route. If it is off course, it is no longer travelling along the correct route.","ex":{"en":"The ill fated ship was sent off course into shallow waters and rammed by another vessel.","cn":"这艘倒霉的船偏离航道误入浅水区，被另外一艘船撞上了。"}},{"pos":"PREP-PHRASE 短语介词","cn":"很可能做成;可能获得","en":"If you are on course for something, you are likely to achieve it.","ex":{"en":"England are well on course for a place at the World Cup Finals","cn":"英格兰队很有可能打进世界杯决赛。"}},{"pos":"PHRASE 短语","cn":"任其发展;听其自然","en":"If something runs its course or takes its course, it develops naturally and comes to a natural end.","ex":{"en":"They estimated that between 17,000 and 20,000 cows would die before the epidemic had run its course","cn":"他们估计在流行病结束之前会有17,000到20,000头牛死去。"}},{"pos":"PHRASE 短语","cn":"坚持到底","en":"If you stay the course, you finish something that you have started, even though it has become very difficult.","ex":{"en":"The oldest president in American history had stayed the course for two terms.","cn":"美国历史上的第一位总统连任两届。"}},{"pos":"PHRASE 短语","cn":"总有一天;最后;终于","en":"If something changes or becomes true in the course of time, it changes or becomes true over a long period of time.","ex":{"en":"In the course of time, many of their myths become entangled.","cn":"最后，他们很多荒诞的说法都变得错综复杂了。"}},{"pos":"","cn":"","en":"in due course→see: ;"}]},"examples":[{"en":"‘I think you’ll enjoy that play.’ ‘I’m sure I will.’/‘Yes, it sounds really good.’ “","cn":"我想你会喜欢那出戏的。” “我肯定会的。”/“是的，这戏看来真棒。”"},{"en":"In the normal course of things we would not treat her disappearance as suspicious.","cn":"在一般情况下，她不露面，我们也不会觉得有什么可疑之处。"}]},"coaching":{"oxford":{"phon":"ˈkəʊtʃɪŋ","pos":"noun","senses":[{"en":"the process of training somebody to play a sport, to do a job better or to improve a skill","cn":"（体育运动、工作或技能的）训练，培训，指导","ex":{"en":"a coaching session","cn":"集训期"}},{"en":"the process of giving a student extra teaching in a particular subject","cn":"（某科目上的）辅导","lab":"especially British English","ex":{"en":"Extra coaching is available for students who might need a little more help.","cn":"需要更多帮助的学生可以得到额外的辅导。"}}]},"media":{"uk":"media/uk/coaching__gb_1.mp3","us":"media/us/coaching__us_1.mp3"},"examples":[{"en":"a coaching session","cn":"集训期"},{"en":"a coaching session with one of England’s leading boxers","cn":"由英格兰一名顶级拳击手指导的一次训练"}],"base":"coach"},"commenting":{"lemma":"comment","media":{"uk":"media/uk/comment__gb_1.mp3","us":"media/us/comment__us_1.mp3"}},"corn":{"media":{"img":["media/ldoce/img/corn.jpg","media/pic/cereals_comp.jpg"],"uk":"media/uk/corn__gb_1.mp3","us":"media/us/corn__us_1.mp3"},"oxford":{"phon":"kɔːn","pos":"noun","senses":[{"en":"any plant that is grown for its grain, such as wheat; the grain of these plants","cn":"（小麦等）谷物；谷粒","g":"[uncountable]","lab":"British English","ex":{"en":"a field of corn","cn":"一片庄稼"}},{"en":"a tall plant grown for its large yellow grains that are used for making flour or eaten as a vegetable; the grains of this plant","cn":"玉蜀黍；玉米","g":"[uncountable]","lab":"North American English","ex":{"en":"The major crops are wheat, barley and corn.","cn":"主要农作物是小麦、大麦和玉米。"}},{"en":"the yellow seeds of a type of corn (maize) plant, also called corn, which grow on thick stems and are cooked and eaten as a vegetable","cn":"玉米","g":"[uncountable]","lab":"North American English","ex":{"en":"fresh corn and arugula salad","cn":"鲜玉米芝麻菜沙拉"}},{"en":"a small area of hard skin on the foot, especially the toe, that is sometimes painful","cn":"（尤指脚趾上的）钉胼，鸡眼","g":"[countable]","ex":{"en":"See your doctor if you have foot pain or corns.","cn":"如果您有脚痛或鸡眼，请去看医生。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"麦类作物;谷物;谷粒","en":"Corn is used to refer to crops such as wheat and barley. It can also be used to refer to the seeds from these plants.","ex":{"en":"...fields of corn","cn":"麦田"}},{"pos":"N-UNCOUNT 不可数名词","cn":"同maize","en":"Corn is the same as maize .","ex":{"en":"...rows of corn in an Iowa field.","cn":"艾奥瓦州农田里成排的玉米"}},{"pos":"N-COUNT 可数名词","cn":"(尤指脚趾周边的)鸡眼，钉胼","en":"Corns are small, painful areas of hard skin which can form on your foot, especially near your toes."}]},"examples":[{"en":"ears/sheaves of corn","cn":"谷穗；一捆捆的谷物"},{"en":"corn-fed chicken","cn":"用谷物饲养的鸡"}]},"comic":{"media":{"uk":"media/uk/comic__gb_1.mp3","us":"media/us/comic__us_1.mp3"},"oxford":{"phon":"ˈkɒmɪk","pos":"adjective","senses":[{"en":"humorous and making you laugh","cn":"滑稽的；使人发笑的","ex":{"en":"a comic monologue/story","cn":"滑稽的长篇独白／故事"}},{"en":"connected with comedy (= entertainment that is funny and that makes people laugh)","cn":"喜剧的","g":"[only before noun]","ex":{"en":"a comic opera","cn":"滑稽歌剧"}},{"en":"a magazine, usually for children, that tells stories through pictures","cn":"（常指儿童看的）连环画杂志","lab":"North American English also","ex":{"en":"a comic book superhero","cn":"连环画杂志里的超级英雄"},"pos":"noun"},{"en":"the section of a newspaper that contains comic strips","cn":"（报章上的）连环漫画栏","g":"[plural]","lab":"North American English","pos":"noun"},{"en":"a person who makes people laugh by telling jokes or funny stories","cn":"滑稽演员；喜剧演员","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"滑稽的;好笑的","en":"If you describe something as comic, you mean that it makes you laugh, and is often intended to make you laugh.","ex":{"en":"The novel is comic and tragic","cn":"这部小说令人笑中带泪。"}},{"pos":"ADJ 形容词","cn":"喜剧的","en":"Comic is used to describe comedy as a form of entertainment, and the actors and entertainers who perform it.","ex":{"en":"Grodin is a fine comic actor.","cn":"格罗丁是一位优秀的喜剧演员。"}},{"pos":"N-COUNT 可数名词","cn":"喜剧演员","en":"A comic is an entertainer who tells jokes in order to make people laugh."},{"pos":"N-COUNT 可数名词","cn":"连环画杂志;漫画书","en":"A comic is a magazine that contains stories told in pictures.","ex":{"en":"Joe loved to read 'Superman' comics.","cn":"乔喜欢看《超人》的漫画书。"}},{"pos":"N-PLURAL 复数名词","cn":"(报纸上的)连环漫画栏","en":"The comics is the part of a newspaper that contains the comic strips."}]},"examples":[{"en":"She can always be relied on to provide comic relief (= sth to make you laugh) at a boring party.","cn":"在沉闷的聚会上，她总是能搞些笑料调剂气氛。"},{"en":"The play is both comic and tragic.","cn":"这部剧既滑稽又悲惨。"}]},"corporation":{"media":{"uk":"media/uk/corporation__gb_1.mp3","us":"media/us/corporation__us_1.mp3"},"oxford":{"phon":"ˌkɔːpəˈreɪʃn","pos":"noun","senses":[{"en":"a large business company","cn":"（大）公司","ex":{"en":"multinational corporations","cn":"跨国公司"}},{"en":"an organization or a group of organizations that is recognized by law as a single unit","cn":"法人；法人团体","ex":{"en":"urban development corporations","cn":"城市开发集团公司"}},{"en":"a group of people elected to govern a large town or city and provide public services","cn":"市政委员会","lab":"British English","ex":{"en":"the Lord Mayor and Corporation of the City of London","cn":"伦敦市长及市政当局"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"大公司;大企业","en":"A corporation is a large business or company.","ex":{"en":"...multi-national corporations.","cn":"跨国公司"}},{"pos":"N-COUNT 可数名词","cn":"(英国某些大城市的)市政委员会","en":"In some large British cities, the corporation is the local authority that is responsible for providing public services.","ex":{"en":"...the corporation's task of regenerating 900 acres of the inner city.","cn":"市政委员会改造900英亩的市中心贫民区的任务"}}]},"examples":[{"en":"urban development corporations","cn":"城市开发集团公司"},{"en":"the Chrysler corporation","cn":"克莱斯勒公司"}]},"composer":{"media":{"uk":"media/uk/composer__gb_1.mp3","us":"media/us/composer__us_1.mp3"},"oxford":{"phon":"kəmˈpəʊzə(r)","pos":"noun","senses":[{"en":"a person who writes music, especially classical music","cn":"（尤指古典音乐的）创作者，作曲者，作曲家","ex":{"en":"Verdi was a prolific composer of operas.","cn":"威尔第是一位多产的歌剧作曲家。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指古典音乐)作曲家","en":"A composer is a person who writes music, especially classical music."}]}},"continuation":{"media":{"uk":"media/uk/xcontinuation__gb_1.mp3","us":"media/us/xcontinuation__us_1.mp3"},"oxford":{"phon":"kənˌtɪnjuˈeɪʃn","pos":"noun","senses":[{"en":"an act or the state of continuing","cn":"继续；连续；持续","g":"[uncountable, singular]","ex":{"en":"They are anxious to ensure the continuation of the economic reform programme.","cn":"他们渴望确保经济改革计划持续下去。"}},{"en":"something that continues or follows something else","cn":"延续部分；续篇","g":"[countable]","ex":{"en":"Her new book is a continuation of her autobiography.","cn":"她的新书是她自传的续篇。"}},{"en":"something that is joined on to something else and forms a part of it","cn":"附加物；延续物","g":"[countable]","ex":{"en":"There are plans to build a continuation of the bypass next year.","cn":"已有计划明年修建这条支路的延长线。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"持续;继续;延续","en":"The continuation of something is the fact that it continues, rather than stopping.","ex":{"en":"It's the coalition forces who are to blame for the continuation of the war","cn":"联合部队应当对战争的延续负责。"}},{"pos":"N-COUNT 可数名词","cn":"续;延续部分","en":"Something that is a continuation of something else is closely connected with it or forms part of it.","ex":{"en":"...since this chapter is a continuation of Chapter 8","cn":"既然这一章是第8章的延续"}}]},"examples":[{"en":"They are anxious to ensure the continuation of the economic reform programme.","cn":"他们渴望经济改革计划一定要持续下去。"},{"en":"There are plans to build a continuation of the bypass next year.","cn":"已有计划明年修建这条支路的延伸线。"}]},"cocoon":{"media":{"uk":"media/uk/cocoon__gb_1.mp3","us":"media/us/cocoon__us_1.mp3"},"oxford":{"phon":"kəˈkuːn","pos":"noun","senses":[{"en":"a cover or case of silk threads that some insects, especially moths, make to protect themselves before they become adults","cn":"茧;卵袋"},{"en":"a layer of something soft that wraps all around a person or thing and forms a protection","cn":"保护膜；防护层；软罩","lab":"figurative","ex":{"en":"the cocoon of a caring family","cn":"家庭中相互关爱所形成的保护"}},{"en":"to protect somebody/something by surrounding them or it completely with something","cn":"把…包围起来保护；（用…）完全保护起来","g":"[transitive]","ex":{"en":"We were warm and safe, cocooned in our sleeping bags.","cn":"我们在睡袋里睡觉，暖和又安全。"},"pos":"verb"},{"en":"to spend more of your free time at home and less time going out and doing things with other people","cn":"宅在家里","g":"[intransitive]","lab":"North American English","ex":{"en":"After spending too much over the holidays, many will simply cocoon at home.","cn":"在假期花费过多之后，许多人就会窝在家里。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"茧;(昆虫的)卵袋","en":"A cocoon is a covering of silky threads that the larvae of moths and other insects make for themselves before they grow into adults."},{"pos":"N-COUNT 可数名词","cn":"茧状包裹物","en":"If you are in a cocoon of something, you are wrapped up in it or surrounded by it.","ex":{"en":"He stood there in a cocoon of golden light.","cn":"他站在那儿，一柱金光笼罩着他。"}},{"pos":"N-COUNT 可数名词","cn":"给人安全感的环境;保护层","en":"If you are living in a cocoon, you are in an environment in which you feel protected and safe, and sometimes isolated from everyday life.","ex":{"en":"...her innocent desire to envelop her beloved in a cocoon of love","cn":"她想要把心上人包裹在爱中的天真想法"}},{"pos":"VERB 动词","cn":"把…保护起来;把…隔绝开来","en":"If something cocoons you from something, it protects you or isolates you from it.","ex":{"en":"There is nowhere to hide when things go wrong, no organisation to cocoon you from blame","cn":"如果出了问题，根本无处可躲，没有哪个机构会庇护你，让你免受指责。"}}]},"examples":[{"en":"We were warm and safe, cocooned in our sleeping bags.","cn":"我们在睡袋里睡觉，暖和又安全。"},{"en":"( figurative ) the cocoon of a caring family","cn":"家庭中相互关爱所形成的保护"}]},"considerations":{"lemma":"consideration"},"cognitive":{"media":{"uk":"media/uk/cognitive__gb_1.mp3","us":"media/us/cognitive__us_1.mp3"},"oxford":{"phon":"ˈkɒɡnətɪv","pos":"adjective","senses":[{"en":"connected with mental processes of understanding","cn":"认知的；感知的；认识的","ex":{"en":"a child’s cognitive development","cn":"儿童的认知发展"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"认识过程的;认知的","en":"Cognitive means relating to the mental process involved in knowing, learning, and understanding things.","ex":{"en":"As children grow older, their cognitive processes become sharper.","cn":"孩子们越长越大，他们的认知过程变得更为敏锐。"}}]},"examples":[{"en":"a child's cognitive development","cn":"儿童的认知发展"},{"en":"cognitive psychology","cn":"认知心理学"}]},"content":{"media":{"uk":"media/uk/xcontent__gb_1.mp3","us":"media/us/xcontent__us_1.mp3"},"oxford":{"phon":"ˈkɒntent","pos":"noun","senses":[{"en":"the things that are contained in something","cn":"所容纳之物；所含之物；内容","g":"[plural]","ex":{"en":"He tipped the contents of the bag onto the table.","cn":"他把提包里的东西倒在桌子上。"}},{"en":"the different sections that are contained in a book","cn":"（书的）目录，目次","g":"[plural]","ex":{"en":"a table of contents (= the list at the front of a book)","cn":"目录"}},{"en":"the subject matter of a book, speech, programme, etc.","cn":"（书、讲话、节目等的）主题，主要内容","g":"[uncountable]","ex":{"en":"Her poetry has a good deal of political content.","cn":"她的诗歌包含大量的政治内容。"}},{"en":"the amount of a substance that is contained in something else","cn":"含量；容量","g":"[singular]","ex":{"en":"food with a high fat content","cn":"脂肪含量高的食物"}},{"en":"the information or other material contained on a website or other digital media","cn":"（网站或其他数字媒介上的）内容","g":"[uncountable]","lab":"computing","ex":{"en":"digital/video/online content","cn":"数字／视频／在线内容"}},{"en":"happy and satisfied with what you have","cn":"满意；满足","ex":{"en":"He seemed more content, less bitter.","cn":"他看起来比较满意，不那么愤愤不平。"},"pos":"adjective"},{"en":"willing to do something","cn":"愿意","ex":{"en":"I was content to wait.","cn":"我愿意等候。"},"pos":"adjective"},{"en":"to accept and be satisfied with something and not try to have or do something better","cn":"满足；满意；知足","ex":{"en":"Martina contented herself with a bowl of soup.","cn":"马丁娜喝了一碗汤就心满意足了。"},"pos":"verb"},{"en":"to make somebody feel happy or satisfied","cn":"使满意；使满足","lab":"formal","ex":{"en":"My apology seemed to content him.","cn":"我的道歉好像使他感到满意。"},"pos":"verb"},{"en":"a feeling of being happy or satisfied","cn":"满意；满足","lab":"more frequent","ex":{"en":"She stood for a moment looking with content at her husband.","cn":"她站了一会儿，满意地看着她的丈夫。"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"所容纳的东西;所含之物","en":"The contents of a container such as a bottle, box, or room are the things that are inside it.","ex":{"en":"Empty the contents of the pan into the sieve","cn":"将锅里的东西倒到筛子上。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(书、演讲、电视节目等的)内容","en":"If you refer to the content or contents of something such as a book, speech, or television programme, you are referring to the subject that it deals with, the story that it tells, or the ideas that it expresses.","ex":{"en":"She is reluctant to discuss the content of the play","cn":"她不愿意谈该剧的内容。"}},{"pos":"N-PLURAL 复数名词","cn":"(书的)目录","en":"The contents of a book are its different chapters and sections, usually shown in a list at the beginning of the book.","ex":{"en":"There is no initial list of contents.","cn":"没有章首目录。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(教育项目或课程的)内容","en":"The content of something such as an educational course or a programme of action is the elements that it consists of.","ex":{"en":"Previous students have had nothing but praise for the course content and staff","cn":"往届学生对课程内容与教员全是赞扬之词。"}},{"pos":"N-SING 单数名词","cn":"含量;成分","en":"You can use content to refer to the amount or proportion of something that a substance contains.","ex":{"en":"Sunflower margarine has the same fat content as butter","cn":"向日葵所制人造黄油的脂肪含量与黄油脂肪含量相同。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"满足的;知足的","en":"If you are content with something, you are willing to accept it, rather than wanting something more or something better.","ex":{"en":"I am content to admire the mountains from below","cn":"我满足于从山脚下观赏山景。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"满意的;惬意的","en":"If you are content, you are fairly happy or satisfied.","ex":{"en":"He says his daughter is quite content.","cn":"他说他女儿非常满意。"}},{"pos":"VERB 动词","cn":"使(自己)满足(于…)","en":"If you content yourself with something, you accept it and do not try to do or have other things.","ex":{"en":"He wisely contented himself with his family and his love of nature","cn":"他非常明智，拥有家庭和对自然的热爱便知足了。"}},{"pos":"","cn":"","en":"to your heart's content→see: ;"}]},"examples":[{"en":"Not content with stealing my boyfriend (= not thinking that this was enough), she has turned all my friends against me.","cn":"她夺走了我的男朋友还不满足，又挑起我所有的朋友和我作对。"},{"en":"She hadn't read the letter and so was unaware of its contents.","cn":"她没有看过那封信，所以对其内容一无所知。"}]},"countrysides":{"lemma":"countryside","media":{"img":["media/pic/countryside_labels_comp.jpg","media/thumb/countryside.jpg"],"uk":"media/uk/countryside__gb_1.mp3","us":"media/us/countryside__us_1.mp3"}},"contribution":{"media":{"uk":"media/uk/xcontribution__gb_1.mp3","us":"media/us/xcontribution__us_1.mp3"},"oxford":{"phon":"ˌkɒntrɪˈbjuːʃn","pos":"noun","senses":[{"en":"a gift or payment that is made to a person or an organization in order to help pay for something","cn":"捐款；捐资","g":"[countable]","ex":{"en":"All contributions will be gratefully received.","cn":"我们对所有捐资表示感谢。"}},{"en":"a sum of money that you pay regularly to your employer or the government in order to pay for benefits such as health insurance, a pension, etc.","cn":"（给雇主或政府用作医疗保险、养老金等津贴的）定期缴款","g":"[countable]","lab":"British English","ex":{"en":"pension contributions","cn":"养老金缴款"}},{"en":"an action or a service that helps to cause or increase something, usually (but not necessarily) something good or valuable","cn":"贡献；促成作用","g":"[countable, usually singular]","ex":{"en":"He made a very positive contribution to the success of the project.","cn":"他对项目的成功作出了非常积极的贡献。"}},{"en":"an item that forms part of a book, magazine, website broadcast, discussion, etc.","cn":"（书、杂志、网站广播、讨论等部分内容的）一则，一条，稿件","g":"[countable]","ex":{"en":"All contributions for the May issue must be received by Friday.","cn":"所有要在五月这一期发表的稿件必须在星期五以前寄到。"}},{"en":"the act of giving something, especially money, to help a person or an organization","cn":"捐赠；捐助；（尤指）捐款","g":"[uncountable]","ex":{"en":"The institute is totally funded by voluntary contribution.","cn":"研究所的经费全部来自自愿捐款。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"贡献","en":"If you make a contribution to something, you do something to help make it successful or to produce it.","ex":{"en":"American economists have made important contributions to the field of financial and corporate economics","cn":"美国的经济学家们在金融和企业经济学领域做出了重要的贡献。"}},{"pos":"N-COUNT 可数名词","cn":"捐款;捐资","en":"A contribution is a sum of money that you give in order to help pay for something.","ex":{"en":"This list ranked companies that make charitable contributions of a half million dollars or more.","cn":"这张名单列出了慈善捐款额达50万美元以上的公司。"}},{"pos":"N-COUNT 可数名词","cn":"稿件;投稿","en":"A contribution to a magazine, newspaper, or book is something that you write to be published in it."}]},"examples":[{"en":"All contributions for the May issue must be received by Friday.","cn":"所有要在五月这一期发表的稿件必须在星期五以前寄到。"},{"en":"These measures would make a valuable contribution towards reducing industrial accidents.","cn":"这些措施将会对减少工业事故起重要的作用。"}]},"colossal":{"media":{"uk":"media/uk/colossal__gb_1.mp3","us":"media/us/colossal__us_1.mp3"},"oxford":{"phon":"kəˈlɒsl","pos":"adjective","senses":[{"en":"extremely large","cn":"巨大的；庞大的","ex":{"en":"a colossal statue","cn":"巨大的雕像"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"巨大的;庞大的","en":"If you describe something as colossal, you are emphasizing that it is very large.","ex":{"en":"There has been a colossal waste of public money","cn":"一直存在巨大的公款浪费。"}}]},"examples":[{"en":"The singer earns a colossal amount of money.","cn":"那歌手现在可赚大钱了。"},{"en":"a colossal statue","cn":"巨大的雕像"}]},"continuous":{"media":{"uk":"media/uk/xcontinuous__gb_1.mp3","us":"media/us/xcontinuous__us_1.mp3"},"oxford":{"phon":"kənˈtɪnjuəs","pos":"adjective","senses":[{"en":"happening or existing for a period of time without being interrupted","cn":"不断的；持续的；连续的","ex":{"en":"Recovery after the accident will be a continuous process that may take several months.","cn":"事故后的恢复将是一个持续的过程，可能需要几个月的时间。"}},{"en":"spreading in a line or over an area without any spaces","cn":"延伸的；遍布的","ex":{"en":"a continuous flow of traffic","cn":"络绎不绝的车流"}},{"en":"repeated many times","cn":"反复的；频繁的","lab":"informal","ex":{"en":"For four days the town suffered continuous attacks.","cn":"那座城镇连续四天遭到了袭击。"}},{"en":"connected with the form of a verb (for example I am waiting or It is raining) that is made from a part of be and the present participle. Progressive forms are used to express an action that continues for a period of time.","cn":"（动词）进行时的，进行式的","lab":"grammar","ex":{"en":"the continuous tenses","cn":"进行时态"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"连续不断的;持续的;不中断的","en":"A continuous process or event continues for a period of time without stopping.","ex":{"en":"Residents report that they heard continuous gunfire.","cn":"居民们报告说他们听到了连续不断的枪声。"}},{"pos":"ADJ 形容词","cn":"(线、表面等)连续的，没有间隔的","en":"A continuous line or surface has no gaps or holes in it.","ex":{"en":"...a continuous line of boats.","cn":"一排船只"}},{"pos":"ADJ 形容词","cn":"(动词)进行式的","en":"In English grammar, continuous verb groups are formed using the auxiliary 'be' and the present participle of a verb, as in 'I'm feeling a bit tired' and 'She had been watching them for some time'. Continuous verb groups are used especially when you are focusing on a particular moment. →see usage note at:"}]},"examples":[{"en":"He has lived and worked in France almost continuously since 1990.","cn":"自从 1990 年以来，他差不多一直在法国居住和工作。"},{"en":"She was in continuous employment until the age of sixty-five.","cn":"她连续不断地受雇于人，一直工作到 65 岁。"}]},"construct":{"media":{"uk":"media/uk/xconstruct__gb_1.mp3","us":"media/us/xconstruct__us_1.mp3"},"oxford":{"phon":"kənˈstrʌkt","pos":"verb","senses":[{"en":"to build or make something such as a road, building or machine","cn":"建筑；修建；建造","g":"[often passive]","ex":{"en":"The building was constructed in 1993.","cn":"这幢大楼建于 1993 年。"}},{"en":"to form something by putting different things together","cn":"组成；创建","ex":{"en":"You must learn how to construct a logical argument.","cn":"你必须学会怎样确立合乎逻辑的论点。"}},{"en":"to draw a line or shape according to the rules of mathematics","cn":"（按照数学规则）编制，绘制","lab":"geometry","ex":{"en":"to construct a triangle","cn":"画一个三角形"}},{"en":"an idea or a belief that is based on various pieces of evidence that have not always been proved to be true","cn":"（根据不总是真实的各种证据得出的）构想，观念，概念","ex":{"en":"a contrast between lived reality and the construct held in the mind","cn":"现实生活与头脑所持概念之间的明显差别"},"pos":"noun"},{"en":"a group of words that form a phrase","cn":"（短语的）结构成分，结构体","lab":"linguistics","pos":"noun"},{"en":"a thing that is built or made","cn":"建造物；构筑物；制成物","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"建筑;建造;修建","en":"If you construct something such as a building, road, or machine, you build it or make it.","ex":{"en":"The French constructed a series of fortresses from Dunkirk on the Channel coast to Douai","cn":"法国人在从敦克尔刻到杜埃的英吉利海峡沿岸修筑了一系列要塞。"}},{"pos":"VERB 动词","cn":"构想，构筑，构思(思想、作品、体系等)","en":"If you construct something such as an idea, a piece of writing, or a system, you create it by putting different parts together.","ex":{"en":"You will find it difficult to construct a spending plan without first recording your spending","cn":"你会发现不先把自己的开销记录下来就很难制订支出计划。"}},{"pos":"N-COUNT 可数名词","cn":"复杂的构想(或思想);观念","en":"A construct is a complex idea.","ex":{"en":"...the underlying constructs (beliefs, philosophy, etc.) which influence action and behaviour","cn":"影响行动和行为的根本思想(信仰、处世哲学等)"}},{"pos":"N-COUNT 可数名词","cn":"建筑物;建造物;创造物","en":"A construct is something that is built, made, or created.","ex":{"en":"As the flimsy constructs soared, the men paid out twine until the kites reached three or four thousand feet","cn":"随着这轻薄的东西向上飞升，这些人慢慢放出细绳，直到风筝飞到三四千英尺高。"}}]},"examples":[{"en":"a contrast between lived reality and the construct held in the mind","cn":"现实生活与头脑所持概念之间的明显差别"},{"en":"You must learn how to construct a logical argument.","cn":"你必须学会怎样确立合乎逻辑的论点。"}]},"connects":{"lemma":"connect","media":{"uk":"media/uk/xconnect__gb_1.mp3","us":"media/us/xconnect__us_1.mp3"}},"conjunction":{"oxford":{"phon":"kənˈdʒʌŋkʃn","pos":"noun","senses":[{"en":"a word that joins words, phrases or sentences, for example ‘and’, ‘but’, ‘or’ or ‘because’","cn":"连词，连接词（如 and、but、or、because）","g":"[countable]","lab":"grammar"},{"en":"a combination of events, etc., that causes a particular result","cn":"（引起某种结果的事物等的）结合，同时发生","g":"[countable]","lab":"formal","ex":{"en":"The conjunction of low inflation and low unemployment came as a very pleasant surprise.","cn":"低通货膨胀与低失业的同时出现是一大惊喜。"}},{"en":"the fact of stars, planets, etc. passing close together, as seen from the earth","cn":"（恒星、行星等的）合","g":"[countable, uncountable]","lab":"astronomy","ex":{"en":"The theory is that there was a rare conjunction of certain bright planets that created the image of the so-called ‘Star of Bethlehem’.","cn":"该理论认为，某些明亮行星的罕见结合创造了所谓的“伯利恒之星”的图像。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(事件的)同时发生，同地发生","en":"A conjunction of two or more things is the occurrence of them at the same time or place.","ex":{"en":"...the conjunction of two events.","cn":"两个事件的同时发生"}},{"pos":"N-COUNT 可数名词","cn":"(语法中的)连词","en":"In grammar, a conjunction is a word or group of words that joins together words, groups, or clauses. In English, there are co-ordinating conjunctions such as 'and' and 'but', and subordinating conjunctions such as 'although', 'because', and 'when'."},{"pos":"PHRASE 短语","cn":"连同…;与…一起","en":"If one thing is done or used in conjunction with another, the two things are done or used together.","ex":{"en":"The army should have operated in conjunction with the fleet to raid the enemy's coast","cn":"陆军本应与舰队共同行动，突袭敌方海岸。"}}]},"media":{"uk":"media/uk/xconjunction__gb_1.mp3","us":"media/us/xconjunction__us_1.mp3"},"examples":[{"en":"The system is designed to be used in conjunction with a word processing program.","cn":"本系统是为与文字处理程序配合使用而设计的。"},{"en":"The conjunction of low inflation and low unemployment came as a very pleasant surprise.","cn":"低通货膨胀与低失业的同时出现是一大惊喜。"}]},"correctly":{"oxford":{"phon":"kəˈrektli","pos":"adverb","senses":[{"en":"in a way that is accurate or true, without any mistakes","cn":"准确无误地；精确地；正确地","ex":{"en":"Have you spelled it correctly?","cn":"你把它拼写对了吗？"}},{"en":"in a way that is right and suitable, so that something is done as it should be done","cn":"恰当地；合适地","ex":{"en":"When correctly applied, fake tan is difficult to tell from the real thing.","cn":"如果涂抹得当，假晒黑跟真晒黑很难分辨。"}},{"en":"in a way that follows the accepted standards or rules","cn":"符合公认准则地；得体地","ex":{"en":"He was looking correctly grave.","cn":"他表情严肃得体。"}}]},"media":{"uk":"media/uk/correctly__gb_1.mp3","us":"media/us/correctly__us_1.mp3"},"examples":[{"en":"They reasoned, correctly, that she was away for the weekend.","cn":"他们的推断没错，她出去度周末了。"},{"en":"Have you spelled it correctly?","cn":"你把它拼写对了吗？"}]},"corrected":{"lemma":"correct","media":{"uk":"media/uk/correct__gb_1.mp3","us":"media/us/correct__us_1.mp3"}},"cover":{"media":{"uk":"media/uk/cover__gb_1.mp3","us":"media/us/cover__us_1.mp3"},"oxford":{"phon":"ˈkʌvə(r)","pos":"verb","senses":[{"en":"to place something over or in front of something in order to hide, protect or decorate it","cn":"掩蔽；遮盖","g":"[transitive]","lab":"figurative","sc":"hide/protect","ex":{"en":"Cover the chicken loosely with foil.","cn":"用锡箔把鸡肉松松地盖起来。"}},{"en":"to lie or spread over the surface of something","cn":"盖；覆盖","g":"[transitive]","sc":"spread over surface","ex":{"en":"Snow covered the ground.","cn":"大雪覆盖了大地。"}},{"en":"to put or spread a layer of liquid, dust, etc. on somebody/something","cn":"撒上，洒上，溅上（一层液体、尘土等）","g":"[transitive]","sc":"spread over surface","ex":{"en":"The wind blew in from the desert and covered everything with sand.","cn":"风从沙漠那边吹来，把一切都蒙上了一层沙子。"}},{"en":"to include something; to deal with something","cn":"包括；包含；涉及；处理","g":"[transitive]","sc":"include","ex":{"en":"The lectures covered a lot of ground (= a lot of material, subjects, etc.).","cn":"这些讲座涉及的内容极为广泛丰富。"}},{"en":"to be or provide enough money for something","cn":"足以支付；够付","g":"[transitive]","sc":"money","ex":{"en":"$100 should cover your expenses.","cn":"100 美元该足够支付你的费用了。"}},{"en":"to travel the distance mentioned","cn":"行走（一段路程）","g":"[transitive]","sc":"distance/area","ex":{"en":"By sunset we had covered thirty miles.","cn":"到日落时我们已走了三十英里。"}},{"en":"to spread over the area mentioned","cn":"占（一片面积）","g":"[transitive]","sc":"distance/area","ex":{"en":"The reserve covers an area of some 1 140 square kilometres.","cn":"保护区占地面积大约 1 140 平方公里。"}},{"en":"to report on an event for television, a newspaper, etc.; to show an event on television","cn":"报道；电视报道","g":"[transitive]","sc":"report news","ex":{"en":"She's covering the party's annual conference.","cn":"她正在报道这个政党的年会新闻。"}},{"en":"to do somebody’s work or duties while they are away","cn":"代替，顶替，替补（某人工作或履行职责）","g":"[intransitive]","sc":"for somebody","ex":{"en":"I'm covering for Jane while she's on leave.","cn":"简休假时我来顶替她工作。"}},{"en":"to invent a lie or an excuse that will stop somebody from getting into trouble","cn":"（为免他人陷入麻烦而用谎话或借口）遮掩，掩盖，敷衍","g":"[intransitive]","sc":"for somebody","ex":{"en":"I have to go out for a minute—will you cover for me if anyone asks where I am?","cn":"我得出去一会儿，假如有人问起我在哪里，你能为我搪塞一下吗？"}},{"en":"to protect somebody against loss, injury, etc. by insurance","cn":"给…保险","g":"[transitive]","sc":"with insurance","ex":{"en":"Are you fully covered for fire and theft?","cn":"你是否买了足够的火险和盗窃险？"}},{"en":"to take action in order to protect yourself against being blamed for something","cn":"采取预防行动（以使自己免遭责备）","g":"[transitive]","sc":"against blame","ex":{"en":"Many firms put money aside to cover themselves against possible legal claims.","cn":"许多公司存钱以应对可能的法律索赔。"}},{"en":"to protect somebody by threatening to shoot at anyone who tries to attack them","cn":"掩护","g":"[transitive]","sc":"with gun","ex":{"en":"Cover me while I move forward.","cn":"掩护我前进。"}},{"en":"to aim a gun at a place or person so that nobody can escape or shoot","cn":"用枪瞄准（以致无人可逃跑或开枪）","g":"[transitive]","sc":"with gun","ex":{"en":"The police covered the exits to the building.","cn":"警方用枪封锁了那栋大楼的出口。"}},{"en":"to record a new version of a song that was originally recorded by another band or singer","cn":"翻唱（原来由另一乐队或歌手演唱的歌曲）","g":"[transitive]","sc":"song","ex":{"en":"They've covered an old Rolling Stones number.","cn":"他们翻唱了滚石乐队的一首老歌。"}},{"en":"a thing that is put over or on another thing, usually to protect it or to decorate it","cn":"覆盖物；掩蔽物；套子；罩子","g":"[countable]","sc":"protection/shelter","ex":{"en":"Brighten up your room with some colourful cushion covers.","cn":"用一些色彩鲜艳的靠垫套使你的房间更添亮丽。"},"pos":"noun"},{"en":"shelter from bad weather or protection from an attack","cn":"躲避处；避难所；庇护所","g":"[uncountable]","sc":"protection/shelter","ex":{"en":"Everyone ran for cover when it started to rain.","cn":"雨下起来时，大家都跑着找地方避雨。"},"pos":"noun"},{"en":"the outside of a book or a magazine","cn":"（书刊的）封面，封皮","g":"[countable]","sc":"of book","ex":{"en":"the front/back cover","cn":"封面；封底"},"pos":"noun"},{"en":"protection that an insurance company provides by promising to pay you money if a particular event happens","cn":"（保险公司的）保险","g":"[uncountable]","lab":"British English","sc":"insurance","ex":{"en":"accident cover","cn":"事故保险"},"pos":"noun"},{"en":"support and protection that is provided when somebody is attacking or in danger of being attacked","cn":"掩护；防护","g":"[uncountable]","sc":"with weapons","ex":{"en":"The ships needed air cover (= protection by military planes) once they reached enemy waters.","cn":"一到达敌方的水域，船只就需要空中掩护。"},"pos":"noun"},{"en":"trees and plants that grow on an area of land","cn":"（生长在一个地区的）植被","g":"[uncountable]","sc":"trees/plants","ex":{"en":"The total forest cover of the earth is decreasing.","cn":"地球上森林覆盖的总面积正在减少。"},"pos":"noun"},{"en":"the fact of the sky being covered with cloud or the ground with snow","cn":"（云层的）遮盖；（雪的）覆盖","g":"[uncountable]","sc":"cloud/snow","ex":{"en":"Fog and low cloud cover are expected this afternoon.","cn":"预计今天下午有雾和低空云层。"},"pos":"noun"},{"en":"the sheets, blankets, etc. on a bed","cn":"床单；床罩；毯子；被子","g":"[plural]","sc":"on bed","ex":{"en":"She threw back the covers and leapt out of bed.","cn":"她掀开被子跳下床来。"},"pos":"noun"},{"en":"a new recording of an old song by a different band or singer","cn":"（由不同乐队演奏或不同歌手演唱的）翻唱版本","g":"[countable]","sc":"song","ex":{"en":"They started out singing covers of country songs.","cn":"他们是以翻唱乡村歌曲起家的。"},"pos":"noun"},{"en":"activities or behaviour that seem honest or true but that hide somebody’s real identity or feelings, or that hide something illegal","cn":"（对身份、感情或违法事情的）掩盖，掩饰","g":"[countable, usually singular]","sc":"hiding something","ex":{"en":"His work as a civil servant was a cover for his activities as a spy.","cn":"他以公务员的工作来掩护他搞间谍活动。"},"pos":"noun"},{"en":"the fact of somebody doing a job when the person who usually does it is away or when there are not enough staff","cn":"代替工作；代劳；替补","g":"[uncountable]","sc":"for somebody’s work","ex":{"en":"It's the manager's job to organize cover for staff who are absent.","cn":"安排他人顶替缺席的员工是经理的工作。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"遮盖;掩蔽","en":"If you cover something, you place something else over it in order to protect it, hide it, or close it.","ex":{"en":"Cover the casserole with a tight-fitting lid","cn":"用大小合适的盖子盖住砂锅。"}},{"pos":"VERB 动词","cn":"盖在…上面;铺在…上面","en":"If one thing covers another, it has been placed over it in order to protect it, hide it, or close it.","ex":{"en":"His finger went up to touch the black patch which covered his left eye","cn":"他伸手去触摸遮住左眼的黑眼罩。"}},{"pos":"VERB 动词","cn":"盖;覆盖;遮住","en":"If one thing covers another, it forms a layer over its surface.","ex":{"en":"The clouds had spread and nearly covered the entire sky","cn":"云彩扩散开来，几乎遮住了整个天空。"}},{"pos":"VERB 动词","cn":"用…遮盖;把…铺在…上","en":"To cover something with or in something else means to put a layer of the second thing over its surface.","ex":{"en":"The trees in your garden may have covered the ground with apples, pears or plums","cn":"你花园里的果树也许已经落了一地的苹果、梨或李子。"}},{"pos":"VERB 动词","cn":"行走(一段路程)","en":"If you cover a particular distance, you travel that distance.","ex":{"en":"It would not be easy to cover ten miles on that amount of petrol","cn":"就那么点儿汽油很难开10英里。"}},{"pos":"VERB 动词","cn":"(用枪等)掩护","en":"To cover someone or something means to protect them from attack, for example by pointing a gun in the direction of people who may attack them, ready to fire the gun if necessary.","ex":{"en":"You go first. I'll cover you.","cn":"你先撤，我掩护你。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(飞机等的)掩护，防护","en":"Cover is protection from enemy attack that is provided for troops or ships carrying out a particular operation, for example by aircraft.","ex":{"en":"They said they could not provide adequate air cover for ground operations.","cn":"他们声称无法为地面军事行动提供充分的空中掩护。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"躲避处;避难所;庇护所","en":"Cover is trees, rocks, or other places where you shelter from the weather or from an attack, or hide from someone.","ex":{"en":"Charles lit the fuses and they ran for cover.","cn":"查尔斯点燃了导火索，他们便赶紧四处躲避。"}},{"pos":"VERB 动词","cn":"给…保险","en":"An insurance policy that covers a person or thing guarantees that money will be paid by the insurance company in relation to that person or thing.","ex":{"en":"Their insurer paid the £900 bill, even though the policy did not strictly cover it","cn":"虽然严格来讲保险单并不包含这一项，他们的保险公司还是支付了那张900英镑的账单。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(保险公司的)保险","en":"Insurance cover is a guarantee from an insurance company that money will be paid by them if it is needed.","ex":{"en":"Make sure that the firm's insurance cover is adequate.","cn":"确保该公司上了足够的保险。"}},{"pos":"VERB 动词","cn":"(法律)适用于，涉及","en":"If a law covers a particular set of people, things, or situations, it applies to them.","ex":{"en":"The law covers four categories of experiments","cn":"该法规适用于4类试验。"}},{"pos":"VERB 动词","cn":"(在演讲、课程或书中)讨论，涉及","en":"If you cover a particular topic, you discuss it in a lecture, course, or book.","ex":{"en":"The Oxford Chemistry Primers aim to cover important topics in organic chemistry","cn":"《牛津化学初级读本》丛书旨在论述有机化学中的重要问题。"}},{"pos":"VERB 动词","cn":"报道","en":"If journalists, newspapers, or television companies cover an event, they report on it.","ex":{"en":"Robinson was sent to Italy to cover the 1990 World Cup","cn":"鲁宾逊被派到意大利报道1990年的世界杯比赛。"}},{"pos":"VERB 动词","cn":"(钱)足以支付，够付","en":"If a sum of money covers something, it is enough to pay for it.","ex":{"en":"Send it to the address given with £1.50 to cover postage and administration","cn":"将它寄到指定地址，并附上1.50英镑以支付邮资和管理费。"}},{"pos":"N-COUNT 可数名词","cn":"覆盖物;套子;罩子;盖子","en":"A cover is something which is put over an object, usually in order to protect it.","ex":{"en":"...a family room with washable covers on the furniture.","cn":"家具上套有可清洗外罩的家庭娱乐室"}},{"pos":"N-PLURAL 复数名词","cn":"被子;毯子;床单;床罩","en":"The covers on your bed are the things such as sheets and blankets that you have on top of you.","ex":{"en":"She set her glass down and slid farther under the covers.","cn":"她放下杯子，钻进被子里。"}},{"pos":"N-COUNT 可数名词","cn":"(书刊的)封面，封皮","en":"The cover of a book or a magazine is the outside part of it.","ex":{"en":"A few years ago, David Byrne was on the cover of Time magazine.","cn":"几年前，大卫·拜恩曾登上《时代》周刊的封面。"}},{"pos":"N-COUNT 可数名词","cn":"(对秘密或违法之事的)掩盖，掩饰","en":"Something that is a cover for secret or illegal activities seems respectable or normal, and is intended to hide the activities.","ex":{"en":"They set up a spurious temple that was a cover for sexual debauchery","cn":"他们建立起一座为淫秽活动作掩护的假寺庙。"}},{"pos":"VERB 动词","cn":"(通过提供假信息或不完全的信息来)遮掩，掩盖，包庇","en":"If you cover for someone who is doing something secret or illegal, you give false information or do not give all the information you have, in order to protect them.","ex":{"en":"Why would she cover for someone who was trying to kill her?","cn":"她为什么要包庇想要杀她的人呢？"}},{"pos":"VERB 动词","cn":"代替，顶替(某人工作)","en":"If you cover for someone who is ill or away, you do their work for them while they are not there.","ex":{"en":"She did not have enough nurses to cover for those who went ill or took holiday.","cn":"她没有足够的护士来顶替那些生病或休假的人工作。"}},{"pos":"VERB 动词","cn":"翻唱(歌曲)","en":"To cover a song originally performed by someone else means to record a new version of it.","ex":{"en":"He must make a decent living from other artists covering his songs.","cn":"其他艺术家翻唱他的歌曲，一定使他过上了收入颇为可观的生活。"}},{"pos":"N-COUNT 可数名词","cn":"同 cover version","en":"A cover is the same as a cover version .","ex":{"en":"The single is a cover of an old Rolling Stones song.","cn":"这支单曲是滚石乐队的一首老歌的翻唱。"}},{"pos":"PHRASE 短语","cn":"揭露，揭示(真实身份或工作的真实性质)","en":"To blow someone's cover means to cause their true identity or the true nature of their work to be revealed.","ex":{"en":"Asking those kind of questions could blow my cover","cn":"问那种问题会暴露我的身份。"}},{"pos":"PHRASE 短语","cn":"(通常为到达另一地点)离开隐蔽处，冲出躲藏处","en":"If you break cover, you leave a place where you have been hiding or sheltering from attack, usually in order to run to another place.","ex":{"en":"They began running again, broke cover and dashed towards the road.","cn":"他们又开始跑，离开隐蔽处朝公路冲去。"}},{"pos":"PHRASE 短语","cn":"躲避(炮火、轰炸或坏天气)","en":"If you take cover, you shelter from gunfire, bombs, or the weather.","ex":{"en":"Shoppers took cover behind cars as police marksmen returned fire.","cn":"警方的射击手开火回击时，购物者们躲在汽车后面。"}},{"pos":"PHRASE 短语","cn":"在…的遮掩下(躲避炮火轰炸、坏天气等)","en":"If you are under cover, you are under something that protects you from gunfire, bombs, or the weather.","ex":{"en":"'Get under cover!' shouted Billy, and we darted once more for the tables.","cn":"“躲起来！”比利喊道，我们便又一次冲向桌子。"}},{"pos":"PREP-PHRASE 短语介词","cn":"在…的掩护下","en":"If you do something under cover of a particular situation, you are able to do it without being noticed because of that situation.","ex":{"en":"They move under cover of darkness.","cn":"他们在黑暗的掩护下行进。"}},{"pos":"PHRASE 短语","cn":"保护自己(免受批评、谴责等);辩解","en":"If you cover your back or cover your rear, you do something in order to protect yourself, for example against criticism or against accusations of doing something wrong.","ex":{"en":"The canny Premier covered his back by pointing out that he was of Scottish stock.","cn":"精明狡猾的首相辩解说自己是苏格兰血统。"}},{"pos":"PHRASE 短语","cn":"同 cover your back","en":"Cover your ass means the same as cover your back .","ex":{"en":"Just play it safe, cover your ass, keep your head down.","cn":"要谨慎行事，保护好自己并保持低调。"}},{"pos":"","cn":"","en":"相关词组：cover up"}]},"examples":[{"en":"I have to go out for a minute — will you cover for me if anyone asks where I am?","cn":"我得出去一会儿，假如有人问起我在哪里你能为我搪塞一下吗？"},{"en":"He had attempted to cover his tracks by making her death appear like suicide.","cn":"他使她的死亡看起来像是自杀，企图以此掩盖自己的罪行。"}]},"contest":{"oxford":{"phon":"ˈkɒntest","pos":"noun","senses":[{"en":"a competition in which people try to win something","cn":"比赛；竞赛","ex":{"en":"to hold a singing/talent contest","cn":"举办歌唱／才艺比赛"}},{"en":"a struggle to gain control or power","cn":"（控制权或权力的）争夺，竞争","ex":{"en":"the leadership/presidential contest","cn":"领导职位／总统竞选"}},{"en":"to take part in a competition, election, etc. and try to win it","cn":"争取赢得（比赛、选举等）","ex":{"en":"Three candidates contested the leadership.","cn":"有三位候选人角逐领导权。"},"pos":"verb"},{"en":"to formally oppose a decision or statement because you think it is wrong","cn":"争辩；就…提出异议","ex":{"en":"to contest a will (= try to show that it was not correctly made in law)","cn":"对遗嘱提出质疑"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"竞赛;比赛","en":"A contest is a competition or game in which people try to win.","ex":{"en":"Few contests in the recent history of British boxing have been as thrilling.","cn":"英国近年的拳击比赛中很少有如此激动人心的。"}},{"pos":"N-COUNT 可数名词","cn":"(权力或控制权的)争夺，竞争","en":"A contest is a struggle to win power or control.","ex":{"en":"The state election due in November will be the last such ballot before next year's presidential contest","cn":"定于11月举行的州选举将是明年总统竞选前最后一次此类投票选举。"}},{"pos":"VERB 动词","cn":"争取赢得(选举、比赛等);角逐","en":"If someone contests an election or competition, they take part in it and try to win it.","ex":{"en":"He quickly won his party's nomination to contest the elections.","cn":"他很快获得了本党提名,角逐大选。"}},{"pos":"VERB 动词","cn":"争辩;对…提出异议","en":"If you contest a statement or decision, you object to it formally because you think it is wrong or unreasonable.","ex":{"en":"Your former employer has to reply within 14 days in order to contest the case","cn":"你的前任雇主若对本案存有异议，必须在14天内予以答复。"}}]},"media":{"uk":"media/uk/xcontest__gb_1.mp3","us":"media/us/xcontest__us_1.mp3"},"examples":[{"en":"The divorce was not contested.","cn":"这桩离婚案没有人提出异议。"},{"en":"Three candidates contested the leadership.","cn":"有三位候选人角逐领导权。"}]},"comprehensive":{"media":{"uk":"media/uk/comprehensive__gb_1.mp3","us":"media/us/comprehensive__us_1.mp3"},"oxford":{"phon":"ˌkɒmprɪˈhensɪv","pos":"adjective","senses":[{"en":"including all, or almost all, the items, details, facts, information, etc., that may be involved","cn":"全部的；所有的；（几乎）无所不包的；详尽的","ex":{"en":"a comprehensive list of addresses","cn":"详尽的地址目录"}},{"en":"designed for students of all abilities in the same school","cn":"综合性的（接收各种资质的学生）","lab":"British English"},{"en":"gained or lost by a large amount","cn":"压倒性的；彻底的；完全的","ex":{"en":"The cricket team finished the season with a comprehensive victory over their rivals.","cn":"板球队以全面战胜对手的方式结束了本赛季。"}},{"en":"(in the UK) a secondary school for young people of all levels of ability","cn":"（英国为各种资质的学生设立的）综合中学","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"综合性的;全面的","en":"Something that is comprehensive includes everything that is needed or relevant.","ex":{"en":"The Rough Guide to Nepal is a comprehensive guide to the region.","cn":"《尼泊尔概况》是一本全面介绍该地区的旅游指南。"}},{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"(英国的公立性)综合中学","en":"In Britain, a comprehensive is a state school in which children of all abilities are taught together.","ex":{"en":"...Birmingham's inner-city comprehensives","cn":"伯明翰旧城区的综合中学"}}]},"examples":[{"en":"comprehensive insurance (= covering all risks)","cn":"综合保险"},{"en":"a comprehensive list of addresses","cn":"详尽的地址目录"}]},"coral":{"media":{"uk":"media/uk/coral__gb_1.mp3","us":"media/us/coral__us_1.mp3","img":["media/ldoce/img/coral.jpg"]},"oxford":{"phon":"ˈkɒrəl","pos":"noun","senses":[{"en":"a hard substance that is red, pink or white in colour, and that forms on the bottom of the sea from the bones of very small creatures. Coral is often used in jewellery.","cn":"珊瑚","g":"[uncountable]","ex":{"en":"coral reefs/islands","cn":"珊瑚礁；珊瑚岛"}},{"en":"a creature that produces coral","cn":"珊瑚虫","g":"[countable]"},{"en":"pink or red in colour, like coral","cn":"珊瑚色的；红色的；粉红的","ex":{"en":"coral lipstick","cn":"珊瑚色的唇膏"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"珊瑚","en":"Coral is a hard substance formed from the bones of very small sea animals. It is often used to make jewellery.","ex":{"en":"The women have elaborate necklaces of turquoise and pink coral.","cn":"那些女人戴着由绿松石和粉色珊瑚制成的精美项链。"}},{"pos":"N-COUNT 可数名词","cn":"珊瑚虫","en":"Corals are very small sea animals."},{"pos":"COLOUR 颜色词","cn":"珊瑚色;珊瑚红;橘红色","en":"Something that is coral is dark orangey-pink in colour.","ex":{"en":"...coral lipstick.","cn":"珊瑚红色的唇膏"}}]},"examples":[{"en":"coral lipstick","cn":"珊瑚色的唇膏"},{"en":"coral reefs/islands","cn":"珊瑚礁/岛"}]},"convince":{"media":{"uk":"media/uk/xconvince__gb_1.mp3","us":"media/us/xconvince__us_1.mp3"},"oxford":{"phon":"kənˈvɪns","pos":"verb","senses":[{"en":"to make somebody/yourself believe that something is true","cn":"使确信；使相信；使信服","ex":{"en":"Are the prime minister's assurances enough to convince the public?","cn":"首相的保证是否足以令公众信服？"}},{"en":"to persuade somebody to do something","cn":"说服，劝说（某人做某事）","lab":"British English","ex":{"en":"I've been trying to convince him to see a doctor.","cn":"我一直劝他去看病。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使确信;使信服;使相信","en":"If someone or something convinces you of something, they make you believe that it is true or that it exists.","ex":{"en":"Although I soon convinced him of my innocence, I think he still has serious doubts about my sanity","cn":"虽然我很快便让他相信我是清白的，但是我想他仍然非常怀疑我是否神志正常。"}},{"pos":"VERB 动词","cn":"说服;劝服","en":"If someone or something convinces you to do something, they persuade you to do it.","ex":{"en":"That weekend in Plattsburgh, he convinced her to go ahead and marry Bud.","cn":"在普拉茨堡的那个周末，他说服她嫁给巴德。"}}]},"examples":[{"en":"You'll need to convince them of your enthusiasm for the job.","cn":"你要使他们相信你殷切希望得到这份工作。"},{"en":"I'd convinced myself (that) I was right.","cn":"我确信自己是正确的。"}]},"collection":{"media":{"uk":"media/uk/collection__gb_1.mp3","us":"media/us/collection__us_1.mp3"},"oxford":{"phon":"kəˈlekʃn","pos":"noun","senses":[{"en":"a group of objects, often of the same sort, that have been collected","cn":"（常指同类的）收集物，收藏品","g":"[countable]","sc":"group of objects/people","ex":{"en":"He wanted to share his vast art collection with the world.","cn":"他想与世界分享他庞大的艺术收藏。"}},{"en":"a group of objects or people","cn":"一批物品；一群人","g":"[countable]","sc":"group of objects/people","ex":{"en":"There was a collection of books and shoes on the floor.","cn":"地板上有成堆的书和鞋。"}},{"en":"an act of taking something away from a place; an act of bringing things together into one place","cn":"取走；拿走；聚集；聚积","g":"[countable, uncountable]","sc":"taking away/bringing together","ex":{"en":"The first stage in research is data collection.","cn":"研究工作的第一步是收集资料。"}},{"en":"a group of poems, stories or pieces of music published together as one book, etc.","cn":"作品集","g":"[countable]","sc":"poems/stories/music","ex":{"en":"a collection of stories by women writers","cn":"女作家小说集"}},{"en":"an act of collecting money to help a charity or during a church service; the money collected","cn":"（为慈善机构或做礼拜时的）募捐，募集；募集的钱","g":"[countable]","sc":"money","ex":{"en":"a house-to-house collection for Cancer Research","cn":"为资助癌症研究院挨门逐户进行的募捐"}},{"en":"a range of new clothes or items for the home that are designed, made and offered for sale, often for a particular season","cn":"（常为季节性推出的）系列时装（或家居用品）","g":"[countable]","lab":"North American English also","sc":"new clothes","ex":{"en":"Armani’s stunning new autumn collection","cn":"款式新颖靓丽的阿玛尼秋装系列"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(一批)收藏品，收集物","en":"A collection of things is a group of similar things that you have deliberately acquired, usually over a period of time.","ex":{"en":"Robert's collection of prints and paintings has been bought over the years","cn":"这些年来，罗伯特逐渐收藏了一批版画和绘画作品。"}},{"pos":"N-COUNT 可数名词","cn":"(故事、诗歌或文章的)集子，作品集","en":"A collection of stories, poems, or articles is a number of them published in one book.","ex":{"en":"Two years ago he published a collection of short stories called 'Facing The Music'","cn":"两年前，他出版了短篇小说集《勇敢面对》。"}},{"pos":"N-COUNT 可数名词","cn":"一堆，一群(东西)","en":"A collection of things is a group of things.","ex":{"en":"Wye Lea is a collection of farm buildings that have been converted into an attractive complex.","cn":"“怀河草地”是一处由农舍改造而成的赏心悦目的建筑群。"}},{"pos":"N-COUNT 可数名词","cn":"(为新季设计的)系列时装","en":"A fashion designer's new collection consists of the new clothes they have designed for the next season."},{"pos":"N-UNCOUNT 不可数名词","cn":"收集;采集","en":"Collection is the act of collecting something from a place or from people.","ex":{"en":"Money can be sent to any one of 22,000 agents worldwide for collection.","cn":"可以把钱汇给分布在世界各地的22,000名筹款代理人中的任何一位。"}},{"pos":"N-COUNT 可数名词","cn":"募捐","en":"If you organize a collection for charity, you collect money from people to give to charity.","ex":{"en":"I asked my headmaster if he could arrange a collection for a refugee charity.","cn":"我问校长他是否能为救济难民的慈善机构组织一次募捐。"}},{"pos":"N-COUNT 可数名词","cn":"(教堂礼拜时的)捐款","en":"A collection is money that is given by people in church during some Christian services."}]},"examples":[{"en":"There is always a strange collection of runners in the London Marathon.","cn":"每次总会有一批稀奇古怪的选手参加伦敦马拉松比赛。"},{"en":"The last collection from this postbox is at 5.15.","cn":"这邮筒最后一次收信的时间是 5:15。"}]},"contemporary":{"media":{"uk":"media/uk/xcontemporary__gb_1.mp3","us":"media/us/xcontemporary__us_1.mp3"},"oxford":{"phon":"kənˈtemprəri","pos":"adjective","senses":[{"en":"belonging to the same time","cn":"属同时期的；同一时代的","ex":{"en":"We have no contemporary account of the battle (= written near the time that it happened).","cn":"我们没有当时人们对这一战役的记载。"}},{"en":"belonging to the present time","cn":"当代的；现代的","ex":{"en":"contemporary society/culture","cn":"当代社会／文化"}},{"en":"following modern ideas in style or design","cn":"当代的；现代的","ex":{"en":"Try some contemporary colours on your kitchen walls.","cn":"在厨房墙壁上尝试一些现代颜色。"}},{"en":"a person who lives or lived at the same time as somebody else, especially somebody who is about the same age","cn":"同代人；同辈人；同龄人","ex":{"en":"She and I were contemporaries at college.","cn":"她和我在大学是同学。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"当代的;现代的","en":"Contemporary things are modern and relate to the present time.","ex":{"en":"She writes a lot of contemporary music for people like Whitney Houston","cn":"她给像惠特尼·休斯敦这样的人写了很多当代音乐作品。"}},{"pos":"ADJ 形容词","cn":"同时发生的;同时期的;同时代的","en":"Contemporary people or things were alive or happened at the same time as something else you are talking about.","ex":{"en":"...drawing upon official records and the reports of contemporary witnesses.","cn":"利用官方的记录与当时的见证者的报告"}},{"pos":"N-COUNT 可数名词","cn":"同时期的人;同时代的人","en":"Someone's contemporary is a person who is or was alive at the same time as them.","ex":{"en":"Like most of my contemporaries, I grew up in a vastly different world.","cn":"和大多数同辈人一样，我生长在一个截然不同的世界。"}}]},"examples":[{"en":"He was a contemporary of Freud and may have known him.","cn":"他是弗洛伊德的同代人，可能认识弗洛伊德。"},{"en":"We have no contemporary account of the battle (= written near the time that it happened).","cn":"我们没有当时人们对这一战役的记载。"}]},"cottages":{"lemma":"cottage"},"concentrate":{"media":{"uk":"media/uk/xconcentrate__gb_1.mp3","us":"media/us/xconcentrate__us_1.mp3"},"oxford":{"phon":"ˈkɒnsntreɪt","pos":"verb","senses":[{"en":"to give all your attention to something and not think about anything else","cn":"集中（注意力）；聚精会神","g":"[intransitive, transitive]","ex":{"en":"I can't concentrate with all that noise going on.","cn":"吵闹声不绝于耳，我无法集中精神。"}},{"en":"to bring something together in one place","cn":"使…集中（或集合、聚集）","g":"[transitive]","ex":{"en":"Power is largely concentrated in the hands of a small elite.","cn":"权力主要集中在少数精英人物的手里。"}},{"en":"to increase the strength of a substance by reducing its volume, for example by boiling it","cn":"（使）浓缩","g":"[transitive]","lab":"specialist"},{"en":"a substance that is made stronger because water or other substances have been removed","cn":"浓缩物","ex":{"en":"mineral concentrates found at the bottom of rivers","cn":"在河底发现的精矿"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"全神贯注;集中（心思）","en":"If you concentrate on something, or concentrate your mind on it, you give all your attention to it.","ex":{"en":"It was up to him to concentrate on his studies and make something of himself","cn":"是否能专心学习并取得一定成就要靠他自己。"}},{"pos":"VERB 动词","cn":"使集中;使汇集","en":"If something is concentrated in an area, it is all there rather than being spread around.","ex":{"en":"Italy's industrial districts are concentrated in its north-central and north-eastern regions","cn":"意大利的工业区集中在该国中北部和东北部地区。"}},{"pos":"N-MASS 物质名词","cn":"浓缩液;浓缩物","en":"Concentrate is a liquid or substance from which water has been removed in order to make it stronger, or to make it easier to store.","ex":{"en":"...orange juice made from concentrate.","cn":"用浓缩橙汁冲兑的橙汁"}},{"pos":"PHRASE 短语","cn":"使清楚地思考","en":"If you say that an unpleasant fact or situation concentrates someone's mind, you mean that it makes them think clearly, because they are aware of the serious consequences if they do not.","ex":{"en":"A term in prison will concentrate his mind wonderfully.","cn":"一想到要被判刑，他的头脑就会变得非常清醒。"}}]},"examples":[{"en":"Nothing concentrates the mind better than the knowledge that you could die tomorrow (= it makes you think very clearly).","cn":"没有什么比知道自己明天就可能会死去更能让人定下心来去思考种种问题的了。"},{"en":"In this lecture I shall concentrate on the early years of Charles's reign.","cn":"这一节课我将着重讲查理王朝的早期统治时期。"}]},"construction":{"oxford":{"phon":"kənˈstrʌkʃn","pos":"noun","senses":[{"en":"the process or method of building or making something, especially roads, buildings, bridges, etc.","cn":"建筑；建造；施工","g":"[uncountable]","sc":"of roads/buildings","ex":{"en":"Construction began this year and will take approximately 18 months.","cn":"施工今年已经开始，大约将需要 18 个月。"}},{"en":"the people and activities involved in making buildings","cn":"建筑业","g":"[uncountable]","sc":"of roads/buildings","ex":{"en":"50 000 more jobs will go from construction in the next five years.","cn":"未来五年，建筑业将再失去 5 万个就业岗位。"}},{"en":"the way that something has been built or made","cn":"建造（或构造）的方式","g":"[uncountable, singular]","sc":"of roads/buildings","ex":{"en":"The bridges are similar in construction.","cn":"这些桥的构造相似。"}},{"en":"a thing that has been built or made","cn":"建造物；构筑物；制成物","g":"[countable]","lab":"formal","sc":"building/structure","ex":{"en":"The summer house was a simple wooden construction.","cn":"那座避暑别墅是简单的木结构建筑。"}},{"en":"the way in which words are used together and arranged to form a sentence, phrase, etc.","cn":"（句子、短语等的）结构","g":"[countable]","sc":"grammar","ex":{"en":"grammatical constructions","cn":"语法结构"}},{"en":"the creating of something from ideas, opinions and knowledge","cn":"（理念、观点和知识的）创造，创立，建立","g":"[uncountable, countable]","sc":"of theory, etc.","ex":{"en":"the construction of a new theory","cn":"新理论的创立"}},{"en":"the way in which words, actions, statements, etc. are understood by somebody","cn":"（对词语、行为、陈述等的）解释，说明，理解","g":"[countable]","lab":"formal","sc":"meaning","ex":{"en":"What construction do you put on this letter (= what do you think it means)?","cn":"你对这封信如何理解？"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(房屋、工厂、道路、桥梁等的)建筑，建造","en":"Construction is the building of things such as houses, factories, roads, and bridges.","ex":{"en":"He'd already started construction on a hunting lodge.","cn":"他已经开始建造一间狩猎用的小屋。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(车辆、机器等的)制造，建造","en":"The construction of something such as a vehicle or machine is the making of it.","ex":{"en":"...companies who have long experience in the construction of those types of equipment","cn":"长期从事此类设备制造的公司"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(体系等的)构建，创建","en":"The construction of something such as a system is the creation of it.","ex":{"en":"...the construction of a just system of criminal justice.","cn":"一套公正的刑事审判制度的创建"}},{"pos":"N-COUNT 可数名词","cn":"建造物;制造物","en":"You can refer to an object that has been built or made as a construction .","ex":{"en":"The British pavilion is an impressive steel and glass construction the size of Westminster Abbey.","cn":"这座英式亭阁是令人赞叹的钢和玻璃建筑，大小和威斯敏斯特教堂相当。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"构造；结构","en":"You use construction to refer to the structure of something and the way it has been built or made.","ex":{"en":"The Shakers believed that furniture should be plain, simple, useful, practical and of sound construction","cn":"震颤派教徒认为家具应当朴素、简单、有用、实用，并且结构合理。"}},{"pos":"N-COUNT 可数名词","cn":"(对某人言行的)解释，理解，阐释","en":"The construction that you put on what someone says or does is your interpretation of what it means.","ex":{"en":"The denial was limited to rejecting the construction put on his remarks","cn":"这种否认仅限于不接受对他所说话语的阐释。"}},{"pos":"N-COUNT 可数名词","cn":"(语法)结构","en":"A grammatical construction is a particular arrangement of words in a sentence, clause, or phrase.","ex":{"en":"Avoid complex verbal constructions.","cn":"避免使用复杂的动词结构。"}}]},"media":{"uk":"media/uk/xconstruction__gb_1.mp3","us":"media/us/xconstruction__us_1.mp3"},"examples":[{"en":"The summer house was a simple wooden construction.","cn":"那座避暑别墅是简单的木结构建筑。"},{"en":"Our new offices are still under construction (= being built).","cn":"我们的新办公楼尚在修建中。"}]},"cos":{"oxford":{"phon":"kəz","pos":"conjunction","senses":[{"en":"because","cn":"因为","ex":{"en":"I can't see her at all, cos it's too dark.","cn":"天太黑，我根本看不见她。"}},{"en":"(in writing) cosine","cn":"（书写形式）余弦","pos":"abbreviation"}]},"media":{"uk":"media/uk/cos__gb_3.mp3","us":"media/us/cos__us_1.mp3"},"examples":[{"en":"I can't see her at all, cos it's too dark.","cn":"天太黑，我根本看不见她。"},{"en":"I don’t get out much now cos of the children.","cn":"因为孩子的关系﹐我现在不大出去了。"}]},"couple":{"media":{"uk":"media/uk/couple__gb_1.mp3","us":"media/us/couple__us_1.mp3"},"oxford":{"phon":"ˈkʌpl","pos":"noun","senses":[{"en":"two people or things","cn":"两人；两件事物","g":"[singular + singular or plural verb]","ex":{"en":"I saw a couple of men get out.","cn":"我看见有两个男人出去了。"}},{"en":"a small number of people or things","cn":"少数人（或事物）","g":"[singular + singular or plural verb]","ex":{"en":"We went there a couple of years ago.","cn":"我们几年前去过那里。"}},{"en":"two people who are seen together, especially if they are married or in a romantic or sexual relationship","cn":"（人）一对；（尤指）夫妻，情侣","g":"[countable + singular or plural verb]","lab":"especially North American English","ex":{"en":"married couples","cn":"几对夫妇"}},{"en":"to join together two parts of something, for example two vehicles or pieces of equipment","cn":"（把车辆或设备等）连接，结合","g":"[transitive, usually passive]","ex":{"en":"The two railway trucks had been coupled together.","cn":"这两节铁道货运车厢给连在了一起。"},"pos":"verb"},{"en":"to have sex","cn":"性交；做爱；交配","g":"[intransitive]","lab":"formal","pos":"verb"}]},"collins":{"senses":[{"pos":"QUANT 数量词","cn":"两个;几个","en":"If you refer to a couple of people or things, you mean two or approximately two of them, although the exact number is not important or you are not sure of it.","ex":{"en":"Across the street from me there are a couple of police officers standing guard","cn":"我对面的街上有几名警官在站岗。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"夫妻;情人","en":"A couple is two people who are married, living together, or having a sexual relationship.","ex":{"en":"The couple have no children.","cn":"这对夫妻没有孩子。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"(在某种场合在一起或有某种关系的)一对人，两个人","en":"A couple is two people that you see together on a particular occasion or that have some association.","ex":{"en":"...as the four couples began the opening dance","cn":"4对舞伴开始跳开场舞的时候"}},{"pos":"VERB 动词","cn":"加上;结合","en":"If you say that one thing produces a particular effect when it is coupled with another, you mean that the two things combine to produce that effect.","ex":{"en":"...a problem that is coupled with lower demand for the machines themselves","cn":"这个问题外加上对机器本身需求量的下降"}},{"pos":"VERB 动词","cn":"(把设备等)连接，结合","en":"If one piece of equipment is coupled to another, it is joined to it so that the two pieces of equipment work together.","ex":{"en":"Its engine is coupled to a semiautomatic gearbox","cn":"它的发动机与一个半自动变速箱相连接。"}}]},"examples":[{"en":"CDTV uses a CD-ROM system that is coupled to a powerful computer.","cn":"动态视频系统使用的是与大功率计算机相连的只读光盘系统。"},{"en":"I'll be with you in a minute. There are a couple of things I have to do first.","cn":"我一会儿就到你那里去。我有几件事情得先处理一下。"}]},"condensation":{"media":{"uk":"media/uk/xcondensation__gb_1.mp3","us":"media/us/xcondensation__us_1.mp3"},"oxford":{"phon":"ˌkɒndenˈseɪʃn","pos":"noun","senses":[{"en":"drops of water that form on a cold surface when warm water vapour becomes cool","cn":"凝结的水珠","g":"[uncountable]","ex":{"en":"The window was steamed up with condensation.","cn":"窗户上结满了水汽。"}},{"en":"the process of a gas changing to a liquid","cn":"（气体）冷凝，凝结","g":"[uncountable]"},{"en":"the process of making a book, etc. shorter by taking out anything that is not necessary","cn":"（书等的）简缩","g":"[countable, usually singular, uncountable]","lab":"formal","ex":{"en":"The essay should be a readable condensation of the recent scientific literature.","cn":"这篇文章应该是最新科学文献的可读浓缩。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"凝结的水珠","en":"Condensation consists of small drops of water which form when warm water vapour or steam touches a cold surface such as a window.","ex":{"en":"He used his sleeve to wipe the condensation off the glass.","cn":"他用袖子擦掉玻璃上凝结的水珠。"}}]},"examples":[{"en":"There was a lot of condensation on the windows.","cn":"窗户上有许多水珠。"}]},"concerned":{"media":{"uk":"media/uk/xconcerned__gb_1.mp3","us":"media/us/xconcerned__us_1.mp3"},"oxford":{"phon":"kənˈsɜːnd","pos":"adjective","senses":[{"en":"worried and feeling concern about something/somebody","cn":"担心的；忧虑的","ex":{"en":"Concerned citizens can have a huge impact.","cn":"焦虑的市民可能具有巨大的冲击力。"}},{"en":"affected by something; involved in something","cn":"受影响；涉及","g":"[not before noun]","ex":{"en":"The loss was a tragedy for all concerned.","cn":"这一损失对有关各方来说都是一场不幸。"}},{"en":"interested in something; dealing with something","cn":"关心；关于","g":"[not before noun]","ex":{"en":"The public is increasingly concerned with how food is produced.","cn":"公众越来越关心食品是如何生产的。"}},{"en":"to think it is important to do something","cn":"认为（做某事）重要","lab":"formal","ex":{"en":"She was concerned to write about situations that everybody could identify with.","cn":"她认为应该写大家都能产生共鸣的情境。"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"认为重要的;关注的","en":"If you are concerned to do something, you want to do it because you think it is important.","ex":{"en":"We were very concerned to keep the staff informed about what we were doing.","cn":"我们很注重让员工随时了解我们正在做的事情。"}}]},"examples":[{"en":"They were more concerned with how the other women had dressed than with what the speaker was saying.","cn":"他们对其他女人的衣着打扮比对演讲者的讲话更加感兴趣。"},{"en":"She was concerned that she might miss the turning and get lost.","cn":"她担心自己会错过转弯的地方而迷路。"}],"base":"concern"},"coming":{"media":{"uk":"media/uk/coming__gb_1.mp3","us":"media/us/coming__us_1.mp3"},"oxford":{"phon":"ˈkʌmɪŋ","pos":"noun","senses":[{"en":"the time when something new begins or somebody arrives","cn":"到来；来临；到达","ex":{"en":"With the coming of modern technology, many jobs were lost.","cn":"随着现代技术的到来，许多工作岗位不复存在。"}},{"en":"happening soon; next","cn":"即将发生的；下一个的","ex":{"en":"in the coming months","cn":"在随后的几个月里"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(事件或时间)即将到来的，即将发生的","en":"A coming event or time is an event or time that will happen soon.","ex":{"en":"This obviously depends on the weather in the coming months","cn":"这显然取决于未来几个月的天气。"}}]},"examples":[{"en":"With the coming of modern technology, many jobs were lost.","cn":"随着现代技术的到来，许多工作岗位不复存在。"},{"en":"It's hard to keep track of the children's comings and goings.","cn":"这些孩子来来往往，很难跟得上他们的行踪。"}]},"costly":{"media":{"uk":"media/uk/costly__gb_1.mp3","us":"media/us/costly__us_1.mp3"},"oxford":{"phon":"ˈkɒstli","pos":"adjective","senses":[{"en":"costing a lot of money, especially more than you want to pay","cn":"花钱多的；昂贵的；价钱高的","lab":"British English","ex":{"en":"Buying new furniture may prove too costly.","cn":"购买新家具可能会花钱太多。"}},{"en":"causing problems or the loss of something","cn":"引起困难的；造成损失的","ex":{"en":"a costly mistake/failure","cn":"造成重大损失的错误／失败"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"昂贵的;价格高的","en":"If you say that something is costly, you mean that it costs a lot of money, often more than you would want to pay.","ex":{"en":"Having professionally made curtains can be costly, so why not make your own?","cn":"既然找专门人员做窗帘非常贵，为什么不自己做呢?"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"造成严重损失的;代价大的","en":"If you describe someone's action or mistake as costly, you mean that it results in a serious disadvantage for them, for example the loss of a large amount of money or the loss of their reputation.","ex":{"en":"Psychometric tests can save organizations from grim and costly mistakes","cn":"心理测试能够使组织机构避免犯下损失惨重的大错。"}}]},"examples":[{"en":"Mining can be costly in terms of lives (= too many people can die).","cn":"采矿有时会造成重大的生命损失。"},{"en":"Buying new furniture may prove too costly.","cn":"购买新家具可能会花钱太多。"}]},"comparisons":{"lemma":"comparison","media":{"uk":"media/uk/comparison__gb_1.mp3","us":"media/us/comparison__us_1.mp3"}},"competitiveness":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the ability of a company, country, or a product to compete with others","cn":"竞争力"},{"en":"the desire to be more successful than other people","cn":"好胜﹐要强"}]},"examples":[{"en":"New machinery has enhanced the company’s productivity and competitiveness.","cn":"新机器帮助公司提高了生产力﹐增强了竞争力。","src":"ld"},{"en":"Her enthusiasm and competitiveness rubbed off on everyone.","cn":"她的热情和好强感染了每一个人。","src":"ld"}],"media":{"uk":"media/uk/competitiveness__gb_1.mp3","us":"media/us/competitiveness__us_1.mp3"},"oxford":{"phon":"kəmˈpetətɪvnəs","pos":"noun","senses":[{"en":"the fact of people or organizations competing against each other","cn":"竞争性：人与人之间或组织与组织之间的竞争。","ex":{"en":"professions involving a higher degree of competitiveness such as marketing and business administration","cn":"市场营销、工商管理等竞争力较高的职业"}},{"en":"the fact of being as good as or better than others","cn":"竞争力：与他人一样好或更好","ex":{"en":"the competitiveness of British industry","cn":"英国的产业竞争力"}},{"en":"the fact of trying very hard to be better than others","cn":"努力超越别人的事实","ex":{"en":"I love his work ethic and his competitiveness.","cn":"我喜欢他的职业道德和竞争力。"}}]}},"comfort":{"media":{"uk":"media/uk/comfort__gb_1.mp3","us":"media/us/comfort__us_1.mp3"},"oxford":{"phon":"ˈkʌmfət","pos":"noun","senses":[{"en":"the state of being physically relaxed and free from pain; the state of having a pleasant life, with everything that you need","cn":"舒服；安逸；舒适","g":"[uncountable]","ex":{"en":"The hotel offers a high standard of comfort and service.","cn":"这家旅馆提供高标准的舒适享受和优质服务。"}},{"en":"a feeling of not suffering or worrying so much; a feeling of being less unhappy","cn":"安慰；慰藉；宽慰","g":"[uncountable]","ex":{"en":"I tried to offer a few words of comfort.","cn":"我试图说上几句安慰的话。"}},{"en":"a person or thing that helps you when you are suffering, worried or unhappy","cn":"令人感到安慰的人（或事物）","g":"[singular]","ex":{"en":"Her being with me was such a comfort.","cn":"她和我在一起真是一种安慰。"}},{"en":"a thing that makes your life easier or more comfortable","cn":"舒适的设施（或条件）","g":"[countable, usually plural]","ex":{"en":"The hotel has all modern comforts/every modern comfort.","cn":"这家旅馆拥有各种现代化的舒适设施。"}},{"en":"to make somebody who is worried or unhappy feel better by being kind and showing sympathy to them","cn":"安慰；抚慰；宽慰","ex":{"en":"The victim's widow was today being comforted by family and friends.","cn":"受害人的遗孀今天正受到亲属和朋友的安慰。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"舒适;舒服","en":"If you are doing something in comfort, you are physically relaxed and contented, and are not feeling any pain or other unpleasant sensations.","ex":{"en":"This will enable the audience to sit in comfort while watching the shows","cn":"这样能够让观众舒舒服服地坐着看表演。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"舒适的生活方式;安逸","en":"Comfort is a style of life in which you have enough money to have everything you need.","ex":{"en":"Surely there is some way of ordering our busy lives so that we can live in comfort and find spiritual harmony too.","cn":"总会有办法能安排好我们忙碌的生活，这样就能过得舒服一点，同时还能达到内心的平静。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"安慰;慰藉","en":"Comfort is what you feel when worries or unhappiness stop.","ex":{"en":"He welcomed the truce, but pointed out it was of little comfort to families spending Christmas without a loved one","cn":"他欣然接受休战，但是指出，那些无法和心爱的人一起过圣诞的家庭并不会由此感到慰藉。"}},{"pos":"N-COUNT 可数名词","cn":"令人感到安慰的人(或事物)","en":"If you refer to a person, thing, or idea as a comfort, you mean that it helps you to stop worrying or makes you feel less unhappy.","ex":{"en":"At least he has given her a child who will be a great comfort to her in the years ahead","cn":"至少他留给她一个孩子，这孩子在未来的岁月里对她将是莫大的安慰。"}},{"pos":"VERB 动词","cn":"安慰;抚慰","en":"If you comfort someone, you make them feel less worried, unhappy, or upset, for example by saying kind things to them.","ex":{"en":"Ned put his arm around her, trying to comfort her.","cn":"内德搂着她，想安慰她。"}},{"pos":"N-COUNT 可数名词","cn":"使生活舒适的东西","en":"Comforts are things which make your life easier and more pleasant, such as electrical devices you have in your home.","ex":{"en":"She enjoys the material comforts married life has brought her","cn":"她喜欢婚姻生活带给她的物质享受。"}},{"pos":"PHRASE 短语","cn":"因太…而令人担忧","en":"If you say that something is, for example, too close for comfort, you mean you are worried because it is closer than you would like it to be.","ex":{"en":"The bombs fell in the sea, many too close for comfort","cn":"这些炸弹落入海中，很多离岸边太近，令人担忧。"}}]},"examples":[{"en":"With DVD, you can watch the latest movies in the comfort of your own home.","cn":"有了 DVD，你就可以在自己家里舒舒服服地看最新的电影。"},{"en":"The children have been a great comfort to me through all of this.","cn":"在我度过这一切的日子里，孩子们一直是我的莫大安慰。"}]},"col":{"media":{"uk":"media/uk/col__gb_1.mp3","us":"media/us/col__us_1.mp3"},"oxford":{"phon":"kɒl","pos":"noun","senses":[{"en":"a low point between two higher points in a mountain range, typically providing a pass (= road or way) through the mountains","cn":"（山脉中两个山峰之间的）山口"},{"en":"(in writing) column","cn":"（书写形式）栏","pos":"abbreviation"},{"en":"(in writing) colonel","cn":"（书写形式）上校","ex":{"en":"Col. Stewart","cn":"斯图尔特上校"},"pos":"abbreviation"}]}},"condensed":{"lemma":"condense"},"conviction":{"media":{"uk":"media/uk/xconviction__gb_1.mp3","us":"media/us/xconviction__us_1.mp3"},"oxford":{"phon":"kənˈvɪkʃn","pos":"noun","senses":[{"en":"the act of finding somebody guilty of a crime in court; the fact of having been found guilty","cn":"判罪；定罪；证明有罪","g":"[countable, uncountable]","lab":"especially North American English","ex":{"en":"He plans to appeal against his conviction.","cn":"他不服判决，准备上诉。"}},{"en":"a strong opinion or belief","cn":"坚定的看法（或信念）","g":"[countable, uncountable]","ex":{"en":"strong political/moral convictions","cn":"坚定不移的政治／道德信念"}},{"en":"the quality of showing that you believe strongly in what you are saying","cn":"（对自己所说的话的）深信，坚信，坚定，肯定","g":"[uncountable]","ex":{"en":"‘Not true!’ she said with conviction.","cn":"“不真实！”她肯定地说道。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"坚定的信念(或主张)","en":"A conviction is a strong belief or opinion.","ex":{"en":"It is our firm conviction that a step forward has been taken","cn":"我们坚信已经向前迈进了一步。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"坚信;深信;确信","en":"If you have conviction, you have great confidence in your beliefs or opinions.","ex":{"en":"'We shall, sir,' said Thorne, with conviction.","cn":"“我们会的，先生，”索恩坚定地说。"}},{"pos":"PHRASE 短语","cn":"令人信服;有说服力","en":"If something carries conviction, it is likely to be true or likely to be believed.","ex":{"en":"Nor did his denial carry conviction.","cn":"他的否认也没有说服力。"}},{"pos":"N-COUNT 可数名词","cn":"定罪;判罪","en":"If someone has a conviction, they have been found guilty of a crime in a court of law.","ex":{"en":"He will appeal against his conviction","cn":"他会对判决提起上诉。"}}]},"examples":[{"en":"The leader's speech in defence of the policy didn't carry much conviction.","cn":"那位领导人为政策辩护的讲话不是很有说服力。"},{"en":"an offence which carries, on conviction, a sentence of not more than five years' imprisonment","cn":"定罪后可判处五年或以下监禁的罪行"}]},"compromise":{"media":{"uk":"media/uk/compromise__gb_1.mp3","us":"media/us/compromise__us_1.mp3"},"oxford":{"phon":"ˈkɒmprəmaɪz","pos":"noun","senses":[{"en":"an agreement made between two people or groups in which each side gives up some of the things they want so that both sides are happy at the end","cn":"妥协；折中；互让；和解","g":"[countable]","ex":{"en":"After lengthy talks the two sides finally reached a compromise.","cn":"双方经过长期的商谈终于达成了妥协。"}},{"en":"a solution to a problem in which two or more things cannot exist together as they are, in which each thing is reduced or changed slightly so that they can exist together","cn":"妥协（或折中）方案","g":"[countable]","ex":{"en":"This model represents the best compromise between price and quality.","cn":"这种型号是平衡了价格和质量的最佳折中方案。"}},{"en":"the act of reaching a compromise","cn":"达成妥协（或和解）","g":"[uncountable]","ex":{"en":"Compromise is an inevitable part of life.","cn":"妥协是生活不可避免的一部分。"}},{"en":"to give up some of your demands in order to reach an agreement after disagreeing with somebody","cn":"（为达成协议而）妥协，折中，让步","g":"[intransitive]","ex":{"en":"Neither side is prepared to compromise.","cn":"双方都不愿意妥协。"},"pos":"verb"},{"en":"to do something that is against your principles or does not reach standards that you have set","cn":"违背（原则）；达不到（标准）","g":"[transitive, intransitive]","ex":{"en":"I refuse to compromise my principles.","cn":"我拒绝在原则问题上妥协。"},"pos":"verb"},{"en":"to cause somebody/something/yourself to be in danger or to be suspected of something, especially by acting in a way that is not very sensible","cn":"（尤指因行为不很明智）使陷入危险，使受到怀疑","g":"[transitive]","ex":{"en":"She had already compromised herself by accepting his invitation.","cn":"她接受了他的邀请，这件事已经使她的声誉受到了损害。"},"pos":"verb"},{"en":"to cause something to be in danger of attack or of working less well","cn":"危害；使效用降低","g":"[transitive]","ex":{"en":"Users perform tasks every day that can compromise the security of their computers.","cn":"用户每天运行的任务有可能危害其电脑的安全性。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"折中;妥协;让步","en":"A compromise is a situation in which people accept something slightly different from what they really want, because of circumstances or because they are considering the wishes of other people.","ex":{"en":"Encourage your child to reach a compromise between what he wants and what you want","cn":"鼓励孩子在他的愿望和你的愿望之间找到一个折中点。"}},{"pos":"V-RECIP 相互动词","cn":"妥协;作出让步","en":"If you compromise with someone, you reach an agreement with them in which you both give up something that you originally wanted. You can also say that two people or groups compromise .","ex":{"en":"The government has compromised with its critics over monetary policies","cn":"政府已经就货币政策向批评人士作出让步。"}},{"pos":"VERB 动词","cn":"使（自己）声誉受损;违背(信念)","en":"If someone compromises themselves or compromises their beliefs, they do something which damages their reputation for honesty, loyalty, or high moral principles.","ex":{"en":"...members of the government who have compromised themselves by co-operating with the emergency committee","cn":"因与紧急委员会合作而使自己名誉受损的政府成员"}}]},"examples":[{"en":"After much argument, the judges finally compromised on (= agreed to give the prize to) the 18-year old pianist.","cn":"经过激烈争论，评委终于同意那个 18 岁的钢琴手获奖。"},{"en":"She had already compromised herself by accepting his invitation.","cn":"她接受了他的邀请，这件事已经使她的声誉受到了损害。"}]},"conquer":{"oxford":{"phon":"ˈkɒŋkə(r)","pos":"verb","senses":[{"en":"to take control of a country or city and its people by force","cn":"占领；攻克；征服","ex":{"en":"The Normans conquered England in 1066.","cn":"诺曼人于 1066 年征服了英格兰。"}},{"en":"to defeat somebody, especially in a competition, race, etc.","cn":"（尤指比赛、赛跑等中）击败，战胜","ex":{"en":"The world champion conquered yet another challenger last night.","cn":"昨晚这位世界冠军又战胜了一名挑战者。"}},{"en":"to succeed in dealing with or controlling something","cn":"（成功地）对付，克服，控制","ex":{"en":"The only way to conquer a fear is to face it.","cn":"克服恐惧的唯一方法是正视恐惧。"}},{"en":"to become very popular or successful in a place","cn":"在（某地）很受欢迎；在（某地）成功","ex":{"en":"The band is now setting out to conquer the world.","cn":"这支乐队现在要出发去征服世界。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"占领;征服","en":"If one country or group of people conquers another, they take complete control of their land.","ex":{"en":"During 1936, Mussolini conquered Abyssinia","cn":"1936年，墨索里尼攻占了阿比西尼亚。"}},{"pos":"VERB 动词","cn":"克服;攻克","en":"If you conquer something such as a problem, you succeed in ending it or dealing with it successfully.","ex":{"en":"I was certain that love was quite enough to conquer our differences","cn":"我相信爱足以克服我们的种种差异。"}}]},"media":{"uk":"media/uk/xconquer__gb_1.mp3","us":"media/us/xconquer__us_1.mp3"},"examples":[{"en":"The Normans conquered England in 1066.","cn":"诺曼人于 1066 年征服了英格兰。"},{"en":"The world champion conquered yet another challenger last night.","cn":"昨晚这位世界冠军又战胜了一名挑战者。"}]},"commanded":{"lemma":"command","media":{"uk":"media/uk/command__gb_1.mp3","us":"media/us/command__us_1.mp3"}},"court":{"media":{"uk":"media/uk/court__gb_1.mp3","us":"media/us/court__us_1.mp3"},"oxford":{"phon":"kɔːt","pos":"noun","senses":[{"en":"the place where legal trials take place and where crimes, etc. are judged","cn":"法院；法庭；审判庭","g":"[countable, uncountable]","lab":"British English","sc":"law","ex":{"en":"the civil/criminal courts","cn":"民事／刑事法庭"}},{"en":"the people in a court, especially those who make the decisions, such as the judge and jury","cn":"全体出庭人员；（尤指）全体审判人员","g":"[usually singular]","sc":"law","ex":{"en":"Please tell the court what happened.","cn":"请向法庭陈述事情的经过。"}},{"en":"a place where games such as tennis and basketball are played","cn":"（网球、篮球等的）球场","g":"[countable]","sc":"for sport","ex":{"en":"a tennis/squash/basketball court","cn":"网球场；壁球场；篮球场"}},{"en":"the official place where kings and queens live","cn":"王宫；宫殿；宫廷","g":"[countable, uncountable]","sc":"kings/queens","ex":{"en":"the court of Queen Victoria","cn":"维多利亚女王的宫廷"}},{"en":"the king or queen, their family, and the people who work for them and/or give advice to them","cn":"王室人员；王宫人员","g":"[singular]","sc":"kings/queens","ex":{"en":"The painting shows the emperor with his court.","cn":"这幅画画的是皇帝和皇宫里的人。"}},{"en":"an open space that is partly or completely surrounded by buildings and is usually part of a castle, a large house, etc.","cn":"（通常为城堡、大宅第等的）庭院，院子，天井","g":"[countable]","sc":"buildings"},{"en":"used in the names of blocks of flats or apartment buildings, or of some short streets; (in the UK) used in the names of some large houses","cn":"（用于套房、公寓或某些短街区的名称）公寓大楼，短街；（英国用于某些大型宅第的名称）宅第，邸宅","g":"[countable]","sc":"buildings","ex":{"en":"The building is situated in a medieval court at the top of Edinburgh's royal mile.","cn":"该建筑位于爱丁堡皇家大道顶部的中世纪宫廷内。"}},{"en":"a large open section of a building, often with a glass roof","cn":"建筑物的开阔部分（常有玻璃房顶）；大厅；馆","g":"[countable]","sc":"buildings"},{"en":"to try to please somebody in order to get something you want, especially the support of a person, an organization, etc.","cn":"（为有所求，尤指为寻求支持而）试图取悦，讨好，争取","g":"[transitive]","sc":"try to please","ex":{"en":"Both candidates have spent the last month courting the media.","cn":"两位候选人在过去的一个月里都在取悦媒体。"},"pos":"verb"},{"en":"to try to obtain something","cn":"试图获得；博得","g":"[transitive]","lab":"formal","sc":"try to get","ex":{"en":"He has never courted popularity.","cn":"他从不追求名望。"},"pos":"verb"},{"en":"to do something that might result in something unpleasant happening","cn":"招致，酿成，导致（不愉快的事）","g":"[transitive]","lab":"formal","sc":"invite something bad","ex":{"en":"to court danger/death/disaster","cn":"招致危险／死亡／灾难"},"pos":"verb"},{"en":"to have a romantic relationship with somebody that you hope to marry","cn":"恋爱","g":"[transitive, intransitive]","lab":"old-fashioned","sc":"have relationship","ex":{"en":"He had been courting Jane for six months.","cn":"他追求简已有六个月之久。"},"pos":"verb"},{"en":"(of a male bird or other animal) to try to attract a female","cn":"（雄鸟或其他雄性动物）求偶","sc":"animals","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"法院;法庭;审判庭","en":"A court is a place where legal matters are decided by a judge and jury or by a magistrate.","ex":{"en":"At this rate, we could find ourselves in the divorce courts!","cn":"照这样下去，我们会为离婚闹上法院！"}},{"pos":"N-COUNT 可数名词","cn":"全体出庭人员;(尤指)全体审判人员","en":"You can refer to the people in a court, especially the judge, jury, or magistrates, as a court .","ex":{"en":"A court at Tampa, Florida has convicted five officials on drugs charges.","cn":"佛罗里达州坦帕市法庭判决5名官员的毒品交易罪名成立。"}},{"pos":"N-COUNT 可数名词","cn":"(网球、篮球、羽毛球或壁球等的)球场","en":"A court is an area in which you play a game such as tennis, basketball, badminton, or squash.","ex":{"en":"The hotel has several tennis and squash courts","cn":"该酒店有几个网球场和壁球场。"}},{"pos":"N-COUNT 可数名词","cn":"王宫;宫殿;宫廷","en":"The court of a king or queen is the place where he or she lives and carries out ceremonial or administrative duties.","ex":{"en":"She came to visit England, where she was presented at the court of James I","cn":"她来到英国访问，在詹姆士一世的王宫受到了接见。"}},{"pos":"N-IN-NAMES 名称名词","cn":"(用于大型宅第和公寓街区的名称中)宅第，宅邸，公寓大楼","en":"In Britain, Court is used in the names of large houses and blocks of flats.","ex":{"en":"...7 Ivebury Court, Latimer Rd, London W10 6RA.","cn":"伦敦西区10号第6街区拉蒂默路艾夫伯里7号公寓大楼"}},{"pos":"PHRASE 短语","cn":"（对…）提起诉讼","en":"If you go to court or take someone to court, you take legal action against them.","ex":{"en":"They have received at least twenty thousand pounds each but had gone to court to demand more.","cn":"他们每人至少已经得到了两万英镑，但仍然向法庭提出诉讼要求获得更多。"}},{"pos":"V PHR","cn":"发表意见的机会","en":"Your day in court is your chance to give your side of an argument or other matter.","ex":{"en":"He knew that this would be his day in court — his last chance to explain why he acted as he did","cn":"他知道这是他为自己辩解的机会，是他能够解释自己为何如此行事的最后机会。"}},{"pos":"PHRASE 短语","cn":"(因为有趣或出名)引人注目，被人围观","en":"If someone holds court in a place, they are surrounded by a lot of people who are paying them a lot of attention because they are interesting or famous.","ex":{"en":"...in the days when Marlene Dietrich and Ernest Hemingway held court in the famous El Floridita club.","cn":"当马琳·黛德丽和欧内斯特·海明威在埃尔·佛罗利迪达俱乐部名噪一时的时候"}},{"pos":"PHRASE 短语","cn":"(因观点或想法可笑而)对…一笑置之，对…不予考虑","en":"If you laugh someone out of court, you say that their opinions or ideas are so ridiculous that they are not worth considering.","ex":{"en":"It's easy for a younger generation of critics to laugh Limon out of court","cn":"年轻一代的批评家很容易对利蒙的观点一笑置之。"}},{"pos":"PHRASE 短语","cn":"庭外;不经法院","en":"If a legal matter is decided or settled out of court, it is decided without legal action being taken in a court of law.","ex":{"en":"The Government is anxious to keep the whole case out of court.","cn":"政府迫切希望整件事能够在庭外解决。"}},{"pos":"VERB 动词","cn":"(为使某人、团体或国家按自己的意愿做某事而)试图取悦，讨好","en":"To court a particular person, group, or country means to try to please them or improve your relations with them, often so that they will do something that you want them to do.","ex":{"en":"Both Democratic and Republican parties are courting former supporters of Ross Perot","cn":"民主党和共和党都在极力拉拢罗斯·佩罗以前的支持者。"}},{"pos":"VERB 动词","cn":"试图获得，追求(关注或声望)","en":"If you court something such as publicity or popularity, you try to attract it.","ex":{"en":"Having spent a lifetime avidly courting publicity, Paul has suddenly become secretive.","cn":"保罗一生都在想方设法出风头，现在却突然行事低调了。"}},{"pos":"VERB 动词","cn":"招致，酿成，导致(不愉快的事)","en":"If you court something unpleasant such as disaster or unpopularity, you act in a way that makes it likely to happen.","ex":{"en":"If he thinks he can remain in power by force he is courting disaster","cn":"如果他认为可以通过武力继续掌权，那他就是在自寻死路。"}},{"pos":"V-RECIP 相互动词","cn":"追求(异性)；向…求爱;恋爱","en":"If you are courting someone of the opposite sex, you spend a lot of time with them, because you are intending to get married. You can also say that a man and a woman are courting .","ex":{"en":"I was courting Billy at 19 and married him when I was 21","cn":"我19岁开始追求比利，21岁嫁给了他。"}}]},"examples":[{"en":"Both candidates have spent the last month courting the media.","cn":"两位候选人在过去的一个月里都在取悦媒体。"},{"en":"Her lawyer made a statement outside the court.","cn":"她的律师在法庭外面发表了一份声明。"}]},"council":{"media":{"uk":"media/uk/council__gb_1.mp3","us":"media/us/council__us_1.mp3"},"oxford":{"phon":"ˈkaʊnsl","pos":"noun","senses":[{"en":"a group of people who are elected to govern an area such as a city or county","cn":"（市、郡等的）政务委员会，地方议会","ex":{"en":"a town council","cn":"镇议会"}},{"en":"the organization that provides services in a city or county, for example education, houses, libraries, etc.","cn":"市政（或地方管理）服务机构","lab":"British English","ex":{"en":"Residents have complained to the council about the noise.","cn":"居民向市政服务机构投诉噪声问题。"}},{"en":"a group of people chosen to give advice, make rules, do research, provide money, etc.","cn":"（顾问、立法、研究、基金等）委员会","ex":{"en":"the Medical Research Council","cn":"医学研究会"}},{"en":"(especially in the past) a formal meeting to discuss what action to take in a particular situation","cn":"（尤指旧时讨论采取什么行动的）协商会议","lab":"formal","ex":{"en":"The king held a council at Nottingham from 14 to 19 October 1330.","cn":"国王于 1330 年 10 月 14 日至 19 日在诺丁汉召集协商会议。"}}]},"collins":{"senses":[{"pos":"N-COUNT-COLL; N-IN-NAMES 可数集合名词；名称名词","cn":"市政委员会;地方议会","en":"A council is a group of people who are elected to govern a local area such as a city or, in Britain, a county.","ex":{"en":"...Cheshire County Council","cn":"柴郡政务委员会"}},{"pos":"ADJ 形容词","cn":"(房屋或公寓)地方政府出租的","en":"Council houses or flats are owned by the local council, and people pay rent to live in them.","ex":{"en":"There is a shortage of council housing","cn":"廉租公房房源不足。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"(用于组织名称)委员会","en":"Council is used in the names of some organizations.","ex":{"en":"...the National Council for Civil Liberties.","cn":"全国公民自由委员会"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"(组织的)管理者，委员","en":"In some organizations, the council is the group of people that controls or governs it.","ex":{"en":"The permanent council of the Organization of American States meets today here in Washington.","cn":"美洲国家组织的常务委员们今天在华盛顿这里会面。"}},{"pos":"N-COUNT 可数名词","cn":"(特定人群参加的正式)会议","en":"A council is a specially organized, formal meeting that is attended by a particular group of people.","ex":{"en":"President Najibullah said he would call a grand council of all Afghans","cn":"纳吉布拉总统称他将召开阿富汗全民大会。"}}]},"examples":[{"en":"The King held a council at Nottingham from 14 to 19 October 1330.","cn":"国王于 1330 年 10 月 14 日至 19 日在诺丁汉召集协商会议。"},{"en":"In Britain, the Arts Council gives grants to theatres.","cn":"英国的艺术委员会向剧院提供资金。"}]},"cousin":{"media":{"uk":"media/uk/cousin__gb_1.mp3","us":"media/us/cousin__us_1.mp3"},"oxford":{"phon":"ˈkʌzn","pos":"noun","senses":[{"en":"a child of your aunt or uncle","cn":"同辈表亲（或堂亲）；堂兄（或弟、姊、妹）；表兄（或弟、姊、妹）","ex":{"en":"She's my cousin.","cn":"她是我的表妹。"}},{"en":"a person who is in your wider family but who is not closely related to you","cn":"远房亲戚；远亲","ex":{"en":"She's some sort of cousin, I think.","cn":"我想她是一个远亲吧。"}},{"en":"a way of describing people from another country who are similar in some way to people in your own country","cn":"兄弟的…国人民（对与本民族有某些类似的另一国家人民的说法）","g":"[usually plural]","ex":{"en":"our American cousins","cn":"我们兄弟的美国人民"}},{"en":"a way of describing things that are similar or related in some way","cn":"同族；同类","g":"[usually plural]","ex":{"en":"Asian elephants are smaller than their African cousins.","cn":"亚洲象比它们的非洲同类小些。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同辈表亲(或堂亲);堂兄弟(或姐妹);表兄弟(或姐妹)","en":"Your cousin is the child of your uncle or aunt.","ex":{"en":"My cousin Mark helped me","cn":"表兄马克帮了我。"}},{"pos":"N-COUNT 可数名词","cn":"对等物;对等的人;相关的人(或事物)","en":"If you refer to two things or groups of people as cousins, you mean that they are equivalents or that there is a connection between them.","ex":{"en":"Whereas West Germans drink wine, their Eastern cousins prefer Schnapps","cn":"西德人喝葡萄酒，而他们东德的兄弟姐妹则喜欢喝杜松子酒。"}}]},"examples":[{"en":"Asian elephants are smaller than their African cousins.","cn":"亚洲象比它们的非洲同类小些。"},{"en":"He's a distant cousin of mine.","cn":"他是我远房的一个表亲。"}]},"conclusions":{"lemma":"conclusion","media":{"uk":"media/uk/xconclusion__gb_1.mp3","us":"media/us/xconclusion__us_1.mp3"}},"cocaine":{"oxford":{"phon":"kəʊˈkeɪn","pos":"noun","senses":[{"en":"a powerful drug that some people take illegally for pleasure and can become addicted to. Doctors sometimes use it as an anaesthetic.","cn":"可卡因；古柯碱"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"可卡因;古柯碱","en":"Cocaine is a powerful drug which some people take for pleasure, but which they can become addicted to."}]},"media":{"uk":"media/uk/cocaine__gb_1.mp3","us":"media/us/cocaine__us_1.mp3"}},"cooperatively":{"oxford":{"phon":"kəʊˈɒpərətɪvli","pos":"adverb","senses":[{"en":"together with others towards a shared aim","cn":"合作的；协作的；同心协力的","ex":{"en":"Participants in this workshop will work cooperatively on the tasks.","cn":"本次研讨会的参与者将合作完成任务。"}},{"en":"in a way that is helpful because you are doing what you are asked to do","cn":"协助的；配合的","ex":{"en":"The prisoner has responded cooperatively in the past.","cn":"囚犯过去曾合作应对。"}},{"en":"in a way that is owned and run by the people involved, with the profits shared by them","cn":"共同拥有共同经营利益共享的；合作的","lab":"business","ex":{"en":"a cooperatively owned business/bank/farm","cn":"合作经营的企业/银行/农场"}}]},"media":{"uk":"media/uk/cooperatively__gb_1.mp3","us":"media/us/cooperatively__us_1.mp3"},"examples":[{"en":"He was doing his best to be cooperative.","cn":""},{"en":"a co-operative venture between the City Council and the police","cn":""}]},"comedy":{"oxford":{"phon":"ˈkɒmədi","pos":"noun","senses":[{"en":"a play, film or TV show that is intended to be funny, usually with a happy ending; plays, films and TV shows of this type","cn":"喜剧；喜剧片","g":"[countable, uncountable]","ex":{"en":"a romantic comedy","cn":"浪漫喜剧"}},{"en":"professional entertainment with jokes, short acts, etc. that is intended to be funny","cn":"喜剧表演","g":"[uncountable]","ex":{"en":"The show combines theatre with the best of stand-up and sketch comedy.","cn":"该演出将单口喜剧和喜剧小品的精华融入戏剧。"}},{"en":"a humorous aspect of something","cn":"滑稽；幽默；诙谐","g":"[uncountable]","ex":{"en":"Her imaginative interpretation of the script brought out the comedy inherent in it.","cn":"她对剧本富有想象力的诠释，衬托出了其中固有的喜剧色彩。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"喜剧表演;喜剧成分;喜剧效果","en":"Comedy consists of types of entertainment, such as plays and films, or particular scenes in them, that are intended to make people laugh.","ex":{"en":"Actor Dom Deluise talks about his career in comedy.","cn":"演员多姆·德卢西谈论自己的喜剧生涯。"}},{"pos":"N-COUNT 可数名词","cn":"喜剧(片)","en":"A comedy is a play, film, or television programme that is intended to make people laugh."},{"pos":"N-UNCOUNT 不可数名词","cn":"滑稽;诙谐;喜剧性","en":"The comedy of a situation involves those aspects of it that make you laugh.","ex":{"en":"Jackie sees the comedy in her millionaire husband's thrifty habits.","cn":"杰姬觉得自己的百万富翁丈夫的一些节俭习惯很是滑稽。"}}]},"media":{"uk":"media/uk/comedy__gb_1.mp3","us":"media/us/comedy__us_1.mp3"},"examples":[{"en":"He didn't appreciate the comedy of the situation.","cn":"他未领略到这种局面的滑稽可笑之处。"},{"en":"a romantic comedy","cn":"浪漫喜剧"}]},"consideration":{"oxford":{"phon":"kənˌsɪdəˈreɪʃn","pos":"noun","senses":[{"en":"the act of thinking carefully about something","cn":"仔细考虑；深思；斟酌","g":"[uncountable, countable]","lab":"formal","ex":{"en":"An employer is legally bound to give due consideration to the request.","cn":"雇主在法律上有义务对这一要求给予适当考虑。"}},{"en":"something that must be thought about when you are planning or deciding something","cn":"（做计划或决定时）必须考虑的事（或因素、原因）","g":"[countable]","ex":{"en":"The government's decision was obviously motivated by political considerations.","cn":"政府的决定显然是出于政治考量。"}},{"en":"the quality of being sensitive towards others and thinking about their wishes and feelings","cn":"（对他人的）考虑周到，体谅，顾及","g":"[uncountable]","ex":{"en":"Their kindness and consideration will not be forgotten.","cn":"他们的善意和体贴不会被忘记。"}},{"en":"a reward or payment for a service","cn":"报酬；酬金；支付款","g":"[countable]","lab":"formal","ex":{"en":"You can buy the books for a small consideration.","cn":"你可以花一小笔钱买这些书。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"仔细考虑;斟酌","en":"Consideration is careful thought about something.","ex":{"en":"He said there should be careful consideration of the future role of the BBC.","cn":"他说应该认真思考英国广播公司将来要扮演的角色。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"讨论;考虑","en":"If something is under consideration, it is being discussed.","ex":{"en":"Several proposals are under consideration by the state assembly.","cn":"有几个提案州议会正在讨论中。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"体贴;体谅;为人着想","en":"If you show consideration, you pay attention to the needs, wishes, or feelings of other people.","ex":{"en":"Show consideration for other rail travellers","cn":"体谅其他铁路乘客。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指在计划或决定时)应考虑的因素","en":"A consideration is something that should be thought about, especially when you are planning or deciding something.","ex":{"en":"They should not allow partisan political considerations or interests to cloud their judgment","cn":"他们不应该让党派政治因素或者党派利益影响自己的判断。"}},{"pos":"PHRASE 短语","cn":"考虑到;顾及","en":"If you take something into consideration, you think about it because it is relevant to what you are doing.","ex":{"en":"The whole affair is bound to be taken into consideration when the Indian side is picked","cn":"如果选的是印度一方，整个事件必定会纳入考虑范围之中。"}}]},"media":{"uk":"media/uk/xconsideration__gb_1.mp3","us":"media/us/xconsideration__us_1.mp3"},"examples":[{"en":"Journalists stayed away from the funeral out of consideration for the bereaved family.","cn":"出于对丧失亲人家属着想，新闻记者没有到葬礼现场。"},{"en":"Taking everything into consideration, the event was a great success.","cn":"总的说来，这项活动取得了极大的成功。"}]},"conservation":{"media":{"uk":"media/uk/xconservation__gb_1.mp3","us":"media/us/xconservation__us_1.mp3"},"oxford":{"phon":"ˌkɒnsəˈveɪʃn","pos":"noun","senses":[{"en":"the protection of the natural environment","cn":"（对自然环境的）保护","ex":{"en":"to be interested in wildlife conservation","cn":"对野生动物保护感兴趣"}},{"en":"the official protection of buildings and objects that have historical or artistic importance","cn":"文物保护","ex":{"en":"the conservation of ancient monuments/manuscripts/our cultural heritage","cn":"对古迹／古代手抄本／我们的文化遗产的保护"}},{"en":"the act of preventing something from being lost, wasted, damaged or destroyed","cn":"防止流失（或浪费、损害、毁坏）；保持；保护","ex":{"en":"to encourage the conservation of water/fuel","cn":"鼓励节约用水／燃料"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(对环境的)保护","en":"Conservation is saving and protecting the environment.","ex":{"en":"...a four-nation regional meeting on elephant conservation.","cn":"四国保护大象的地区性会议"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(对文物或艺术品的) 保护","en":"Conservation is saving and protecting historical objects or works of art such as paintings, sculptures, or buildings.","ex":{"en":"Then he began his most famous work, the conservation and rebinding of the Book of Kells","cn":"之后他就开始了他最为出名的工作，即保护并重新装订《凯尔斯书》。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"节约;防止浪费","en":"The conservation of a supply of something is the careful use of it so that it lasts for a long time.","ex":{"en":"...projects aimed at promoting energy conservation.","cn":"旨在促进节约能源的计划"}}]},"examples":[{"en":"to be interested in wildlife conservation","cn":"对野生动物保护感兴趣"},{"en":"to encourage the conservation of water/fuel","cn":"鼓励节约用水/燃料"}]},"competence":{"media":{"uk":"media/uk/competence__gb_1.mp3","us":"media/us/competence__us_1.mp3"},"oxford":{"phon":"ˈkɒmpɪtəns","pos":"noun","senses":[{"en":"the ability to do something well","cn":"能力；胜任","g":"[uncountable, countable]","lab":"less frequent","ex":{"en":"to gain a high level of competence in English","cn":"获得高水平的英语能力"}},{"en":"the power that a court, an organization or a person has to deal with something","cn":"（法庭、机构或人的）权限，管辖权","g":"[uncountable]","lab":"law","ex":{"en":"The judge has to act within the competence of the court.","cn":"法官必须在法庭的权限范围内行使权力。"}},{"en":"a skill that you need in a particular job or for a particular task","cn":"技能；本领","g":"[countable]","lab":"less frequent","ex":{"en":"The syllabus lists the knowledge and competences required at this level.","cn":"教学大纲列出了这一级水平要求掌握的知识和技能。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"能力;才干","en":"Competence is the ability to do something well or effectively.","ex":{"en":"His competence as an economist had been reinforced by his successful fight against inflation","cn":"成功地扼制制通货膨胀的经历加强了他作为经济学家的才能。"}}]},"examples":[{"en":"The syllabus lists the knowledge and competences required at this level.","cn":"教学大纲列出了这一级水平要求掌握的知识技能。"},{"en":"The judge has to act within the competence of the court.","cn":"法官必须在法庭的权限范围内行使权力。"}]},"cocoa":{"oxford":{"phon":"ˈkəʊkəʊ","pos":"noun","senses":[{"en":"dark brown powder made from the seeds (called cocoa beans) of a tropical tree","cn":"可可粉","g":"[uncountable]"},{"en":"a hot drink made by mixing cocoa powder with milk and/or water and usually sugar","cn":"热可可（饮料）","g":"[uncountable]","ex":{"en":"a mug of cocoa","cn":"一大杯热可可饮料"}},{"en":"a cup of cocoa","cn":"一杯热可可饮料","g":"[countable]"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"可可粉","en":"Cocoa is a brown powder made from the seeds of a tropical tree. It is used in making chocolate.","ex":{"en":"The Ivory Coast became the world's leading cocoa producer.","cn":"象牙海岸成为世界上可可粉的主要产地。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"热可可(饮料)","en":"Cocoa is a hot drink made from cocoa powder and milk or water.","ex":{"en":"My wife was tucked up in bed with her cup of cocoa.","cn":"我老婆端着一杯热可可窝在床上。"}}]},"media":{"uk":"media/uk/cocoa__gb_1.mp3","us":"media/us/cocoa__us_1.mp3"},"examples":[{"en":"a mug of cocoa","cn":"一大杯热可可饮料"},{"en":"a cup of cocoa","cn":"一杯可可"}]},"combat":{"oxford":{"phon":"ˈkɒmbæt","pos":"noun","senses":[{"en":"fighting or a fight, especially during a time of war","cn":"搏斗；打仗；战斗","ex":{"en":"He was killed in combat.","cn":"他在战斗中阵亡。"}},{"en":"to stop something unpleasant or harmful from happening or from getting worse","cn":"防止；减轻","ex":{"en":"measures to combat crime/inflation/unemployment/disease","cn":"防止犯罪／通货膨胀／失业／疾病的措施"},"pos":"verb"},{"en":"to fight against an enemy","cn":"战斗；与…搏斗","lab":"formal","ex":{"en":"The security forces were unwilling to combat the insurgents.","cn":"安全部队不愿意打击叛乱分子。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"战斗","en":"Combat is fighting that takes place in a war.","ex":{"en":"Over 16 million men had died in combat","cn":"1,600多万人在战斗中牺牲。"}},{"pos":"N-COUNT 可数名词","cn":"斗争;格斗","en":"A combat is a battle, or a fight between two people.","ex":{"en":"It was the end of a long combat.","cn":"这是一场长期斗争的结束。"}},{"pos":"VERB 动词","cn":"与…作斗争;打击","en":"If people in authority combat something, they try to stop it happening.","ex":{"en":"Congress has criticised new government measures to combat crime.","cn":"国会对政府打击犯罪的新措施提出了批评。"}}]},"media":{"uk":"media/uk/combat__gb_1.mp3","us":"media/us/combat__us_1.mp3"},"examples":[{"en":"He was killed in combat.","cn":"他在战斗中阵亡。"},{"en":"measures to combat crime/inflation/unemployment/disease","cn":"防止犯罪/通货膨胀/失业/疾病的措施"}]},"cocktail":{"media":{"uk":"media/uk/cocktail__gb_1.mp3","us":"media/us/cocktail__us_1.mp3","img":["media/ldoce/img/cocktail.jpg"]},"oxford":{"phon":"ˈkɒkteɪl","pos":"noun","senses":[{"en":"a drink usually made from a mixture of one or more spirits (= strong alcoholic drinks) and fruit juice. It can also be made without alcohol.","cn":"鸡尾酒","g":"[countable]","ex":{"en":"a cocktail bar/cabinet/lounge/shaker","cn":"鸡尾酒酒吧／陈列柜／酒吧间／调酒器"}},{"en":"a dish of small pieces of food, usually served cold","cn":"凉菜；冷盘","g":"[countable, uncountable]","ex":{"en":"a prawn/shrimp cocktail","cn":"大虾／小虾冷盘"}},{"en":"a mixture of different substances or elements, often ones that do not mix together well","cn":"（通常不太相融的）混合物","g":"[countable]","ex":{"en":"a lethal cocktail of drugs","cn":"致命的混合药物"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鸡尾酒","en":"A cocktail is an alcoholic drink which contains several ingredients.","ex":{"en":"On arrival, guests are offered wine or a champagne cocktail","cn":"每位宾客一到场都会有人送上葡萄酒或香槟鸡尾酒。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指不宜搭配在一起的材料构成的)合成物，混合物","en":"A cocktail is a mixture of a number of different things, especially ones that do not go together well.","ex":{"en":"The court was told she had taken a cocktail of drugs and alcohol","cn":"有人在法庭上指称她把毒品和烈酒混在一起喝下去了。"}}]},"examples":[{"en":"a cocktail bar/cabinet/lounge","cn":"鸡尾酒酒吧/陈列柜/酒吧间"},{"en":"a prawn/shrimp cocktail","cn":"大虾/小虾冷盘"}]},"collective":{"media":{"uk":"media/uk/collective__gb_1.mp3","us":"media/us/collective__us_1.mp3"},"oxford":{"phon":"kəˈlektɪv","pos":"adjective","senses":[{"en":"done or shared by all members of a group of people; involving a whole group or society","cn":"集体的；共有的；共同的","ex":{"en":"collective leadership/decision-making/responsibility","cn":"集体领导／决策；共同责任"}},{"en":"used to refer to all members of a group","cn":"全体成员的；总体的","ex":{"en":"The collective name for mast, boom and sails on a boat is the ‘rig’.","cn":"船的桅杆、帆桁和帆总称为“索具”。"}},{"en":"a group of people who own a business or a farm and run it together; the business that they run","cn":"企业集团；合作农场；集体企业","ex":{"en":"an independent collective making films for television","cn":"为电视制作影片的独立集体企业"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"集体的;共同的","en":"Collective actions, situations, or feelings involve or are shared by every member of a group of people.","ex":{"en":"It was a collective decision","cn":"这是集体的决定。"}},{"pos":"ADJ 形容词","cn":"总的;集合的","en":"A collective amount of something is the total obtained by adding together the amounts that each person or thing in a group has.","ex":{"en":"Their collective volume wasn't very large.","cn":"他们的总量不是太大。"}},{"pos":"ADJ 形容词","cn":"集合的;总括的","en":"The collective term for two or more types of thing is a general word or expression which refers to all of them.","ex":{"en":"Social science is a collective name, covering a series of individual sciences.","cn":"社会科学是一个统称，涵盖一系列的独立学科。"}},{"pos":"N-COUNT 可数名词","cn":"集体企业;合作农场","en":"A collective is a business or farm which is run, and often owned, by a group of people who take an equal share of any profits.","ex":{"en":"He will see that he is participating in all the decisions of the collective.","cn":"他会确保自己参与集体企业的各项决策。"}}]},"examples":[{"en":"We have had a successful year, both collectively and individually.","cn":"我们这一年干得不错，无论是整体还是个人都取得了成功。"},{"en":"The collective name for mast, boom and sails on a boat is the ‘rig’.","cn":"船的桅杆、帆桁和帆总称为“索具”。"}]},"coca-cola":{"oxford":{"phon":"ˌkəʊkə ˈkəʊlə","pos":"noun","senses":[{"en":"a popular type of cola drink","cn":"可口可乐（饮料）","g":"[uncountable, countable]"},{"en":"a glass, bottle or can of Coca-Cola","cn":"一杯（或一瓶、一罐）可口可乐","g":"[countable]","ex":{"en":"I’ll have a Coke, please.","cn":"请给我一杯可乐。"}}]},"media":{"uk":"media/uk/coca_cola_1_gb_1.mp3","us":"media/us/coca_cola_1_us_1.mp3"}},"consciousness":{"media":{"uk":"media/uk/xconsciousness__gb_1.mp3","us":"media/us/xconsciousness__us_1.mp3"},"oxford":{"phon":"ˈkɒnʃəsnəs","pos":"noun","senses":[{"en":"the state of being able to use your senses and mental powers to understand what is happening","cn":"清醒状态；知觉","ex":{"en":"I can't remember any more—I must have lost consciousness.","cn":"我什么都想不起来了，我当时一定是失去了知觉。"}},{"en":"the state of being aware of something","cn":"觉察；感觉；意识","ex":{"en":"his consciousness of the challenge facing him","cn":"他对所面临的挑战的清醒意识"}},{"en":"the ideas and opinions of a person or group","cn":"观念；看法","ex":{"en":"her newly developed political consciousness","cn":"她最近形成的政治观念"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"意识;思想","en":"Your consciousness is your mind and your thoughts.","ex":{"en":"That idea has been creeping into our consciousness for some time.","cn":"不知不觉间，那种想法在我们脑海里渐渐形成已经有一段时间了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(群体的)观念，态度","en":"The consciousness of a group of people is their set of ideas, attitudes, and beliefs.","ex":{"en":"The Greens were the catalysts of a necessary change in the European consciousness.","cn":"绿党促使欧洲人的观念发生了必要的改变。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(对特定主题或观点的)关注，意识","en":"You use consciousness to refer to an interest in and knowledge of a particular subject or idea.","ex":{"en":"Her political consciousness sprang from her upbringing when her father's illness left the family short of money.","cn":"她的政治意识源于她的成长经历，那时因为父亲生病，家境窘迫。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"清醒状态;知觉;意识","en":"Consciousness is the state of being awake rather than being asleep or unconscious. If someone loses consciousness, they become unconscious, and if they regain consciousness, they become conscious after being unconscious.","ex":{"en":"She banged her head and lost consciousness","cn":"她撞到了头，失去了知觉。"}}]},"examples":[{"en":"I can't remember any more — I must have lost consciousness.","cn":"我什么都想不起来了 — 我当时一定是失去了知觉。"},{"en":"She did not regain consciousness and died the next day.","cn":"她再也没有苏醒过来，第二天便去世了。"}]},"consist":{"media":{"uk":"media/uk/xconsist__gb_1.mp3","us":"media/us/xconsist__us_1.mp3"},"oxford":{"phon":"kənˈsɪst","pos":"verb","senses":[{"en":"( formal ) to have sth as the main or only part or feature","cn":"存在于；在于"},{"en":"to be formed from the things or people mentioned","cn":"由 … 组成（或构成）"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"由…组成;由…构成","en":"Something that consists of particular things or people is formed from them.","ex":{"en":"Breakfast consisted of porridge served with butter.","cn":"早餐是麦片粥配佐餐黄油。"}},{"pos":"VERB 动词","cn":"在于;存在于","en":"Something that consists in something else has that thing as its main or only part.","ex":{"en":"His work as a consultant consisted in advising foreign companies on the siting of new factories.","cn":"作为一名顾问，他的工作是为外国公司在新厂选址问题上提供建议。"}}]},"examples":[{"en":"The beauty of the city consists in its magnificent buildings.","cn":"这座城市的美就在于它那些宏伟的建筑。"},{"en":"Around 15% of our diet is composed of protein.","cn":"我们的饮食中大约 15% 是蛋白质。"}]},"controlled":{"oxford":{"phon":"kənˈtrəʊld","pos":"adjective","senses":[{"en":"done or arranged in a very careful way","cn":"十分小心完成的；精心安排的","ex":{"en":"a controlled explosion","cn":"控制爆破"}},{"en":"limited, or managed by law or by rules","cn":"（受法律或规则）限制的，控制的，管制的","ex":{"en":"controlled airspace","cn":"管制空域"}},{"en":"managed by a particular group, or in a particular way","cn":"（受某团体或用某种方式）管理的，控制的，操纵的","ex":{"en":"a British-controlled company","cn":"英资公司"}},{"en":"remaining calm and not getting angry or upset","cn":"保持冷静的；克制的","ex":{"en":"She remained quiet and controlled.","cn":"她沉默不语保持克制。"}}]},"media":{"uk":"media/uk/xcontrolled__gb_1.mp3","us":"media/us/xcontrolled__us_1.mp3"},"examples":[{"en":"She remained quiet and controlled.","cn":"她沉默不语保持克制。"},{"en":"a controlled environment","cn":"受到控制的生态环境"}],"base":"control"},"conducting":{"lemma":"conduct","media":{"uk":"media/uk/xconduct__gb_1.mp3","us":"media/us/xconduct__us_1.mp3"}},"competition":{"media":{"uk":"media/uk/competition__gb_1.mp3","us":"media/us/competition__us_1.mp3"},"oxford":{"phon":"ˌkɒmpəˈtɪʃn","pos":"noun","senses":[{"en":"an event in which people compete with each other to find out who is the best at something","cn":"比赛；竞赛","g":"[countable]","ex":{"en":"a design/an art/a talent competition","cn":"设计／艺术／才艺比赛"}},{"en":"a situation in which people or organizations compete with each other for something that not everyone can have","cn":"竞争；角逐","g":"[uncountable]","ex":{"en":"stiff/fierce/intense/tough competition","cn":"激烈的竞争"}},{"en":"the people who are competing against somebody","cn":"竞争者；对手","g":"[singular + singular or plural verb]","ex":{"en":"We'll be able to assess the competition at the conference.","cn":"我们可以在会上对竞争对手进行估量。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"竞争;角逐","en":"Competition is a situation in which two or more people or groups are trying to get something which not everyone can have.","ex":{"en":"There's been some fierce competition for the title","cn":"夺冠之争一直都相当激烈。"}},{"pos":"N-SING 单数名词","cn":"竞争对手","en":"The competition is the person or people you are competing with.","ex":{"en":"I have to change my approach, the competition is too good now.","cn":"我得改变方法，现在的竞争对手太强。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(商业)竞争","en":"Competition is an activity involving two or more firms, in which each firm tries to get people to buy its own goods in preference to the other firms' goods.","ex":{"en":"The deal would have reduced competition in the commuter-aircraft market","cn":"这项协议原本会减少通勤航班市场的竞争。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"竞争产品(或商品)","en":"The competition is the goods that a rival organization is selling.","ex":{"en":"The American aerospace industry has been challenged by some stiff competition.","cn":"美国航空和航天工业已经受到某种强劲的竞争产品的挑战。"}},{"pos":"N-VAR 可变名词","cn":"比赛；竞赛","en":"A competition is an event in which many people take part in order to find out who is best at a particular activity.","ex":{"en":"...a surfing competition","cn":"冲浪比赛"}}]},"examples":[{"en":"There is now intense competition between schools to attract students.","cn":"现在学校之间为了招揽学生展开了激烈竞争。"},{"en":"We won the contract in the face of stiff competition.","cn":"面对激烈的竞争，我们赢得了这份合同。"}]},"comer":{"media":{"uk":"media/uk/comer__gb_1.mp3","us":"media/us/comer__us_1.mp3"},"oxford":{"phon":"ˈkʌmə(r)","pos":"noun","senses":[{"en":"anyone who wants to take part in an activity or a competition","cn":"所有申请者；所有想参加者","g":"[plural]","ex":{"en":"The event is open to all comers.","cn":"所有人均可参加这项比赛。"}},{"en":"a person who arrives somewhere","cn":"到达者","ex":{"en":"Early comers can enjoy the festival warm-up act.","cn":"早到者可以欣赏节日暖场演出。"}},{"en":"a person who is likely to be successful","cn":"可能成功者","lab":"North American English, informal，，"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"到达者;到来的人","en":"You can use comers to refer to people who arrive at a particular place.","ex":{"en":"I arrived at the church at two-thirty p.m. to find some early comers outside the main door","cn":"我下午两点半到达教堂，发现大门外面有一些人已经到了。"}}]},"examples":[{"en":"The event is open to all comers.","cn":"所有人均可参加这项比赛。"},{"en":"The contest is open to all comers.","cn":"该项竞赛所有人都可参加。"}]},"cotton":{"media":{"uk":"media/uk/cotton__gb_1.mp3","us":"media/us/cotton__us_1.mp3"},"oxford":{"phon":"ˈkɒtn","pos":"noun","senses":[{"en":"a plant grown in warm countries for the soft white hairs around its seeds that are used to make cloth and thread","cn":"棉，棉花（植株）","ex":{"en":"They grew cotton, tobacco, corn and fruit.","cn":"他们种植棉花、烟草、玉米和水果。"}},{"en":"the cloth made from the cotton plant","cn":"棉织物；棉布","ex":{"en":"The sheets are 100 per cent pure cotton.","cn":"这些被单是 100% 纯棉的。"}},{"en":"thread that is used for sewing","cn":"棉线；棉纱","lab":"especially British English","ex":{"en":"sewing cotton","cn":"缝纫用棉线"}},{"en":"a soft mass of white material that is used for cleaning the skin or a wound","cn":"药棉；脱脂棉","lab":"North American English","ex":{"en":"Use a cotton ball to apply the lotion.","cn":"用棉球涂护肤液。"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"棉布","en":"Cotton is a type of cloth made from soft fibres from a particular plant.","ex":{"en":"...a cotton shirt.","cn":"棉布衬衫"}},{"pos":"N-UNCOUNT 不可数名词","cn":"棉;棉花;棉株","en":"Cotton is a plant which is grown in warm countries and which produces soft fibres used in making cotton cloth.","ex":{"en":"...a large cotton plantation in Tennessee.","cn":"田纳西州大片的棉田"}},{"pos":"N-MASS 物质名词","cn":"棉线;棉纱","en":"Cotton is thread that is used for sewing, especially thread that is made from cotton.","ex":{"en":"There's a needle and cotton there.","cn":"那儿有针和线。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"脱脂棉;药棉","en":"Cotton or absorbent cotton is a soft mass of cotton, used especially for applying liquids or creams to your skin."},{"pos":"","cn":"","en":"相关词组：cotton on cotton to"}]},"examples":[{"en":"The sheets are 100% pure cotton.","cn":"这些被单是 100% 的纯棉。"},{"en":"I suddenly cottoned on to what he was doing.","cn":"我突然明白了他在做什么。"}]},"coexistence":{"oxford":{"phon":"ˌkəʊɪɡˈzɪstəns","pos":"noun","senses":[{"en":"the state of being together in the same place at the same time","cn":"共处；共存","ex":{"en":"to live in uneasy/peaceful coexistence within one nation","cn":"在一个国家内难以／和平共存"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同时存在;共存","en":"The coexistence of one thing with another is the fact that they exist together at the same time or in the same place.","ex":{"en":"He also believed in coexistence with the West.","cn":"他还相信他们能与西方国家共存。"}}]},"media":{"uk":"media/uk/coexistence__gb_1.mp3","us":"media/us/coexistence__us_1.mp3"},"examples":[{"en":"to live in uneasy/peaceful coexistence within one nation","cn":"在一个国家内难以/和平共存"},{"en":"the coexistence of two systems of measurement","cn":"两种计量制的共存"}]},"counsel":{"oxford":{"phon":"ˈkaʊnsl","pos":"noun","senses":[{"en":"advice, especially given by older people or experts; a piece of advice","cn":"（尤指年长者或专家的）劝告，忠告，建议","lab":"formal","ex":{"en":"Listen to the counsel of your elders.","cn":"要听从长辈的忠告。"}},{"en":"a lawyer or group of lawyers representing somebody in court","cn":"法律顾问；律师","lab":"law","ex":{"en":"to be represented by counsel","cn":"由律师代表"}},{"en":"to listen to and give support or professional advice to somebody who needs help","cn":"提供专业咨询","ex":{"en":"She counsels clients on mindfulness and coping with stress.","cn":"她为客户提供有关正念和应对压力的建议。"},"pos":"verb"},{"en":"to advise somebody to do something","cn":"建议，劝告（做某事）","lab":"formal","ex":{"en":"Most experts counsel caution in such cases.","cn":"大多数专家建议在这样的情况下要谨慎从事。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"劝告，忠告;建议","en":"Counsel is advice.","ex":{"en":"He had always been able to count on her wise counsel","cn":"他总能从她那里得到明智的建议。"}},{"pos":"VERB 动词","cn":"建议，劝告(做 …)","en":"If you counsel someone to take a course of action, or if you counsel a course of action, you advise that course of action.","ex":{"en":"My advisers counselled me to do nothing","cn":"顾问们建议我什么也不要做。"}},{"pos":"VERB 动词","cn":"给…提供建议","en":"If you counsel people, you give them advice about their problems.","ex":{"en":"...a psychologist who counsels people with eating disorders","cn":"为饮食失调症患者提供建议的心理学家"}},{"pos":"N-COUNT 可数名词","cn":"律师","en":"Someone's counsel is the lawyer who gives them advice on a legal case and speaks on their behalf in court.","ex":{"en":"Singleton's counsel said after the trial that he would appeal","cn":"审判结束后，辛格尔顿的律师表示他将会上诉。"}},{"pos":"PHRASE 短语","cn":"将自己的意见保密;不暴露自己的意图","en":"If you keep your own counsel, you keep quiet about your opinions or intentions.","ex":{"en":"Guscott rarely speaks out, preferring to keep his own counsel.","cn":"古斯科特很少发表意见，他更喜欢把自己的看法埋在心里。"}}]},"media":{"uk":"media/uk/counsel__gb_1.mp3","us":"media/us/counsel__us_1.mp3"},"examples":[{"en":"The court then heard counsel for the dead woman's father.","cn":"法庭接着听取了已死女人的父亲所请律师的陈述。"},{"en":"Most experts counsel caution in such cases.","cn":"大多数专家建议在这样的情况下要谨慎从事。"}]},"corridor":{"media":{"uk":"media/uk/corridor__gb_1.mp3","us":"media/us/corridor__us_1.mp3"},"oxford":{"phon":"ˈkɒrɪdɔː(r)","pos":"noun","senses":[{"en":"a long narrow passage in a building, with doors that open into rooms on either side","cn":"（建筑物内的）走廊，过道，通道","lab":"North American English also","ex":{"en":"His room is along the corridor.","cn":"他的房间就在走廊边。"}},{"en":"a long narrow piece of land belonging to one country that passes through the land of another country; a part of the sky over a country that planes, for example from another country, can fly through","cn":"走廊（一国领土通过他国境内的狭长地带）；空中走廊（一国领空中允许他国飞机经过的区域）","ex":{"en":"UN troops will secure the land corridor so that food supplies can reach the trapped civilians.","cn":"联合国部队将保护陆路信道以便食物可送到被围困平民的手中。"}},{"en":"a long narrow piece of land that follows the course of an important road or river","cn":"（沿着重要道路或河道的）狭长地带","ex":{"en":"the electronics industry in the M4 corridor","cn":"4 号高速公路沿线一带的电子工业区"}},{"en":"a passage along the side of some railway trains, from which doors lead into separate compartments","cn":"（某些火车上的）走道，过道，通道","lab":"British English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(建筑物或火车内的)走廊，过道，通道","en":"A corridor is a long passage in a building or train, with doors and rooms on one or both sides."},{"pos":"N-COUNT 可数名词","cn":"走廊(通往他国或经由他国通向大海的狭长地带)","en":"A corridor is a strip of land that connects one country to another or gives it a route to the sea through another country.","ex":{"en":"East Prussia and the rest of Germany were separated, in 1919, by the Polish corridor.","cn":"东普鲁士和德国的其他地区于1919年被波兰走廊分隔。"}}]},"examples":[{"en":"the electronics industry in the M4 corridor * 4","cn":"号高速公路沿线一带的电子工业区"},{"en":"His room is along the corridor.","cn":"他的房间就在走廊边。"}]},"complement":{"oxford":{"phon":"ˈkɒmplɪment","pos":"verb","senses":[{"en":"to add to something in a way that improves it or makes it more attractive","cn":"补充；补足；使相得益彰；使更具吸引力","ex":{"en":"The excellent menu is complemented by a good wine list.","cn":"佳肴佐以美酒，堪称完美。"}},{"en":"a thing that adds new qualities to something in a way that improves it or makes it more attractive","cn":"补充物；补足物","ex":{"en":"This vegetable's natural sweetness is a perfect complement to salty or rich foods.","cn":"这种蔬菜的天然甜味是咸食或油腻食物的完美搭配。"},"pos":"noun"},{"en":"the complete number or quantity needed or allowed","cn":"足数；足额","ex":{"en":"We've taken our full complement of trainees this year.","cn":"我们今年接收的实习生已满员。"},"pos":"noun"},{"en":"a word or phrase, especially an adjective or a noun, that is used after linking verbs such as be and become, and describes the subject of the verb. In some descriptions of grammar it is used to refer to any word or phrase that is governed by a verb and usually comes after the verb in a sentence.","cn":"补语；补足语","lab":"grammar","ex":{"en":"In the sentences ‘I'm angry’ and ‘He became a politician’, ‘angry’ and ‘politician’ are complements.","cn":"在句子 I’m angry 和 He became a politician 中，angry 和 politician 为补语。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使(优点)突出;衬托出","en":"If one thing complements another, it goes well with the other thing and makes its good qualities more noticeable.","ex":{"en":"Nutmeg, parsley and cider all complement the flavour of these beans well.","cn":"肉豆蔻、西芹和苹果酒都能很好地突出这些豆子的味道。"}},{"pos":"VERB 动词","cn":"补足;补充;与…相辅相成","en":"If people or things complement each other, they are different or do something different, which makes them a good combination.","ex":{"en":"There will be a written examination to complement the practical test","cn":"会有笔试作为实践考试的补充。"}},{"pos":"N-COUNT 可数名词","cn":"衬托物;补足物","en":"Something that is a complement to something else complements it.","ex":{"en":"The green wallpaper is the perfect complement to the old pine of the dresser","cn":"绿色的墙纸完美地衬托出衣橱那年代久远的松木。"}},{"pos":"N-COUNT 可数名词","cn":"装备定额;编制名额","en":"The complement of things or people that something has is the number of things or people that it normally has, which enable it to function properly.","ex":{"en":"Each ship had a complement of around a dozen officers and 250 men","cn":"每艘船的编制人数约为军官12位，船员250名。"}},{"pos":"N-COUNT 可数名词","cn":"补语","en":"In grammar, the complement of a link verb is an adjective group or noun group which comes after the verb and describes or identifies the subject. For example, in the sentence 'They felt very tired', 'very tired' is the complement. In 'They were students', 'students' is the complement."}]},"media":{"uk":"media/uk/complement__gb_1.mp3","us":"media/us/complement__us_1.mp3"},"examples":[{"en":"In the sentences ‘I'm angry’ and ‘He became a politician’, ‘angry’ and ‘politician’ are complements.","cn":"在句子 I'm angry 和 He became a politician 中，angry 和 politician 为补语。"},{"en":"The team needs players who complement each other.","cn":"球队需要能够相互取长补短的队员。"}]},"confusion":{"media":{"uk":"media/uk/xconfusion__gb_1.mp3","us":"media/us/xconfusion__us_1.mp3"},"oxford":{"phon":"kənˈfjuːʒn","pos":"noun","senses":[{"en":"a state of not being certain about what is happening, what you should do, what something means, etc.","cn":"不确定；困惑","g":"[uncountable, countable]","ex":{"en":"The announcement caused a lot of confusion.","cn":"这一声明造成了严重混乱。"}},{"en":"the fact of making a mistake about who somebody is or what something is","cn":"混淆；混同","g":"[uncountable, countable]","ex":{"en":"To avoid confusion, please write the children's names clearly on all their school clothes.","cn":"为避免搞错，请在孩子所有的校服上写清楚他们各自的姓名。"}},{"en":"a situation in which you feel embarrassed because you do not understand something and are not sure what to do","cn":"困窘；尴尬；局促不安","g":"[uncountable]","ex":{"en":"He looked at me in confusion and did not answer the question.","cn":"他困窘地看着我，没有回答问题。"}},{"en":"a confused situation in which people do not know what action to take","cn":"（让人不知所措的）混乱局面，乱成一团","g":"[uncountable]","ex":{"en":"Fighting had broken out and all was chaos and confusion.","cn":"战斗爆发了，一切都陷入了混乱不堪的状态。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(尤指因想法不同造成的)困惑，不明确","en":"If there is confusion about something, it is not clear what the true situation is, especially because people believe different things.","ex":{"en":"There's still confusion about the number of casualties","cn":"伤亡人数依然不明。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指因很多事情同时发生造成的)混乱局面，骚乱","en":"Confusion is a situation in which everything is in disorder, especially because there are lots of things happening at the same time.","ex":{"en":"There was confusion when a man fired shots","cn":"一个男子开了几枪，场面一片混乱。"}},{"pos":"N-VAR 可变名词","cn":"困惑;不知所措","en":"If your mind is in a state of confusion, you do not know what to believe or what you should do.","ex":{"en":"We always left his office in a state of confusion.","cn":"我们总是一头雾水地离开他的办公室。"}}]},"examples":[{"en":"To avoid confusion, please write the children's names clearly on all their school clothes.","cn":"为避免搞错，请在孩子所有的校服上写清楚他们各自的姓名。"},{"en":"There is some confusion about what the correct procedure should be.","cn":"对于什么是正确的处理程序还是有些不清楚。"}]},"composed":{"media":{"uk":"media/uk/composed__gb_1.mp3","us":"media/us/composed__us_1.mp3"},"oxford":{"phon":"kəmˈpəʊzd","pos":"adjective","senses":[{"en":"to be made or formed from several parts, things or people","cn":"由…组成（或构成）的","lab":"formal","ex":{"en":"The committee is composed mainly of lawyers.","cn":"委员会主要由律师组成。"}},{"en":"calm and in control of your feelings","cn":"镇静；镇定；平静","g":"[not usually before noun]","ex":{"en":"She seemed outwardly composed.","cn":"她表面上好像很镇静。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"平静的;镇定的;沉着的","en":"If someone is composed, they are calm and able to control their feelings.","ex":{"en":"Laura was very calm and composed","cn":"劳拉十分冷静沉着。"}}]},"examples":[{"en":"The committee is composed mainly of lawyers.","cn":"委员会主要由律师组成。"},{"en":"She seemed outwardly composed.","cn":"她表面上好像很镇静。"}],"base":"compose"},"compound":{"oxford":{"phon":"ˈkɒmpaʊnd","pos":"noun","senses":[{"en":"a thing consisting of two or more separate things combined together","cn":"复合物；混合物","ex":{"en":"compounds derived from rainforest plants","cn":"来自雨林植物的化合物"}},{"en":"a substance formed by a chemical reaction of two or more elements in fixed amounts relative to each other","cn":"化合物","lab":"chemistry","ex":{"en":"Common salt is a compound of sodium and chlorine.","cn":"普通食盐是钠和氯的化合物。"}},{"en":"a noun, an adjective or a verb made of two or more words or parts of words, written as one or more words, or joined by a hyphen. Travel agent, dark-haired and bathroom are all compounds.","cn":"复合词","lab":"grammar","ex":{"en":"Most compound nouns form their plurals in the usual way.","cn":"大多数复合名词以通常的方式形成复数形式。"}},{"en":"an area surrounded by a fence or wall in which a factory or other group of buildings stands","cn":"有围栏（或围墙）的场地（内有工厂或其他建筑群）","ex":{"en":"life inside the prison compound","cn":"监狱大院里的生活"}},{"en":"formed of two or more parts","cn":"复合的","ex":{"en":"a compound adjective, such as fair-skinned","cn":"复合形容词，如 fair-skinned"},"pos":"adjective"},{"en":"to make something bad become even worse by causing further damage or problems","cn":"使加重；使恶化","ex":{"en":"The problems were compounded by severe food shortages.","cn":"严重的食物短缺使问题进一步恶化。"},"pos":"verb"},{"en":"to be formed from something","cn":"由…构成（或形成）","lab":"formal","ex":{"en":"The DNA molecule is compounded from many smaller molecules.","cn":"脱氧核糖核酸分子是由许多更小的分子组成的。"},"pos":"verb"},{"en":"to mix something together","cn":"混合；掺和；拌和","g":"[often passive]","lab":"formal or specialist","ex":{"en":"liquid soaps compounded with disinfectant","cn":"用消毒剂混合制成的皂液"},"pos":"verb"},{"en":"to pay or charge interest on an amount of money that includes any interest already earned or charged","cn":"支付，收取（复利）","lab":"finance","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(作特殊用途的)大院，有围墙的场地","en":"A compound is an enclosed area of land that is used for a particular purpose.","ex":{"en":"Police fired on them as they fled into the embassy compound.","cn":"当他们逃进使馆大院时，警察向他们开了枪。"}},{"pos":"N-COUNT 可数名词","cn":"(化学中的)化合物","en":"In chemistry, a compound is a substance that consists of two or more elements.","ex":{"en":"Organic compounds contain carbon in their molecules.","cn":"有机化合物的分子中含碳。"}},{"pos":"N-COUNT 可数名词","cn":"混合物;组合物","en":"If something is a compound of different things, it consists of those things.","ex":{"en":"Honey is basically a compound of water, two types of sugar, vitamins and enzymes.","cn":"蜂蜜基本上是水、两种糖、几种维生素和酶的混合物。"}},{"pos":"ADJ 形容词","cn":"复合的;组合的;混合的","en":"Compound is used to indicate that something consists of two or more parts or things.","ex":{"en":"...a tall shrub with shiny compound leaves.","cn":"长有油光闪亮的复叶的高株灌木"}},{"pos":"ADJ 形容词","cn":"(单词)复合的","en":"In grammar, a compound noun, adjective, or verb is one that is made up of two or more words, for example 'fire engine', 'bottle-green', and 'force-feed'."},{"pos":"ADJ 形容词","cn":"(句子)复合的","en":"In grammar, a compound sentence is one that is made up of two or more main clauses."},{"pos":"VERB 动词","cn":"使恶化；使复杂化;加重","en":"To compound a problem, difficulty, or mistake means to make it worse by adding to it.","ex":{"en":"Additional bloodshed and loss of life will only compound the tragedy","cn":"额外的流血和牺牲只会加重这场悲剧。"}}]},"media":{"uk":"media/uk/compound__gb_1.mp3","us":"media/us/compound__us_1.mp3"},"examples":[{"en":"The DNA molecule is compounded from many smaller molecules.","cn":"脱氧核糖核酸分子是由许多更小的分子组成的。"},{"en":"a compound adjective, such as fair-skinned","cn":"复合形容词，如 fair-skinned"}]},"consume":{"media":{"uk":"media/uk/xconsume__gb_1.mp3","us":"media/us/xconsume__us_1.mp3"},"oxford":{"phon":"kənˈsjuːm","pos":"verb","senses":[{"en":"to use something, especially fuel, energy or time","cn":"消耗，耗费（尤指燃料、能量或时间）","ex":{"en":"The electricity industry consumes large amounts of fossil fuels.","cn":"电力工业消耗大量的化石燃料。"}},{"en":"to eat or drink something","cn":"吃；喝；饮","lab":"formal","ex":{"en":"Before he died, he had consumed a large quantity of alcohol.","cn":"他死亡前喝了大量的酒。"}},{"en":"to fill somebody with a strong feeling","cn":"使强烈地感到","g":"[often passive]","lab":"formal","ex":{"en":"Carolyn was consumed with guilt.","cn":"卡罗琳深感内疚。"}},{"en":"to completely destroy something","cn":"烧毁；毁灭","lab":"formal","ex":{"en":"The hotel was quickly consumed by fire.","cn":"那座旅馆很快被大火吞噬。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"吃;喝;饮用","en":"If you consume something, you eat or drink it.","ex":{"en":"Many people experienced a drop in their cholesterol levels when they consumed oat bran.","cn":"很多人食用燕麦麸后胆固醇水平下降了。"}},{"pos":"VERB 动词","cn":"消耗，耗费(燃料、能源或时间)","en":"To consume an amount of fuel, energy, or time means to use it up.","ex":{"en":"Some of the most efficient refrigerators consume 70 percent less electricity than traditional models.","cn":"一些极为节能的冰箱比传统型号耗电减少70%。"}},{"pos":"VERB 动词","cn":"(火)烧毁，吞没，吞噬","en":"If a fire consumes a building, it completely destroys it.","ex":{"en":"...the fire which consumed the dwelling.","cn":"吞噬了居所的火灾"}},{"pos":"VERB 动词","cn":"(使)沉溺，(使)沉迷，(使)充满(感情或思想)","en":"If a feeling or idea consumes you, it affects you very strongly indeed.","ex":{"en":"The memories consumed him.","cn":"他沉浸在回忆中。"}}]},"examples":[{"en":"The electricity industry consumes large amounts of fossil fuels.","cn":"电力工业消耗大量的矿物燃料。"},{"en":"The hotel was quickly consumed by fire.","cn":"那座旅馆很快被大火吞噬。"}]},"complain":{"media":{"uk":"media/uk/complain__gb_1.mp3","us":"media/us/complain__us_1.mp3"},"oxford":{"phon":"kəmˈpleɪn","pos":"verb","senses":[{"en":"to say that you are annoyed, unhappy or not satisfied about somebody/something","cn":"抱怨；埋怨；投诉；发牢骚","lab":"informal","ex":{"en":"She never complains, but she's obviously exhausted.","cn":"她虽然从不抱怨，但显然已疲惫不堪。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"抱怨;发牢骚","en":"If you complain about a situation, you say that you are not satisfied with it.","ex":{"en":"Miners have complained bitterly that the government did not fulfill their promises","cn":"矿工们愤愤不平地抱怨说政府没有履行诺言。"}},{"pos":"VERB 动词","cn":"诉说有…病痛;主诉","en":"If you complain of pain or illness, you say that you are feeling pain or feeling ill.","ex":{"en":"He complained of a headache.","cn":"他说头痛。"}}]},"examples":[{"en":"If nobody objects, we'll postpone the meeting till next week.","cn":"如果没有人反对，我们就把会议推迟到下周。"},{"en":"He objected that the police had arrested him without sufficient evidence.","cn":"他抗辩说警察没有充分证据就逮捕了他。"}]},"coupling":{"media":{"uk":"media/uk/coupling__gb_1.mp3","us":"media/us/coupling__us_1.mp3"},"oxford":{"phon":"ˈkʌplɪŋ","pos":"noun","senses":[{"en":"an action of joining or combining two things","cn":"连接；结合；联结","g":"[usually singular]","ex":{"en":"a coupling of Mozart’s Prague Symphony and Schubert’s Unfinished Symphony (= for example, on the same CD)","cn":"编排在一起的莫扎特的《布拉格交响曲》与舒伯特的《未完成交响曲》（如在同一张光盘上）"}},{"en":"an act of having sex","cn":"性交","lab":"formal","ex":{"en":"illicit couplings","cn":"不正当的性交"}},{"en":"a thing that joins together two parts of something, two vehicles or two pieces of equipment","cn":"联轴器；（连接车辆的）车钩","lab":"specialist","ex":{"en":"The coupling was designed to fit the grooves in the pipe.","cn":"接头设计用于安装管道中的凹槽。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"耦接头;联轴器;(连接车辆的)车钩","en":"A coupling is a device which is used to join two vehicles or pieces of equipment together.","ex":{"en":"Before driving away, re-check the trailer coupling.","cn":"开走之前，再检查一下拖车的挂钩。"}},{"pos":"N-COUNT 可数名词","cn":"(两种不同的事物、想法或活动的)连接，结合;合作","en":"When two different things, ideas, or activities are combined, or when two people work together, you can refer to this combination as a coupling .","ex":{"en":"Anton the chef concocts a sensual coupling of lobster and asparagus","cn":"厨师安东用龙虾和芦笋搭配，制作出了一道口感很好的菜肴。"}},{"pos":"N-COUNT 可数名词","cn":"性交","en":"An act of sexual intercourse is sometimes referred to as a coupling .","ex":{"en":"...sexual couplings.","cn":"性交"}}]},"examples":[{"en":"a coupling of Mozart's Prague Symphony and Schubert's Unfinished Symphony (= for example, on the same CD)","cn":"编排在一起的莫扎特的《布拉格交响曲》与舒伯特的《未完成交响曲》（如在同一张光盘上）"},{"en":"illicit couplings","cn":"不正当的性交"}],"base":"couple"},"combines":{"lemma":"combine","media":{"uk":"media/uk/combine__gb_1.mp3","us":"media/us/combine__us_1.mp3"}},"coercion":{"media":{"uk":"media/uk/coercion__gb_1.mp3","us":"media/us/coercion__us_1.mp3"},"oxford":{"phon":"kəʊˈɜːʃn","pos":"noun","senses":[{"en":"the action of making somebody do something that they do not want to do, using force or threatening to use force","cn":"强迫；胁迫","ex":{"en":"He claimed he had only acted under coercion.","cn":"他声称他只是受了胁迫才采取行动。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"强迫;胁迫;逼迫","en":"Coercion is the act or process of persuading someone forcefully to do something that they do not want to do.","ex":{"en":"It was vital that the elections should be free of coercion or intimidation.","cn":"选举中不应有强迫或恐吓行为，这一点至关重要。"}}]},"examples":[{"en":"He claimed he had only acted under coercion.","cn":"他声称他只是被迫采取行动。"},{"en":"The defendant explained that he had been acting under coercion.","cn":"被告辩解说他是受到胁迫才那么做的。"}]},"cohesive":{"oxford":{"phon":"kəʊˈhiːsɪv","pos":"adjective","senses":[{"en":"forming a united whole","cn":"结成一个整体的","ex":{"en":"a cohesive group","cn":"一个紧密团结的群体"}},{"en":"causing people or things to become united","cn":"使结合的；使凝结的；使内聚的","ex":{"en":"the cohesive power of shared suffering","cn":"共患难的内聚力"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"统一的;团结的","en":"Something that is cohesive consists of parts that fit together well and form a united whole.","ex":{"en":"'Daring Adventures' from '86 is a far more cohesive and successful album","cn":"1986年发行的《勇于冒险》是一张风格更为统一也更为成功的专辑。"}}]},"media":{"uk":"media/uk/cohesive__gb_1.mp3","us":"media/us/cohesive__us_1.mp3"},"examples":[{"en":"well-structured sentences illustrating the use of cohesive markers such as ‘nevertheless’ and ‘however’","cn":"能够表明像 nevertheless 和 however 这类连词用法的结构严谨的句子"},{"en":"the cohesive power of shared suffering","cn":"共患难的内聚力"}]},"contact":{"media":{"uk":"media/uk/xcontact__gb_1.mp3","us":"media/us/xcontact__us_1.mp3"},"oxford":{"phon":"ˈkɒntækt","pos":"noun","senses":[{"en":"the act of communicating with somebody, especially regularly","cn":"（尤指经常的）联系，联络","g":"[uncountable]","sc":"act of communicating","ex":{"en":"I don't have much contact with my uncle.","cn":"我和叔父甚少联系。"}},{"en":"the state of meeting somebody or having to deal with something","cn":"遇见（某人）；碰上（要处理的事）","g":"[uncountable]","sc":"meeting somebody/something","ex":{"en":"She always avoided contact with the press.","cn":"她总是避免与媒体接触。"}},{"en":"an occasion on which you meet or communicate with somebody; a relationship with somebody","cn":"会见；交往；人际关系","g":"[countable, usually plural]","sc":"relationship","ex":{"en":"Even the US, which has no embassy there, is beginning to forge contacts.","cn":"就连在那里没有大使馆的美国也开始建立联系。"}},{"en":"a person that you know, especially somebody who can be helpful to you in your work","cn":"熟人；（尤指工作中有用的）社会关系","g":"[countable]","sc":"person","ex":{"en":"social/personal contacts","cn":"社会上的／私下的熟人"}},{"en":"the state of touching something","cn":"触摸；接触","g":"[uncountable]","sc":"touching somebody/something","ex":{"en":"a fear of physical contact","cn":"对身体接触的恐惧感"}},{"en":"an electrical connection","cn":"（电流的）接触，接通；接触器","g":"[countable]","sc":"electrical","ex":{"en":"The switches close the contacts and complete the circuit.","cn":"这些开关可接通形成闭合电路。"}},{"en":"a contact lens (= a small round piece of thin plastic that you put on your eye to help you see better)","cn":"隐形眼镜","g":"[usually plural]","lab":"informal","sc":"for eyes"},{"en":"a person who has recently been near to somebody with a contagious disease and so might have caught the infection from them","cn":"（传染病人的）接触者","g":"[countable]","sc":"medical"},{"en":"to communicate with somebody, for example by phone, letter or email","cn":"联系，联络（如用电话、信件或电邮）","lab":"British English","ex":{"en":"I've been trying to contact you all day.","cn":"我一整天都在设法与你联系。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指经常性的)联系，联络","en":"Contact involves meeting or communicating with someone, especially regularly.","ex":{"en":"Opposition leaders are denying any contact with the government in Kabul","cn":"反对派领袖否认与喀布尔政府有任何联系。"}},{"pos":"PHRASE 短语","cn":"保持联系;有联系","en":"If you are in contact with someone, you regularly meet them or communicate with them.","ex":{"en":"He was in direct contact with the kidnappers","cn":"他与绑架者有直接联系。"}},{"pos":"VERB 动词","cn":"联系;联络","en":"If you contact someone, you telephone them, write to them, or go to see them in order to tell or ask them something.","ex":{"en":"Contact the Tourist Information Bureau for further details","cn":"详情请洽旅游信息处。"}},{"pos":"ADJ 形容词","cn":"(信息、电话号码等)供联系的，供联络的","en":"Your contact details or number are information such as a telephone number where you can be contacted.","ex":{"en":"You must leave your full name and contact details when you phone.","cn":"打电话时须留下全名与联络信息。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"接触;遇见","en":"If you come into contact with someone or something, you meet that person or thing in the course of your work or other activities.","ex":{"en":"Doctors I came into contact with voiced their concern","cn":"我接触到的医生都表示了他们的担心。"}},{"pos":"PHR-RECIP 相互短语","cn":"与…联络;和…取得联系","en":"If you make contact with someone, you find out where they are and talk or write to them.","ex":{"en":"Then, after she had become famous, he tried to make contact with her.","cn":"后来，她出名之后，他曾试图与她联系。"}},{"pos":"PHR-RECIP 相互短语","cn":"与…失去联系;与…断了联系","en":"If you lose contact with someone who you have been friendly with, you no longer see them, speak to them, or write to them.","ex":{"en":"Though they all live nearby, I lost contact with them really quickly","cn":"虽然他们都住在附近，但我很快与他们失去了联系。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"触碰;接触","en":"When people or things are in contact, they are touching each other.","ex":{"en":"They compared how these organisms behaved when left in contact with different materials","cn":"他们比较了与不同材料接触时这些生物体的反应。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(无线电)联络，通信","en":"Radio contact is communication by means of radio.","ex":{"en":"He failed to make radio contact.","cn":"他未能进行无线电联络。"}},{"pos":"N-COUNT 可数名词","cn":"熟人;有用的社会关系","en":"A contact is someone you know in an organization or profession who helps you or gives you information.","ex":{"en":"Their contact in the United States Embassy was called Phil.","cn":"他们在美国大使馆的熟人叫菲尔。"}},{"pos":"","cn":"","en":"to make eye contact→see: ;"}]},"examples":[{"en":"The organization put me in contact with other people in a similar position (= gave me their addresses or telephone numbers).","cn":"这家机构为我提供了其他和我职务相若的人的联系方法。"},{"en":"The company has maintained trade contacts with India.","cn":"这家公司和印度一直保持着贸易往来。"}]},"conveyor":{"oxford":{"phon":"kənˈveɪə(r)","pos":"noun","senses":[{"en":"a continuous moving band used for transporting goods from one part of a building to another, for example products in a factory or bags, cases, etc. in an airport","cn":"传送带，输送带（如输送工厂的产品或机场的行李）","ex":{"en":"The products are labelled as they pass by on the conveyor.","cn":"产品在传送带上经过时会被贴上标签。"}},{"en":"a person or thing that carries something or makes something known","cn":"运送者；传送者；传播者；传达者","lab":"formal","ex":{"en":"Words are conveyors of meaning.","cn":"文字是意义的传递工具。"}}]},"media":{"uk":"media/uk/xconveyor__gb_1.mp3","us":"media/us/xconveyor__us_1.mp3"},"examples":[{"en":"the conveyer of good news","cn":"带来好消息的人"}]},"convent":{"oxford":{"phon":"ˈkɒnvənt","pos":"noun","senses":[{"en":"a building in which a Christian community of nuns (= members of a female religious community) live together","cn":"女隐修院；女修道院","lab":"North American English","ex":{"en":"She entered a convent at the age of sixteen.","cn":"她 16 岁当了修女。"}},{"en":"a school run by nuns","cn":"女修会开办的学校"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"女修道院","en":"A convent is a building in which a community of nuns live."},{"pos":"N-COUNT 可数名词","cn":"同 convent school","en":"A convent is the same as a convent school ."}]},"media":{"uk":"media/uk/xconvent__gb_1.mp3","us":"media/us/xconvent__us_1.mp3"}},"cooler":{"media":{"uk":"media/uk/cooler__gb_1.mp3","us":"media/us/cooler__us_1.mp3","img":["media/ldoce/img/cooler.jpg"]},"oxford":{"phon":"ˈkuːlə(r)","pos":"noun","senses":[{"en":"a machine that cools things, especially drinks","cn":"冷却器","ex":{"en":"the office water cooler","cn":"办公室的饮水冷却器"}},{"en":"a container that keeps things cold, especially drinks","cn":"（尤用于冷藏饮料的）冷藏箱，保温箱","lab":"especially North American English","ex":{"en":"They took a cooler full of drinks to the beach.","cn":"他们把冷藏箱装满饮料带到了海滩。"}},{"en":"a drink with ice and usually wine in it","cn":"（通常有冰和酒的）清凉饮料","lab":"North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"冷藏箱;(尤指)冰箱;冷却器","en":"A cooler is a container for keeping things cool, especially drinks."}]},"examples":[{"en":"( especially NAmE ) They took a cooler full of drinks to the beach.","cn":"他们把冷藏器装满饮料带到了海滩。"},{"en":"They took a cooler full of drinks to the beach.","cn":""}]},"confuse":{"oxford":{"phon":"kənˈfjuːz","pos":"verb","senses":[{"en":"to make somebody unable to think clearly or understand something","cn":"使糊涂；使迷惑","ex":{"en":"These two sets of statistics are guaranteed to confuse the public.","cn":"这两组统计数据肯定会让公众感到困惑。"}},{"en":"to think wrongly that somebody/something is somebody/something else","cn":"误以为…是；混淆","ex":{"en":"People often confuse me and my twin sister.","cn":"人们常常把我和我的孪生妹妹搞错。"}},{"en":"to make a subject more difficult to understand","cn":"使更难于理解","ex":{"en":"His comments only served to confuse the issue further.","cn":"他的评论只是把问题弄得更加复杂。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"混淆;搞错","en":"If you confuse two things, you get them mixed up, so that you think one of them is the other one.","ex":{"en":"Great care is taken to avoid confusing the two types of projects","cn":"大家非常谨慎，以免把这两类项目弄混。"}},{"pos":"VERB 动词","cn":"把…弄糊涂;使困惑","en":"To confuse someone means to make it difficult for them to know exactly what is happening or what to do.","ex":{"en":"German politics surprised and confused him.","cn":"德国政治既令他惊讶，又让他困惑不解。"}},{"pos":"VERB 动词","cn":"搅乱;使复杂化","en":"To confuse a situation means to make it complicated or difficult to understand.","ex":{"en":"To further confuse the issue, there is an enormous variation in the amount of sleep people feel happy with.","cn":"使问题进一步复杂化的是，每个人需要的睡眠时间千差万别。"}}]},"media":{"uk":"media/uk/xconfuse__gb_1.mp3","us":"media/us/xconfuse__us_1.mp3"},"examples":[{"en":"They confused me with conflicting accounts of what happened.","cn":"他们对发生的事所作的陈述自相矛盾，使我迷惑不解。"},{"en":"People often confuse me and my twin sister.","cn":"人们常常把我和我的孪生妹妹搞错。"}]},"complexity":{"media":{"uk":"media/uk/complexity__gb_1.mp3","us":"media/us/complexity__us_1.mp3"},"oxford":{"phon":"kəmˈpleksəti","pos":"noun","senses":[{"en":"the state of being formed of many parts; the state of being difficult to understand","cn":"复杂性；难懂","g":"[uncountable]","ex":{"en":"the increasing complexity of modern telecommunication systems","cn":"日益复杂的现代电信系统"}},{"en":"the features of a problem or situation that are difficult to understand","cn":"难题；难以理解的局势","g":"[plural]","ex":{"en":"the complexities of the system","cn":"这一系统的复杂之处"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"复杂性;错综复杂","en":"Complexity is the state of having many different parts connected or related to each other in a complicated way.","ex":{"en":"...a diplomatic tangle of great complexity.","cn":"非常复杂的外事纠纷"}}]},"examples":[{"en":"I was astonished by the size and complexity of the problem.","cn":"这个问题的复杂性和涉及面之广使我感到惊讶。"},{"en":"the increasing complexity of modern telecommunication systems","cn":"日益复杂的现代电信系统"}]},"confusing":{"media":{"uk":"media/uk/xconfusing__gb_1.mp3","us":"media/us/xconfusing__us_1.mp3"},"oxford":{"phon":"kənˈfjuːzɪŋ","pos":"adjective","senses":[{"en":"difficult to understand; not clear","cn":"难懂的；模糊的；隐晦的；不清楚的","ex":{"en":"The instructions on the box are very confusing.","cn":"盒子上的使用说明令人费解。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人困惑的;费解的；混乱的","en":"Something that is confusing makes it difficult for people to know exactly what is happening or what to do.","ex":{"en":"The statement is highly confusing","cn":"这一声明十分费解。"}}]},"examples":[{"en":"The instructions on the box are very confusing.","cn":"盒子上的使用说明令人费解。"},{"en":"a very confusing experience","cn":"让人莫名其妙的经历"}],"base":"confuse"},"commitment":{"media":{"uk":"media/uk/commitment__gb_1.mp3","us":"media/us/commitment__us_1.mp3"},"oxford":{"phon":"kəˈmɪtmənt","pos":"noun","senses":[{"en":"a promise to do something or to behave in a particular way; a promise to support somebody/something; the fact of committing yourself","cn":"承诺；许诺；允诺承担；保证","g":"[countable, uncountable]","ex":{"en":"I'm not ready to make a long-term commitment.","cn":"我还没准备好做出长期的承诺。"}},{"en":"the desire to work hard and give your energy and time to a job or an activity","cn":"（对工作或活动的）献身，奉献，投入","g":"[uncountable]","ex":{"en":"He has demonstrated exceptional commitment and dedication.","cn":"他表现出非凡的投入和奉献精神。"}},{"en":"a thing that you have promised or agreed to do, or that you have to do","cn":"已承诺（或同意）的事；不得不做的事","g":"[countable, usually plural]","ex":{"en":"He's busy for the next month with filming commitments.","cn":"他正忙于准备已经承诺下个月接拍的电影。"}},{"en":"a promise to pay for something, especially regularly; a promise to use resources in order to achieve something","cn":"投入；付出","g":"[countable, uncountable]","ex":{"en":"Taking on a mortgage is a huge financial commitment.","cn":"承担抵押贷款是一项巨大的经济支出。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"信奉;忠诚","en":"Commitment is a strong belief in an idea or system.","ex":{"en":"...commitment to the ideals of Bolshevism.","cn":"对布尔什维克主义理想的信奉"}},{"pos":"N-COUNT 可数名词","cn":"承诺;责任;义务","en":"A commitment is something which regularly takes up some of your time because of an agreement you have made or because of responsibilities that you have.","ex":{"en":"I've got a lot of commitments","cn":"我承担了很多责任。"}},{"pos":"N-COUNT 可数名词","cn":"承诺;许诺","en":"If you make a commitment to do something, you promise that you will do it.","ex":{"en":"We made a commitment to keep working together","cn":"我们承诺继续合作。"}},{"pos":"N-VAR 可变名词","cn":"收监;送入医院","en":"Commitment is the process of officially sending someone to a prison or to hospital."}]},"examples":[{"en":"The company's commitment to providing quality at a reasonable price has been vital to its success.","cn":"这家公司保证供货质优价廉的承诺对它的成功起了决定性的作用。"},{"en":"She doesn't want to make a big emotional commitment to Steve at the moment.","cn":"她不想在此刻对史蒂夫在感情上作出重大的承诺。"}]},"conditioning":{"oxford":{"phon":"kənˈdɪʃənɪŋ","pos":"noun","senses":[{"en":"the training or experience that an animal or a person has that makes them behave in a particular way in a particular situation","cn":"训练；熏陶；条件作用","ex":{"en":"Is personality the result of conditioning from parents and society, or are we born with it?","cn":"个性是受父母和社会熏陶的结果，还是我们生而有之？"}}]},"media":{"uk":"media/uk/xconditioning__gb_1.mp3","us":"media/us/xconditioning__us_1.mp3"},"examples":[{"en":"Is personality the result of conditioning from parents and society, or are we born with it?","cn":"个性是受父母和社会薰陶的结果，还是我们生而有之？"},{"en":"Social conditioning makes crying more difficult for men.","cn":"社会熏陶使得男人不轻易哭泣。"}],"base":"condition"},"cooking":{"media":{"img":["media/pic/cooking_methods_comp.jpg","media/thumb/casserole.jpg"],"uk":"media/uk/cooking__gb_1.mp3","us":"media/us/cooking__us_1.mp3"},"oxford":{"phon":"ˈkʊkɪŋ","pos":"noun","senses":[{"en":"the process of preparing food by heating it","cn":"烹饪；烹调","lab":"British English","ex":{"en":"My husband does all the cooking.","cn":"我丈夫把做饭全包了下来。"}},{"en":"food that has been prepared in a particular way","cn":"（用某种方法烹制的）食物，饭菜","ex":{"en":"The restaurant offers traditional home cooking (= food similar to that cooked at home).","cn":"这家餐馆供应传统的家常菜。"}},{"en":"suitable for cooking","cn":"适于烹饪的","ex":{"en":"cooking oil","cn":"食用油"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(做好的)饭菜","en":"Cooking is food which has been cooked.","ex":{"en":"The menu is based on classic French cooking.","cn":"菜单是以经典的法国菜为主。"}},{"pos":"ADJ 形容词","cn":"烹调用的;适合烹饪的","en":"Cooking ingredients or equipment are used in cookery.","ex":{"en":"Finely slice the cooking apples.","cn":"把烹调用的苹果切成薄片。"}}]},"examples":[{"en":"The restaurant offers traditional home cooking (= food similar to that cooked at home).","cn":"这家餐馆供应传统的家常菜。"},{"en":"My husband does all the cooking.","cn":"我丈夫把做饭全包了下来。"}],"base":"cook"},"conclude":{"media":{"uk":"media/uk/xconclude__gb_1.mp3","us":"media/us/xconclude__us_1.mp3"},"oxford":{"phon":"kənˈkluːd","pos":"verb","senses":[{"en":"to decide or believe something as a result of what you have heard or seen","cn":"断定；推断出；得出结论","g":"[transitive]","ex":{"en":"It is too early for us to conclude anything.","cn":"我们现在下结论还为时过早。"}},{"en":"to come to an end; to bring something to an end","cn":"（使）结束，终止","g":"[intransitive, transitive]","lab":"formal","ex":{"en":"This was how the negotiations finally concluded.","cn":"最终谈判就是这样结束的。"}},{"en":"to arrange and settle an agreement with somebody formally and finally","cn":"达成，订立，缔结（协定）","g":"[transitive]","lab":"formal","ex":{"en":"They concluded a treaty with Turkey.","cn":"他们同土耳其缔结了一项条约。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"推断出;推论出;断定","en":"If you conclude that something is true, you decide that it is true using the facts you know as a basis.","ex":{"en":"Larry had concluded that he had no choice but to accept Paul's words as the truth","cn":"拉里断定自己别无选择，只能当保罗的话是真的。"}},{"pos":"VERB 动词","cn":"结束(讲话);总结","en":"When you conclude, you say the last thing that you are going to say.","ex":{"en":"'It's a waste of time,' he concluded","cn":"“这是浪费时间。”他总结道。"}},{"pos":"V-ERG 及物/不及物动词","cn":"结束;终止","en":"When something concludes, or when you conclude it, you end it.","ex":{"en":"The evening concluded with dinner and speeches","cn":"这个夜晚在宴会和讲话中结束。"}},{"pos":"V-RECIP 相互动词","cn":"达成(协议等);缔结(条约)","en":"If one person or group concludes an agreement, such as a treaty or business deal, with another, they arrange it. You can also say that two people or groups conclude an agreement.","ex":{"en":"Mexico and the Philippines have both concluded agreements with their commercial bank creditors","cn":"墨西哥和菲律宾均已与商业银行债权人达成了协议。"}}]},"examples":[{"en":"The report concluded (that) the cheapest option was to close the laboratory.","cn":"这份报告认为代价最低廉的选择是关闭实验室。"},{"en":"He concluded from their remarks that they were not in favour of the plan.","cn":"他从他们的话语中推断出他们不赞同此项计划。"}]},"collectivism":{"oxford":{"phon":"kəˈlektɪvɪzəm","pos":"noun","senses":[{"en":"the political system in which all farms, businesses and industries are owned by the state or by all the people","cn":"集体主义；集体所有制；公有制"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"集体主义(制度);公有制","en":"Collectivism is the political belief that a country's industries and services should be owned and controlled by the state or by all the people in a country."}]},"media":{"uk":"media/uk/collectivism__gb_1.mp3","us":"media/us/collectivism__us_1.mp3"}},"colony":{"oxford":{"phon":"ˈkɒləni","pos":"noun","senses":[{"en":"a country or an area that is governed by people from another, more powerful, country","cn":"殖民地","g":"[countable]","ex":{"en":"former British colonies","cn":"前英国殖民地"}},{"en":"a group of people who go to live permanently in a colony","cn":"殖民地定居者群体","g":"[singular + singular or plural verb]"},{"en":"a group of people from the same place or with the same work or interests who live in a particular city or country or who live together","cn":"（来自同一地方，职业或兴趣相同的）聚居人群","g":"[countable + singular or plural verb]","ex":{"en":"the American colony in Paris","cn":"聚居巴黎的美国侨民"}},{"en":"a small town set up by an employer or an organization for its workers","cn":"（雇主或机构设立的）职工城，职工居住区","g":"[countable]","lab":"Indian English"},{"en":"a group of plants or animals that live together or grow in the same place","cn":"（同地生长的植物或动物）群体，集落，群","g":"[countable + singular or plural verb]","lab":"biology","ex":{"en":"a colony of ants","cn":"蚁群"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"殖民地","en":"A colony is a country which is controlled by a more powerful country.","ex":{"en":"In France's former North African colonies, anti-French feeling is growing","cn":"在北非的一些前法属殖民地国家，反法情绪日益增长。"}},{"pos":"N-COUNT 可数名词","cn":"(某一类人的)聚居地，聚居区","en":"You can refer to a place where a particular group of people lives as a particular kind of colony .","ex":{"en":"In 1932, he established a school and artists' colony in Stone City, Iowa.","cn":"1932年，他在艾奥瓦州的石头城创建了一所学校，那儿成了艺术家的聚居地。"}},{"pos":"N-PLURAL 复数名词","cn":"(统称)英属殖民地","en":"The colonies means all the countries that used to be British colonies.","ex":{"en":"Many of our troops and officers were scattered around the world in the service of His Majesty in the colonies.","cn":"我们的很多部队和军官分驻世界各地的英属殖民地，为英王效力。"}},{"pos":"N-PLURAL 复数名词","cn":"(美国独立前的)北美十三州","en":"The colonies means the 13 British colonies in North America which formed the original United States.","ex":{"en":"On the eve of the Revolution, the colonies produced thirty thousand tons of crude iron a year.","cn":"独立战争前夕，北美十三州每年生产3万吨生铁。"}},{"pos":"N-COUNT 可数名词","cn":"(鸟、昆虫或动物的)群体，集群，群落","en":"A colony of birds, insects, or animals is a group of them that live together.","ex":{"en":"The Shetlands are famed for their colonies of sea birds","cn":"设得兰群岛以其众多的海鸟而闻名。"}}]},"media":{"uk":"media/uk/colony__gb_1.mp3","us":"media/us/colony__us_1.mp3"},"examples":[{"en":"the American colony in Paris","cn":"聚居巴黎的美国侨民"},{"en":"former British colonies","cn":"前英国殖民地"}]},"consuming":{"media":{"uk":"media/uk/xconsuming__gb_1.mp3","us":"media/us/xconsuming__us_1.mp3"},"oxford":{"phon":"kənˈsjuːmɪŋ","pos":"adjective","senses":[{"en":"so strong or important that it takes up all your time and energy","cn":"强烈的；重要的；令人着迷的","ex":{"en":"Basketball is his consuming passion.","cn":"篮球令他着迷。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"令人沉迷的;极其强烈的;令人忘乎一切的","en":"A consuming passion or interest is more important to you than anything else.","ex":{"en":"He has developed a consuming passion for chess.","cn":"他对下棋产生了极为浓厚的兴趣。"}}]},"examples":[{"en":"Basketball is his consuming passion.","cn":"篮球令他着迷。"},{"en":"During this period, politics became his consuming interest.","cn":"这段时期﹐政治成了他强烈的兴趣所在。"}],"base":"consume"},"corporate":{"media":{"uk":"media/uk/corporate__gb_1.mp3","us":"media/us/corporate__us_1.mp3"},"oxford":{"phon":"ˈkɔːpərət","pos":"adjective","senses":[{"en":"connected with a large business company","cn":"（大）公司的","ex":{"en":"corporate finance/profits/tax","cn":"公司财务／利润／税务"}},{"en":"forming a corporation (= an organization or group of organizations that is recognized by law as a single unit)","cn":"法人的；组成公司（或团体）的","lab":"specialist","ex":{"en":"The BBC is a corporate organization.","cn":"英国广播公司为法人组织。"}},{"en":"involving or shared by all the members of a group","cn":"社团的；全体的；共同的","ex":{"en":"a corporate act of worship in the College chapel","cn":"在学院教堂举行的集体礼拜活动"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"公司的","en":"Corporate means relating to business corporations or to a particular business corporation.","ex":{"en":"...top US corporate executives.","cn":"美国顶级公司经理人"}}]},"examples":[{"en":"The law applies to both individuals and corporate bodies.","cn":"本法律既适用于个人也适用于法人团体。"},{"en":"The BBC is a corporate body.","cn":"英国广播公司为法人团体。"}]},"compare":{"media":{"uk":"media/uk/compare__gb_1.mp3","us":"media/us/compare__us_1.mp3"},"oxford":{"phon":"kəmˈpeə(r)","pos":"verb","senses":[{"en":"to examine people or things to see how they are similar and how they are different","cn":"比较；对比","g":"[transitive]","ex":{"en":"It is interesting to compare their situation and ours.","cn":"把他们的状况与我们的相比很有意思。"}},{"en":"to be similar to somebody/something else, either better or worse","cn":"与…类似（或相似）","g":"[intransitive]","ex":{"en":"This school compares with the best in the country (= it is as good as them).","cn":"这所学校可与全国最好的学校媲美。"}},{"en":"to show or state that somebody/something is similar to somebody/something else","cn":"表明…与…相似；将…比作","g":"[transitive]","ex":{"en":"The critics compared his work to that of Martin Amis.","cn":"评论家把他的作品和马丁·埃米斯的相提并论。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"比较;对比","en":"When you compare things, you consider them and discover the differences or similarities between them. to compare notes→see: ;","ex":{"en":"Compare the two illustrations in Fig 60","cn":"比较图60中的两幅插图。"}},{"pos":"VERB 动词","cn":"把…比作","en":"If you compare one person or thing to another, you say that they are like the other person or thing.","ex":{"en":"Some commentators compared his work to that of James Joyce","cn":"有些评注者把他的作品与詹姆斯·乔伊斯的作品相提并论。"}},{"pos":"V-RECIP 相互动词","cn":"(与…)比起来(好/差)","en":"If one thing compares favourably with another, it is better than the other thing. If it compares unfavourably, it is worse than the other thing.","ex":{"en":"Our road safety record compares favourably with that of other European countries","cn":"我们的道路安全纪录比欧洲其他国家要好。"}},{"pos":"VERB 动词","cn":"相比","en":"If you say that something does not compare with something else, you mean that it is much worse.","ex":{"en":"The flowers here do not compare with those at home","cn":"这儿的花比不上家乡的花。"}},{"pos":"PHRASE 短语","cn":"无与伦比;无可比拟","en":"If you describe something as beyond compare, you mean that it is extremely good or extremely great.","ex":{"en":"She was a storyteller beyond compare.","cn":"她是个无与伦比的讲故事高手。"}}]},"examples":[{"en":"I've had some difficulties, but they were nothing compared to yours (= they were not nearly as bad as yours).","cn":"我遇到了一些困难，但与你的困难比起来就算不上什么了。"},{"en":"Standards in health care have improved enormously compared to 40 years ago.","cn":"与 40 年前相比，卫生保健的水平提高了不少。"}]},"comparatively":{"media":{"uk":"media/uk/comparatively__gb_1.mp3","us":"media/us/comparatively__us_1.mp3"},"oxford":{"phon":"kəmˈpærətɪvli","pos":"adverb","senses":[{"en":"as compared to something/somebody else","cn":"比较上；相对地","ex":{"en":"The unit is comparatively easy to install and cheap to operate.","cn":"这种设备比较容易安装而且用起来便宜。"}}]},"examples":[{"en":"The unit is comparatively easy to install and cheap to operate.","cn":"这种设备比较容易安装而且用起来便宜。"},{"en":"He died comparatively young (= at a younger age than most people die).","cn":"他死时年纪并不大。"}]},"collects":{"lemma":"collect","media":{"uk":"media/uk/collect__gb_1.mp3","us":"media/us/collect__us_1.mp3"}},"collected":{"media":{"uk":"media/uk/collected__gb_1.mp3","us":"media/us/collected__us_1.mp3"},"oxford":{"phon":"kəˈlektɪd","pos":"adjective","senses":[{"en":"very calm and in control of yourself","cn":"镇静；冷静；泰然","g":"[not before noun]","ex":{"en":"She always stays cool, calm and collected in a crisis.","cn":"她在危急关头总是很冷静镇定，处之泰然。"}},{"en":"all the books, etc. written by one author, published in one book or in a set","cn":"收成全集的","ex":{"en":"the collected works of Edgar Allan Poe","cn":"埃德加·爱伦·坡文集"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(作品、信件)收成全集的","en":"An author's collected works or letters are all their works or letters published in one book or in a set of books.","ex":{"en":"...the collected works of Rudyard Kipling","cn":"拉迪亚德·吉卜林作品全集"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(尤指在困难或危急情境中)镇定的，泰然自若的","en":"If you say that someone is collected, you mean that they are very calm and self-controlled, especially when they are in a difficult or serious situation.","ex":{"en":"Police say she was cool and collected during her interrogation.","cn":"警方说她在审问过程中表现得冷静自若。"}}]},"examples":[{"en":"She always stays cool, calm and collected in a crisis.","cn":"她在危急关头总是很冷静镇定，处之泰然。"},{"en":"She wanted to arrive feeling cool, calm, and collected .","cn":"她想在到达时感觉平和冷静﹐泰然自若。"}],"base":"collect"},"cooks":{"lemma":"cook","media":{"uk":"media/uk/cook__gb_1.mp3","us":"media/us/cook__us_1.mp3"}},"compliment":{"media":{"uk":"media/uk/compliment__gb_1.mp3","us":"media/us/compliment__us_1.mp3"},"oxford":{"phon":"ˈkɒmplɪmənt","pos":"noun","senses":[{"en":"a comment that expresses praise or approval of somebody","cn":"赞扬；称赞","g":"[countable]","ex":{"en":"to pay somebody a compliment (= to praise them for something)","cn":"对某人表示赞扬"}},{"en":"polite words or good wishes, especially when used to express praise and approval","cn":"致意；问候；祝贺","g":"[plural]","lab":"formal","ex":{"en":"My compliments to the chef!","cn":"请向厨师代为致意！"}},{"en":"to tell somebody that you like or admire something they have done, their appearance, etc.","cn":"赞美；称赞；钦佩","ex":{"en":"She complimented him on his excellent German.","cn":"她夸奖他德语棒极了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"赞美;恭维(话)","en":"A compliment is a polite remark that you say to someone to show that you like their appearance, appreciate their qualities, or approve of what they have done.","ex":{"en":"You can do no harm by paying a woman compliments","cn":"对女人说些恭维话没有坏处。"}},{"pos":"VERB 动词","cn":"赞美;恭维","en":"If you compliment someone, you pay them a compliment.","ex":{"en":"They complimented me on the way I looked each time they saw me","cn":"每次见到我，他们都称赞我的外貌。"}},{"pos":"N-COUNT 可数名词","cn":"赞美;赞赏","en":"If you consider something that a person says or does as a compliment, it convinces you of your own good qualities, or that the person appreciates you.","ex":{"en":"We consider it a compliment to be called 'conservative'","cn":"我们认为被称作“保守分子”是对我们的一种赞赏。"}},{"pos":"N-PLURAL 复数名词","cn":"致谢;祝贺;致意","en":"You can refer to your compliments when you want to express thanks, good wishes, or respect to someone in a formal way.","ex":{"en":"My compliments to the chef","cn":"请向厨师代为致意！"}},{"pos":"PHRASE 短语","cn":"回报;回敬","en":"If you say that someone returns the compliment, you mean that they do the same thing to someone else as that person has done to them.","ex":{"en":"The actors have entertained us so splendidly during this weekend, I think it's time we returned the compliment.","cn":"这周末演员们给我们带来了精彩的演出，我觉得我们该回请他们了。"}},{"pos":"PHRASE 短语","cn":"(尤指赠送礼物或给予帮助时)…敬赠，请接受…的敬意","en":"If you say that you are giving someone something with your compliments, you are saying in a polite and fairly formal way that you are giving it to them, especially as a gift or a favour.","ex":{"en":"Please give this to your boss with my compliments","cn":"请把这个给你的老板，算是我的一点心意。"}}]},"examples":[{"en":"‘You understand the problem because you're so much older.’ ‘I'll take that as a compliment! ’ “","cn":"您能理解这个问题，因为您是长者。” “过奖了。”"},{"en":"( BrE ) Compliments of the season! (= for Christmas or the New Year)","cn":"谨致节日的祝贺！（圣诞节或新年时的贺辞）"}]},"completion":{"oxford":{"phon":"kəmˈpliːʃn","pos":"noun","senses":[{"en":"the act or process of finishing something; the state of being finished and complete","cn":"完成；结束","g":"[uncountable]","ex":{"en":"the completion of the new hospital building","cn":"新医院大楼的竣工"}},{"en":"the formal act of completing the sale of property, for example the sale of a house","cn":"（房地产等的）完成交易，完成交割","g":"[uncountable, countable]","lab":"British English","ex":{"en":"The keys will be handed over on completion.","cn":"完成交易时交钥匙。"}}]},"media":{"uk":"media/uk/completion__gb_1.mp3","us":"media/us/completion__us_1.mp3"},"examples":[{"en":"Satisfactory completion of the course does not ensure you a job.","cn":"圆满完成课程并不能保证你能得到工作。"},{"en":"The project is due for completion in the spring.","cn":"这项工程预定在明年春季竣工。"}]},"courtyard":{"media":{"uk":"media/uk/courtyard__gb_1.mp3","us":"media/us/courtyard__us_1.mp3"},"oxford":{"phon":"ˈkɔːtjɑːd","pos":"noun","senses":[{"en":"an open space that is partly or completely surrounded by buildings and is usually part of a castle, a large house, etc.","cn":"（通常为城堡、大宅第等的）庭院，院子，天井","ex":{"en":"the central/inner courtyard","cn":"中心／内庭院"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"庭院;院子;天井","en":"A courtyard is an open area of ground which is surrounded by buildings or walls.","ex":{"en":"They walked through the arch and into the cobbled courtyard.","cn":"他们穿过拱门走进铺着鹅卵石的院子。"}}]},"examples":[{"en":"the central/inner courtyard","cn":"中心/内庭院"},{"en":"the castle courtyard","cn":"城堡的庭院"}]},"coffee":{"media":{"uk":"media/uk/coffee__gb_1.mp3","us":"media/us/coffee__us_1.mp3","img":["media/ldoce/img/coffee.jpg"]},"oxford":{"phon":"ˈkɒfi","pos":"noun","senses":[{"en":"the roasted seeds (called coffee beans) of a tropical bush; a powder made from them","cn":"（烘烤过的）咖啡豆；咖啡粉","g":"[uncountable, countable]","ex":{"en":"ground/real/instant coffee","cn":"现磨咖啡；速溶咖啡"}},{"en":"a hot drink made from coffee powder and boiling water. It may be drunk with milk and/or sugar added.","cn":"咖啡（热饮料）","g":"[uncountable]","ex":{"en":"to drink/sip coffee","cn":"喝／抿咖啡"}},{"en":"a cup of coffee","cn":"一杯咖啡","g":"[countable]","ex":{"en":"Do you want to go and get a coffee?","cn":"你想去喝杯咖啡吗？"}},{"en":"the colour of coffee mixed with milk; light brown","cn":"咖啡色；浅褐色；浅棕色","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"咖啡","en":"Coffee is a hot drink made with water and ground or powdered coffee beans.","ex":{"en":"Would you like some coffee?","cn":"要来点咖啡吗？"}},{"pos":"N-MASS 物质名词","cn":"咖啡豆;咖啡粉","en":"Coffee is the roasted beans or powder from which the drink is made.","ex":{"en":"Brazil harvested 28m bags of coffee in 1991, the biggest crop for four years.","cn":"1991年，巴西的咖啡豆产量达2,800万袋，为4年来最高。"}}]},"examples":[{"en":"a blend of Brazilian and Colombian coffees","cn":"巴西和哥伦比亚的混合咖啡"},{"en":"Two strong black coffees, please.","cn":"请来两杯不加奶的浓咖啡。"}]},"comatose":{"media":{"uk":"media/uk/comatose__gb_1.mp3","us":"media/us/comatose__us_1.mp3"},"oxford":{"phon":"ˈkəʊmətəʊs","pos":"adjective","senses":[{"en":"deeply unconscious; in a coma","cn":"不省人事的；昏迷的","lab":"medical"},{"en":"extremely tired and having no energy; sleeping deeply","cn":"困乏的；无精打采的；酣睡的","lab":"humorous"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"昏迷的","en":"A person who is comatose is in a coma.","ex":{"en":"The right side of my brain had been so severely bruised that I was comatose for a month.","cn":"由于右脑遭受重创，我昏迷了一个月。"}},{"pos":"ADJ 形容词","cn":"(通常指因劳累或饮酒过量而)酣睡的","en":"A person who is comatose is in a deep sleep, usually because they are tired or have drunk too much alcohol.","ex":{"en":"Grandpa lies comatose on the sofa.","cn":"爷爷躺在沙发上，睡得很沉。"}}]}},"committee":{"oxford":{"phon":"kəˈmɪti","pos":"noun","senses":[{"en":"a group of people who are chosen, usually by a larger group, to make decisions or to deal with a particular subject","cn":"委员会","ex":{"en":"an executive/advisory/organizing committee","cn":"执行／咨询／组织委员会"}}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"委员会","en":"A committee is a group of people who meet to make decisions or plans for a larger group or organization that they represent.","ex":{"en":"...a committee of ministers.","cn":"部长委员会"}}]},"media":{"uk":"media/uk/committee__gb_1.mp3","us":"media/us/committee__us_1.mp3"},"examples":[{"en":"The committee has/have decided to close the restaurant.","cn":"委员会已决定关闭这家餐馆。"},{"en":"She's on the management committee.","cn":"她任管理委员会委员。"}]},"collections":{"lemma":"collection","media":{"uk":"media/uk/collection__gb_1.mp3","us":"media/us/collection__us_1.mp3"}},"complicated":{"media":{"uk":"media/uk/complicated__gb_1.mp3","us":"media/us/complicated__us_1.mp3"},"oxford":{"phon":"ˈkɒmplɪkeɪtɪd","pos":"adjective","senses":[{"en":"made of many different things or parts that are connected; difficult to understand","cn":"复杂的；难懂的","ex":{"en":"a complicated issue/process/system","cn":"复杂的问题／过程／系统"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"复杂的;难懂的;难处理的","en":"If you say that something is complicated, you mean it has so many parts or aspects that it is difficult to understand or deal with.","ex":{"en":"The situation in Lebanon is very complicated.","cn":"黎巴嫩的情况十分复杂。"}}]},"examples":[{"en":"It's all very complicated — but I'll try and explain.","cn":"尽管这一切都很难理解，但我会尽力解释。"},{"en":"The instructions look very complicated.","cn":"这说明书看起来很难懂。"}],"base":"complicate"},"courage":{"media":{"uk":"media/uk/courage__gb_1.mp3","us":"media/us/courage__us_1.mp3"},"oxford":{"phon":"ˈkʌrɪdʒ","pos":"noun","senses":[{"en":"the ability to do something dangerous, or to face pain or opposition, without showing fear","cn":"勇气；勇敢；无畏；胆量","ex":{"en":"He showed great courage and determination.","cn":"他表现得十分勇敢和果断。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"勇气;勇敢;胆量","en":"Courage is the quality shown by someone who decides to do something difficult or dangerous, even though they may be afraid.","ex":{"en":"General Lewis Mackenzie has impressed everyone with his authority and personal courage","cn":"刘易斯·麦肯奇将军的威信和勇气给所有人留下了深刻的印象。"}},{"pos":"PHRASE 短语","cn":"有勇气做自己认为正确的事","en":"If you have the courage of your convictions, you have the confidence to do what you believe is right, even though other people may not agree or approve. to pluck up the courage→see: ;","ex":{"en":"Developers should have the courage of their convictions and stick to what they do best.","cn":"研发人员应该对自己充满信心，坚持做自己最擅长的事。"}}]},"examples":[{"en":"Taking her courage in both hands, she opened the door and walked in.","cn":"她壮着胆打开门，走了进去。"},{"en":"He showed great courage and determination.","cn":"他表现得十分勇敢和果断。"}]},"country":{"media":{"uk":"media/uk/country__gb_1.mp3","us":"media/us/country__us_1.mp3"},"oxford":{"phon":"ˈkʌntri","pos":"noun","senses":[{"en":"an area of land that has or used to have its own government and laws","cn":"国；国家","g":"[countable]","lab":"British English","ex":{"en":"European countries","cn":"欧洲国家"}},{"en":"any area outside towns and cities, with fields, woods, farms, etc.","cn":"乡下；乡村","g":"[singular]","lab":"especially North American English","ex":{"en":"I live in the country.","cn":"我住在乡下。"}},{"en":"an area of land, especially with particular physical features, suitable for a particular purpose or connected with a particular person or people","cn":"（尤指具有某种自然特征、适于某目的或与某种人有关的）地区，区域","g":"[uncountable]","ex":{"en":"The town is surrounded by miles and miles of open country.","cn":"小镇的周围是连绵数英里的空旷地带。"}},{"en":"the people of a country; the nation as a whole","cn":"全国人民；国民；全民","g":"[singular]","ex":{"en":"They have the support of most of the country.","cn":"他们有大多数国民的支持。"}},{"en":"a type of popular music in the style of the traditional music of the southern US, with singing and dance tunes played on violin, guitar and banjo","cn":"乡村音乐","g":"[uncountable]","ex":{"en":"pop, folk and country","cn":"流行、民谣和乡村音乐"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"国;国家","en":"A country is one of the political units which the world is divided into, covering a particular area of land.","ex":{"en":"Indonesia is the fourth most populous country in the world.","cn":"印度尼西亚是世界上第四大人口大国。"}},{"pos":"N-SING 单数名词","cn":"全国人民;国民;全民","en":"The people who live in a particular country can be referred to as the country .","ex":{"en":"The country had confounded the pundits by electing a fourth-term Tory government","cn":"该国国民连续四次选举托利党来执掌政府，这令专家们困惑不已。"}},{"pos":"N-SING 单数名词","cn":"乡下;乡村","en":"The country consists of places such as farms, open fields, and villages which are away from towns and cities.","ex":{"en":"...a healthy life in the country","cn":"乡下的健康生活"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(具有某种特征或与某名人有关的)地区，区域","en":"A particular kind of country is an area of land which has particular characteristics or is connected with a particular well-known person.","ex":{"en":"Varese Ligure is a small town in mountainous country east of Genoa.","cn":"瓦雷泽古雷是位于热那亚以东山区的一座小城。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(源自美国南部的)乡村音乐","en":"Country music is popular music from the southern United States.","ex":{"en":"For a long time I just wanted to play country music.","cn":"有很长一段时间我只想弹奏乡村音乐。"}},{"pos":"PHRASE 短语","cn":"穿过田野;不走大路","en":"If you travel across country, you travel through country areas, avoiding major roads and towns.","ex":{"en":"From here we walked across country to Covington.","cn":"我们从这儿走乡间小路去卡温顿。"}},{"pos":"PHRASE 短语","cn":"长途;长距离;跨越地区地","en":"If you travel across country, you travel a long distance, from one part of a country to another.","ex":{"en":"We've just moved all the way across country to begin a new life.","cn":"我们刚刚经过长途的搬迁来这里开始一种新生活。"}},{"pos":"PHRASE 短语","cn":"(政府首脑或政府)举行大选","en":"If a head of government or a government goes to the country, they hold a general election.","ex":{"en":"The Prime Minister does not have to go to the country for another year.","cn":"首相明年也不用举行大选。"}}]},"examples":[{"en":"This pattern of woods and fields is typical of the English landscape.","cn":"这种林地与田野的格局是典型的英格兰乡村景色。"},{"en":"Many younger people are leaving the land to find work in the cities.","cn":"许多较年轻的人陆续离开农村到城市去找工作。"}]},"commercialism":{"media":{"uk":"media/uk/commercialism__gb_1.mp3","us":"media/us/commercialism__us_1.mp3"},"oxford":{"phon":"kəˈmɜːʃəlɪzəm","pos":"noun","senses":[{"en":"the fact of being more interested in making money than in the value or quality of things","cn":"商业主义；赢利主义","ex":{"en":"commercialism in the theatre","cn":"剧院的商业主义"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"商业主义;营利主义","en":"Commercialism is the practice of making a lot of money from things without caring about their quality.","ex":{"en":"Koons has engrossed himself in a world of commercialism that most modern artists disdain.","cn":"昆斯投身于商界，那是一个大部分现代艺术家所不齿的圈子。"}}]},"examples":[{"en":"the commercialism of modern culture","cn":"现代文化的实利主义"}]},"cook":{"media":{"uk":"media/uk/cook__gb_1.mp3","us":"media/us/cook__us_1.mp3"},"oxford":{"phon":"kʊk","pos":"verb","senses":[{"en":"to prepare food by heating it, for example by boiling, baking or frying it","cn":"烹饪；烹调","g":"[intransitive, transitive]","lab":"especially British English","ex":{"en":"Where did you learn to cook?","cn":"你在哪里学的烹调？"}},{"en":"to be prepared by boiling, baking, frying, etc.","cn":"煮（或烘烤、煎炸等）","g":"[intransitive]","ex":{"en":"While the pasta is cooking, prepare the sauce.","cn":"煮意大利面的时候，准备酱汁。"}},{"en":"to be planned secretly","cn":"密谋；秘密策划","g":"[intransitive]","lab":"informal","ex":{"en":"Everyone is being very secretive—there's something cooking.","cn":"人人都神秘兮兮的，准是在搞什么鬼把戏。"}},{"en":"a person who cooks food or whose job is cooking","cn":"做饭的人；炊事员；厨师","ex":{"en":"John is a very good cook (= he cooks well).","cn":"约翰很会做菜。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"烹饪;烹调;煮;烧","en":"When you cook a meal, you prepare food for eating by heating it.","ex":{"en":"I have to go and cook the dinner","cn":"我得去做饭了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"烧(熟);煮(熟)","en":"When you cook food, or when food cooks, it is heated until it is ready to be eaten.","ex":{"en":"...some basic instructions on how to cook a turkey","cn":"烹饪火鸡的一些基本的做法指导"}},{"pos":"N-COUNT 可数名词","cn":"厨师;炊事员","en":"A cook is a person whose job is to prepare and cook food, especially in someone's home or in an institution.","ex":{"en":"They had a butler, a cook, and a maid.","cn":"他们有一个男管家、一个厨师和一个女佣。"}},{"pos":"N-COUNT 可数名词","cn":"做饭的人;烹饪者","en":"If you say that someone is a good cook, you mean they are good at preparing and cooking food."},{"pos":"PHRASE 短语","cn":"篡改数据;做假账","en":"If you say that someone has cooked the books, you mean that they have changed figures or a written record in order to deceive people."},{"pos":"","cn":"","en":"相关词组：cook up"}]},"examples":[{"en":"Everyone is being very secretive — there's something cooking.","cn":"人人都神秘兮兮的，准是在搞什么鬼把戏。"},{"en":"His accountant had been cooking the books for years.","cn":"多年来他的会计师一直在做假账。"}]},"conclusion":{"media":{"uk":"media/uk/xconclusion__gb_1.mp3","us":"media/us/xconclusion__us_1.mp3"},"oxford":{"phon":"kənˈkluːʒn","pos":"noun","senses":[{"en":"something that you decide when you have thought about all the information connected with the situation","cn":"结论；推论","g":"[countable]","ex":{"en":"We can safely draw some conclusions from our discussion.","cn":"从讨论中我们可以有把握地得出一些结论。"}},{"en":"the end of something such as a speech or a piece of writing","cn":"结束；结果；结尾；结局","g":"[countable, usually singular]","ex":{"en":"The conclusion of the book was disappointing.","cn":"这部书的结尾令人失望。"}},{"en":"the formal and final arrangement of something official","cn":"签订；达成；缔结","g":"[uncountable]","ex":{"en":"the successful conclusion of a trade treaty","cn":"贸易条约的成功签署"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"结论;推论","en":"When you come to a conclusion, you decide that something is true after you have thought about it carefully and have considered all the relevant facts.","ex":{"en":"Over the years I've come to the conclusion that she's a very great musician","cn":"这些年来，我得出的结论是她是一位非常伟大的音乐家。"}},{"pos":"N-SING 单数名词","cn":"结束;末尾","en":"The conclusion of something is its ending.","ex":{"en":"At the conclusion of the programme, I asked the children if they had any questions they wanted to ask me.","cn":"节目结束的时候，我问孩子们有没有问题想问我。"}},{"pos":"N-SING 单数名词","cn":"缔结;签订","en":"The conclusion of a treaty or a business deal is the act of arranging it or agreeing it.","ex":{"en":"...the expected conclusion of a free-trade agreement between Mexico and the United States.","cn":"墨西哥与美国之间自由贸易协定的如期签订"}},{"pos":"PHRASE 短语","cn":"必然会发生的事;事先料定的结局","en":"You can refer to something that seems certain to happen as a foregone conclusion .","ex":{"en":"It was a foregone conclusion that I would end up in the same business as him","cn":"早已注定我最终会和他干同一行。"}},{"pos":"PHRASE 短语","cn":"最后;总而言之","en":"You say 'in conclusion' to indicate that what you are about to say is the last thing that you want to say.","ex":{"en":"In conclusion, walking is a cheap, safe, enjoyable and readily available form of exercise.","cn":"总而言之，散步是一种廉价、安全、愉快的锻炼方式，而且随时随地都可以进行。"}},{"pos":"PHRASE 短语","cn":"匆忙地下判断;草率地下结论","en":"If you say that someone jumps to a conclusion, you are critical of them because they decide too quickly that something is true, when they do not know all the facts.","ex":{"en":"I didn't want her to jump to the conclusion that the divorce was in any way her fault","cn":"我不想让她草率地断定离婚完全是她的错。"}}]},"examples":[{"en":"If we took this argument to its logical conclusion …","cn":"假如我们把这个论点归结到合乎其逻辑的结论 …"},{"en":"It took the jury some time to reach the conclusion that she was guilty.","cn":"陪审团花了很长时间才得出结论认为她有罪。"}]},"congenitally":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a congenital medical condition or disease has affected someone since they were born","cn":""},{"en":"a congenital quality is one that has always been part of your character and is unlikely to change","cn":""}]},"examples":[{"en":"He’s a congenital liar .","cn":"","src":"ld"},{"en":"her congenital inability to make decisions","cn":"","src":"ld"}],"media":{"uk":"media/uk/xcongenitally__gb_1.mp3","us":"media/us/xcongenitally__us_1.mp3"},"oxford":{"phon":"kənˈdʒenɪtəli","pos":"adverb","senses":[{"en":"in a way that has existed since or before birth","cn":"先天的；天生的","ex":{"en":"The research involved people who are either congenitally blind or who lost their sight before age 4.","cn":"该研究涉及先天性失明或 4 岁之前失明的人。"}},{"en":"in a way that exists as part of a person's character and that is unlikely to change","cn":"生性的；生就的","ex":{"en":"He is congenitally incapable of telling the truth.","cn":"他天生就没有能力说真话。"}}]}},"controls":{"lemma":"control","media":{"uk":"media/uk/xcontrol__gb_1.mp3","us":"media/us/xcontrol__us_1.mp3"}},"color":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"media":{"uk":"media/uk/color__gb_1.mp3","us":"media/us/color__us_1.mp3"},"oxford":{"phon":"ˈkʌlə(r)","pos":"noun","senses":[{"en":"the appearance that things have that results from the way in which they reflect light. Red, orange and green are colors.","cn":"颜色；色彩","g":"[countable, uncountable]","ex":{"en":"What's your favorite color?","cn":"你最喜欢什么颜色？"}},{"en":"the use of all the colors, not only black and white","cn":"彩色","g":"[uncountable]","ex":{"en":"the introduction of color television in the 1960s","cn":"20 世纪 60 年代彩色电视进入英国"}},{"en":"the color of a person’s skin, seen as showing that they belong to a particular race","cn":"（人种的）肤色","g":"[uncountable, countable]","ex":{"en":"Discrimination on the grounds of race, religion or color was outlawed.","cn":"基于种族、宗教或肤色的歧视被禁止。"}},{"en":"a red or pink color in somebody’s face, especially when it shows that they look healthy or that they are embarrassed","cn":"（尤指脸色的）红润，粉红；（尴尬时的）脸红","g":"[uncountable]","ex":{"en":"The fresh air brought color to their cheeks.","cn":"新鲜空气使他们的脸颊红润。"}},{"en":"a substance that is used to give color to something","cn":"颜料；染料","g":"[countable, uncountable]","ex":{"en":"a semi-permanent hair color that lasts six to eight washes","cn":"经得起洗涤六至八次的半永久性染发剂"}},{"en":"interesting and exciting details or qualities","cn":"趣味；乐趣","g":"[uncountable]","ex":{"en":"The old town is full of color and attractions.","cn":"这座古城姿彩纷呈，引人入胜。"}},{"en":"the particular colors that are used on clothes, flags, etc. to represent a team, school, political party or country","cn":"（用于服装、旗帜等代表团队、学校、政党或国家的）色彩","g":"[plural]","lab":"figurative","ex":{"en":"Red and white are the team colors.","cn":"红白两色是这支队的队服色。"}},{"en":"a flag, badge, etc. that represents a team, country, ship, etc.","cn":"（代表团队、国家、船等的）旗帜，徽章","g":"[plural]","lab":"especially British English","ex":{"en":"sailing under the French colors","cn":"在法国旗帜下航行"}},{"en":"to put color on something using paint, colored pencils, etc.","cn":"（用颜料、彩色笔等）为…着色","g":"[intransitive, transitive]","sc":"put color on something","ex":{"en":"The children love to draw and color.","cn":"孩子们喜欢画画和涂色。"},"pos":"verb"},{"en":"to become red because the person is embarrassed","cn":"（因尴尬而）脸红","g":"[intransitive]","sc":"of face","ex":{"en":"She colored at his remarks.","cn":"她听到他的话脸红了。"},"pos":"verb"},{"en":"to affect something, especially in a negative way","cn":"（尤指负面地）影响","g":"[transitive]","sc":"affect","ex":{"en":"This incident colored her whole life.","cn":"这事件影响了她的一生。"},"pos":"verb"}]}},"consumption":{"media":{"uk":"media/uk/xconsumption__gb_1.mp3","us":"media/us/xconsumption__us_1.mp3"},"oxford":{"phon":"kənˈsʌmpʃn","pos":"noun","senses":[{"en":"the act of using energy, food or materials; the amount used","cn":"（能量、食物或材料的）消耗，消耗量","lab":"figurative","ex":{"en":"the production of fuel for domestic consumption (= to be used in the country where it is produced)","cn":"供国内消耗的燃料生产"}},{"en":"the act of buying and using products","cn":"消费","ex":{"en":"Consumption rather than saving has become the central feature of contemporary societies.","cn":"现代社会的主要特征是消费而不是储蓄。"}},{"en":"a serious disease of the lungs","cn":"肺病；肺痨；肺结核","lab":"old-fashioned"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(燃料、自然资源的)消耗量，消费量","en":"The consumption of fuel or natural resources is the amount of them that is used or the act of using them.","ex":{"en":"The laws have led to a reduction in fuel consumption in the US.","cn":"这些法律已经使美国燃料消费量有所减少。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"吃;喝;饮用","en":"The consumption of food or drink is the act of eating or drinking something, or the amount that is eaten or drunk.","ex":{"en":"Most of the wine was unfit for human consumption","cn":"这些酒中大部分都不适于人类饮用。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"消费","en":"Consumption is the act of buying and using things.","ex":{"en":"Recycling the waste from our increased consumption is better than burning it.","cn":"对我们增加消费产生的垃圾进行回收要好过将其焚烧。"}},{"pos":"PHRASE 短语","cn":"供(某人或某个群体)使用，享用","en":"If you do or say something for a particular person's or group's consumption, you do or say it especially for them, although your private thoughts or plans may be very different.","ex":{"en":"The hard-line speech appears to be mostly for domestic consumption","cn":"强硬路线的讲话似乎主要是说给国内人听的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"同 tuberculosis","en":"Consumption is the same as tuberculosis ."}]},"examples":[{"en":"Gas and oil consumption always increases in cold weather.","cn":"燃气和燃油的消耗量在天冷时总会增加。"},{"en":"Her speech to party members was not intended for public consumption (= to be heard by the public).","cn":"她对党员发表的讲话并不打算公诸大众。"}]},"corroborate":{"oxford":{"phon":"kəˈrɒbəreɪt","pos":"verb","senses":[{"en":"to provide evidence or information that supports a statement, theory, etc.","cn":"证实，确证（陈述、理论等）","ex":{"en":"The evidence was corroborated by two independent witnesses.","cn":"此证据被两名独立证人证实。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"证实;确证","en":"To corroborate something that has been said or reported means to provide evidence or information that supports it.","ex":{"en":"I had access to a wide range of documents which corroborated the story","cn":"我能够查阅证实这一说法的大量文件。"}}]},"media":{"uk":"media/uk/corroborate__gb_1.mp3","us":"media/us/corroborate__us_1.mp3"},"examples":[{"en":"The evidence was corroborated by two independent witnesses.","cn":"此证据由两名独立证人提供。"},{"en":"corroborating evidence","cn":"确凿的证据"}]},"correlates":{"lemma":"correlate"},"coaches":{"lemma":"coach","media":{"img":["media/pic/buses_comp.jpg","media/thumb/bus.jpg"],"uk":"media/uk/coach__gb_1.mp3","us":"media/us/coach__us_1.mp3"}},"counter":{"media":{"uk":"media/uk/counter__gb_1.mp3","us":"media/us/counter__us_1.mp3"},"oxford":{"phon":"ˈkaʊntə(r)","pos":"noun","senses":[{"en":"a long flat surface over which goods are sold or business is done in a shop, bank, etc.","cn":"（商店、银行等的）柜台","ex":{"en":"I asked the woman behind the counter if they had any postcards.","cn":"我问柜台后面的女人是否有明信片。"}},{"en":"a flat surface in a kitchen for preparing food on","cn":"（厨房的）操作台","lab":"both North American English","ex":{"en":"He put his bags down on the kitchen counter.","cn":"他把包放在厨房的柜台上。"}},{"en":"a small disc used for playing or scoring in some board games","cn":"（某些桌面游戏的）棋子，筹码"},{"en":"an electronic device for counting something","cn":"（电子）计数器，计算器","ex":{"en":"The needle on the rev counter soared.","cn":"转速表的指针猛升。"}},{"en":"a person who counts something, for example votes in an election","cn":"计数员；计票员","ex":{"en":"You can get computers to help the counters to count the votes.","cn":"您可以使用计算机来帮助计票员计算选票。"}},{"en":"a response to somebody/something that opposes their ideas, position, etc.","cn":"（对意见、态度等的）反对，反驳","g":"[usually singular]","lab":"formal","ex":{"en":"The employers' association was seen as a counter to union power.","cn":"雇主协会被看作是工会权力的对头。"}},{"en":"to reply to somebody by trying to prove that what they said is not true","cn":"反驳；驳斥","g":"[transitive, intransitive]","ex":{"en":"Such arguments are not easily countered.","cn":"这种论点不易反驳。"},"pos":"verb"},{"en":"to do something to reduce or prevent the bad effects of something","cn":"抵制；抵消","g":"[transitive]","ex":{"en":"Businesses would like to see new laws to counter late payments of debts.","cn":"商界希望见到对付债务逾期不还的新法律出台。"},"pos":"verb"},{"en":"in the opposite direction to something; in opposition to something","cn":"逆向地；相反地；反对地","ex":{"en":"The company's plans run counter to local development guidelines.","cn":"公司的计划与当地的发展方针背道而驰。"},"pos":"adverb"},{"en":"against; opposite","cn":"逆；反对；相反；对立","ex":{"en":"counterterrorism","cn":"反恐怖主义"},"pos":"combining form"},{"en":"corresponding","cn":"相应；对应","ex":{"en":"counterpart","cn":"对方职位相当的人"},"pos":"combining form"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(商店或酒吧的)柜台","en":"In a place such as a shop or café a counter is a long narrow table or flat surface at which customers are served.","ex":{"en":"...those fellows we see working behind the counter at our local video rental store.","cn":"我们见到在我们当地录像带出租店里做店员的那些人"}},{"pos":"VERB 动词","cn":"抵制;抵消","en":"If you do something to counter a particular action or process, you do something which has an opposite effect to it or makes it less effective.","ex":{"en":"The leadership discussed a plan of economic measures to counter the effects of such a blockade","cn":"领导层讨论了计划采取的一揽子经济措施，以减轻这一封锁带来的影响。"}},{"pos":"N-SING 单数名词","cn":"（…的）对立面;（与…）相对的事物","en":"Something that is a counter to something else has an opposite effect to it or makes it less effective.","ex":{"en":"...NATO's traditional role as a counter to the military might of the Warsaw pact.","cn":"北约作为与华沙公约军事力量相抗衡的传统角色"}},{"pos":"VERB 动词","cn":"反驳;驳斥","en":"If you counter something that someone has said, you say something which shows that you disagree with them or which proves that they are wrong.","ex":{"en":"Both of them had to counter fierce criticism","cn":"他们两个人都不得不对尖锐的批评进行反击。"}},{"pos":"N-COUNT 可数名词","cn":"(机械或电子)计数器，计算器","en":"A counter is a mechanical or electronic device which keeps a count of something and displays the total.","ex":{"en":"...an answerphone with an LED display call counter.","cn":"带发光二极管来电显示屏的电话答录机"}},{"pos":"N-COUNT 可数名词","cn":"(棋盘游戏的)筹码","en":"A counter is a small, flat, round object used in board games."},{"pos":"PHRASE 短语","cn":"(买药)不用处方地","en":"If a medicine can be bought over the counter, you do not need a prescription to buy it.","ex":{"en":"Are you taking any other medicines whether on prescription or bought over the counter?","cn":"你在服用其他什么处方药或非处方药吗？"}},{"pos":"PHRASE 短语","cn":"(股票)场外交易的，不通过交易所买卖的","en":"Over-the-counter shares are bought and sold directly rather than on a stock exchange."},{"pos":"PHRASE 短语","cn":"与…相对;与…冲突","en":"If one thing runs counter to another, or if one thing is counter to another, the first thing is the opposite of the second thing or conflicts with it.","ex":{"en":"Much of the plan runs counter to European agriculture and environmental policy","cn":"该计划的很多内容与欧洲农业及环境方面的政策相冲突。"}},{"pos":"PHRASE 短语","cn":"秘密地，暗地里，非法地(销售商品)","en":"If someone buys or sells goods under the counter, they buy or sell them secretly and illegally.","ex":{"en":"The smugglers allegedly sold the gold under the counter, cheating the VAT man out of £5 million.","cn":"据说走私者暗地销售黄金，偷逃增值税达500万英镑。"}}]},"examples":[{"en":"The government's plans run counter to agreed European policy on this issue.","cn":"政府的计划违反了有关这个问题已协商好的欧洲政策。"},{"en":"I tried to argue but he countered that the plans were not yet finished.","cn":"我试图争辩，但他却申辩说各项计划尚未完成。"}]},"concerning":{"media":{"uk":"media/uk/xconcerning__gb_1.mp3","us":"media/us/xconcerning__us_1.mp3"},"oxford":{"phon":"kənˈsɜːnɪŋ","pos":"preposition","senses":[{"en":"about something; involving somebody/something","cn":"关于；涉及","ex":{"en":"He asked several questions concerning the future of the company.","cn":"他问了几个有关公司前途的问题。"}},{"en":"causing worry","cn":"令人担心的","ex":{"en":"This pattern of behaviour is extremely concerning.","cn":"这种行为模式非常令人担忧。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"关于","en":"You use concerning to indicate what a question or piece of information is about.","ex":{"en":"For more information concerning the club contact I. Coldwell.","cn":"咨询俱乐部详情，请与I.科德维尔联系。"}},{"pos":"ADJ 形容词","cn":"让人不安的;令人担忧的","en":"If something is concerning, it causes you to feel concerned about it.","ex":{"en":"It is particularly concerning that he is working for non-British companies while advising on foreign policy.","cn":"让人尤为不安的是，他在提供外交政策咨询的同时却又供职于一些外国公司。"}}]},"examples":[{"en":"All cases concerning children are dealt with in a special children's court.","cn":"所有涉及儿童的案件均由儿童特别法庭审理。"},{"en":"He asked several questions concerning the future of the company.","cn":"他问了几个有关公司前途的问题。"}],"base":"concern"},"contract":{"media":{"uk":"media/uk/xcontract__gb_1.mp3","us":"media/us/xcontract__us_1.mp3"},"oxford":{"phon":"ˈkɒntrækt","pos":"noun","senses":[{"en":"an official written agreement","cn":"合同；合约；契约","ex":{"en":"All employees have a written contract of employment.","cn":"每个员工都有一份书面聘用合同。"}},{"en":"an agreement to kill somebody for money","cn":"（雇用杀人的）协议，合同","lab":"informal","ex":{"en":"She took out a contract on her ex-husband.","cn":"她雇好了凶手打算谋杀她的前夫。"}},{"en":"to become less or smaller; to make something become less or smaller","cn":"（使）收缩，缩小","g":"[intransitive, transitive]","ex":{"en":"Glass contracts as it cools.","cn":"玻璃遇冷收缩。"},"pos":"verb"},{"en":"to get an illness","cn":"感染（疾病）；得（病）","g":"[transitive]","lab":"formal or medical","ex":{"en":"to contract a virus/a disease/measles","cn":"感染病毒／疾病／麻疹"},"pos":"verb"},{"en":"to make a legal agreement with somebody for them to work for you or provide you with a service","cn":"与…订立合同（或契约）","g":"[transitive]","ex":{"en":"The player is contracted to play until August.","cn":"这位选手签约参加比赛到八月份。"},"pos":"verb"},{"en":"to make a legal agreement to work for somebody or provide them with a service","cn":"订立…的合同（或契约）","g":"[intransitive]","ex":{"en":"She has contracted to work 20 hours a week.","cn":"她已签订每周工作 20 小时的合同。"},"pos":"verb"},{"en":"to formally agree to marry somebody/form an alliance with somebody","cn":"（与…）订立（婚约）；（与…）缔结（同盟）","g":"[transitive]","lab":"formal","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"合同;契约","en":"A contract is a legal agreement, usually between two companies or between an employer and employee, which involves doing work for a stated sum of money.","ex":{"en":"The company won a prestigious contract for work on Europe's tallest building","cn":"这家公司赢得了一份极为重要的合同，参与建设欧洲最高的大厦。"}},{"pos":"VERB 动词","cn":"签合同，订立契约(做某事)","en":"If you contract with someone to do something, you legally agree to do it for them or for them to do it for you.","ex":{"en":"You can contract with us to deliver your cargo","cn":"你可以跟我们签订送货合同。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)收缩;(使)缩小;(使)缩短","en":"When something contracts or when something contracts it, it becomes smaller or shorter.","ex":{"en":"Blood is only expelled from the heart when it contracts","cn":"血液在心脏收缩的时候从心脏流出。"}},{"pos":"VERB 动词","cn":"(经济、市场等)紧缩，缩小","en":"When something such as an economy or market contracts, it becomes smaller.","ex":{"en":"The manufacturing economy contracted in October for the sixth consecutive month.","cn":"10月，制造业经济已经连续第6个月出现萎缩状况。"}},{"pos":"VERB 动词","cn":"感染，患(病)","en":"If you contract a serious illness, you become ill with it.","ex":{"en":"He contracted AIDS from a blood transfusion","cn":"他因为输血而感染了艾滋病。"}},{"pos":"VERB 动词","cn":"订立(婚约);签订(盟约等)","en":"If you contract a marriage, alliance, or other relationship with someone, you arrange to have that relationship with them.","ex":{"en":"She contracted a formal marriage to a British ex-serviceman.","cn":"她和一个英国退役军人正式订婚了。"}},{"pos":"N-COUNT 可数名词","cn":"买凶杀人的协议","en":"If there is a contract on a person or on their life, someone has made an arrangement to have them killed.","ex":{"en":"The convictions resulted in the local crime bosses putting a contract on him","cn":"这些判罪导致当地犯罪团伙的老大们要雇凶杀他。"}},{"pos":"PHRASE 短语","cn":"签订工作合同的","en":"If you are under contract to someone, you have signed a contract agreeing to work for them, and for no-one else, during a fixed period of time.","ex":{"en":"The director wanted Olivia de Havilland, then under contract to Warner Brothers.","cn":"导演想要当时签约于华纳兄弟娱乐公司旗下的奥利维娅·德哈维兰出演。"}},{"pos":"","cn":"","en":"相关词组：contract out"}]},"examples":[{"en":"‘I will’ and ‘I shall’ are usually contracted to ‘I'll’ (= made shorter). * I will","cn":"和 I shall 通常缩约为 I'll。"},{"en":"Under the terms of the contract the job should have been finished yesterday.","cn":"根据合同的条款，这项工作本应于昨天完成。"}]},"commonality":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"共同特征;共性","en":"Commonality is used to refer to a feature or purpose that is shared by two or more people or things.","ex":{"en":"We don't have the same commonality of interest","cn":"我们没有共同的兴趣。"}}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41commonality.mp3","us":"media/ldoce/hwd/ame/5/ld41commonality.mp3"},"oxford":{"phon":"ˌkɒmənˈæləti","pos":"noun","senses":[{"en":"the state of sharing features","cn":"共性","g":"[uncountable, singular]","ex":{"en":"There is a high degree of commonality between the different computer science courses on offer.","cn":"所提供的不同计算机科学课程之间存在高度的共性。"}},{"en":"a shared feature","cn":"共同点","g":"[countable]","ex":{"en":"We need to understand the differences between us and the commonalities that we share.","cn":"我们需要了解我们之间的差异以及我们的共同点。"}}]}},"colleague":{"media":{"uk":"media/uk/colleague__gb_1.mp3","us":"media/us/colleague__us_1.mp3"},"oxford":{"phon":"ˈkɒliːɡ","pos":"noun","senses":[{"en":"a person that you work with, especially in a profession or a business","cn":"同事；同僚；同人","ex":{"en":"work/senior/male colleagues","cn":"同事；资深同事；男同事"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同事;同僚","en":"Your colleagues are the people you work with, especially in a professional job.","ex":{"en":"Without consulting his colleagues he flew from Lisbon to Split","cn":"没跟同事们商量，他就从里斯本飞到了斯普利特。"}}]},"examples":[{"en":"We were friends and colleagues for more than 20 years. * 20","cn":"多年来我们既是朋友又是同事。"},{"en":"a colleague of mine from the office","cn":"我办公室的一位同事"}]},"contraction":{"oxford":{"phon":"kənˈtrækʃn","pos":"noun","senses":[{"en":"the process of becoming smaller","cn":"收缩；缩小","g":"[uncountable]","ex":{"en":"The design needs to allow for the expansion and contraction of the metal.","cn":"设计需要考虑到金属的膨胀和收缩。"}},{"en":"a sudden and painful contracting of muscles, especially the muscles around a woman’s womb, that happens when she is giving birth to a child","cn":"（肌肉的）收缩，挛缩；（尤指分娩时的）子宫收缩","g":"[countable, uncountable]","ex":{"en":"The contractions started coming every five minutes.","cn":"子宫开始每隔五分钟收缩一次。"}},{"en":"a short form of a word","cn":"词的缩约形式","g":"[countable]","lab":"linguistics","ex":{"en":"‘He's’ may be a contraction of ‘he is’ or ‘he has’.","cn":"he’s 可以是 he is 或 he has 的缩写形式。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(分娩时的)子宫收缩，宫缩","en":"When a woman who is about to give birth has contractions, she experiences a very strong, painful tightening of the muscles of her womb."},{"pos":"N-COUNT 可数名词","cn":"(词的)缩约形式","en":"A contraction is a shortened form of a word or words.","ex":{"en":"'It's' (with an apostrophe) should be used only as a contraction for 'it is'.","cn":"it's (带撇号)只能用作 it is 的缩约形式。"}}]},"media":{"uk":"media/uk/xcontraction__gb_1.mp3","us":"media/us/xcontraction__us_1.mp3"},"examples":[{"en":"‘He's’ may be a contraction of ‘he is’ or ‘he has’. * he's","cn":"可以是 he is 或 he has 的缩约形式。"},{"en":"The sudden contraction of the markets left them with a lot of unwanted stock.","cn":"股票市场骤然收缩，让他们剩下了许多无人要的股票。"}]},"co":{"media":{"uk":"media/uk/co__gb_1.mp3","us":"media/us/co__us_1.mp3"},"oxford":{"phon":"ˌsiː ˈəʊ","pos":"abbreviation","senses":[{"en":"Commanding Officer (an officer who commands a group of soldiers, sailors, etc.)","cn":"指挥官；指挥长"},{"en":"company","cn":"公司","lab":"business","ex":{"en":"Pitt, Briggs & Co.","cn":"皮特–布里格斯公司"}},{"en":"county","cn":"郡；县"},{"en":"and other members of a group of people","cn":"及其他成员；及其一伙","lab":"informal","ex":{"en":"Were Jane and co. at the party?","cn":"简那几个人都参加聚会了吗？"}},{"en":"together with","cn":"和…一起；共同；联合","ex":{"en":"co-produced","cn":"合作生产的"},"pos":"prefix"}]}},"coverings":{"lemma":"cover","media":{"uk":"media/uk/covering__gb_1.mp3","us":"media/us/covering__us_1.mp3"}},"corollary":{"media":{"uk":"media/uk/corollary__gb_1.mp3","us":"media/us/corollary__us_1.mp3"},"oxford":{"phon":"kəˈrɒləri","pos":"noun","senses":[{"en":"a situation, an argument or a fact that is the natural and direct result of another one","cn":"必然的结果（或结论）","ex":{"en":"In rural areas, the corollary of increased car ownership has been a rapid decline in the provision of public transport.","cn":"在农村地区，汽车保有量增加的必然结果是公共交通供应迅速下降。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"必然的想法(或结果);直接推论","en":"A corollary of something is an idea, argument, or fact that results directly from it.","ex":{"en":"The number of prisoners increased as a corollary of the government's determination to combat violent crime.","cn":"政府决心打击暴力犯罪，直接导致了囚犯数量的增多。"}}]},"examples":[{"en":"Is social inequality the inevitable corollary of economic freedom?","cn":"社会不平等是不是经济自由的必然结果呢？"}]},"cognitively":{"lemma":"cognitive","media":{"uk":"media/uk/cognitive__gb_1.mp3","us":"media/us/cognitive__us_1.mp3"}},"committing":{"lemma":"commit"},"communicate":{"media":{"uk":"media/uk/communicate__gb_1.mp3","us":"media/us/communicate__us_1.mp3"},"oxford":{"phon":"kəˈmjuːnɪkeɪt","pos":"verb","senses":[{"en":"to share or exchange information, news, ideas, feelings, etc.","cn":"交流（信息、消息、意见、情感等）","g":"[intransitive, transitive]","sc":"exchange information","ex":{"en":"We only communicate by email.","cn":"我们只是互通电邮。"}},{"en":"to have a good relationship because you are able to understand and talk about your own and other people’s thoughts, feelings, etc.","cn":"沟通（想法、情感等）","g":"[intransitive]","sc":"in a relationship","ex":{"en":"His inability to communicate has damaged their relationship beyond repair.","cn":"他欠缺沟通能力，使他们的关系受到无法修复的伤害。"}},{"en":"to pass a disease from one person, animal, etc. to another","cn":"传染；传播","g":"[transitive, usually passive]","sc":"disease","ex":{"en":"The disease is communicated through dirty drinking water.","cn":"这种疾病通过不干净的饮用水传播。"}},{"en":"if two rooms communicate, they are next to each other and you can get from one to the other","cn":"相通；相连","g":"[intransitive]","sc":"of two rooms","ex":{"en":"a communicating door (= one that connects two rooms)","cn":"连通门"}}]},"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"沟通;联系;交流","en":"If you communicate with someone, you share or exchange information with them, for example by speaking, writing, or using equipment. You can also say that two people communicate .","ex":{"en":"My natural mother has never communicated with me","cn":"我的亲生母亲从未和我联系过。"}},{"pos":"VERB 动词","cn":"传达;传递","en":"If you communicate information, a feeling, or an idea to someone, you let them know about it.","ex":{"en":"They successfully communicate their knowledge to others","cn":"他们成功地把知识传授给他人。"}},{"pos":"V-RECIP 相互动词","cn":"沟通，交流(情感、想法等)","en":"If one person communicates with another, they successfully make each other aware of their feelings and ideas. You can also say that two people communicate .","ex":{"en":"He was never good at communicating with the players","cn":"他不善于和队员们进行沟通。"}}]},"examples":[{"en":"They failed to communicate what was happening and why.","cn":"他们没说清楚当时发生了什么以及起因是什么。"},{"en":"The novel is about a family who can't communicate with each other.","cn":"这部小说写的是一个彼此无法沟通的家庭。"}]},"considerate":{"media":{"uk":"media/uk/xconsiderate__gb_1.mp3","us":"media/us/xconsiderate__us_1.mp3"},"oxford":{"phon":"kənˈsɪdərət","pos":"adjective","senses":[{"en":"always thinking of other people’s wishes and feelings; careful not to hurt or upset others","cn":"考虑周到的；为（他人）着想的；体谅的；体贴的","ex":{"en":"She is always polite and considerate towards her employees.","cn":"她对待雇员总是客客气气，关心体谅。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"替人着想的;体贴的","en":"Someone who is considerate pays attention to the needs, wishes, or feelings of other people.","ex":{"en":"I think he's the most charming, most considerate man I've ever known","cn":"我觉得他是我所认识的最有魅力并且最为体贴的男士。"}}]},"examples":[{"en":"She is always polite and considerate towards her employees.","cn":"她对待雇员总是客客气气，关心体谅。"},{"en":"It was very considerate of him to wait.","cn":"他一直在等候着，真是体贴。"}]},"connect":{"media":{"uk":"media/uk/xconnect__gb_1.mp3","us":"media/us/xconnect__us_1.mp3"},"oxford":{"phon":"kəˈnekt","pos":"verb","senses":[{"en":"to join together two or more things; to be joined together","cn":"（使）连接；联结","g":"[transitive, intransitive]","sc":"join","ex":{"en":"The towns are connected by train and bus services.","cn":"这些城镇由火车和公共汽车连接起来。"}},{"en":"to join something to the main supply of electricity, gas, water, etc. or to another piece of equipment","cn":"使…连接；接通","g":"[transitive]","sc":"electricity/gas/water","ex":{"en":"We're waiting for the broadband to be connected.","cn":"我们在等待宽带开通。"}},{"en":"to join a computer or a mobile device to the internet or to a computer network","cn":"（使计算机或移动设备）连接（到互联网或计算机网络）","g":"[intransitive, transitive]","sc":"internet","ex":{"en":"The device can be hooked up to a mobile phone to connect wirelessly.","cn":"该设备可与手机连接，实现无线联网。"}},{"en":"to notice or make a link between people, things, events, etc.","cn":"注意到…有关联；把…联系起来","g":"[transitive]","sc":"link","ex":{"en":"I was surprised to hear them mentioned together: I had never connected them before.","cn":"听到有人把他们牵扯在一起让我很吃惊；我以前从未把他们联起来想过。"}},{"en":"to arrive just before another one leaves so that passengers can change from one to the other","cn":"衔接；联运","g":"[intransitive]","sc":"of train/bus/plane","ex":{"en":"His flight to Amsterdam connects with an afternoon flight to New York.","cn":"他飞往阿姆斯特丹的航班与下午飞往纽约的一趟航班相衔接。"}},{"en":"to put somebody in contact by phone","cn":"为（某人）接通电话","g":"[transitive]","sc":"phone lines","ex":{"en":"After a long wait I was connected to customer services.","cn":"等了好久，我接通了客户服务部的电话。"}},{"en":"to form a good relationship with somebody so that you like and understand each other","cn":"（与某人）建立良好关系，沟通","g":"[intransitive]","sc":"form relationship","ex":{"en":"They met a couple of times but they didn't really connect.","cn":"尽管他们见了几次面，但仍未真正建立起良好的关系。"}},{"en":"to hit somebody/something","cn":"打，击（某人或某物）","g":"[intransitive]","lab":"informal","sc":"hit","ex":{"en":"The blow connected and she felt a surge of pain.","cn":"她遭到沉重的一击，感到一阵疼痛。"}}]},"collins":{"senses":[{"pos":"V-RECIP-ERG","cn":"(使)连接","en":"If something or someone connects one thing to another, or if one thing connects to another, the two things are joined together.","ex":{"en":"You can connect the machine to your hi-fi","cn":"你可以把机器连在高保真音响上。"}},{"pos":"VERB 动词","cn":"使连接，使接通(电源、水源等)","en":"If a piece of equipment or a place is connected to a source of power or water, it is joined to that source so that it has power or water.","ex":{"en":"These appliances should not be connected to power supplies","cn":"这些家用电器不应该接通电源。"}},{"pos":"VERB 动词","cn":"（接线员）给…接通电话","en":"If a telephone operator connects you, he or she enables you to speak to another person by telephone.","ex":{"en":"To call the police, an ambulance or the fire brigade dial 999 and the operator will connect you","cn":"呼叫警察、救护车或消防队，请拨打999，接线员会为您接通电话。"}},{"pos":"V-RECIP-ERG","cn":"(使)相连;(使)相通","en":"If two things or places connect or if something connects them, they are joined and people or things can pass between them.","ex":{"en":"...the long hallway that connects the rooms","cn":"连接各个房间的长过道"}},{"pos":"V-RECIP 相互动词","cn":"(火车或飞机等)联运，衔接","en":"If one train or plane, for example, connects with another, it arrives at a time which allows passengers to change to the other one in order to continue their journey.","ex":{"en":"...a train connecting with a ferry to Ireland","cn":"与开往爱尔兰的渡船联运的火车"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)换乘(飞机或火车)","en":"If you connect to a particular plane or train, or if another plane or train connects you to it, you change to that plane or train from another one in order to continue your journey.","ex":{"en":"...business travellers wanting to connect to a long-haul flight","cn":"想换乘长途航班的商务旅行者"}},{"pos":"VERB 动词","cn":"把…联系起来","en":"If you connect a person or thing with something, you realize that there is a link or relationship between them.","ex":{"en":"I hoped he would not connect me with that now-embarrassing review I'd written seven years earlier","cn":"我希望他不会把我和我7年前写的那篇现在看来令人难堪的评论联系起来。"}},{"pos":"VERB动词","cn":"使…有联系","en":"Something that connects a person or thing with something else shows or provides a link or relationship between them.","ex":{"en":"A search of Brady's house revealed nothing that could connect him with the robberies","cn":"对布雷迪住所的搜查没有发现任何能证明他与这些抢劫案有关的东西。"}},{"pos":"V-RECIP 相互动词","cn":"(与…)有同感，产生共鸣","en":"If you connect with someone, you feel a sense of agreement and familiarity with them because you have the same kind of ideas.","ex":{"en":"If you stand on stage and share your view of the world, people will connect with you.","cn":"如果你站在舞台上，分享自己对世界的看法，人们会与你产生共鸣的。"}},{"pos":"","cn":"","en":"相关词组：connect up"}]},"examples":[{"en":"I was surprised to hear them mentioned together: I had never connected them before.","cn":"听到有人把他们牵扯在一起让我很吃惊；我以前从未把他们联起来想过。"},{"en":"His flight to Amsterdam connects with an afternoon flight to New York.","cn":"他飞往阿姆斯特丹的班机与下午飞往纽约的一趟航班衔接。"}]},"confuses":{"lemma":"confuse"},"cod":{"media":{"uk":"media/uk/cod__gb_1.mp3","us":"media/us/cod__us_1.mp3"},"oxford":{"phon":"kɒd","pos":"noun","senses":[{"en":"a large sea fish that is white inside and used for food","cn":"鳕鱼","ex":{"en":"fishing for cod","cn":"捕鳕鱼"}},{"en":"not real or what somebody claims it is","cn":"假的；伪的；不真实的","ex":{"en":"a cod American accent","cn":"假装的美国口音"},"pos":"adjective"},{"en":"cash on delivery or (in American English) collect on delivery (payment for goods will be made when the goods are delivered)","cn":"货到付款；交货付现","pos":"abbreviation"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"鳕鱼","en":"Cod are a type of large edible fish.","ex":{"en":"A Catalan speciality is to serve salt cod cold.","cn":"冷盘咸鳕鱼是加泰罗尼亚的一道特色菜。"}},{"pos":"ADJ 形容词","cn":"假的;仿真的;骗人的","en":"You use cod to describe something which is not genuine and which is intended to deceive or amuse people by looking or sounding like the real thing.","ex":{"en":"...a cod documentary on what animals think of living in a zoo.","cn":"讲述动物如何看待动物园生活的搞笑伪纪录片"}}]},"examples":[{"en":"a cod American accent","cn":"假装的美国口音"},{"en":"cod fillets","cn":"鳕鱼鱼片"}]},"conflicted":{"media":{"uk":"media/uk/xconflicted__gb_1.mp3","us":"media/us/xconflicted__us_1.mp3"},"oxford":{"phon":"kənˈflɪktɪd","pos":"adjective","senses":[{"en":"confused about what to do or choose because you have strong but very different feelings","cn":"心里矛盾的；内心冲突的"}]},"examples":[{"en":"Many mothers today feel conflicted about working outside the home.","cn":"如今许多做母亲的对要不要出去上班心里很矛盾。"}],"base":"conflict"},"contributions":{"lemma":"contribution","media":{"uk":"media/uk/xcontribution__gb_1.mp3","us":"media/us/xcontribution__us_1.mp3"}},"collect":{"media":{"uk":"media/uk/collect__gb_1.mp3","us":"media/us/collect__us_1.mp3"},"oxford":{"phon":"kəˈlekt","pos":"adverb","senses":[{"en":"using a system in which a phone call is paid for by the person who receives it","cn":"由受话人付费的","ex":{"en":"to call somebody collect","cn":"给某人打对方付费电话"}},{"en":"to bring things together from different people or places","cn":"收集；采集","g":"[transitive]","sc":"bring together","ex":{"en":"to collect data/evidence/information","cn":"收集资料／证据／信息"},"pos":"verb"},{"en":"to buy or find things of a particular type and keep them as a hobby","cn":"收藏；搜集；收集","g":"[transitive]","sc":"as hobby","ex":{"en":"to collect stamps/postcards/coins","cn":"集邮；收藏明信片；收藏硬币"},"pos":"verb"},{"en":"to gradually increase in amount in a place; to gradually obtain more and more of something in a place","cn":"聚积；积聚；积累","g":"[intransitive, transitive]","sc":"increase in amount","ex":{"en":"In spite of their efforts a large pool of liquid continued to collect.","cn":"尽管他们付出了努力，仍然有一大滩液体积聚起来。"},"pos":"verb"},{"en":"to go somewhere in order to take somebody/something away","cn":"领取；收走；接走","g":"[transitive]","lab":"British English","sc":"take away","ex":{"en":"What day do they collect the rubbish/garbage?","cn":"他们哪天收运垃圾？"},"pos":"verb"},{"en":"to ask people to give you money for a particular purpose","cn":"募捐；募集","g":"[intransitive, transitive]","sc":"money","ex":{"en":"I've been out collecting, knocking on peoples doors and asking them for money.","cn":"我一直在外面收集，敲人们的门，向他们要钱。"},"pos":"verb"},{"en":"to obtain the money, etc. that somebody owes, for example by going to their house to get it","cn":"收（欠款）；（上门）收（账）","g":"[transitive]","sc":"money","ex":{"en":"to collect rent/debts/tax","cn":"收租金；讨债；征税"},"pos":"verb"},{"en":"to receive something; to win something","cn":"收到；赢得；获得","g":"[transitive, intransitive]","sc":"receive/win","ex":{"en":"She collected £25 000 in compensation.","cn":"她得到了 25 000 英镑赔偿金。"},"pos":"verb"},{"en":"to come together in one place to form a larger group","cn":"聚集；集合；汇集","g":"[intransitive]","sc":"of people","ex":{"en":"A crowd began to collect in front of the embassy.","cn":"人群开始聚集在大使馆的前面。"},"pos":"verb"},{"en":"paid for by the person who receives the call","cn":"由受话人付费的","ex":{"en":"to make a collect call","cn":"打对方付费电话"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"收集;采集","en":"If you collect a number of things, you bring them together from several places or from several people.","ex":{"en":"Two young girls were collecting firewood","cn":"两个小女孩正在拾柴火。"}},{"pos":"VERB 动词","cn":"搜集;收藏","en":"If you collect things, such as stamps or books, as a hobby, you get a large number of them over a period of time because they interest you.","ex":{"en":"I used to collect stamps","cn":"我曾经集过邮。"}},{"pos":"VERB 动词","cn":"接走;领取;收取","en":"When you collect someone or something, you go and get them from the place where they are waiting for you or have been left for you.","ex":{"en":"David always collects Alistair from school on Wednesdays","cn":"戴维总是星期三去学校接阿利斯泰尔。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)聚积;(使)积存","en":"If a substance collects somewhere, or if something collects it, it keeps arriving over a period of time and is held in that place or thing.","ex":{"en":"Methane gas does collect in the mines around here.","cn":"周围的矿井里的确有沼气聚积。"}},{"pos":"VERB 动词","cn":"积聚(光、能或热)","en":"If something collects light, energy, or heat, it attracts it.","ex":{"en":"Like a telescope it has a curved mirror to collect the sunlight.","cn":"和望远镜一样，它有一个曲面镜可以积聚阳光。"}},{"pos":"VERB 动词","cn":"(为慈善事业或礼品)筹款，集资;募捐","en":"If you collect for a charity or for a present for someone, you ask people to give you money for it.","ex":{"en":"Are you collecting for charity?","cn":"你是在为慈善事业筹款吗？"}},{"pos":"VERB 动词","cn":"尽力镇静下来;整理(思绪)","en":"If you collect yourself or collect your thoughts, you make an effort to calm yourself or prepare yourself mentally.","ex":{"en":"She paused for a moment to collect herself","cn":"她停了一会儿，让自己镇定下来。"}},{"pos":"ADJ 形容词","cn":"受话人付费的","en":"A collect call is a telephone call that is paid for by the person receiving it, not the person making it.","ex":{"en":"She received a collect phone call from Alaska.","cn":"她接到一个从阿拉斯加打来的付费电话。"}},{"pos":"","cn":"","en":"相关词组：collect up"}]},"examples":[{"en":"She collected £25 000 in compensation.","cn":"她得到了 25 000 英镑赔偿金。"},{"en":"We collected over £300 for the appeal.","cn":"我们为募捐筹集了 300 多英镑。"}]},"consequent":{"oxford":{"phon":"ˈkɒnsɪkwənt","pos":"adjective","senses":[{"en":"happening as a result of something","cn":"随之发生的；作为结果的","ex":{"en":"the lowering of taxes and the consequent increase in spending","cn":"税收降低与随之引起的消费增长"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"因之而起的;作为结果的","en":"Consequent means happening as a direct result of an event or situation.","ex":{"en":"The warming of the Earth and the consequent climatic changes affect us all","cn":"地球变暖以及随之而来的气候变化影响着我们所有人。"}}]},"media":{"uk":"media/uk/xconsequent__gb_1.mp3","us":"media/us/xconsequent__us_1.mp3"},"examples":[{"en":"the lowering of taxes and the consequent increase in spending","cn":"税收降低与随之引起的消费增长"},{"en":"the responsibilities consequent upon the arrival of a new child","cn":"新生儿出世后随之而来的职责"}]},"context":{"media":{"uk":"media/uk/xcontext__gb_1.mp3","us":"media/us/xcontext__us_1.mp3"},"oxford":{"phon":"ˈkɒntekst","pos":"noun","senses":[{"en":"the situation in which something happens and that helps you to understand it","cn":"（事情发生的）背景，环境，来龙去脉","ex":{"en":"Such databases are being used in a wide range of contexts.","cn":"这类数据库广泛应用于各种场合。"}},{"en":"the words that come just before and after a word, phrase or statement and help you to understand its meaning","cn":"上下文；语境","ex":{"en":"You should be able to guess the meaning of the word from the context.","cn":"你应该能从上下文猜出这个词的含义。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(想法、事件等的)背景，环境","en":"The context of an idea or event is the general situation that relates to it, and which helps it to be understood.","ex":{"en":"We are doing this work in the context of reforms in the economic, social and cultural spheres.","cn":"我们是在对经济、社会、文化诸领域进行改革的背景下从事这项工作的。"}},{"pos":"N-VAR 可变名词","cn":"上下文;语境","en":"The context of a word, sentence, or text consists of the words, sentences, or text before and after it which help to make its meaning clear.","ex":{"en":"Without a context, I would have assumed it was written by a man.","cn":"如果没有上下文，我会以为这是出自一名男子笔下。"}},{"pos":"PHRASE 短语","cn":"在上下文中;置于背景之下","en":"If something is seen in context or if it is put into context, it is considered together with all the factors that relate to it.","ex":{"en":"Taxation is not popular in principle, merely acceptable in context","cn":"征税基本上是不受欢迎的，在一定情境中才勉强为人接受。"}},{"pos":"PHRASE 短语","cn":"脱离上下文;断章取义地","en":"If a statement or remark is quoted out of context, the circumstances in which it was said are not correctly reported, so that it seems to mean something different from the meaning that was intended.","ex":{"en":"Thomas says that he has been taken out of context on the issue","cn":"托马斯说，在这个问题上他的话被断章取义了。"}}]},"examples":[{"en":"This speech needs to be set in the context of Britain in the 1960s.","cn":"这篇演说需要放到 20 世纪 60 年代的英国这一背景之下来看待。"},{"en":"His decision can only be understood in context.","cn":"只有了解来龙去脉才能明白他的决定。"}]},"commonly":{"media":{"uk":"media/uk/commonly__gb_1.mp3","us":"media/us/commonly__us_1.mp3"},"oxford":{"phon":"ˈkɒmənli","pos":"adverb","senses":[{"en":"usually; very often; by most people","cn":"通常；常常；大多数人地","ex":{"en":"Christopher is commonly known as Kit.","cn":"克里斯托弗通常被称为基特。"}}]},"examples":[{"en":"Christopher is commonly known as Kit.","cn":"克里斯托弗通常被称为基特。"},{"en":"This is one of the most commonly used methods.","cn":"这是最常采用的方法之一。"}]},"correlated":{"lemma":"correlate"},"copper":{"media":{"uk":"media/uk/copper__gb_1.mp3","us":"media/us/copper__us_1.mp3"},"oxford":{"phon":"ˈkɒpə(r)","pos":"noun","senses":[{"en":"a chemical element. Copper is a soft red-brown metal used for making electric wires, pipes and coins.","cn":"铜","g":"[uncountable]","ex":{"en":"a copper mine","cn":"铜矿"}},{"en":"brown coins that do not have much value","cn":"铜币","g":"[plural]","lab":"British English","ex":{"en":"I only paid a few coppers for it.","cn":"我只花了几个铜板买下这东西。"}},{"en":"a police officer","cn":"警察","g":"[countable]","lab":"British English, informal，，","ex":{"en":"Apparently, her dad's a copper.","cn":"显然，她的父亲是个铜人。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"铜","en":"Copper is reddish brown metal that is used to make things such as coins and electrical wires.","ex":{"en":"Chile is the world's largest producer of copper.","cn":"智利是世界上最大的产铜国。"}},{"pos":"ADJ 形容词","cn":"铜色的;紫铜色的;红棕色的","en":"Copper is sometimes used to describe things that are reddish-brown in colour.","ex":{"en":"His hair has reverted back to its original copper hue.","cn":"他的头发又变回原来的淡红棕色。"}},{"pos":"N-COUNT 可数名词","cn":"铜板;铜币","en":"Coppers are brown metal coins of low value."},{"pos":"N-COUNT 可数名词","cn":"警察","en":"A copper is a policeman or a policewoman.","ex":{"en":"...your friendly neighbourhood copper.","cn":"你们友善的社区警察"}}]},"examples":[{"en":"I only paid a few coppers for it.","cn":"我只花了几个铜板买下这东西。"},{"en":"copper-coloured hair","cn":"红棕色的头发"}]},"competitive":{"media":{"uk":"media/uk/competitive__gb_1.mp3","us":"media/us/competitive__us_1.mp3"},"oxford":{"phon":"kəmˈpetətɪv","pos":"adjective","senses":[{"en":"used to describe a situation in which people or organizations compete against each other","cn":"竞争的","ex":{"en":"competitive games/sports","cn":"竞技性的比赛／体育运动"}},{"en":"trying very hard to be better than others","cn":"努力竞争的；一心求胜的","ex":{"en":"You have to be highly competitive to do well in sport these days.","cn":"如今你必须有强烈的竞争意识才能在体育运动中取得好成绩。"}},{"en":"as good as or better than others","cn":"（与…）一样好的；（比…）更好的；有竞争力的","ex":{"en":"a shop selling clothes at competitive prices (= as low as any other shop)","cn":"在价格上有竞争力的服装店"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"竞争的；角逐的","en":"Competitive is used to describe situations or activities in which people or firms compete with each other.","ex":{"en":"Only by keeping down costs will America maintain its competitive advantage over other countries","cn":"只有通过控制成本，美国才能保持对其他国家的竞争优势。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"好竞争的;好胜的","en":"A competitive person is eager to be more successful than other people.","ex":{"en":"He has always been ambitious and fiercely competitive","cn":"他一直都雄心勃勃，而且极其好胜。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(商品或服务)具有竞争力的","en":"Goods or services that are at a competitive price or rate are likely to be bought, because they are less expensive than other goods of the same kind.","ex":{"en":"Only those homes offered for sale at competitive prices will secure interest from serious purchasers.","cn":"只有那些价格优惠的住房才会引起真想买房的人的兴趣。"}}]},"examples":[{"en":"You have to be highly competitive to do well in sport these days.","cn":"如今你必须有强烈的竞争意识才能在体育运动中取得好成绩。"},{"en":"We need to work harder to remain competitive with other companies.","cn":"我们需要更加努力工作以保持对其他公司具有竞争力。"}]},"coca":{"media":{"uk":"media/uk/coca__gb_1.mp3","us":"media/us/coca__us_1.mp3"},"oxford":{"phon":"ˈkəʊkə","pos":"noun","senses":[{"en":"a tropical bush whose leaves are used to make the drug cocaine","cn":"古柯（热带灌木，叶子用于制作可卡因）"}]}},"comb":{"oxford":{"phon":"kəʊm","pos":"noun","senses":[{"en":"a flat piece of plastic or metal with a row of thin teeth along one side, used for making your hair neat; a smaller version of this worn by women in their hair to hold it in place or as a decoration","cn":"梳子；篦子；压发梳","g":"[countable]","ex":{"en":"He just had time to wash his face and drag a comb through his hair before going out.","cn":"他只有时间洗了把脸，用梳子梳了梳头发，然后就出去了。"}},{"en":"the act of using a comb on your hair","cn":"梳理（头发）","g":"[countable, usually singular]","ex":{"en":"Your hair needs a good comb.","cn":"你的头发得好好梳理一下。"}},{"en":"a structure of cells with six sides, made by bees for holding their honey and their eggs","cn":"蜂巢","g":"[countable, uncountable]"},{"en":"the soft red part on the top of the head of a male chicken","cn":"（公鸡的）鸡冠","g":"[countable]"},{"en":"to pull a comb through your hair in order to make it neat","cn":"梳，梳理（头发）","g":"[transitive]","ex":{"en":"Don't forget to comb your hair!","cn":"别忘了梳一下头发！"},"pos":"verb"},{"en":"to search something carefully in order to find somebody/something","cn":"仔细搜索；搜寻","g":"[transitive, intransitive]","ex":{"en":"I combed the shops looking for something to wear.","cn":"我跑遍商店寻找可穿的东西。"},"pos":"verb"},{"en":"to make wool, cotton, etc. clean and straight using a special comb so that it can be used to make cloth","cn":"梳理（羊毛、棉花等）","g":"[transitive]","lab":"specialist","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"梳子","en":"A comb is a flat piece of plastic or metal with narrow pointed teeth along one side, which you use to tidy your hair."},{"pos":"VERB 动词","cn":"梳理(头发)","en":"When you comb your hair, you tidy it using a comb.","ex":{"en":"Salvatore combed his hair carefully","cn":"萨尔瓦托认真地梳了梳头。"}},{"pos":"VERB 动词","cn":"在…四处搜寻","en":"If you comb a place, you search everywhere in it in order to find someone or something.","ex":{"en":"Officers combed the woods for the murder weapon","cn":"警察在树林里四处搜寻凶器。"}},{"pos":"VERB 动词","cn":"在(信息)中仔细搜寻","en":"If you comb through information, you look at it very carefully in order to find something.","ex":{"en":"Eight policemen then spent two years combing through the evidence.","cn":"之后8位警察花了两年时间搜寻证据。"}}]},"media":{"img":["media/ldoce/img/comb.jpg","media/pic/toiletries_bathroom_comp.jpg"],"uk":"media/uk/comb__gb_1.mp3","us":"media/us/comb__us_1.mp3"},"examples":[{"en":"The police combed the area for clues.","cn":"警察彻底搜索了那个地区以寻找线索。"},{"en":"They combed through the files for evidence of fraud.","cn":"他们查遍档案搜寻欺诈的证据。"}]},"control":{"media":{"uk":"media/uk/xcontrol__gb_1.mp3","us":"media/us/xcontrol__us_1.mp3"},"oxford":{"phon":"kənˈtrəʊl","pos":"noun","senses":[{"en":"the power to make decisions about how a country, an area, an organization, etc. is run","cn":"（对国家、地区、机构等的）管理权，控制权，支配权","g":"[uncountable]","sc":"power","ex":{"en":"The party expects to gain control of the council in the next election.","cn":"该党期待在下次选举中获得对地方议会的控制权。"}},{"en":"the ability to make somebody/something do what you want","cn":"控制（或操纵）能力","g":"[uncountable]","sc":"power","ex":{"en":"The teacher had no control over the children.","cn":"那位老师管不住学生。"}},{"en":"the act of limiting or managing something; a method of doing this","cn":"限制；约束；管理；管制","g":"[uncountable, countable]","sc":"limiting/managing","ex":{"en":"traffic control","cn":"交通管制"}},{"en":"the switches and buttons, etc. that you use to operate a machine or a vehicle","cn":"（机器或车辆的）操纵装置，开关，按钮","g":"[countable, usually plural]","sc":"in machine","ex":{"en":"the controls of an aircraft","cn":"飞机的操纵装置"}},{"en":"a person, thing or group used as a standard of comparison for checking the results of a scientific experiment; an experiment whose result is known, used for checking working methods","cn":"对照标准；（检验工作方法的）参照实验","g":"[countable]","lab":"specialist","sc":"in experiment","ex":{"en":"The study showed that women with the disease have had fewer children than the controls.","cn":"研究表明，患有这种疾病的女性比对照组女性生育的孩子少。"}},{"en":"a place where orders are given or where checks are made; the people who work in this place","cn":"指挥（或检查、控制）站；指挥（或检查、控制）人员","g":"[singular]","sc":"place","ex":{"en":"We went through passport control and into the departure lounge.","cn":"我们通过护照检查站进入了候机大厅。"}},{"en":"(on a computer keyboard) a key that you press when you want to perform a particular operation","cn":"（键盘上的）控制键","g":"[uncountable]","sc":"on computer"},{"en":"to have power over a person, company, country, etc. so that you are able to decide what they must do or how it is run","cn":"指挥；控制；掌管；支配","sc":"have power","ex":{"en":"By the age of 21 he controlled the company.","cn":"他 21 岁就掌管了公司。"},"pos":"verb"},{"en":"to limit something or make it happen in a particular way","cn":"限制；限定","sc":"limit/manage","ex":{"en":"It is essential for businesses to control costs.","cn":"企业控制成本很关键。"},"pos":"verb"},{"en":"to stop something from spreading or getting worse","cn":"阻止蔓延（或恶化）","sc":"limit/manage","ex":{"en":"Firefighters are still trying to control the blaze.","cn":"消防队员仍在尽力控制火势的蔓延。"},"pos":"verb"},{"en":"to make something such as a machine or system work in the way that you want it to","cn":"操纵，控制（机器或系统等）","sc":"machine","ex":{"en":"This knob controls the volume.","cn":"此旋钮调节音量。"},"pos":"verb"},{"en":"to manage to make yourself remain calm, even though you are upset or angry","cn":"抑制；克制","sc":"stay calm","ex":{"en":"I was so angry I couldn't control myself.","cn":"我气得无法控制自己。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(对机构、地方、体系等的)控制权，支配权","en":"Control of an organization, place, or system is the power to make all the important decisions about the way that it is run.","ex":{"en":"The restructuring involves Mr Ronson giving up control of the company","cn":"这次改组涉及龙森先生放弃对公司的控制权。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"控制(能力);支配(能力)","en":"If you have control of something or someone, you are able to make them do what you want them to do.","ex":{"en":"He lost control of his car","cn":"他的汽车失控了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"克制;控制力","en":"If you show control, you prevent yourself behaving in an angry or emotional way.","ex":{"en":"He had a terrible temper, and sometimes he would completely lose control","cn":"他的脾气很坏，有时会完全失控。"}},{"pos":"VERB 动词","cn":"控制;掌管;管理;统治","en":"The people who control an organization or place have the power to take all the important decisions about the way that it is run.","ex":{"en":"He now controls the largest retail development empire in southern California","cn":"他现在掌管着加州南部最大的零售发展企业。"}},{"pos":"VERB 动词","cn":"控制，操纵(设备、过程、系统等)","en":"To control a piece of equipment, process, or system means to make it work in the way that you want it to work.","ex":{"en":"...a computerised system to control the gates","cn":"控制大门的计算机系统"}},{"pos":"VERB 动词","cn":"管制，限定，控制(价格、工资、活动等)","en":"When a government controls prices, wages, or the activity of a particular group, it uses its power to restrict them.","ex":{"en":"The federal government tried to control rising health-care costs.","cn":"联邦政府试图控制日益高涨的医疗保健费用。"}},{"pos":"VERB 动词","cn":"控制;自制;克制","en":"If you control yourself, or if you control your feelings, voice, or expression, you make yourself behave calmly even though you are feeling angry, excited, or upset.","ex":{"en":"Jo was advised to learn to control herself","cn":"乔得到的建议是要学会控制自己的情绪。"}},{"pos":"VERB 动词","cn":"控制，抑制(危险)","en":"To control something dangerous means to prevent it from becoming worse or from spreading.","ex":{"en":"...the need to control environmental pollution","cn":"控制环境污染的需要"}},{"pos":"N-COUNT 可数名词","cn":"控制按钮;控制装置;操纵装置","en":"A control is a device such as a switch or lever which you use in order to operate a machine or other piece of equipment.","ex":{"en":"I practised operating the controls.","cn":"我练习操作这些控制装置。"}},{"pos":"N-VAR 可变名词","cn":"控制措施;管制措施","en":"Controls are the methods that a government uses to restrict increases, for example in prices, wages, or weapons.","ex":{"en":"Critics question whether price controls would do any good","cn":"评论家们质疑物价管制措施是否会有用。"}},{"pos":"N-VAR 可变名词","cn":"检查站","en":"Control is used to refer to a place where your documents or luggage are officially checked when you enter a foreign country.","ex":{"en":"He went straight through Passport Control without incident.","cn":"他很顺利地通过了护照检查处。"}},{"pos":"PHRASE 短语","cn":"失去控制;不受控制","en":"If something is out of control, no-one has any power over it.","ex":{"en":"The fire is burning out of control","cn":"熊熊燃烧的大火正在失去控制。"}},{"pos":"PHRASE 短语","cn":"被控制住;得到控制","en":"If something harmful is under control, it is being dealt with successfully and is unlikely to cause any more harm.","ex":{"en":"The situation is under control","cn":"局势已经得到控制。"}}]},"examples":[{"en":"Owing to circumstances beyond our control , the flight to Rome has been cancelled.","cn":"由于出现了我们无法控制的情况，飞往罗马的航班已被取消。"},{"en":"There has been some violence after the match, but the police are now in control of the situation.","cn":"比赛后发生了一些暴力事件，但是现在警方已控制了局势。"}]},"commander":{"media":{"uk":"media/uk/commander__gb_1.mp3","us":"media/us/commander__us_1.mp3"},"oxford":{"phon":"kəˈmɑːndə(r)","pos":"noun","senses":[{"en":"a person who is in charge of something, especially an officer in charge of a particular group of soldiers or a military operation","cn":"负责人；（尤指）司令官，指挥官","ex":{"en":"military/allied/field/flight commanders","cn":"军事／盟军／战地／飞行指挥官"}},{"en":"an officer of fairly high rank in the British or American navy","cn":"（英国或美国）海军中校"},{"en":"(in England) a London police officer of high rank","cn":"（英格兰）伦敦高级警官"}]},"collins":{"senses":[{"pos":"N-COUNT; N-TITLE; N-VOC可数名词；头衔名词；称呼名词","cn":"指挥官;长官","en":"A commander is an officer in charge of a military operation or organization.","ex":{"en":"The commander and some of the men had been released.","cn":"指挥官和一些士兵已经获释。"}},{"pos":"N-COUNT; N-TITLE; N-VOC可数名词；头衔名词；称呼名词","cn":"(英国或美国)海军中校","en":"A commander is an officer in the Royal Navy or the U.S. Navy."}]},"examples":[{"en":"military/allied/field/flight commanders","cn":"军事/盟军/战地/飞行指挥官"},{"en":"the commander of the expedition","cn":"探险队队长"}]},"conventional":{"oxford":{"phon":"kənˈvenʃənl","pos":"adjective","senses":[{"en":"tending to follow what is done or considered acceptable by society in general; normal and ordinary, and perhaps not very interesting","cn":"依照惯例的；遵循习俗的；墨守成规的；普通平凡的","lab":"often disapproving","ex":{"en":"conventional behaviour/morality","cn":"循规蹈矩的行为；传统的道德规范"}},{"en":"following what is traditional or the way something has been done for a long time","cn":"传统的；习惯的","g":"[usually before noun]","ex":{"en":"conventional methods/approaches","cn":"传统方法"}},{"en":"using the usual scientific methods of Western medicine such as artificial drugs and operations","cn":"传统西医的；常规的","g":"[usually before noun]","ex":{"en":"conventional medicine","cn":"传统医学"}},{"en":"not nuclear","cn":"非核的；常规的","g":"[usually before noun]","ex":{"en":"conventional forces/weapons","cn":"常规部队／武器"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（行为、观念等）传统的，符合习俗的","en":"Someone who is conventional has behaviour or opinions that are ordinary and normal.","ex":{"en":"...a respectable married woman with conventional opinions.","cn":"一位观念传统、受人尊敬的已婚女性"}},{"pos":"ADJ 形容词","cn":"（方法或产品）通常的，传统的","en":"A conventional method or product is one that is usually used or that has been in use for a long time.","ex":{"en":"It is simpler and quicker to use than conventional methods.","cn":"这比通常的做法更简单、更快捷。"}},{"pos":"ADJ 形容词","cn":"(武器、战争等)常规的，非核的","en":"Conventional weapons and wars do not involve nuclear explosives.","ex":{"en":"We must reduce the danger of war by controlling nuclear, chemical and conventional arms.","cn":"我们必须通过控制核武器、化学武器和常规武器的数量来减少战争的危险。"}},{"pos":"","cn":"","en":"conventional wisdom→see: ;"}]},"media":{"uk":"media/uk/xconventional__gb_1.mp3","us":"media/us/xconventional__us_1.mp3"},"examples":[{"en":"It's not a hotel, in the conventional sense, but rather a whole village turned into a hotel.","cn":"这不是一家传统意义上的旅馆，而是由整个村庄变身而成的度假村。"},{"en":"You can use a microwave or cook it in a conventional oven.","cn":"你可以用微波炉或传统烤箱烹制。"}]},"consistently":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to continue to be the same and not change","cn":""},{"en":"an amount, temperature, rate etc that is constant stays the same and does not change","cn":""}]},"examples":[{"en":"She’s the team’s most consistent player.","cn":"","src":"ld"},{"en":"We need to be consistent in our approach.","cn":"","src":"ld"}],"media":{"uk":"media/uk/xconsistently__gb_1.mp3","us":"media/us/xconsistently__us_1.mp3"},"oxford":{"phon":"kənˈsɪstəntli","pos":"adverb","senses":[{"en":"always the same","cn":"一贯地；始终如一地","lab":"approving","ex":{"en":"Her work has been of a consistently high standard.","cn":"她的工作一贯是高水准的。"}},{"en":"in a way that does not change and continues for a period of time","cn":"连续地；持续地","ex":{"en":"We have argued consistently for a change in the law.","cn":"我们一直力主更改法律。"}},{"en":"in a way that has different parts that all agree with each other","cn":"相互连贯地；一致地","ex":{"en":"Studies have not consistently demonstrated any benefit.","cn":"研究没有一致显示出有益处。"}}]}},"concept":{"media":{"uk":"media/uk/xconcept__gb_1.mp3","us":"media/us/xconcept__us_1.mp3"},"oxford":{"phon":"ˈkɒnsept","pos":"noun","senses":[{"en":"an idea or a principle that is connected with something abstract","cn":"概念；观念","ex":{"en":"the concept of social class","cn":"社会等级的概念"}},{"en":"an idea for something new","cn":"新想法；新理念","ex":{"en":"a novel/innovative concept","cn":"新颖／创新的理念"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"概念;观念","en":"A concept is an idea or abstract principle.","ex":{"en":"She added that the concept of arranged marriages is misunderstood in the west.","cn":"她补充说，西方人对包办婚姻的概念有些误解。"}}]},"examples":[{"en":"concepts such as ‘civilization’ and ‘government’","cn":"诸如“文明”和“政府”的概念"},{"en":"He can't grasp the basic concepts of mathematics.","cn":"他无法掌握数学的基本概念。"}]},"cord":{"media":{"img":["media/pic/cord_comp.jpg","media/thumb/cord.jpg"],"uk":"media/uk/cord__gb_1.mp3","us":"media/us/cord__us_1.mp3"},"oxford":{"phon":"kɔːd","pos":"noun","senses":[{"en":"strong thick string or thin rope; a piece of this","cn":"（结实的）粗线，细绳；一根粗线（或细绳）","g":"[uncountable, countable]","ex":{"en":"a piece/length of cord","cn":"一根／一段粗线"}},{"en":"a piece of wire that is covered with plastic, used for carrying electricity to a piece of equipment","cn":"软线；花线；皮线","g":"[countable, uncountable]","lab":"especially North American English","ex":{"en":"an electrical cord","cn":"电线"}},{"en":"a part of the body that is like a piece of cord","cn":"脐带；（人体的）带，索","g":"[countable]","ex":{"en":"The baby was still attached to its mother by the cord.","cn":"婴儿与母体仍有脐带相连。"}},{"en":"a type of strong soft cotton cloth with a pattern of raised straight lines on it, used for making clothes","cn":"灯芯绒","g":"[uncountable]","ex":{"en":"a cord jacket","cn":"灯芯绒夹克"}},{"en":"trousers made of corduroy","cn":"灯芯绒裤子","g":"[plural]","lab":"old-fashioned","ex":{"en":"a pair of cords","cn":"一条灯芯绒裤子"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"粗线;细绳","en":"Cord is strong, thick string.","ex":{"en":"The door had been tied shut with a length of nylon cord.","cn":"门用一段尼龙绳拴住了。"}},{"pos":"N-VAR 可变名词","cn":"电源线","en":"Cord is wire covered in rubber or plastic which connects electrical equipment to an electricity supply.","ex":{"en":"...electrical cord","cn":"电源线"}},{"pos":"N-PLURAL 复数名词","cn":"灯芯绒裤子","en":"Cords are trousers made of corduroy .","ex":{"en":"He had bare feet, a T-shirt and cords on.","cn":"他光着脚，穿着T恤衫和灯芯绒裤子。"}},{"pos":"ADJ 形容词","cn":"灯芯绒的","en":"Cord means made of corduroy .","ex":{"en":"...a pair of cord trousers.","cn":"一条灯芯绒裤子"}}]},"examples":[{"en":"a silk bag tied with a gold cord","cn":"用金线捆扎的丝绸包"},{"en":"picture cord (= used for hanging pictures)","cn":"画的挂绳"}]},"combine":{"media":{"uk":"media/uk/combine__gb_1.mp3","us":"media/us/combine__us_1.mp3"},"oxford":{"phon":"kəmˈbaɪn","pos":"verb","senses":[{"en":"to come together to form a single thing or group; to join two or more things or groups together to form a single one","cn":"（使）结合，组合，联合，混合","g":"[intransitive, transitive]","ex":{"en":"Hydrogen and oxygen combine to form water.","cn":"氢与氧化合成水。"}},{"en":"to have two or more different features or characteristics; to put two or more different things, features or qualities together","cn":"兼有；兼备；使融合（或并存）","g":"[transitive]","ex":{"en":"We are still looking for someone who combines all the necessary qualities.","cn":"我们仍在寻觅兼具所有必要才能的人选。"}},{"en":"to do two or more things at the same time","cn":"同时做（两件或以上的事）；兼做；兼办","g":"[transitive]","ex":{"en":"The trip will combine business with pleasure.","cn":"此次旅行将把公干和游玩结合起来。"}},{"en":"to come together in order to work or act together; to put two things or groups together so that they work or act together","cn":"合并；协力","g":"[intransitive, transitive]","ex":{"en":"They combined against a common enemy.","cn":"他们联手对付共同的敌人。"}},{"en":"a large farm machine that both cuts a crop and also separates the grains from the rest of the plant","cn":"联合收割机","lab":"British English also","pos":"noun"},{"en":"a group of people or organizations acting together in business","cn":"集团；联合企业","pos":"noun"}]},"collins":{"senses":[{"pos":"V-RECIP-ERG","cn":"(使)结合;(使)组合;(使)综合","en":"If you combine two or more things or if they combine, they exist together.","ex":{"en":"The Church has something to say on how to combine freedom with responsibility","cn":"教会想就如何把自由与责任结合起来发表一下意见。"}},{"pos":"V-RECIP-ERG","cn":"(使)合并;(使)综合","en":"If you combine two or more things or if they combine, they join together to make a single thing.","ex":{"en":"David Jacobs was given the job of combining the data from these 19 studies into one giant study","cn":"分给戴维·雅格布斯的任务是把这19项研究得出的数据加以综合，使之成为一项大型研究。"}},{"pos":"VERB 动词","cn":"兼有;兼备","en":"If someone or something combines two qualities or features, they have both those qualities or features at the same time.","ex":{"en":"Their system seems to combine the two ideals of strong government and proportional representation.","cn":"他们的体制似乎是强有力的政府和比例代表制的完美结合。"}},{"pos":"VERB 动词","cn":"兼做;同时做(两件事)","en":"If someone combines two activities, they do them both at the same time.","ex":{"en":"It is possible to combine a career with being a mother","cn":"兼顾职业女性和母亲这两个角色是可能的。"}},{"pos":"V-RECIP-ERG","cn":"(使)合并;(使)联合","en":"If two or more groups or organizations combine or if someone combines them, they join to form a single group or organization.","ex":{"en":"...an announcement by Steetley and Tarmac of a joint venture that would combine their operations","cn":"斯蒂特利公司和泰玛士集团发表的整合其生产经营成立一个合资企业的声明"}},{"pos":"N-COUNT 可数名词","cn":"联盟;联合体","en":"A combine is a group of people or organizations that are working or acting together.","ex":{"en":"...Veba, an energy-and-chemicals combine that is Germany's fourth-biggest company.","cn":"能源化工联合企业费巴是德国的第四大企业"}}]},"examples":[{"en":"They have successfully combined the old with the new in this room.","cn":"他们在这个房间里成功地把古老和现代的风格融为一体。"},{"en":"It took the combined efforts of both the press and the public to bring about a change in the law.","cn":"这项法律的变更来自媒体和公众的通力合作。"}]},"comforter":{"media":{"uk":"media/uk/comforter__gb_1.mp3","us":"media/us/comforter__us_1.mp3"},"oxford":{"phon":"ˈkʌmfətə(r)","pos":"noun","senses":[{"en":"a person or thing that makes you feel calmer or less worried","cn":"令人感到安慰（或慰藉）的人（或事物）","ex":{"en":"She was hugging a pillow as a comforter.","cn":"她抱着一个枕头作为被子。"}},{"en":"a type of thick cover for a bed","cn":"加衬芯床罩","lab":"North American English"},{"en":"a large cloth bag that is filled with feathers or other soft material and that you have on top of you in bed to keep yourself warm","cn":"羽绒被","lab":"North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"安慰者;给人安慰的事物","en":"A comforter is a person or thing that comforts you.","ex":{"en":"He became Vivien Leigh's devoted friend and comforter.","cn":"他成了费雯丽忠诚的朋友和给她安慰的人。"}},{"pos":"N-COUNT 可数名词","cn":"羽绒被","en":"A comforter is a large cover filled with feathers or similar material which you put over yourself in bed instead of a sheet and blankets."}]}},"connectivity":{"media":{"uk":"media/uk/xconnectivity__gb_1.mp3","us":"media/us/xconnectivity__us_1.mp3"},"oxford":{"phon":"kəˌnekˈtɪvəti","pos":"noun","senses":[{"en":"the ability of systems, platforms and applications to be connected to each other","cn":"（系统、平台和应用软件之间的）连接能力","lab":"computing","ex":{"en":"wireless/broadband/Bluetooth connectivity","cn":"无线／宽带／蓝牙连接"}},{"en":"the state of being connected; the degree to which two things are connected","cn":"连通性；连接（度）；联结（度）","ex":{"en":"There is a need to improve road, rail and air connectivity to the rest of the country.","cn":"有必要改善与国内其他地区的公路、铁路和空中交通。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"连接性；连通性","en":"Connectivity is the ability of a computing device to connect to other computers or to the Internet.","ex":{"en":"...a DVD video and CD player with Internet connectivity.","cn":"能连接因特网的DVD和CD播放机"}}]},"examples":[{"en":"ISDN connectivity allows computers to communicate over a network.","cn":"综合业务数字网连接实现了计算机网络通讯。"},{"en":"a growing demand for high-speed connectivity","cn":"对高速连接功能日益增长的需求"}]},"cope":{"media":{"uk":"media/uk/cope__gb_1.mp3","us":"media/us/cope__us_1.mp3"},"oxford":{"phon":"kəʊp","pos":"verb","senses":[{"en":"to deal successfully with something difficult","cn":"（成功地）对付，处理","ex":{"en":"I got to the stage where I wasn't coping any more.","cn":"到了这个阶段，我已经无法应付了。"}},{"en":"a long loose piece of clothing worn by priests on special occasions","cn":"（圣职人员在特定礼仪中穿的）斗篷式祭衣，大圆衣","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(成功地)处理，应付，对付","en":"If you cope with a problem or task, you deal with it successfully.","ex":{"en":"It was amazing how my mother coped with bringing up three children on less than three pounds a week","cn":"我妈妈用每周不到3英镑的钱抚养大了3个孩子，简直太不可思议了。"}},{"pos":"VERB 动词","cn":"应付，忍受(不愉快的局面)","en":"If you have to cope with an unpleasant situation, you have to accept it or bear it.","ex":{"en":"Never before has the industry had to cope with war and recession at the same time","cn":"这个行业以前从未有过必须同时应付战争和萧条的经历。"}},{"pos":"VERB 动词","cn":"(机器、系统等)能够处理，应付","en":"If a machine or a system can cope with something, it is large enough or complex enough to deal with it satisfactorily.","ex":{"en":"New blades have been designed to cope with the effects of dead insects","cn":"新的桨片设计使其可以应付昆虫尸体带来的影响。"}},{"pos":"N-COUNT 可数名词","cn":"(基督教牧师在特殊仪式中所穿的)长袍，法衣","en":"A cope is a long sleeveless piece of clothing worn by some Christian priests on special occasions."}]},"examples":[{"en":"He wasn't able to cope with the stresses and strains of the job.","cn":"对付这项工作的紧张与压力，他无能为力。"},{"en":"I got to the stage where I wasn't coping any more.","cn":"到了这个阶段，我已经无法应付了。"}]},"composition":{"oxford":{"phon":"ˌkɒmpəˈzɪʃn","pos":"noun","senses":[{"en":"the different parts that something is made of; the way in which the different parts are organized","cn":"成分；构成；组合方式","g":"[uncountable]","ex":{"en":"the chemical composition of the soil","cn":"土壤的化学成分"}},{"en":"a short text that is written as a school exercise; a short essay","cn":"作文；小论文","g":"[countable]","ex":{"en":"a composition on the effects of crime","cn":"论述犯罪影响的文章"}},{"en":"a piece of music or art, or a poem","cn":"（音乐、艺术、诗歌的）作品","g":"[countable]","lab":"formal","ex":{"en":"one of Beethoven’s finest compositions","cn":"贝多芬最优美的音乐作品之一"}},{"en":"the act of composing something, especially a piece of music; the art of writing music","cn":"（音乐）创作；作曲","g":"[uncountable]","ex":{"en":"pieces performed in the order of their composition","cn":"按作曲顺序表演的作品"}},{"en":"the arrangement of people or objects in a painting or photograph","cn":"（绘画、摄影的）构图","g":"[uncountable]","lab":"art"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"组成;构成;组合方式","en":"When you talk about the composition of something, you are referring to the way in which its various parts are put together and arranged.","ex":{"en":"Television has transformed the size and social composition of the audience at great sporting occasions","cn":"电视改变了重大体育赛事观众的规模和其社会阶层构成结构。"}},{"pos":"N-COUNT 可数名词","cn":"(作曲家、画家等的)作品","en":"The compositions of a composer, painter, or other artist are the works of art that they have produced.","ex":{"en":"Mozart's compositions are undoubtedly amongst the world's greatest.","cn":"莫扎特的作品无疑位居世界上最伟大的作品之列。"}},{"pos":"N-COUNT 可数名词","cn":"(学生的)作文","en":"A composition is a piece of written work that children write at school."},{"pos":"N-UNCOUNT 不可数名词","cn":"艺术创作技巧","en":"Composition is the technique or skill involved in creating a work of art.","ex":{"en":"He taught the piano, organ and composition","cn":"他教授钢琴、管风琴和作曲。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(音乐、诗歌等的)创作，作曲","en":"Composition is the act of composing something such as a piece of music or a poem.","ex":{"en":"These plays are arranged in their order of composition.","cn":"这些剧作是按照其创作的先后顺序安排的。"}}]},"media":{"uk":"media/uk/composition__gb_1.mp3","us":"media/us/composition__us_1.mp3"},"examples":[{"en":"pieces performed in the order of their composition","cn":"按作曲顺序表演的作品"},{"en":"the chemical composition of the soil","cn":"土壤的化学成分"}]},"companionship":{"oxford":{"phon":"kəmˈpænjənʃɪp","pos":"noun","senses":[{"en":"the pleasant feeling that you have when you have a friendly relationship with somebody and are not alone","cn":"友情；交谊；友谊","ex":{"en":"They meet at the club for companionship and advice.","cn":"他们在俱乐部相会是为了联谊和寻求建议。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"友谊;交往;伴侣关系","en":"Companionship is having someone you know and like with you, rather than being on your own.","ex":{"en":"I depended on his companionship and on his judgment","cn":"我信赖他的友情，也相信他的判断。"}}]},"media":{"uk":"media/uk/companionship__gb_1.mp3","us":"media/us/companionship__us_1.mp3"},"examples":[{"en":"They meet at the club for companionship and advice.","cn":"他们在俱乐部相会是为了联谊和寻求建议。"},{"en":"She had only her cat for companionship.","cn":"她只有猫儿作伴。"}]},"compelling":{"media":{"uk":"media/uk/compelling__gb_1.mp3","us":"media/us/compelling__us_1.mp3"},"oxford":{"phon":"kəmˈpelɪŋ","pos":"adjective","senses":[{"en":"that makes you pay attention to it because it is so interesting and exciting","cn":"引人入胜的；扣人心弦的","ex":{"en":"Her latest book makes compelling reading.","cn":"她新出的书读起来扣人心弦。"}},{"en":"so strong that you cannot resist it","cn":"非常强烈的；不可抗拒的","ex":{"en":"a compelling need/desire","cn":"非常强烈的需要／欲望"}},{"en":"that makes you think it is true","cn":"令人信服的","ex":{"en":"There is no compelling reason to believe him.","cn":"没有令人信服的理由让人相信他。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人信服的;有说服力的","en":"A compelling argument or reason is one that convinces you that something is true or that something should be done.","ex":{"en":"Factual and forensic evidence makes a suicide verdict the most compelling answer to the mystery of his death","cn":"事实证据和法庭证据使得自杀成为解开他死因之谜的最令人信服的答案。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非常有趣的;很有吸引力的","en":"If you describe something such as a film or book, or someone's appearance, as compelling, you mean you want to keep looking at it or reading it because you find it so interesting.","ex":{"en":"...a frighteningly violent yet compelling film","cn":"有可怕的暴力镜头但却引人入胜的电影"}}]},"examples":[{"en":"There is no compelling reason to believe him.","cn":"没有令人信服的理由让人相信他。"},{"en":"Her latest book makes compelling reading.","cn":"她新出的书读起来扣人心弦。"}]},"colours":{"lemma":"colour"},"comprehension":{"media":{"uk":"media/uk/comprehension__gb_1.mp3","us":"media/us/comprehension__us_1.mp3"},"oxford":{"phon":"ˌkɒmprɪˈhenʃn","pos":"noun","senses":[{"en":"the ability to understand","cn":"理解力；领悟能力","g":"[uncountable]","ex":{"en":"speech and comprehension","cn":"说话能力和理解力"}},{"en":"an exercise that trains students to understand a language","cn":"（语言学习中的）理解练习（或训练）","g":"[uncountable, countable]","ex":{"en":"We did a listening comprehension.","cn":"我们做了一次听力练习。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"理解力；领悟力","en":"Comprehension is the ability to understand something.","ex":{"en":"This was utterly beyond her comprehension.","cn":"这让她完全无法理解。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"充分了解;完全明白","en":"Comprehension is full knowledge and understanding of the meaning of something.","ex":{"en":"They turned to one another with the same expression of dawning comprehension, surprise, and relief.","cn":"他们相互看了看，脸上都是同一种表情，恍然大悟、惊讶，而又如释重负。"}},{"pos":"N-VAR 可变名词","cn":"(听力或阅读)理解测试","en":"When pupils do comprehension, they do an exercise to find out how well they understand a piece of spoken or written language.","ex":{"en":"The course also features creative writing exercises and listening comprehension.","cn":"这门课程也包括写作练习和听力理解。"}}]},"examples":[{"en":"His behaviour was completely beyond comprehension (= impossible to understand).","cn":"他的举止完全令人费解。"},{"en":"She had no comprehension of what was involved.","cn":"她不明白所涉及的事情。"}]},"competent":{"oxford":{"phon":"ˈkɒmpɪtənt","pos":"adjective","senses":[{"en":"having enough skill or knowledge to do something well or to the necessary standard","cn":"足以胜任的；有能力的；称职的","ex":{"en":"He's very competent in his work.","cn":"他工作十分称职。"}},{"en":"of a good standard but not very good","cn":"合格的；不错的；尚好的","ex":{"en":"Ron was a competent player—more than that, he was good!","cn":"罗恩是个合格的选手，岂止合格，他很棒！"}},{"en":"having the power to decide something","cn":"有决定权的","ex":{"en":"The case was referred to a competent authority.","cn":"事情已交给有关当局处理。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"能胜任的;称职的","en":"Someone who is competent is efficient and effective.","ex":{"en":"He was a loyal, distinguished and very competent civil servant.","cn":"他是一位敬业、优秀而且非常称职的公务员。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有…能力的;能干的","en":"If you are competent to do something, you have the skills, abilities, or experience necessary to do it well.","ex":{"en":"Most adults do not feel competent to deal with a medical emergency involving a child.","cn":"大部分成年人不懂得如何对儿童实施急救。"}}]},"media":{"uk":"media/uk/competent__gb_1.mp3","us":"media/us/competent__us_1.mp3"},"examples":[{"en":"Make sure the firm is competent to carry out the work.","cn":"要确保这家公司有能力完成这项工作。"},{"en":"The case was referred to a competent authority.","cn":"事情已交给有关当局处理。"}]},"commute":{"oxford":{"phon":"kəˈmjuːt","pos":"verb","senses":[{"en":"to travel regularly by bus, train, car, etc. between your place of work and your home","cn":"（乘公共汽车、火车、汽车等）上下班往返，经常往返（于两地）","g":"[intransitive, transitive]","ex":{"en":"She commutes from Oxford to London every day.","cn":"她每天上下班往返于牛津与伦敦之间。"}},{"en":"to replace one punishment with another that is less severe","cn":"减刑","g":"[transitive]","lab":"law","ex":{"en":"The death sentence was commuted to life imprisonment.","cn":"死刑被改判为无期徒刑。"}},{"en":"to exchange one form of payment, for something else","cn":"代偿","g":"[transitive]","lab":"finance","ex":{"en":"The capital invested will be commuted to a loan.","cn":"投资资本将转换为贷款。"}},{"en":"the journey that a person makes when they commute to work","cn":"上下班路程","ex":{"en":"a two-hour commute into downtown Washington","cn":"去华盛顿中心区两小时的上下班路程"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(经很远的路程)上下班往返;通勤","en":"If you commute, you travel a long distance every day between your home and your place of work.","ex":{"en":"Mike commutes to London every day","cn":"迈克每天都去伦敦上班。"}},{"pos":"N-COUNT 可数名词","cn":"上下班路程","en":"A commute is the journey that you make when you commute.","ex":{"en":"The average Los Angeles commute is over 60 miles a day.","cn":"洛杉矶的平均上下班路程为每天60多英里。"}},{"pos":"VERB 动词","cn":"减轻(刑罚)","en":"If a death sentence or prison sentence is commuted to a less serious punishment, it is changed to that punishment.","ex":{"en":"His death sentence was commuted to life imprisonment","cn":"他的死刑被减为无期徒刑。"}}]},"media":{"uk":"media/uk/commute__gb_1.mp3","us":"media/us/commute__us_1.mp3"},"examples":[{"en":"I live within commuting distance of Dublin.","cn":"我住在离都柏林上下班可乘公交车往返的地方。"},{"en":"People are prepared to commute long distances if they are desperate for work.","cn":"极需得到工作的人会愿意长途乘车往返上下班。"}]},"comparison":{"media":{"uk":"media/uk/comparison__gb_1.mp3","us":"media/us/comparison__us_1.mp3"},"oxford":{"phon":"kəmˈpærɪsn","pos":"noun","senses":[{"en":"the process of comparing two or more people or things","cn":"比较","g":"[uncountable]","ex":{"en":"For Durkheim, comparison was the most important method of analysis in sociology.","cn":"对于涂尔干来说，比较是社会学最重要的分析方法。"}},{"en":"an occasion when two or more people or things are compared","cn":"对比；相比","g":"[countable]","ex":{"en":"The films are too different for a fair comparison.","cn":"这些电影差异太大，无法进行公平比较。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"比较;对照","en":"When you make a comparison, you consider two or more things and discover the differences between them.","ex":{"en":"...a comparison of the British and German economies","cn":"英国经济与德国经济的比较"}},{"pos":"N-COUNT 可数名词","cn":"比拟;比喻","en":"When you make a comparison, you say that one thing is like another in some way.","ex":{"en":"It is demonstrably an unfair comparison","cn":"这样打比方显然不公平。"}},{"pos":"PHRASE 短语","cn":"与…相比;与…比较而言","en":"If you say, for example, that something is large or small in comparison with ,in comparison to, or by comparison with something else, you mean that it is larger or smaller than the other thing.","ex":{"en":"Is the human heart weak in comparison with the other organs?","cn":"与其他器官相比，人的心脏是不是很脆弱？"}},{"pos":"PHRASE 短语","cn":"不能相提并论;不能相比","en":"If you say there is no comparison between one thing and another, you mean that you think the first thing is much better than the second, or very different from it.","ex":{"en":"There is no comparison between the knowledge and skill of such a player and the ordinary casual participant.","cn":"临时的普通参赛者无法与这种选手所掌握的知识和技巧相提并论。"}},{"pos":"PHRASE 短语","cn":"比得上;可(与…)相媲美","en":"If someone or something stands or bears comparison with another person or thing, they are as good, or almost as good.","ex":{"en":"...the only post-war French intellectual who stands comparison with De Tocqueville.","cn":"法国战后唯一能与德·托克维尔相媲美的知识分子"}}]},"examples":[{"en":"The tallest buildings in London are small in comparison with New York's skyscrapers.","cn":"伦敦最高的建筑物与纽约的摩天大厦一比就相形见绌。"},{"en":"The education system bears/stands no comparison with (= is not as good as) that in many Asian countries.","cn":"这种教育制度比不上许多亚洲国家的教育制度。"}]},"cognition":{"media":{"uk":"media/uk/cognition__gb_1.mp3","us":"media/us/cognition__us_1.mp3"},"oxford":{"phon":"kɒɡˈnɪʃn","pos":"noun","senses":[{"en":"the process by which knowledge and understanding is developed in the mind","cn":"认知；感知；认识","ex":{"en":"child studies centring on theories of cognition","cn":"以认知理论为中心的儿童研究"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"认识(过程);认知","en":"Cognition is the mental process involved in knowing, learning, and understanding things.","ex":{"en":"...processes of perception and cognition.","cn":"感觉和认知过程"}}]},"examples":[{"en":"the regions of the brain that are responsible for memory and cognition","cn":"大脑主管记忆与认知的区域"}]},"convey":{"media":{"uk":"media/uk/xconvey__gb_1.mp3","us":"media/us/xconvey__us_1.mp3"},"oxford":{"phon":"kənˈveɪ","pos":"verb","senses":[{"en":"to make ideas, feelings, etc. known to somebody","cn":"表达，传递（思想、感情等）","lab":"formal","ex":{"en":"Colours like red convey a sense of energy and strength.","cn":"红色之类的颜色可给人以充满活力与力量的感觉。"}},{"en":"to take, carry or transport somebody/something from one place to another","cn":"传送；运送；输送","lab":"formal","ex":{"en":"Pipes convey hot water from the boiler to the radiators.","cn":"管道把热水从锅炉输送到暖气片。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"传达;表达;传递","en":"To convey information or feelings means to cause them to be known or understood by someone.","ex":{"en":"When I returned home, I tried to convey the wonder of this machine to my husband","cn":"回到家后，我竭力地想把这台机器的精妙之处描述给丈夫听。"}},{"pos":"VERB 动词","cn":"运输;运送;输送","en":"To convey someone or something to a place means to carry or transport them there.","ex":{"en":"The railway company extended a branch line to Brightlingsea to convey fish direct to Billingsgate.","cn":"铁路公司修建了一条通往布赖特灵西的支线，以便直接将鱼运送到比林斯门。"}}]},"examples":[{"en":"Colours like red convey a sense of energy and strength.","cn":"红色之类的颜色可给人以充满活力与力量的感觉。"},{"en":"He tried desperately to convey how urgent the situation was.","cn":"他不顾一切地试图说明情况是多么紧急。"}]},"cool":{"media":{"uk":"media/uk/cool__gb_1.mp3","us":"media/us/cool__us_1.mp3"},"oxford":{"phon":"kuːl","pos":"adjective","senses":[{"en":"fairly cold; not hot or warm","cn":"凉的；凉爽的；凉快的","sc":"fairly cold","ex":{"en":"cool air/water","cn":"凉爽的空气；凉水"}},{"en":"helping you keep cool","cn":"凉快的","sc":"clothes","ex":{"en":"Wear light, cool clothing but try to avoid shorts.","cn":"穿轻便凉快的衣服，但尽量不要穿短裤。"}},{"en":"making you feel pleasantly cool","cn":"使人感到凉爽的；冷色的","sc":"colours","ex":{"en":"a room painted in cool greens and blues","cn":"涂成令人感到凉爽的绿色和蓝色的房间"}},{"en":"used to show that you admire or approve of somebody/something because they are/it is fashionable, attractive and often different","cn":"（因时髦、漂亮且与众不同而）令人钦佩的，绝妙的，酷的","lab":"informal","sc":"approving","ex":{"en":"Doesn't she look cool in those sunglasses?","cn":"她戴着墨镜看起来不是很酷吗？"}},{"en":"used to describe something that you like or enjoy","cn":"美妙的；很棒的","lab":"informal","sc":"approving","ex":{"en":"We had such a cool time with Ed and his friends.","cn":"我们和埃德还有他的朋友们度过了一段快乐的时光。"}},{"en":"used to show that you approve of something or agree to a suggestion","cn":"（表示满意或赞同）妙极的，酷的","lab":"informal","sc":"approving","ex":{"en":"We're meeting Jake for lunch and we can go on the yacht in the afternoon.’ ‘Cool!’","cn":"“我们和杰克一起吃午饭，下午乘游艇玩去。”“棒极了！”"}},{"en":"calm; not excited, angry or emotional","cn":"冷静的；镇静的；平静的","sc":"calm","ex":{"en":"Keep cool!","cn":"保持冷静！"}},{"en":"not friendly, interested or enthusiastic","cn":"不友好的；冷淡的；冷漠的","sc":"not friendly/enthusiastic","ex":{"en":"They gave the prime minister a cool reception.","cn":"他们对首相态度冷淡。"}},{"en":"calm and confident in a way that lacks respect for other people, but makes people admire you even if they don't approve","cn":"孤傲冷漠的；满不在乎的","lab":"informal","sc":"confident","ex":{"en":"She just took his keys and walked out with them, cool as you please.","cn":"她拿了他的钥匙就跟他们走了，你看多有个性。"}},{"en":"used about a sum of money to emphasize how large it is","cn":"（强调金额之大）整整的，足足的","g":"[only before noun]","lab":"informal","sc":"money","ex":{"en":"The car cost a cool thirty thousand.","cn":"那辆车花了整整三万。"}},{"en":"to become cool or cooler; to make somebody/something become cool or cooler","cn":"（使）变凉，冷却","g":"[intransitive, transitive]","sc":"become colder","ex":{"en":"Glass contracts as it cools.","cn":"玻璃遇冷收缩。"},"pos":"verb"},{"en":"to become calmer, less excited or less enthusiastic","cn":"冷静下来；镇静下来；冷淡下来","g":"[intransitive]","sc":"become calmer","ex":{"en":"I think we should wait until tempers have cooled.","cn":"我认为我们应该等到怒火平息下来再说。"},"pos":"verb"},{"en":"cool air or a cool place","cn":"凉气；凉快的地方","ex":{"en":"the cool of the evening","cn":"夜晚的凉爽"},"pos":"noun"},{"en":"the quality of being fashionable, attractive or impressive","cn":"时髦；迷人；魅力","g":"[uncountable]","lab":"informal","ex":{"en":"all the cool of high fashion","cn":"高档时装的十足魅力"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"凉的;凉爽的;温度不高的","en":"Something that is cool has a temperature which is low but not very low.","ex":{"en":"I felt a current of cool air","cn":"我感觉到一阵凉风。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"凉快的;凉爽的","en":"If it is cool, or if a place is cool, the temperature of the air is low but not very low.","ex":{"en":"Thank goodness it's cool in here","cn":"谢天谢地，这里面挺凉快。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(衣服等)让人感觉凉爽的","en":"Clothing that is cool is made of thin material so that you do not become too hot in hot weather.","ex":{"en":"In warm weather, you should wear clothing that is cool and comfortable.","cn":"在热天里，应该穿凉快舒适的衣服。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(颜色)冷的;冷色调的","en":"Cool colours are light colours which give an impression of coolness.","ex":{"en":"Choose a cool colour such as cream","cn":"选择冷色系，比如乳白色。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)变凉;(使)冷却;(使)降温","en":"When something cools or when you cool it, it becomes lower in temperature.","ex":{"en":"Drain the meat and allow it to cool","cn":"把肉沥干水，让它冷却。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(感觉、感情等)变淡，减弱，减少","en":"When a feeling or emotion cools, or when you cool it, it becomes less powerful.","ex":{"en":"Within a few minutes tempers had cooled","cn":"几分钟之内，火气就变小了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人、行为等)冷静的，沉着的，泰然自若的","en":"If you say that a person or their behaviour is cool, you mean that they are calm and unemotional, especially in a difficult situation.","ex":{"en":"He was marvelously cool again, smiling as if nothing had happened","cn":"他又变得出奇地冷静，微笑着，好像什么也没有发生过。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人、行为等)冷漠的，冷淡的，不友善的","en":"If you say that a person or their behaviour is cool, you mean that they are unfriendly or not enthusiastic.","ex":{"en":"I didn't like him at all. I thought he was cool, aloof, and arrogant","cn":"我一点也不喜欢他，觉得他冷漠、孤僻而且傲慢。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人、行为等)酷的，时尚的，吸引人的","en":"If you say that a person or their behaviour is cool, you mean that they are fashionable and attractive.","ex":{"en":"He was trying to be really cool and trendy.","cn":"他竭力想扮酷，赶时髦。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坦然接受的;心平气和的","en":"If you say that someone is cool about something, you mean that they accept it and are not angry or upset about it.","ex":{"en":"Bev was really cool about it all.","cn":"贝芙对这一切都表现得相当平静。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非常好的;特别棒的;绝妙的","en":"If you say that something is cool, you think it is very good.","ex":{"en":"Kathleen gave me a really cool dress.","cn":"凯瑟琳给了我一件非常漂亮的衣服。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(尤指轻易得到的数额)巨大的，整整","en":"You can use cool to emphasize that an amount or figure is very large, especially when it has been obtained easily.","ex":{"en":"Columbia recently resigned the band for a cool $30 million.","cn":"哥伦比亚唱片公司最近以3,000万美元的高价再次签下这个乐队。"}},{"pos":"PHRASE 短语","cn":"冷静下来;别激动","en":"If you tell someone to cool it, you want them to stop being angry and aggressive and to behave more calmly.","ex":{"en":"Can't you guys just cool it?","cn":"你们能不能冷静一下？"}},{"pos":"PHRASE 短语","cn":"保持冷静/失去冷静","en":"If you keep your cool in a difficult situation, you manage to remain calm. If you lose your cool, you get angry or upset.","ex":{"en":"She kept her cool and managed to get herself out of the ordeal","cn":"她保持着冷静与克制，努力使自己走出了这次痛苦的经历。"}},{"pos":"PHRASE 短语","cn":"假装冷静;故作镇定","en":"If you play it cool, you deliberately behave in a calm, unemotional way because you do not want people to know you are enthusiastic or angry about something.","ex":{"en":"It's ridiculous to play it cool if someone you're mad about is mad about you too.","cn":"如果让你生气的人也在生你的气，而你还要假装冷静，那就太可笑了。"}},{"pos":"","cn":"","en":"as cool as a cucumber→see: ; to cool your heels→see: ;"},{"pos":"","cn":"","en":"相关词组：cool down cool off"}]},"examples":[{"en":"‘We're meeting Jake for lunch and we can go on the yacht in the afternoon.’ ‘Cool!’ “","cn":"我们和杰克一起吃午饭，下午乘游艇玩去。” “棒极了！”"},{"en":"I was surprised that she got the job, but I'm cool with it (= it's not a problem for me).","cn":"我对于她得到这份工作感到惊讶，但觉得还可以接受。"}]},"computer":{"media":{"img":["media/pic/computing_equipment_comp.jpg","media/thumb/pc.jpg"],"uk":"media/uk/computer__gb_1.mp3","us":"media/us/computer__us_1.mp3"},"oxford":{"phon":"kəmˈpjuːtə(r)","pos":"noun","senses":[{"en":"an electronic machine that can store, organize and find information, do processes with numbers and other data, and control other machines","cn":"计算机；电脑","ex":{"en":"a home computer","cn":"家用计算机"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"计算机;电脑","en":"A computer is an electronic machine that can store and deal with large amounts of information.","ex":{"en":"The data are then fed into a computer","cn":"数据随后被输入电脑。"}}]},"examples":[{"en":"Our sales information is processed by computer.","cn":"我们的销售信息是用计算机处理的。"},{"en":"computer software/hardware/graphics","cn":"计算机软件/硬件/制图"}]},"concert":{"oxford":{"phon":"ˈkɒnsət","pos":"noun","senses":[{"en":"a public performance of music","cn":"音乐会；演奏会","lab":"British English","ex":{"en":"to attend/go to a concert","cn":"去听音乐会"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"音乐会","en":"A concert is a performance of music.","ex":{"en":"...a short concert of piano music","cn":"一场短暂的钢琴音乐会"}},{"pos":"PHRASE 短语","cn":"现场演出","en":"If a musician or group of musicians appears in concert, they are giving a live performance.","ex":{"en":"I want people to remember Elvis in concert.","cn":"我希望大家记住现场演唱会上的猫王。"}},{"pos":"PHRASE 短语","cn":"合作;同心协力","en":"If a number of people do something in concert, they do it together.","ex":{"en":"He wants to act in concert with other nations.","cn":"他想和其他国家采取一致行动。"}}]},"media":{"uk":"media/uk/xconcert__gb_1.mp3","us":"media/us/xconcert__us_1.mp3"},"examples":[{"en":"They're in concert at Wembley Arena.","cn":"他们在文布利运动场举行音乐会。"},{"en":"a concert of music by Bach","cn":"巴赫作品音乐会"}]},"cost-cutting":{"oxford":{"phon":"ˈkɒst kʌtɪŋ","pos":"noun","senses":[{"en":"the reduction of the amount of money spent on something, especially because of financial difficulty","cn":"（尤指因财政困难的）成本削减","ex":{"en":"Deliveries of mail could be delayed because of cost-cutting.","cn":"由于削减成本，邮件的递送可能会延迟。"}}]},"media":{"uk":"media/uk/cost_cutting_1_gb_1.mp3","us":"media/us/cost_cutting_1_us_1.mp3"},"examples":[{"en":"Deliveries of mail could be delayed because of cost-cutting.","cn":"由于削减成本，邮件的递送可能会延迟。"},{"en":"a cost-cutting exercise/measure/programme","cn":"成本削减的实施/措施/计划"}]},"corruption":{"oxford":{"phon":"kəˈrʌpʃn","pos":"noun","senses":[{"en":"dishonest or illegal behaviour, especially of people in authority","cn":"腐败；贪污；贿赂；受贿","g":"[uncountable]","lab":"British English","ex":{"en":"allegations of bribery and corruption","cn":"对贿赂与贪污的指控"}},{"en":"the act or effect of making somebody change from moral to immoral standards of behaviour","cn":"堕落；腐蚀","g":"[uncountable]","ex":{"en":"He claimed that sex and violence on TV led to the corruption of young people.","cn":"他断言电视中所宣扬的色情与暴力诱使青少年堕落。"}},{"en":"the form of a word or phrase that has become changed from its original form in some way; the process by which a word or phrase changes form in this way","cn":"（单词或短语的）变体，变体过程","g":"[countable, usually singular, uncountable]","ex":{"en":"The word ‘holiday’ is a corruption of ‘holy day’.","cn":"单词 holiday 是 holy day 的变体。"}},{"en":"the effect when data is changed by accident in a computer system due to hardware or software failure","cn":"（数据的）损坏","g":"[uncountable]","lab":"computing","ex":{"en":"A failure of a hard disk can cause unrecoverable data corruption.","cn":"硬盘故障可能会导致不可恢复的数据损坏。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"腐败;贪污;受贿","en":"Corruption is dishonesty and illegal behaviour by people in positions of authority or power.","ex":{"en":"The President faces 54 charges of corruption and tax evasion","cn":"总统面临54项腐败和逃税的指控。"}},{"pos":"N-COUNT 可数名词","cn":"(单词的)变体","en":"In linguistics, a corruption is a word that is derived from an earlier word, but which has become changed in some way.","ex":{"en":"'Morris' is an English corruption of 'Moorish', meaning North African.","cn":"Morris 在英语中是 Moorish 的变体，意思是“北非的”。"}}]},"media":{"uk":"media/uk/corruption__gb_1.mp3","us":"media/us/corruption__us_1.mp3"},"examples":[{"en":"The word ‘holiday’ is a corruption of ‘holy day’.","cn":"单词 holiday 是 holy day 的变体。"},{"en":"He claimed that sex and violence on TV led to the corruption of young people.","cn":"他断言电视中所宣扬的色情与暴力诱使青少年堕落。"}]},"consensus":{"media":{"uk":"media/uk/xconsensus__gb_1.mp3","us":"media/us/xconsensus__us_1.mp3"},"oxford":{"phon":"kənˈsensəs","pos":"noun","senses":[{"en":"an opinion that all members of a group agree with","cn":"一致的意见；共识","ex":{"en":"She is skilled at achieving consensus on sensitive issues.","cn":"她擅长就敏感问题进行斡旋，从而达成共识。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"一致看法;共识","en":"A consensus is general agreement among a group of people.","ex":{"en":"The consensus amongst the world's scientists is that the world is likely to warm up over the next few decades","cn":"世界各国科学家一致认为在未来几十年里地球有可能变暖。"}}]},"examples":[{"en":"She is skilled at achieving consensus on sensitive issues.","cn":"她擅长就敏感问题进行斡旋，从而达成共识。"},{"en":"There is a general consensus among teachers about the need for greater security in schools.","cn":"教师们对必须加强学校的保安有普遍的共识。"}]},"counterpane":{"media":{"uk":"media/uk/counterpane__gb_1.mp3","us":"media/us/counterpane__us_1.mp3"},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"床单;床罩","en":"A counterpane is a decorative cover on a bed."}]},"oxford":{"phon":"ˈkaʊntəpeɪn","pos":"noun","senses":[{"en":"an attractive cover put on top of all the sheets and covers on a bed","cn":"床罩"}]}},"considering":{"oxford":{"phon":"kənˈsɪdərɪŋ","pos":"preposition, conjunction, adverb","senses":[{"en":"used to show that you are thinking about a particular fact, and are influenced by it, when you make a statement about something","cn":"考虑到；就…而言；鉴于","lab":"informal","ex":{"en":"She's very active, considering her age.","cn":"就她的年龄来说，她是十分活跃的。"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"考虑到;鉴于","en":"You use considering to indicate that you are thinking about a particular fact when making a judgment or giving an opinion.","ex":{"en":"He must be hoping, but considering the situation in June he may hoping for too much too soon","cn":"他一定心存希望，但是考虑到6月份的情形，他可能期望得过多过快了。"}},{"pos":"CONJ-SUBORD 连词","cn":"考虑到(后接从句)","en":"You use considering that to indicate that you are thinking about a particular fact when making a judgment or giving an opinion.","ex":{"en":"Considering that you are no longer involved with this man, your response is a little extreme.","cn":"考虑到你已经与这个男人划清了界限，你的反应有一点儿过头。"}},{"pos":"ADV 副词","cn":"通盘考虑;从各方面考虑","en":"When you are giving an opinion or making a judgment, you can use considering to suggest that you have thought about all the circumstances, and often that something has succeeded in spite of these circumstances.","ex":{"en":"I think you're pretty safe, considering.","cn":"总的说来，我认为你的处境很安全。"}}]},"media":{"uk":"media/uk/xconsidering__gb_1.mp3","us":"media/us/xconsidering__us_1.mp3"},"examples":[{"en":"( informal ) You've done very well, considering (= in the difficult circumstances).","cn":"考虑到处境的艰难，你已经做得相当不错了。"},{"en":"Considering he's only just started, he knows quite a lot about it.","cn":"鉴于他才刚刚开始，他懂得的已经不少了。"}],"base":"consider"},"counterpart":{"media":{"uk":"media/uk/counterpart__gb_1.mp3","us":"media/us/counterpart__us_1.mp3"},"oxford":{"phon":"ˈkaʊntəpɑːt","pos":"noun","senses":[{"en":"a person or thing that has the same position or function as somebody/something else in a different place or situation","cn":"职位（或作用）相当的人；对应的事物","ex":{"en":"The Foreign Minister held talks with his Chinese counterpart.","cn":"外交部长与中国的同级官员举行了会谈。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"职能(或地位)相当的人;对应的事物","en":"Someone's or something's counterpart is another person or thing that has a similar function or position in a different place.","ex":{"en":"The Foreign Secretary telephoned his Italian counterpart to protest.","cn":"外交部长致电意大利外长表示抗议。"}}]},"examples":[{"en":"The women's shoe, like its male counterpart, is specifically designed for the serious tennis player.","cn":"像同类的男款鞋一样，这款女鞋是专为认真从事网球运动的人设计的。"},{"en":"The Foreign Minister held talks with his Chinese counterpart.","cn":"外交部长与中国外交部长举行了会谈。"}]},"commanding":{"oxford":{"phon":"kəˈmɑːndɪŋ","pos":"adjective","senses":[{"en":"in a position of authority that allows you to give formal orders","cn":"指挥的；统帅的","g":"[only before noun]","ex":{"en":"Who is your commanding officer?","cn":"谁是你们的指挥官？"}},{"en":"if you are in a commanding position or have a commanding lead, you are likely to win a race or competition","cn":"（速度竞赛或比赛）居领先位置的，遥遥领先的","g":"[usually before noun]"},{"en":"powerful and making people admire and obey you","cn":"权威的；威严的","g":"[usually before noun]","ex":{"en":"a commanding figure/presence/voice","cn":"威严的人物／气派／说话声"}},{"en":"if a building is in a commanding position or has a commanding view, you can see the area around very well from it","cn":"居高临下的；视野宽阔的","g":"[only before noun]","ex":{"en":"The castle occupies a commanding position on a hill.","cn":"城堡占据着山上居高临下的位置。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"指挥的;统帅的","en":"If you are in a commanding position or situation, you are in a strong or powerful position or situation.","ex":{"en":"Right now you're in a more commanding position than you have been for ages","cn":"现在你的权力超过了多年以来任何时候。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"威严的;权威的","en":"If you describe someone as commanding, you mean that they are powerful and confident.","ex":{"en":"Lovett was a tall, commanding man with a waxed gray mustache","cn":"洛维特是个威严的高个男人，蓄着灰白的八字胡。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"居高临下的;视野开阔的","en":"If a building has a commanding position, it is high up and has good views of the surrounding area.","ex":{"en":"The size of the castle and its commanding position still impress the visitor today","cn":"城堡很大，加上其居高临下的位置，至今仍让参观者赞叹不已。"}}]},"media":{"uk":"media/uk/commanding__gb_1.mp3","us":"media/us/commanding__us_1.mp3"},"examples":[{"en":"The castle occupies a commanding position on a hill.","cn":"城堡占据着山上居高临下的位置。"},{"en":"Who is your commanding officer?","cn":"谁是你们的指挥官？"}],"base":"command"},"conference":{"media":{"uk":"media/uk/xconference__gb_1.mp3","us":"media/us/xconference__us_1.mp3"},"oxford":{"phon":"ˈkɒnfərəns","pos":"noun","senses":[{"en":"a large official meeting, usually lasting for a few days, at which people with the same work or interests come together to discuss their views","cn":"（通常持续几天的大型正式）会议，研讨会","ex":{"en":"The hotel is used for exhibitions, conferences and social events.","cn":"这家旅馆用于举行展览、大型会议和社交活动。"}},{"en":"a meeting at which people have formal discussions","cn":"（正式）讨论会，商讨会","ex":{"en":"They agreed to convene a peace conference by mid-November.","cn":"他们同意在 11 月中旬召开和平会议。"}},{"en":"a group of sports teams that play against each other in a league","cn":"体育协会（或联合会）","lab":"especially North American English","ex":{"en":"Southeast Conference football champions","cn":"东南联盟美式足球冠军"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(常持续数天的)专题讨论会，研讨会","en":"A conference is a meeting, often lasting a few days, which is organized on a particular subject or to bring together people who have a common interest.","ex":{"en":"The President summoned all the state governors to a conference on education.","cn":"总统召集各州州长召开了一次教育研讨会。"}},{"pos":"N-COUNT 可数名词","cn":"会议;正式商谈","en":"A conference is a meeting at which formal discussions take place.","ex":{"en":"They sat down at the dinner table, as they always did, before the meal, for a conference","cn":"他们在餐桌旁坐下，和平常一样，吃饭之前要开个会。"}}]},"examples":[{"en":"She is attending a three-day conference on AIDS education.","cn":"她正在出席一个为期三天的有关艾滋病教育的会议。"},{"en":"The hotel is used for exhibitions, conferences and social events.","cn":"这家旅馆用于举行展览、大型会议和社交活动。"}]},"correcting":{"lemma":"correct","media":{"uk":"media/uk/correct__gb_1.mp3","us":"media/us/correct__us_1.mp3"}},"collaborative":{"media":{"uk":"media/uk/collaborative__gb_1.mp3","us":"media/us/collaborative__us_1.mp3"},"oxford":{"phon":"kəˈlæbərətɪv","pos":"adjective","senses":[{"en":"involving, or done by, several people or groups of people working together","cn":"合作的；协作的；协力的","ex":{"en":"collaborative projects/studies/research","cn":"合作项目／研究"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"合作的;协作的","en":"A collaborative piece of work is done by two or more people or groups working together.","ex":{"en":"...a collaborative research project","cn":"协作研究项目"}}]},"examples":[{"en":"a collaborative effort/venture","cn":"共同的努力；合作企业"},{"en":"collaborative projects/studies/research","cn":"合作项目/研究"}]},"commissioned":{"lemma":"commission","media":{"uk":"media/uk/commission__gb_1.mp3","us":"media/us/commission__us_1.mp3"}},"consciously":{"oxford":{"phon":"ˈkɒnʃəsli","pos":"adverb","senses":[{"en":"in a way that shows that you are aware of something or noticing something","cn":"有意识地：以某种方式表明您知道某事或注意到某事","ex":{"en":"Sound has more profound effects on us than we consciously realize.","cn":"声音对我们的影响比我们有意识地意识到的更深远。"}},{"en":"in a way that is deliberate or careful","cn":"有意识地：以故意或谨慎的方式","ex":{"en":"Consciously or unconsciously, you made a choice.","cn":"有意无意之中，你作出了选择。"}}]},"media":{"uk":"media/uk/xconsciously__gb_1.mp3","us":"media/us/xconsciously__us_1.mp3"},"examples":[{"en":"Consciously or unconsciously, you made a choice.","cn":"不管是有意还是无意，你已作出了选择。"},{"en":"She was probably not consciously aware of her true feelings.","cn":"她也许没有清醒地意识到自己真实的感情。"}]},"concern":{"media":{"uk":"media/uk/xconcern__gb_1.mp3","us":"media/us/xconcern__us_1.mp3"},"oxford":{"phon":"kənˈsɜːn","pos":"verb","senses":[{"en":"to affect somebody/something; to involve somebody/something","cn":"影响；涉及；牵涉","sc":"affect/involve","ex":{"en":"Don't interfere in what doesn't concern you.","cn":"不要管与自己无关的事。"}},{"en":"to be about something","cn":"涉及；论及；与…有关","sc":"be about","ex":{"en":"The story concerns the prince's efforts to rescue Pamina.","cn":"这故事讲的是王子奋力解救帕米娜。"}},{"en":"to worry somebody","cn":"让（某人）担忧","sc":"worry somebody","ex":{"en":"What concerns me is our lack of preparation for the change.","cn":"让我担心的是我们对事态的变化缺乏准备。"}},{"en":"to take an interest in something","cn":"（对…）感兴趣","sc":"take an interest","ex":{"en":"He didn't concern himself with the details.","cn":"他对细节不感兴趣。"}},{"en":"a feeling of worry, especially one that is shared by many people","cn":"（尤指许多人共同的）担心，忧虑","g":"[uncountable, countable]","sc":"worry","ex":{"en":"Villagers expressed concern about the level of traffic.","cn":"村民对交通流量表示担忧。"},"pos":"noun"},{"en":"a desire to protect and help somebody/something","cn":"关爱；关心","g":"[uncountable]","sc":"desire to protect","ex":{"en":"parents’ concern for their children","cn":"父母对子女的关爱"},"pos":"noun"},{"en":"something that is important to a person, an organization, etc.","cn":"（对人、组织等）重要的事情","g":"[countable]","sc":"something important","ex":{"en":"Our main concern is to ensure the safety of the children.","cn":"确保孩子安全是我们的头等大事。"},"pos":"noun"},{"en":"something that is your responsibility or that you have a right to know about","cn":"（某人）负责的事，有权知道的事","g":"[countable, usually singular]","lab":"formal","sc":"responsibility","ex":{"en":"This matter is their concern.","cn":"这件事由他们负责。"},"pos":"noun"},{"en":"a company or business","cn":"公司；企业","g":"[countable]","sc":"company","ex":{"en":"The scheme has been set up by a major publishing concern.","cn":"该计划是由一家主要出版公司设立的。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"忧虑;担心","en":"Concern is worry about a situation.","ex":{"en":"The group has expressed concern about reports of political violence in Africa","cn":"该团体对有关非洲政治暴力的报道表示关切。"}},{"pos":"VERB 动词","cn":"使担忧;使心烦","en":"If something concerns you, it worries you.","ex":{"en":"The growing number of people seeking refuge in Thailand is beginning to concern Western aid agencies","cn":"到泰国寻求庇护的人日益增多，这开始引起了西方援助机构的不安。"}},{"pos":"N-COUNT 可数名词","cn":"令人担忧的事实(或情况)","en":"A concern is a fact or situation that worries you.","ex":{"en":"His concern was that people would know that he was responsible","cn":"他担心大家会知道是他的责任。"}},{"pos":"N-VAR 可变名词","cn":"关心;关切","en":"Someone's concern with something is their feeling that it is important.","ex":{"en":"...a story that illustrates how dangerous excessive concern with safety can be.","cn":"一个说明过分关心安全问题会招致何等麻烦的故事"}},{"pos":"N-COUNT 可数名词","cn":"(对…)重要的事;关心的事","en":"Someone's concerns are the things that they consider to be important.","ex":{"en":"Feminism must address issues beyond the concerns of middle-class whites.","cn":"女权主义解决的问题不能仅仅局限于中产阶级白人妇女所关心的问题。"}},{"pos":"N-VAR 可变名词","cn":"关心;关怀;关爱","en":"Concern for someone is a feeling that you want them to be happy, safe, and well. If you do something out of concern for someone, you do it because you want them to be happy, safe, and well.","ex":{"en":"Without her care and concern, he had no chance at all","cn":"若非她的关心和照顾，他根本没有机会。"}},{"pos":"VERB 动词","cn":"关心;关注","en":"If you concern yourself with something, you give it attention because you think that it is important.","ex":{"en":"I didn't concern myself with politics","cn":"我不关心政治。"}},{"pos":"VERB 动词","cn":"关于;涉及","en":"If something such as a book or a piece of information concerns a particular subject, it is about that subject.","ex":{"en":"The bulk of the book concerns Sandy's two middle-aged children","cn":"书中主要描写桑迪的两个已到中年的孩子。"}},{"pos":"VERB 动词","cn":"(情况、事件或活动)对…有影响，与…相关","en":"If a situation, event, or activity concerns you, it affects or involves you.","ex":{"en":"It was just a little unfinished business from my past, and it doesn't concern you at all.","cn":"这只是我过去的一点未了之事，与你没有任何关系。"}},{"pos":"N-SING 单数名词","cn":"(某人)负责的事，分内之事","en":"If a situation or problem is your concern, it is something that you have a duty or responsibility to be involved with.","ex":{"en":"The technical aspects were the concern of the Army","cn":"技术方面由陆军负责。"}},{"pos":"N-COUNT 可数名词","cn":"公司，企业(通常用于描述其类型)","en":"You can refer to a company or business as a concern, usually when you are describing what type of company or business it is.","ex":{"en":"If not a large concern, Queensbury Nursery was at least a successful one.","cn":"即使规模不算大，昆斯伯里托儿所至少办得很成功。"}},{"pos":"PHRASE 短语","cn":"就…而言;在…看来","en":"You can say 'as far as I'm concerned' to indicate that you are giving your own opinion.","ex":{"en":"As far as I'm concerned the officials incited the fight.","cn":"在我看来，是官员们煽动了这场争斗。"}},{"pos":"PHRASE 短语","cn":"就…而言，说到(用于表明所谈论的话题)","en":"You can say as far as something is concerned to indicate the subject that you are talking about.","ex":{"en":"As far as starting a family is concerned, the trend is for women having their children later in life.","cn":"在要孩子方面，目前的趋势是女性要孩子要得比较晚。"}},{"pos":"PHRASE 短语","cn":"正常运营的公司","en":"If a company is a going concern, it is actually doing business, rather than having stopped trading or not yet having started trading.","ex":{"en":"The receivers will always prefer to sell a business as a going concern.","cn":"破产管理人总是希望在公司仍然正常运转的时候将其卖掉。"}},{"pos":"PHRASE 短语","cn":"令…担忧的;让…关注的","en":"If something is of concern to someone, they find it worrying and unsatisfactory.","ex":{"en":"Any injury to a child is a cause of great concern to us","cn":"孩子受到任何伤害都会让我们非常担心。"}},{"pos":"PHRASE 短语","cn":"对…重要的;与…有利害关系的","en":"If something is of concern to you, it is important to you.","ex":{"en":"How they are paid should be of little concern to the bank as long as they are paid.","cn":"只要肯付款，付款方式对银行来说不是很重要。"}}]},"examples":[{"en":"One major difference between these computers concerns the way in which they store information.","cn":"这些计算机彼此之间的一个主要差异涉及其贮存信息的方式。"},{"en":"Where our children's education is concerned, no compromise is acceptable.","cn":"在事关我们的孩子的教育问题上，那是毫无妥协余地的。"}]},"continue":{"media":{"uk":"media/uk/xcontinue__gb_1.mp3","us":"media/us/xcontinue__us_1.mp3"},"oxford":{"phon":"kənˈtɪnjuː","pos":"verb","senses":[{"en":"to keep existing or happening without stopping","cn":"持续；继续存在；不断发生","g":"[intransitive, transitive]","ex":{"en":"If the current trend continues, that number will increase 165 per cent by 2050.","cn":"如果目前的趋势继续下去，到 2050 年，这个数字将增加 165%。"}},{"en":"to keep doing something without stopping","cn":"继续做；不停地干","g":"[transitive, intransitive]","ex":{"en":"She wanted to continue working until she was 60.","cn":"她想要继续工作到 60 岁。"}},{"en":"to go or move further in the same direction","cn":"（朝相同方向）走，移动；延伸","g":"[intransitive]","ex":{"en":"The rough track continues, but it quickly disappears into undergrowth.","cn":"崎岖不平的小路还在继续，但很快就消失在灌木丛中。"}},{"en":"to remain in a particular job or condition","cn":"留任；维持原状","g":"[intransitive]","ex":{"en":"She will continue in her present job until a replacement can be found.","cn":"在找到替换人员以前，她将继续做她目前的工作。"}},{"en":"to start or start something again after stopping for a time","cn":"（停顿后）继续，再开始","g":"[intransitive, transitive]","ex":{"en":"The story continues in our next issue.","cn":"这篇故事我们将在下一期里继续刊载。"}},{"en":"to start speaking again after stopping","cn":"（停顿后）继续说，接着说","g":"[intransitive, transitive]","ex":{"en":"Please continue—I didn't mean to interrupt.","cn":"请继续往下说，我并非有意打断你的话。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"继续;持续","en":"If someone or something continues to do something, they keep doing it and do not stop.","ex":{"en":"I hope they continue to fight for equal justice after I'm gone","cn":"我希望我走了以后他们能继续为司法公正而战。"}},{"pos":"V-ERG 及物/不及物动词","cn":"延续;继续","en":"If something continues or if you continue it, it does not stop happening.","ex":{"en":"He insisted that the conflict would continue until conditions were met for a ceasefire","cn":"他坚持认为除非满足停火条件，否则冲突会继续下去。"}},{"pos":"VERB 动词","cn":"(中断后)继续，再开始","en":"If you continue with something, you start doing it again after a break or interruption.","ex":{"en":"I went up to my room to continue with my packing","cn":"我走进房间，继续打包。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(中断后)继续","en":"If something continues or if you continue it, it starts again after a break or interruption.","ex":{"en":"He denies 18 charges. The trial continues today","cn":"他否认了18项指控。审判今天继续。"}},{"pos":"VERB 动词","cn":"继续说;接着说","en":"If you continue, you begin speaking again after a pause or interruption.","ex":{"en":"'You have no right to intimidate this man,' Alison continued","cn":"“你没有权利威胁这个人，”艾莉森接着说。"}},{"pos":"VERB 动词","cn":"继续(做某项工作或处于某种状态)","en":"If you continue as something or continue in a particular state, you remain in a particular job or state.","ex":{"en":"He had hoped to continue as a full-time career officer","cn":"他曾经希望继续当一名全职的职业事务员。"}},{"pos":"VERB 动词","cn":"继续走;继续旅行","en":"If you continue in a particular direction, you keep walking or travelling in that direction.","ex":{"en":"He continued rapidly up the path, not pausing until he neared the Chapter House.","cn":"他匆匆地继续沿着这条路走，一直快到牧师会礼堂时才停下来。"}},{"pos":"VERB 动词","cn":"(路等)延伸","en":"If a road or path continues somewhere, it goes there after the place you have mentioned.","ex":{"en":"The main road continues towards Viterbo before turning right to Bolsena.","cn":"大路一直延伸到维泰博，之后右转通向博尔塞纳。"}}]},"examples":[{"en":"She will continue in her present job until a replacement can be found.","cn":"在找到替换人员以前，她将继续做她目前的工作。"},{"en":"‘In fact,’ he continued, ‘I'd like to congratulate you.’ “","cn":"其实，”他接着说，“我想向你表示祝贺。”"}]},"conflict":{"media":{"uk":"media/uk/xconflict__gb_1.mp3","us":"media/us/xconflict__us_1.mp3"},"oxford":{"phon":"ˈkɒnflɪkt","pos":"noun","senses":[{"en":"a situation in which people, groups or countries disagree strongly or are involved in a serious argument","cn":"冲突；争执；争论","ex":{"en":"The violence was the result of political conflicts.","cn":"暴力事件是政治冲突的结果。"}},{"en":"a violent situation or period of fighting between two countries","cn":"（军事）冲突；战斗","ex":{"en":"armed/military conflict","cn":"武装／军事冲突"}},{"en":"a situation in which there are ideas, opinions, feelings or wishes that are opposed to each other; a situation in which it is difficult to choose","cn":"抵触；矛盾；不一致","ex":{"en":"Her diary was a record of her inner conflict.","cn":"她的日记记录了她内心的矛盾。"}},{"en":"if two ideas, beliefs, stories, etc. conflict, it is not possible for them to exist together or for them both to be true","cn":"（两种思想、信仰、说法等）冲突，抵触","ex":{"en":"Reports conflicted on how much of the aid was reaching the famine victims.","cn":"对于究竟有多少援助到了饥民手里，相关报告的说法彼此矛盾。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"争执;争论;分歧","en":"Conflict is serious disagreement and argument about something important. If two people or groups are in conflict, they have had a serious disagreement or argument and have not yet reached agreement.","ex":{"en":"Try to keep any conflict between you and your ex-partner to a minimum","cn":"尽量将自己与前配偶之间的摩擦减到最小。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"矛盾心理；内心冲突","en":"Conflict is a state of mind in which you find it impossible to make a decision.","ex":{"en":"...the anguish of his own inner conflict.","cn":"内心矛盾给他带来的极大痛苦"}},{"pos":"N-VAR 可变名词","cn":"(军事)冲突;战斗","en":"Conflict is fighting between countries or groups of people.","ex":{"en":"...talks aimed at ending four decades of conflict","cn":"旨在结束持续了40年的冲突的会谈"}},{"pos":"N-VAR 可变名词","cn":"(信仰、观念或利益之间的)严重分歧，冲突","en":"A conflict is a serious difference between two or more beliefs, ideas, or interests. If two beliefs, ideas, or interests are in conflict, they are very different.","ex":{"en":"There is a conflict between what they are doing and what you want","cn":"他们所做的与你想要的之间存在冲突。"}},{"pos":"V-RECIP 相互动词","cn":"(想法、信仰或陈述)冲突，抵触，相互矛盾","en":"If ideas, beliefs, or accounts conflict, they are very different from each other and it seems impossible for them to exist together or to each be true.","ex":{"en":"Personal ethics and professional ethics sometimes conflict","cn":"个人道德和职业道德有时会相互抵触。"}}]},"examples":[{"en":"Reports conflicted on how much of the aid was reaching the famine victims.","cn":"对于究竟有多少援助到了饥民手里，这些报告的说法彼此矛盾。"},{"en":"The government has done nothing to resolve the conflict over nurses' pay.","cn":"政府未采取任何措施来解决护士工资问题引发的冲突。"}]},"consultancy":{"oxford":{"phon":"kənˈsʌltənsi","pos":"noun","senses":[{"en":"a company that gives expert advice on a particular subject to other companies or organizations","cn":"咨询公司","g":"[countable]","ex":{"en":"a management/design/computer, etc. consultancy","cn":"管理／设计／计算机等咨询公司"}},{"en":"expert advice that a company or person is paid to provide on a particular subject","cn":"专家咨询","g":"[uncountable]","ex":{"en":"consultancy fees","cn":"咨询费"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"咨询公司","en":"A consultancy is a company that gives expert advice on a particular subject.","ex":{"en":"A survey of 57 hospitals by Newchurch, a consultancy, reveals striking improvements.","cn":"一家名为纽彻奇的咨询公司对57家医院所作的调查显示改善十分明显。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"咨询服务;专家咨询","en":"Consultancy is expert advice on a particular subject which a person or group is paid to provide to a company or organization.","ex":{"en":"He is acting on a consultancy basis","cn":"他是根据专家意见采取行动的。"}}]},"media":{"uk":"media/uk/xconsultancy__gb_1.mp3","us":"media/us/xconsultancy__us_1.mp3"},"examples":[{"en":"a management/design/computer, etc. consultancy","cn":"管理/设计/计算机等咨询公司"},{"en":"consultancy fees","cn":"咨询费"}]},"cows":{"lemma":"cow","media":{"uk":"media/uk/cow__gb_1.mp3","us":"media/us/cow__us_1.mp3"}},"commit":{"oxford":{"phon":"kəˈmɪt","pos":"verb","senses":[{"en":"to do something wrong or illegal","cn":"做出（错事）；犯（罪）","g":"[transitive]","sc":"crime","ex":{"en":"to commit a crime/an offence","cn":"犯罪"}},{"en":"to kill yourself deliberately","cn":"自杀","g":"[transitive]","sc":"suicide","ex":{"en":"Her father had committed suicide.","cn":"她的父亲自杀了。"}},{"en":"to promise sincerely that you will definitely do something, keep to an agreement or arrangement, etc.","cn":"承诺，保证（做某事、遵守协议或遵从安排等）","g":"[transitive, often passive]","sc":"promise/say definitely","ex":{"en":"They want to see the text of the proposed treaty before fully committing themselves.","cn":"他们想在作出全面承诺之前看到拟议条约的文本。"}},{"en":"to give an opinion or make a decision openly so that it is then difficult to change it","cn":"（公开地）表达意见，作出决定（以致日后难以更改）","g":"[transitive]","sc":"promise/say definitely","ex":{"en":"You don't have to commit yourself now—just think about it.","cn":"你不必现在表态，只需考虑一下这件事。"}},{"en":"to stay with and completely support one person, organization, etc. or give all your time and effort to your work, an activity, etc.","cn":"忠于（某个人、机构等）；全心全意投入（工作、活动等）","g":"[intransitive]","sc":"stay with","ex":{"en":"Why are so many men scared to commit? (= say they will stay with one person)","cn":"为什么有这么多的男人害怕许诺专情于一人？"}},{"en":"to spend money or time on something/somebody","cn":"花（钱或时间）","g":"[transitive]","sc":"money/time","ex":{"en":"The council has committed large amounts of money to housing projects.","cn":"市政会在住宅项目上投入了大量资金。"}},{"en":"to order somebody to be sent to a hospital, prison, etc.","cn":"（下令）把（某人）送进（医院或监狱等）","g":"[transitive, often passive]","sc":"to hospital/prison","ex":{"en":"She was committed to a psychiatric hospital.","cn":"她被送进了精神病院。"}},{"en":"to send somebody for trial in court","cn":"把（某人）送交法庭受审","g":"[transitive]","sc":"somebody for trial","ex":{"en":"The attackers were committed for trial at Bristol Crown Court.","cn":"袭击者已被送往布里斯托皇家法院受审。"}},{"en":"to learn something well enough to remember it exactly","cn":"把…学好记牢","g":"[transitive]","sc":"something to memory","ex":{"en":"She committed the instructions to memory.","cn":"她把指令记得很牢。"}},{"en":"to write something down","cn":"把…记（或写）下来","g":"[transitive]","sc":"something to paper/writing"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"犯(罪);做(坏事)","en":"If someone commits a crime or a sin, they do something illegal or bad.","ex":{"en":"I have never committed any crime","cn":"我从来没犯过罪。"}},{"pos":"VERB 动词","cn":"自杀","en":"If someone commits suicide, they deliberately kill themselves.","ex":{"en":"There are unconfirmed reports he tried to commit suicide.","cn":"有未经证实的报道说他曾企图自杀。"}},{"pos":"VERB 动词","cn":"拨出，调配(资金、资源等)","en":"If you commit money or resources to something, you decide to use them for a particular purpose.","ex":{"en":"They called on Western nations to commit more money to the poorest nations","cn":"他们呼吁西方国家向极端贫困国家投入更多的钱。"}},{"pos":"VERB 动词","cn":"承诺，保证(做);忠于(某人)","en":"If you commit yourself to something, you say that you will definitely do it. If you commit yourself to someone, you decide that you want to have a long-term relationship with them.","ex":{"en":"I would advise people to think very carefully about committing themselves to working Sundays","cn":"我建议大家慎重考虑一下答应周日工作的问题。"}},{"pos":"VERB 动词","cn":"明确表态","en":"If you do not want to commit yourself on something, you do not want to say what you really think about it or what you are going to do.","ex":{"en":"It isn't their diplomatic style to commit themselves on such a delicate issue","cn":"对这样一个微妙的问题明确表态并非他们的外交风格。"}},{"pos":"VERB 动词","cn":"把…正式送进(医院、监狱等)","en":"If someone is committed to a hospital, prison, or other institution, they are officially sent there for a period of time.","ex":{"en":"Arthur's drinking caused him to be committed to a psychiatric hospital.","cn":"阿瑟由于酗酒被送进一家精神病医院。"}},{"pos":"VERB 动词","cn":"(英国)把…提交高等刑事法庭","en":"In the British legal system, if someone is committed for trial, they are sent by magistrates to stand trial in a crown court.","ex":{"en":"He is expected to be committed for trial at Liverpool Crown Court.","cn":"预计他会被移交利物浦高等刑事法庭。"}},{"pos":"VERB 动词","cn":"把…写下来;把…记住","en":"If you commit something to paper or to writing, you record it by writing it down. If you commit something to memory, you learn it so that you will remember it.","ex":{"en":"She had not committed anything to paper about it","cn":"关于这件事她未曾写下只言片语。"}}]},"media":{"uk":"media/uk/commit__gb_1.mp3","us":"media/us/commit__us_1.mp3"},"examples":[{"en":"Why are so many men scared to commit? (= say they will be loyal to one person)","cn":"为什么有这么多的男人害怕许诺忠诚于人？"},{"en":"You don't have to commit yourself now, just think about it.","cn":"你不必现在表态，只需考虑一下这件事。"}]},"conferencing":{"media":{"uk":"media/uk/xconferencing__gb_1.mp3","us":"media/us/xconferencing__us_1.mp3"},"oxford":{"phon":"ˈkɒnfərənsɪŋ","pos":"noun","senses":[{"en":"the activity of organizing or taking part in meetings, especially when people are in different places and use phones, computers, or video to communicate","cn":"召集（或参加）会议（尤指电话、网络或视频会议）","ex":{"en":"web conferencing","cn":"网络会议"}}]},"examples":[{"en":"video conferencing","cn":"召开视频会议"}]},"code":{"media":{"uk":"media/uk/code__gb_1.mp3","us":"media/us/code__us_1.mp3"},"oxford":{"phon":"kəʊd","pos":"noun","senses":[{"en":"a system of words, letters, numbers or symbols that represent a message or record information secretly or in a shorter form","cn":"密码；暗码；电码；代码","g":"[countable, uncountable]","ex":{"en":"to break/crack a code (= to understand and read the message)","cn":"破译密码"}},{"en":"the numbers that are used for a particular town, area or country, in front of an individual phone number","cn":"（电话的）区号","g":"[countable]","lab":"British English","ex":{"en":"There are three codes for London.","cn":"伦敦有三个电话区号。"}},{"en":"a system of computer programming instructions","cn":"（代）码","g":"[uncountable]","lab":"computing","ex":{"en":"Bill wrote the computer code for the project.","cn":"比尔为该项目编写了计算机代码。"}},{"en":"a set of moral principles or rules of behaviour that are generally accepted by society or a social group","cn":"道德准则；行为规范","g":"[countable]","ex":{"en":"The school enforces a strict code of conduct.","cn":"这所学校对行为操守严格要求。"}},{"en":"a system of laws or written rules that state how people in an institution or a country should behave","cn":"法典；法规","g":"[countable]","lab":"North American English","ex":{"en":"The law includes amendments to the penal code.","cn":"该法律包括几条刑法修正案。"}},{"en":"to write or print words, letters, numbers, etc. on something so that you know what it is, what group it belongs to, etc.","cn":"为…编码","g":"[transitive]","ex":{"en":"Each order is coded separately.","cn":"每份订单都单独编号。"},"pos":"verb"},{"en":"to put a message into code so that it can only be understood by a few people","cn":"把…译成密码","g":"[transitive]","pos":"verb"},{"en":"to write a computer program by putting one system of numbers, words and symbols into another system","cn":"编程序；编码","g":"[transitive, intransitive]","lab":"computing","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"行为准则;规则;法典;法规","en":"A code is a set of rules about how people should behave or about how something must be done.","ex":{"en":"...Article 159 of the Turkish Penal Code.","cn":"《土耳其刑法法典》第159条"}},{"pos":"N-COUNT 可数名词","cn":"密码;暗码;代码","en":"A code is a system of replacing the words in a message with other words or symbols, so that nobody can understand it unless they know the system.","ex":{"en":"They used elaborate secret codes, as when the names of trees stood for letters","cn":"他们使用了复杂的暗号，比如用树的名称代表字母。"}},{"pos":"N-COUNT 可数名词","cn":"(邮政)编码;(电话)区号","en":"A code is a group of numbers or letters which is used to identify something, such as a postal address or part of a telephone system.","ex":{"en":"Callers dialing the wrong area code will not get through.","cn":"打电话的人如果拨错区号，就无法接通。"}},{"pos":"N-COUNT 可数名词","cn":"信号;标记","en":"A code is any system of signs or symbols that has a meaning.","ex":{"en":"It will need different microchips to reconvert the digital code back into normal TV signals.","cn":"把数字信号重新转换回通常的电视信号需要另外的微芯片。"}},{"pos":"N-COUNT 可数名词","cn":"(遗传)密码","en":"The genetic code of a person, animal or plant is the information contained in DNA which determines the structure and function of cells, and the inherited characteristics of all living things.","ex":{"en":"Scientists provided the key to understanding the genetic code that determines every bodily feature.","cn":"科学家们找到了破解决定各种身体特征的遗传密码的密钥。"}},{"pos":"VERB 动词","cn":"把…编码(或编号)","en":"To code something means to give it a code or to mark it with its code.","ex":{"en":"He devised a way of coding every statement uniquely","cn":"他设计了一种把每句话进行独特编码的方法。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"编码","en":"Computer code is a system or language for expressing information and instructions in a form which can be understood by a computer."}]},"examples":[{"en":"In the event of the machine not operating correctly, an error code will appear.","cn":"如果机器运转不正常，就会出现错误代码。"},{"en":"Tap your code number into the machine.","cn":"把你的密码数字输入机器。"}]},"commands":{"lemma":"command","media":{"uk":"media/uk/command__gb_1.mp3","us":"media/us/command__us_1.mp3"}},"conquering":{"lemma":"conquer","media":{"uk":"media/ldoce/hwd/bre/2/conquer0205.mp3","us":"media/ldoce/hwd/ame/e/conquer.mp3"}},"correlate":{"oxford":{"phon":"ˈkɒrəleɪt","pos":"verb","senses":[{"en":"if two or more facts, figures, etc. correlate or if a fact, figure, etc. correlates with another, the facts are closely connected and affect or depend on each other","cn":"相互关联影响；相互依赖","g":"[intransitive]","ex":{"en":"The figures do not seem to correlate.","cn":"这些数字似乎毫不相干。"}},{"en":"to show that there is a close connection between two or more facts, figures, etc.","cn":"显示（两个或多个事实或数字等）的紧密联系","g":"[transitive]","ex":{"en":"Researchers are trying to correlate the two sets of figures.","cn":"研究人员正试图展示这两组数字的相关性。"}},{"en":"one of two or more facts, figures, etc. that are closely connected and affect or depend on each other","cn":"相互关联影响；相互依赖","ex":{"en":"Drug use is a significant correlate of property crime.","cn":"吸毒与财产犯罪密切相关。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-RECIP-ERG","cn":"相互关联;极为相似","en":"If one thing correlates with another, there is a close similarity or connection between them, often because one thing causes the other. You can also say that two things correlate .","ex":{"en":"Obesity correlates with increased risk for hypertension and stroke","cn":"肥胖会增加高血压和中风发作的几率。"}},{"pos":"VERB 动词","cn":"使显示联系;使相互关联","en":"If you correlate things, you work out the way in which they are connected or the way they influence each other.","ex":{"en":"Attempts to correlate specific language functions with particular parts of the brain have not advanced very far","cn":"人们试图把特定的语言功能与大脑的某些特定部位联系起来，这一努力目前还没有取得很大进展。"}}]},"media":{"uk":"media/uk/correlate__gb_1.mp3","us":"media/us/correlate__us_1.mp3"},"examples":[{"en":"A high-fat diet correlates with a greater risk of heart disease.","cn":"高脂肪饮食与增加心脏病发作的风险密切相关。"},{"en":"Researchers are trying to correlate the two sets of figures.","cn":"研究人员正试图展示这两组数字的相关性。"}]},"coping":{"oxford":{"phon":"ˈkəʊpɪŋ","pos":"adjective","senses":[{"en":"that enables somebody to deal with something difficult","cn":"能够应对困难的","ex":{"en":"Give people coping skills and they are more resilient in future traumas.","cn":"赋予人们应对技能，他们在未来的创伤中更有弹性。"}},{"en":"the top row, usually curved or sloping, of a stone or brick wall","cn":"压顶板","pos":"noun"}]},"media":{"uk":"media/uk/coping__gb_1.mp3","us":"media/us/coping__us_1.mp3"},"base":"cope"},"coat":{"media":{"img":["media/pic/coats_jackets_comp.jpg","media/thumb/overcoat.jpg"],"uk":"media/uk/coat__gb_1.mp3","us":"media/us/coat__us_1.mp3"},"oxford":{"phon":"kəʊt","pos":"noun","senses":[{"en":"a piece of outdoor clothing that is worn over other clothes to keep warm or dry. Coats have sleeves (= parts covering the arms) and may be long or short.","cn":"外套；外衣；大衣","ex":{"en":"to wear a coat","cn":"穿外套"}},{"en":"a jacket that is worn as part of a suit","cn":"（套装的）上装，上衣","lab":"North American English"},{"en":"the fur, hair or wool that covers an animal’s body","cn":"动物皮毛","ex":{"en":"a dog with a smooth/shaggy coat","cn":"皮毛光滑的／蓬乱的狗"}},{"en":"a layer of paint or some other substance that covers a surface","cn":"涂料层；覆盖层","ex":{"en":"to give the walls a second coat of paint","cn":"给墙刷上第二层涂料"}},{"en":"to cover something with a layer of a substance","cn":"给…涂上一层；用…覆盖","ex":{"en":"The cookies were thickly coated with chocolate.","cn":"曲奇上涂了厚厚一层巧克力。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"上衣;外衣;外套","en":"A coat is a piece of clothing with long sleeves which you wear over your other clothes when you go outside.","ex":{"en":"He turned off the television, put on his coat and walked out.","cn":"他关掉电视，穿上外套，出门了。"}},{"pos":"N-COUNT 可数名词","cn":"(动物的)皮毛","en":"An animal's coat is the fur or hair on its body.","ex":{"en":"Vitamin B6 is great for improving the condition of dogs' and horses' coats.","cn":"维生素B6对于改善狗和马的皮毛有显著的作用。"}},{"pos":"VERB 动词","cn":"给…涂上(或盖上、裹上)","en":"If you coat something with a substance or in a substance, you cover it with a thin layer of the substance.","ex":{"en":"Coat the fish with seasoned flour.","cn":"用拌有佐料的面粉将鱼裹上。"}},{"pos":"N-COUNT 可数名词","cn":"(油漆、清漆等的)一层","en":"A coat of paint or varnish is a thin layer of it on a surface.","ex":{"en":"The front door needs a new coat of paint","cn":"前门需要刷一层新漆了。"}}]},"examples":[{"en":"a dog with a smooth/shaggy coat","cn":"皮毛光滑的/蓬乱的狗"},{"en":"A film of dust coated the table.","cn":"桌上覆盖着一层灰尘。"}]},"commuting":{"lemma":"commute"},"courtesy":{"media":{"uk":"media/uk/courtesy__gb_1.mp3","us":"media/us/courtesy__us_1.mp3"},"oxford":{"phon":"ˈkɜːtəsi","pos":"noun","senses":[{"en":"polite behaviour that shows respect for other people","cn":"礼貌；谦恭；彬彬有礼","g":"[uncountable]","ex":{"en":"I was treated with the utmost courtesy by the staff.","cn":"我受到了工作人员极有礼貌的接待。"}},{"en":"a polite thing that you say or do when you meet people in formal situations","cn":"（正式场合见面时的）客气话，礼貌","g":"[countable, usually plural]","lab":"formal","ex":{"en":"an exchange of courtesies before the meeting","cn":"会议开始前互致问候"}},{"en":"provided free, at no cost to the person using it","cn":"免费乘坐（或使用）的","ex":{"en":"A courtesy bus operates between the hotel and the beach.","cn":"有一趟免费的公共汽车往返于旅馆和海滩之间。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"礼貌;谦恭;彬彬有礼","en":"Courtesy is politeness, respect, and consideration for others.","ex":{"en":"...a gentleman who behaves with the utmost courtesy towards ladies","cn":"对女士极有风度的绅士"}},{"pos":"N-SING 单数名词","cn":"礼貌","en":"If you refer to the courtesy of doing something, you are referring to a polite action.","ex":{"en":"By extending the courtesy of a phone call to my clients, I was building a personal relationship with them","cn":"通过礼貌性地给客户打电话，我开始和他们建立起私交。"}},{"pos":"N-COUNT 可数名词","cn":"(正式场合的)客气话，礼貌话","en":"Courtesies are polite, conventional things that people say in formal situations.","ex":{"en":"Hugh and John were exchanging faintly barbed courtesies.","cn":"休和约翰正说着带有相互挤兑意味的客气话。"}},{"pos":"ADJ 形容词","cn":"(服务)免费的","en":"Courtesy is used to describe services that are provided free of charge by an organization to its customers, or to the general public.","ex":{"en":"A courtesy shuttle bus operates between the hotel and the town.","cn":"有免费班车往返于酒店和市区。"}},{"pos":"ADJ 形容词","cn":"(拜访)礼节性的","en":"A courtesy call or a courtesy visit is a formal visit that you pay someone as a way of showing them politeness or respect.","ex":{"en":"The President paid a courtesy call on Emperor Akihito.","cn":"总统对明仁天皇进行了礼节性的拜访。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(无法律实效的或非正式的)尊称","en":"A courtesy title is a title that someone is allowed to use, although it has no legal or official status.","ex":{"en":"Both were accorded the courtesy title of Lady","cn":"两人都被尊称为“夫人”。"}},{"pos":"PREP-PHRASE 短语介词","cn":"(用来表示感谢)承蒙…的好意，蒙…提供","en":"If something is provided courtesy of someone or by courtesy of someone, they provide it. You often use this expression in order to thank them.","ex":{"en":"The waitress brings over some congratulatory glasses of champagne, courtesy of the restaurant","cn":"女侍者端来几杯饭店赠送的用来庆祝的香槟。"}},{"pos":"PREP-PHRASE 短语介词","cn":"作为…的结果;由…引起","en":"If you say that one thing happens courtesy of another or by courtesy of another, you mean that the second thing causes or is responsible for the first thing.","ex":{"en":"The air was fresh, courtesy of three holes in the roof","cn":"房顶有3个洞，所以空气很清新。"}}]},"examples":[{"en":"Viewers can see the stadium from the air, courtesy of a camera fastened to the plane.","cn":"由于飞机上安装有摄像机，电视观众可从空中鸟瞰体育场。"},{"en":"Win a weekend in Rome, courtesy of Fiat.","cn":"赢了就可以获得菲亚特公司提供的到罗马度周末的机会。"}]},"cooperation":{"media":{"uk":"media/uk/cooperation__gb_1.mp3","us":"media/us/cooperation__us_1.mp3"},"oxford":{"phon":"kəʊˌɒpəˈreɪʃn","pos":"noun","senses":[{"en":"the fact of doing something together or of working together towards a shared aim","cn":"合作；协作","ex":{"en":"They offered their cooperation on the project.","cn":"他们表示愿意在这个项目上合作。"}},{"en":"a desire to be helpful and do as you are asked","cn":"协助；配合","ex":{"en":"We would be grateful for your cooperation in clearing the hall as quickly as possible.","cn":"你们若大力协助尽快把大厅腾空，我们将不胜感激。"}}]},"examples":[{"en":"We would be grateful for your cooperation in clearing the hall as quickly as possible.","cn":"你们若大力协助尽快把大厅腾空，我们将不胜感激。"},{"en":"We would like to see closer cooperation between parents and schools.","cn":"我们希望家长和学校有更加紧密的合作。"}]},"continuously":{"oxford":{"phon":"kənˈtɪnjuəsli","pos":"adverb","senses":[{"en":"in a way that happens or exists for a period of time without being interrupted","cn":"不断的；持续的；连续的","ex":{"en":"He has lived and worked in France almost continuously since 1990.","cn":"自 1990 年以来，他几乎一直在法国生活和工作。"}},{"en":"in a way that is repeated many times","cn":"反复的；频繁的","lab":"informal","ex":{"en":"This prevents the system from continuously trying to deliver email.","cn":"这可以防止系统不断尝试发送电子邮件。"}}]},"media":{"uk":"media/uk/xcontinuously__gb_1.mp3","us":"media/us/xcontinuously__us_1.mp3"},"examples":[{"en":"He has lived and worked in France almost continuously since 1990.","cn":"自从 1990 年以来，他差不多一直在法国居住和工作。"},{"en":"a continuous flow of information","cn":""}]},"cooled":{"lemma":"cool","media":{"uk":"media/uk/cool__gb_1.mp3","us":"media/us/cool__us_1.mp3"}},"cola":{"media":{"uk":"media/uk/cola__gb_1.mp3","us":"media/us/cola__us_1.mp3"},"oxford":{"phon":"ˈkəʊlə","pos":"noun","senses":[{"en":"a sweet brown, fizzy drink (= with bubbles) that does not contain alcohol. Its taste comes from the seeds of a West African tree (the cola tree) and other substances.","cn":"可乐饮料","g":"[uncountable, countable]"},{"en":"a glass, can or bottle of cola","cn":"一杯（或一罐、一瓶）可乐","g":"[countable]"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"可乐(饮料)","en":"Cola is a sweet brown non-alcoholic fizzy drink.","ex":{"en":"...a can of cola.","cn":"一听可乐"}}]},"examples":[{"en":"a can of cola","cn":"一罐可乐"}]},"competes":{"lemma":"compete","media":{"uk":"media/uk/compete__gb_1.mp3","us":"media/us/compete__us_1.mp3"}},"composting":{"lemma":"compost"},"congress":{"oxford":{"phon":"ˈkɒŋɡres","pos":"noun","senses":[{"en":"a large formal meeting or series of meetings where representatives from different groups discuss ideas, make decisions, etc.","cn":"代表大会","g":"[countable]","ex":{"en":"an international congress of trades unions","cn":"工会国际代表大会"}},{"en":"(in the US and some other countries) the name of the group of people who are elected to make laws, in the US consisting of the Senate and the House of Representatives","cn":"（美国及其他一些国家的）国会，议会","g":"[countable + singular or plural verb]","lab":"especially North American English","ex":{"en":"Congress will vote on the proposals tomorrow.","cn":"国会明天将对提案进行投票表决。"}},{"en":"a political organization or society","cn":"国民大会","g":"[countable + singular or plural verb]","ex":{"en":"the African National Congress","cn":"非洲人国民大会"}},{"en":"the action of coming together","cn":"性交，交媾","g":"[uncountable]","lab":"formal","ex":{"en":"sexual congress","cn":"性交。"}}]},"collins":{"senses":[{"pos":"N-PROPER-COLL 专有集合名词","cn":"(由众议院和参议院组成的)美国国会","en":"Congress is the elected group of politicians that is responsible for making the law in the United States. It consists of two parts: the House of Representatives and the Senate. →see usage note at:","ex":{"en":"We want to cooperate with both the administration and Congress.","cn":"我们既想与政府合作，也想与国会合作。"}}]},"media":{"uk":"media/uk/xcongress__gb_1.mp3","us":"media/us/xcongress__us_1.mp3"},"examples":[{"en":"Congress will vote on the proposals tomorrow.","cn":"国会明天将对提案进行投票表决。"},{"en":"an international congress of trades unions","cn":"工会国际代表大会"}]},"consumerism":{"oxford":{"phon":"kənˈsjuːmərɪzəm","pos":"noun","senses":[{"en":"the buying and using of goods and services; the belief that it is good for a society or an individual person to buy and use a large quantity of goods and services","cn":"消费；消费主义（认为大量消费对社会和个人有利）","ex":{"en":"She was appalled by the greed and rampant consumerism she saw in modern society.","cn":"她对现代社会中贪婪和消费主义的大行其道感到震惊。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"消费主义","en":"Consumerism is the belief that it is good to buy and use a lot of goods.","ex":{"en":"They have clearly embraced Western consumerism.","cn":"他们显然完全接受了西方的消费主义观念。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"消费者权益保护","en":"Consumerism is the protection of the rights and interests of consumers."}]},"media":{"uk":"media/uk/xconsumerism__gb_1.mp3","us":"media/us/xconsumerism__us_1.mp3"},"examples":[{"en":"consumerist values","cn":"消费主义的价值观"},{"en":"the growth of consumerism","cn":"消费主义的兴起"}]},"complex":{"media":{"uk":"media/uk/complex__gb_1.mp3","us":"media/us/complex__us_1.mp3"},"oxford":{"phon":"ˈkɒmpleks","pos":"adjective","senses":[{"en":"made of many different things or parts that are connected; difficult to understand","cn":"复杂的；难懂的","ex":{"en":"a complex problem/issue/process/system","cn":"复杂的问题／议题／过程／系统"}},{"en":"containing one main part (= the root of a word or main clause of a sentence) and one or more other parts (called affixes or subordinate clauses)","cn":"复合的（指词根加有词缀或主句含有从句）","lab":"grammar","ex":{"en":"In the complex sentence, ‘I'd like to go to the beach, if it's warm enough’, ‘I'd like to go to the beach’ is the main clause, and ‘if it's warm enough’ is the subordinate clause.","cn":"在复杂句中，“I'd like to go to the beach, if it's warm enough”，“I'd like to go to the beach”是主句，“if it's warm enough”是从句。"}},{"en":"a group of buildings of a similar type together in one place","cn":"（类型相似的）建筑群","lab":"especially North American English","ex":{"en":"a sports/leisure/shopping complex","cn":"运动／休闲／购物中心"},"pos":"noun"},{"en":"a group of things that are connected","cn":"相关联的一组事物","ex":{"en":"This is just one of a whole complex of issues.","cn":"这仅仅是所有相关的问题之一。"},"pos":"noun"},{"en":"a set of beliefs or fears, which may not be conscious, that can make somebody very unhappy or cause a mental illness","cn":"一系列可能无意识的信念或恐惧，可能使人非常不快乐或导致精神疾病","lab":"psychology","ex":{"en":"He suffers from a guilt complex.","cn":"他蒙受负罪感之苦。"},"pos":"noun"},{"en":"a feeling of worry or embarrassment about something that is not necessary or reasonable","cn":"对不必要或不合理的事情感到担心或尴尬","lab":"informal","ex":{"en":"She has a complex about her big ears.","cn":"她总是为自己的两只大耳朵感到不安。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"复杂的;错综的","en":"Something that is complex has many different parts, and is therefore often difficult to understand.","ex":{"en":"...in-depth coverage of today's complex issues.","cn":"对时下一些复杂问题的深度报道"}},{"pos":"ADJ 形容词","cn":"(句子)复合的","en":"In grammar, a complex sentence contains one or more subordinate clauses as well as a main clause."},{"pos":"N-COUNT 可数名词","cn":"综合建筑群;综合大楼","en":"A complex is a group of buildings designed for a particular purpose, or one large building divided into several smaller areas.","ex":{"en":"...plans for constructing a new stadium and leisure complex.","cn":"修建新体育场和休闲中心的计划"}},{"pos":"N-COUNT 可数名词","cn":"错综复杂的组合;复合体","en":"A complex of things is a group or system of things that are connected with each other in a complicated way.","ex":{"en":"...the complex of clans which occupied the land.","cn":"生活在这片土地上的关系复杂的氏族群落"}},{"pos":"N-COUNT 可数名词","cn":"(通常指由于过去不愉快的经历而形成的)情结","en":"If someone has a complex about something, they have a mental or emotional problem relating to it, often because of an unpleasant experience in the past.","ex":{"en":"I have never had a complex about my height.","cn":"我从来没有担心过自己的身高。"}}]},"examples":[{"en":"This is just one of a whole complex of issues.","cn":"这仅仅是所有相关的问题之一。"},{"en":"the complex structure of the human brain","cn":"错综复杂的人脑构造"}]},"consists":{"oxford":{"phon":"kənˈsɪst","pos":"verb","senses":[{"en":"( formal ) to have sth as the main or only part or feature","cn":"存在于；在于"},{"en":"to be formed from the things or people mentioned","cn":"由 … 组成（或构成）"}]},"media":{"uk":"media/uk/xconsist__gb_1.mp3","us":"media/us/xconsist__us_1.mp3"}},"could":{"media":{"uk":"media/uk/could__gb_1.mp3","us":"media/us/could__us_1.mp3"},"oxford":{"phon":"kəd","pos":"modal verb","senses":[{"en":"used as the past tense of ‘can’","cn":"（用于 can 的过去式）","ex":{"en":"She said that she couldn't come.","cn":"她说她来不了。"}},{"en":"used to ask if you can do something","cn":"（询问是否可做某事）能，可以","ex":{"en":"Could I use your phone, please?","cn":"请让我用一下你的电话可以吗？"}},{"en":"used to politely ask somebody to do something for you","cn":"（礼貌地请求别人做事）能，可以","ex":{"en":"Could you babysit for us on Friday?","cn":"你星期五帮我们看一下孩子好吗？"}},{"en":"used to show that something is or might be possible","cn":"（表示可能性）可能","ex":{"en":"I could do it now, if you like.","cn":"如果你愿意的话，我现在就可以做这事。"}},{"en":"used to suggest something","cn":"（用于建议）可以","ex":{"en":"We could write a letter to the director.","cn":"我们不妨给主管写封信。"}},{"en":"used to show that you are annoyed that somebody did not do something","cn":"（对某人未做某事表示恼怒）本来可以","ex":{"en":"They could have let me know they were going to be late!","cn":"他们要晚来，也该早告诉我一声呀！"}},{"en":"used to emphasize how strongly you want to express your feelings","cn":"（强调感觉）真想","lab":"informal","ex":{"en":"I'm so fed up I could scream!","cn":"我烦透了，非大喊大叫不可！"}}]},"collins":{"senses":[{"pos":"MODAL 情态动词","cn":"能;会","en":"You use could to indicate that someone had the ability to do something. You use could not or couldn't to say that someone was unable to do something. →see usage note at:","ex":{"en":"For my return journey, I felt I could afford the extra and travel first class","cn":"至于回程，我觉得我能多花点钱坐头等舱。"}},{"pos":"MODAL 情态动词","cn":"可能会;有时会","en":"You use could to indicate that something sometimes happened.","ex":{"en":"Though he had a temper and could be nasty, it never lasted","cn":"虽然他爱发脾气，而且有时还很讨厌，但向来都只是一阵儿。"}},{"pos":"MODAL 情态动词","cn":"本能够，本可以(表示某事本有可能发生但却并未发生)","en":"You use could have to indicate that something was a possibility in the past, although it did not actually happen.","ex":{"en":"He could have made a fortune as a lawyer","cn":"他本可以当律师挣大钱的。"}},{"pos":"MODAL 情态动词","cn":"(表示某事可能属实或可能发生)可能","en":"You use could to indicate that something is possibly true, or that it may possibly happen.","ex":{"en":"Doctors told him the disease could have been caused by years of working in smokey clubs","cn":"医生们告诉他这种疾病可能是由于多年在烟雾缭绕的俱乐部工作所致。"}},{"pos":"MODAL 情态动词","cn":"(表示某事不属实)不可能","en":"You use could not or couldn't to indicate that it is not possible that something is true.","ex":{"en":"They argued all the time and thought it couldn't be good for the baby","cn":"他们一直在争论，认为这对孩子肯定不好。"}},{"pos":"MODAL 情态动词","cn":"(表示可能性、能力或机会)可能","en":"You use could to talk about a possibility, ability, or opportunity that depends on other conditions.","ex":{"en":"Their hope was that a new and better East Germany could be born","cn":"他们希望能够诞生一个崭新的、更加美好的东德。"}},{"pos":"MODAL 情态动词","cn":"好像；仿佛","en":"You use could when you are saying that one thing or situation resembles another.","ex":{"en":"The charming characters she draws look like they could have walked out of the 1920s.","cn":"她画的那些优雅迷人的人物就好像是从20世纪30年代走出来的一样。"}},{"pos":"MODAL 情态动词","cn":"(表示提议或建议)可以","en":"You use could, or couldn't in questions, when you are making offers and suggestions.","ex":{"en":"I could call the local doctor","cn":"我可以给当地医生打电话。"}},{"pos":"MODAL 情态动词","cn":"(用于礼貌地提出请求或征得许可。当说话者意识到可能被拒绝时，可以用 couldn't 代替 could)能，可以","en":"You use could in questions when you are making a polite request or asking for permission to do something. Speakers sometimes use couldn't instead of 'could' to show that they realize that their request may be refused.","ex":{"en":"Could I stay tonight?","cn":"我今晚可以留下吗？"}},{"pos":"MODAL 情态动词","cn":"(用以礼貌地打断某人或引出将要说的话)请允许我","en":"People sometimes use structures with if I could or could I as polite ways of interrupting someone or of introducing what they are going to say next.","ex":{"en":"Well, if I could just interject","cn":"嗯，请允许我插一句。"}},{"pos":"MODAL 情态动词","cn":"(用以强调某人应该做所提及的事情，尤用于当说话者因为其没做该事而生气时)","en":"You use could to say emphatically that someone ought to do the thing mentioned, especially when you are annoyed because they have not done it. You use why couldn't in questions to express your surprise or annoyance that someone has not done something.","ex":{"en":"We've come to see you, so you could at least stand and greet us properly","cn":"我们都来看你了，你至少应该起身得体地打个招呼。"}},{"pos":"MODAL 情态动词","cn":"(表示想要做某事的强烈感情)","en":"You use could when you are expressing strong feelings about something by saying that you feel as if you want to do the thing mentioned, although you do not do it.","ex":{"en":"I could kill you! I swear I could!","cn":"我想杀了你！我发誓我真想杀了你！"}},{"pos":"MODAL 情态动词","cn":"(用在if后以谈论没有能力或机会做但为考虑可能的结果而设想去做的事)","en":"You use could after 'if' when talking about something that you do not have the ability or opportunity to do, but which you are imagining in order to consider what the likely consequences might be.","ex":{"en":"If I could afford it I'd have four television sets","cn":"假如能买得起，我就会有4台电视机。"}},{"pos":"MODAL 情态动词","cn":"(与比较级连用，强调某物或某人具备某种特征的程度)太…，再…不过","en":"You use could not or couldn't with comparatives to emphasize that someone or something has as much as is possible of a particular quality. For example, if you say 'I couldn't be happier', you mean that you are extremely happy.","ex":{"en":"The rest of the players are a great bunch of lads and I couldn't be happier","cn":"剩下的选手是一帮很棒的小伙子，我太高兴了。"}},{"pos":"MODAL 情态动词","cn":"怎么会(用在疑问句中强调对所发生的不愉快之事的感受)","en":"In speech, you use how could in questions to emphasize that you feel strongly about something bad that has happened.","ex":{"en":"How could you allow him to do something like that?","cn":"你怎么会允许他做那样的事？"}},{"pos":"CONVENTION 惯用语","cn":"不用了(谢绝更多的食物或饮品)","en":"You say 'I couldn't' to refuse an offer of more food or drink.","ex":{"en":"'More cake?' — 'Oh no, I couldn't.'","cn":"“再来点蛋糕？”——“哦不，不用了。”"}},{"pos":"","cn":"","en":"could do with→see: ;"}]},"examples":[{"en":"‘Have some more cake.’ ‘Oh, I couldn't, thank you (= I'm too full). ’ “","cn":"再来点蛋糕吧。” “谢谢你，吃不下了。”"},{"en":"I could do it now, if you like.","cn":"如果你愿意的话，我现在就可以做这事。"}]},"cowardice":{"media":{"uk":"media/uk/cowardice__gb_1.mp3","us":"media/us/cowardice__us_1.mp3"},"oxford":{"phon":"ˈkaʊədɪs","pos":"noun","senses":[{"en":"fear or lack of courage","cn":"惧怕；胆小；懦弱","ex":{"en":"The lieutenant had displayed cowardice in the face of the enemy.","cn":"那个中尉在面对敌人时表现怯懦。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"惧怕;胆小;懦弱","en":"Cowardice is cowardly behaviour.","ex":{"en":"He openly accused his opponents of cowardice.","cn":"他公然指责对手胆小懦弱。"}}]},"examples":[{"en":"cowardice in the face of danger","cn":"面临危险时的胆怯"}]},"countable":{"oxford":{"phon":"ˈkaʊntəbl","pos":"adjective","senses":[{"en":"a noun that is countable can be used in the plural and with a or an, for example table, cat and idea","cn":"（名词）可数的"}]},"media":{"uk":"media/uk/countable__gb_1.mp3","us":"media/us/countable__us_1.mp3"}},"copy":{"media":{"uk":"media/uk/copy__gb_1.mp3","us":"media/us/copy__us_1.mp3"},"oxford":{"phon":"ˈkɒpi","pos":"noun","senses":[{"en":"a thing that is made to be the same as something else, especially a document or a work of art","cn":"（尤指文件或艺术品的）复印件，副本，复制品","g":"[countable]","ex":{"en":"The thieves replaced the original painting with a copy.","cn":"盗贼们用摹本换走了原画。"}},{"en":"a single example of a book, newspaper, etc. of which many have been made","cn":"（书、报纸等的）一本，一册，一份","g":"[countable]","ex":{"en":"The book sold 20 000 copies within two weeks.","cn":"这本书在两周内销售了 2 万册。"}},{"en":"written material that is to be published in a newspaper, magazine, etc.; news or information that can be used in a newspaper article or advertisement","cn":"（报刊等的）稿件；（可用于报纸文章或广告的）消息，信息","g":"[uncountable]","ex":{"en":"The subeditors prepare the reporters' copy for the paper and write the headlines.","cn":"助理编辑处理记者为报纸写的稿件并加标题。"}},{"en":"a copy of a document, etc. made by a machine that photographs and then prints","cn":"复印件","g":"[countable]","ex":{"en":"Could I have ten copies of this page, please?","cn":"请把这一页给我复印十份好吗？"}},{"en":"a book used by students for writing exercises, etc. in","cn":"作业本；练习本","g":"[countable]","lab":"Indian English"},{"en":"to make something that is exactly like something else","cn":"复制；复印；仿造；临摹","g":"[transitive]","ex":{"en":"He taught himself by copying paintings in the Louvre.","cn":"他通过在卢浮宫临摹绘画自学成才。"},"pos":"verb"},{"en":"to write something exactly as it is written somewhere else","cn":"抄写；誊写","g":"[transitive]","ex":{"en":"The monks spent their days copying manuscripts.","cn":"僧侣整天都在抄写手抄本。"},"pos":"verb"},{"en":"to create an identical (= similar in every detail) version of data, a program, etc. so that you can use it again somewhere else","cn":"拷贝；复制","g":"[transitive]","lab":"computing","ex":{"en":"The software has been illegally copied.","cn":"这个软件已被非法复制。"},"pos":"verb"},{"en":"to behave or do something in the same way as somebody else","cn":"模仿；效法；仿效","g":"[transitive]","ex":{"en":"She copies everything her sister does.","cn":"她一切都效仿她的姐姐。"},"pos":"verb"},{"en":"to cheat in an exam, school work, etc. by writing what somebody else has written and pretending it is your own work","cn":"作弊；抄袭","g":"[intransitive, transitive]","ex":{"en":"He was punished by his teacher for copying in the exam.","cn":"他因考试抄袭而受到老师的惩罚。"},"pos":"verb"},{"en":"to make a photocopy of something","cn":"影印；复制；复印","g":"[transitive]","ex":{"en":"Finally, the notes can be copied and distributed to the audience.","cn":"最后，笔记可以复印分发给听众。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"复制品;复印件","en":"If you make a copy of something, you produce something that looks like the original thing.","ex":{"en":"The reporter apparently obtained a copy of Steve's resignation letter","cn":"那记者显然弄到了史蒂夫辞职信的复印件。"}},{"pos":"VERB 动词","cn":"复制;复印;仿造","en":"If you copy something, you produce something that looks like the original thing.","ex":{"en":"She never participated in obtaining or copying any classified documents for anyone.","cn":"她从未参与过为任何人获取或复制机密文件之事。"}},{"pos":"VERB 动词","cn":"抄写;誊写","en":"If you copy a piece of writing, you write it again exactly.","ex":{"en":"He would allow John slyly to copy his answers to impossibly difficult algebra questions","cn":"他会让约翰偷偷抄下自己对一些极难的代数题的解答。"}},{"pos":"VERB 动词","cn":"模仿;效法;仿效","en":"If you copy a person or what they do, you try to do what they do or try to be like them, usually because you admire them or what they have done.","ex":{"en":"Children can be seen to copy the behaviour of others whom they admire or identify with","cn":"人们发现儿童会模仿他们所崇拜或有共鸣感的人。"}},{"pos":"N-COUNT 可数名词","cn":"(书、报纸或CD的)一本，一册，一份","en":"A copy of a book, newspaper, or CD is one of many that are exactly the same.","ex":{"en":"I bought a copy of 'USA Today' from a street-corner machine","cn":"我从街角的自动售卖机买了一份《今日美国》。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(准备刊印或广播的)原稿，稿件","en":"In journalism, copy is written material that is ready to be printed or read in a broadcast.","ex":{"en":"...his ability to write the most lyrical copy in the history of sports television.","cn":"他能够撰写体育节目史上最富热情和激情的稿件"}},{"pos":"N-UNCOUNT 不可数名词","cn":"有报道价值的消息;新闻素材","en":"In journalism, copy is news or information that can be used in an article in a newspaper.","ex":{"en":"...journalists looking for good copy.","cn":"搜罗好题材的记者"}},{"pos":"","cn":"","en":"相关词组：copy down copy out"}]},"examples":[{"en":"Everything in the computer's memory can be copied onto DVDs.","cn":"计算机内存里的所有资料都可以复制到 DVD 光盘上。"},{"en":"The subeditors prepare the reporters' copy for the paper and write the headlines.","cn":"助理编辑处理记者为报纸写的稿件并加标题。"}]},"command":{"media":{"uk":"media/uk/command__gb_1.mp3","us":"media/us/command__us_1.mp3"},"oxford":{"phon":"kəˈmɑːnd","pos":"noun","senses":[{"en":"an order given to a person or an animal","cn":"（给人或动物的）命令","g":"[countable]","sc":"order","ex":{"en":"Begin when I give the command.","cn":"我发出命令时开始。"}},{"en":"an instruction given to a computer","cn":"指令；命令","g":"[countable]","sc":"for computer","ex":{"en":"The computer executes commands successively in the order they arrive.","cn":"计算机按照指令送达的顺序依次执行。"}},{"en":"control and authority over a situation or a group of people","cn":"控制；管辖；指挥","g":"[uncountable]","sc":"control","ex":{"en":"He has 1 200 men under his command.","cn":"他掌管着 1 200 人。"}},{"en":"a part of an army, air force, etc. that is organized and controlled separately; a group of officers who give orders","cn":"（陆军、空军等的）兵团，军区，指挥部，司令部","g":"[countable]","sc":"in army","ex":{"en":"Bomber Command","cn":"轰炸机组的指挥部"}},{"en":"your knowledge of something; your ability to do or use something, especially a language","cn":"知识；（尤指对语言的）掌握，运用能力","g":"[uncountable, singular]","sc":"knowledge","ex":{"en":"Applicants will be expected to have (a) good command of English.","cn":"申请人必须精通英语。"}},{"en":"to tell somebody to do something","cn":"命令","lab":"formal","sc":"order","ex":{"en":"He commanded his men to retreat.","cn":"他命令手下撤退。"},"pos":"verb"},{"en":"to be in charge of a group of people in the army, navy, etc.","cn":"指挥，统率（陆军、海军等）","sc":"in army","ex":{"en":"In March 1942 he was appointed to command US naval forces in Europe","cn":"1942 年 3 月，他受命指挥驻欧美国海军。"},"pos":"verb"},{"en":"to deserve and get something because of the special qualities you have","cn":"应得；博得；值得","g":"[no passive]","sc":"deserve and get","ex":{"en":"to command sympathy/support","cn":"值得同情／支持"},"pos":"verb"},{"en":"to be in a position from where you can see or control something","cn":"居高临下地掌控；俯瞰","g":"[no passive]","lab":"formal","sc":"view","ex":{"en":"The hotel commands a fine view of the valley.","cn":"从这家旅馆俯瞰，下面的峡谷一览无余。"},"pos":"verb"},{"en":"to have control of something; to have something available for use","cn":"控制；拥有…可供使用；掌管","lab":"formal","sc":"control","ex":{"en":"The party was no longer able to command a majority in Parliament.","cn":"该党已不能在国会中再占有多数。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"命令;下令;指示","en":"If someone in authority commands you to do something, they tell you that you must do it.","ex":{"en":"He commanded his troops to attack","cn":"他命令部队发起进攻。"}},{"pos":"VERB 动词","cn":"博得，赢得，拥有(尊重、服从等)","en":"If you command something such as respect or obedience, you obtain it because you are popular, famous, or important.","ex":{"en":"...an excellent physician who commanded the respect of all his colleagues","cn":"赢得所有同事尊敬的优秀的内科医生"}},{"pos":"VERB 动词","cn":"控制;掌管","en":"If an army or country commands a place, they have total control over it.","ex":{"en":"The Royal Navy would command the seas","cn":"皇家海军会控制所有海域。"}},{"pos":"VERB 动词","cn":"统率，指挥(军队)","en":"An officer who commands part of an army, navy, or air force is responsible for controlling and organizing it.","ex":{"en":"...the French general who commands the UN troops in the region","cn":"统率该地区联合国部队的法国将军"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"司令部;指挥部","en":"In the armed forces, a command is a group of officers who are responsible for organizing and controlling part of an army, navy, or air force.","ex":{"en":"He had authorisation from the military command to retaliate","cn":"他得到军事指挥部授权，准备反击。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"（某一指挥官统率的）部队，兵团，军区","en":"In the armed forces, a command is a group of soldiers that a particular officer is in charge of.","ex":{"en":"There would continue to be a joint command of US and Saudi forces operating within Saudi borders.","cn":"美国军队和沙特军队共同组成的联合部队将继续在沙特阿拉伯境内实施军事行动。"}},{"pos":"N-COUNT 可数名词","cn":"(计算机的)指令","en":"In computing, a command is an instruction that you give to a computer."},{"pos":"N-UNCOUNT 不可数名词","cn":"(对局面的)控制，掌握","en":"If someone has command of a situation, they have control of it because they have, or seem to have, power or authority.","ex":{"en":"Whoever was waiting for them there had command of the situation","cn":"在那边等候他们的人控制了局势。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"掌握;精通","en":"Your command of something, such as a foreign language, is your knowledge of it and your ability to use this knowledge.","ex":{"en":"His command of English was excellent.","cn":"他精通英语。"}},{"pos":"VERB 动词","cn":"居高临下;俯瞰;清楚地看到","en":"If a place commands a view, especially an impressive one, you can see the view clearly from that place. If a person commands a view of something, they can see it clearly from where they are.","ex":{"en":"The house commanded some splendid views of Delaware Bay.","cn":"从这座房子可以俯瞰到特拉华湾壮丽的景致。"}},{"pos":"PHRASE 短语","cn":"(技术或资源)可运用自如，充分运用，可支配","en":"If you have a particular skill or particular resources at your command, you have them and can use them fully.","ex":{"en":"He came from the Sudan without a word of English at his command","cn":"他来自苏丹地区，一句英语都不会。"}},{"pos":"PHRASE 短语","cn":"应付自如","en":"If you are in command or in command of yourself, you are relaxed and able to react and behave in the way that you want to.","ex":{"en":"Nixon looked comfortable and in command","cn":"尼克松看上去镇定自若。"}}]},"examples":[{"en":"He looked relaxed and totally in command of himself.","cn":"他看起来很轻松，有绝对的自信完全能控制住自己。"},{"en":"For the first time in years, she felt in command of her life.","cn":"多少年来第一次，她觉得生活掌握在自己的手里。"}]},"computerized":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(系统、进程或业务)计算机化的，电脑化的","en":"A computerized system, process, or business is one in which the work is done by computer.","ex":{"en":"The National Cancer Institute now has a computerized system that can quickly provide information.","cn":"国家癌症研究所现在拥有一套能迅速提供信息的电脑化系统。"}},{"pos":"ADJ 形容词","cn":"(信息)存入计算机的，电脑储存的","en":"Computerized information is stored on a computer.","ex":{"en":"Computerized data bases are proliferating fast","cn":"计算机数据库正在迅速激增。"}}]}},"colonialism":{"media":{"uk":"media/uk/colonialism__gb_1.mp3","us":"media/us/colonialism__us_1.mp3"},"oxford":{"phon":"kəˈləʊniəlɪzəm","pos":"noun","senses":[{"en":"the practice by which a powerful country controls another country or other countries","cn":"殖民主义","ex":{"en":"European colonialism","cn":"欧洲殖民主义"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"殖民主义;殖民政策","en":"Colonialism is the practice by which a powerful country directly controls less powerful countries and uses their resources to increase its own power and wealth.","ex":{"en":"...the bitter oppression of slavery and colonialism","cn":"奴隶制度和殖民主义的残酷压迫"}}]},"examples":[{"en":"colonialist laws","cn":"殖民主义的法律"},{"en":"European colonialism","cn":"欧洲殖民主义"}]},"complicatedly":{"lemma":"complicated","media":{"uk":"media/uk/complicated__gb_1.mp3","us":"media/us/complicated__us_1.mp3"}},"costing":{"oxford":{"phon":"ˈkɒstɪŋ","pos":"noun","senses":[{"en":"an estimate of how much money will be needed for something","cn":"成本估算","ex":{"en":"Here is a detailed costing of our proposals.","cn":"这是我们的方案的详细成本估算。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"成本估算","en":"A costing is an estimate of all the costs involved in a project or a business venture.","ex":{"en":"We'll put together a proposal, including detailed costings, free of charge.","cn":"我们将免费拟一份提案，其中包括详细的成本估算。"}}]},"media":{"uk":"media/uk/costing__gb_1.mp3","us":"media/us/costing__us_3.mp3"},"examples":[{"en":"Here is a detailed costing of our proposals.","cn":"这是我们的方案的详细成本估算。"},{"en":"You'd better do some costings.","cn":"你最好作一些成本估算。"}],"base":"cost"},"coloured":{"media":{"uk":"media/uk/coloured__gb_1.mp3","us":"media/us/coloured__us_1.mp3"},"oxford":{"phon":"ˈkʌləd","pos":"adjective","senses":[{"en":"having a particular colour or different colours","cn":"有…色的；色彩…的","ex":{"en":"brightly coloured balloons","cn":"色彩鲜艳的气球"}},{"en":"a word used to describe a person who is not white, which is now considered offensive","cn":"有色人种的","lab":"old-fashioned, offensive，，"},{"en":"(in South Africa) having parents who are of different races","cn":"（南非）混血种的"},{"en":"a word for a person who is not white, which is now considered offensive","cn":"有色人种","lab":"old-fashioned, offensive，，","pos":"noun"},{"en":"(in South Africa) a person whose parents are of different races","cn":"（南非）混血种的人","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有…色的","en":"Something that is coloured a particular colour is that colour.","ex":{"en":"The illustration shows a cluster of five roses coloured apricot orange.","cn":"插图上是一簇杏橙色的玫瑰，一共5朵。"}},{"pos":"ADJ 形容词","cn":"彩色的;有颜色的","en":"Something that is coloured is a particular colour or combination of colours, rather than being just white, black, or the colour that it is naturally.","ex":{"en":"You can often choose between plain white or coloured and patterned scarves.","cn":"常可在纯白色或带图案的彩色围巾中作出选择。"}},{"pos":"ADJ 形容词","cn":"有色人种的","en":"A coloured person belongs to a race of people with dark skins."},{"pos":"N-COUNT 可数名词","cn":"有色人种","en":"People whose skin is dark are sometimes referred to as coloureds ."}]},"examples":[{"en":"She was wearing a cream-coloured suit.","cn":"她穿着一身米色套装。"},{"en":"brightly coloured balloons","cn":"色彩鲜艳的气球"}],"base":"colour"},"committed":{"media":{"uk":"media/uk/committed__gb_1.mp3","us":"media/us/committed__us_1.mp3"},"oxford":{"phon":"kəˈmɪtɪd","pos":"adjective","senses":[{"en":"willing to work hard and give your time and energy to something; believing strongly in something","cn":"尽心尽力的；坚信的；坚定的","ex":{"en":"a committed member of the team","cn":"忠于职守的队员"}}]},"examples":[{"en":"They are committed socialists.","cn":"他们是坚定的社会主义者。"},{"en":"a committed member of the team","cn":"忠于职守的队员"}],"base":"commit"},"conceptual":{"oxford":{"phon":"kənˈseptʃuəl","pos":"adjective","senses":[{"en":"related to or based on ideas","cn":"概念（上）的；观念（上）的","ex":{"en":"a conceptual framework within which children’s needs are assessed","cn":"对儿童需求进行评估的概念框架"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"概念的;观念的","en":"Conceptual means related to ideas and concepts formed in the mind.","ex":{"en":"...replacing old laws with new within the same conceptual framework.","cn":"在同一个概念体系内以新法代替旧法"}}]},"media":{"uk":"media/uk/xconceptual__gb_1.mp3","us":"media/us/xconceptual__us_1.mp3"},"examples":[{"en":"a conceptual framework within which children's needs are assessed","cn":"对儿童需求进行评估的概念框架"},{"en":"conceptually similar/distinct","cn":"概念上相似/不同"}]},"cooperative":{"oxford":{"phon":"kəʊˈɒpərətɪv","pos":"adjective","senses":[{"en":"involving doing something together or working together with others towards a shared aim","cn":"合作的；协作的；同心协力的","g":"[usually before noun]","ex":{"en":"Cooperative activity is essential to effective community work.","cn":"要把社区工作做好，协作活动是必不可少的。"}},{"en":"helpful by doing what you are asked to do","cn":"协助的；配合的","ex":{"en":"Employees will generally be more cooperative if their views are taken seriously.","cn":"如果雇员的意见得到认真对待，他们一般都会更加配合。"}},{"en":"owned and run by the people involved, with the profits shared by them","cn":"共同拥有共同经营利益共享的；合作的","g":"[usually before noun]","lab":"business","ex":{"en":"a cooperative farm","cn":"合作农场"}},{"en":"a cooperative business or other organization","cn":"合作企业；合作社组织","ex":{"en":"agricultural cooperatives in India","cn":"印度的农业合作社"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"合作社;合作机构","en":"A co-operative is a business or organization run by the people who work for it, or owned by the people who use it. These people share its benefits and profits.","ex":{"en":"They decided a housing co-operative was the way to regenerate Ormiston Crescent","cn":"他们最终决定通过住房合作社来重建奥米斯顿月牙街。"}},{"pos":"ADJ 形容词","cn":"齐心协力的;合作进行的","en":"A co-operative activity is done by people working together.","ex":{"en":"He was transferred to FBI custody in a smooth co-operative effort between Egyptian and US authorities","cn":"在埃及当局和美国当局的共同努力下他被顺利移交美国联邦调查局进行羁押。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"合作的;有协作精神的;愿意配合的","en":"If you say that someone is co-operative, you mean that they do what you ask them to without complaining or arguing.","ex":{"en":"I made every effort to be co-operative.","cn":"我尽了最大努力配合。"}}]},"media":{"uk":"media/uk/cooperative__gb_1.mp3","us":"media/us/cooperative__us_1.mp3"},"examples":[{"en":"Employees will generally be more cooperative if their views are taken seriously.","cn":"如果雇员的意见得到认真对待，他们一般都会更加配合。"},{"en":"Cooperative activity is essential to effective community work.","cn":"要把社区工作做好，协作活动是必不可少的。"}]},"commons":{"lemma":"common","media":{"uk":"media/uk/commons__gb_1.mp3","us":"media/us/commons__us_1.mp3"}},"concentrating":{"lemma":"concentrate"},"concerns":{"lemma":"concern"},"confessed":{"lemma":"confess","media":{"uk":"media/ldoce/hwd/bre/1/confessed0205.mp3","us":"media/ldoce/hwd/ame/c/confessed.mp3"}},"communications":{"lemma":"communication"},"commercials":{"lemma":"commercial"},"conflicting":{"oxford":{"phon":"kənˈflɪktɪŋ","pos":"adjective","senses":[{"en":"unable to exist together or both be true","cn":"相互冲突的；相互矛盾的","ex":{"en":"There were conflicting reports about the number of people injured.","cn":"关于受伤人数，各种报道互相矛盾。"}}]},"media":{"uk":"media/ldoce/hwd/bre/0/ldoce6conflicting.mp3","us":"media/ldoce/hwd/ame/f/conflicting_adj.mp3"},"base":"conflict"},"condemned":{"lemma":"condemn","media":{"uk":"media/ldoce/hwd/bre/9/condemned0205.mp3","us":"media/ldoce/hwd/ame/8/laadcondemned.mp3"}},"concludes":{"lemma":"conclude"},"comments":{"lemma":"comment"},"containing":{"lemma":"contain"},"copies":{"lemma":"copy"},"courtyards":{"lemma":"courtyard"},"combinations":{"lemma":"combination"},"consequences":{"oxford":{"phon":"ˈkɒnsɪkwənsɪz","pos":"noun","senses":[{"en":"a game in which each player writes the first line of a story on a piece of paper and then passes it to the next player who writes the second line, and so on. Each player folds the paper so that the next player cannot see what is already written. The result is a number of crazy and often funny stories. The stories follow a pattern that always begins with the names of two people and ends with the sentence 'And the consequence was…’","cn":"结果：一种游戏，其中每个玩家将故事的第一行写在纸上，然后将其传递给下一个写第二行的玩家，依此类推。每个玩家都折叠纸张，以便下一个玩家看不到已经写的内容。结果产生了许多疯狂且常常有趣的故事。故事遵循的模式总是以两个人的名字开头，以“结果是……”结尾。"}]},"media":{"uk":"media/ldoce/hwd/bre/5/p028-000003580.mp3","us":"media/ldoce/hwd/ame/5/p028-000003580.mp3"},"base":"consequence"},"concertos":{"lemma":"concerto"},"conditions":{"lemma":"condition"},"connotations":{"lemma":"connotation"},"conventions":{"lemma":"convention"},"collaborated":{"lemma":"collaborate"},"communicating":{"lemma":"communicate"},"colleagues":{"lemma":"colleague"},"conspires":{"oxford":{"phon":"kənˈspaɪə(r)","pos":"verb","senses":[{"en":"to secretly plan with other people to do sth illegal or harmful","cn":"密谋；图谋；合谋"},{"en":"to seem to work together to make sth bad happen","cn":"似乎共同导致（不良后果）"}]}},"connotes":{"oxford":{"phon":"kəˈnəʊt","pos":"verb","senses":[{"en":"to suggest a feeling, an idea, etc. as well as the main meaning","cn":"意味着；暗示；隐含"}]}},"confronted":{"lemma":"confront"},"counting":{"lemma":"count"},"connecting":{"lemma":"connect"},"coveted":{"oxford":{"phon":"ˈkʌvət","pos":"verb","senses":[{"en":"( formal ) to want sth very much, especially sth that belongs to sb else","cn":"渴望；贪求（尤指别人的东西）；觊觎"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"人人向往的","en":"You use coveted to describe something that very many people would like to have.","ex":{"en":"Allan Little from Radio 4 took the coveted title of reporter of the year.","cn":"第四广播台的艾伦·利特尔获得了人人梦寐以求的年度记者称号。"}}]}},"consulting":{"lemma":"consult","media":{"uk":"media/ldoce/hwd/bre/4/consulting_n0205.mp3","us":"media/ldoce/hwd/ame/6/consulting.mp3"}},"components":{"lemma":"component"},"conjured":{"lemma":"conjure"},"complaints":{"lemma":"complaint"},"constituents":{"oxford":{"phon":"kənˈstɪtjuənt","pos":"noun","senses":[{"en":"a person who lives, and can vote in a constituency （","cn":"选区的）选民，选举人"},{"en":"one of the parts of sth that combine to form the whole","cn":"成分；构成要素"}]}},"complained":{"lemma":"complain"},"contractors":{"lemma":"contractor"},"countries":{"lemma":"country"},"counted":{"lemma":"count"},"contains":{"lemma":"contain"},"coincides":{"lemma":"coincide"},"corridors":{"lemma":"corridor"},"courts":{"lemma":"court"},"compilations":{"oxford":{"phon":"ˌkɒmpɪˈleɪʃn","pos":"noun","senses":[{"en":"a collection of items, especially pieces of music or writing, taken from different places and put together","cn":"收集；选编；选辑"},{"en":"the process of compiling sth","cn":"编纂；编著；编写"}]}},"congressmen":{"oxford":{"phon":"ˈkɒŋɡresmən","pos":"noun","senses":[{"en":"a member of Congress in the US, especially the House of Representatives （","cn":"尤指美国众议院的）国会议员；众议员"}]}},"competed":{"lemma":"compete"},"computers":{"lemma":"computer"},"conducted":{"lemma":"conduct"},"consisting":{"oxford":{"phon":"kənˈsɪst","pos":"verb","senses":[{"en":"( formal ) to have sth as the main or only part or feature","cn":"存在于；在于"},{"en":"to be formed from the things or people mentioned","cn":"由 … 组成（或构成）"}]}},"concentrates":{"lemma":"concentrate"},"contents":{"lemma":"content"},"continues":{"lemma":"continue"},"completed":{"lemma":"complete"},"contrasts":{"lemma":"contrast"},"consumes":{"lemma":"consume"},"converted":{"lemma":"convert"},"confronting":{"lemma":"confront"},"copyrighted":{"lemma":"copyright"},"counts":{"lemma":"count"},"commenced":{"oxford":{"phon":"kəˈmens","pos":"verb","senses":[{"en":"to begin to happen; to begin sth","cn":"开始发生；开始；着手"}]}},"corroded":{"lemma":"corrode"},"consultants":{"lemma":"consultant"},"corners":{"lemma":"corner"},"conversations":{"lemma":"conversation"},"colder":{"lemma":"cold"},"considered":{"lemma":"consider","media":{"uk":"media/ldoce/hwd/bre/e/brelasdeconsidered.mp3","us":"media/ldoce/hwd/ame/4/considered.mp3"}},"contributed":{"lemma":"contribute"},"coated":{"lemma":"coat"},"corrections":{"lemma":"correction"},"contexts":{"lemma":"context"},"couldn't":{"lemma":"could"},"conversationalists":{"oxford":{"phon":"ˌkɒnvəˈseɪʃənəlɪst","pos":"noun","senses":[{"en":"a person who is good at talking to others, especially in an informal way","cn":"健谈的人；能聊的人"}]}},"connections":{"lemma":"connection"},"compensating":{"lemma":"compensate"},"cordials":{"lemma":"cordial"},"concluded":{"lemma":"conclude"},"conveys":{"lemma":"convey"},"concealing":{"lemma":"conceal"},"communities":{"lemma":"community"},"conveyances":{"oxford":{"phon":"kənˈveɪəns","pos":"noun","senses":[{"en":"( formal ) the process of taking sb/sth from one place to another","cn":"传送；运送；输送"},{"en":"( formal ) a vehicle","cn":"运载（或交通）工具；车辆"}]}},"constructed":{"lemma":"construct"},"comparing":{"lemma":"compare"},"comes":{"lemma":"come"},"coats":{"lemma":"coat"},"copied":{"lemma":"copy"},"cooked":{"lemma":"cook"},"cornets":{"oxford":{"phon":"ˈkɔːnɪt","pos":"noun","senses":[{"en":"a brass musical instrument like a small trumpet","cn":"短号"}]}},"cooling":{"lemma":"cool"},"collecting":{"lemma":"collect"},"contemplated":{"lemma":"contemplate"},"conserved":{"oxford":{"phon":"kənˈsɜːv","pos":"verb","senses":[{"en":"to use as little of sth as possible so that it lasts a long time","cn":"节省；节约"},{"en":"to protect sth and prevent it from being changed or destroyed","cn":"保护；保存；保藏"}]}},"covers":{"lemma":"cover"},"coalfields":{"oxford":{"phon":"ˈkəʊlfiːld","pos":"noun","senses":[{"en":"a large area where there is a lot of coal under the ground","cn":"煤田"}]}},"consisted":{"oxford":{"phon":"kənˈsɪst","pos":"verb","senses":[{"en":"( formal ) to have sth as the main or only part or feature","cn":"存在于；在于"},{"en":"to be formed from the things or people mentioned","cn":"由 … 组成（或构成）"}]}},"completing":{"lemma":"complete"},"contained":{"lemma":"contain"},"compressors":{"oxford":{"phon":"kəmˈpresə(r)","pos":"noun","senses":[{"en":"a machine that compresses air or other gases","cn":"压气机；压缩机"}]}},"consigned":{"oxford":{"phon":"kənˈsaɪn","pos":"verb","senses":[{"en":"to put sb/sth somewhere in order to get rid of them/it （","cn":"为摆脱而）把 … 置于，把 … 交付给"},{"en":"to put sb/sth in an unpleasant situation","cn":"把 … 置于（令人不快的境地）；打发；发落"}]}},"conferring":{"oxford":{"phon":"kənˈfɜː(r)","pos":"verb","senses":[{"en":"to discuss sth with sb, in order to exchange opinions or get advice","cn":"商讨；协商；交换意见"},{"en":"to give sb an award, a university degree or a particular honour or right","cn":"授予，颁发（奖项、学位、荣誉或权利）"}]}},"companies":{"lemma":"company"},"commentators":{"lemma":"commentator"},"composers":{"lemma":"composer"},"codes":{"lemma":"code"},"conditioned":{"lemma":"condition"},"coined":{"lemma":"coin"},"conserving":{"oxford":{"phon":"kənˈsɜːv","pos":"verb","senses":[{"en":"to use as little of sth as possible so that it lasts a long time","cn":"节省；节约"},{"en":"to protect sth and prevent it from being changed or destroyed","cn":"保护；保存；保藏"}]}},"compared":{"lemma":"compare"},"conferences":{"lemma":"conference"},"costs":{"lemma":"cost"},"cocktails":{"lemma":"cocktail"},"colleges":{"lemma":"college"},"counters":{"lemma":"counter"},"courses":{"lemma":"course"},"contrasted":{"lemma":"contrast"},"couples":{"lemma":"couple"},"couching":{"lemma":"couch"},"colouring":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"颜色;色彩","en":"The colouring of something is the colour or colours that it is.","ex":{"en":"Other countries vary the coloring of their bank notes as well as their size.","cn":"其他国家的纸币色彩不一，大小也不同。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(头发、皮肤和眼睛的)颜色","en":"Someone's colouring is the colour of their hair, skin, and eyes.","ex":{"en":"None of them had their father's dark colouring","cn":"他们都不像父亲那样黑。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"食物色素;着色剂","en":"Colouring is a substance that is used to give colour to food.","ex":{"en":"A few drops of green food coloring were added.","cn":"加了几滴绿色的食物色素。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a particular type of one colour, which is darker or lighter than other types of the same colour","cn":""},{"en":"a small amount of a particular colour in something that is mostly another colour","cn":""},{"en":"a vivid colour is very bright and noticeable, especially in a way that is attractive","cn":""}]},"collocations":{"phrases":["ADJ. natural | dark, fair","VERB + COLOURING have He daughter has very fair colouring."]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdecolouring.mp3","us":"media/ldoce/hwd/ame/8/coloring.mp3"},"examples":[{"en":"insects with vivid yellow and black colouring","cn":"躯体带有鲜黄色和黑色的昆虫"},{"en":"Blue suited her fair colouring.","cn":"蓝色适合于她白皙的肤色。"}],"oxford":{"phon":"ˈkʌlərɪŋ","pos":"noun","senses":[{"en":"a substance that is used to give a particular colour to food","cn":"（食物的）着色剂，色素","g":"[uncountable, countable]","ex":{"en":"red food colouring","cn":"红色食物着色剂"}},{"en":"the colour of a person’s skin, eyes and hair","cn":"（皮肤、眼睛和头发的）颜色","g":"[uncountable]","ex":{"en":"Blue suited her fair colouring.","cn":"蓝色适合于她白皙的肤色。"}},{"en":"the colours that exist in something, especially a plant or an animal","cn":"（尤指动植物的）天然色，色彩","g":"[uncountable]","ex":{"en":"insects with vivid yellow and black colouring","cn":"躯体带有鲜黄色和黑色的昆虫"}}]},"base":"colour"},"conjunctivitis":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"结膜炎","en":"Conjunctivitis is an eye infection which causes the thin skin that covers the eye to become red."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a painful and infectious disease of the eye that makes it red","cn":"结膜炎"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41conjunctivitis.mp3","us":"media/ldoce/hwd/ame/1/conjunctivitis.mp3"},"oxford":{"phon":"kənˌdʒʌŋktɪˈvaɪtɪs","pos":"noun","senses":[{"en":"an eye disease that causes part of the eye to become red and painful","cn":"结膜炎"}]}},"concussion":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"脑震荡","en":"If you suffer concussion after a blow to your head, you lose consciousness or feel sick or confused.","ex":{"en":"Nicky was rushed to hospital with concussion","cn":"尼基因脑震荡被火速送往医院。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"temporary damage to the brain that makes you lose consciousness or feel sick for a short time, usually caused by something hitting your head","cn":""},{"en":"an injury to the brain that makes you lose consciousness or feel sick for a short time, usually caused by something hitting your head","cn":"脑震荡"},{"en":"a violent shaking movement, caused by the very loud sound of something such as an explosion 〔","cn":"爆炸等引起的〕震动﹐震荡"}]},"vocab":{"pos":"n","senses":[{"en":"A concussion is a violent blow, especially to the head, that often injures the brain or causes a loss of consciousness — an all-too-frequent occurrence, unfortunately, in contact sports like football or boxing."}]},"collocations":{"phrases":["ADJ. bad | mild, minor, slight","VERB + CONCUSSION have, suffer","PREP. with ~ He was carried off the field with slight concussion."]},"media":{"uk":"media/ldoce/hwd/bre/b/concussion0205.mp3","us":"media/ldoce/hwd/ame/4/concussion.mp3"},"examples":[{"en":"( BrE ) He was taken to hospital with concussion.","cn":"他因脑震荡被送进医院。"},{"en":"( NAmE ) He was taken to the hospital with a concussion.","cn":"他因脑震荡被送进医院。"}],"oxford":{"phon":"kənˈkʌʃn","pos":"noun","senses":[{"en":"a temporary loss of consciousness caused by a hard hit on the head; the effects of a severe hit on the head, such as not being able to think clearly and temporary loss of physical and mental abilities","cn":"脑震荡","ex":{"en":"He was taken to hospital with concussion.","cn":"他因脑震荡被送进医院。"}}]}},"costa":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"used humorously, especially in newspapers, when describing a place on the coast that has particular characteristics","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld5_costa.mp3","us":"media/ldoce/hwd/ame/7/ld5_costa.mp3"},"examples":[{"en":"The town is part of the Costa geriatrica on England's south coast. (= many old people live there )","cn":""},{"en":"the Costa del crime","cn":""}]},"concession":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指为平息争端或冲突而作出的)让步，妥协","en":"If you make a concession to someone, you agree to let them do or have something, especially in order to end an argument or conflict.","ex":{"en":"The King made major concessions to end the confrontation with his people.","cn":"为了结束与其臣民的冲突，国王作出了很大的让步。"}},{"pos":"N-COUNT 可数名词","cn":"特许权;优惠","en":"A concession is a special right or privilege that is given to someone.","ex":{"en":"The government has granted concessions to three private telephone companies.","cn":"政府已经向3家私营电话公司授予了特许权。"}},{"pos":"N-COUNT 可数名词","cn":"(通常指针对老人、学生和失业人员的)优惠价格","en":"A concession is a special price which is lower than the usual price and which is often given to old people, students, and the unemployed.","ex":{"en":"Open daily; admission £1.10 with concessions for children and OAPs.","cn":"每天开放;门票1.10英镑，儿童和退休人士可享受票价优惠。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指在别家公司大楼内的)销售权(或经营权)协议","en":"A concession is an arrangement where someone is given the right to sell a product or to run a business, especially in a building belonging to another business."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to reach an agreement with someone in which both of you accept less than you really want","cn":""},{"en":"to do or pay part of what the other person in an agreement wants if they will do or pay part of what you want","cn":""},{"en":"if someone in authority makes concessions , they let their opponents have something that they are asking for, in order to reach an agreement","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"The noun concession comes in handy in negotiations — between countries, political parties, or even parents and their kids. Want a raise in your allowance? You may have to agree to do more chores as a concession before your parents will agree."}]},"collocations":{"phrases":["ADJ. important, key, major, significant, substantial | limited, minor, small | special","VERB + CONCESSION grant (sb/sth), make, offer (sb/sth) | get, obtain, win","PREP. ~ on The pressure group has won a number of concessions on environmental policy. | ~ to The firm will be forced to make concessions to","PHRASES make no concessions to sb/sth They made no concessions to his disability. 2 special right to do sth","ADJ. trade","VERB + CONCESSION grant (sb/sth) | obtain, secure, win The company has just won a mining concession in the north of the country. 3 lower cha","ADJ. tax, travel","CONCESSION + VERB be available to travel concessions available to older people"]},"media":{"uk":"media/ldoce/hwd/bre/d/concession0205.mp3","us":"media/ldoce/hwd/ame/6/concession.mp3"},"examples":[{"en":"Adults £2.50, concessions £2, family £5","cn":"成人、优惠、家庭票价分别为 2.50 英镑、2 英镑、5 英镑。"},{"en":"The Bolivian government has granted logging concessions covering 22 million hectares.","cn":"玻利维亚政府批准了在 2 200 万公顷土地上的伐木特许权。"}],"oxford":{"phon":"kənˈseʃn","pos":"noun","senses":[{"en":"something that you allow or do, or allow somebody to have, in order to end an argument or to make a situation less difficult","cn":"让步；妥协","g":"[countable, uncountable]","ex":{"en":"The firm will be forced to make concessions if it wants to avoid a strike.","cn":"要想避免罢工，公司将不得不作出一些让步。"}},{"en":"the act of giving something or allowing something; the act of conceding","cn":"承认；给予；许可；让步","g":"[uncountable]","ex":{"en":"the concession of university status to some colleges","cn":"对某些学院升为大学的许可"}},{"en":"a reduction in an amount of money that has to be paid; a ticket that is sold at a reduced price to a particular group of people","cn":"减价；（对某类人的）减价票","g":"[countable, usually plural]","lab":"British English","ex":{"en":"They may grant tax concessions to encourage foreign investors.","cn":"他们可能会给予税收优惠以鼓励外国投资者。"}},{"en":"a right or an advantage that is given to a group of people, an organization, etc., especially by a government or an employer","cn":"（尤指由政府或雇主给予的）特许权，优惠","g":"[countable]","ex":{"en":"The Bolivian government has granted logging concessions covering 22 million hectares.","cn":"玻利维亚政府批准了在 2 200 万公顷土地上的伐木特许权。"}},{"en":"the right to sell something in a particular place; the place where you sell it, sometimes an area that is part of a larger building or store","cn":"（在某地的）特许经营权；（有时为大型建筑物或商场中的）销售场地，摊位","g":"[countable]","lab":"especially US English","ex":{"en":"the burger concessions at the stadium","cn":"体育场内的汉堡包小吃摊"}}]}},"comical":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"滑稽的;令人发笑的","en":"If you describe something as comical, you mean that it makes you want to laugh because it seems funny or silly.","ex":{"en":"Her expression is almost comical","cn":"她的表情近乎滑稽。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making you laugh","cn":""},{"en":"funny and enjoyable. Amusing is more formal than funny . It is often used when something is a little funny and makes you smile, rather than laugh","cn":""},{"en":"intended to be funny – used about stories, films, articles etc that have situations that are a little funny","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something comical is humorous, amusing, silly, or just plain funny; it makes people laugh."}]},"collocations":{"phrases":["VERBS be, look, sound | become | make sth What made it so comical was that their hats kept falling off.","ADV. extremely, very | almost | faintly, quite, rather, slightly, somewhat He is a faintly comical figure who fears being made fun of."]},"media":{"uk":"media/ldoce/hwd/bre/1/comical0205.mp3","us":"media/ldoce/hwd/ame/2/comical.mp3"},"examples":[{"en":"The note of pure panic in his voice was almost comical.","cn":"他那种十分慌张的口气几乎有点滑稽。"}],"oxford":{"phon":"ˈkɒmɪkl","pos":"adjective","senses":[{"en":"funny, especially because it is strange or silly","cn":"滑稽可笑的；奇特有趣的","ex":{"en":"He is a faintly comical figure who fears being made fun of.","cn":"他是个害怕被别人取笑的有点儿滑稽的人物。"}}]}},"coating":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"涂层;覆盖层","en":"A coating of a substance is a thin layer of it spread over a surface.","ex":{"en":"Under the coating of dust and cobwebs, he discovered a fine French Louis XVI clock.","cn":"在一层灰尘和蜘蛛网底下，他发现了一座精美的法国路易十六时期的时钟。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a thin flat quantity of something that covers the whole of a surface","cn":""},{"en":"a very thin clear layer, especially of something liquid, that has formed on a surface","cn":""},{"en":"a layer of a liquid or soft substance that has been put on the surface of something, for example in order to protect it or make it taste better","cn":""}]},"collocations":{"phrases":["ADJ. thick | fine, thin | outer, surface | protective | magnetic | chocolate, metal, plastic","VERB + COATING be covered in/with, have The fruit is covered in a thick coating of milk chocolate. | apply Apply a thin coating of glue to t"]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdecoating.mp3","us":"media/ldoce/hwd/ame/a/coating.mp3"},"examples":[{"en":"magnetic coating on a floppy disk","cn":"软盘上的磁层"},{"en":"a thin coating of chocolate","cn":"薄薄一层巧克力"}],"oxford":{"phon":"ˈkəʊtɪŋ","pos":"noun","senses":[{"en":"a thin layer of a substance covering a surface","cn":"（薄的）覆盖层，涂层","ex":{"en":"a thin coating of chocolate","cn":"薄薄一层巧克力"}}]},"base":"coat"},"concede":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(勉强)承认，承认…属实","en":"If you concede something, you admit, often unwillingly, that it is true or correct.","ex":{"en":"Bess finally conceded that Nancy was right","cn":"贝丝最终承认了南希是对的。"}},{"pos":"VERB 动词","cn":"赋予，授予(权利、特权)","en":"If you concede something to someone, you allow them to have it as a right or privilege.","ex":{"en":"The government conceded the right to establish independent trade unions","cn":"政府承认建立独立工会的权利。"}},{"pos":"VERB 动词","cn":"让给;让与","en":"If you concede something, you give it to the person who has been trying to get it from you.","ex":{"en":"A strike by some ten thousand bank employees has ended after the government conceded some of their demands.","cn":"政府答应了他们的一些要求后，大约有一万名银行员工参加的罢工结束了。"}},{"pos":"VERB 动词","cn":"(在体育运动中)未能阻止(对方进球或得分)","en":"In sport, if you concede goals or points, you are unable to prevent your opponent from scoring them.","ex":{"en":"They conceded four goals to Leeds United","cn":"他们被利兹联队攻进4个球。"}},{"pos":"VERB 动词","cn":"认输;承认失败","en":"If you concede a game, contest, or argument, you end it by admitting that you can no longer win.","ex":{"en":"Reiner, 56, has all but conceded the race to his rival","cn":"56岁的赖纳在比赛中几乎已经向对手认输了。"}},{"pos":"VERB 动词","cn":"承认(失败);认(输)","en":"If you concede defeat, you accept that you have lost a struggle.","ex":{"en":"Airtours conceded defeat in its attempt to take control of holiday industry rival Owners Abroad","cn":"空中旅游公司承认其对度假服务行业竞争对手海外业主旅行社的控股企图以失败告终。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to agree unwillingly that something is true","cn":""},{"en":"to admit something in a discussion or argument","cn":""},{"en":"to say that something is true or that a situation exists","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If you concede something, you admit that it is true, proper, or certain––usually in an unwilling way and often in the context of a competition, as in \"At midnight, the candidate finally conceded defeat.\""}]},"collocations":{"phrases":["ADV. eventually, finally | readily She readily concedes that there is much work still to be done. | grudgingly, reluctantly He reluctantly c","VERB + CONCEDE be forced to | be prepared to, be willing to He was not prepared to concede that he had acted illegally. | be reluctant to, b","PREP. to The firm should concede a significant salary increase to its employees."]},"media":{"uk":"media/ldoce/hwd/bre/8/concede0205.mp3","us":"media/ldoce/hwd/ame/8/concede.mp3"},"examples":[{"en":"Women were only conceded full voting rights in the 1950s.","cn":"妇女在 20 世纪 50 年代才被容许完全享有选举权。"},{"en":"It must be conceded that different judges have different approaches to these cases.","cn":"必须承认不同的法官会采用不同的方法来判定这些案件。"}],"oxford":{"phon":"kənˈsiːd","pos":"verb","senses":[{"en":"to admit that something is true, logical, etc. after first denying it or resisting it","cn":"（在否认或拒不承认后）承认（某事属实、合乎逻辑等）","g":"[transitive]","lab":"especially British English","ex":{"en":"‘Not bad,’ she conceded grudgingly.","cn":"“不错。”她勉强承认道。"}},{"en":"to admit that you have lost a game, an election, etc.","cn":"承认（比赛、选举等失败）","g":"[intransitive, transitive]","ex":{"en":"After losing this decisive battle, the general was forced to concede.","cn":"输掉了这场决定性的战役后，那位将军不得不承认失败。"}},{"en":"to give something away, especially unwillingly; to allow somebody to have something","cn":"（尤指勉强地）让与，让步；允许","g":"[transitive]","ex":{"en":"The president was obliged to concede power to the army.","cn":"总统被迫把权力让给军队。"}}]}},"coupon":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(购物的)赠券，优惠券","en":"A coupon is a piece of printed paper which allows you to pay less money than usual for a product, or to get it free.","ex":{"en":"Bring the coupon below to any Tecno store and pay just £10.99.","cn":"持下面的优惠券到任意一家Tecno专卖店，只需付10.99英镑。"}},{"pos":"N-COUNT 可数名词","cn":"(剪自报刊的)咨询单，订货单，参赛表","en":"A coupon is a small form, for example in a newspaper or magazine, which you send off to ask for information, to order something, or to enter a competition.","ex":{"en":"Send the coupon with a cheque for £18.50, made payable to 'Good Housekeeping'","cn":"将订单连同一张18.50英镑的支票一同寄出，支票抬头为“《好管家》杂志”。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small piece of printed paper that gives you the right to pay less for something or get something free","cn":"优惠券﹐折价券﹔赠券"},{"en":"a printed form, used when you order something, enter a competition etc","cn":"印刷表格〔如订货单、参赛表格〕"}]},"collocations":{"phrases":["ADJ. valid This coupon is valid until 31 January. | money-off | entry To enter the competition, fill in the entry coupon on page 6. | clothi","VERB + COUPON collect, save She had saved enough coupons to get a free flight. | complete, fill in | post, return, send (off) Cut out and re"]},"media":{"uk":"media/ldoce/hwd/bre/e/coupon0205.mp3","us":"media/ldoce/hwd/ame/e/coupon.mp3"},"examples":[{"en":"Fill in and return the attached coupon.","cn":"填写所附上的参赛表并寄回。"},{"en":"an international reply coupon","cn":"国际通用预付回信邮资券"}],"oxford":{"phon":"ˈkuːpɒn","pos":"noun","senses":[{"en":"a small piece of printed paper that you can exchange for something or that gives you the right to buy something at a cheaper price than normal","cn":"配给券；（购物）票证，优惠券","ex":{"en":"money-off coupons","cn":"优惠券"}},{"en":"a printed form, often cut out from a newspaper, that is used to enter a competition, order goods, etc.","cn":"（常为剪自报章的）参赛表，订货单","ex":{"en":"Fill in and return the attached coupon.","cn":"填写所附上的参赛表并寄回。"}}]}},"conglomerate":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大型联合企业;企业集团","en":"A conglomerate is a large business firm consisting of several different companies.","ex":{"en":"Fiat is Italy's largest industrial conglomerate.","cn":"菲亚特是意大利最大的产业集团。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an organization that makes or sells something, or provides a service","cn":""},{"en":"a company, especially one that provides a service rather than producing goods","cn":""},{"en":"a company – often used when talking about a company that employs only a small number of people","cn":""}]},"vocab":{"pos":"v adj n","senses":[{"en":"A conglomerate is a group of things, especially companies, put together to form one. If you are rich enough to buy a TV network, a record company, several newspapers, and a radio station, you too can own a media conglomerate ."}]},"collocations":{"phrases":["ADJ. big, huge, large, vast | international, multinational | business, financial, industrial | food, media, mining, publishing, etc."]},"media":{"uk":"media/ldoce/hwd/bre/9/conglomerate0205.mp3","us":"media/ldoce/hwd/ame/0/conglomerate.mp3"},"examples":[{"en":"a media conglomerate","cn":"大众传媒联合体"},{"en":"an international conglomerate","cn":"国际大型联合企业"}],"oxford":{"phon":"kənˈɡlɒmərət","pos":"noun","senses":[{"en":"a large company formed by joining together different firms","cn":"联合大公司；企业集团","g":"[countable]","lab":"business","ex":{"en":"He turned the business into a huge media conglomerate.","cn":"他令公司成为一个庞大的大众传媒联合集团。"}},{"en":"a number of things or parts that are put together to form a whole","cn":"合成物；组合物；聚合物","g":"[singular]","lab":"formal"},{"en":"a type of rock made of small stones held together by dried clay","cn":"砾岩","g":"[uncountable]","lab":"geology"}]}},"contributor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指不愉快事件的)促成因素，原因之一","en":"You can use contributor to refer to one of the causes of an event or situation, especially if that event or situation is an unpleasant one.","ex":{"en":"Old buses are major contributors to pollution in British cities","cn":"破旧的公交车是造成英国城市污染的主要因素。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who gives money, help, ideas etc to something that a lot of other people are also involved in","cn":"捐款人﹔捐助人﹔做出贡献的人"},{"en":"someone who writes a story, song, speech etc that forms part of a larger work such as a newspaper, book, broadcast, recording etc","cn":"撰稿人﹔投稿人"},{"en":"someone or something that helps to cause something to happen","cn":"导致某事的人[事]﹔起作用的人[因素]﹔促成者[因素]"}]},"vocab":{"pos":"n","senses":[{"en":"A contributor is someone who takes part in something or makes a contribution . Writers and people who donate money in particular are called contributors ."}]},"collocations":{"phrases":["ADJ. important, significant | big, large | main, principal | net net contributors to the economy | regular The core of regular contributors ","PREP. ~ to Carbon dioxide is the largest contributor to the greenhouse effect."]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41contributor.mp3","us":"media/ldoce/hwd/ame/0/contributor.mp3"},"examples":[{"en":"Sulphur dioxide is a pollutant and a major contributor to acid rain.","cn":"二氧化硫是一种污染物，并且是形成酸雨的主要因素。"},{"en":"Older people are important contributors to the economy.","cn":"老一辈人为发展经济作出了重要贡献。"}],"oxford":{"phon":"kənˈtrɪbjətə(r)","pos":"noun","senses":[{"en":"a person who writes articles for a magazine, book or website, or who talks on a radio or television programme or at a meeting","cn":"（杂志、书或网站的）撰稿人，投稿人；（电台、电视节目中的）嘉宾；（会议的）发言人","ex":{"en":"a regular contributor to this magazine","cn":"该杂志的定期撰稿人"}},{"en":"a person or thing that provides money or goods to help pay for or support something","cn":"捐款者；捐赠者；作出贡献者","ex":{"en":"Older people are important contributors to the economy.","cn":"老一辈人为发展经济作出了重要贡献。"}},{"en":"something that helps to cause something","cn":"促成物","ex":{"en":"Sulphur dioxide is a pollutant and a major contributor to acid rain.","cn":"二氧化硫是一种污染物，并且是形成酸雨的主要因素。"}}]}},"consternation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"不安;忧虑;害怕","en":"Consternation is a feeling of anxiety or fear.","ex":{"en":"His decision caused consternation in the art photography community","cn":"他的决定在艺术摄影圈内引起了恐慌。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a feeling of worry, shock, or fear","cn":"惊愕﹔震惊﹔惊惶失措"}]},"vocab":{"pos":"n","senses":[{"en":"Consternation is a noun that can stop you in your tracks because it means \"a sudden, alarming amazement or dread that results in utter confusion; dismay.\""}]},"collocations":{"phrases":["ADJ. considerable, great | widespread","VERB + CONSTERNATION cause, create, fill sb with The announcement created surprise and consternation. The thought of meeting him filled me w","PREP. in ~ She stared at me in consternation. | ~ among There is some consternation among business leaders."]},"media":{"uk":"media/ldoce/hwd/bre/7/consternation0205.mp3","us":"media/ldoce/hwd/ame/c/consternation.mp3"},"examples":[{"en":"The announcement of her retirement caused consternation among tennis fans.","cn":"她宣布挂拍告退的消息引起了网球迷的震惊。"},{"en":"The government’s plans have caused considerable consternation among many Americans.","cn":"政府的计划在许多美国人中间引起了相当大的恐慌。"}],"oxford":{"phon":"ˌkɒnstəˈneɪʃn","pos":"noun","senses":[{"en":"a worried, sad feeling after you have received an unpleasant surprise","cn":"惊愕；惊恐","ex":{"en":"The announcement of her retirement caused consternation among tennis fans.","cn":"她宣布挂拍退役的消息引起了网球迷的震惊。"}}]}},"costume":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(演员或表演者的)戏服，表演服装","en":"An actor's or performer's costume is the set of clothes they wear while they are performing.","ex":{"en":"Even from a distance the effect of his fox costume was stunning","cn":"即使从远处看,他的狐狸戏服也很抢眼。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(某历史时期或某国的)服装，装束","en":"The clothes worn by people at a particular time in history, or in a particular country, are referred to as a particular type of costume .","ex":{"en":"...men and women in eighteenth-century costume","cn":"身穿18世纪服装的男男女女"}},{"pos":"ADJ 形容词","cn":"(戏剧)古装的","en":"A costume play or drama is one which is set in the past and in which the actors wear the type of clothes that were worn in that period.","ex":{"en":"...a lavish costume drama set in Ireland and the US in the 1890s.","cn":"一部耗资巨大、以19世纪90年代的爱尔兰和美国为背景的古装戏"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a pair of trousers or a skirt, that you wear with a short coat made of the same material","cn":""},{"en":"a set of clothes that look attractive together, that you wear for a special occasion - use this especially about women's clothes","cn":""},{"en":"a set of clothes for acting in a play or performance or that you wear for a party to make you look like someone or something else","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A costume is a set of clothes you wear when you want to dress up like another person. You might wear a witch's costume to go trick-or-treating on Halloween, or put on a George Washington costume to reenact a scene from the American Revolution in a play."}]},"collocations":{"phrases":["ADJ. full For the dress rehearsal, the cast will be in full costume. | colourful, elaborate, lavish | national, traditional | period | eight","VERB + COSTUME be dressed in, dress in, have on, wear He had a cowboy costume on.","COSTUME + NOUN design | designer | drama The film is a costume drama based on a 19th-century novel. | change The main character had five cos","PREP. in ~ The battle was re-enacted by actors in period costume."]},"media":{"uk":"media/ldoce/hwd/bre/e/costume0205.mp3","us":"media/ldoce/hwd/ame/f/costume.mp3"},"examples":[{"en":"He went to the party in a giant chicken costume.","cn":"他是打扮成一只大鸡去参加聚会的。"},{"en":"She has four costume changes during the play.","cn":"她在这出戏里要换四次服装。"}],"oxford":{"phon":"ˈkɒstjuːm","pos":"noun","senses":[{"en":"the clothes worn by people from a particular place or during a particular historical period","cn":"（某地或某历史时期的）服装，装束","g":"[countable, uncountable]","ex":{"en":"an exhibition of Victorian costumes","cn":"维多利亚时代服装展"}},{"en":"the clothes worn by actors in a play or film, or worn by somebody to make them look like somebody/something else","cn":"戏装；装扮用服装","g":"[countable, uncountable]","ex":{"en":"The former dancer has also designed the costumes.","cn":"这位前舞者还设计了服装。"}},{"en":"a piece of clothing worn for swimming, especially the type worn by women and girls","cn":"（尤指女式）游泳衣","g":"[countable]","lab":"both British English","ex":{"en":"If you’d like a swim, we can lend you a costume.","cn":"如果你想游泳，我们可以借给你一套泳衣。"}}]}},"counselling":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(治疗师或其他专家提供的)咨询，建议","en":"Counselling is advice which a therapist or other expert gives to someone about a particular problem.","ex":{"en":"She will need medical help and counselling to overcome the tragedy","cn":"她需要借助医学治疗和心理咨询来克服惨剧带来的影响。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"what someone advises you to do","cn":""},{"en":"a simple but useful piece of advice about how to do something more easily or effectively","cn":""},{"en":"advice about how to deal with a problem, especially given by a group of people who have made a detailed study of it","cn":""}]},"collocations":{"phrases":["ADJ. group, individual | professional | proper | abortion, bereavement, business, career, debt, family, marriage guidance, retirement, stres","VERB + COUNSELLING give sb, offer (sb), provide (sb with) | have, receive | be in need of, need Many of the victims of the tragedy still nee","COUNSELLING + NOUN service the new student counselling and guidance service | session | skills","PREP. ~ for counselling for parents and children counselling for depression"]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdecounselling.mp3","us":"media/ldoce/hwd/ame/1/laadcounseling.mp3"},"examples":[{"en":"marriage guidance counselling","cn":"婚姻指导咨询"},{"en":"a student counselling service","cn":"学生辅导服务"}],"oxford":{"phon":"ˈkaʊnsəlɪŋ","pos":"noun","senses":[{"en":"professional advice about a problem","cn":"咨询；辅导","ex":{"en":"The couple decided to go for relationship counselling.","cn":"这对夫妇决定去寻求关系咨询。"}}]},"base":"counsel"},"compensate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"赔偿;补偿","en":"To compensate someone for money or things that they have lost means to pay them money or give them something to replace that money or those things.","ex":{"en":"The official promise to compensate people for the price rise clearly hadn't been worked out properly","cn":"显然，官方对物价上涨进行补偿的承诺没有真正兑现。"}},{"pos":"VERB 动词","cn":"弥补;补偿","en":"If you compensate for a lack of something or for something you have done wrong, you do something to make the situation better.","ex":{"en":"The company agreed to keep up high levels of output in order to compensate for supplies lost","cn":"这家公司同意保持高产量以弥补供货丢失带来的缺口。"}},{"pos":"VERB 动词","cn":"抵消","en":"Something that compensates for something else balances it or reduces its effects.","ex":{"en":"MPs say it is crucial that a system is found to compensate for inflation","cn":"下议院的议员们说关键是要找到一种抵消通货膨胀影响的机制。"}},{"pos":"VERB 动词","cn":"弥补(过失或不足)","en":"If you try to compensate for something that is wrong or missing in your life, you try to do something that removes or reduces the harmful effects.","ex":{"en":"People who sense that they are inferior have to compensate, and often over-compensate by way of outward achievement.","cn":"觉得自卑的人只有通过外在的成就来弥补自己的不足，但往往都做过了头。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to change things so that people are treated equally, especially in their employment","cn":""},{"en":"if two amounts, numbers etc balance out , they become equal or have an equal effect, especially if this happens over a fairly long period of time","cn":""},{"en":"if two amounts, or levels even out or you even them out , the differences between them gradually become smaller","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"Compensate is about correcting for an imbalance. If you step in an unmarked pothole, the city may compensate you by paying your doctor bills treating a broken ankle."}]},"collocations":{"phrases":["ADV. amply, fully | more than The advantages of the scheme more than compensate for the risks associated with it. | partially, partly","PREP. for 2 pay money for a loss/injury","ADV. adequately, properly | fully, in full People whose health has suffered will be compensated in full. | financially I expect to be compen","PREP. for The company will compensate you for the losses you have suffered."]},"media":{"uk":"media/ldoce/hwd/bre/9/compensate0205.mp3","us":"media/ldoce/hwd/ame/5/compensate.mp3"},"examples":[{"en":"Her lawyers say she should be compensated for the suffering she had been caused.","cn":"她的律师说她应该为所遭受的痛苦得到赔偿。"},{"en":"He received a compensatory payment of $20 000.","cn":"他获得了 2 万元的赔偿金。"}],"oxford":{"phon":"ˈkɒmpenseɪt","pos":"verb","senses":[{"en":"to provide something good to balance or reduce the bad effects of damage, loss, etc.","cn":"补偿；弥补","g":"[intransitive]","ex":{"en":"Nothing can compensate for the loss of a loved one.","cn":"失去心爱的人是无法弥补的。"}},{"en":"to act in order to balance or correct something wrong or not normal","cn":"补偿；纠正；弥补","g":"[intransitive]","ex":{"en":"In the second experiment, the temperature was raised to compensate for this bias.","cn":"在第二个实验中，温度被升高以校正这一偏差。"}},{"en":"to pay somebody money because they have suffered some damage, loss, injury, etc.","cn":"给（某人）赔偿","g":"[transitive]","ex":{"en":"Her lawyers say she should be compensated for the suffering she had been caused.","cn":"她的律师说她应该为所遭受的痛苦得到赔偿。"}}]}},"conservatism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(政治)保守主义;保守党的政治主张","en":"Conservatism is a political philosophy which believes that if changes need to be made to society, they should be made gradually. You can also refer to the political beliefs of a conservative party in a particular country as Conservatism .","ex":{"en":"...the philosophy of modern Conservatism.","cn":"现代保守主义哲学"}},{"pos":"N-UNCOUNT 不可数名词","cn":"保守;守旧","en":"Conservatism is unwillingness to accept changes and new ideas.","ex":{"en":"The conservatism of the literary establishment in this country is astounding","cn":"这个国家文学界的因循守旧令人震惊。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"dislike of change and new ideas","cn":"守旧﹐保守主义"},{"en":"the political belief that society should change as little as possible 〔","cn":"政治上的〕保守主义"},{"en":"the political beliefs of the British Conservative Party 〔","cn":"英国〕保守党的政治主张"}]},"vocab":{"pos":"n","senses":[{"en":"When people discuss politics and mention the word conservatism , they're talking about a philosophy that favors making few changes in society, sticking with traditions, and often spending as little money as possible."}]},"collocations":{"phrases":["ADJ. diehard, entrenched | moderate, relative | inherent, innate, natural the innate conservatism of British businessmen | economic, fiscal,","PREP. ~ in people's conservatism in musical taste"]},"media":{"uk":"media/ldoce/hwd/bre/8/conservatism0205.mp3","us":"media/ldoce/hwd/ame/9/conservatism.mp3"},"examples":[{"en":"an examination of the political theories of conservatism and liberalism","cn":"对保守主义和自由主义政治理论的审视"},{"en":"the innate conservatism of older people","cn":"老年人固有的保守性"}],"oxford":{"phon":"kənˈsɜːvətɪzəm","pos":"noun","senses":[{"en":"the wish to resist great or sudden change","cn":"保守；守旧","ex":{"en":"the innate conservatism of older people","cn":"老年人固有的保守性"}},{"en":"the political belief that society should change as little as possible","cn":"保守主义","ex":{"en":"an examination of the political theories of conservatism and liberalism","cn":"对保守主义和自由主义政治理论的审视"}},{"en":"the principles of the Conservative Party in British politics","cn":"（英国）保守党的原则"}]}},"constipated":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"便秘的","en":"Someone who is constipated has difficulty in getting rid of solid waste from their body."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"pain in your stomach or near your stomach","cn":""},{"en":"pain or uncomfortable feelings that you get when your stomach cannot break down food that you have eaten","cn":""},{"en":"a stomach illness caused by eating food that contains harmful bacteria, so that you vomit","cn":""}]},"collocations":{"phrases":["VERBS be | become, get | make sb","ADV. severely, very | a bit, slightly"]},"media":{"uk":"media/ldoce/hwd/bre/d/constipation0205.mp3","us":"media/ldoce/hwd/ame/e/constipation.mp3"},"oxford":{"phon":"ˈkɒnstɪpeɪtɪd","pos":"adjective","senses":[{"en":"unable to get rid of waste material from the bowels easily","cn":"便秘的","ex":{"en":"You should eat more fibre and fruit if you are constipated.","cn":"如果你便秘，你应该多吃纤维和水果。"}}]}},"commentator":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"解说员;实况播音员","en":"A commentator is a broadcaster who gives a radio or television commentary on an event.","ex":{"en":"...a sports commentator.","cn":"体育解说员"}},{"pos":"N-COUNT 可数名词","cn":"评论员","en":"A commentator is someone who often writes or broadcasts about a particular subject.","ex":{"en":"...a political commentator","cn":"政治评论员"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone on a television or radio programme who tells you what the programme will be about, and introduces the other people in it","cn":""},{"en":"someone on a television or radio programme who tells you what the programme will be about, or who tells you about a sports game as it is happening","cn":""},{"en":"someone who introduces the people on a show and who talks to people or about reports or scenes included in the programme - use this especially about talk shows, game shows, or quiz shows","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A person who analyzes and discusses topics in politics and sports is called a commentator . If you want to hear opinions on the news rather than the news itself, listen to commentators ."}]},"collocations":{"phrases":["ADJ. cricket, football, rugby, sports, etc. | match, race | radio, television/TV • Note at JOB 2 person who gives opinions on sth in the med","ADJ. influential | independent | foreign | media | cultural, economic, political, social Political commentators are predicting that the mini","PREP. ~ on a commentator on current affairs"]},"media":{"uk":"media/ldoce/hwd/bre/e/commentator0205.mp3","us":"media/ldoce/hwd/ame/8/commentator.mp3"},"examples":[{"en":"a television/sports commentator","cn":"电视台/体育运动实况解说员"},{"en":"a political commentator","cn":"政治评论员"}],"oxford":{"phon":"ˈkɒmənteɪtə(r)","pos":"noun","senses":[{"en":"a person who describes an event while it is happening, especially on television or radio","cn":"（尤指电视台或电台的）现场解说员，实况播音员","ex":{"en":"a television/sports commentator","cn":"电视台／体育运动实况解说员"}},{"en":"a person who is an expert on a particular subject and talks or writes about it on television or radio, in a newspaper or on social media","cn":"（电视台、电台、报章或社交媒体的）评论员","ex":{"en":"She's a political commentator for the BBC.","cn":"她是英国广播公司的政治评论员。"}}]}},"conversion":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"变换;转换;转变;改变","en":"Conversion is the act or process of changing something into a different state or form.","ex":{"en":"...the conversion of disused rail lines into cycle routes","cn":"将废弃的铁路线改成自行车道"}},{"pos":"N-VAR 可变名词","cn":"(宗教、信仰等的)改变，皈依，归附","en":"If someone changes their religion or beliefs, you can refer to their conversion to their new religion or beliefs.","ex":{"en":"...his conversion to Christianity","cn":"他皈依基督教"}},{"pos":"N-COUNT 可数名词","cn":"(橄榄球运动中的)附加得分","en":"In rugby, if a player makes or kicks a conversion, he scores points by kicking the ball over the goal after a try has been scored."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the process of changing something from one form or system to another one so that it can be used for a different purpose","cn":""},{"en":"the process of changing something in particular ways so that it can be used for a different purpose","cn":""},{"en":"when you change something from one form, purpose, or system to a different one","cn":"转变﹔改造﹔转换﹔换算"}]},"vocab":{"pos":"1 n 2 n 3 n 4 n 5 n","senses":[{"en":"Something that is transformed from one state or form to another has had a conversion . The twentieth century saw the conversion from outhouses to indoor plumbing. You may oversee the conversion of your attic into an extra bedroom."}]},"collocations":{"phrases":["ADJ. careful Today, after a careful conversion, it is a very comfortable and elegant country home. | barn, loft | office | currency There ar","VERB + CONVERSION carry out, undertake","PREP. ~ from, ~ into A local building firm will carry out the conversion of the farm buildings into business units. | ~ to conversion from a","ADJ. religious | deathbed | overnight, sudden (figurative) her overnight conversion to market economics","VERB + CONVERSION experience, undergo In the late eighties he underwent a religious conversion.","CONVERSION + NOUN experience","PREP. ~ from, ~ to her conversion from Buddhism to Christianity 3 in rugby","VERB + CONVERSION kick | add The try came in the third minute and Jon Bland added the conversion."]},"media":{"uk":"media/ldoce/hwd/bre/7/conversion0205.mp3","us":"media/ldoce/hwd/ame/1/conversion.mp3"},"examples":[{"en":"the conversion of the Anglo-Saxons by Christian missionaries","cn":"基督教传教士使盎格鲁 – 撒克逊人的信仰改变"},{"en":"No conversion from analogue to digital data is needed.","cn":"没有必要把模拟转换为数字数据。"}],"oxford":{"phon":"kənˈvɜːʃn","pos":"noun","senses":[{"en":"the act or process of changing something from one form, use or system to another","cn":"转变；转换；转化","g":"[uncountable, countable]","ex":{"en":"Their main business is the conversion of farm buildings into family homes.","cn":"他们的主要业务是将农场建筑物改建为家庭住宅。"}},{"en":"the process or experience of changing somebody's or your own religion or beliefs","cn":"（宗教或信仰的）改变；皈依；归附","g":"[uncountable, countable]","ex":{"en":"the conversion of the Anglo-Saxons by Christian missionaries","cn":"基督教传教士使盎格鲁–撒克逊人的信仰改变"}},{"en":"a way of scoring extra points after scoring a try or a touchdown","cn":"（持球过对方球门线触地或达阵后的）附加攻门（得分）","g":"[countable]","ex":{"en":"The try came in the third minute and Jon Bland added the conversion.","cn":"第三分钟，乔恩・布兰德踢定位球又拿到了附加分。"}},{"en":"a building or room that has been changed so that it can be used for a different purpose, especially for living in","cn":"（尤指为居住而）改建的房屋","g":"[countable]"}]}},"comply":{"collins":{"senses":[{"pos":"VERB 动词","cn":"服从;遵守","en":"If someone or something complies with an order or set of rules, they are in accordance with what is required or expected.","ex":{"en":"The commander said that the army would comply with the ceasefire","cn":"指挥官说军队会遵守停火协议。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do what a law or rule says you must do","cn":""},{"en":"if you comply with a law or a decision, you do what it says you must do","cn":""},{"en":"to accept and obey a decision, rule, agreement etc, even though you may not agree with it","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Comply is to act according to someone's wishes or rules. Although you might like to stay out with your friends, you'll have to comply with your parents' rules and be home by midnight."}]},"collocations":{"phrases":["ADV. fully, strictly","VERB + COMPLY fail to, refuse to When requested to leave, they refused to comply.","PREP. with Candidates must comply strictly with these instructions."]},"media":{"uk":"media/ldoce/hwd/bre/9/comply0205.mp3","us":"media/ldoce/hwd/ame/2/comply.mp3"},"examples":[{"en":"They refused to comply with the UN resolution.","cn":"他们拒绝遵守联合国的决议。"},{"en":"Failure to comply with the regulations will result in prosecution.","cn":"违反规定者将被起诉。"}],"oxford":{"phon":"kəmˈplaɪ","pos":"verb","senses":[{"en":"to obey a rule, an order, etc.; to meet particular standards","cn":"遵从；服从；符合","ex":{"en":"They refused to comply with the UN resolution.","cn":"他们拒绝遵守联合国的决议。"}}]}},"courier":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"快递员;信使;快递公司","en":"A courier is a person who is paid to take letters and parcels direct from one place to another.","ex":{"en":"He worked as a motorcycle courier","cn":"他的工作是骑摩托车送快递。"}},{"pos":"N-COUNT 可数名词","cn":"(旅游公司的)导游","en":"A courier is a person employed by a travel company to look after people who are on holiday."},{"pos":"VERB 动词","cn":"让快递员送;快递","en":"If you courier something somewhere, you send it there by courier.","ex":{"en":"I couriered it to Darren in New York.","cn":"我把它快递给纽约的达伦。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who takes a message or whose job it is to take messages","cn":""},{"en":"someone whose job it is to carry urgent messages, letters, parcels etc, especially for a company","cn":""},{"en":"someone who takes messages between two people or groups because they are not able to meet or do not want to meet","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A courier is a person you trust with delivering important messages or packages. Let the mailman deliver your electric bill and the form letter from the “Save the Orchids” foundation, but only trust a courier with your book contract or birth certificate.."}]},"collocations":{"phrases":["ADJ. diplomatic | drug | cycle, motorcycle","VERB + COURIER act as He has admitted to acting as a drug courier. | send sth by Urgent deliveries of medicine may be sent by motorcycle cou"]},"media":{"uk":"media/ldoce/hwd/bre/a/courier_v0205.mp3","us":"media/ldoce/hwd/ame/4/courier1.mp3"},"examples":[{"en":"Courier that letter — it needs to get there today (= send it by courier ).","cn":"那封信必须今天到达，用专递寄吧。"},{"en":"We sent the documents by courier.","cn":"我们派了信使送交这些文件。"}],"oxford":{"phon":"ˈkʊriə(r)","pos":"noun","senses":[{"en":"a person or company whose job is to take packages or important papers somewhere","cn":"（递送包裹或重要文件的）信使，通讯员，专递公司","ex":{"en":"We sent the documents by courier.","cn":"我们派了信使送交这些文件。"}},{"en":"a person who is employed by a travel company to give advice and help to a group of tourists on holiday","cn":"（旅游公司的）导游","lab":"British English"},{"en":"to send a package, important papers, etc. by courier (= not by normal post)","cn":"（递送包裹或重要文件的）信使，通讯员，专递公司","ex":{"en":"Courier that letter—it needs to get there today.","cn":"那封信必须今天到达，用专递寄吧。"},"pos":"verb"}]}},"competitor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"竞争者;对手","en":"A company's competitors are companies who are trying to sell similar goods or services to the same people.","ex":{"en":"The bank isn't performing as well as some of its competitors.","cn":"这家银行表现得不如几家竞争对手出色。"}},{"pos":"N-COUNT 可数名词","cn":"选手;参赛者","en":"A competitor is a person who takes part in a competition or contest.","ex":{"en":"Herbert Blocker of Germany, one of the oldest competitors, won the individual silver medal.","cn":"德国的赫伯特·布洛克尔是年纪最大的选手之一，赢得了个人项目的银牌。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a person or company that tries to do better than another that offers similar goods or services","cn":""},{"en":"a person, team, or company that tries to do better than another similar one, especially over a long period","cn":""},{"en":"all the people or groups that are trying to do better than you, especially in business","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Competitors are rivals or contenders for the same thing. Two boxers in a ring are competitors , and so are restaurants located on the same block."}]},"collocations":{"phrases":["ADJ. biggest, chief, leading, main, major | fierce, serious, strong The company has no serious competitors in this area. | closest, direct, ","PREP. ~ for fierce competitors for the dominant position in the Asian market 2 person who takes part in a competition","ADJ. strong, top She is one of the sport's top competitors. | successful","COMPETITOR + VERB enter sth Ten competitors entered the race."]},"media":{"uk":"media/ldoce/hwd/bre/c/competitor0205.mp3","us":"media/ldoce/hwd/ame/2/competitor.mp3"},"examples":[{"en":"Over 200 competitors entered the race. * 200","cn":"多名选手参加了赛跑。"},{"en":"Over 200 competitors entered the race.","cn":""}],"oxford":{"phon":"kəmˈpetɪtə(r)","pos":"noun","senses":[{"en":"a person who takes part in a competition","cn":"参赛者；竞赛者","ex":{"en":"Over 200 competitors entered the race.","cn":"200 多名选手参加了赛跑。"}},{"en":"a person or an organization that competes against others, especially in business","cn":"（尤指商业方面的）竞争者，对手","ex":{"en":"We produce cheaper goods than our competitors.","cn":"我们生产的商品比竞争对手更便宜。"}}]}},"compartment":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(火车上的)分隔厢，隔间","en":"A compartment is one of the separate spaces into which a railway carriage is divided.","ex":{"en":"On the way home we shared our first class compartment with a group of businessmen.","cn":"回家的路上，我们和一群生意人一起坐在一等车厢。"}},{"pos":"N-COUNT 可数名词","cn":"格;分隔间;隔层","en":"A compartment is one of the separate parts of an object that is used for keeping things in.","ex":{"en":"I put a bottle of champagne in the freezer compartment.","cn":"我把一瓶香槟放进冷冻室。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a smaller enclosed space inside something larger","cn":"隔层﹔分隔间"},{"en":"one of the separate areas into which a plane, ship, or train is divided 〔","cn":"飞机﹑轮船或火车上的〕隔间﹐舱"}]},"vocab":{"pos":"n","senses":[{"en":"A compartment is a space within another space, like the glove compartment in a car."}]},"collocations":{"phrases":["ADJ. first-class, second-class | non-smoking, smoking | passenger, sleeping, luggage","PREP. in a/the ~ 2 section of a container, etc.","ADJ. separate | secret | battery, freezer, glove, storage Your sunglasses are in the glove compartment.","VERB + COMPARTMENT be divided into The case is divided into four separate compartments.","PREP. in a/the ~"]},"media":{"uk":"media/ldoce/hwd/bre/d/compartment0205.mp3","us":"media/ldoce/hwd/ame/f/compartment.mp3"},"examples":[{"en":"There is a handy storage compartment beneath the oven.","cn":"在烤箱的下面有一个便利的橱柜。"},{"en":"The desk has a secret compartment.","cn":"这书桌有一个秘密隔层。"}],"oxford":{"phon":"kəmˈpɑːtmənt","pos":"noun","senses":[{"en":"one of the separate sections that something such as a piece of furniture or equipment has for keeping things in","cn":"（家具或设备等的）分隔间，隔层","ex":{"en":"The desk has a secret compartment.","cn":"这书桌有一个秘密暗格。"}},{"en":"one of the separate sections that a coach on a train is divided into","cn":"（列车车厢的）隔间，包厢","ex":{"en":"He found an empty first-class compartment.","cn":"他在头等车厢找到了一个空着的隔间。"}}]}},"consult":{"collins":{"senses":[{"pos":"VERB 动词","cn":"咨询;请教;请示(以获得许可)","en":"If you consult an expert or someone senior to you or consult with them, you ask them for their opinion and advice about what you should do or their permission to do something.","ex":{"en":"Consult your doctor about how much exercise you should attempt","cn":"咨询一下医生你需要多大的运动量。"}},{"pos":"V-RECIP 相互动词","cn":"商量;商讨;商议","en":"If a person or group of people consults with other people or consults them, they talk and exchange ideas and opinions about what they might decide to do.","ex":{"en":"After consulting with her daughter and manager she decided to take on the part, on her terms","cn":"与女儿兼经纪人商量之后，她决定出演这一角色，不过要按照她开出的条件。"}},{"pos":"VERB 动词","cn":"查阅，查询(书、地图等)","en":"If you consult a book or a map, you look in it or look at it in order to find some information.","ex":{"en":"Consult the chart on page 44 for the correct cooking times","cn":"翻到44页的图表，查一下正确的烹饪时间。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to get advice from someone who is trained in a particular profession, for example a lawyer or a doctor","cn":""},{"en":"to go to someone and ask them for for their advice, especially a professional person such as a lawyer or doctor. See is the usual word to use in everyday English","cn":""},{"en":"to ask someone to tell you what they think you should do in a particular situation","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To consult is to give or get help or advice. When you don't know the meaning of a word, you consult a dictionary. That's why you're here, right?"}]},"collocations":{"phrases":["ADV. widely We consulted quite widely before deciding what to do. | closely | adequately, properly They felt they had not been properly cons","VERB + CONSULT need to, should If the pain persists you should consult your doctor.","PREP. about I need to consult my teacher about changing my course. | with We are consulting closely with our partners and allies."]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdeconsult.mp3","us":"media/ldoce/hwd/ame/4/consult.mp3"},"examples":[{"en":"If the pain continues, consult your doctor.","cn":"如果疼痛持续不消退，要请医生诊治。"},{"en":"Consult with your physician about possible treatments.","cn":"向你的医生咨询可行的治疗方案。"}],"oxford":{"phon":"kənˈsʌlt","pos":"verb","senses":[{"en":"to go to somebody for information or advice","cn":"咨询；请教","g":"[transitive, intransitive]","lab":"North American English","ex":{"en":"If the pain continues, consult your doctor.","cn":"如果疼痛持续，要请医生诊治。"}},{"en":"to discuss something with somebody to get their permission for something, or to help you make a decision","cn":"（与某人）商议，商量（以得到许可或帮助决策）","g":"[transitive, intransitive]","ex":{"en":"You shouldn't have done it without consulting me.","cn":"你不该不和我商量就做了这件事。"}},{"en":"to look in or at something to get information","cn":"查阅；查询；参看","g":"[transitive]","ex":{"en":"He consulted the manual.","cn":"他查阅了使用说明书。"}}]}},"counterintuitive":{"vocab":{"pos":"adj","senses":[{"en":"If something is counterintuitive it means it's the opposite of \"intuitive\" — in other words it's not easily understood in an instinctive, unconscious way. A red light for \"go\" and a green light for \"stop\" would be highly counterintuitive, for example."}]}},"collaborate":{"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"合作，协作(尤指著书或做研究)","en":"When one person or group collaborates with another, they work together, especially on a book or on some research.","ex":{"en":"He collaborated with his son Michael on the English translation of a text on food production","cn":"他和儿子迈克尔合作，把一篇介绍食品生产的文章译成了英文。"}},{"pos":"VERB 动词","cn":"通（敌）;勾结(敌人)","en":"If someone collaborates with an enemy that is occupying their country during a war, they help them.","ex":{"en":"He was accused of having collaborated with the secret police.","cn":"他被控与秘密警察勾结。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be disloyal to your country, for example by helping its enemies or giving them secret information","cn":""},{"en":"to betray your country by helping its enemies when they have defeated your country and taken control of it","cn":""},{"en":"the crime of betraying your country by helping its enemies","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you work together on shared goal, you collaborate . If you don't just split a project up evenly but work together on creating solutions, you collaborate ."}]},"collocations":{"phrases":["ADV. actively, closely","PREP. on, with We have collaborated closely with the university on this project."]},"media":{"uk":"media/ldoce/hwd/bre/4/collaborate0205.mp3","us":"media/ldoce/hwd/ame/a/collaborate.mp3"},"examples":[{"en":"Researchers around the world are collaborating to develop a new vaccine.","cn":"世界各地的研究人员正在合作培育一种新的疫苗。"},{"en":"We have collaborated on many projects over the years.","cn":"这些年来我们合作搞了许多项目。"}],"oxford":{"phon":"kəˈlæbəreɪt","pos":"verb","senses":[{"en":"to work together with somebody in order to produce or achieve something","cn":"合作；协作","g":"[intransitive]","ex":{"en":"Researchers around the world are collaborating to develop a new vaccine.","cn":"世界各地的研究人员正在合作培育一种新的疫苗。"}},{"en":"to help the enemy who has taken control of your country during a war","cn":"通敌；勾结敌人","g":"[intransitive]","lab":"disapproving","ex":{"en":"He was accused of collaborating with the enemy.","cn":"他被指控与敌人勾结。"}}]}},"correspondent":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指专门报道某一类新闻的)记者，通讯员","en":"A correspondent is a newspaper or television journalist, especially one who specializes in a particular type of news.","ex":{"en":"...our Diplomatic Correspondent Mark Brayne.","cn":"我们的外交通讯员马克·布雷恩"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who writes for a newspaper or magazine","cn":""},{"en":"someone whose job is to find out about news stories and ask questions for a newspaper, television or radio company etc","cn":""},{"en":"someone who writes news articles or does reports about a particular subject, especially a serious one, for a newspaper or news organization","cn":""}]},"collocations":{"phrases":["ADJ. newspaper, television | business, education, foreign, health, industrial, legal affairs, media, parliamentary, political, royal, scienc","CORRESPONDENT + VERB write (sth)"]},"media":{"uk":"media/ldoce/hwd/bre/9/correspondent0205.mp3","us":"media/ldoce/hwd/ame/8/correspondent1.mp3"},"examples":[{"en":"She's a poor correspondent (= she does not write regularly).","cn":"她是个懒于写信的人。"},{"en":"the BBC's political correspondent","cn":"英国广播公司的政治新闻记者"}],"oxford":{"phon":"ˌkɒrəˈspɒndənt","pos":"noun","senses":[{"en":"a person who reports news from a particular country or on a particular subject for a newspaper or a television or radio station","cn":"记者；通讯员","ex":{"en":"She's the BBC's political correspondent.","cn":"她是英国广播公司的政治新闻记者。"}},{"en":"a person who writes letters, emails, etc. to another person","cn":"通信者；（电子邮件等的）联系人","ex":{"en":"She's a poor correspondent (= she does not write regularly).","cn":"她是个懒于写信的人。"}}]}},"conceal":{"collins":{"senses":[{"pos":"VERB 动词","cn":"掩盖;隐藏","en":"If you conceal something, you cover it or hide it carefully.","ex":{"en":"Frances decided to conceal the machine behind a hinged panel","cn":"弗朗西斯决定把机器藏在带铰链的嵌板的后面。"}},{"pos":"VERB 动词","cn":"隐瞒（信息);掩饰(感情)","en":"If you conceal a piece of information or a feeling, you do not let other people know about it.","ex":{"en":"Robert could not conceal his relief","cn":"罗伯特无法掩饰自己如释重负的心情。"}},{"pos":"VERB 动词","cn":"掩盖;遮住","en":"If something conceals something else, it covers it and prevents it from being seen.","ex":{"en":"...a pair of carved Indian doors which conceal a built-in cupboard","cn":"嵌入式壁橱上的一对印度雕花门"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something difficult to see or find, or to not show your true feelings","cn":""},{"en":"to hide something, especially by carefully putting it somewhere. Also used when talking about hiding your feelings, especially in negative sentences","cn":""},{"en":"to put something over another thing that you do not want people to see, in order to hide it completely","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you conceal something, you are keeping it from being discovered: “To avoid another argument with his cousins, Jonathan worked hard to conceal his disappointment at the outcome of the race.”"}]},"collocations":{"phrases":["ADV. completely | partially, partly | barely, scarcely He waited with barely concealed impatience. | carefully, cleverly, cunningly | dishon","VERB + CONCEAL be able/unable to She was unable to conceal her surprise. | try to | manage to","PREP. from He concealed the truth from her."]},"media":{"uk":"media/ldoce/hwd/bre/d/conceal0205.mp3","us":"media/ldoce/hwd/ame/8/conceal.mp3"},"examples":[{"en":"The paintings were concealed beneath a thick layer of plaster.","cn":"那些画被隐藏在厚厚的灰泥层下面。"},{"en":"She sat down to conceal the fact that she was trembling.","cn":"她坐下来以不让人看出她在发抖。"}],"oxford":{"phon":"kənˈsiːl","pos":"verb","senses":[{"en":"to hide somebody/something","cn":"隐藏；隐瞒；掩盖","ex":{"en":"The paintings were concealed beneath a thick layer of plaster.","cn":"那些画被隐藏在厚厚的灰泥层下面。"}}]}},"confront":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(问题、任务或困难)降临，使面临","en":"If you are confronted with a problem, task, or difficulty, you have to deal with it.","ex":{"en":"She was confronted with severe money problems","cn":"她面临严峻的资金问题。"}},{"pos":"VERB 动词","cn":"勇敢地面对;正视","en":"If you confront a difficult situation or issue, you accept the fact that it exists and try to deal with it.","ex":{"en":"We are learning how to confront death","cn":"我们正在学习如何直面死亡。"}},{"pos":"VERB 动词","cn":"使面对(有威胁性或困难的事)","en":"If you are confronted by something that you find threatening or difficult to deal with, it is there in front of you.","ex":{"en":"I was confronted with an array of knobs, levers, and switches.","cn":"我面对的是一大堆旋钮、控制杆和开关。"}},{"pos":"VERB 动词","cn":"与…对峙;与…对抗","en":"If you confront someone, you stand or sit in front of them, especially when you are going to fight, argue, or compete with them.","ex":{"en":"She pushed her way through the mob and confronted him face to face","cn":"她挤过骚动的人群，与他当面对峙。"}},{"pos":"VERB 动词","cn":"与…当面对证(或对质)","en":"If you confront someone with something, you present facts or evidence to them in order to accuse them of something.","ex":{"en":"She had decided to confront Kathryn with what she had learnt","cn":"她决定拿自己了解的事实与凯瑟琳当面对证。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"a statement saying that someone has done something bad","cn":""},{"en":"to say publicly that someone has done something bad or illegal, even though this has not been proved - used especially in newspapers and news reports","cn":""},{"en":"a public statement saying that someone has done something bad or illegal, even though this has not been proved","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Confront means either to face a situation that makes you uncomfortable, or to say something to someone about something they've done that bothers you. Rather than letting things go, when people are rude to you you should confront them."}]},"collocations":{"phrases":["ADV. directly He is willing to confront problems directly. | immediately, suddenly","PHRASES be confronted with sth I was suddenly confronted by the task of rewriting the entire book. | find yourself confronted by sth The dem"]},"media":{"uk":"media/ldoce/hwd/bre/b/confront0205.mp3","us":"media/ldoce/hwd/ame/f/confront.mp3"},"examples":[{"en":"He confronted her with a choice between her career or their relationship.","cn":"他要她在事业和他们两人关系之间作出抉择。"},{"en":"Most people when confronted with a horse will pat it.","cn":"大多数人遇见马时都会轻轻地拍拍它。"}],"oxford":{"phon":"kənˈfrʌnt","pos":"verb","senses":[{"en":"to appear and need to be dealt with by somebody","cn":"使…无法回避；降临于","ex":{"en":"What is to be done about the economic problems confronting the country?","cn":"面对国家面临的经济问题，该怎么办？"}},{"en":"to deal with a problem or difficult situation","cn":"处理，解决（问题或困境）","ex":{"en":"She knew that she had to confront her fears.","cn":"她心里明白自己必须克服恐惧心理。"}},{"en":"to face somebody so that they cannot avoid seeing and hearing you, especially in an unfriendly or dangerous situation","cn":"面对；对抗；与（某人）对峙","ex":{"en":"This was the first time he had confronted an armed robber.","cn":"这是他第一次面对一个武装劫匪。"}},{"en":"to make somebody face or deal with an unpleasant or difficult person or situation","cn":"使面对，使面临，使对付（令人不快或难处的人、场合）","ex":{"en":"He confronted her with a choice between her career or their relationship.","cn":"他要她在事业和他们两人关系之间作出抉择。"}},{"en":"to have something in front of you that you have to deal with or react to","cn":"面对（某事物）","ex":{"en":"Most people when confronted with a horse will pat it.","cn":"大多数人遇见马时都会轻轻地拍拍它。"}}]}},"cordial":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"友好的;可亲的","en":"Cordial means friendly.","ex":{"en":"He had never known him to be so chatty and cordial","cn":"他从没见过他如此健谈，如此友善。"}},{"pos":"N-MASS 物质名词","cn":"(不含酒精的)甜果汁饮料","en":"Cordial is a sweet non-alcoholic drink made from fruit juice.","ex":{"en":"...fruit cordials.","cn":"果汁饮料"}},{"pos":"N-MASS 物质名词","cn":"(饭后饮用的)利口酒，烈性甜酒","en":"A cordial is a strong alcoholic drink with a sweet taste. You drink it after a meal."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"sweet fruit juice that you add water to before you drink it 〔","cn":"加水后饮用的〕果汁"},{"en":"a strong sweet alcoholic drink","cn":"烈性甜酒﹔甜露酒"},{"en":"behaving towards someone in a way that shows you like them and are ready to talk to them or help them","cn":""}]},"vocab":{"pos":"1 adj 2 n","senses":[{"en":"If you like someone but you wouldn't say they're your friend, you might describe your relationship as cordial . Use cordial to describe a greeting or relationship that is friendly and sincere."}]},"collocations":{"phrases":["VERBS be | remain","ADV. extremely, remarkably, very | not entirely | quite Relations between the two governments remained quite cordial."]},"media":{"uk":"media/ldoce/hwd/bre/9/cordial_n0205.mp3","us":"media/ldoce/hwd/ame/4/l3cordial.mp3"},"examples":[{"en":"I was greeted with a show of cordiality.","cn":"我受到了热情友好的接待。"},{"en":"a cordial atmosphere/meeting/relationship","cn":"亲切友好的气氛/会议/关系"}],"oxford":{"phon":"ˈkɔːdiəl","pos":"adjective","senses":[{"en":"pleasant and friendly","cn":"热情友好的；和蔼可亲的","ex":{"en":"a cordial atmosphere/meeting/relationship","cn":"亲切友好的气氛／会议／关系"}},{"en":"a sweet drink that does not contain alcohol, made from fruit juice. It is drunk with water added.","cn":"（不含酒精、加水饮用的）甜果汁饮料","g":"[uncountable, countable]","lab":"British English","ex":{"en":"blackcurrant cordial","cn":"黑醋栗果汁饮料"},"pos":"noun"},{"en":"a strong sweet alcoholic drink, sometimes tasting of fruit. It is usually drunk in very small glasses after a meal.","cn":"（通常餐后少量饮用的）烈性甜酒","g":"[uncountable, countable]","lab":"North American English","pos":"noun"},{"en":"a glass of cordial","cn":"一杯甜果汁饮料","g":"[countable]","pos":"noun"}]}},"cover-up":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(对罪行或错误的)掩饰，掩盖","en":"A cover-up is an attempt to hide a crime or mistake.","ex":{"en":"General Schwarzkopf denied there'd been any cover-up.","cn":"施瓦茨科普夫将军否认曾经有任何掩饰行为。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a deliberate plan to prevent mistakes or embarrassing information, especially about politicians or other people in official positions, from being publicly known","cn":""},{"en":"an attempt by a government or official committee to hide the true facts of a situation from the public, especially when there was supposed to have been an official and fair examination of these facts","cn":""},{"en":"something that you do or say as a way of hiding your true actions or intentions, especially when these are illegal or dishonest","cn":""}]},"collocations":{"phrases":["ADJ. big, major | government VERB + COVER-UP be engaged in, be implicated in, be involved in Military leaders were involved in a major cover","PREP. ~ by cover-ups by the police | ~ over evidence of a cover-up over arms sales","PHRASES allegations/claims of a cover-up"]},"media":{"uk":"media/ldoce/hwd/bre/2/cover_up0205.mp3","us":"media/ldoce/hwd/ame/8/cover-up.mp3"},"examples":[{"en":"Government sources denied there had been a deliberate cover-up.","cn":"政府方面否认了有故意掩饰的行为。"},{"en":"He accused the government of a cover-up.","cn":"他指责政府隐瞒实情。"}],"oxford":{"phon":"ˈkʌvər ʌp","pos":"noun","senses":[{"en":"action that is taken to hide a mistake or an illegal activity from the public","cn":"（对过失或不法活动的）掩盖，掩饰","ex":{"en":"Government sources denied there had been a deliberate cover-up.","cn":"政府方面否认了有故意掩饰的行为。"}}]}},"convert":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)改变;更改;(使)转变","en":"If one thing is converted or converts into another, it is changed into a different form.","ex":{"en":"The signal will be converted into digital code.","cn":"信号会被转变为数字代码。"}},{"pos":"VERB 动词","cn":"改造，改建(房屋等)","en":"If someone converts a room or building, they alter it in order to use it for a different purpose.","ex":{"en":"By converting the loft, they were able to have two extra bedrooms.","cn":"把阁楼改造一下，他们就可以多出两间卧室。"}},{"pos":"VERB 动词","cn":"改造，改装(车辆或设备)","en":"If you convert a vehicle or piece of equipment, you change it so that it can use a different fuel.","ex":{"en":"Save money by converting your car to unleaded","cn":"将车改装一下，使用无铅汽油，这样可以省钱。"}},{"pos":"VERB 动词","cn":"换算;折算","en":"If you convert a quantity from one system of measurement to another, you calculate what the quantity is in the second system.","ex":{"en":"Converting metric measurements to U.S. equivalents is easy.","cn":"将公制计量换算成美制计量非常简单。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)改变宗教（或政治）信仰;(使)皈依;(使)归附","en":"If someone converts you, they persuade you to change your religious or political beliefs. You can also say that someone converts to a different religion.","ex":{"en":"If you try to convert him, you could find he just walks away","cn":"如果你试图改变他的信仰，他就会走开。"}},{"pos":"N-COUNT 可数名词","cn":"皈依者;归附者;改变信仰者","en":"A convert is someone who has changed their religious or political beliefs.","ex":{"en":"She, too, was a convert to Roman Catholicism.","cn":"她也皈依了天主教。"}},{"pos":"VERB 动词","cn":"使…迷上;使…热衷于","en":"If someone converts you to something, they make you very enthusiastic about it.","ex":{"en":"He quickly converted me to the joys of cross-country skiing.","cn":"他很快就使我迷上了越野滑雪。"}},{"pos":"N-COUNT 可数名词","cn":"刚迷上…的人;最近开始热衷于…的人","en":"If you describe someone as a convert to something, you mean that they have recently become very enthusiastic about it.","ex":{"en":"...recent converts to vegetarianism.","cn":"最近开始热衷于素食主义的人"}},{"pos":"","cn":"","en":"to preach to the converted→see: ;"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to change something so that it can be used in a different way","cn":""},{"en":"to make small changes to something such as a piece of equipment, a set of ideas, or a way of behaving in order to improve it or to make it more suitable for a particular purpose","cn":""},{"en":"to change something completely so that it has a different form and can be used for a different purpose","cn":""}]},"vocab":{"pos":"1 v 2 v n 3 v 4 v","senses":[{"en":"Think of the word convert as meaning \"change,\" whether it is a person who adopts a new belief, or a changing action, such as when you convert dollars into euros."}]},"collocations":{"phrases":["ADJ. recent | enthusiastic | reluctant | Catholic, Jewish, etc.","VERB + CONVERT become | gain, make, win an attempt to gain converts to Communism","PREP. ~ from One of the early popes, Clement was a convert from paganism. | ~ to a recent convert to Catholicism"]},"media":{"uk":"media/ldoce/hwd/bre/5/convert_v0205.mp3","us":"media/ldoce/hwd/ame/d/l3convert.mp3"},"examples":[{"en":"We've converted from oil to gas central heating.","cn":"我们已经把中央供热系统由燃油改成了燃气。"},{"en":"What rate will I get if I convert my dollars into euros?","cn":"如果我把美元兑换成欧元，汇率是多少？"}],"oxford":{"phon":"kənˈvɜːt","pos":"verb","senses":[{"en":"to change or make something change from one form, purpose, system, etc. to another","cn":"（使）转变，转换，转化","g":"[transitive, intransitive]","ex":{"en":"They took just nine months to convert the building.","cn":"他们只用了九个月就完成了大楼的改建。"}},{"en":"to be able to be changed from one form, purpose, or system to another","cn":"可转变为；可变换成","g":"[intransitive]","ex":{"en":"a sofa that converts into a bed","cn":"可改作床用的沙发"}},{"en":"to change your religion or beliefs; to make somebody change their religion or beliefs","cn":"（使）改变（宗教或信仰）；（使）皈依，归附","g":"[intransitive, transitive]","ex":{"en":"He converted from Catholicism 20 years ago.","cn":"20年前他皈依了天主教。"}},{"en":"to change an opinion, a habit, etc.","cn":"改变（观点、习惯等）","g":"[intransitive, transitive]","ex":{"en":"I've converted to organic food.","cn":"我改吃有机食物了。"}},{"en":"to score extra points after a try or a touchdown","cn":"（在持球过对方球门线触地或达阵后）获得附加分","g":"[transitive]"},{"en":"a person who has changed their religion, beliefs or opinions","cn":"改变宗教（或信仰、观点）的人；皈依者","ex":{"en":"a convert to Islam","cn":"改信伊斯兰教的人"},"pos":"noun"}]}},"constable":{"collins":{"senses":[{"pos":"N-COUNT; N-TITLE; N-VOC可数名词；头衔名词；称呼名词","cn":"(英国等国家中最低级别的)警察；警员","en":"In Britain and some other countries, a constable is a police officer of the lowest rank.","ex":{"en":"He was a constable at Sutton police station.","cn":"他是萨顿警察局的警员。"}},{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"(美国城镇中参与维持秩序、级别低于县治安官的)巡官","en":"In the United States, a constable is an official who helps keep the peace in a town. They are lower in rank than a sheriff."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a member of the police. In British English, police officer is used especially in more formal contexts, for example in news reports. In everyday English, British people still usually say policeman or policewoman","cn":""},{"en":"a man who is a member of the police","cn":""},{"en":"a woman who is a member of the police","cn":""}]},"collocations":{"phrases":["ADJ. police | Chief, Detective | beat, special, uniformed The force hopes to increase the number of its beat constables. Special constables ","PHRASES the rank of constable"]},"media":{"uk":"media/ldoce/hwd/bre/5/constable0205.mp3","us":"media/ldoce/hwd/ame/7/constable.mp3"},"examples":[{"en":"Have you finished your report, Constable?","cn":"警察先生，你的报告完成了吗？"}],"oxford":{"phon":"ˈkʌnstəbl","pos":"noun","senses":[{"en":"(in the UK and some other countries) a police officer of the lowest rank","cn":"（英国和其他一些国家的）警察，警员","lab":"British English","ex":{"en":"Have you finished your report, Constable?","cn":"警察，你的报告完成了吗？"}},{"en":"an official with some of the powers of a police officer, typically in a small town","cn":"（通常指小城镇的）警员，治安官"}]}},"cornell":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"an important US university in Ithaca, New York, which is one of the ivy league colleges","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/p028-000003635.mp3","us":"media/ldoce/hwd/ame/3/p028-000003635.mp3"}},"coffin":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"棺材;灵柩","en":"A coffin is a box in which a dead body is buried or cremated."},{"pos":"PHRASE 短语","cn":"促使…失败（或完结）的因素","en":"If you say that one thing is a nail in the coffin of another thing, you mean that it will help bring about its end or failure.","ex":{"en":"A fine would be the final nail in the coffin of the airline.","cn":"罚款将会是对这家航空公司的最后致命一击。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long box in which a dead person is buried or burnt","cn":"棺材﹐灵柩"}]},"collocations":{"phrases":["VERB + COFFIN carry, take | lower The coffin was lowered into the grave.","PREP. in a/the ~"]},"media":{"uk":"media/ldoce/hwd/bre/f/coffin0205.mp3","us":"media/ldoce/hwd/ame/b/coffin.mp3"},"oxford":{"phon":"ˈkɒfɪn","pos":"noun","senses":[{"en":"a box in which a dead body is buried or cremated","cn":"棺材；棺椁；棺木","ex":{"en":"A procession of mourners slowly followed the coffin.","cn":"哀悼队伍缓缓跟随在灵柩后面。"}}]}},"commendable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"值得称赞(或表扬)的","en":"If you describe someone's behaviour as commendable, you approve of it or are praising it.","ex":{"en":"Mr Sparrow has acted with commendable speed","cn":"斯帕罗先生行动之快值得赞扬。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"deserving praise","cn":"值得称赞的﹐值得表扬的"},{"en":"deserving praise for your actions, efforts, and intentions even if the final result is not always completely successful","cn":""},{"en":"deserving praise","cn":"值得称赞的﹐值得表扬的"}]},"vocab":{"pos":"adj adv","senses":[{"en":"If something's commendable it deserves whatever praise it receives. When you developed a car that could run on solar power, that was a commendable accomplishment. Now, it's time to move from Seattle."}]},"collocations":{"phrases":["VERBS be, seem","ADV. highly, very The government's action here is highly commendable. | entirely, wholly"]},"media":{"uk":"media/ldoce/hwd/bre/b/commendable0205.mp3","us":"media/ldoce/hwd/ame/d/commendable.mp3"},"examples":[{"en":"commendable honesty","cn":"值得称赞的诚实"},{"en":"Your enthusiasm is highly commendable .","cn":"你的热情非常值得嘉许。"}],"oxford":{"phon":"kəˈmendəbl","pos":"adjective","senses":[{"en":"deserving praise and approval","cn":"值得赞扬（或嘉许）的","ex":{"en":"They always conduct their affairs with commendable honesty.","cn":"他们总是以值得称道的诚实来处理事务。"}}]}},"complexion":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"肤色;面色","en":"When you refer to someone's complexion, you are referring to the natural colour or condition of the skin on their face.","ex":{"en":"She had short brown hair and a pale complexion.","cn":"她留着褐色短发，皮肤白皙。"}},{"pos":"N-COUNT 可数名词","cn":"性质;特性","en":"The complexion of something is its general nature or character.","ex":{"en":"Every time the political complexion of the government changed, so did the defence policy","cn":"每当政府的政治性质发生变化，国防政策也会随之变化。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the natural colour or appearance of the skin on your face","cn":"面色﹐面容﹐气色"},{"en":"the general character or nature of something","cn":"一般性质﹔一般特征"},{"en":"to make a situation or event seem different","cn":"使形势[事情]改变"}]},"vocab":{"pos":"1 n v 2 n 3 n","senses":[{"en":"Complexion refers to the color of a person's skin, especially the face. If you have light skin, for example, you might be said to have a fair or pale complexion ."}]},"collocations":{"phrases":["ADJ. clear, flawless, fresh, glowing, healthy, lovely, nice, perfect | bad, blotchy, dull, pallid, pasty, sallow | ageing | creamy, fair, mi","VERB + COMPLEXION have | give sb Years of heavy drinking had given Alison a florid complexion. 2 general nature/character of sth","ADJ. serious | different, new | political, social a change in the political complexion of the council","VERB + COMPLEXION put, take on What you have told us puts quite a different complexion on the situation. The joke took on a rather serious c"]},"media":{"uk":"media/ldoce/hwd/bre/7/complexion0205.mp3","us":"media/ldoce/hwd/ame/7/complexion.mp3"},"examples":[{"en":"a move which changed the political complexion of the country","cn":"改变国家政局的举措"},{"en":"a pale/bad complexion","cn":"苍白的/病态的脸色"}],"oxford":{"phon":"kəmˈplekʃn","pos":"noun","senses":[{"en":"the natural colour and condition of the skin on a person’s face","cn":"面色；肤色；气色","lab":"informal","ex":{"en":"a pale/bad complexion","cn":"苍白的／病态的脸色"}},{"en":"the general character of something","cn":"（事物的）性质，特性","g":"[usually singular]","ex":{"en":"a move that changed the political complexion of the country","cn":"改变国家政局的举措"}}]}},"comforting":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"安慰的;令人欣慰的","en":"If you say that something is comforting, you mean it makes you feel less worried or unhappy.","ex":{"en":"My mother had just died and I found the book very comforting","cn":"我母亲刚去世，我从这本书中获取了不少慰藉。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is soothing makes you feel calm and relaxed when you are upset, anxious, or nervous","cn":""},{"en":"making you feel less worried or frightened about something","cn":""},{"en":"something that is consoling , especially something that someone says, makes you feel better when you are unhappy or disappointed","cn":""}]},"collocations":{"phrases":["VERBS be, feel | find sth","ADV. extremely, most, very, wonderfully | hardly, not particularly | strangely She found his voice strangely comforting."]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41comforting.mp3","us":"media/ldoce/hwd/ame/2/ld41comforting.mp3"},"examples":[{"en":"It's comforting to know that you'll be there.","cn":"知道你要去那里令人感到欣慰。"},{"en":"her comforting words","cn":"她说的那些令人安慰的话"}],"oxford":{"phon":"ˈkʌmfətɪŋ","pos":"adjective","senses":[{"en":"making you feel calmer and less worried or unhappy","cn":"令人安慰的","ex":{"en":"her comforting words","cn":"她说的那些令人安慰的话"}}]},"base":"comfort"},"columbia":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the capital of the US state of South Carolina","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/p028-000003510.mp3","us":"media/ldoce/hwd/ame/9/p028-000003510.mp3"},"oxford":{"phon":"kəˈlʌmbiə","pos":"","senses":[{"en":"the first US space shuttle (= spacecraft that can be used again). Its first flight was in 1981 with two astronauts, John Young and Robert Crippen. By 1996 Columbia had made 20 flights and that year made the longest one (more than 405 hours). In 2003 all seven of its crew members died when the space shuttle exploded as it was returning to earth.","cn":"哥伦比亚：美国第一架航天飞机。它的第一次飞行是在1981年，有两名宇航员，约翰·扬和罗伯特·克里彭。到1996年，哥伦比亚已经进行了20趟飞行，那一年飞行了最长的一次（超过405小时）。2003年，当航天飞机返回地球时爆炸时，所有七名机组人员死亡。"}]}},"coherence":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"统一;一致性;连贯性","en":"Coherence is a state or situation in which all the parts or ideas fit together well so that they form a united whole.","ex":{"en":"The anthology has a surprising sense of coherence.","cn":"整本选集有着惊人的连贯性。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when something such as a piece of writing is easy to understand because its parts are connected in a clear and reasonable way","cn":"连贯（性）﹐条理（性）﹐一致（性）"},{"en":"if a group has coherence, its members are connected or united because they share common aims, qualities, or beliefs","cn":"凝聚力"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"When something has coherence , all of its parts fit together well. An argument with coherence is logical and complete — with plenty of supporting facts."}]},"collocations":{"phrases":["ADJ. internal Your essay lacks internal coherence. | ideological, intellectual, logical, theoretical theories which lack ideological coheren","VERB + COHERENCE have, possess | achieve, create, give sth, maintain They have struggled to create coherence within the group. | lack","PREP. ~ between a lack of coherence between the policy and the speech | ~ in/within There's a strong sense of coherence in the school curric","PHRASES a degree/sense of coherence"]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41coherence.mp3","us":"media/ldoce/hwd/ame/5/coherence.mp3"},"examples":[{"en":"The points you make are fine, but the whole essay lacks coherence.","cn":"你提出的论点很好，但整篇文章缺乏呼应连贯。"},{"en":"An overall theme will help to give your essay coherence.","cn":"一个总的主题将有助于使文章连贯紧凑。"}],"oxford":{"phon":"kəʊˈhɪərəns","pos":"noun","senses":[{"en":"the situation in which all the parts of something fit together well","cn":"连贯性；条理性","ex":{"en":"The points you make are fine, but the whole essay lacks coherence.","cn":"你提出的论点很好，但整篇文章缺乏呼应连贯。"}}]}},"coup":{"collins":{"senses":[{"pos":"","cn":"政变","en":"When there is a coup, a group of people seize power in a country.","ex":{"en":"...a military coup","cn":"军事政变"}},{"pos":"","cn":"了不起的成就;成功之举","en":"A coup is an achievement which is thought to be especially good because it was very difficult.","ex":{"en":"The sale is a big coup for the auction house","cn":"这笔交易是该拍卖行的一大成功之举。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an attempt by a large group of people at revolution","cn":""},{"en":"an occasion when a group of people, especially soldiers, suddenly take control of a country","cn":""},{"en":"an attempt by the army to take control of the government","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A coup is a pretty major achievement, whether it involves taking over a government by force, or landing a major business contract."}]},"collocations":{"phrases":["ADJ. abortive, attempted, failed, unsuccessful | successful | bloody | bloodless | army, military | palace, presidential He deposed his fath","VERB + COUP launch, mount, stage | foil, put down The coup was immediately put down and the plotters were shot. | plan, plot | lead | come t","COUP + NOUN attempt, plot | leader, plotter","PREP. ~ against an army coup against the president 2 achievement","ADJ. big, brilliant, great, major, real, spectacular Winning that contract was her greatest coup. | diplomatic, financial, intelligence, pro","VERB + COUP pull off He managed to pull off a major diplomatic coup."]},"media":{"uk":"media/ldoce/hwd/bre/5/coup0703.mp3","us":"media/ldoce/hwd/ame/1/coo.mp3"},"examples":[{"en":"He seized power in a military coup in 2008.","cn":"他在 2008 年的军事政变中夺取了政权。"},{"en":"Getting this contract has been quite a coup for us.","cn":"把这份合同争取到手让我们费了很大力气。"}],"oxford":{"phon":"kuː","pos":"noun","senses":[{"en":"a sudden change of government that is illegal and often violent","cn":"政变","ex":{"en":"He seized power in a military coup in 2008.","cn":"他在 2008 年的军事政变中夺取了政权。"}},{"en":"the fact of achieving something that was difficult to do","cn":"努力办到难办的事","ex":{"en":"Getting this contract has been quite a coup for us.","cn":"把这份合同争取到手让我们费了很大力气。"}}]}},"corrosion":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"腐蚀;侵蚀","en":"Corrosion is the damage that is caused when something is corroded.","ex":{"en":"Zinc is used to protect other metals from corrosion.","cn":"锌被用来保护其他金属不受腐蚀。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when a chemical or a chemical process makes a metal decay","cn":""},{"en":"the gradual destruction of metal by the effect of water, chemicals etc or a substance such as rust produced by this process","cn":"腐蚀﹔侵蚀"}]},"vocab":{"pos":"n","senses":[{"en":"Corrosion is the process by which something deteriorates because of oxidation, a chemical action that creates oxides that flake away from the base."}]},"collocations":{"phrases":["VERB + CORROSION cause | prevent | suffer from a building whose structure is suffering from corrosion","PHRASES signs of corrosion"]},"media":{"uk":"media/ldoce/hwd/bre/9/corrosion0205.mp3","us":"media/ldoce/hwd/ame/e/corrosion.mp3"},"examples":[{"en":"Clean off any corrosion before applying the paint.","cn":"先把锈迹清除干净再涂油漆。"},{"en":"Look for signs of corrosion.","cn":"寻找腐蚀的痕迹。"}],"oxford":{"phon":"kəˈrəʊʒn","pos":"noun","senses":[{"en":"the process of destroying something slowly, especially by chemical action; the condition that results from this process","cn":"腐蚀；侵蚀","ex":{"en":"Look for signs of corrosion.","cn":"寻找腐蚀的痕迹。"}}]}},"commonplace":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"平常的;不足为奇的","en":"If something is commonplace, it happens often or is often found, and is therefore not surprising.","ex":{"en":"Foreign vacations have become commonplace","cn":"去国外度假已经变得很平常了。"}},{"pos":"N-COUNT 可数名词","cn":"平常的事;司空见惯的事","en":"A commonplace is something that happens often or is often found.","ex":{"en":"It's become a commonplace to see people collapsing from hunger in the streets.","cn":"现在在街上时不时会看见有人饿晕。"}},{"pos":"N-COUNT 可数名词","cn":"老生常谈;陈词滥调","en":"A commonplace is a remark or opinion that is often expressed and is therefore not original or interesting.","ex":{"en":"It is a commonplace to say that Northern Ireland is a backwater in the modern Europe.","cn":"说北爱尔兰是现代欧洲死气沉沉的落后地区已是陈词滥调了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something is common, there are a lot of them","cn":""},{"en":"happening in a lot of places or done by a lot of people","cn":""},{"en":"common in a particular place or time – used especially when saying that this seems surprising or unusual","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"Something commonplace is ordinary. It can also be something dull and unchallenging or tired and clichéd. Coffee shops in cities are commonplace , so are berets in Paris. You see them all over the place."}]},"collocations":{"phrases":["VERBS be, seem | become | regard sth as Such actions were regarded as commonplace during the war.","ADV. very | almost | enough, fairly, quite, rather Her situation sounded commonplace enough.","PREP. among/amongst These ideas are commonplace among teenagers."]},"media":{"uk":"media/ldoce/hwd/bre/5/commonplace_ad0205.mp3","us":"media/ldoce/hwd/ame/6/commonplace1.mp3"},"examples":[{"en":"Computers are now commonplace in primary classrooms.","cn":"计算机如今在小学教室里很普遍。"},{"en":"Car thefts are commonplace in this part of town.","cn":"镇上的这个地段盗车案屡见不鲜。"}],"oxford":{"phon":"ˈkɒmənpleɪs","pos":"adjective","senses":[{"en":"done very often, or existing in many places, and therefore not unusual","cn":"平凡的；普通的；普遍的","ex":{"en":"This technology is now commonplace in schools.","cn":"这种技术现在在学校很普遍。"}},{"en":"an event, etc. that happens very often and is not unusual","cn":"常见的事；平常的事","g":"[usually singular]","pos":"noun"},{"en":"a remark, etc. that is not new or interesting","cn":"平淡无奇的言语等；老生常谈","ex":{"en":"The speech was full of commonplaces.","cn":"讲话充满了老生常谈。"},"pos":"noun"}]}},"constipation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"便秘","en":"Constipation is a medical condition which causes people to have difficulty getting rid of solid waste from their body."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"pain in your stomach or near your stomach","cn":""},{"en":"pain or uncomfortable feelings that you get when your stomach cannot break down food that you have eaten","cn":""},{"en":"a stomach illness caused by eating food that contains harmful bacteria, so that you vomit","cn":""}]},"collocations":{"phrases":["ADJ. severe | acute, chronic","QUANT. bout","VERB + CONSTIPATION have, suffer from | cause | prevent •"]},"media":{"uk":"media/ldoce/hwd/bre/d/constipation0205.mp3","us":"media/ldoce/hwd/ame/e/constipation.mp3"},"oxford":{"phon":"ˌkɒnstɪˈpeɪʃn","pos":"noun","senses":[{"en":"the condition of being unable to get rid of waste material from the bowels easily (= being constipated)","cn":"便秘"}]}},"contempt":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"鄙视;蔑视;轻视","en":"If you have contempt for someone or something, you have no respect for them or think that they are unimportant.","ex":{"en":"He has contempt for those beyond his immediate family circle","cn":"他鄙视直系亲属圈子以外的人。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"同 contempt of court","en":"Contempt means the same as contempt of court .","ex":{"en":"Mr. Kelly was sentenced to six months in prison for contempt.","cn":"凯利先生因藐视法庭被判6个月监禁。"}},{"pos":"PHRASE 短语","cn":"鄙视;蔑视;轻视","en":"If you hold someone or something in contempt, you feel contempt for them. familiarity breeds contempt→see: ;","ex":{"en":"Small wonder that many voters hold their politicians in contempt.","cn":"无怪乎很多选民看不起他们的政治家。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an angry feeling of deep dislike for someone or something","cn":""},{"en":"the angry feeling that someone has when they hate someone and want to harm them","cn":""},{"en":"a very strong feeling of hatred for someone or something that you think is extremely unpleasant","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Reserve the noun contempt for an extreme lack of respect: a food snob has nothing but contempt for mass-produced burgers and fries at a fast-food joint."}]},"collocations":{"phrases":["ADJ. deep, utter, withering | cold, icy | healthy She'd developed what she considered a healthy contempt for authority. | barely/thinly disg","VERB + CONTEMPT feel, have, hold sb/sth in He felt nothing but contempt for them. Politicians seem to be generally held in contempt by the p","PREP. ~ for He has a deep contempt for racists. | beneath ~ His treatment of his children is beneath contempt (= so bad it is not even worth","ADJ. civil, criminal","VERB + CONTEMPT be held in She was held in contempt for refusing to testify.","PREP. in ~"]},"media":{"uk":"media/ldoce/hwd/bre/e/contempt0205.mp3","us":"media/ldoce/hwd/ame/b/contempt.mp3"},"examples":[{"en":"The firefighters showed a contempt for their own safety.","cn":"那些消防队员已把他们自己的安全置之度外。"},{"en":"His treatment of his children is beneath contempt (= so unacceptable that it is not even worth feeling contempt for).","cn":"他对待自己子女的那种行径为人所不齿。"}],"oxford":{"phon":"kənˈtempt","pos":"noun","senses":[{"en":"the feeling that somebody/something is without value and deserves no respect at all","cn":"蔑视；轻蔑；鄙视","ex":{"en":"She looked at him with contempt.","cn":"她轻蔑地看着他。"}},{"en":"a lack of worry or fear about rules, danger, etc.","cn":"（对规则、危险等的）藐视，不顾","ex":{"en":"The firefighters showed a contempt for their own safety.","cn":"那些消防队员把他们自己的安全置之度外。"}},{"en":"the crime of refusing to obey an order made by a court; not showing respect for a court or judge","cn":"藐视法庭（罪）","ex":{"en":"He could be jailed for two years for contempt.","cn":"他由于藐视法庭可能被监禁两年。"}}]}},"courteous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有礼貌的;谦恭的;恭敬的;客气的","en":"Someone who is courteous is polite and respectful to other people.","ex":{"en":"He was a kind and courteous man","cn":"他为人友善，而且彬彬有礼。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving or speaking in a way that is correct for the social situation you are in, and showing that you are careful to consider other people’s needs and feelings","cn":""},{"en":"having good manners and knowing the correct way to behave in social situations","cn":""},{"en":"polite and not causing any trouble – used about children or animals","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you are courteous , your good manners show friendliness and concern for others, like your courteous habit of holding the door for people entering a building with you."}]},"collocations":{"phrases":["VERBS be, seem","ADV. extremely, very | entirely, perfectly | always, invariably, unfailingly She was unfailingly courteous and helpful. | naturally","PREP. to He was perfectly courteous to me."]},"media":{"uk":"media/ldoce/hwd/bre/9/courteous0205.mp3","us":"media/ldoce/hwd/ame/4/courteous.mp3"},"examples":[{"en":"The hotel staff are friendly and courteous.","cn":"旅馆服务人员友好而有礼貌。"},{"en":"a courteous young man","cn":"彬彬有礼的年轻人"}],"oxford":{"phon":"ˈkɜːtiəs","pos":"adjective","senses":[{"en":"polite, especially in a way that shows respect","cn":"有礼貌的；客气的；（尤指）恭敬的，谦恭的","ex":{"en":"a courteous young man","cn":"彬彬有礼的年轻人"}}]}},"colic":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指婴儿的)腹绞痛，急性腹痛","en":"Colic is an illness in which you get severe pains in your stomach and bowels. Babies especially suffer from colic.","ex":{"en":"The doctor said it was colic and that she would grow out of it.","cn":"医生说她患的是腹绞痛，长大了就没事了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if a baby has colic, it has severe pain in its stomach and bowel s 〔","cn":"婴儿的〕腹绞痛﹐急性腹痛"}]},"collocations":{"phrases":["ADJ. violent | biliary | infantile","QUANT. attack, bout","VERB + COLIC have, suffer from | develop | treat •"]},"media":{"uk":"media/ldoce/hwd/bre/9/ld44colic.mp3","us":"media/ldoce/hwd/ame/9/ld44colic.mp3"},"oxford":{"phon":"ˈkɒlɪk","pos":"noun","senses":[{"en":"severe pain in the stomach and bowels, suffered especially by babies","cn":"（尤指婴儿的）急性腹痛，腹绞痛"}]}},"councillor":{"collins":{"senses":[{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"市议员;政务委员会委员","en":"A councillor is a member of a local council.","ex":{"en":"...the first black New York City councillor, Benjamin Davis Jr.","cn":"纽约市政委员会第一位黑人委员，小本杰明·戴维斯"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a member of a council","cn":"市政委员﹔议员"}]},"collocations":{"phrases":["ADJ. borough, city, county, district, local, parish, town | Conservative, Labour, Liberal Democrat, Tory, etc. | former | newly-elected","VERB + COUNCILLOR elect sb (as)","PHRASES the office of councillor"]},"media":{"uk":"media/ldoce/hwd/bre/8/councillor0205.mp3","us":"media/ldoce/hwd/ame/f/councilor.mp3"},"examples":[{"en":"Talk to your local councillor about the problem.","cn":"关于这个问题可与你当地的市议员谈一谈。"},{"en":"Councillor Ann Jones","cn":"安 · 琼斯委员"}],"oxford":{"phon":"ˈkaʊnsələ(r)","pos":"noun","senses":[{"en":"a member of a city or county council","cn":"市议员；地方议会议员；政务委员会委员","ex":{"en":"Councillor Ann Jones","cn":"安·琼斯委员"}}]}},"commotion":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"喧闹;混乱;骚动","en":"A commotion is a lot of noise, confusion, and excitement.","ex":{"en":"He heard a commotion outside","cn":"他听见外面一阵骚动。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a loud sound, especially an unpleasant one","cn":""},{"en":"a loud unpleasant noise, especially one that annoys you. Racket is more informal than din","cn":""},{"en":"a very loud unpleasant noise, especially one that continues for a long time","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A commotion is a noisy disturbance. If you're trying to quietly concentrate on reading this, you wouldn't want the person next to you to cause a commotion, or it would distract you."}]},"collocations":{"phrases":["ADJ. dreadful, great, terrible | sudden","VERB + COMMOTION cause, make, set up The people upstairs were making a great commotion. The dogs set up a terrible commotion as we came near","COMMOTION + VERB break out | die down","PREP. in a/the ~ Lots of furniture had been knocked over in the commotion. | ~ about/over What's all the commotion about?"]},"media":{"uk":"media/ldoce/hwd/bre/d/commotion0205.mp3","us":"media/ldoce/hwd/ame/5/commotion.mp3"},"examples":[{"en":"I heard a commotion and went to see what was happening.","cn":"我听到一阵喧闹便去看看发生了什么事情。"},{"en":"The crowd waiting outside was causing a commotion.","cn":"在外面等待的人群眼看就要发生骚乱。"}],"oxford":{"phon":"kəˈməʊʃn","pos":"noun","senses":[{"en":"sudden noisy and confused activity or excitement","cn":"（突然发生的）喧闹，骚乱，骚动","ex":{"en":"I heard a commotion and went to see what was happening.","cn":"我听到一阵喧闹，便去看看发生了什么事情。"}}]}},"commissioner":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(政府部门或其他组织的)长官，要人","en":"A commissioner is an important official in a government department or other organization.","ex":{"en":"...the European Commissioner for External Affairs.","cn":"欧洲委员会外事专员"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is officially in charge of a government department in some countries","cn":"部长"},{"en":"the head of the police department in some parts of the US 〔","cn":"美国部分地区的〕警察局局长"},{"en":"a member of a commission","cn":"委员"}]},"vocab":{"pos":"n","senses":[{"en":"The noun commissioner refers to someone in charge of a formal group or organization, such as a police commissioner or a baseball commissioner ."}]},"collocations":{"phrases":["ADJ. high | assistant, deputy | special | European Union/EU, police, United Nations/UN","VERB + COMMISSIONER appoint, appoint sb (as)","PREP. ~ for He was appointed United Nations High Commissioner for refugees."]},"media":{"uk":"media/ldoce/hwd/bre/1/commissioner0205.mp3","us":"media/ldoce/hwd/ame/2/commissioner.mp3"},"examples":[{"en":"the Church Commissioners (= the group of people responsible for controlling the financial affairs of the Church of England)","cn":"英国国教会财政管理委员会委员"},{"en":"Commissioner Rhodes was unavailable for comment.","cn":"罗兹局长无暇评论。"}],"oxford":{"phon":"kəˈmɪʃənə(r)","pos":"noun","senses":[{"en":"a member of a commission (= an official group of people who are responsible for controlling something or finding out about something)","cn":"（委员会的）委员，专员，特派员","ex":{"en":"the Church Commissioners (= the group of people responsible for controlling the financial affairs of the Church of England)","cn":"英格兰国教会财政管理委员会委员"}},{"en":"the head of a particular police force in some countries","cn":"警察局长；警长","lab":"especially in North American English"},{"en":"the head of a government department in some countries","cn":"（政府部门的）首长，长官","ex":{"en":"the agriculture/health, etc. commissioner","cn":"农业、卫生等厅长"}},{"en":"(in the US) an official chosen by a sports association to control it","cn":"（美国体育协会的）总干事，主管人","ex":{"en":"the baseball commissioner","cn":"棒球协会总干事"}}]}},"commend":{"collins":{"senses":[{"pos":"VERB 动词","cn":"赞扬;赞许","en":"If you commend someone or something, you praise them formally.","ex":{"en":"I commended her for that action","cn":"我赞扬了她的那一举动。"}},{"pos":"VERB 动词","cn":"推荐;举荐","en":"If someone commends a person or thing to you, they tell you that you will find them good or useful.","ex":{"en":"I can commend it to him as a realistic course of action.","cn":"我可以把这作为一个切实可行的处理方法推荐给他。"}},{"pos":"VERB 动词","cn":"被接受;得到认可","en":"If something commends itself to you, you approve of it.","ex":{"en":"The Rousseau model commended itself to a lot of early socialists.","cn":"卢梭提出的模式被很多早期的社会主义者接受。"}},{"pos":"PHRASE 短语","cn":"令人称道/乏善可陈","en":"If you say that something has much to commend it, you approve of it. If you say that something has little to commend it, you disapprove of it.","ex":{"en":"The Prime Minister's initiative has much to commend it.","cn":"首相的新方案有不少令人赞许之处。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say that you admire and approve of someone or something, especially publicly","cn":""},{"en":"to tell someone that you think it is good that they have achieved something","cn":""},{"en":"to say to someone that you like how they look, or you like something they have done","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"Ever shout \"Bravo!\" at the end of a ballet or coo \"Good boy!\" to the dog when he relieved himself outdoors instead of on the rug? Then you know how to commend someone — in other words, to express approval aloud."}]},"collocations":{"phrases":["PREP. for He was commended for his brave actions. | to She said she would commend the proposal to the Board.","PHRASES be highly/widely commended His book was highly commended. | sth has little/much to commend it The proposed site has much to commend "]},"media":{"uk":"media/ldoce/hwd/bre/4/commend0205.mp3","us":"media/ldoce/hwd/ame/5/commend.mp3"},"examples":[{"en":"She is an excellent worker and I commend her to you without reservation.","cn":"她工作出色，我毫无保留地把她推荐给你。"},{"en":"She was commended on her handling of the situation.","cn":"她因妥善处理了那个局面而受到表扬。"}],"oxford":{"phon":"kəˈmend","pos":"verb","senses":[{"en":"to praise somebody/something, especially publicly","cn":"（尤指公开地）赞扬，称赞，表扬","ex":{"en":"She was commended on her handling of the situation.","cn":"她因妥善处理了那个局面而受到表扬。"}},{"en":"to recommend somebody/something to somebody","cn":"推荐；举荐","lab":"formal","ex":{"en":"She is an excellent worker and I commend her to you without reservation.","cn":"她工作出色，我毫无保留地把她推荐给你。"}},{"en":"if something commends itself to somebody, they approve of it","cn":"受到赞同；得到认可","lab":"formal","ex":{"en":"His outspoken behaviour did not commend itself to his colleagues.","cn":"他直言不讳的行为不受他同事的欢迎。"}},{"en":"to give somebody/something to somebody in order to be taken care of","cn":"把…托付给（或委托于）","lab":"formal","ex":{"en":"We commend her soul to God.","cn":"我们把她的灵魂托付给上帝。"}}]}},"component":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"组成部分;成分","en":"The components of something are the parts that it is made of.","ex":{"en":"Enriched uranium is a key component of a nuclear weapon","cn":"浓缩铀是核武器的关键组成部分。"}},{"pos":"ADJ 形容词","cn":"组成的;构成的","en":"The component parts of something are the parts that make it up.","ex":{"en":"Gorbachev failed to keep the component parts of the Soviet Union together","cn":"戈尔巴乔夫没能把苏联各成员国团结在一起。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that together with other things forms a whole","cn":""},{"en":"a small part of something","cn":""},{"en":"one of several different parts that you join together to make something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"It's the Ikea curse: You spend four hours figuring out how to piece together your new furniture, only to be left with one random component , or part, that doesn't seem to fit anywhere."}]},"collocations":{"phrases":["ADJ. basic, central, core, critical, crucial, essential, fundamental, important, integral, key, main, major, necessary, principal, significa","COMPONENT + NOUN failure Component failure was the cause of the accident. | manufacturer, supplier","PREP. ~ in a crucial component in our success."]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdecomponent.mp3","us":"media/ldoce/hwd/ame/3/component.mp3"},"examples":[{"en":"Trust is a vital component in any relationship.","cn":"在任何关系中，信任都是一个至关重要的因素。"},{"en":"Break the problem down into its component parts.","cn":"把这个问题分解成若干组成部分。"}],"oxford":{"phon":"kəmˈpəʊnənt","pos":"noun","senses":[{"en":"one of several parts of which something is made","cn":"组成部分；成分；部件","ex":{"en":"the different organizations involved in the design of the various components","cn":"参与各个组件设计的不同组织"}},{"en":"used to describe one of several parts of which something is made","cn":"构成的；组成的","ex":{"en":"Break the problem down into its component parts.","cn":"把问题拆分为几个组成部分。"},"pos":"adjective"}]}},"connotation":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(词或名字的)内涵意义，隐含意义，联想意义","en":"The connotations of a particular word or name are the ideas or qualities which it makes you think of.","ex":{"en":"It's just one of those words that's got so many negative connotations","cn":"这只是那种有太多负面含义的词之一。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"what a word, sign, or statement means","cn":""},{"en":"one of the meanings of a word that has several meanings","cn":""},{"en":"the important meaning that something has, especially if the meaning is not immediately clear","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When you're talking about the implied subtext of words rather than their literal meaning, reach for the noun connotation . A political boss might not want to be called \"boss\" because of the negative connotations ."}]},"collocations":{"phrases":["ADJ. strong | wider The notion of abuse has wider connotations than the physical. | negative, pejorative | positive | humorous | moral, raci","VERB + CONNOTATION carry, have That word has strong sexual connotations. | attach, give sth the negative connotations attached to the word &","PREP. ~ of The word carries connotations of romance."]},"media":{"uk":"media/ldoce/hwd/bre/b/connotation0205.mp3","us":"media/ldoce/hwd/ame/d/connotation.mp3"},"examples":[{"en":"The word ‘professional’ has connotations of skill and excellence. * professional","cn":"这个词隐含着技艺和专长的意思。"},{"en":"negative connotations","cn":"贬义"}],"oxford":{"phon":"ˌkɒnəˈteɪʃn","pos":"noun","senses":[{"en":"an idea suggested by a word in addition to its main meaning","cn":"含义；隐含意义","ex":{"en":"The word ‘professional’ has connotations of skill and excellence.","cn":"professional 这个词隐含着技艺和专长的意思。"}}]}},"corrode":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)腐蚀;(使)侵蚀","en":"If metal or stone corrodes, or is cor-roded, it is gradually destroyed by a chemical or by rust.","ex":{"en":"He has devised a process for making gold wires which neither corrode nor oxidise","cn":"他设计了一种能够避免腐蚀或氧化的金丝制作流程。"}},{"pos":"VERB 动词","cn":"削弱;侵蚀","en":"To corrode something means to gradually make it worse or weaker.","ex":{"en":"Suffering was easier to bear than the bitterness he felt corroding his spirit","cn":"相较于他感觉正在侵蚀他灵魂的痛苦而言，这种折磨倒更容易承受。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if the wind, rain, sea etc wears something away , it very gradually destroys its surface until there is nothing left","cn":""},{"en":"if water, wind, air etc erodes rock, land, soil etc, it gradually damages it over a long time by removing little pieces of it","cn":""},{"en":"if a chemical corrodes something metal, it damages it and makes it gradually disappear or become weaker","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Corrode means to eat away at and cause to deteriorate, like rust slowly taking over an old bike left out in the rain."}]},"collocations":{"phrases":["PHRASES be badly corroded If the pipe is badly corroded, it should be replaced."]},"media":{"uk":"media/ldoce/hwd/bre/e/corrode0205.mp3","us":"media/ldoce/hwd/ame/0/corrode.mp3"},"examples":[{"en":"( figurative ) Corruption corrodes public confidence in a political system.","cn":"腐败可削弱公众对政治制度的信心。"},{"en":"Clean off any corrosion before applying the paint.","cn":"先把锈迹清除干净再涂油漆。"}],"oxford":{"phon":"kəˈrəʊd","pos":"verb","senses":[{"en":"to slowly destroy or damage metal, stone or other materials by chemical action; to be destroyed in this way","cn":"腐蚀；侵蚀","g":"[transitive, intransitive]","ex":{"en":"Acid corrodes metal.","cn":"酸腐蚀金属。"}},{"en":"to slowly destroy or make something weaker","cn":"削弱；侵蚀","g":"[transitive]","ex":{"en":"Corruption corrodes public confidence in a political system.","cn":"腐败可削弱公众对政治制度的信心。"}}]}},"controller":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"控制者;管理者;指挥者","en":"A controller is a person who has responsibility for a particular organization or for a particular part of an organization.","ex":{"en":"...the job of controller of BBC 1.","cn":"英国广播公司第一频道负责人的工作"}},{"pos":"N-COUNT 可数名词","cn":"同 comptroller","en":"A controller is the same as a comptroller ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is in charge of a particular system, organization, or part of an organization","cn":"控制者﹔管理者﹔指挥者"},{"en":"someone who is in charge of the money received or paid out by a company or government department","cn":"财务主管﹔审计官"}]},"collocations":{"phrases":["ADJ. air traffic | programme He is the new programme controller for BBC2. | credit, financial, marketing, production | district, divisional,","PREP. ~ for the company's marketing controller for the north-west • Note at JOB"]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41controller.mp3","us":"media/ldoce/hwd/ame/8/controller.mp3"},"examples":[{"en":"a temperature controller","cn":"温控器"},{"en":"air-traffic controllers","cn":"空中交通调度员"}],"oxford":{"phon":"kənˈtrəʊlə(r)","pos":"noun","senses":[{"en":"a person who manages or directs something, especially a large organization or part of an organization","cn":"（尤指大型机构或部门的）管理者，控制者，指挥者","ex":{"en":"He is the new programme controller for BBC2.","cn":"他是英国广播公司第二频道的新任节目总监。"}},{"en":"a device that controls or regulates a machine or part of a machine","cn":"（机器或部件的）控制器，调节器","lab":"specialist","ex":{"en":"a temperature controller","cn":"温度控制器"}},{"en":"a person who is in charge of the financial accounts of a business company","cn":"（公司的）财务总管"},{"en":"an electronic device that is used to control video games via a computer or games console","cn":"游戏控制器"}]}},"cooperate":{"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"合作;协作","en":"If you co-operate with someone, you work with them or help them for a particular purpose. You can also say that two people co-operate .","ex":{"en":"The UN had been co-operating with the State Department on a plan to find countries willing to take the refugees","cn":"联合国一直都在与美国国务院合作推进一项计划，寻找愿意接纳难民的国家。"}},{"pos":"VERB 动词","cn":"合作;配合","en":"If you co-operate, you do what someone has asked or told you to do.","ex":{"en":"He agreed to co-operate with the police investigation","cn":"他同意配合警方的调查。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if two people or groups cooperate with each other, they work together and help each other in order to achieve something that will be good for both of them","cn":""},{"en":"to work together, especially on a specific piece of scientific, artistic, or industrial work","cn":""},{"en":"to work with someone else to achieve something that you both want","cn":"合作﹐协作"}]},"vocab":{"pos":"v","senses":[{"en":"When you cooperate , you work together. You can cooperate with the police by telling them everything you know about your neighbor’s pet leopard, or your preschooler can cooperate with you by doing everything you tell him to do, now!"}]},"collocations":{"phrases":["ADV. fully He has said he will cooperate fully with the police enquiries. | closely","VERB + COOPERATE will/would | agree to, be prepared to, be willing to | refuse to","PREP. in The two companies are cooperating in the development of a new engine. | on cooperating on a research project | with The firm has ag"]},"media":{"uk":"media/ldoce/hwd/bre/2/cooperate0205.mp3","us":"media/ldoce/hwd/ame/2/cooperate.mp3"},"examples":[{"en":"Their captors told them they would be killed unless they cooperated.","cn":"抓住他们的人说如果他们不配合就杀掉他们。"},{"en":"They had cooperated closely in the planning of the project.","cn":"他们曾密切合作，共同规划这一项目。"}],"oxford":{"phon":"kəʊˈɒpəreɪt","pos":"verb","senses":[{"en":"to work together with somebody else in order to achieve something","cn":"合作；协作","g":"[intransitive]","ex":{"en":"The two groups agreed to cooperate with each other.","cn":"这两个组同意相互协作。"}},{"en":"to be helpful by doing what somebody asks you to do","cn":"协助；配合","g":"[intransitive]","ex":{"en":"Their captors told them they would be killed unless they cooperated.","cn":"抓住他们的人说如果他们不配合就杀掉他们。"}}]}},"concentrated":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"浓缩的","en":"A concentrated liquid has been increased in strength by having water removed from it.","ex":{"en":"Sweeten dishes sparingly with honey, or concentrated apple or pear juice.","cn":"加一点蜂蜜或浓缩苹果汁或梨汁，让菜带点甜味。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（活动）集中的，密集的","en":"A concentrated activity is directed with great intensity in one place.","ex":{"en":"...a more concentrated effort to reach out to troubled kids.","cn":"把精力更多地集中在与问题儿童的沟通上"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a concentrated liquid or substance has been made stronger by removing water from it","cn":"浓缩的"},{"en":"showing a lot of effort or determination","cn":"全神贯注的﹔全力以赴的"}]},"vocab":{"pos":"adj","senses":[{"en":"Things that are concentrated have been gathered together in the smallest possible bunch. If you use a concentrated cleaning product, you might need to mix it with water before using it."}]},"collocations":{"phrases":["VERBS be","ADV. totally Kate sat up fully, her attention now totally concentrated. 2 of a substance","VERBS be","ADV. highly, very The liquid is found in a highly concentrated form. 3 found in one place","VERBS be","ADV. heavily, highly, particularly, strongly, very | increasingly | largely, mainly, mostly, overwhelmingly, primarily | disproportionately ","PREP. at, in Most of the country's industry is concentrated in the north. | within Childbearing is concentrated within the first decade of m"]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdeconcentrated.mp3","us":"media/ldoce/hwd/ame/b/concentrated.mp3"},"examples":[{"en":"He made a concentrated effort to finish the work on time.","cn":"他全力以赴以按时完成这项工作。"},{"en":"a concentrated solution of salt in water","cn":"浓缩盐水溶液"}],"oxford":{"phon":"ˈkɒnsntreɪtɪd","pos":"adjective","senses":[{"en":"showing that you are determined to do something","cn":"决心要做的；全力以赴的","ex":{"en":"He made a concentrated effort to finish the work on time.","cn":"他全力以赴以按时完成这项工作。"}},{"en":"made stronger because water or other substances have been removed","cn":"浓缩的","ex":{"en":"concentrated orange juice","cn":"浓缩橙汁"}},{"en":"if something exists or happens in a concentrated way, there is a lot of it in one place or at one time","cn":"密集的；集中的","ex":{"en":"concentrated gunfire","cn":"密集的炮火"}}]},"base":"concentrate"},"convulsion":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"抽搐;痉挛","en":"If someone has convulsions, they suffer uncontrollable movements of their muscles."},{"pos":"N-COUNT 可数名词","cn":"(国家、体系、组织发生的)动乱，骚乱","en":"If there are convulsions in a country, system, or organization, there are major unexpected changes in it.","ex":{"en":"...the political convulsions that led to de Gaulle's return to power in May 1958.","cn":"促使戴高乐在1958年5月重新上台的政治动乱"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you shake , your body makes small quick uncontrolled movements, for example because you are frightened, nervous, or angry","cn":""},{"en":"to shake very slightly, especially because you are frightened or upset","cn":""},{"en":"to shake because you are cold, or because of an emotion such as fear","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you see someone have a convulsion , it can either be scary or funny, depending on whether it's caused by a medical condition or a really funny joke. A convulsion is a jerking, uncontrolled movement."}]},"collocations":{"phrases":["ADJ. violent | slight | sudden","VERB + CONVULSION go into, have, suffer The patient lost consciousness and went into convulsions. | cause","CONVULSION + VERB shake sb A sudden convulsion shook him, and he fell to the ground."]},"media":{"uk":"media/ldoce/hwd/bre/8/convulsion0205.mp3","us":"media/ldoce/hwd/ame/9/convulsion.mp3"},"examples":[{"en":"The child went into convulsions.","cn":"那孩子全身抽搐起来。"},{"en":"His temperature was very high and he went into convulsions .","cn":"他的体温很高并开始抽搐。"}],"oxford":{"phon":"kənˈvʌlʃn","pos":"noun","senses":[{"en":"a sudden shaking movement of the body that cannot be controlled","cn":"惊厥；抽搐","ex":{"en":"The child went into convulsions.","cn":"那孩子全身抽搐起来。"}},{"en":"a sudden important change that happens to a country or an organization","cn":"动乱；骚动","ex":{"en":"political convulsions threatening the stability of new democracies","cn":"威胁新民主国家稳定的政治动乱"}}]}},"collector":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"收集者;收藏家","en":"A collector is a person who collects things of a particular type as a hobby.","ex":{"en":"...a stamp-collector.","cn":"集邮爱好者"}},{"pos":"N-COUNT 可数名词","cn":"(…的)收取人;讨债人;收税员;收票员;收垃圾者","en":"You can use collector to refer to someone whose job is to take something such as money, tickets, or rubbish from people. For example, a rent collector collects rent from people.","ex":{"en":"He earned his living as a tax collector.","cn":"他以收税为业。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who collects things that are interesting or attractive","cn":"收集者﹔收藏家"},{"en":"someone whose job is to collect taxes, tickets, debts etc","cn":"收税人﹔收票员﹔收债人"}]},"collocations":{"phrases":["ADJ. great, major a major collector of Japanese art | ardent, assiduous, avid, enthusiastic, keen, serious | private | art, coin, plant, rec","PHRASES a collector's item This vase is quite rare and is almost a collector's item."]},"media":{"uk":"media/ldoce/hwd/bre/8/collector0205.mp3","us":"media/ldoce/hwd/ame/b/collector.mp3"},"examples":[{"en":"ticket/tax/debt collectors","cn":"收票员；收税员；讨债人"},{"en":"a stamp collector","cn":"集邮者"}],"oxford":{"phon":"kəˈlektə(r)","pos":"noun","senses":[{"en":"a person who collects things, either as a hobby or as a job","cn":"收集者；收藏家","ex":{"en":"a stamp collector","cn":"集邮者"}},{"en":"the leader of a district in some South Asian countries","cn":"（南亚某些国家的）地方行政长官"}]}},"cookery":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"烹饪;烹调","en":"Cookery is the activity of preparing and cooking food.","ex":{"en":"The school runs cookery courses throughout the year.","cn":"这个学校常年开设烹饪学习班。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the activity of cooking","cn":""},{"en":"the activity or study of cooking","cn":""},{"en":"the way food is cooked by a particular person or in a particular place","cn":""}]},"collocations":{"phrases":["ADJ. basic Before he leaves home, he needs to learn some basic cookery. | step-by-step a step-by-step cookery series for beginners | vegetar","VERB + COOKERY learn","COOKERY + NOUN demonstration | class, course, lesson, school | book, column, magazine, programme | expert, writer"]},"media":{"uk":"media/ldoce/hwd/bre/c/cookery0205.mp3","us":"media/ldoce/hwd/ame/c/laadcookery.mp3"},"examples":[{"en":"Italian cookery","cn":"意大利烹饪"},{"en":"a cookery course","cn":"烹饪课程"}],"oxford":{"phon":"ˈkʊkəri","pos":"noun","senses":[{"en":"the art or activity of preparing and cooking food","cn":"烹饪术；烹饪；烹调","ex":{"en":"I'm going on a cookery course.","cn":"我正在上一个烹饪课程。"}}]}},"com":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the abbreviation of commercial organization , used in Internet addresses","cn":"商业机构〔用于因特网地址〕"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld44com.mp3","us":"media/ldoce/hwd/ame/d/ld44com.mp3"},"oxford":{"phon":"kɒm","pos":"abbreviation","senses":[{"en":"commercial organization","cn":"商业组织","ex":{"en":"The internet address of Oxford University Press is www.oup.com.","cn":"牛津大学出版社的互联网地址是 www.oup.com。"}}]}},"contemptuous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"蔑视的;藐视的;鄙视的","en":"If you are contemptuous of someone or something, you do not like or respect them at all.","ex":{"en":"He was contemptuous of private farmers","cn":"他看不起私营农场主。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"showing that you think someone or something deserves no respect","cn":"轻蔑的﹐鄙视的﹔傲慢不恭的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you insult someone or dismiss them in a hateful way, you're being contemptuous . The difference between being hateful and contemptuous is subtle. It involves disdain."}]},"collocations":{"phrases":["VERBS be, feel, sound Her voice sounded almost contemptuous.","ADV. savagely | utterly | almost | rather | openly","PREP. of He was utterly contemptuous of her efforts."]},"media":{"uk":"media/ldoce/hwd/bre/b/contemptuous0205.mp3","us":"media/ldoce/hwd/ame/7/contemptuous.mp3"},"examples":[{"en":"She gave him a contemptuous look.","cn":"她鄙夷地看了他一眼。"},{"en":"He was contemptuous of everything I did.","cn":"他看不起我做的一切。"}],"oxford":{"phon":"kənˈtemptʃuəs","pos":"adjective","senses":[{"en":"feeling or showing that you have no respect for somebody/something","cn":"蔑视的；鄙视的；表示轻蔑的","ex":{"en":"She gave him a contemptuous look.","cn":"她鄙夷地看了他一眼。"}}]}},"consultation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"商讨会;研讨;磋商","en":"A consultation is a meeting which is held to discuss something. Consultation is discussion about something.","ex":{"en":"Next week he'll be in Florida for consultations with President Mitterrand","cn":"下周，他将在佛罗里达与密特朗总统进行磋商。"}},{"pos":"N-VAR 可变名词","cn":"咨询;就诊","en":"A consultation with a doctor or other expert is a meeting with them to discuss a particular problem and get their advice. Consultation is the process of getting advice from a doctor or other expert.","ex":{"en":"A personal diet plan is devised after a consultation with a nutritionist.","cn":"咨询营养学家后，制订了个人饮食方案。"}},{"pos":"N-COUNT 可数名词","cn":"会诊","en":"A consultation is a meeting where several doctors discuss a patient and his or her condition and treatment."},{"pos":"N-UNCOUNT 不可数名词","cn":"查阅;参看","en":"Consultation of a book or other source of information is looking at it in order to find out certain facts.","ex":{"en":"With such excellent studies available for consultation, it should be easy to avoid the pitfalls.","cn":"有如此优秀的研究可供参考，避开陷阱应该很容易。"}},{"pos":"ADJ 形容词","cn":"(政府或机构旨在修改法律的文件)征询意见的","en":"A consultation paper or document is a document containing ideas for changes in the law. It is published by the government or by an organization, so that people can discuss it and give their opinions on it.","ex":{"en":"The Government proposed a common retirement age of 63 in a consultation paper published yesterday.","cn":"政府在昨天公布的征求意见稿中提出，一般退休年龄为63岁。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an occasion when you discuss something, or the process of discussing it","cn":""},{"en":"discussion of a particular subject that often continues for a long time, in which people express different opinions. Also used to mean a formal discussion of a subject, after which people vote for or against something","cn":""},{"en":"formal discussions between governments, organizations etc","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A consultation is a conference or meeting at which opinions are exchanged or advice is prescribed. If one doctor says your severe blueberry allergy is cured, you might want a consultation with another doctor before indulging in the forbidden fruit."}]},"collocations":{"phrases":["ADJ. close | extensive, full, wide | proper | joint a joint consultation with doctors and patients | public There will be a period of public","VERB + CONSULTATION have, hold The prime minister will hold a consultation with all the relevant groups.","CONSULTATION + NOUN document, paper | period","PREP. in ~ with The scheme was developed in close consultation with the local community. | without ~ They have taken this decision without a"]},"media":{"uk":"media/ldoce/hwd/bre/c/consultation0205.mp3","us":"media/ldoce/hwd/ame/4/consultation.mp3"},"examples":[{"en":"The decision was taken after close consultation with local residents.","cn":"这项决定是在与当地居民仔细磋商后作出的。"},{"en":"There is a large collection of texts available for consultation on-screen.","cn":"有大量的文本可通过电脑查阅。"}],"oxford":{"phon":"ˌkɒnslˈteɪʃn","pos":"noun","senses":[{"en":"the act of discussing something with somebody or with a group of people before making a decision about it","cn":"咨询；商讨；磋商","g":"[uncountable]","ex":{"en":"a consultation document/paper/period/process","cn":"咨询文件／论文／期／过程"}},{"en":"a formal meeting to discuss something","cn":"商讨会；协商会","g":"[countable]","ex":{"en":"There have been extensive consultations between the two countries.","cn":"两国之间进行了广泛磋商。"}},{"en":"a meeting with an expert, especially a doctor, to get advice or treatment","cn":"（向专家请教的）咨询会；（尤指）就诊","g":"[countable]","ex":{"en":"A 30-minute consultation will cost £50.","cn":"就诊30分钟要花50英镑。"}},{"en":"the act of looking for information in a book, etc.","cn":"查找；查阅；查看","g":"[uncountable]","ex":{"en":"There is a large collection of texts available for consultation on-screen.","cn":"有大量的文本可通过电脑查阅。"}}]}},"conceivable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"可想到的;可想象的;可以相信的","en":"If something is conceivable, you can imagine it or believe it.","ex":{"en":"Without their support the project would not have been conceivable","cn":"如果没有他们的支持，这个项目根本就不可想象。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"use this when you think that something may happen or may be true, but you are not sure. Perhaps is more formal than maybe .","cn":""},{"en":"use this with other verbs, to show that something is possible, or likely, but you are not sure about it. May and might are more formal than could","cn":""},{"en":"use this when you think that something may happen or may be done, but that it is not very likely","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you see yellowish skies on a humid, spring evening in Kansas, it is entirely conceivable that a tornado is in the making. That is to say, it's imaginable or even possible, so make sure you take every conceivable precaution."}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. entirely, perfectly, quite It's quite conceivable that she hasn't heard the news yet. | just I suppose it's just conceivable that we've","PHRASES every conceivable sth We had to draw up plans for every conceivable emergency."]},"media":{"uk":"media/ldoce/hwd/bre/c/conceivable0205.mp3","us":"media/ldoce/hwd/ame/f/conceivable.mp3"},"examples":[{"en":"a beautiful city with buildings of every conceivable age and style","cn":"拥有各个时代和各种风格建筑物的美丽城市"},{"en":"The disease could conceivably be transferred to humans.","cn":"这种疾病可能会传染给人类。"}],"oxford":{"phon":"kənˈsiːvəbl","pos":"adjective","senses":[{"en":"that you can imagine or believe","cn":"可想象的；可信的","ex":{"en":"It is conceivable that I'll see her tomorrow.","cn":"我可能明天会见到她。"}}]}},"contentious":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有争议的;引起争论的","en":"A contentious issue causes a lot of disagreement or arguments.","ex":{"en":"Sanctions are expected to be among the most contentious issues.","cn":"制裁可能会是争议最大的问题之一。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"爱争论的;动辄争吵的","en":"A contentious person seems to like arguing and disagreeing with other people.","ex":{"en":"Rodney was a cheerful, elegant and gregarious if rather contentious man.","cn":"罗德尼尽管非常喜欢与人争辩，却是个阳光、优雅、合群的人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"causing a lot of disagreement and angry argument, especially in the newspapers, on television etc","cn":""},{"en":"likely to cause a lot of disagreement and argument","cn":""},{"en":"used when you think that something is not certain and that people have different opinions about it, especially in the phrase it is debatable/arguable whether","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"A contentious issue is one that people are likely to argue about, and a contentious person is someone who likes to argue or fight."}]},"collocations":{"phrases":["VERBS be, prove | become | remain","ADV. highly, very Abortion is a highly contentious issue. | rather, somewhat | politically"]},"media":{"uk":"media/ldoce/hwd/bre/f/contentious0205.mp3","us":"media/ldoce/hwd/ame/e/contentious.mp3"},"examples":[{"en":"Both views are highly contentious.","cn":"两种观点都很有争议。"},{"en":"a contentious issue/topic/subject","cn":"有争议的问题/话题/主题"}],"oxford":{"phon":"kənˈtenʃəs","pos":"adjective","senses":[{"en":"likely to cause people to disagree","cn":"有争议的；可能引起争论的","ex":{"en":"a contentious issue/topic/subject","cn":"有争议的问题／话题／主题"}},{"en":"liking to argue; involving a lot of arguing","cn":"爱争论的；充满争吵的","ex":{"en":"a contentious meeting","cn":"争论不休的会议"}}]}},"cosmopolitan":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"世界性的，国际化的;受各国文化影响的","en":"A cosmopolitan place or society is full of people from many different countries and cultures.","ex":{"en":"London has always been a cosmopolitan city.","cn":"伦敦一直是一个国际化都市。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"见过世面的;见识广的;开明的","en":"Someone who is cosmopolitan has had a lot of contact with people and things from many different countries and as a result is very open to different ideas and ways of doing things.","ex":{"en":"The family are rich, and extremely sophisticated and cosmopolitan.","cn":"这家人很富有，老于世故，而且见多识广。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"when people are treated unfairly or attacked because of their race","cn":""},{"en":"divisions, problems etc between groups of people of different races, or with different customs, living in the same place, especially when one group is smaller than the other","cn":""},{"en":"a multiracial or multicultural society, school, community etc is one in which people from several different races live together or work together, especially in a friendly way","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"Your Aunt Eleanor, who's lived in six different countries and speaks four languages fluently, might be described as cosmopolitan , or comfortable and familiar with different cultures and people."}]},"collocations":{"phrases":["VERBS be","ADV. distinctly, truly, very"]},"media":{"uk":"media/ldoce/hwd/bre/7/cosmopolitan_a0205.mp3","us":"media/ldoce/hwd/ame/d/cosmopolitan1.mp3"},"examples":[{"en":"The club has a cosmopolitan atmosphere.","cn":"这个俱乐部具有世界文化的气氛。"},{"en":"She's a real cosmopolitan.","cn":"她是个真正的四海为家的人。"}],"oxford":{"phon":"ˌkɒzməˈpɒlɪtən","pos":"adjective","senses":[{"en":"containing people of different types or from different countries, and influenced by their culture","cn":"世界性的；全球各国的；有各国人的；受各国文化影响的","ex":{"en":"a cosmopolitan city/resort","cn":"国际性的都市／度假胜地"}},{"en":"having or showing a wide experience of people and things from many different countries","cn":"接触过许多国家的人（或事物）的；见过世面的；见识广的","ex":{"en":"people with a truly cosmopolitan outlook","cn":"真正具有世界眼光的人"}},{"en":"found all over the world","cn":"周游世界的人","lab":"specialist","ex":{"en":"Sea urchins are cosmopolitan in their distribution.","cn":"海胆分布广泛。"}},{"en":"a person who has a wide experience of people and things from many different countries","cn":"周游世界的人；见多识广的人","ex":{"en":"She's a real cosmopolitan.","cn":"她是个真正的四海为家的人。"},"pos":"noun"},{"en":"a magazine for young women, published each month and sold in over 110 countries around the world. It first appeared as a women's magazine in 1965 and was one of the first women's magazines to discuss sex.","cn":"世界性的：面向年轻女性的杂志，每月发行一次，在全球110多个国家销售。它于1965年首次出现在女性杂志上，并且是最早讨论性问题的女性杂志之一。","pos":""}]}},"correlation":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"关联;联系","en":"A correlation between things is a connection or link between them.","ex":{"en":"...the correlation between smoking and disease.","cn":"吸烟与疾病的联系"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the way in which two things are connected and affect each other, or the way in which the connection can be explained","cn":""},{"en":"a connection between two facts or events, especially when one causes or affects the other","cn":""},{"en":"if there is a correlation between two things, they happen or exist together and it seems likely that one causes or influences the other","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Correlation is something that scientists are often trying to show––is there a correlation between smoking and poor health or between napping and productivity? How about daily flossing and good grades?"}]},"collocations":{"phrases":["ADJ. close, good, high, remarkable, significant, strong | clear, obvious | direct, simple There is a direct correlation between exposure to ","VERB + CORRELATION have The second group of measurements had a high correlation with the first. | discover, establish, find, observe, show T","CORRELATION + VERB exist A strong correlation exists between the fatness of parents and their children.","PREP. ~ between the correlation between speed and risk of accident | ~ with the correlation of height with weight","PHRASES lack of correlation"]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdecorrelation.mp3","us":"media/ldoce/hwd/ame/c/correlation.mp3"},"examples":[{"en":"There is a direct correlation between exposure to sun and skin cancer.","cn":"暴露在太阳下与皮肤癌直接相关。"},{"en":"the correlation of social power with wealth","cn":"社会权力与财富的相关性"}],"oxford":{"phon":"ˌkɒrəˈleɪʃn","pos":"noun","senses":[{"en":"a connection between two things in which one thing changes as the other does","cn":"相互关系；相关；关联","ex":{"en":"There is a direct correlation between exposure to sun and skin cancer.","cn":"暴露在太阳下与皮肤癌直接相关。"}}]}},"coy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(对爱情或性爱)害羞的，腼腆的，故作忸怩的，假装害羞的","en":"A coy person is shy, or pretends to be shy, about love and sex.","ex":{"en":"She is modest without being coy","cn":"她很端庄，丝毫不忸怩。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(因愧疚或难为情而)含糊其辞的","en":"If someone is being coy, they are unwilling to talk about something that they feel guilty or embarrassed about.","ex":{"en":"The hotel are understandably coy about the incident","cn":"酒店对那次事件不愿多说，这可以理解。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not confident about talking to people, especially people you do not know","cn":""},{"en":"frightened to talk to people or to give your opinion, because you have very little confidence","cn":""},{"en":"someone who is bashful is unwilling to give their opinions or do something that they would enjoy, especially because they are embarrassed or afraid that they will look stupid","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Take the adjective, coy, for a person who pretends to be shy but really isn't, or someone who could give a definite answer but won't. Coy behavior can be playful or just plain annoying."}]},"collocations":{"phrases":["VERBS be | go","ADV. all, extremely, very He went all coy when I mentioned her name. | a bit, a little, rather She gave him a rather coy look. 2 unwilling t","VERBS be | remain","ADV. extremely, very | a little, rather Alicia was a little coy about how much the new dress had cost. | uncharacteristically","PREP. about"]},"media":{"uk":"media/ldoce/hwd/bre/1/coy0205.mp3","us":"media/ldoce/hwd/ame/9/coy.mp3"},"examples":[{"en":"She was a little coy about how much her dress cost.","cn":"她对她那条连衣裙花了多少钱有点吞吞吐吐。"},{"en":"She gave me a coy smile.","cn":"她羞答答地对我笑了笑。"}],"oxford":{"phon":"kɔɪ","pos":"adjective","senses":[{"en":"shy or pretending to be shy and innocent, especially about love or sex, sometimes in order to make people more interested in you","cn":"（尤指对爱情或性爱）羞羞答答的，假装害羞无知的，故作忸怩的","ex":{"en":"She gave me a coy smile.","cn":"她羞答答地对我笑了笑。"}},{"en":"not willing to give information about something, or give answers that tell people too much about you","cn":"不愿提供信息的；不肯作答的；含糊其词的","ex":{"en":"She was a little coy about how much her contract is worth.","cn":"对于她的合同价值多少，她有点含糊其辞。"}}]}},"conscription":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"征兵","en":"Conscription is officially making people in a particular country join the armed forces.","ex":{"en":"All adult males will be liable for conscription.","cn":"所有成年男子都有义务应征入伍。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to join the army","cn":""},{"en":"to be ordered to serve in the army by the government","cn":""},{"en":"a government policy of ordering people to serve in the army","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When a military needs people to fight in a war, but there aren’t enough volunteers, sometimes they'll begin conscription , which is a law that says if you are able to fight, you have to fight."}]},"collocations":{"phrases":["ADJ. universal | military","VERB + CONSCRIPTION introduce | abolish, end | avoid He injured himself to avoid conscription."]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41conscription.mp3","us":"media/ldoce/hwd/ame/c/conscription.mp3"},"oxford":{"phon":"kənˈskrɪpʃn","pos":"noun","senses":[{"en":"the practice of ordering people by law to join the armed forces","cn":"征募；征兵","ex":{"en":"the forced conscription of boys into the army","cn":"强征男青年服兵役"}}]}},"communist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"共产主义者","en":"A communist is someone who believes in communism."},{"pos":"ADJ 形容词","cn":"共产主义的","en":"Communist means relating to communism.","ex":{"en":"...the Communist Party.","cn":"共产党"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is a member of a political party that supports communism, or who believes in communism","cn":"共产党员﹔共产主义者"},{"en":"relating to communism","cn":"共产主义的"}]},"vocab":{"pos":"adj n","senses":[{"en":"Communism is a political doctrine that is an extreme form of Socialism, and anyone belonging to this particular political party is called a communist . A handful of countries call themselves communist , including China, Cuba, and North Korea — though many communists would disagre"}]},"collocations":{"phrases":["ADJ. militant, revolutionary | hardline, old-style, orthodox | reform/reformed | former The president of the new democracy is actually a for"]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdecommunist.mp3","us":"media/ldoce/hwd/ame/8/amelasdecommunist.mp3"},"examples":[{"en":"a Communist country/government/leader","cn":"共产主义的国家/政府/领袖"},{"en":"communist ideology","cn":"共产主义的思想体系"}],"oxford":{"phon":"ˈkɒmjənɪst","pos":"adjective","senses":[{"en":"connected with communism","cn":"共产主义的","ex":{"en":"communist ideology","cn":"共产主义思想体系"}},{"en":"governed by or belonging to a Communist party","cn":"共产党的","ex":{"en":"a Communist country/government/leader","cn":"共产党国家／政府／领导人"}},{"en":"a person who believes in or supports communism","cn":"共产主义者；共产主义的支持者","pos":"noun"},{"en":"a member of a Communist Party","cn":"共产党党员","ex":{"en":"The president of the new democracy is actually a former Communist.","cn":"新民主政体的总统实际上是一个前共产党人。"},"pos":"noun"}]}},"cock":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"公鸡;雄鸡","en":"A cock is an adult male chicken.","ex":{"en":"The cock was announcing the start of a new day.","cn":"雄鸡正在报晓。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指作为猎捕对象的)雄鸟，雄禽","en":"You refer to a male bird, especially a male game bird, as a cock when you want to distinguish it from a female bird.","ex":{"en":"...a cock pheasant.","cn":"雄雉"}},{"pos":"N-COUNT 可数名词","cn":"鸡巴","en":"A man's cock is his penis."},{"pos":"VERB 动词","cn":"翘起，竖起(身体部位)","en":"If you cock a part of your body in a particular direction, you lift it or point it in that direction.","ex":{"en":"He paused and cocked his head as if listening","cn":"他停顿了一下，歪着头，好像是在听。"}},{"pos":"VERB 动词","cn":"竖起（耳朵）听;侧（耳）倾听","en":"If someone cocks their ear, they try very hard to hear something from a particular direction.","ex":{"en":"He suddenly cocked an ear and listened","cn":"他突然竖起耳朵仔细倾听。"}},{"pos":"VERB 动词","cn":"扳上(枪)的扳机","en":"When someone cocks a gun, they set a small device in the gun so that it is ready to fire.","ex":{"en":"His hands were too weak to cock his revolver.","cn":"他的手没劲儿，扳不动左轮手枪的扳机。"}},{"pos":"","cn":"","en":"to cock a snook at someone→see: ;"},{"pos":"","cn":"","en":"相关词组：cock up"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an adult male chicken","cn":"公鸡"},{"en":"an adult male bird of any kind","cn":"雄鸟﹐雄禽"},{"en":"a penis","cn":"阴茎"}]},"vocab":{"pos":"1 n v 2 v n 3 n 4 v ","senses":[{"en":"Cock is most often used to refer to either birds or guns. A cock is a rooster, but it's also the hammer on a gun that you adjust so you can fire it."}]},"collocations":{"phrases":["ADJ. fighting | barnyard The market traders cried out like barnyard cocks.","COCK + VERB crow The cock crowed at dawn.","COCK + NOUN fight, fighting"]},"media":{"img":["media/ldoce/img/cockerel.jpg"],"uk":"media/ldoce/hwd/bre/1/brelasdecock.mp3","us":"media/ldoce/hwd/ame/e/cock1.mp3"},"examples":[{"en":"The dog cocked its leg by every tree on our route (= in order to urinate ).","cn":"这狗在我们一路上走过每棵树时都抬起一条腿（撒尿）。"},{"en":"She cocked up all the arrangements for the party.","cn":"她把聚会的安排搞得一塌糊涂。"}],"oxford":{"phon":"kɒk","pos":"noun","senses":[{"en":"an adult male chicken","cn":"公鸡；雄鸡","g":"[countable]","lab":"British English","ex":{"en":"The cock crowed.","cn":"公鸡啼叫。"}},{"en":"a male of any other bird","cn":"雄禽","g":"[countable]","ex":{"en":"a cock pheasant","cn":"雄雉"}},{"en":"a penis","cn":"鸡巴；屌","g":"[countable]","lab":"taboo, slang，，"},{"en":"a tap that controls the flow of liquid or gas through a pipe","cn":"（调节管道流量的）旋塞，活栓","g":"[countable]"},{"en":"used as a friendly form of address between men","cn":"（男子间友好的称呼）老兄，家伙，伙计","g":"[singular]","lab":"British English, old-fashioned, slang，，，，"},{"en":"to raise a part of your body so that it is pointing upwards or at an angle","cn":"立起，竖起，翘起（身体部位）","ex":{"en":"The dog cocked its leg by every tree on our route (= in order to urinate).","cn":"这狗在我们一路上走过每棵树时都抬起一条腿（撒尿）。"},"pos":"verb"},{"en":"to raise the hammer on a gun so that it is ready to fire","cn":"扣（或扳）上扳机准备射击","pos":"verb"}]}},"condone":{"collins":{"senses":[{"pos":"VERB 动词","cn":"容忍，纵容（不道德行为）","en":"If someone condones behaviour that is morally wrong, they accept it and allow it to happen.","ex":{"en":"I have never encouraged nor condoned violence","cn":"我从不煽动也不纵容暴力行为。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to approve of something -- used especially when you are talking about something other people might not agree with","cn":""},{"en":"to approve of something such as a decision, a way of doing something, or a plan","cn":""},{"en":"to approve of a type of behaviour or way of doing something, especially because you think there are important principles involved","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If you condone something, you allow it, approve of it, or at least can live with it. Some teachers condone chewing gum, and some don't."}]},"collocations":{"phrases":["ADV. tacitly","VERB + CONDONE cannot/could not We cannot condone violence of any sort."]},"media":{"uk":"media/ldoce/hwd/bre/4/condone0205.mp3","us":"media/ldoce/hwd/ame/b/condone.mp3"},"examples":[{"en":"Terrorism can never be condoned.","cn":"决不能容忍恐怖主义。"},{"en":"I cannot condone the use of violence under any circumstances.","cn":"我不能原谅在任何情况下使用暴力。"}],"oxford":{"phon":"kənˈdəʊn","pos":"verb","senses":[{"en":"to accept behaviour that is morally wrong or to treat it as if it were not serious","cn":"容忍；纵容","ex":{"en":"Terrorism can never be condoned.","cn":"决不能容忍恐怖主义。"}}]}},"corrosive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"腐蚀性的;侵蚀性的","en":"A corrosive substance is able to destroy solid materials by a chemical reaction.","ex":{"en":"Sodium and sulphur are highly corrosive.","cn":"钠和硫磺腐蚀性很强。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"逐渐起破坏作用的;损害性的","en":"If you say that something has a corrosive effect, you mean that it gradually causes serious harm.","ex":{"en":"...the corrosive effects of inflation.","cn":"通货膨胀的破坏作用"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a corrosive liquid such as an acid can destroy metal, plastic etc","cn":"腐蚀性的﹔侵蚀性的"},{"en":"gradually making something weaker, and possibly destroying it","cn":"有害的﹐起损害作用的"}]},"vocab":{"pos":"adj n","senses":[{"en":"A corrosive substance, like hydrochloric acid, will eat away most things on which it is spilled. Watch out in Chemistry lab: you wouldn't want to destroy your homework, desk, or worse, your own skin by spilling something corrosive on it."}]},"collocations":{"phrases":["VERBS be","ADV. highly, strongly, very Many highly corrosive substances are used in the nuclear industry."]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41corrosive.mp3","us":"media/ldoce/hwd/ame/c/corrosive.mp3"},"examples":[{"en":"Unemployment is having a corrosive effect on our economy.","cn":"失业对我国的经济起着破坏作用。"},{"en":"the corrosive effects of salt water","cn":"盐水的腐蚀作用"}],"oxford":{"phon":"kəˈrəʊsɪv","pos":"adjective","senses":[{"en":"tending to destroy something slowly by chemical action","cn":"腐蚀性的；侵蚀性的","ex":{"en":"the corrosive effects of salt water","cn":"盐水的腐蚀作用"}},{"en":"tending to damage something gradually","cn":"损害性的；逐渐起破坏作用的","lab":"formal","ex":{"en":"Unemployment is having a corrosive effect on our economy.","cn":"失业对我国的经济起着破坏作用。"}}]}},"convoy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"车队;舰队","en":"A convoy is a group of vehicles or ships travelling together.","ex":{"en":"...a U.N. convoy carrying food and medical supplies","cn":"运送食品和医疗用品的联合国车队"}},{"pos":"VERB 动词","cn":"护送;护卫;为…护航","en":"To convoy goods or people somewhere means to move them there in a convoy.","ex":{"en":"He ordered the combined fleet to convoy troops to Naples.","cn":"他命令联合舰队将军队护送到那不勒斯。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of vehicles or ships travelling together, sometimes in order to protect one another 〔","cn":"负责护送的〕车队﹐舰队"},{"en":"convoy of The British left in a convoy of 20 cars.","cn":"英国人在一支由20辆汽车组成的车队护送下离开了。 in convoy We drove in convoy. 我们结队驾车。 a military convoy 军方的护送舰队 aid/relief/food etc convoy 援助/救"},{"en":"to travel with something in order to protect it","cn":"护送﹔护航"}]},"vocab":{"pos":"n v","senses":[{"en":"To travel in a convoy is to be escorted by a group of protective vehicles. If you are a teenage rock star with millions of fans, you probably need a security convoy just to go visit your grandmother."}]},"collocations":{"phrases":["ADJ. armed, army, military, naval, troop | road, vehicle | aid, food, humanitarian, relief the proposal to send 500 armed soldiers to escort","VERB + CONVOY lead | escort, protect | attack","CONVOY + VERB carry sth | arrive","PREP. in ~ The ships travelled in convoy. | ~ of a large convoy of lorries carrying medical supplies | ~ to the next aid convoy to the war-t"]},"media":{"uk":"media/ldoce/hwd/bre/b/convoy_n0205.mp3","us":"media/ldoce/hwd/ame/8/convoy1.mp3"},"examples":[{"en":"A United Nations aid convoy loaded with food and medicine finally got through to the besieged town.","cn":"一支联合国援助车队载着食物和药物终于抵达了被围困的市镇。"},{"en":"We drove in convoy because I didn't know the route.","cn":"因为我不熟悉路线，所以我们结队行驶。"}],"oxford":{"phon":"ˈkɒnvɔɪ","pos":"noun","senses":[{"en":"a group of vehicles or ships travelling together, especially when soldiers or other vehicles travel with them for protection","cn":"（尤指有士兵护送的）车队，船队","ex":{"en":"a convoy of trucks/lorries/freighters","cn":"被护送的卡车／货船队"}}]}},"compassion":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"怜悯;同情","en":"Compassion is a feeling of pity, sympathy, and understanding for someone who is suffering.","ex":{"en":"Elderly people need time and compassion from their physicians.","cn":"老年人需要医生多花时间，还需要他们的关爱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling you have when you are sorry for someone who is having problems, and you understand how they feel","cn":""},{"en":"a feeling that you have when you feel very sorry for someone, often when you are unable to help them","cn":""},{"en":"a strong feeling of pity for someone who is suffering, and a desire to help them","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If someone shows kindness, caring, and a willingness to help others, they're showing compassion ."}]},"collocations":{"phrases":["ADJ. deep, great | genuine","VERB + COMPASSION be filled with, feel, have I survived. Someone or something had had compassion on me. | show (sb) | lack","PREP. ~ for He was filled with overwhelming love and compassion for his wife. | ~ towards I felt no compassion towards her. | with ~ The old","PHRASES love and compassion"]},"media":{"uk":"media/ldoce/hwd/bre/0/compassion0205.mp3","us":"media/ldoce/hwd/ame/b/compassion.mp3"},"examples":[{"en":"to feel/show compassion","cn":"感到/表示同情"}],"oxford":{"phon":"kəmˈpæʃn","pos":"noun","senses":[{"en":"a strong feeling of sympathy for people or animals who are suffering and a desire to help them","cn":"同情；怜悯；爱心","ex":{"en":"to feel/show compassion","cn":"感到／表示同情"}}]}},"counterargument":{"vocab":{"pos":"n","senses":[{"en":"A counterargument is the thoughtful response you give when you disagree with someone's ideas or claims. In criminal court, a defense attorney usually gives a counterargument to the prosecutor's accusations."}]},"oxford":{"phon":"ˈkaʊntərɑːɡjumənt","pos":"noun","senses":[{"en":"an argument or set of reasons that you put forward to oppose an idea or theory","cn":"用来驳斥的观点；用来辩驳的观点","ex":{"en":"Meyer offers a strong counterargument to these claims.","cn":"迈耶对这些言论提出了有力的反驳。"}}]}},"consistent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(行为、态度等)一贯的，一致的，始终如一的","en":"Someone who is consistent always behaves in the same way, has the same attitudes towards people or things, or achieves the same level of success in something.","ex":{"en":"Becker has never been the most consistent of players anyway.","cn":"不管怎么说，贝克尔从来就不是表现最为稳定的球员。"}},{"pos":"ADJ 形容词","cn":"（观点等）一致的，吻合的，不矛盾的","en":"If one fact or idea is consistent with another, they do not contradict each other.","ex":{"en":"This result is consistent with the findings of Garnett & Tobin","cn":"这个结果与加尼特托宾公司的调查结果一致。"}},{"pos":"ADJ 形容词","cn":"(观点或看法)前后一致的，连贯的","en":"An argument or set of ideas that is consistent is one in which no part contradicts or conflicts with any other part.","ex":{"en":"These are clear consistent policies which we are putting into place.","cn":"这些就是我们正在付诸实施的政策，不但清楚而且前后一致。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to continue to be the same and not change","cn":""},{"en":"an amount, temperature, rate etc that is constant stays the same and does not change","cn":""},{"en":"always staying the same in your beliefs, your behaviour, the quality of your work etc","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you get the same Donkey Kong score every time you play, you're consistent . It's consistent with video-game addiction, however, that you will continue to play in the hopes of beating that score."}]},"collocations":{"phrases":["VERBS be | remain","ADV. highly, remarkably, very | absolutely, completely, entirely, quite, wholly His attitude isn't absolutely consistent. | largely | fairly","VERBS be, seem | remain","ADV. completely, entirely, fully, perfectly | broadly, largely | fairly, quite, reasonably | internally His argument is not even internally ","PREP. across These findings are consistent across all the studies. | with The figures are fully consistent with last year's results."]},"media":{"uk":"media/ldoce/hwd/bre/9/consistent0205.mp3","us":"media/ldoce/hwd/ame/9/consistent.mp3"},"examples":[{"en":"The results are entirely consistent with our earlier research.","cn":"这些结果与我们早些时候的研究完全吻合。"},{"en":"He has been Milan's most consistent (= most consistently good) player this season.","cn":"他是米兰队这个赛季状态最稳定的队员。"}],"oxford":{"phon":"kənˈsɪstənt","pos":"adjective","senses":[{"en":"always behaving in the same way, or having the same opinions, standards, etc.","cn":"一致的；始终如一的","lab":"approving","ex":{"en":"a consistent approach to the problem","cn":"解决问题的一贯方法"}},{"en":"happening in the same way and continuing for a period of time","cn":"连续的；持续的","ex":{"en":"We have had enough of the party's consistent failure to come up with any new policies.","cn":"我们已经受够了党一贯的失败，无法提出任何新政策。"}},{"en":"in agreement with something; not contradicting something","cn":"与…一致的；相符的；符合的；不矛盾的","ex":{"en":"The results are entirely consistent with our earlier research.","cn":"这些结果与我们早些时候的研究完全吻合。"}},{"en":"having different parts that all agree with each other","cn":"相互连贯的","ex":{"en":"a well-thought-out and consistent argument","cn":"经过深思熟虑的、相互连贯的论点"}}]}},"confederation":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of people, political parties, or organizations that have united for political purposes or trade","cn":"联盟﹔同盟"}]},"vocab":{"pos":"n","senses":[{"en":"When a group of people or nations form an alliance, it is called a confederation , allowing each member to govern itself but agreeing to work together for common causes. Perhaps the best-known confederation was the South during the U.S. Civil War."}]},"collocations":{"phrases":["ADJ. loose The Franks were originally a loose confederation of Germanic tribes.","VERB + CONFEDERATION establish, form, found | join","PREP. ~ between a confederation between two states | ~ of a confederation of employers"]},"media":{"uk":"media/ldoce/hwd/bre/8/confederation0205.mp3","us":"media/ldoce/hwd/ame/5/confederation.mp3"},"examples":[{"en":"the Confederation of British Industry","cn":"英国工业联合会"}],"oxford":{"phon":"kənˌfedəˈreɪʃn","pos":"noun","senses":[{"en":"an organization consisting of countries, businesses, etc. that have joined together in order to help each other","cn":"联盟；联合体","ex":{"en":"the Confederation of British Industry","cn":"英国工业联合会"}},{"en":"(in Canada) the joining together of provinces and territories forming Canada, which began 1 July, 1867","cn":"加拿大联邦（从 1867 年 7 月 1 日起由若干省和地区组成加拿大）"}]}},"contingent":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(警察、军队或军用车辆的)分遣队，小分队","en":"A contingent of police, soldiers, or military vehicles is a group of them.","ex":{"en":"Nigeria provided a large contingent of troops to the West African Peacekeeping Force","cn":"尼日利亚向西非维和部队派遣了一大批军队。"}},{"pos":"N-COUNT 可数名词","cn":"代表团;代表队;代表群体","en":"A contingent is a group of people representing a country or organization at a meeting or other event.","ex":{"en":"The strong British contingent suffered mixed fortunes","cn":"实力雄厚的英国军团喜忧参半。"}},{"pos":"ADJ 形容词","cn":"取决于…的;由…决定的","en":"If something is contingent on something else, the first thing depends on the second in order to happen or exist.","ex":{"en":"In effect, growth is contingent on improved incomes for the mass of the low-income population.","cn":"事实上，发展有赖于大量低收入人群收入的增长。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"depending on something that may happen in the future","cn":"依情况而变的﹐视条件而定的"},{"en":"a group of people that someone has organized in order to go somewhere or do something","cn":""},{"en":"a group of people who do things together or spend time together","cn":""}]},"vocab":{"pos":"1 adj 2 n 3 n","senses":[{"en":"The adjective contingent can be used to describe when something can occur only when something else does first. Making money is contingent on finding a good-paying job."}]},"collocations":{"phrases":["ADJ. large, strong, substantial | military, naval, police | British, UN, etc.","PREP. ~ from a strong contingent from Camberwell Art School | ~ of a large contingent of American troops"]},"media":{"uk":"media/ldoce/hwd/bre/d/contingent_n0205.mp3","us":"media/ldoce/hwd/ame/9/contingent1.mp3"},"examples":[{"en":"A strong contingent of local residents were there to block the proposal.","cn":"由当地居民组成的强大的代表团在那里阻止通过这项提案。"},{"en":"All payments are contingent upon satisfactory completion dates.","cn":"所有的付款须视乎是否如期完成。"}],"oxford":{"phon":"kənˈtɪndʒənt","pos":"noun","senses":[{"en":"a group of people at a meeting or an event who have something in common, especially the place they come from, that is not shared by other people at the event","cn":"（有共同点的，尤指来自同一地方的）一组与会者，代表团","ex":{"en":"The largest contingent was from the United States.","cn":"最大的会议代表团来自美国。"}},{"en":"a group of soldiers that are part of a larger force","cn":"（军队的）分遣队，小分队","ex":{"en":"The French contingent in the UN peacekeeping force withdrew.","cn":"联合国维和部队的法国分队撤离了。"}},{"en":"depending on something that may or may not happen","cn":"依情况而定的","lab":"formal","ex":{"en":"All payments are contingent upon satisfactory completion dates.","cn":"所有的付款须视是否如期完成而定。"},"pos":"adjective"},{"en":"a person, or work done by a person, who does not have a permanent contract with a company","cn":"临时工；临时工作","lab":"business","ex":{"en":"the spread of contingent work throughout the economy","cn":"临时工作在整个经济领域的扩展"},"pos":"adjective"}]}},"conform":{"collins":{"senses":[{"pos":"VERB 动词","cn":"遵守，遵从，符合(法律、意愿等)","en":"If something conforms to something such as a law or someone's wishes, it is of the required type or quality.","ex":{"en":"The Night Rider lamp has been designed to conform to new British Standard safety requirements","cn":"“夜行者”灯的设计符合新的英国安全标准的要求。"}},{"pos":"VERB 动词","cn":"按规矩行事;顺从;随潮流","en":"If you conform, you behave in the way that you are expected or supposed to behave.","ex":{"en":"Many children who can't or don't conform are often bullied","cn":"很多不能或不按规矩行事的小孩常常被人欺负。"}},{"pos":"VERB 动词","cn":"(与样式、类型等)非常相似，一致，相吻合","en":"If someone or something conforms to a pattern or type, they are very similar to it.","ex":{"en":"I am well aware that we all conform to one stereotype or another","cn":"我们所有人都能找到某种与自己相似的模式化形象，这一点我很清楚。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do and say things that are good, bad, normal, strange etc","cn":""},{"en":"to behave in a particular way, especially in a way that seems unusual, surprising, or annoying to other people","cn":""},{"en":"to behave towards someone or deal with someone in a particular way","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To conform means to adapt to fit in with new conditions. So if you travel to Morocco, you should conform to the local custom and adjust your usually skin-bearing wardrobe to one that is more modest."}]},"collocations":{"phrases":["ADV. fully","VERB + CONFORM be required to, must, should | fail to The toys fail to conform to current safety standards.","PREP. to All companies are required to conform to these rules. | with This equipment conforms fully with the latest safety regulations."]},"media":{"uk":"media/ldoce/hwd/bre/6/conform0205.mp3","us":"media/ldoce/hwd/ame/a/conform.mp3"},"examples":[{"en":"It did not conform to the usual stereotype of an industrial city.","cn":"这和工业城市那种千篇一律的格局不一样。"},{"en":"There is considerable pressure on teenagers to conform.","cn":"青少年承受着相当大的社会压力。"}],"oxford":{"phon":"kənˈfɔːm","pos":"verb","senses":[{"en":"to behave and think in the same way as most other people in a group or society","cn":"顺从，顺应（大多数人或社会）；随潮流","g":"[intransitive]","ex":{"en":"There is considerable pressure on teenagers to conform.","cn":"青少年被大力要求守规矩。"}},{"en":"to obey a rule, law, etc.","cn":"遵守，遵从，服从（规则、法律等）","g":"[intransitive]","ex":{"en":"The building does not conform with safety regulations.","cn":"这座建筑物不符合安全条例。"}},{"en":"to agree with or match something","cn":"相一致；相符合；相吻合","g":"[intransitive]","ex":{"en":"It did not conform to the usual stereotype of an industrial city.","cn":"这和工业城市那种千篇一律的格局不一样。"}}]}},"contrived":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"人为的;虚假的;捏造的;矫揉造作的","en":"If you say that something someone says or does is contrived, you think it is false and deliberate, rather than natural and not planned.","ex":{"en":"There was nothing contrived or calculated about what he said","cn":"他说的话里没有任何蓄意捏造的成分。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(戏剧、电影、小说等)虚构的，不足信的，不真实的","en":"If you say that the plot of a play, film, or novel is contrived, you mean that it is unlikely and unconvincing.","ex":{"en":"The plot seems contrived.","cn":"情节看起来不真实。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"abstract paintings, pictures, designs etc contain shapes and images that represent real things and people but do not look like them","cn":""},{"en":"something that is unrealistic shows or describes things in a way that does not seem real, and is therefore not very good or cannot be believed","cn":""},{"en":"a story, situation etc that is contrived has been written or arranged in a way that seems false and not natural","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you see something that seems fake since it was too perfectly planned out, call it contrived . If you can easily predict the final minutes of a made-for-TV movie, then call it contrived ."}]},"collocations":{"phrases":["VERBS be, seem, sound","ADV. highly, very highly contrived laboratory conditions | a little, rather, somewhat | carefully the carefully contrived image of party uni"]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdecontrived.mp3","us":"media/ldoce/hwd/ame/e/contrived.mp3"},"examples":[{"en":"The book's happy ending seemed contrived.","cn":"这部书大团圆的结局读来让人感到不真实。"},{"en":"a contrived situation","cn":"人为的状况"}],"oxford":{"phon":"kənˈtraɪvd","pos":"adjective","senses":[{"en":"planned in advance and not natural or what somebody claims it is; written or arranged in a way that is not natural or realistic","cn":"预谋的；不自然的；人为的；做作的","ex":{"en":"a contrived situation","cn":"人为的状况"}}]}},"coalition":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"联合政府","en":"A coalition is a government consisting of people from two or more political parties.","ex":{"en":"Since June the country has had a coalition government","cn":"从6月份起，该国一直由一个联合政府执掌政权。"}},{"pos":"N-COUNT 可数名词","cn":"(政党、社团等的)同盟，联盟","en":"A coalition is a group consisting of people from different political or social groups who are co-operating to achieve a particular aim.","ex":{"en":"He had been opposed by a coalition of about 50 civil rights, women's and Latino organizations.","cn":"大约有50个民权组织、女性社团和拉丁裔社团联合起来反对他。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a union of two or more political parties that allows them to form a government or fight an election together 〔","cn":"由两个或两个以上政党组成的〕联盟"},{"en":"a group of people who join together to achieve a particular purpose, usually a political one 〔","cn":"常为某种政治目的而组成的〕联盟﹐同盟"},{"en":"a process in which two or more political parties or groups join together 〔","cn":"两个或两个以上政治党派或团体的〕联合﹐结盟"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A coalition is a group of people who join together for a common cause, like a coalition you form with other skateboarders who want to convince your town to build a skate park."}]},"collocations":{"phrases":["ADJ. strong | loose | broad, broad-based, rainbow, umbrella an umbrella coalition of human rights organizations | grand a grand coalition of","VERB + COALITION create, form The centre-right opposition parties have formed a coalition. | join | lead a coalition led by the Socialist Pa","COALITION + VERB break up, collapse, fall (apart)","COALITION + NOUN government | forces, member, partner, party","PREP. in (a/the) ~ The two parties governed in coalition for four years. the biggest party in the government coalition | ~ between a coaliti"]},"media":{"uk":"media/ldoce/hwd/bre/8/coalition0205.mp3","us":"media/ldoce/hwd/ame/c/coalition.mp3"},"examples":[{"en":"They didn't rule out coalition with the Social Democrats.","cn":"他们不排除与社会民主党人结盟的可能性。"},{"en":"a coalition of environmental and consumer groups","cn":"环境保护和消费者团体的联盟"}],"oxford":{"phon":"ˌkəʊəˈlɪʃn","pos":"noun","senses":[{"en":"a government formed by two or more political parties working together","cn":"（两党或多党）联合政府","ex":{"en":"The two parties have formed a coalition.","cn":"两党结成了一个联盟。"}},{"en":"a group formed by people from several different groups, especially political ones, agreeing to work together for a particular purpose","cn":"（尤指多个政治团体的）联合体，联盟","ex":{"en":"The network is a global coalition of environmental and consumer groups.","cn":"这个圈子网罗了全球的环境保护团体和消费者团体。"}}]}},"confrontation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"对抗;冲突;战斗;战役","en":"A confrontation is a dispute, fight, or battle between two groups of people.","ex":{"en":"The issue has caused great tension between the two countries and could lead to a military confrontation","cn":"这个问题使得两国关系非常紧张，可能会导致军事对抗。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when a lot of people fight each other in a public place","cn":""},{"en":"an uncontrolled violent fight in a public place that involves a large number of people and usually damage to property, cars etc, especially among people who are protesting about something","cn":""},{"en":"a fight between two large groups of people","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A confrontation is an angry disagreement. You might become so irritated about your upstairs neighbor's loud, awful music that a confrontation is unavoidable."}]},"collocations":{"phrases":["ADJ. full-scale, major, serious Their demands could lead to a serious confrontation with management. | direct, eyeball-to-eyeball, face-to-f","QUANT. series","VERB + CONFRONTATION have | cause, end in, lead to, provoke | bring sb into His actions brought him into direct confrontation with the autho","CONFRONTATION + VERB arise, take place","PREP. ~ between a head-on confrontation between the two governments | ~ over She had a series of heated confrontations with her parents over"]},"media":{"uk":"media/ldoce/hwd/bre/6/confrontation0205.mp3","us":"media/ldoce/hwd/ame/9/confrontation.mp3"},"examples":[{"en":"She wanted to avoid another confrontation with her father.","cn":"她想避免和父亲再次发生冲突。"},{"en":"confrontation between employers and unions","cn":"资方与工会之间的对峙"}],"oxford":{"phon":"ˌkɒnfrʌnˈteɪʃn","pos":"noun","senses":[{"en":"a situation in which there is anger between people or groups who disagree because they have different opinions","cn":"对抗；对峙；冲突","ex":{"en":"She wanted to avoid another confrontation with her father.","cn":"她想避免和父亲再次发生冲突。"}}]}},"compulsion":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"强烈欲望;(难以克制的)冲动","en":"A compulsion is a strong desire to do something, which you find difficult to control.","ex":{"en":"He felt a sudden compulsion to drop the bucket and run","cn":"他突然有一种想扔掉水桶撒腿就跑的冲动。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"强迫;强制","en":"If someone uses compulsion in order to get you to do something, they force you to do it, for example by threatening to punish you if you do not do it.","ex":{"en":"Many universities argued that students learned more when they were in classes out of choice rather than compulsion","cn":"很多大学认为如果学生上课是出于自愿而不是被迫，那么他们学到的东西会更多。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong feeling of wanting to have something or wanting to do something, especially something important, which makes you try very hard to have it or do it","cn":""},{"en":"something that you want to happen, especially when this is very important to you","cn":""},{"en":"a very strong and long-lasting desire for something that you are unlikely to get - used especially in stories and literature","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Let's say you have a secret. You've promised not to tell, but there's something forcing you to call a friend and spill the beans. This force is compulsion , that urge to do something even though you know you shouldn't."}]},"collocations":{"phrases":["ADJ. strange | inner","QUANT. element There is an element of compulsion in the new scheme for the unemployed.","VERB + COMPULSION feel, have He felt an inner compulsion to write.","PREP. under ~ You're under no compulsion to take part."]},"media":{"uk":"media/ldoce/hwd/bre/b/compulsion0205.mp3","us":"media/ldoce/hwd/ame/5/compulsion.mp3"},"examples":[{"en":"He felt a great compulsion to tell her everything.","cn":"他感到一阵强烈的冲动，想要把一切都告诉她。"},{"en":"You are under no compulsion to pay immediately.","cn":"没有人强迫你立刻付款。"}],"oxford":{"phon":"kəmˈpʌlʃn","pos":"noun","senses":[{"en":"strong pressure that makes somebody do something that they do not want to do","cn":"强迫；强制","g":"[uncountable, countable]","lab":"formal","ex":{"en":"You are under no compulsion to pay immediately.","cn":"没有人强迫你立刻付款。"}},{"en":"a strong desire to do something, especially something that is wrong, silly or dangerous","cn":"（尤指做不正确、愚蠢或危险的事的）强烈欲望，冲动","g":"[countable]","ex":{"en":"He felt a great compulsion to tell her everything.","cn":"他感到一阵强烈的冲动，想要把一切都告诉她。"}}]}},"conception":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"概念;观念;想法","en":"A conception of something is an idea that you have of it in your mind.","ex":{"en":"My conception of a garden was based on gardens I had visited in England","cn":"我对花园的概念是基于我在英格兰观赏过的花园。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"构想;构思;设想","en":"Conception is the forming of an idea for something in your mind.","ex":{"en":"The symphony is admirable in conception","cn":"这支交响乐的构思好极了。"}},{"pos":"N-VAR 可变名词","cn":"受孕;怀孕","en":"Conception is the process in which the egg in a woman is fertilized and she becomes pregnant.","ex":{"en":"Six weeks after conception your baby is the size of your little fingernail","cn":"怀孕6个星期后，胎儿的大小相当于小拇指的指甲。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an idea about what something is like, or a general understanding of something","cn":"概念﹔观念﹐思想﹔想法"},{"en":"a process in which someone forms a plan or idea","cn":"构思﹐构想﹐设想"},{"en":"the process by which a woman or female animal becomes pregnant , or the time when this happens","cn":"受孕﹔怀孕"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Conception means any idea or concept, or a sum of ideas and concepts. Your conception for designing the little girl's room with a princess theme was a hit. Her evil stepsisters are jealous."}]},"collocations":{"phrases":["ADJ. clear, distinct We now have a clearer conception of the problem. | broad, general | narrow | bold, grand | modern | traditional | popul","VERB + CONCEPTION have","PREP. in ~ His work is strikingly fresh in conception.","PHRASES have no conception of sth You have no conception of what her life is like. 2 becoming/making sb pregnant","VERB + CONCEPTION prevent","PREP. at ~ Sex identity is fixed at conception.","PHRASES the moment of conception"]},"media":{"uk":"media/ldoce/hwd/bre/8/conception0205.mp3","us":"media/ldoce/hwd/ame/d/conception.mp3"},"examples":[{"en":"The plan was brilliant in its conception but failed because of lack of money.","cn":"尽管这计划构想绝妙，但终因资金不足而告流产。"},{"en":"He has no conception of how difficult life is if you're unemployed.","cn":"他不懂得失业后生活会是怎样的艰难。"}],"oxford":{"phon":"kənˈsepʃn","pos":"noun","senses":[{"en":"an understanding or a belief of what something/somebody is or what something/somebody should be","cn":"理解（认为某事／某人怎样或应该怎样）","g":"[countable, uncountable]","ex":{"en":"Marx’s conception of social justice","cn":"马克思对社会公平概念的理解"}},{"en":"the process of forming an idea or a plan","cn":"构思；构想；设想","g":"[uncountable]","ex":{"en":"The plan was brilliant in its conception but failed because of lack of money.","cn":"尽管这计划构想绝妙，但终因资金不足而告流产。"}},{"en":"the process of an egg being fertilized inside a woman’s body so that she becomes pregnant","cn":"怀孕；受孕","g":"[uncountable, countable]","ex":{"en":"the moment of conception","cn":"受孕的一刻"}}]}},"conspicuous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"显眼的;引人注目的","en":"If someone or something is conspicuous, people can see or notice them very easily.","ex":{"en":"The most conspicuous way in which the old politics is changing is in the growing use of referendums","cn":"旧式政治最明显的变化在于其越来越多地进行全民公决。"}},{"pos":"PHRASE 短语","cn":"因缺席而引人注意的","en":"If you say that someone or something is conspicuous by their absence, you are drawing attention to the fact that they are not in a place or situation where you think they should be.","ex":{"en":"He played no part in the game and was conspicuous by his absence in the post-match celebrations.","cn":"比赛时他没有上场，并且由于没有参加赛后的庆祝活动而引起了大家的关注。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is obvious is very easy to notice or understand – used especially when you are surprised that other people cannot notice it","cn":""},{"en":"easy to notice that something is true, so that you feel sure about it and have no doubts","cn":""},{"en":"very easy to notice, especially because you can see, hear, smell, or feel something","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Keep your eye on the adjective conspicuous for something that stands out so much you notice it right away — like that zit in the center of your friend's forehead."}]},"collocations":{"phrases":["VERBS be, feel, seem | become | make sb Its colouring makes it highly conspicuous.","ADV. highly, very | rather, somewhat The new building was rather conspicuous. | horribly, uncomfortably The stain on her dress was horribly "]},"media":{"uk":"media/ldoce/hwd/bre/7/conspicuous0205.mp3","us":"media/ldoce/hwd/ame/e/conspicuous.mp3"},"examples":[{"en":"When it came to cleaning up afterwards, Anne was conspicuous by her absence.","cn":"后来到打扫时，本应在场的安妮却因为不在而引起了注意。"},{"en":"I felt very conspicuous in my new car.","cn":"坐在我的新车里，我感到十分惹人注目。"}],"oxford":{"phon":"kənˈspɪkjuəs","pos":"adjective","senses":[{"en":"easy to see or notice; likely to attract attention","cn":"易见的；明显的；惹人注意的","ex":{"en":"Mary's red hair always made her conspicuous at school.","cn":"玛丽的红头发在学校里总是很惹眼。"}}]}},"coincidence":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"巧合;巧事","en":"A coincidence is when two or more similar or related events occur at the same time by chance and without any planning.","ex":{"en":"Mr. Berry said the timing was a coincidence and that his decision was unrelated to Mr. Roman's departure","cn":"贝里先生说这是时间上的巧合，他的决定与罗曼先生的离开没有关系。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if something happens by chance , it happens unexpectedly and seems to have no particular cause","cn":""},{"en":"if you do something by accident , you do it by chance and without intending to do it","cn":""},{"en":"if you happen to do something , you do it by chance and not because of any particular reason or plan","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"People love to talk about strange coincidences ––like you and your mother having the same birthday, or two unrelated families named \"The Martins\" living next door to each other. A coincidence is something that's not planned or arranged but seems like it is."}]},"collocations":{"phrases":["ADJ. complete, pure, sheer It was pure coincidence that they were both in Paris on the same day. | mere | happy What a happy coincidence to ","QUANT. series, set, string They met through a series of strange coincidences.","COINCIDENCE + VERB happen Remarkable coincidences do happen in real life.","PREP. by (a) ~ By coincidence, we both went to the same school. By an unfortunate coincidence, their house was burgled on the day he lost hi"]},"media":{"uk":"media/ldoce/hwd/bre/0/coincidence0205.mp3","us":"media/ldoce/hwd/ame/a/coincidence.mp3"},"examples":[{"en":"By (sheer) coincidence, I met the person we'd been discussing the next day.","cn":"真是巧了，我在第二天就遇见了我们一直在谈论的那个人。"},{"en":"It's not a coincidence that none of the directors are women (= it did not happen by chance).","cn":"没有一位董事是女性，这并非偶然。"}],"oxford":{"phon":"kəʊˈɪnsɪdəns","pos":"noun","senses":[{"en":"the fact of two things happening at the same time by chance, in a surprising way","cn":"（令人吃惊的）巧合，巧事","g":"[countable, uncountable]","ex":{"en":"a strange/an extraordinary/a remarkable coincidence","cn":"奇怪的／不寻常的／惊人的巧合"}},{"en":"the fact of things being present at the same time","cn":"同时存在；并存","g":"[singular]","lab":"formal","ex":{"en":"the coincidence of inflation and unemployment","cn":"通货膨胀与失业的并存"}},{"en":"the fact of two or more opinions, etc. being the same","cn":"（意见等的）相同，相符，一致","g":"[singular]","lab":"formal","ex":{"en":"a coincidence of interests between the two partners","cn":"两个合伙人之间利益的一致"}}]}},"constraint":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"限制;束缚;约束","en":"A constraint is something that limits or controls what you can do.","ex":{"en":"Their decision to abandon the trip was made because of financial constraints","cn":"他们决定放弃这次出游是因为财力有限。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"克制","en":"Constraint is control over the way you behave which prevents you from doing what you want to do."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the rules or facts that control someone's freedom or their ability to do what they want","cn":""},{"en":"limits on what someone or something is able to do","cn":""},{"en":"rules or laws that strictly control what you are allowed to do","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A constraint is a limit or restriction. Hopefully your school won't cut the sports or music programs due to budget constraints !"}]},"collocations":{"phrases":["ADJ. important, major | severe, tight The government has placed tight constraints on spending this year. | budget, financial","VERB + CONSTRAINT impose, place, put | remove","PREP. within a/the ~ We have to work within severe constraints. | without ~ I felt free to speak to her without constraint. | ~ on/upon Ther"]},"media":{"uk":"media/ldoce/hwd/bre/1/constraint0205.mp3","us":"media/ldoce/hwd/ame/0/constraint.mp3"},"examples":[{"en":"This decision will impose serious constraints on all schools.","cn":"这项决定将使所有的学校受到各种严格的限制。"},{"en":"At last we could relax and talk without constraint.","cn":"我们终于可以放松下来，无拘无束地谈话了。"}],"oxford":{"phon":"kənˈstreɪnt","pos":"noun","senses":[{"en":"a thing that limits something, or limits your freedom to do something","cn":"限制；限定；约束","g":"[countable]","ex":{"en":"constraints of time/money/space","cn":"时间／资金／空间的限制"}},{"en":"strict control over the way that you behave or are allowed to behave","cn":"约束；严管","g":"[uncountable]","ex":{"en":"At last we could relax and talk without constraint.","cn":"我们终于可以放松下来，无拘无束地谈话了。"}}]}},"condemnation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"谴责；指责","en":"Condemnation is the act of saying that something or someone is very bad and unacceptable.","ex":{"en":"There was widespread condemnation of Saturday's killings","cn":"周六的杀人事件受到普遍谴责。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an expression of very strong disapproval of someone or something, especially something you think is morally wrong","cn":"责难﹐谴责﹐责备"}]},"vocab":{"pos":"1 n 2 n 3 n 4 n","senses":[{"en":"Condemnation is the act of declaring something awful or evil. If your little brother does something unspeakably awful, express your condemnation so he will learn not to do it again."}]},"collocations":{"phrases":["ADJ. utter, wholesale | firm, severe, strong | universal, widespread | official, public There's been no official condemnation of the bombing","VERB + CONDEMNATION express, issue I can only express my strong condemnation of this dreadful behaviour. The United Nations issued a condemn","CONDEMNATION + VERB come from sb/sth Condemnation of this policy has come from all political parties."]},"media":{"uk":"media/ldoce/hwd/bre/0/condemnation0205.mp3","us":"media/ldoce/hwd/ame/0/condemnation.mp3"},"examples":[{"en":"There was widespread condemnation of the invasion.","cn":"那次侵略遭到了人们普遍的谴责。"},{"en":"There was widespread international condemnation of the bombing.","cn":"这次爆炸受到了国际社会的广泛谴责。"}],"oxford":{"phon":"ˌkɒndemˈneɪʃn","pos":"noun","senses":[{"en":"an expression of very strong disapproval","cn":"谴责；指责","ex":{"en":"There was widespread condemnation of the invasion.","cn":"那次侵略遭到了人们普遍的谴责。"}}]}},"correspond":{"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"相类似;相关;相对应","en":"If one thing corresponds to another, there is a close similarity or connection between them. You can also say that two things correspond .","ex":{"en":"Racegoers will be given a number which will correspond to a horse running in a race","cn":"观看赛马比赛的观众将获得一个与某一匹赛马相对应的号码。"}},{"pos":"V-RECIP 相互动词","cn":"(与…)通信","en":"If you correspond with someone, you write letters to them. You can also say that two people correspond .","ex":{"en":"She still corresponds with American friends she met in Majorca nine years ago","cn":"她仍与9年前在马略卡岛结识的美国朋友们通信。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if facts or situations correspond , they are the same as each other or have the same effect","cn":""},{"en":"if something that is said, written, or done is consistent with a particular idea or piece of information, it says the same thing or follows the same principles","cn":""},{"en":"if two pieces of information agree with each other, they are the same, and so they are both likely to be correct","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"When you correspond with someone, you send messages back and forth. Hand-written letters, email, even text messages are ways to correspond ."}]},"collocations":{"phrases":["ADV. closely | directly, exactly, precisely | approximately, broadly, roughly","PREP. to Their nursery schools correspond roughly to our infant schools. | with The movement of the dot on the screen corresponds exactly wi","ADV. regularly","PREP. with She corresponded regularly with her former music teacher."]},"media":{"uk":"media/ldoce/hwd/bre/e/correspond0205.mp3","us":"media/ldoce/hwd/ame/d/correspond.mp3"},"examples":[{"en":"The British job of Lecturer corresponds roughly to the US Associate Professor.","cn":"英国的讲师职位大致相当于美国的副教授。"},{"en":"Your account of events does not correspond with hers.","cn":"你对事情的陈述与她说的不相符。"}],"oxford":{"phon":"ˌkɒrəˈspɒnd","pos":"verb","senses":[{"en":"to be the same as or match something","cn":"相一致；符合","g":"[intransitive]","ex":{"en":"Your account and hers do not correspond.","cn":"你说的情况与她说的不相符。"}},{"en":"to be similar to or the same as something else","cn":"类似于；相当于","g":"[intransitive]","ex":{"en":"The British job of Lecturer corresponds roughly to the US Associate Professor.","cn":"英国的讲师职位大致相当于美国的副教授。"}},{"en":"to write letters or emails, etc. to somebody and receive letters or emails, etc. from them","cn":"通信；（通过电子邮件等）联系","g":"[intransitive]","lab":"formal","ex":{"en":"She corresponded regularly with her former teacher.","cn":"她和她以前的老师定期通信。"}}]}},"counsellor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指针对私人问题提供咨询的)顾问，辅导顾问","en":"A counsellor is a person whose job is to give advice to people who need it, especially advice on their personal problems.","ex":{"en":"Children who have suffered like this should see a counsellor experienced in bereavement","cn":"经受了这种苦难的孩子应该去咨询在排遣丧亲之痛方面有着丰富经验的辅导人员。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to give advice, especially in business, law, or politics","cn":""},{"en":"someone who gives special technical advice to companies or other organizations","cn":""},{"en":"someone who gives professional advice and emotional support to people, especially about personal problems","cn":""}]},"collocations":{"phrases":["ADJ. accredited, professional, trained | career, debt, marriage guidance, student","VERB + COUNSELLOR see, talk to He talked to a counsellor about his marriage difficulties. • Note at JOB"]},"media":{"uk":"media/ldoce/hwd/bre/8/councillor0205.mp3","us":"media/ldoce/hwd/ame/f/councilor.mp3"},"examples":[{"en":"a marriage guidance counsellor","cn":"婚姻指导顾问"},{"en":"Are you seeing a counsellor?","cn":"你是不是在看心理辅导员？"}],"oxford":{"phon":"ˈkaʊnsələ(r)","pos":"noun","senses":[{"en":"a person who has been trained to advise people with problems, especially personal problems","cn":"（尤指针对私人问题的）顾问；辅导顾问","ex":{"en":"I went to see a debt counsellor and she agreed to come to the bank with me.","cn":"我去找了一位债务顾问，她同意和我一起去银行。"}},{"en":"a lawyer","cn":"律师","lab":"North American English, Irish English，，"},{"en":"a person who is in charge of young people at a summer camp","cn":"夏令营负责人","lab":"North American English"}]}},"cough":{"collins":{"senses":[{"pos":"VERB 动词","cn":"咳嗽","en":"When you cough, you force air out of your throat with a sudden, harsh noise. You often cough when you are ill, or when you are nervous or want to attract someone's attention.","ex":{"en":"Graham began to cough violently","cn":"格雷厄姆开始剧烈咳嗽。"}},{"pos":"N-COUNT 可数名词","cn":"咳嗽(病)","en":"A cough is an illness in which you cough often and your chest or throat hurts.","ex":{"en":"...if you have a persistent cough for over a month.","cn":"如果你持续咳嗽一个月以上"}},{"pos":"VERB 动词","cn":"咯出(血等)","en":"If you cough blood or mucus, it comes up out of your throat or mouth when you cough.","ex":{"en":"I started coughing blood so they transferred me to a hospital.","cn":"我开始咯血，于是他们把我转到了医院。"}},{"pos":"VERB 动词","cn":"(发动机等)突然发出刺耳的噪声","en":"If an engine or other machine coughs, it makes a sudden, harsh noise.","ex":{"en":"Then suddenly, the engine coughed, spluttered and died.","cn":"接着，发动机突然咔咔地响了几声，然后就熄火了。"}},{"pos":"","cn":"","en":"相关词组：cough up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to give money in exchange for goods or services","cn":""},{"en":"if a company or organization meets the cost of something, it pays for it for someone else, especially when they do not have a legal duty to do this","cn":""},{"en":"to pay for something for someone else, especially when you do not want to or do not think that you should","cn":""}]},"collocations":{"phrases":["ADV. a bit, a little, slightly | apologetically, discreetly, nervously, politely | loudly, violently | up He vomited and began coughing up b","PHRASES cough and splutter The whisky made her cough and splutter. | a coughing fit He had a coughing fit and couldn't speak for a few momen"]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdecough.mp3","us":"media/ldoce/hwd/ame/a/cough1.mp3"},"examples":[{"en":"My cold's better, but I can't seem to shake off this cough.","cn":"我感冒好些了，但这咳嗽好像老也不好。"},{"en":"Steve finally coughed up the money he owed us.","cn":"史蒂夫最终勉强归还了他欠我们的钱。"}],"oxford":{"phon":"kɒf","pos":"verb","senses":[{"en":"to force out air suddenly and noisily through your throat, for example when you have a cold","cn":"咳嗽","g":"[intransitive]","ex":{"en":"I couldn't stop coughing.","cn":"我咳嗽不止。"}},{"en":"to force something out of your throat or lungs by coughing","cn":"（从喉咙或肺中）咳出","g":"[transitive]","ex":{"en":"Sometimes she coughed (up) blood.","cn":"她有时咯血。"}},{"en":"to make a sudden noise, especially as a sign that the engine is not working correctly","cn":"突然发出刺耳的声音（尤指故障的征兆）","g":"[intransitive]","ex":{"en":"The old engine coughed and spluttered into life.","cn":"旧发动机嘎吱作响，发动起来。"}},{"en":"an act or a sound of coughing (= forcing out air suddenly and noisily through your throat, for example when you have a cold)","cn":"咳嗽；咳嗽声","ex":{"en":"She gave a little cough to attract my attention.","cn":"她轻轻地咳了一声以引起我的注意。"},"pos":"noun"},{"en":"an illness or infection that makes you cough often","cn":"咳嗽病","ex":{"en":"to have a dry/persistent cough","cn":"干咳；顽固的咳嗽"},"pos":"noun"}]}},"contender":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"竞争者;争夺者","en":"A contender is someone who takes part in a competition.","ex":{"en":"Her trainer said yesterday that she would be a strong contender for a place in Britain's Olympic squad","cn":"她的教练昨天说，她将是英国奥运代表队席位的有力争夺者。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone or something that is in competition with other people or things","cn":"竞争者﹐角逐者﹐争夺者"},{"en":"contender for a contender for the title","cn":"争夺冠军者 serious/strong/leading etc contender Her album is a strong contender for the Album of the Year award. 她的专辑是年度专辑奖的有"}]},"vocab":{"pos":"n","senses":[{"en":"Baseball players, boxers, politicians: each is a contender in that they compete or campaign to win something."}]},"collocations":{"phrases":["ADJ. serious, strong | leading, main, major, number one, obvious, top | genuine, likely, possible","PREP. ~ for a strong contender for the gold medal"]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdecontender.mp3","us":"media/ldoce/hwd/ame/3/contender.mp3"},"examples":[{"en":"a leading/serious/strong contender for the party leadership","cn":"该党领导权最重要的/强劲的/有实力的角逐者"},{"en":"a contender for a gold medal in the Olympics","cn":"奥运金牌的争夺者"}],"oxford":{"phon":"kənˈtendə(r)","pos":"noun","senses":[{"en":"a person or team with a chance of winning a competition","cn":"竞争者；角逐者；争夺者","ex":{"en":"a contender for a gold medal in the Olympics","cn":"奥运金牌的争夺者"}}]}},"concentration":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"全神贯注;专心;专注","en":"Concentration on something involves giving all your attention to it.","ex":{"en":"Neal kept interrupting, breaking my concentration","cn":"尼尔不停地打断我，使得我无法集中注意力。"}},{"pos":"N-VAR 可变名词","cn":"集中;汇集","en":"A concentration of something is a large amount of it or large numbers of it in a small area.","ex":{"en":"The area has one of the world's greatest concentrations of wildlife","cn":"这个地区是世界上野生动物最为密集的区域之一。"}},{"pos":"N-VAR 可变名词","cn":"浓度","en":"The concentration of a substance is the proportion of essential ingredients or substances in it.","ex":{"en":"pH is a measure of the concentration of free hydrogen atoms in a solution","cn":"pH值是测试溶液中自由氢原子浓度的单位。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to listen to and watch carefully what you are doing, what is happening, or what someone is saying","cn":""},{"en":"to think very carefully about something that you are doing, without being interrupted","cn":""},{"en":"your ability to think carefully about what you are doing without being interrupted","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"If you have great powers of concentration , that means you're able to focus all your attention on the matter at hand. Concentration can also refer to something that's clustered together or to the density or strength of a solution."}]},"collocations":{"phrases":["ADJ. deep, great, intense | total a look of total concentration on her face | poor | exclusive","VERB + CONCENTRATION demand, require The game requires great concentration. | lose | break, disturb Don's voice from outside broke my concen","CONCENTRATION + NOUN span","PREP. ~ on his concentration on his writing","PHRASES a lack of concentration, a lapse in/of concentration One momentary lapse in concentration could prove fatal. | powers of concentrati","ADJ. great, heavy, high, large The greatest concentration of traffic is in the city centre. | low | geographical","CONCENTRATION + VERB increase, rise The concentration of nitrates in the drinking water has risen in recent years. | decrease, fall"]},"media":{"uk":"media/ldoce/hwd/bre/1/concentration0205.mp3","us":"media/ldoce/hwd/ame/2/concentration.mp3"},"examples":[{"en":"This book requires a great deal of concentration.","cn":"这本书需要全神贯注才能读懂。"},{"en":"a need for greater concentration on environmental issues","cn":"更加关注环境问题的必要性"}],"oxford":{"phon":"ˌkɒnsnˈtreɪʃn","pos":"noun","senses":[{"en":"the ability to direct all your effort and attention on one thing, without thinking of other things","cn":"专心；专注","g":"[uncountable]","ex":{"en":"This book requires a great deal of concentration.","cn":"这本书需要全神贯注才能读懂。"}},{"en":"the process of people directing effort and attention on a particular thing","cn":"关注；重视","g":"[uncountable]","ex":{"en":"He stressed the need for greater concentration on environmental issues.","cn":"他强调需要更加关注环境问题。"}},{"en":"a lot of something in one place","cn":"集中；聚集","g":"[countable]","ex":{"en":"a concentration of industry in the north of the country","cn":"该国北部的产业集中"}},{"en":"the amount of a substance in a liquid or in another substance","cn":"浓度；含量","g":"[countable, uncountable]","ex":{"en":"glucose concentrations in the blood","cn":"血液中的葡萄糖含量"}}]}},"convict":{"collins":{"senses":[{"pos":"VERB 动词","cn":"给…定罪;宣判…有罪","en":"If someone is convicted of a crime, they are found guilty of that crime in a law court.","ex":{"en":"In 1977 he was convicted of murder and sentenced to life imprisonment","cn":"1977年，他被判谋杀罪名成立，判处终身监禁。"}},{"pos":"N-COUNT 可数名词","cn":"已决犯;囚犯","en":"A convict is someone who is in prison."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to prove that someone is guilty of a crime","cn":""},{"en":"if a court of law finds someone guilty or convicts them, they decide that that person is guilty of a crime","cn":""},{"en":"to prove or officially announce that someone is guilty of a crime after a trial in a law court","cn":"证明[判定]…有罪"}]},"vocab":{"pos":"v n","senses":[{"en":"A convict is a person who has been found guilty — convicted — of a crime and is serving a sentence in prison."}]},"collocations":{"phrases":["ADJ. escaped"]},"media":{"uk":"media/ldoce/hwd/bre/f/convict_v0205.mp3","us":"media/ldoce/hwd/ame/0/l3convict.mp3"},"examples":[{"en":"He was convicted of fraud.","cn":"他被判犯有诈骗罪。"},{"en":"a convicted murderer","cn":"已定罪的谋杀犯"}],"oxford":{"phon":"kənˈvɪkt","pos":"verb","senses":[{"en":"to decide and state officially in court that somebody is guilty of a crime","cn":"定罪；宣判…有罪","lab":"especially North American English","ex":{"en":"He was convicted of fraud.","cn":"他被判犯有诈骗罪。"}},{"en":"a person who has been found guilty of a crime and sent to prison","cn":"已决犯；服刑囚犯","ex":{"en":"The novel begins with Pip’s meeting with an escaped convict from the prison ship.","cn":"这本小说以皮普与从囚犯船上逃出来的一个囚犯见面开始。"},"pos":"noun"}]}},"congratulations":{"collins":{"senses":[{"pos":"CONVENTION 惯用语","cn":"恭喜;祝贺","en":"You say 'Congratulations' to someone in order to congratulate them on something nice that has happened to them or something good that they have done.","ex":{"en":"Congratulations, you have a healthy baby boy","cn":"恭喜，你生了个健康的男孩。"}},{"pos":"N-PLURAL 复数名词","cn":"祝贺的话语;贺词","en":"If you offer someone your congratulations, you congratulate them on something nice that has happened to them or on something good that they have done.","ex":{"en":"The club also offers its congratulations to D. Brown on his appointment as president.","cn":"俱乐部也对D.布朗被任命为主席表示祝贺。"}}]},"vocab":{"pos":"n","senses":[{"en":"\"Kudos,\" \"well-done,\" and other words of praise are forms of congratulations , or an expression of approval and acclaim."}]},"collocations":{"phrases":["ADJ. deepest | heartfelt, hearty, sincere, warm May I offer my heartiest congratulations on your promotion?","VERB + CONGRATULATIONS express, extend, give (sb), offer (sb), send (sb) Please give your parents my congratulations. | accept","PREP. ~ on/upon Please accept my warmest congratulations on your engagement. | ~ to Congratulations to Tony on his new job!"]}},"contagious":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（病）接触传染的","en":"A disease that is contagious can be caught by touching people or things that are infected with it.","ex":{"en":"...a highly contagious disease of the lungs.","cn":"极具传染性的肺病"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(感情、态度等)感染性的，会迅速蔓延开的","en":"A feeling or attitude that is contagious spreads quickly among a group of people.","ex":{"en":"Laughing is contagious","cn":"笑是有感染力的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a disease spreads or is spread , it is passed from one person to another, and it affects more and more people","cn":""},{"en":"if an illness goes around , it spreads from one person to another, especially in a school, office etc","cn":""},{"en":"an infectious disease is spread by being passed from one person to another","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"You should probably postpone dinner if your date's cold is contagious — that means it's easily spread and likely to get you sick."}]},"collocations":{"phrases":["VERBS be, prove The new disease proved contagious.","ADV. highly, very Enthusiasm is highly contagious."]},"media":{"uk":"media/ldoce/hwd/bre/b/contagious0205.mp3","us":"media/ldoce/hwd/ame/e/contagious.mp3"},"examples":[{"en":"Scarlet fever is highly contagious.","cn":"猩红热的接触传染性很强。"},{"en":"( figurative ) His enthusiasm was contagious (= spread quickly to other people).","cn":"他的热情富有感染力。"}],"oxford":{"phon":"kənˈteɪdʒəs","pos":"adjective","senses":[{"en":"a contagious disease spreads by close contact between people","cn":"（疾病）接触传染的","lab":"figurative","ex":{"en":"Scarlet fever is highly contagious.","cn":"猩红热的接触传染性很强。"}},{"en":"if a person is contagious, they have a disease that can be spread by close contact with other people","cn":"患接触性传染病","g":"[not usually before noun]"}]}},"compensation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"补偿(或赔偿)金","en":"Compensation is money that someone who has experienced loss or suffering claims from the person or organization responsible, or from the state.","ex":{"en":"He received one year's salary as compensation for loss of office","cn":"他得到一年的工资作为失业补偿金。"}},{"pos":"N-VAR 可变名词","cn":"(对不利事情的)补偿","en":"If something is some compensation for something bad that has happened, it makes you feel better.","ex":{"en":"Helen gained some compensation for her earlier defeat by winning the final open class","cn":"海伦在公开组决赛中取胜，这对她早先的失败算是一种补偿。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"money that a law court orders someone to pay to you because they have caused you harm","cn":""},{"en":"money that someone pays you because they have caused you harm, loss, or damage to your property","cn":""},{"en":"money paid to someone because they have suffered injury or loss, or because something they own has been damaged","cn":"补偿费﹐赔偿金"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Compensation means \"making up for a something.\" When a restaurant offers you a free dessert as compensation for messing up your dinner order, the hope is you will leave happy and come back again."}]},"collocations":{"phrases":["ADJ. full | partial, small | adequate, appropriate, sufficient | financial, monetary","QUANT. amount","VERB + COMPENSATION award (sb), give (sb), grant (sb), offer (sb), pay (sb), provide (sb with) | accept, gain, get, obtain, receive She got ","COMPENSATION + VERB be payable If the government is proved negligent, compensation will be payable.","COMPENSATION + NOUN claim | fund | order | payment | scheme","PREP. as ~ (for) She received &pound; 7,000 as compensation for her injuries. | in ~ (for) They will have to pay &pound; 5,000 in compensati","PHRASES compensation in money"]},"media":{"uk":"media/ldoce/hwd/bre/7/compensation0205.mp3","us":"media/ldoce/hwd/ame/3/compensation.mp3"},"examples":[{"en":"I wish I were young again, but getting older has its compensations.","cn":"我要是能再次年轻就好了，但上了年纪也有上了年纪的好处。"},{"en":"to receive £10 000 in compensation.","cn":"得到赔偿金 1 万英镑"}],"oxford":{"phon":"ˌkɒmpenˈseɪʃn","pos":"noun","senses":[{"en":"something, especially money, that somebody gives you because they have hurt you, or damaged something that you own; the act of giving this to somebody","cn":"补偿（或赔偿）物；（尤指）赔偿金，补偿金；赔偿","g":"[uncountable, countable]","ex":{"en":"to claim/award/receive compensation","cn":"要求／判给／得到赔偿金"}},{"en":"money that an employee receives for doing their job","cn":"酬金；薪金","g":"[uncountable]","lab":"especially North American English","ex":{"en":"Send your CV and current compensation to Executive Search Consultant.","cn":"把你的简历和目前的薪酬发给猎头顾问。"}},{"en":"a thing or things that make a bad situation better","cn":"使坏的情况变好的事物；（对不利局面的）补偿","g":"[countable, usually plural, uncountable]","ex":{"en":"I wish I were young again, but getting older has its compensations.","cn":"我要是能再次年轻就好了，但上了年纪也有上了年纪的好处。"}}]}},"contraceptive":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"避孕的;节育的","en":"A contraceptive method or device is a method or a device which a woman uses to prevent herself from becoming pregnant.","ex":{"en":"...a demand for a greater choice of effective contraceptive methods","cn":"对于更为多样的有效避孕方法的需求"}},{"pos":"N-COUNT 可数名词","cn":"避孕用具;避孕药物","en":"A contraceptive is a device or drug that prevents a woman from becoming pregnant.","ex":{"en":"...oral contraceptives","cn":"口服避孕药"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a drug, object, or method used to prevent a woman from becoming pregnant when she has sex","cn":"避孕药物[用具﹐方法]"}]},"collocations":{"phrases":["ADJ. effective | oral","VERB + CONTRACEPTIVE use"]},"media":{"uk":"media/ldoce/hwd/bre/f/contraceptive_las3_br.mp3","us":"media/ldoce/hwd/ame/9/contraceptive.mp3"},"examples":[{"en":"contraceptive advice/precautions/methods","cn":"避孕咨询/措施/方法"},{"en":"oral contraceptives","cn":"口服避孕药"}],"oxford":{"phon":"ˌkɒntrəˈseptɪv","pos":"adjective","senses":[{"en":"used to prevent a woman from becoming pregnant","cn":"避孕药；避孕用具；避孕措施","ex":{"en":"a contraceptive pill","cn":"避孕药"}},{"en":"a drug, device or practice used to avoid becoming pregnant when having sex","cn":"避孕药；避孕用具；避孕措施","ex":{"en":"oral contraceptives","cn":"口服避孕药"},"pos":"noun"}]}},"compassionate":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有同情心的;表示同情的","en":"If you describe someone or something as compassionate, you mean that they feel or show pity, sympathy, and understanding for people who are suffering.","ex":{"en":"My father was a deeply compassionate man","cn":"我父亲是一个非常富有同情心的人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"kind to someone who is having problems","cn":""},{"en":"wanting to help people who are suffering or having problems","cn":""},{"en":"not getting angry with someone or criticizing them, because you can see that they have problems","cn":""}]},"vocab":{"pos":"adj v","senses":[{"en":"If you are compassionate , you feel other people's pain and struggles as though they were your own. Compassionate people are often moved to work to end the suffering of others, perhaps by feeding the hungry or educating the poor."}]},"collocations":{"phrases":["VERBS be, feel, sound","ADV. deeply, very a deeply compassionate man"]},"media":{"uk":"media/ldoce/hwd/bre/2/compassionate0205.mp3","us":"media/ldoce/hwd/ame/a/compassionate.mp3"},"examples":[{"en":"He was allowed to go home on compassionate grounds (= because he was suffering).","cn":"他因为得到同情而获准回家。"},{"en":"I allowed him to go home on compassionate grounds .","cn":"我出于同情让他回家了。"}],"oxford":{"phon":"kəmˈpæʃənət","pos":"adjective","senses":[{"en":"feeling or showing sympathy for people or animals who are suffering","cn":"有同情心的；表示怜悯的；有爱心的","ex":{"en":"Politicians are not usually regarded as warm or compassionate people.","cn":"政客通常不被视为热情或富有同情心的人。"}}]}},"coincide":{"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"巧合;同时发生","en":"If one event coincides with another, they happen at the same time.","ex":{"en":"The exhibition coincides with the 50th anniversary of his death","cn":"展览恰好在他逝世50周年之际举行。"}},{"pos":"V-RECIP 相互动词","cn":"(想法、利益等)一致，相符","en":"If the ideas or interests of two or more people coincide, they are the same.","ex":{"en":"The kids' views on life don't always coincide, but they're not afraid of voicing their opinions","cn":"孩子们的人生观并不总是一致，但他们敢于表达自己的观点。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if facts or situations correspond , they are the same as each other or have the same effect","cn":""},{"en":"if something that is said, written, or done is consistent with a particular idea or piece of information, it says the same thing or follows the same principles","cn":""},{"en":"if two pieces of information agree with each other, they are the same, and so they are both likely to be correct","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When things happen at the same time, they are said to coincide . Often, this is because they're intentionally coordinated––\"the bake sale coincided with Parent Day\"––but not always."}]},"collocations":{"phrases":["ADV. exactly Her visit coincided exactly with a visit by the American president. | roughly","VERB + COINCIDE be planned to, be timed to","PREP. with The singer's arrival was timed to coincide with the opening of the festival. 2 be the same","ADV. closely | exactly","PREP. with Our views on this issue coincide closely with yours."]},"media":{"uk":"media/ldoce/hwd/bre/b/coincide0205.mp3","us":"media/ldoce/hwd/ame/a/coincide.mp3"},"examples":[{"en":"The strike was timed to coincide with the party conference.","cn":"那次罢工选择在召开政党大会的同一时间举行。"},{"en":"The present position of the house coincides with that of an earlier dwelling.","cn":"这栋房子现在的位置恰与原住宅的位置一致。"}],"oxford":{"phon":"ˌkəʊɪnˈsaɪd","pos":"verb","senses":[{"en":"to take place at the same time","cn":"同时发生","g":"[intransitive]","ex":{"en":"It's a pity our trips to New York don't coincide.","cn":"真遗憾我们的纽约之行不在同一时间。"}},{"en":"to be the same or very similar","cn":"相同；相符；极为类似","g":"[intransitive]","lab":"formal","ex":{"en":"The interests of employers and employees do not always coincide.","cn":"雇主和雇员的利益并不总是一致的。"}},{"en":"to meet; to share the same space","cn":"相接；相交；位置重合；重叠","g":"[intransitive]","lab":"formal","ex":{"en":"At this point the two paths coincide briefly.","cn":"两条小路在这个地方有一小段合在了一起。"}}]}},"controversy":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"争论;争议;辩论","en":"Controversy is a lot of discussion and argument about something, often involving strong feelings of anger or disapproval.","ex":{"en":"The proposed cuts have caused considerable controversy.","cn":"削减开支的提议引起了诸多争议。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when people disagree with each other","cn":""},{"en":"when people are unable to agree, especially about something important - use this as a way of avoiding more direct words like 'argument' and 'disagreement'","cn":""},{"en":"a serious disagreement about a decision, plan, or action, that causes arguments for a long time in newspapers, on television etc","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If a kid in your school is expelled for getting in trouble, but not on school property, a controversy is likely to ensue over whether that's fair. A controversy is a long discussion in which many people express opposing views."}]},"collocations":{"phrases":["ADJ. considerable, great, major | bitter, fierce, raging, violent | lively His views have excited a lively controversy among fellow scientis","VERB + CONTROVERSY arouse, cause, create, excite, fuel, give rise to, provoke, spark (off), stir up What they are doing is bound to stir up ","CONTROVERSY + VERB arise, break out A fierce controversy has broken out over the issue. | rage Controversy is raging over the route of the n","PREP. amid ~ The minister has resigned amid continuing controversy over his education proposals. | ~ about/concerning/over There has been a ","PHRASES a matter/source/subject of controversy, a storm of controversy The book raised a storm of controversy."]},"media":{"uk":"media/ldoce/hwd/bre/a/controversy0205.mp3","us":"media/ldoce/hwd/ame/a/controversy.mp3"},"examples":[{"en":"a bitter controversy over/about the site of the new airport","cn":"有关新机场选址的激烈争论"},{"en":"the controversy surrounding his latest movie","cn":"围绕他最近一部电影的争论"}],"oxford":{"phon":"ˈkɒntrəvɜːsi","pos":"noun","senses":[{"en":"public discussion and argument about something that many people strongly disagree about, think is bad, or are shocked by","cn":"（公开的）争论，争议，论战","ex":{"en":"to arouse/cause controversy","cn":"引起争论"}}]}},"compose":{"collins":{"senses":[{"pos":"VERB 动词","cn":"组成;构成","en":"The things that something is composed of are its parts or members. The separate things that compose something are the parts or members that form it.","ex":{"en":"The force would be composed of troops from NATO countries","cn":"这支军队将由来自北约国家的部队组成。"}},{"pos":"VERB 动词","cn":"谱写(乐曲);作(曲)","en":"When someone composes a piece of music, they write it.","ex":{"en":"Vivaldi composed a large number of very fine concertos","cn":"维瓦尔第创作了很多非常优美的协奏曲。"}},{"pos":"VERB 动词","cn":"创作，写(信、诗或演讲稿)","en":"If you compose something such as a letter, poem, or speech, you write it, often using a lot of concentration or skill.","ex":{"en":"He started at once to compose a reply to Anna","cn":"他马上开始给安娜写回信。"}},{"pos":"VERB 动词","cn":"为（照片、图像）构图","en":"If you compose a picture or image, you arrange it in an attractive and artistic way.","ex":{"en":"Anthony dismounted with his camera and walked away from the walls to compose a shot","cn":"安东尼拿着照相机下了车，走向离城墙更远的地方，为拍摄构图。"}},{"pos":"VERB 动词","cn":"使（自己）平静(或镇定);使（表情）镇静下来","en":"If you compose yourself or if you compose your features, you succeed in becoming calm after you have been angry, excited, or upset.","ex":{"en":"She quickly composed herself as the car started off","cn":"车一上路，她就很快让自己平静了下来。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to become calm again after you have been angry or upset","cn":""},{"en":"to calm down after you have been very angry","cn":""},{"en":"to deliberately make yourself look and feel calm after you have been upset","cn":""}]},"vocab":{"pos":"1 v 2 v 3 v","senses":[{"en":"To compose is to put something together, like a song, poem, or even yourself. You might want to compose yourself before returning to the party after a good cry."}]},"collocations":{"phrases":["ADV. specially music specially composed for the occasion"]},"media":{"uk":"media/ldoce/hwd/bre/d/compose0205.mp3","us":"media/ldoce/hwd/ame/5/compose.mp3"},"examples":[{"en":"Mozart composed his last opera shortly before he died.","cn":"莫扎特在创作出他最后一部歌剧后不久便去世了。"},{"en":"Emma frowned, making an effort to compose herself.","cn":"埃玛皱起了眉头，努力使自己镇定下来。"}],"oxford":{"phon":"kəmˈpəʊz","pos":"verb","senses":[{"en":"to write music","cn":"作曲；创作（音乐）","g":"[transitive, intransitive]","ex":{"en":"Mozart composed his last opera shortly before he died.","cn":"莫扎特在创作出他最后一部歌剧后不久便去世了。"}},{"en":"to write a letter, etc. usually with a lot of care and thought","cn":"撰写（信函、讲稿、诗歌等）","g":"[transitive]","ex":{"en":"She composed a letter of protest.","cn":"她写了一封抗议信。"}},{"en":"to combine together to form a whole","cn":"组成，构成（一个整体）","g":"[transitive]","lab":"formal","ex":{"en":"Ten people compose the committee.","cn":"委员会由十人组成。"}},{"en":"to manage to control your feelings or expression","cn":"使镇静；使平静","g":"[transitive, no passive]","lab":"formal","ex":{"en":"Emma frowned, making an effort to compose herself.","cn":"埃玛皱起了眉头，努力使自己镇定下来。"}}]}},"concerto":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"协奏曲","en":"A concerto is a piece of music written for one or more solo instruments and an orchestra.","ex":{"en":"...Tchaikovsky's First Piano Concerto.","cn":"柴可夫斯基的《第一钢琴协奏曲》"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of classical music, usually for one instrument and an orchestra","cn":"协奏曲"}]},"collocations":{"phrases":["ADJ. piano, violin, etc. | D major, B minor, etc.","VERB + CONCERTO compose, write | perform, play | conduct | record","PREP. ~ for a concerto for clarinet and orchestra •"]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdeconcerto.mp3","us":"media/ldoce/hwd/ame/9/concerto.mp3"},"examples":[{"en":"a concerto for flute and harp","cn":"长笛与竖琴协奏曲"},{"en":"a piano concerto","cn":"钢琴协奏曲"}],"oxford":{"phon":"kənˈtʃeətəʊ","pos":"noun","senses":[{"en":"a piece of music for one or more solo instruments playing with an orchestra","cn":"协奏曲","ex":{"en":"a piano concerto","cn":"钢琴协奏曲"}}]}},"comeback":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(娱乐圈、体育明星等的)复出，东山再起","en":"If someone such as an entertainer or sports personality makes a comeback, they return to their profession or sport after a period away.","ex":{"en":"Sixties singing star Petula Clark is making a comeback.","cn":"60年代的歌星佩杜拉·克拉克复出了。"}},{"pos":"N-COUNT 可数名词","cn":"再度流行","en":"If something makes a comeback, it becomes fashionable again.","ex":{"en":"Tight fitting T-shirts are making a comeback.","cn":"紧身T恤再度流行起来。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"因受到伤害而追究他人的责任","en":"If you have no comeback when someone has done something wrong to you, there is nothing you can do to have them punished or held responsible."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something you say when someone asks you a question or speaks to you","cn":""},{"en":"an answer – used especially in written English to report what someone said","cn":""},{"en":"an answer that clearly shows your reaction to a question, suggestion etc","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A comeback is a quick, witty reply. “Your mama” is a lame comeback but a popular one. It's also a return to prominence after a break, like an athlete who retires and then makes a comeback by returning to the sport."}]},"collocations":{"phrases":["ADJ. big, dramatic, fighting, great, remarkable, successful | long-awaited | political","VERB + COMEBACK make, stage He made one of the most remarkable comebacks in modern politics. | attempt","COMEBACK + NOUN trail The player is on the comeback trail after a serious knee injury."]},"media":{"uk":"media/ldoce/hwd/bre/0/comeback0205.mp3","us":"media/ldoce/hwd/ame/4/comeback.mp3"},"examples":[{"en":"You agreed to the contract, so now you have no comeback.","cn":"你同意了这份合同，所以现在你不能追究他人的责任了。"},{"en":"an ageing pop star trying to stage a comeback","cn":"试图重返歌坛的已经上了年纪的流行音乐歌星"}],"oxford":{"phon":"ˈkʌmbæk","pos":"noun","senses":[{"en":"if a person in public life makes a comeback, they start doing something again that they had stopped doing, or they become popular again","cn":"复出；重返；再度受欢迎","g":"[usually singular]","ex":{"en":"an ageing pop star trying to stage a comeback","cn":"试图重返歌坛的已经上了年纪的流行音乐歌星"}},{"en":"if a thing makes a comeback, it becomes popular and fashionable or successful again","cn":"再度流行并变得时髦；再度获得成功"},{"en":"a quick reply to a critical remark","cn":"（对批评迅速作出的）反驳，回应","lab":"informal"},{"en":"a way of holding somebody responsible for something wrong that has been done to you","cn":"可因自身受到伤害而追究某人的责任","ex":{"en":"You agreed to the contract, so now you have no comeback.","cn":"你同意了这份合同，所以现在你不能追究他人的责任了。"}}]}},"conclusive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"确定的;毫无疑问的;不容置疑的","en":"Conclusive evidence shows that something is certainly true.","ex":{"en":"Her attorneys claim there is no conclusive evidence that any murders took place","cn":"她的律师声称并无确凿证据表明发生了谋杀。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something is definite , it is certain because someone has officially stated that it will happen, is true etc","cn":""},{"en":"proof etc that is certainly true and cannot be doubted","cn":""},{"en":"showing that something is definitely true","cn":"结论性的﹔令人确信的﹐毫无疑问的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you've got a theory that you're trying to prove, and you uncover a conclusive piece of evidence, then the case is closed. Conclusive means you've got your answer, you've proved your theory, and there can't be any doubt about it."}]},"collocations":{"phrases":["VERBS appear, be, seem","ADV. absolutely | fairly, pretty They produced some fairly conclusive evidence. | by no means, far from, hardly, not very The argument was f"]},"media":{"uk":"media/ldoce/hwd/bre/2/conclusive0205.mp3","us":"media/ldoce/hwd/ame/5/conclusive.mp3"},"examples":[{"en":"conclusive evidence/proof/results","cn":"确凿的证据；不容置疑的结果"},{"en":"to prove sth conclusively","cn":"确凿地证明某事"}],"oxford":{"phon":"kənˈkluːsɪv","pos":"adjective","senses":[{"en":"proving something in a way that is certain and allows no doubt","cn":"确凿的；不容置疑的","ex":{"en":"conclusive evidence/proof/results","cn":"确凿的证据；不容置疑的结果"}}]}},"complication":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"使复杂化的难题(或困难)","en":"A complication is a problem or difficulty that makes a situation harder to deal with.","ex":{"en":"The age difference was a complication to the relationship","cn":"年龄差异使得双方交往更加困难。"}},{"pos":"N-COUNT 可数名词","cn":"并发症","en":"A complication is a medical problem that occurs as a result of another illness or disease.","ex":{"en":"Blindness is a common complication of diabetes","cn":"失明是糖尿病常见的并发症。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a bad situation that must be dealt with, because it is causing harm or inconvenience, or it is stopping you from doing what you want to do","cn":""},{"en":"a problem that makes it more difficult to do something that you are trying to do","cn":""},{"en":"a problem or several problems that make something difficult, spoil your plans etc","cn":""}]},"collocations":{"phrases":["ADJ. major | added, additional, further | undue, unnecessary | political","VERB + COMPLICATION add, cause The presence of an armed gang added a major complication. | avoid We always try to avoid any unnecessary comp","COMPLICATION + VERB arise, occur Further complications arose when the newspapers published an interview with the prisoner's family. 2 medica","ADJ. acute, dangerous, serious, severe | chronic, long-term | minor | common | rare | local | potential | birth, diabetic, medical, post-ope","VERB + COMPLICATION develop, have, suffer She developed complications two weeks after the treatment. | die from/of | avoid, prevent","COMPLICATION + VERB develop, occur, arise Complications develop if the drug is not used properly. | result from sth","PHRASES a risk of complications The treatment carries a high risk of complications.","PREP. ~ with complications with her pregnancy."]},"media":{"uk":"media/ldoce/hwd/bre/7/complication0205.mp3","us":"media/ldoce/hwd/ame/7/complication.mp3"},"examples":[{"en":"The bad weather added a further complication to our journey.","cn":"恶劣的天气给我们的旅行增加了更多的困难。"},{"en":"She developed complications after the surgery.","cn":"她手术后出现了并发症。"}],"oxford":{"phon":"ˌkɒmplɪˈkeɪʃn","pos":"noun","senses":[{"en":"a thing that makes a situation more complicated or difficult","cn":"使更复杂化（或更困难）的事物","g":"[countable, uncountable]","ex":{"en":"The bad weather added a further complication to our journey.","cn":"恶劣的天气给我们的旅行增加了更多的困难。"}},{"en":"a new problem or illness that makes treatment of a previous one more complicated or difficult","cn":"并发症","g":"[countable, usually plural]","lab":"medical","ex":{"en":"She developed complications after the surgery.","cn":"她手术后出现了并发症。"}}]}},"contravene":{"collins":{"senses":[{"pos":"VERB 动词","cn":"违反，违背，触犯(法律或规则)","en":"To contravene a law or rule means to do something that is forbidden by the law or rule.","ex":{"en":"The Board has banned the film on the grounds that it contravenes criminal libel laws","cn":"委员会决定禁播这部电影，理由是它触犯了刑事诽谤法。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to not obey a person, order, rule, or law","cn":""},{"en":"to not obey a law or rule","cn":""},{"en":"to deliberately refuse to obey a rule or law, or what someone in authority tells you to do","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To contravene means to go against or defy. You might contravene your parents' ban on sweets when your friend offers to share her candy because chocolate tastes too good to resist!"}]},"collocations":{"phrases":["ADV. blatantly, clearly blatantly contravening the rules of civilized warfare"]},"media":{"uk":"media/ldoce/hwd/bre/5/contravene0205.mp3","us":"media/ldoce/hwd/ame/1/contravene.mp3"},"examples":[{"en":"The company was found guilty of contravening safety regulations.","cn":"那家公司被判违反了安全条例。"},{"en":"These actions are in contravention of European law.","cn":"这些行动违反了欧洲的法律。"}],"oxford":{"phon":"ˌkɒntrəˈviːn","pos":"verb","senses":[{"en":"to do something that is not allowed by a law or rule","cn":"违犯，违反（法律或规则）","ex":{"en":"The company was found guilty of contravening safety regulations.","cn":"那家公司被判违反了安全条例。"}}]}},"commentary":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(广播或电视上播出的)实况解说，现场报道","en":"A commentary is a description of an event that is broadcast on radio or television while the event is taking place.","ex":{"en":"He gave the listening crowd a running commentary","cn":"他给这一大群听众进行现场报道。"}},{"pos":"N-COUNT 可数名词","cn":"评论性文章(或著作)","en":"A commentary is an article or book which explains or discusses something.","ex":{"en":"Mr Rich will be writing a twice-weekly commentary on American society and culture.","cn":"里奇先生每周将就美国社会与文化发表两篇评论文章。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"讨论;评论","en":"Commentary is discussion or criticism of something.","ex":{"en":"The show mixed comedy with social commentary","cn":"这个节目把喜剧和社会评论结合了起来。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"what you say or write when you are describing a person, place, or thing","cn":""},{"en":"a description of a situation or event, based on a study of the facts, that provides people with information about it and also tries to explain it","cn":""},{"en":"a written or spoken description of something that happened","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When the language in a work of literature such as \"Beowulf\" is difficult to understand, it is helpful to read from an edition that includes a commentary — an explanation or expansion or criticism added to the original material."}]},"collocations":{"phrases":["ADJ. brief | live | running (= continuous) She kept up a running commentary on the festivities. | radio, television listening to the radio c","VERB + COMMENTARY give, keep up, provide | listen to","COMMENTARY + NOUN box the reporters in the commentary box","PREP. ~ on BBC1 will give a live commentary on the election results. 2 criticism/discussion of sth","ADJ. detailed | critical | political, social","VERB + COMMENTARY provide The novel provides a powerful social commentary on post-war Germany.","PREP. ~ on","PHRASES be a sad commentary (on sth) (= to reflect badly on sth) The petty quarrels were a sad commentary on the state of the government."]},"media":{"uk":"media/ldoce/hwd/bre/d/commentary0205.mp3","us":"media/ldoce/hwd/ame/0/commentary.mp3"},"examples":[{"en":"Our reporters will give a running commentary (= a continuous one) on the election results as they are announced.","cn":"我们的记者将对选举的公布结果作实况追踪报道。"},{"en":"The petty quarrels were a sad commentary on the state of the government.","cn":"这些鸡毛蒜皮的争吵说明了政府的状况很糟糕。"}],"oxford":{"phon":"ˈkɒməntri","pos":"noun","senses":[{"en":"a spoken description of an event that is given while it is happening, especially on the radio or television","cn":"（尤指电台或电视台所作的）实况报道，现场解说","g":"[countable, uncountable]","ex":{"en":"a sports commentary","cn":"体育实况报道"}},{"en":"a written explanation or discussion of something such as a book or a play","cn":"注释；解释；评注；评论","g":"[countable]","ex":{"en":"a critical commentary on the final speech of the play","cn":"对这剧本结尾的台词所作的批判性评论"}},{"en":"a criticism or discussion of something","cn":"批评；议论","g":"[countable, uncountable]","ex":{"en":"The petty quarrels were a sad commentary on the state of the government.","cn":"这些鸡毛蒜皮的争吵说明了政府的状况很糟糕。"}}]}},"commune":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"群居团体;社群;公社","en":"A commune is a group of people who live together and share everything.","ex":{"en":"Mack lived in a commune.","cn":"麦克生活在一个群居团体里。"}},{"pos":"N-COUNT 可数名词","cn":"(法国等国家有自己的地方议会的)市镇","en":"In France and some other countries, a commune is a town, village, or area which has its own council."},{"pos":"VERB 动词","cn":"与(动物、精灵或大自然)交流;与…融为一体","en":"If you say that someone is communing with an animal or spirit, or with nature, you mean that they appear to be communicating with it.","ex":{"en":"He was so happy communing with the dolphin in Dingle Bay","cn":"他在丁格尔湾与海豚交流的时候特别开心。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of people who live together and who share the work and their possessions 〔","cn":"生活在一起﹑分享财产﹑分担职责的〕群居团体﹐社区"},{"en":"the smallest unit of local government in countries such as France and Belgium","cn":"市镇〔法国、比利时等国最小的地方行政区〕"},{"en":"a group of people in a Communist country who work as a team on a farm, and give what they produce to the state 〔","cn":"共产主义国家的〕公社"}]},"vocab":{"pos":"1 v 2 v 3 n 4 n","senses":[{"en":"A commune is a group living situation where people share everything. Communes were popular with the peace-loving hippies of the 1960s."}]},"collocations":{"phrases":["ADJ. hippy","VERB + COMMUNE join He gave up his job in the city and joined a commune. | belong to | form, set up","PREP. in/on a/the ~ She lives in a commune."]},"media":{"uk":"media/ldoce/hwd/bre/0/commune_n0205.mp3","us":"media/ldoce/hwd/ame/8/l3commune.mp3"},"examples":[{"en":"He spent much of this time communing with nature.","cn":"他这个时期的许多时间都沉浸在大自然中。"},{"en":"a 1970s hippy commune * 20","cn":"世纪 70 年代的嬉皮士群体"}],"oxford":{"phon":"ˈkɒmjuːn","pos":"noun","senses":[{"en":"a group of people who live together and share responsibilities, possessions, etc.","cn":"（共同生活、分担责任、共享财产等的）群体，公社","ex":{"en":"a 1970s hippy commune","cn":"20 世纪 70 年代的嬉皮士群体"}},{"en":"the smallest division of local government in France and some other countries","cn":"（法国及其他一些国家的）最小的行政区"}]}},"courageous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"勇敢的;有胆量的;无畏的","en":"Someone who is courageous shows courage.","ex":{"en":"It was a very frightening experience and they were very courageous","cn":"那是一次让人胆战心惊的经历，而他们表现得非常勇敢。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"showing that you are not afraid to do things that other people find dangerous or difficult","cn":""},{"en":"very brave – used especially about someone fighting for what they believe in, or fighting against a disease","cn":""},{"en":"brave and willing to take a lot of risks","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you are a courageous person, you face danger or stand up against the odds without flinching. Known as \"The Man without Fear,\" Daredevil is regarded as a very courageous superhero."}]},"collocations":{"phrases":["VERBS be, seem","ADV. exceptionally, extraordinarily, extremely, highly, incredibly, tremendously, very | quite, rather"]},"media":{"uk":"media/ldoce/hwd/bre/8/courageous0205.mp3","us":"media/ldoce/hwd/ame/9/courageous.mp3"},"examples":[{"en":"I hope people will be courageous enough to speak out against this injustice.","cn":"我希望人们能敢于大胆说出来，反对这种不公。"},{"en":"a very courageous decision","cn":"十分勇敢的决定"}],"oxford":{"phon":"kəˈreɪdʒəs","pos":"adjective","senses":[{"en":"showing courage","cn":"勇敢的；无畏的","ex":{"en":"a very courageous decision","cn":"十分勇敢的决定"}}]}},"collision":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"碰撞;相撞","en":"A collision occurs when a moving object crashes into something.","ex":{"en":"They were on their way to the Shropshire Union Canal when their van was involved in a collision with a car","cn":"在去往什罗普郡联盟运河的路上，他们的小货车与一辆小车相撞。"}},{"pos":"N-COUNT 可数名词","cn":"(不同文化或思想的)碰撞，冲突，抵触","en":"A collision of cultures or ideas occurs when two very different cultures or people meet and conflict.","ex":{"en":"It's the collision of disparate ideas that alters one's perspective","cn":"是迥然不同的观点之间的碰撞改变了人们的看法。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an event in which a vehicle is damaged and often someone is hurt","cn":""},{"en":"a serious accident in which a vehicle hits something else","cn":""},{"en":"an accident in which two or more cars, trains etc hit each other","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A collision is when two or more things smash together. You shouldn't give yourself a pedicure while driving because it might result in a collision , wrecking your car and spoiling your toenail polish to boot."}]},"collocations":{"phrases":["ADJ. serious | near | multiple | head-on, mid-air","VERB + COLLISION be involved in, have I had a near collision with a lorry. | avoid | cause","COLLISION + VERB happen, occur The collision occurred near the hospital.","PREP. in a/the ~ She was injured in a collision. | in ~ with The car was in collision with a lorry. | ~ between a head-on collision between ","PHRASES be on a collision course with sth An iceberg was on a collision course with the ship."]},"media":{"uk":"media/ldoce/hwd/bre/3/collision0205.mp3","us":"media/ldoce/hwd/ame/e/collision.mp3"},"examples":[{"en":"I was on a collision course with my boss over the sales figures.","cn":"我和我的老板在销售数字问题上差点发生争执。"},{"en":"A giant iceberg was on a collision course with the ship.","cn":"巨大的冰山朝着可能与船发生相撞的方向漂移。"}],"oxford":{"phon":"kəˈlɪʒn","pos":"noun","senses":[{"en":"an accident in which two vehicles or people crash into each other","cn":"碰撞（或相撞）事故","ex":{"en":"a collision between two trains","cn":"两列火车相撞事故"}},{"en":"a strong disagreement between two people or between ideas, opinions, etc. that are opposed to each other; the meeting of two things that are very different","cn":"（两人之间或对立意见、看法等之间的）冲突，抵触","lab":"formal","ex":{"en":"a collision between two opposing points of view","cn":"两种对立观点的冲突"}}]}},"confidential":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"秘密的;机密的","en":"Information that is confidential is meant to be kept secret or private.","ex":{"en":"She accused them of leaking confidential information about her private life","cn":"她指责他们泄露其私生活的秘密。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"悄悄的;隐秘的","en":"If you talk to someone in a confidential way, you talk to them quietly because what you are saying is secret or private.","ex":{"en":"'Look,' he said in a confidential tone, 'I want you to know that me and Joey are cops.'","cn":"“听着，”他悄声说，“我想让你知道我和乔伊是警察。”"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"known about by only a few people, who have agreed not to tell anyone else","cn":""},{"en":"used about information, especially in business or government, that is secret and not intended to be shown or told to other people","cn":""},{"en":"used about information that the government has ordered to be kept secret from most people","cn":""}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"If you get a letter stamped confidential , that means you're not supposed to tell anyone else what it says. It's private and you're not supposed to blab about it."}]},"collocations":{"phrases":["VERBS be | remain | keep sth, treat sth as The affair must be kept confidential. Information about prices is to be treated as confidential.","ADV. extremely, highly | absolutely, completely, strictly, totally The findings are strictly confidential. | commercially commercially confi"]},"media":{"uk":"media/ldoce/hwd/bre/6/confidential0205.mp3","us":"media/ldoce/hwd/ame/a/confidential.mp3"},"examples":[{"en":"She told me confidentially that she is going to retire early.","cn":"她私下告诉我她要提早退休。"},{"en":"He spoke in a confidential tone, his voice low.","cn":"他低声用隐密的语气说话。"}],"oxford":{"phon":"ˌkɒnfɪˈdenʃl","pos":"adjective","senses":[{"en":"meant to be kept secret and not told to or shared with other people","cn":"机密的；保密的；秘密的","ex":{"en":"confidential information/documents","cn":"机密情报／文件"}},{"en":"showing that what you are saying is private or secret","cn":"隐秘的；秘密的","ex":{"en":"He spoke in a confidential tone, his voice low.","cn":"他低声用隐秘的语气说话。"}},{"en":"trusted with private or secret information","cn":"受信任的；委以机密的","g":"[only before noun]","lab":"formal","ex":{"en":"a confidential secretary","cn":"机要秘书"}}]}},"cordon":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(由警察、士兵或车辆组成的)警戒线，封锁线;封锁圈","en":"A cordon is a line or ring of police, soldiers, or vehicles preventing people from entering or leaving an area.","ex":{"en":"Police formed a cordon between the two crowds.","cn":"警察在两群人之间筑起了一道封锁线。"}},{"pos":"","cn":"","en":"相关词组：cordon off"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a line of police officers, soldiers, or vehicles that is put around an area to stop people going there","cn":"警戒线﹐封锁线"},{"en":"to surround and protect an area with police officers, soldiers, or vehicles","cn":"设置警戒线围起"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"That yellow police tape and group of officers encircling the crime scene? That's a kind of cordon — something set up to guard something."}]},"collocations":{"phrases":["ADJ. tight | police, security","VERB + CORDON form, throw Police officers threw a cordon around his car to protect him. | break through The crowd managed to break through t","CORDON + VERB prevent sth A police cordon prevented the marchers from entering the main square.","PREP. ~ around/round There is a tight security cordon around the area."]},"media":{"uk":"media/ldoce/hwd/bre/4/cordon_n0205.mp3","us":"media/ldoce/hwd/ame/7/cordon1.mp3"},"examples":[{"en":"Police cordoned off the area until the bomb was made safe.","cn":"警方封锁了这个地区直到炸弹被安全拆除为止。"},{"en":"Demonstrators broke through the police cordon.","cn":"示威者冲破了警方的警戒线。"}],"oxford":{"phon":"ˈkɔːdn","pos":"noun","senses":[{"en":"a line or ring of police officers, soldiers, etc. guarding something or stopping people from entering or leaving a place","cn":"（由警察、士兵等组成的）警戒线，封锁线","ex":{"en":"Demonstrators broke through the police cordon.","cn":"示威者冲破了警方的警戒线。"}}]}},"consent":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"许可;允许","en":"If you give your consent to something, you give someone permission to do it.","ex":{"en":"At approximately 11:30 p.m., Pollard finally gave his consent to the search","cn":"大概晚上11点半的时候，波拉德最终同意进行搜查。"}},{"pos":"VERB 动词","cn":"同意;允许","en":"If you consent to something, you agree to do it or to allow it to be done.","ex":{"en":"He finally consented to go","cn":"他最终同意去了。"}},{"pos":"PHRASE 短语","cn":"经一致同意;经双方同意","en":"If something happens by common consent or by mutual consent, it happens as the result of an agreement between the people or groups involved.","ex":{"en":"By common consent their talk avoided the reason for their being there at all","cn":"双方达成共识，他们的谈话对他们去那儿的原因完全避而不谈。"}},{"pos":"PHRASE 短语","cn":"经普遍同意","en":"You can use by general consent or by common consent to indicate that most people agree that something is true.","ex":{"en":"By common consent this election constituted a historic step on the road to democracy.","cn":"普遍认为这次选举是迈上民主之路的历史性一步。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when someone officially allows you to do something","cn":""},{"en":"official permission to do something, especially written permission, from someone in a position of authority","cn":""},{"en":"formal permission you give for something important that will affect you, your family, or your property","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"Before you have surgery, you'd better give your consent , because the surgeon can't get his scalpel anywhere near your skin without first getting this permission from you."}]},"collocations":{"phrases":["ADV. freely | kindly He has kindly consented to give us some of his valuable time.","PREP. to Her father would not consent to the marriage."]},"media":{"uk":"media/ldoce/hwd/bre/3/consent_n0205.mp3","us":"media/ldoce/hwd/ame/d/consent1.mp3"},"examples":[{"en":"He is charged with taking a car without the owner's consent.","cn":"他因未征得车主的同意自行开走车而受到指控。"},{"en":"When she told them what she intended they readily consented.","cn":"她告诉他们她的打算时，他们欣然同意。"}],"oxford":{"phon":"kənˈsent","pos":"noun","senses":[{"en":"permission to do something, especially given by somebody in authority","cn":"同意；准许；允许","g":"[uncountable]","ex":{"en":"The written consent of a parent is required.","cn":"要求有家长的书面同意。"}},{"en":"agreement about something","cn":"同意；赞同","g":"[uncountable]","ex":{"en":"She was chosen as leader by common consent (= everyone agreed to the choice).","cn":"大家一致同意选她为领导人。"}},{"en":"an official document giving permission for something","cn":"正式批准文件；批文","g":"[countable]","ex":{"en":"Your family, in effect, signs the consent for you.","cn":"事实上，你的家人给你签了同意书。"}},{"en":"to agree to something or give your permission for something","cn":"同意；准许；允许","ex":{"en":"When she told them what she intended, they readily consented.","cn":"她告诉他们她的打算时，他们欣然同意。"},"pos":"verb"}]}},"congratulate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"祝贺;向…道贺","en":"If you congratulate someone, you say something to show you are pleased that something nice has happened to them.","ex":{"en":"She congratulated him on the birth of his son","cn":"她祝贺他喜得贵子。"}},{"pos":"VERB 动词","cn":"表扬；称赞","en":"If you congratulate someone, you praise them for something good that they have done.","ex":{"en":"I really must congratulate the organisers for a well run and enjoyable event","cn":"活动安排得有条不紊，充满乐趣，我必须要称赞一下组织者。"}},{"pos":"VERB 动词","cn":"为(自己)感到高兴(或自豪）","en":"If you congratulate yourself, you are pleased about something that you have done or that has happened to you.","ex":{"en":"Waterstone has every reason to congratulate himself","cn":"沃特斯通完全有理由为自己感到高兴。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say that you admire and approve of someone or something, especially publicly","cn":""},{"en":"to tell someone that you think it is good that they have achieved something","cn":""},{"en":"to say to someone that you like how they look, or you like something they have done","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you congratulate someone, you give that person praise — or maybe even a party to congratulate him or her on a job well done."}]},"collocations":{"phrases":["ADV. warmly","VERB + CONGRATULATE must, wish to, would like to I must congratulate you on your excellent exam results.","PREP. for The employees should be congratulated for the part they have played in the success. | on She congratulated me warmly on my perform","PHRASES sb is to be congratulated The company is to be congratulated on its success."]},"media":{"uk":"media/ldoce/hwd/bre/d/congratulate0205.mp3","us":"media/ldoce/hwd/ame/b/congratulate.mp3"},"examples":[{"en":"The authors are to be congratulated on producing such a clear and authoritative work.","cn":"向创作出这样一部具有权威性又清晰易懂的作品的作者们祝贺。"},{"en":"I congratulated them all on their results.","cn":"我为他们取得的成就向他们所有人表示祝贺。"}],"oxford":{"phon":"kənˈɡrætʃəleɪt","pos":"verb","senses":[{"en":"to tell somebody that you are pleased about their success or achievements","cn":"向（某人）道贺；祝贺","lab":"British English","ex":{"en":"I congratulated them all on their results.","cn":"我为他们取得的成就向他们所有人表示祝贺。"}},{"en":"to feel pleased and proud because you have achieved something or been successful at something","cn":"（为成就或成功）感到自豪，引以为豪","ex":{"en":"You can congratulate yourself on having done an excellent job.","cn":"你应该为你出色的工作感到自豪。"}}]}},"communism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"共产主义;共产主义信仰","en":"Communism is the political belief that all people are equal and that workers should control the means of producing things.","ex":{"en":"...the ultimate triumph of communism in the world.","cn":"共产主义在世界上最终的胜利"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a political system in which the government controls the production of all food and goods, and there is no privately owned property","cn":"共产主义（制度）"},{"en":"the belief in this political system","cn":"共产主义的信念"}]},"vocab":{"pos":"n","senses":[{"en":"At the opposite end of the spectrum from \"capitalism,\" communism is an economic theory favoring a classless society and the abolition of private property."}]},"collocations":{"phrases":["ADJ. revolutionary | international","VERB + COMMUNISM embrace | overthrow, reject","PREP. under ~ a book describing life under communism","PHRASES the collapse/fall of communism, the fight/struggle against communism, the rise/spread of communism"]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdecommunism.mp3","us":"media/ldoce/hwd/ame/7/amelasdecommunism.mp3"},"oxford":{"phon":"ˈkɒmjənɪzəm","pos":"noun","senses":[{"en":"a theory or system of social organization in which all property is owned by the community and each person contributes and receives according to their ability and needs","cn":"共产主义"},{"en":"the system of government by a ruling Communist Party, such as in the former USSR","cn":"共产主义制度","ex":{"en":"a book describing life under Communism","cn":"描写共产主义体制下生活的书籍"}}]}},"cosmetic":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"化妆品; 美容品","en":"Cosmetics are substances such as lipstick or powder, which people put on their face to make themselves look more attractive."},{"pos":"ADJ 形容词","cn":"装门面的;表面的","en":"If you describe measures or changes as cosmetic, you mean they improve the appearance of a situation or thing but do not change its basic nature, and you are usually implying that they are inadequate.","ex":{"en":"It is a cosmetic measure which will do nothing to help the situation long term","cn":"这项举措只是表面文章，长期来看对于改善情况不会有任何帮助。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"dealing with the outside appearance rather than the important part of something","cn":"装门面的﹔表面的"},{"en":"intended to make your hair, skin, body etc look more attractive","cn":"化妆用的﹔美容的"}]},"vocab":{"pos":"adj n","senses":[{"en":"Cosmetic refers to how something or someone looks. Visit the cosmetics department of a store if you are looking to buy lipstick, and visit a cosmetic surgeon if you are looking to buy new lips."}]},"collocations":{"phrases":["ADJ. expensive | cheap","VERB + COSMETIC use, wear | apply, put on","COSMETIC + NOUN business, company, industry"]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdecosmetic.mp3","us":"media/ldoce/hwd/ame/b/cosmetic1.mp3"},"examples":[{"en":"She dismissed the plan as a cosmetic exercise to win votes.","cn":"她认为这项计划是为了赢得选票所做的表面文章，因而不予考虑。"},{"en":"These reforms are not merely cosmetic.","cn":"这些改革不仅仅是装点门面的。"}],"oxford":{"phon":"kɒzˈmetɪk","pos":"noun","senses":[{"en":"a substance that you put on your face or body to make it more attractive","cn":"化妆品；美容品","lab":"North American English also","ex":{"en":"the cosmetics industry","cn":"化妆品行业"}},{"en":"improving only the outside appearance of something and not its basic character","cn":"装门面的；表面的","ex":{"en":"These reforms are not merely cosmetic.","cn":"这些改革不仅仅是装点门面的。"},"pos":"adjective"},{"en":"connected with medical treatment that is intended to improve a person’s appearance","cn":"整容的","ex":{"en":"cosmetic surgery","cn":"整容外科"},"pos":"adjective"}]}},"confess":{"collins":{"senses":[{"pos":"VERB 动词","cn":"承认，供认，坦白(自己做错的事)","en":"If someone confesses to doing something wrong, they admit that they did it.","ex":{"en":"He had confessed to seventeen murders","cn":"他供认了17起谋杀案。"}},{"pos":"VERB 动词","cn":"(向上帝或神甫)忏悔，告解(罪过)","en":"If someone confesses or confesses their sins, they tell God or a priest about their sins so that they can be forgiven.","ex":{"en":"You just go to the church and confess your sins","cn":"你干脆去教堂忏悔自己的罪过吧。"}},{"pos":"PHRASE 短语","cn":"我承认，我必须承认(用来对自己的过失等略表歉意)","en":"You use expressions like 'I confess', 'I must confess', or 'I have to confess' to apologize slightly for admitting something you are ashamed of or that you think might offend or annoy someone.","ex":{"en":"I confess it's got me baffled","cn":"我承认这把我难倒了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to agree unwillingly that something is true","cn":""},{"en":"to admit something in a discussion or argument","cn":""},{"en":"to say that something is true or that a situation exists","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you confess , you admit to doing something wrong. You might feel guilty about eating the entire platter of chocolate chip cookies and confess to your mom before she notices. If she presses charges, you would confess to the cookie crime."}]},"collocations":{"phrases":["ADV. freely, openly | allegedly | ruefully, sheepishly","VERB + CONFESS have to, must I must confess that I didn't have much faith in her ideas.","PREP. to He was arrested and confessed to the murder. She confessed to me that she had known his true identity for some time."]},"media":{"uk":"media/ldoce/hwd/bre/a/confess0205.mp3","us":"media/ldoce/hwd/ame/1/confess.mp3"},"examples":[{"en":"After hours of questioning, the suspect confessed.","cn":"经过数小时的审问后，嫌疑犯终于招供。"},{"en":"‘I know nothing about them,’ he confessed. “","cn":"我对他们一无所知。”他承认道。"}],"oxford":{"phon":"kənˈfes","pos":"verb","senses":[{"en":"to admit, especially formally or to the police, that you have done something wrong or illegal","cn":"供认，坦白，承认（错误或罪行）","g":"[intransitive, transitive]","ex":{"en":"After hours of questioning, the suspect confessed.","cn":"经过数小时的审问，嫌疑犯终于招供。"}},{"en":"to admit something that you feel ashamed or embarrassed about","cn":"承认（自己感到羞愧或尴尬的事）","g":"[intransitive, transitive]","lab":"formal","ex":{"en":"She was reluctant to confess her ignorance.","cn":"她不愿承认她的无知。"}},{"en":"to tell God or a priest about the bad things you have done so that you can say that you are sorry and be forgiven","cn":"忏悔；悔过；告罪；告解","g":"[intransitive, transitive]","ex":{"en":"They had confessed their sins and done their penance.","cn":"他们已经告罪并作了补赎。"}},{"en":"to hear somebody confess their sins (= the bad things they have done)","cn":"聆听（某人的）忏悔（或告罪、告解）","g":"[transitive]"}]}},"consistency":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"连贯性;一致性","en":"Consistency is the quality or condition of being consistent.","ex":{"en":"He scores goals with remarkable consistency","cn":"他的进球一气呵成。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"稠度;平滑度","en":"The consistency of a substance is how thick or smooth it is.","ex":{"en":"Dilute the paint with water until it is the consistency of milk","cn":"用水把涂料稀释到牛奶般的稠度。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the quality of always being the same, doing things in the same way, having the same standards etc – used to show approval","cn":"连贯性﹐前后一致〔含褒义〕"},{"en":"how thick, smooth etc a substance is","cn":"密实度﹔平滑度﹔黏稠度"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Foods like puddings and gravies need to be the correct consistency — that is, the right thickness or texture — for the dish. It would not be good, for example, for gravy to have the consistency of cottage cheese."}]},"collocations":{"phrases":["ADJ. absolute, complete, total | great, remarkable | internal","QUANT. degree, level","VERB + CONSISTENCY show He has shown remarkable consistency in his exam results. | achieve, ensure, maintain | lack","PREP. ~ in/of a consistency in/of approach | ~ with to maintain consistency with past practice 2 thickness/firmness of a liquid substance","ADJ. thick, thin | soft, stiff | creamy, smooth | sticky | dropping Add milk to produce a soft dropping consistency. | correct, right Knead ","VERB + CONSISTENCY have The mixture should have the consistency of thick cream. | give, produce"]},"media":{"uk":"media/ldoce/hwd/bre/4/consistency0205.mp3","us":"media/ldoce/hwd/ame/2/consistency.mp3"},"examples":[{"en":"We need to ensure the consistency of service to our customers.","cn":"我们对客户要确保服务的连贯性。"},{"en":"The cement should have the consistency of wet sand.","cn":"水泥应当具有湿沙的坚实度。"}],"oxford":{"phon":"kənˈsɪstənsi","pos":"noun","senses":[{"en":"the quality of always behaving in the same way or of having the same opinions, standard, etc.; the quality of being consistent","cn":"一致性；连贯性","g":"[uncountable]","lab":"approving","ex":{"en":"She has played with great consistency all season.","cn":"她整个赛季表现相当稳定。"}},{"en":"the consistency of a mixture or a liquid substance is how thick, smooth, etc. it is","cn":"黏稠度；密实度；平滑度；坚实度","g":"[countable, uncountable]","lab":"especially British English","ex":{"en":"Beat the ingredients together to a creamy consistency.","cn":"把配料搅拌成乳脂状。"}}]}},"constitution":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(一国的)宪法;(组织的)章程","en":"The constitution of a country or organization is the system of laws which formally states people's rights and duties.","ex":{"en":"The king was forced to adopt a new constitution which reduced his powers.","cn":"国王被迫采用了削弱其权力的新宪法。"}},{"pos":"N-COUNT 可数名词","cn":"体质;体格","en":"Your constitution is your health.","ex":{"en":"He must have an extremely strong constitution","cn":"他的体格必定极其强壮。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is strong has a healthy body that can do a lot of physical exercise, and becomes well quickly after any illnesses","cn":""},{"en":"to not become ill easily and easily get well again after an illness or injury","cn":""},{"en":"someone who is robust is very healthy, strong, and active, and almost never ill","cn":""}]},"vocab":{"pos":"1 n 2 n 3 n","senses":[{"en":"A constitution is a statement of the basic principles and laws of a nation, state, or group, such as the U.S. Constitution. Another very common meaning of constitution is the physical makeup of a person."}]},"collocations":{"phrases":["ADJ. federal, state | codified, written Britain does not have a written constitution. | unwritten | draft, proposed | interim","VERB + CONSTITUTION draft, draw up, prepare plans to draft a new constitution | have | adopt, approve, enact, promulgate, ratify The new con","CONSTITUTION + VERB forbid sth, guarantee sth, stipulate sth The constitution stipulated that a general election must be held within 120 day","PREP. according to/under a/the ~ Under the constitution, an election must be called every five years. | in a/the ~ These rights are establis","PHRASES an amendment to a constitution, a clause in a constitution, the principles of a constitution, the provisions/terms of a constitution","ADJ. good, strong | weak","VERB + CONSTITUTION have The child had a weak constitution and was always ill."]},"media":{"uk":"media/ldoce/hwd/bre/5/constitution0205.mp3","us":"media/ldoce/hwd/ame/b/constitution.mp3"},"examples":[{"en":"your right to vote under the constitution","cn":"根据宪法所拥有的选举权"},{"en":"to propose a new amendment to the Constitution","cn":"提出一项新的宪法修正案"}],"oxford":{"phon":"ˌkɒnstɪˈtjuːʃn","pos":"noun","senses":[{"en":"the system of laws and basic principles that a state, a country or an organization is governed by","cn":"宪法；章程","g":"[countable]","ex":{"en":"your right to vote under the constitution","cn":"根据宪法所拥有的选举权"}},{"en":"the condition of a person’s body and how healthy it is","cn":"身体素质；体质；体格","g":"[countable]","ex":{"en":"to have a healthy/strong/weak constitution","cn":"体质健康／强壮／虚弱"}},{"en":"the way something is formed or organized","cn":"构成；构造","g":"[uncountable, countable]","lab":"formal","ex":{"en":"the genetic constitution of cells","cn":"细胞的基因构造"}},{"en":"the act of forming something","cn":"组成；形成","g":"[uncountable]","lab":"formal","ex":{"en":"He recommended the constitution of a review committee.","cn":"他建议设立审查委员会。"}}]}},"copenhagen":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the capital city of Denmark, a port and industrial centre in the east of the country. There is a well-known statue (= image of a person made from solid material ) of the ‘Little Mermaid’ in the port.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/p028-000003614.mp3","us":"media/ldoce/hwd/ame/f/p028-000003614.mp3"}},"coax":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(用好话)劝诱，哄","en":"If you coax someone into doing something, you gently try to persuade them to do it.","ex":{"en":"After lunch, she watched, listened and coaxed Bobby into talking about himself","cn":"吃过午饭，她照看着博比，听他说话，哄他说说自己的事。"}},{"pos":"VERB 动词","cn":"连哄带劝地得到","en":"If you coax something such as information out of someone, you gently persuade them to give it to you.","ex":{"en":"The WPC talked yesterday of her role in trying to coax vital information from the young victim","cn":"昨天，这名女警谈到自己在诱导年轻的受害人说出重要信息的过程中所起的作用。"}},{"pos":"VERB 动词","cn":"小心地摆弄(机器或装置)","en":"If you coax a machine or device into doing something, you make it work by operating it very slowly and gently.","ex":{"en":"He would stride on stage then proceed to coax the sweetest possible sounds out of his violin","cn":"他会大步走上舞台，然后轻轻地拉他的小提琴，奏出美妙动听的曲调。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone decide to do something, especially by giving them reasons why they should do it, or asking them many times to do it","cn":""},{"en":"to persuade someone to do something, especially something they do not really want to do","cn":""},{"en":"to make someone do something by persuading or asking them","cn":""}]},"vocab":{"pos":"1 v 2 n","senses":[{"en":"When you coax someone, you try to convince him gently, with pleasant words and maybe a little flattery. You’ll have to be patient, as you can’t rush someone you’re trying to coax ."}]},"collocations":{"phrases":["ADV. gently","VERB + COAX try to | manage to | fail to","PREP. from He could coax tears and laughter from his audience. | into He gently coaxed life back into my frozen toes. | out of She never fai"]},"media":{"uk":"media/ldoce/hwd/bre/d/coax0205.mp3","us":"media/ldoce/hwd/ame/8/coax.mp3"},"examples":[{"en":"The director coaxed a brilliant performance out of the cast.","cn":"经过导演悉心劝说，全体演员完成一场精彩的表演。"},{"en":"He was coaxed out of retirement to help the failing company.","cn":"他退休之后又被力劝出山帮助濒临破产的公司。"}],"oxford":{"phon":"kəʊks","pos":"verb","senses":[{"en":"to persuade somebody to do something by talking to them in a kind and gentle way","cn":"哄劝；劝诱","lab":"figurative","ex":{"en":"She coaxed the horse into coming a little closer.","cn":"她哄着那匹马让它再靠近了一点。"}},{"en":"(of a cable) sending signals using two wires inside one cable, one of which is wrapped around the other. Coax cable is used by TV, phone and internet companies.","cn":"（电缆）同轴的","pos":"adjective"}]}},"correction":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指对作业的)批改，修改","en":"Corrections are marks or comments made on a piece of work, especially school work, which indicate where there are mistakes and what are the right answers."},{"pos":"N-UNCOUNT 不可数名词","cn":"(对罪犯的)惩罚，处罚","en":"Correction is the punishment of criminals.","ex":{"en":"...jails and other parts of the correction system.","cn":"监狱和其他惩治改造机构"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a mark or note correcting something on a piece of written work","cn":""},{"en":"to tell someone the true facts when they have made a mistake, especially if you are annoyed by their mistake","cn":""},{"en":"to tell people the true facts about something, especially in public, because you want to make it very clear that what is believed is in fact not correct","cn":""}]},"collocations":{"phrases":["ADJ. minor, small | necessary Make any necessary corrections before the text is printed. | error, spelling","VERB + CORRECTION make | need, require There are some programming errors that need correction.","PREP. ~ to I've got to make one or two small corrections to the text before it's finished."]},"media":{"uk":"media/ldoce/hwd/bre/a/correction0205.mp3","us":"media/ldoce/hwd/ame/e/correction.mp3"},"examples":[{"en":"I don't know. Correction — I do know, but I'm not going to tell you.","cn":"我不知道。不，我知道不假，但不打算告诉你。"},{"en":"The paper had to publish a correction to the story.","cn":"这家报纸不得不对这则新闻报道发一个更正。"}],"oxford":{"phon":"kəˈrekʃn","pos":"noun","senses":[{"en":"a change that makes something more accurate than it was before","cn":"改正；纠正；修正","g":"[countable]","ex":{"en":"I've made a few small corrections to your report.","cn":"我对你的报告作了几处小的修改。"}},{"en":"the act or process of correcting something","cn":"改正的行动（或过程）","g":"[uncountable]","ex":{"en":"There are some programming errors that need correction.","cn":"有一些程序错误需要改正。"}},{"en":"punishment","cn":"惩罚；处罚；惩治","g":"[uncountable]","lab":"old-fashioned","ex":{"en":"the correction of young offenders","cn":"对失足青少年的管教"}},{"en":"used when you want to correct something that you have just said","cn":"（想纠正刚说过的话时用）改正，更正","ex":{"en":"I don't know. Correction—I do know, but I'm not going to tell you.","cn":"我不知道。不，我知道不假，但不打算告诉你。"},"pos":"exclamation"}]}},"complicity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同谋;串通","en":"Complicity is involvement with other people in an illegal activity or plan.","ex":{"en":"Recently a number of policemen were sentenced to death for their complicity in the murder","cn":"最近，几名警察因串谋杀人被判处死刑。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"involvement in a crime, together with other people 〔","cn":"罪案的〕共犯﹐同谋"},{"en":"involvement in or knowledge of a situation, especially one that is morally wrong or dishonest 〔","cn":"尤指对不道德或不诚实情况的〕串通﹐勾结﹐同谋"}]},"vocab":{"pos":"n","senses":[{"en":"Complicity is involvement in a wrongful act — like when you drove your newly-turned-vegetarian friend to a fast food joint so that she could scarf down a hamburger."}]},"collocations":{"phrases":["ADJ. alleged, apparent her alleged complicity in the bombing | active | government, police","PREP. ~ between the complicity between the army and drug smugglers | ~ in her complicity in a plot to kill the president | ~ with She did no","PHRASES an act of complicity • Note at CRIME (for verbs)"]},"media":{"uk":"media/ldoce/hwd/bre/5/complicity0205.mp3","us":"media/ldoce/hwd/ame/3/complicity.mp3"},"examples":[{"en":"evident complicity between the two brothers","cn":"两兄弟间明显的串通一气"},{"en":"to be guilty of complicity in the murder","cn":"犯凶杀同谋罪"}],"oxford":{"phon":"kəmˈplɪsəti","pos":"noun","senses":[{"en":"the act of taking part with another person in a crime","cn":"同谋；共犯；勾结","ex":{"en":"to be guilty of complicity in the murder","cn":"犯凶杀同谋罪"}}]}},"conjecture":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"推测;猜测","en":"A conjecture is a conclusion that is based on information that is not certain or complete.","ex":{"en":"That was a conjecture, not a fact","cn":"那只是猜测，不是事实。"}},{"pos":"VERB 动词","cn":"推测;猜测;揣测","en":"When you conjecture, you form an opinion or reach a conclusion on the basis of information that is not certain or complete.","ex":{"en":"He conjectured that some individuals may be able to detect major calamities","cn":"他猜测说有些人也许能够察觉重大灾难。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an attempt to guess something","cn":""},{"en":"an opinion about the value, size, speed etc of something that is formed partly by calculating and partly by guessing","cn":""},{"en":"when you try to understand something or find the answer to something by guessing, because you do not have all the information you need","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"Can you guess what conjecture means? It's a word to use when you are not sure of something and have to \"guess or surmise.\""}]},"collocations":{"phrases":["ADJ. pure Whether the business will survive another ten years is pure conjecture.","PREP. ~ about/as to There was a lot of conjecture as to the extent of her wealth.","PHRASES a matter for conjecture, open to conjecture Whether she will run for a second term in office is open to conjecture."]},"media":{"uk":"media/ldoce/hwd/bre/4/conjecture_n0205.mp3","us":"media/ldoce/hwd/ame/2/conjecture1.mp3"},"examples":[{"en":"What was going through the killer's mind is a matter for conjecture.","cn":"凶手作案时心里是怎样想的，这个问题只能由人们去推测了。"},{"en":"We can only conjecture about what was in the killer's mind.","cn":"我们只能猜测当时凶手心里想的是什么。"}],"oxford":{"phon":"kənˈdʒektʃə(r)","pos":"noun","senses":[{"en":"an opinion or idea that is not based on definite knowledge and is formed by guessing","cn":"猜测；推测","g":"[countable]","ex":{"en":"The truth of his conjecture was confirmed by the newspaper report.","cn":"新闻报道证明了他的推测果然不假。"}},{"en":"the act of forming an opinion or idea that is not based on definite knowledge","cn":"揣测；臆测","g":"[uncountable]","ex":{"en":"What was going through the killer's mind is a matter for conjecture.","cn":"凶手当时心里是怎样想的，这个问题只能由人们去推测了。"}},{"en":"to form an opinion about something even though you do not have much information on it","cn":"猜测；推测","ex":{"en":"We can only conjecture about what was in the killer's mind.","cn":"我们只能猜测当时凶手心里想的是什么。"},"pos":"verb"}]}},"contention":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(争论或讨论时的)看法，观点","en":"Someone's contention is the idea or opinion that they are expressing in an argument or discussion.","ex":{"en":"This evidence supports their contention that the outbreak of violence was prearranged.","cn":"这一证据证实了他们的观点，即此次突发暴力事件是有预谋的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"不和;争吵;争执","en":"If something is a cause of contention, it is a cause of disagreement or argument.","ex":{"en":"They generally tried to avoid subjects of contention between them","cn":"他们一般都尽量避免会引起彼此不和的话题。"}},{"pos":"PHRASE 短语","cn":"有机会获胜","en":"If you are in contention in a contest, you have a chance of winning it.","ex":{"en":"He was in contention for a place in the European championship squad.","cn":"他有望在欧洲锦标赛代表队中获得一席之地。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a statement that something is true, even though it has not been proved","cn":""},{"en":"a statement that someone has done something wrong or illegal, but that has not been proved","cn":""},{"en":"something that you say or write that you strongly believe","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"There is nothing \"content,\" or satisfying, about being in contention, and that's probably because the word contention means being in a competition that ends with one side, usually the winning one, being content."}]},"collocations":{"phrases":["ADJ. main Her main contention is that staff should get better training.","VERB + CONTENTION support There is no evidence to support her contention. | reject 2 disagreement between people","PREP. ~ between There is no contention between the two groups.","PHRASES an area of contention, a bone/point/source of contention Where to go on holiday is always a bone of contention in our family."]},"media":{"uk":"media/ldoce/hwd/bre/f/contention0205.mp3","us":"media/ldoce/hwd/ame/5/contention.mp3"},"examples":[{"en":"One area of contention is the availability of nursery care.","cn":"争论的一个方面是提供幼儿保育的可能性。"},{"en":"It is our client's contention that the fire was an accident.","cn":"我们当事人的看法是这场火灾属于事故。"}],"oxford":{"phon":"kənˈtenʃn","pos":"noun","senses":[{"en":"anger between people who disagree","cn":"争执；争吵","g":"[uncountable]","ex":{"en":"One area of contention is the availability of nursery care.","cn":"争论的一个方面是提供幼儿照顾的问题。"}},{"en":"a belief or an opinion that you express, especially in an argument","cn":"（尤指争论时的）看法，观点","g":"[countable]","ex":{"en":"It is our client's contention that the fire was an accident.","cn":"我们当事人的看法是这场火灾属于意外事故。"}}]}},"composure":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"冷静;镇定;沉着","en":"Composure is the appearance or feeling of calm and the ability to control your feelings.","ex":{"en":"For once Dimbleby lost his composure. It was all he could do to stop tears of mirth falling down his cheeks","cn":"这一次丁布尔比没能控制住自己的感情。他唯一能做的也就是不让欢乐的泪水流下脸庞。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the state of feeling or seeming calm","cn":"冷静﹐镇定"},{"en":"recover/regain your composure (= become calm after feeling angry or upset ) Carter looked stunned, but he soon regained his composure.","cn":"卡特看上去大吃一惊﹐但很快又恢复了镇定。 keep/maintain your composure (= stay calm ) The widow broke down in tears, but her daughters mainta"}]},"vocab":{"pos":"n","senses":[{"en":"When you stay calm under pressure, you keep your composure . Keeping your composure for a skinned knee? Easy. Keeping your composure during an avalanche? Not so easy."}]},"collocations":{"phrases":["ADJ. cool, perfect","VERB + COMPOSURE keep, maintain | lose She totally lost her composure and began shouting. | recover, regain | ruffle Nothing could ruffle hi","PREP. with ~ She answered with perfect composure."]},"media":{"uk":"media/ldoce/hwd/bre/b/composure0205.mp3","us":"media/ldoce/hwd/ame/6/composure.mp3"},"examples":[{"en":"to keep/lose/recover/regain your composure","cn":"保持/失去/恢复镇静"}],"oxford":{"phon":"kəmˈpəʊʒə(r)","pos":"noun","senses":[{"en":"the state of being calm and in control of your feelings or behaviour","cn":"沉着；镇静；镇定","ex":{"en":"to keep/lose/recover/regain your composure","cn":"保持／失去／恢复镇静"}}]}},"collapse":{"collins":{"senses":[{"pos":"VERB 动词","cn":"倒塌;塌下","en":"If a building or other structure collapses, it falls down very suddenly.","ex":{"en":"A section of the Bay Bridge had collapsed","cn":"海湾大桥有一段垮塌了。"}},{"pos":"VERB 动词","cn":"(体系或机构)崩溃，瓦解，突然失败","en":"If something, for example a system or institution, collapses, it fails or comes to an end completely and suddenly.","ex":{"en":"His business empire collapsed under a massive burden of debt","cn":"他的商业帝国无力承担沉重的债务负担而垮掉了。"}},{"pos":"VERB 动词","cn":"(因生病或虚弱)突然倒下，昏倒","en":"If you collapse, you suddenly faint or fall down because you are very ill or weak.","ex":{"en":"He collapsed following a vigorous exercise session at his home","cn":"在家剧烈运动了一阵后他突然昏倒了。"}},{"pos":"VERB 动词","cn":"(因精疲力竭而)突然坐下(或倒下)","en":"If you collapse onto something, you sit or lie down suddenly because you are very tired.","ex":{"en":"She arrived home exhausted and barely capable of showering before collapsing on her bed.","cn":"她精疲力竭地回到家，勉强冲了个澡就倒在了床上。"}},{"pos":"VERB 动词","cn":"萎陷;内陷;瘪掉","en":"If something with air inside collapses, it falls inwards and becomes smaller or flatter.","ex":{"en":"He plunged 300ft to the ground when his parachute collapsed","cn":"降落伞突然瘪了，他从300英尺的高空跌落到地面。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to suddenly go down onto the floor when standing, walking, or running","cn":""},{"en":"to fall or almost fall when you hit your foot against something","cn":""},{"en":"to fall or almost fall when you are walking on a wet or very smooth surface","cn":""}]},"vocab":{"pos":"1 v n 2 v n 3 v n 4 ","senses":[{"en":"To collapse means to fall over, cave in, or totally crumple. After finding out that the stock market has collapsed and your investments along with it, you'd probably collapse to the ground and sob uncontrollably."}]},"collocations":{"phrases":["ADV. completely","PREP. into Several buildings have collapsed into the sea. | under The roof collapsed under the weight of snow. 2 of a sick person","ADV. suddenly","PREP. against The man collapsed against the wall and slid down it. | from She collapsed suddenly from a heart attack. | with He collapsed wi","ADV. eventually, finally In November the strike finally collapsed. | quickly, rapidly | suddenly | virtually","PHRASES to collapse in the face of sth The scheme collapsed in the face of determined opposition."]},"media":{"uk":"media/ldoce/hwd/bre/0/collapse_v0205.mp3","us":"media/ldoce/hwd/ame/9/collapse1.mp3"},"examples":[{"en":"Share prices collapsed after news of poor trading figures.","cn":"在交易数额不佳的消息公布后，股票价格暴跌。"},{"en":"He collapsed in the street and died two hours later.","cn":"他昏倒在大街上，两小时后便去世了。"}],"oxford":{"phon":"kəˈlæps","pos":"verb","senses":[{"en":"to fall down or fall in suddenly, often after breaking apart","cn":"（突然）倒塌，坍塌","g":"[intransitive]","sc":"of building","ex":{"en":"The roof collapsed under the weight of snow.","cn":"房顶在雪的重压下突然坍塌下来。"}},{"en":"to fall down (and usually become unconscious), especially because you are very ill","cn":"（尤指因病重而）倒下，昏倒，晕倒","g":"[intransitive]","sc":"of sick person","ex":{"en":"She collapsed and was rushed to hospital.","cn":"她晕倒了，被紧急送往医院。"}},{"en":"to sit or lie down and relax, especially after working hard","cn":"（尤指工作劳累后）坐下，躺下放松","g":"[intransitive]","lab":"informal","sc":"relax","ex":{"en":"When I get home I like to collapse on the sofa and listen to music.","cn":"回到家时，我喜欢倒在沙发上听音乐。"}},{"en":"to fail suddenly or completely","cn":"突然失败；崩溃；瓦解","g":"[intransitive]","sc":"fail","ex":{"en":"Talks between management and unions have collapsed.","cn":"资方与工会的谈判已告破裂。"}},{"en":"to decrease suddenly in amount or value","cn":"（突然）降价，贬值；暴跌","g":"[intransitive]","sc":"of prices/currencies","ex":{"en":"Share prices collapsed after news of poor trading figures.","cn":"在交易数额不佳的消息公布后，股票价格暴跌。"}},{"en":"to fold something into a shape that uses less space; to be able to be folded in this way","cn":"折叠；套缩；可折叠（或套缩）","g":"[intransitive, transitive]","sc":"fold","ex":{"en":"The table collapses for easy storage.","cn":"这桌子可折叠起来方便存放。"}},{"en":"if a lung or blood vessel collapses or is collapsed, it falls in and becomes flat and empty","cn":"（肺或血管）萎陷","g":"[intransitive, transitive]","sc":"medical"},{"en":"a sudden failure of something, such as an institution, a business or a course of action","cn":"（机构、生意、行动等的）突然失败，倒闭，崩溃","g":"[countable, usually singular, uncountable]","sc":"failure","ex":{"en":"the collapse of the Soviet Union","cn":"苏联的解体"},"pos":"noun"},{"en":"the action of a building suddenly falling","cn":"（突然的）倒塌，塌陷，垮掉","g":"[uncountable]","sc":"of building","ex":{"en":"The walls were strengthened to protect them from collapse.","cn":"围墙已加固以防倒塌。"},"pos":"noun"},{"en":"a medical condition when a person suddenly becomes very ill, or when somebody falls because they are ill or weak","cn":"病倒；（因病或体弱的）昏倒，晕倒","g":"[uncountable, countable, usually singular]","sc":"illness","ex":{"en":"a state of mental/nervous collapse","cn":"精神／神经的崩溃状态"},"pos":"noun"},{"en":"a sudden fall in value","cn":"突然降价；突然贬值；暴跌","g":"[countable, usually singular]","sc":"of prices/currencies","ex":{"en":"Shares suffered a fresh collapse today.","cn":"今天股票再次暴跌。"},"pos":"noun"}]}},"coroner":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"验尸官","en":"A coroner is an official who is responsible for investigating the deaths of people who have died in a sudden, violent, or unusual way.","ex":{"en":"The coroner recorded a verdict of accidental death.","cn":"验尸官作出了意外死亡的结论。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an official whose job is to discover the cause of someone’s death, especially if they died in a sudden or unusual way 〔","cn":"调查死因的〕验尸官"}]},"vocab":{"pos":"n","senses":[{"en":"A coroner is a scientist with a grim specialty: a coroner studies dead bodies and figures out the cause of death."}]},"collocations":{"phrases":["ADJ. deputy","CORONER + VERB issue sth The coroner issued a burial certificate. | order sth The coroner ordered an investigation into the man's death. | r","PHRASES a coroner's court/inquest, a coroner's report/verdict"]},"media":{"uk":"media/ldoce/hwd/bre/e/coroner0205.mp3","us":"media/ldoce/hwd/ame/c/coroner.mp3"},"examples":[{"en":"The coroner recorded a verdict of death by natural causes.","cn":"验尸官作出了自然死亡的结论。"},{"en":"the coroner’s court","cn":"死因裁判法庭"}],"oxford":{"phon":"ˈkɒrənə(r)","pos":"noun","senses":[{"en":"an official whose job is to discover the cause of any sudden, violent or suspicious death by holding an inquest","cn":"验尸官","ex":{"en":"The coroner issued a burial certificate.","cn":"验尸官出具了入殓证明书。"}}]}},"colonel":{"collins":{"senses":[{"pos":"N-COUNT; N-TITLE; N-VOC可数名词；头衔名词；称呼名词","cn":"(陆军、空军或海军陆战队的)上校","en":"A colonel is a senior officer in an army, air force, or the marines.","ex":{"en":"This particular place was run by an ex-Army colonel.","cn":"这个地方以前由一位前陆军上校经管。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a high rank in the army, Marines, or the US air force, or someone who has this rank 〔","cn":"陆军﹑海军陆战队或美国空军的〕上校军衔﹔上校"}]},"vocab":{"pos":"n","senses":[{"en":"A colonel is a commissioned military officer in the U.S. Army, Air Force, or Marines who ranks above a lieutenant colonel and below a brigadier general."}]},"media":{"uk":"media/ldoce/hwd/bre/c/colonel0205.mp3","us":"media/ldoce/hwd/ame/8/colonel.mp3"},"examples":[{"en":"Colonel Jim Edge","cn":"吉姆 · 埃奇上校"}],"oxford":{"phon":"ˈkɜːnl","pos":"noun","senses":[{"en":"an officer of high rank in the army, the marines, or the US air force","cn":"（陆军、海军陆战队或美国空军）上校","ex":{"en":"Colonel Jim Edge","cn":"吉姆·埃奇上校"}}]}},"contemplate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"考虑;思量;思忖","en":"If you contemplate an action, you think about whether to do it or not.","ex":{"en":"For a time he contemplated a career as an army medical doctor","cn":"有段时间，他考虑去当军医。"}},{"pos":"VERB 动词","cn":"深思熟虑;沉思;苦思冥想","en":"If you contemplate an idea or subject, you think about it carefully for a long time.","ex":{"en":"As he lay in his hospital bed that night, he cried as he contemplated his future","cn":"那天晚上，他躺在医院的病床上，想到未来，他哭了起来。"}},{"pos":"VERB 动词","cn":"凝视;注视","en":"If you contemplate something or someone, you look at them for a long time.","ex":{"en":"He contemplated his hands, still frowning.","cn":"他盯着自己的双手，眉头紧锁。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to use your mind to decide about something, form an opinion, imagine something etc","cn":""},{"en":"to think about something carefully before deciding what to do","cn":""},{"en":"to carefully think about a plan or choice by comparing all the advantages and disadvantages involved","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Before you accept a job offer, or a college's offer of admission, you should take time to contemplate the pros and cons of your decision. If you contemplate something, you think about it carefully."}]},"collocations":{"phrases":["ADV. seriously She was seriously contemplating working abroad.","VERB + CONTEMPLATE be prepared to, be willing to Are you prepared to contemplate retraining? | cannot, could not | refuse to","PHRASES too awful/horrible/horrific to contemplate The thought of war was too awful to contemplate."]},"media":{"uk":"media/ldoce/hwd/bre/f/contemplate0205.mp3","us":"media/ldoce/hwd/ame/1/contemplate.mp3"},"examples":[{"en":"He continued while she contemplated how to answer.","cn":"她还在考虑如何回答时，他就继续往下说了。"},{"en":"I can't contemplate what it would be like to be alone.","cn":"我不能想像独自一人会是个什么样子。"}],"oxford":{"phon":"ˈkɒntəmpleɪt","pos":"verb","senses":[{"en":"to think about whether you should do something, or how you should do something","cn":"考虑；思量；思忖","g":"[transitive]","ex":{"en":"You're too young to be contemplating retirement.","cn":"你考虑退休还太年轻。"}},{"en":"to think carefully about and accept the possibility of something happening","cn":"考虑接受（发生某事的可能性）","g":"[transitive]","ex":{"en":"The thought of war is too awful to contemplate.","cn":"战争太可怕了，真不敢去想。"}},{"en":"to think deeply about something for a long time","cn":"深思熟虑；沉思；苦思冥想","g":"[transitive, intransitive]","lab":"formal","ex":{"en":"to contemplate your future","cn":"仔细盘算未来"}},{"en":"to look at somebody/something in a careful way for a long time","cn":"端详；审视","g":"[transitive]","lab":"formal","ex":{"en":"She contemplated him in silence.","cn":"她默默地注视着他。"}}]}},"complacent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自满的;沾沾自喜的;满不在乎的","en":"A complacent person is very pleased with themselves or feels that they do not need to do anything about a situation, even though the situation may be uncertain or dangerous.","ex":{"en":"We cannot afford to be complacent about our health.","cn":"对于健康我们决不能掉以轻心。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"pleased with a situation, especially something you have achieved, so that you stop trying to improve or change things – used to show disapproval","cn":"自满的﹐得意的〔含贬义〕"}]},"vocab":{"pos":"adj","senses":[{"en":"Someone who is complacent has become overly content — the junk-food-eating couch potato might be feeling complacent about his health."}]},"collocations":{"phrases":["VERBS appear, be, seem, sound | become, get, grow","ADV. extremely, remarkably, very | far from Teachers are far from complacent about this problem. | rather, somewhat | alarmingly, dangerousl","PREP. about It is vital that we do not get complacent about this disease."]},"media":{"uk":"media/ldoce/hwd/bre/3/complacent0205.mp3","us":"media/ldoce/hwd/ame/5/complacent.mp3"},"examples":[{"en":"a dangerously complacent attitude to the increase in unemployment","cn":"对失业增加抱满不在乎的危险态度"},{"en":"We must not become complacent about progress.","cn":"我们决不能因进步变得自满。"}],"oxford":{"phon":"kəmˈpleɪsnt","pos":"adjective","senses":[{"en":"too satisfied with yourself or with a situation, so that you do not feel that any change is necessary; showing or feeling complacency","cn":"自满的；自鸣得意的；表现出自满的","ex":{"en":"a dangerously complacent attitude to the increase in unemployment","cn":"对失业增加抱满不在乎的危险态度"}}]}},"coil":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(绳子、金属丝等绕成的)卷，圈","en":"A coil of rope or wire is a length of it that has been wound into a series of loops.","ex":{"en":"Tod shook his head angrily and slung the coil of rope over his shoulder","cn":"托德气愤地摇了摇头，然后把那卷绳子往肩上一搭。"}},{"pos":"N-COUNT 可数名词","cn":"一卷;一圈","en":"A coil is one loop in a series of loops.","ex":{"en":"Pythons kill by tightening their coils so that their victim cannot breathe.","cn":"大蟒蛇紧紧盘绕猎物使之无法呼吸，从而杀死猎物。"}},{"pos":"N-COUNT 可数名词","cn":"(电路的)线圈","en":"A coil is a thick spiral of wire through which an electrical current passes."},{"pos":"N-COUNT 可数名词","cn":"(汽车发动机的)盘管","en":"In a vehicle, the coil is the part on a petrol engine that sends electricity to the spark plugs."},{"pos":"N-COUNT 可数名词","cn":"子宫节育环;避孕环","en":"The coil is a contraceptive device used by women. It is fitted inside a woman's womb, usually for several months or years."},{"pos":"V-ERG 及物/不及物动词","cn":"卷;盘绕","en":"If you coil something, you wind it into a series of loops or into the shape of a ring. If it coils around something, it forms loops or a ring.","ex":{"en":"He turned off the water and began to coil the hose","cn":"他关掉水龙头，开始盘水管。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something have a curved shape, or to fold something at an angle, by pushing or pressing it","cn":""},{"en":"to bend and turn something several times, such as a piece of wire, cloth, or rope, especially in order to tie it to something or make something with it","cn":""},{"en":"to wind or twist into a round shape, or to wind or twist something in this way","cn":""}]},"collocations":{"phrases":["ADV. tightly | loosely | neatly | up He coiled the rope up tightly and put it away.","PREP. around/round The snake coiled itself around a branch. | into Her hair was neatly coiled into a bun."]},"media":{"uk":"media/ldoce/hwd/bre/0/coil_v0205.mp3","us":"media/ldoce/hwd/ame/8/coil1.mp3","img":["media/thumb/coil.jpg"]},"examples":[{"en":"The snake coiled up, ready to strike.","cn":"那条蛇盘绕起来准备攻击。"},{"en":"Her hair was coiled on top of her head.","cn":"她把头发盘在头顶上。"}],"oxford":{"phon":"kɔɪl","pos":"verb","senses":[{"en":"to wind into a series of circles; to make something do this","cn":"（使）缠绕，盘绕","ex":{"en":"The snake coiled up, ready to strike.","cn":"那条蛇盘绕起来准备攻击。"}},{"en":"a series of circles formed by winding up a length of rope, wire, etc.","cn":"（绳索、金属线等的）圈，卷，盘","ex":{"en":"The device consisted of a coil of copper wire, connected at either end to two electrodes.","cn":"这个装置由一卷铜线组成，两端连接到两个电极上。"},"pos":"noun"},{"en":"one circle of rope, wire, etc. in a series","cn":"一圈（绳索、金属线等）","ex":{"en":"Shake the rope and let the coils unwind.","cn":"抖动绳索把绳圈展开。"},"pos":"noun"},{"en":"a length of wire, wound into circles, that can carry electricity","cn":"线圈；绕组","pos":"noun"},{"en":"an intrauterine device (= a small plastic or metal object placed inside a woman’s uterus to stop her becoming pregnant)","cn":"宫内节育器","pos":"noun"}]}},"corporal":{"collins":{"senses":[{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"(陆军或美国海军陆战队的)下士","en":"A corporal is a non-commissioned officer in the army or United States Marines.","ex":{"en":"The corporal shouted an order at the men.","cn":"下士向士兵们发出号令。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a low rank in the army, air force etc 〔","cn":"陆军﹑空军等的〕下士"}]},"vocab":{"pos":"1 adj 2 n","senses":[{"en":"Corporal means of the body. Corporal punishment involves hitting, spanking, and slapping — all types of bodily hurt. A corporal is also a noncommissioned officer in the Army, Air Force, and Marines."}]},"media":{"uk":"media/ldoce/hwd/bre/f/corporal0205.mp3","us":"media/ldoce/hwd/ame/c/corporal1.mp3"},"examples":[{"en":"Corporal Smith","cn":"史密斯下士"}],"oxford":{"phon":"ˈkɔːpərəl","pos":"noun","senses":[{"en":"a member of one of the lower ranks in the army, the marines or the British air force","cn":"（陆军、海军陆战队或英国空军的）下士","ex":{"en":"Corporal Smith","cn":"史密斯下士"}}]}},"compatible":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(系统、想法和信仰)兼容的，可以并存的","en":"If things, for example systems, ideas, and beliefs, are compatible, they work well together or can exist together successfully.","ex":{"en":"Free enterprise, he argued, was compatible with Russian values and traditions","cn":"他认为自由企业制并不违背俄罗斯的价值观和传统。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"能和谐相处的;合得来的","en":"If you say that you are compatible with someone, you mean that you have a good relationship with them because you have similar opinions and interests.","ex":{"en":"Mildred and I are very compatible. She's interested in the things that interest me","cn":"我和米尔德丽德很合得来，我感兴趣的东西她也感兴趣。"}},{"pos":"ADJ 形容词","cn":"(尤指与 IBM公司制造的计算机或计算机设备)兼容的","en":"If one make of computer or computer equipment is compatible with another make, especially IBM, they can be used together and can use the same software."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"able to have a very good relationship with each other, because you have characters, interests, qualities etc that go well together","cn":""},{"en":"if two people are well-matched or well-suited , they are suitable for each other because they agree about most things, like and dislike the same things etc","cn":""},{"en":"if two people are made for each other , they are naturally very suitable for each other","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"A word that comes up a lot in discussions of both food and people pairings, compatible speaks to a person or thing’s ability to exist agreeably with something or someone else."}]},"collocations":{"phrases":["VERBS be, seem","ADV. highly, very | entirely, fully, perfectly, quite, totally, wholly three different, yet entirely compatible programs | directly | hardly","PREP. with The theory does not seem compatible with his other ideas."]},"media":{"uk":"media/ldoce/hwd/bre/d/compatible_adj0205.mp3","us":"media/ldoce/hwd/ame/e/compatible1.mp3"},"examples":[{"en":"Are measures to protect the environment compatible with economic growth?","cn":"保护环境的措施与经济的增长协调吗？"},{"en":"The new system will be compatible with existing equipment.","cn":"新的系统将与现有的设备相互兼容。"}],"oxford":{"phon":"kəmˈpætəbl","pos":"adjective","senses":[{"en":"able to be used together","cn":"兼容的；可共用的","ex":{"en":"The new system will be compatible with existing equipment.","cn":"新的系统将与现有的设备相互兼容。"}},{"en":"able to exist or be used together without causing problems","cn":"可共存的；可共用的；兼容的","ex":{"en":"Are measures to protect the environment compatible with economic growth?","cn":"保护环境的措施与经济的增长协调吗？"}},{"en":"if two people are compatible, they can have a good relationship because they have similar ideas, interests, etc.","cn":"（因思想、志趣等相投而）关系好的，和睦相处的","ex":{"en":"She found a compatible partner through a computer dating agency.","cn":"她通过电脑约会机构找到了一个兼容的伴侣。"}}]}},"coexist":{"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"同时存在;共存","en":"If one thing coexists with another, they exist together at the same time or in the same place. You can also say that two things coexist .","ex":{"en":"Pockets of affluence coexist with poverty","cn":"少数富裕地区与贫困地区并存。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if two different things coexist, they exist at the same time or in the same place","cn":"共存﹐共处"}]},"vocab":{"pos":"v","senses":[{"en":"To coexist is to live in the same place or at the same time. If you, your roommate, and a cat all live in an apartment together, you can say the three of you coexist ."}]},"collocations":{"phrases":["ADV. peacefully What makes it difficult for the communities to coexist peacefully?","PREP. alongside/with Modern farming methods coexist with more traditional practices."]},"media":{"uk":"media/ldoce/hwd/bre/6/coexist0205.mp3","us":"media/ldoce/hwd/ame/e/coexist.mp3"},"examples":[{"en":"English speakers now coexist peacefully with their Spanish-speaking neighbours.","cn":"讲英语的人现在与他们讲西班牙语的邻居和睦相处。"},{"en":"The illness frequently coexists with other chronic diseases.","cn":"这种病往往与其他慢性病同时存在。"}],"oxford":{"phon":"ˌkəʊɪɡˈzɪst","pos":"verb","senses":[{"en":"to exist together in the same place or at the same time, especially in a peaceful way","cn":"共存；（尤指）和平共处","ex":{"en":"The illness frequently coexists with other chronic diseases.","cn":"这种病往往与其他慢性病同时存在。"}}]}},"concur":{"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"意见一致;同意","en":"If one person concurs with another person, the two people agree. You can also say that two people concur .","ex":{"en":"Local feeling does not necessarily concur with the press","cn":"当地人的感受未必与媒体一致。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to have the same opinion as someone, or to think that a statement is correct","cn":""},{"en":"if people are in agreement, they agree with each other, especially after discussing something","cn":""},{"en":"to have the same opinion as someone, especially about an important issue","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To concur is to agree or approve of something. If someone says something you agree with, you can say \"I concur !\""}]},"collocations":{"phrases":["ADV. strongly I strongly concur with that idea. | entirely, fully","PREP. in, with Historians have concurred with each other in this view."]},"media":{"uk":"media/ldoce/hwd/bre/c/concur0205.mp3","us":"media/ldoce/hwd/ame/c/concur.mp3"},"examples":[{"en":"Historians have concurred with each other in this view.","cn":"历史学家在这个观点上已取得一致意见。"},{"en":"The coroner concurred with this assessment.","cn":"验尸官同意这个鉴定。"}],"oxford":{"phon":"kənˈkɜː(r)","pos":"verb","senses":[{"en":"to agree","cn":"同意；赞同","ex":{"en":"Historians have concurred with each other in this view.","cn":"历史学家在这个观点上已取得一致意见。"}}]}},"condom":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"安全套;避孕套","en":"A condom is a covering made of thin rubber which a man can wear on his penis as a contraceptive or as protection against disease during sexual intercourse."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a thin rubber bag that a man wears over his penis (= sex organ ) during sex, to prevent a woman having a baby or to protect against disease","cn":"保险套﹐避孕套"}]},"collocations":{"phrases":["QUANT. packet","VERB + CONDOM unroll | put on, use, wear"]},"media":{"uk":"media/ldoce/hwd/bre/8/condom0205.mp3","us":"media/ldoce/hwd/ame/a/condom.mp3"},"oxford":{"phon":"ˈkɒndɒm","pos":"noun","senses":[{"en":"a thin rubber tube that a man wears over his penis during sex to stop a woman from becoming pregnant or to protect against disease","cn":"（男用）避孕套，保险套，安全套","lab":"British English also"},{"en":"a thin rubber device that a woman wears inside her vagina during sex to prevent herself from becoming pregnant","cn":"（女用）避孕套"}]}},"corrupt":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"腐败的;贪污的;受贿的;营私舞弊的","en":"Someone who is corrupt behaves in a way that is morally wrong, especially by doing dishonest or illegal things in return for money or power.","ex":{"en":"...to save the nation from corrupt politicians of both parties","cn":"从两个政党的腐败政客手中挽救这个国家"}},{"pos":"VERB 动词","cn":"使腐化","en":"If someone is corrupted by something, it causes them to become dishonest and unjust and unable to be trusted.","ex":{"en":"It is sad to see a man so corrupted by the desire for money and power.","cn":"看到一个人因为追逐金钱和权力而如此腐化真是悲哀。"}},{"pos":"VERB 动词","cn":"使堕落","en":"To corrupt someone means to cause them to stop caring about moral standards.","ex":{"en":"...warning that television will corrupt us all","cn":"警告说电视将会使我们所有人堕落"}},{"pos":"VERB 动词","cn":"损坏;破坏","en":"If something is corrupted, it becomes damaged or spoiled in some way.","ex":{"en":"Some of the finer typefaces are corrupted by cheap, popular computer printers","cn":"有些比较优美的字体经过价廉、通用的电脑打印机处理后就面目全非了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving in a way that is intended to deceive people, for example by lying, cheating, or stealing","cn":""},{"en":"using your power in a dishonest way for your own advantage – used about people in official positions","cn":""},{"en":"good at secretly thinking of clever plans to trick people in order to get what you want","cn":""}]},"vocab":{"pos":"1 adj v 2 v 3 adj v","senses":[{"en":"If someone or something is corrupt, they’re broken morally or in some other way. Corrupt people perform immoral or illegal acts for personal gain, without apology. Corrupt politicians take bribes and deny it."}]},"collocations":{"phrases":["VERBS be | become","ADV. thoroughly, totally The whole regime is thoroughly corrupt. | notoriously one of the most notoriously corrupt city councils | morally, "]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdecorrupt.mp3","us":"media/ldoce/hwd/ame/2/l3corrupt.mp3"},"examples":[{"en":"The program has somehow corrupted the system files.","cn":"这程序莫名其妙地导致系统文件出错了。"},{"en":"The whole system is inefficient and corrupt.","cn":"整个体系都效率低下并且腐败堕落。"}],"oxford":{"phon":"kəˈrʌpt","pos":"adjective","senses":[{"en":"willing to use their power to do dishonest or illegal things in return for money or to get an advantage","cn":"贪污的；受贿的；腐败的；营私舞弊的","ex":{"en":"It was seen as the only way to overthrow a corrupt regime.","cn":"这被视为推翻腐败政权的唯一方法。"}},{"en":"not honest or moral","cn":"不诚实的；不道德的","ex":{"en":"They had been engaged in corrupt practices.","cn":"他们曾从事腐败行为。"}},{"en":"containing changes or faults, and no longer in the original state","cn":"已变换的；有缺陷的；有错误的","lab":"computing","ex":{"en":"corrupt software","cn":"已受损的软件"}},{"en":"to have a bad effect on somebody and make them behave in a way that is not honest or moral","cn":"使腐化；使堕落","g":"[transitive, intransitive]","ex":{"en":"He was corrupted by power and ambition.","cn":"权力与野心使他腐化堕落。"},"pos":"verb"},{"en":"to change the original form of something, so that it is damaged or made less good in some way","cn":"破坏；损坏","g":"[transitive, often passive]","ex":{"en":"a corrupted form of Buddhism","cn":"一种蜕变了的佛教"},"pos":"verb"},{"en":"to cause mistakes to appear in a computer file, etc. with the result that the information in it is no longer correct; (of a computer file, etc.) to start containing mistakes","cn":"引起（计算机文件等的）错误；损坏；出错","g":"[transitive, intransitive]","lab":"computing","ex":{"en":"The program has somehow corrupted the system files.","cn":"这程序莫名其妙地导致系统文件出错了。"},"pos":"verb"}]}},"corpse":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指人的)尸体","en":"A corpse is a dead body, especially the body of a human being."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the dead body of a person","cn":"尸体"},{"en":"the dead body of a person. Corpse is is used when you are thinking about the body as an object rather than a person","cn":""},{"en":"the dead body of an animal","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Another name for a dead body is corpse . You might hear it on TV crime shows, but a corpse doesn't have to be a crime victim, just any lifeless body."}]},"collocations":{"phrases":["ADJ. human | naked | bloody, headless, mutilated | decaying, desiccated, rotting We passed the desiccated corpse of a brigand hanging on a g","VERB + CORPSE lay out The corpse had been laid out on a marble slab. | embalm | butcher, dismember, eviscerate, mutilate","CORPSE + VERB be sprawled, lie, sprawl They saw the corpse sprawled on the steps.","PHRASES be littered/strewn with corpses The ground was littered with the corpses of enemy soldiers."]},"media":{"uk":"media/ldoce/hwd/bre/a/corpse0205.mp3","us":"media/ldoce/hwd/ame/e/corpse.mp3"},"examples":[{"en":"The corpse was found by children playing in the woods.","cn":"这具尸体是在林子里玩耍的孩子发现的。"}],"oxford":{"phon":"kɔːps","pos":"noun","senses":[{"en":"a dead body, especially of a human","cn":"尸体；（尤指人的）死尸，尸首","ex":{"en":"The corpse was barely recognizable.","cn":"这具尸体几乎无从辨认。"}}]}},"congestion":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"堵塞;拥堵","en":"If there is congestion in a place, the place is extremely crowded and blocked with traffic or people.","ex":{"en":"The problems of traffic congestion will not disappear in a hurry","cn":"交通拥堵问题不会一下子就消失。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(身体部位的)堵塞，充血，淤血","en":"Congestion in a part of the body is a medical condition in which the part becomes blocked.","ex":{"en":"...nasal congestion.","cn":"鼻塞"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the problem of too much traffic in a place","cn":"交通拥挤，堵车"},{"en":"the condition of part of your body being very full of liquid, usually blood or mucus 〔","cn":"身体部位〕充液〔一般指充血或充满黏液〕"}]},"vocab":{"pos":"n","senses":[{"en":"When a driver complains about congestion , she's talking about the cars that are backed up on the highway. When your sneezing friend complains about congestion , he's talking about his stuffed-up nose."}]},"collocations":{"phrases":["ADJ. serious, severe | increased, increasing | road, traffic Parking near the school causes severe traffic congestion. | nasal","VERB + CONGESTION cause, lead to | avoid, ease, reduce, relieve measures to ease the increasing congestion in the centre of London | increas"]},"media":{"uk":"media/ldoce/hwd/bre/4/ldoce6congestion.mp3","us":"media/ldoce/hwd/ame/0/congestion_am.mp3"},"examples":[{"en":"traffic congestion and pollution","cn":"交通拥塞和污染"},{"en":"medicine to relieve nasal congestion","cn":"治疗鼻塞的药"}],"oxford":{"phon":"kənˈdʒestʃən","pos":"noun","senses":[{"en":"the state of being crowded and full of traffic","cn":"（交通）拥塞；塞车","lab":"especially North American English","ex":{"en":"traffic congestion and pollution","cn":"交通拥塞和污染"}},{"en":"the state of part of the body being blocked with blood or mucus","cn":"充血；淤血；黏液阻塞","lab":"medical","ex":{"en":"congestion of the lungs","cn":"肺淤血"}}]}},"condemn":{"collins":{"senses":[{"pos":"VERB 动词","cn":"谴责；指责","en":"If you condemn something, you say that it is very bad and unacceptable.","ex":{"en":"Political leaders united yesterday to condemn the latest wave of violence","cn":"政界领袖昨日联合起来对最近激增的暴力事件予以谴责。"}},{"pos":"VERB 动词","cn":"宣判;判处(某人刑罚)","en":"If someone is condemned to a punishment, they are given this punishment.","ex":{"en":"He was condemned to life imprisonment.","cn":"他被判终身监禁。"}},{"pos":"VERB 动词","cn":"使陷入(不愉快的境地)","en":"If circumstances condemn you to an unpleasant situation, they make it certain that you will suffer in that way.","ex":{"en":"Their lack of qualifications condemned them to a lifetime of boring, usually poorly-paid work","cn":"没有学历使他们一辈子都得从事枯燥乏味而且通常报酬很低的工作。"}},{"pos":"VERB 动词","cn":"正式宣布(建筑)不安全","en":"If authorities condemn a building, they officially decide that it is not safe and must be pulled down or repaired.","ex":{"en":"State officials said the court's ruling clears the way for proceedings to condemn buildings in the area.","cn":"州政府官员称法庭判决为宣布该地区楼房为危房的行动扫清了道路。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say what you think is bad about someone or something","cn":""},{"en":"to criticize someone or something, especially by giving detailed reasons for this","cn":""},{"en":"to criticize someone or something very strongly, especially publicly in the newspapers, on TV etc","cn":""}]},"vocab":{"pos":"1 v 2 v 3 v 4 v 5 v","senses":[{"en":"You can condemn , or openly criticize, someone who is behaving inappropriately. If you are an animal rights activist, you would probably condemn someone for wearing fur."}]},"collocations":{"phrases":["ADV. fiercely, roundly, strongly, vehemently, vigorously, vociferously | unequivocally, utterly | unanimously, universally | openly, publicl","PREP. for He was roundly condemned for his mistake.","PHRASES be widely condemned The action has been widely condemned by human rights groups."]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdecondemn.mp3","us":"media/ldoce/hwd/ame/d/condemn.mp3"},"examples":[{"en":"They were condemned to spend every holiday on a rainy campsite.","cn":"他们得在阴雨连绵的野营地度过每一个假日，徒叹奈何。"},{"en":"The editor of the newspaper was condemned as lacking integrity.","cn":"这家报纸的编辑被指责为缺乏操守。"}],"oxford":{"phon":"kənˈdem","pos":"verb","senses":[{"en":"to say very strongly that you think something is bad, usually for moral reasons","cn":"（通常出于道义而）谴责，指责","sc":"say something is bad","ex":{"en":"The government issued a statement condemning the killings.","cn":"政府发表声明谴责这些凶杀事件。"}},{"en":"to say what somebody’s punishment will be","cn":"宣判；判处（某人某种刑罚）","g":"[usually passive]","sc":"somebody to punishment","ex":{"en":"He was condemned to death for murder and later hanged.","cn":"他因谋杀罪被判处死刑后被绞死了。"}},{"en":"to force somebody to accept a difficult or unpleasant situation","cn":"迫使…接受困境（或不愉快的状况）","g":"[usually passive]","sc":"somebody to difficult situation","ex":{"en":"He was condemned to a life of hardship.","cn":"他不得不过苦日子。"}},{"en":"to say officially that something is not safe enough to be used","cn":"宣告使用…不安全","g":"[usually passive]","sc":"something dangerous","ex":{"en":"The meat was condemned as unfit to eat.","cn":"这种肉被宣告不宜食用。"}},{"en":"to show or suggest that somebody is guilty of something","cn":"证明（或表明）有罪","sc":"show guilt","ex":{"en":"She is condemned out of her own mouth (= her own words show that she is guilty).","cn":"她自己说的话显示她有罪责。"}}]}},"congregation":{"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"教堂会众","en":"The people who are attending a church service or who regularly attend a church service are referred to as the congregation .","ex":{"en":"Most members of the congregation begin arriving a few minutes before services.","cn":"礼拜仪式开始前几分钟，大部分教堂会众陆续到来。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of people gathered together in a church","cn":"会众〔在教堂里聚集的人群〕"},{"en":"the people who usually go to a particular church","cn":"会众〔通常去某教堂做礼拜的人群〕"}]},"vocab":{"pos":"n","senses":[{"en":"Although the word is most usually assigned to the members of a church, any gathering might be called a congregation , including a gathering of animals. Come to think of it, a congregation of church members is often called a \"flock.\""}]},"collocations":{"phrases":["ADJ. full | large | small","VERB + CONGREGATION address The vicar stood up to address the congregation.","PREP. in a/the ~","PHRASES a member of a congregation"]},"media":{"uk":"media/ldoce/hwd/bre/3/congregation0205.mp3","us":"media/ldoce/hwd/ame/0/congregation.mp3"},"examples":[{"en":"The congregation stood to sing the hymn.","cn":"会众站起来唱圣歌。"},{"en":"The congregation knelt to pray.","cn":"会众跪下祈祷。"}],"oxford":{"phon":"ˌkɒŋɡrɪˈɡeɪʃn","pos":"noun","senses":[{"en":"a group of people who are gathered together in a church for a religious service, not including the priest and choir","cn":"（教堂的）会众","lab":"North American English","ex":{"en":"The congregation stood to sing the hymn.","cn":"会众站起来唱圣歌。"}},{"en":"a group of people who regularly attend a particular church","cn":"（定期去特定地方做礼拜的）会众","ex":{"en":"members of local congregations","cn":"地方教堂会众"}},{"en":"a group or collection of people, animals or things","cn":"会众：一群人，动物或事物的集合","lab":"formal","ex":{"en":"Large congregations of birds may cause public harm.","cn":"庞大的鸟群可能会成为公害。"}}]}},"connoisseur":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(艺术、食品、酒等的)鉴赏家，鉴定家，行家","en":"A connoisseur is someone who knows a lot about the arts, food, drink, or some other subject.","ex":{"en":"Sarah tells me you're something of an art connoisseur.","cn":"萨拉告诉我你是一位艺术鉴赏家。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has a lot of knowledge about something or skill at doing something","cn":""},{"en":"an expert who has studied a particular medical or technical subject for a long time and knows much more about it than other people","cn":""},{"en":"an expert whose knowledge and opinions are greatly respected","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A connoisseur is a person who, through study and interest, has a fine appreciation for something, like the connoisseur who can identify the clarinet player on a jazz recording by the sound of his inhalations alone."}]},"collocations":{"phrases":["ADJ. great, real Only the real connoisseur could tell the difference between these two wines. | art, music, wine","PREP. ~ of a great connoisseur of Japanese art"]},"media":{"uk":"media/ldoce/hwd/bre/8/connoisseur0205.mp3","us":"media/ldoce/hwd/ame/c/connoisseur.mp3"},"examples":[{"en":"a connoisseur of Italian painting","cn":"意大利绘画鉴赏家"},{"en":"a wine connoisseur","cn":"葡萄酒鉴定家"}],"oxford":{"phon":"ˌkɒnəˈsɜː(r)","pos":"noun","senses":[{"en":"an expert on matters involving the judgement of beauty, quality or skill in art, food or music","cn":"鉴赏家；鉴定家；行家","ex":{"en":"a connoisseur of Italian painting","cn":"意大利绘画鉴赏家"}}]}},"collide":{"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"碰撞;相撞;撞上","en":"If two or more moving people or objects collide, they crash into one another. If a moving person or object collides with a person or object that is not moving, they crash into them.","ex":{"en":"Two trains collided head-on in north-eastern Germany early this morning","cn":"今天早上德国东北部两列火车迎面相撞。"}},{"pos":"V-RECIP 相互动词","cn":"(目标、意见等)冲突，抵触","en":"If the aims, opinions, or interests of one person or group collide with those of another person or group, they are very different from each other and are therefore opposed.","ex":{"en":"The aims of the negotiators in New York again seem likely to collide with the aims of the warriors in the field","cn":"看来，纽约谈判人员的目标可能会再次与战场上勇士们的目标发生冲突。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to hit another vehicle, a tree, the ground etc, with a lot of force, causing a lot of damage","cn":""},{"en":"to move into something quickly and with force","cn":""},{"en":"if two cars, trains, planes etc collide, they hit each other, especially when they are moving in opposite directions","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"It could be protons bouncing around in a particle accelerator, two cars failing to stop at an intersection, or the priorities of two people with very different goals. When things crash together, they collide ."}]},"collocations":{"phrases":["ADV. nearly | head-on Two trains collided head-on.","PREP. with His car nearly collided with a bus."]},"media":{"uk":"media/ldoce/hwd/bre/d/collide0205.mp3","us":"media/ldoce/hwd/ame/c/collide.mp3"},"examples":[{"en":"The car and the van collided head-on in thick fog.","cn":"那辆小轿车和货车在浓雾中迎面相撞。"},{"en":"They regularly collide over policy decisions.","cn":"他们经常在政策决策上发生冲突。"}],"oxford":{"phon":"kəˈlaɪd","pos":"verb","senses":[{"en":"if two people, vehicles, etc. collide, they crash into each other; if a person, vehicle, etc. collides with another, or with something that is not moving, they crash into it","cn":"碰撞；相撞","g":"[intransitive]","ex":{"en":"The car and the van collided head-on in thick fog.","cn":"那辆小轿车和货车在浓雾中迎面相撞。"}},{"en":"to disagree strongly","cn":"严重不一致；冲突；抵触","g":"[intransitive]","lab":"formal","ex":{"en":"They regularly collide over policy decisions.","cn":"他们经常在政策决策上发生冲突。"}}]}},"conceive":{"collins":{"senses":[{"pos":"VERB 动词","cn":"想象;相信","en":"If you cannot conceive of something, you cannot imagine it or believe it.","ex":{"en":"I just can't even conceive of that quantity of money","cn":"那么多钱，我根本都无法想象。"}},{"pos":"VERB 动词","cn":"认为","en":"If you conceive something as a particular thing, you consider it to be that thing.","ex":{"en":"The ancients conceived the earth as afloat in water","cn":"古人认为地球飘浮在水里。"}},{"pos":"VERB 动词","cn":"构思;设想;想出","en":"If you conceive a plan or idea, you think of it and work out how it can be done.","ex":{"en":"She had conceived the idea of a series of novels","cn":"她萌生出撰写系列小说的想法。"}},{"pos":"VERB 动词","cn":"怀孕","en":"When a woman conceives, she becomes pregnant.","ex":{"en":"Women, he says, should give up alcohol before they plan to conceive","cn":"他说女性在计划怀孕之前应该戒酒。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to think of an idea for a new product, machine etc, and design it or make it","cn":""},{"en":"to make or design something new and original","cn":""},{"en":"to produce a new idea, plan, method, excuse etc by thinking","cn":""}]},"vocab":{"pos":"1 v 2 v 3 v","senses":[{"en":"To conceive is to become pregnant or to come up with an idea. Both imply planting a seed for something, either a baby or a thought. \"When his wife became pregnant, he could imagine the blue nursery right away, but she would conceive of something different: a pink one.\""}]},"collocations":{"phrases":["ADV. brilliantly, carefully The plan was brilliantly conceived. | poorly | broadly The course is very broadly conceived (= it covers a wide ","VERB + CONCEIVE can't/cannot I cannot conceive why you paid out so much money. | be difficult to, be impossible to It is difficult to concei","PREP. of We conceive of ourselves as individuals. 2 become pregnant","ADV. naturally She was unable to conceive a child naturally and was offered fertility treatment.","VERB + CONCEIVE be able/unable to"]},"media":{"uk":"media/ldoce/hwd/bre/8/conceive0205.mp3","us":"media/ldoce/hwd/ame/c/conceive.mp3"},"examples":[{"en":"He conceived the idea of transforming the old power station into an arts centre.","cn":"他想出了把旧发电站改造为艺术中心的主意。"},{"en":"Their first child was conceived on their wedding night.","cn":"他们的第一个小孩是在新婚之夜怀上的。"}],"oxford":{"phon":"kənˈsiːv","pos":"verb","senses":[{"en":"to form an idea, a plan, etc. in your mind","cn":"想出（主意、计划等）；构想；设想","g":"[transitive]","lab":"formal","ex":{"en":"He conceived the idea of transforming the old power station into an arts centre.","cn":"他想出了把旧发电站改造为艺术中心的主意。"}},{"en":"to imagine something","cn":"想象；幻想","g":"[transitive]","lab":"formal","ex":{"en":"God is often conceived of as male.","cn":"上帝常常被想象为男性。"}},{"en":"when a woman conceives or conceives a child, she becomes pregnant","cn":"怀孕；怀胎","g":"[intransitive, transitive]","ex":{"en":"She is unable to conceive.","cn":"她不能怀孕。"}}]}},"congested":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（道路或区域）交通阻塞的，拥堵的","en":"A congested road or area is extremely crowded and blocked with traffic or people.","ex":{"en":"He first promised two weeks ago to clear Britain's congested roads","cn":"他在两周前首次承诺解决英国道路拥堵的问题。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(身体部位)堵塞的，充血的，淤血的","en":"If a part of the body is congested, it is blocked.","ex":{"en":"The arteries in his neck had become fatally congested.","cn":"他颈动脉栓塞，危在旦夕。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"full of traffic","cn":"交通拥挤的﹐车辆阻塞的"},{"en":"a part of your body that is congested is very full of liquid, usually blood or mucus 〔","cn":"身体某部位〕充血的﹐黏液阻塞的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you are having trouble breathing, you keep sneezing, and your head feels like it might explode, you may very well be congested . In other words, fluid may have built up in your sinuses and your lungs."}]},"collocations":{"phrases":["VERBS be | become, get","ADV. heavily, highly, severely, very The roads to Bordeaux were heavily congested.","PREP. with The city streets were congested with vehicles."]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdecongested.mp3","us":"media/ldoce/hwd/ame/5/congested.mp3"},"examples":[{"en":"Many of Europe's airports are heavily congested.","cn":"欧洲许多机场都十分拥挤。"},{"en":"congested city streets","cn":"交通拥塞的城市街道"}],"oxford":{"phon":"kənˈdʒestɪd","pos":"adjective","senses":[{"en":"crowded; full of traffic","cn":"拥挤的；挤满的；（交通）堵塞的","ex":{"en":"congested city streets","cn":"交通拥塞的城市街道"}},{"en":"blocked with blood or mucus","cn":"充血的；黏液阻塞的","lab":"medical"}]}},"confetti":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(婚礼上向新娘、新郎抛撒的)五彩纸屑","en":"Confetti is small pieces of coloured paper that people throw over the bride and bridegroom at a wedding."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"small pieces of coloured paper that you throw into the air over people who have just got married or at events such as parties, parade s etc 〔","cn":"婚礼﹑聚会或游行等时抛撒的〕五彩纸屑"}]},"collocations":{"phrases":["QUANT. shower","VERB + CONFETTI shower (sb with), throw The winning team was showered with confetti.","CONFETTI + VERB shower down Confetti showered down on the newly-weds."]},"media":{"uk":"media/ldoce/hwd/bre/b/confetti0205.mp3","us":"media/ldoce/hwd/ame/9/confetti.mp3"},"oxford":{"phon":"kənˈfeti","pos":"noun","senses":[{"en":"small pieces of coloured paper that people often throw at weddings over people who have just been married, or (in the US) at other special events","cn":"（在婚礼或美国其他特殊活动中撒的）五彩纸屑","ex":{"en":"Confetti showered down on the newly-weds.","cn":"彩屑洒在一双新人身上。"}}]}},"confinement":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"监禁;关押;禁闭","en":"Confinement is the state of being forced to stay in a prison or another place which you cannot leave.","ex":{"en":"She had been held in solitary confinement for four months","cn":"她被单独关押了4个月。"}},{"pos":"N-VAR 可变名词","cn":"分娩;生产","en":"A woman's confinement is the period of time just before and during which she gives birth to a child.","ex":{"en":"There has been a movement to support women seeking home confinement.","cn":"一场支持女性在家分娩的运动一直在进行。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if someone who the police think is guilty of a crime is in custody , they are kept in prison until it is time for them to be judged in a court","cn":""},{"en":"if someone is under arrest , the police are keeping them guarded because they think they are guilty of a crime","cn":""},{"en":"when someone is being forced to stay in a place where they do not want to be - use this when this situation is illegal or wrong","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"If you're dealing with confinement to a jail cell, or your classroom, or the broom closet, you're stuck there and you can't leave. Confinement means you're being held and you can't move freely."}]},"collocations":{"phrases":["ADJ. close The animals are kept in close confinement. | solitary","VERB + CONFINEMENT be held in, be kept in | be placed in, be put in","PREP. in ~ He spent eleven years in solitary confinement. | ~ to their confinement to army barracks"]},"media":{"uk":"media/ldoce/hwd/bre/c/confinement0205.mp3","us":"media/ldoce/hwd/ame/f/confinement.mp3"},"examples":[{"en":"years of confinement as a political prisoner","cn":"作为政治犯被监禁的岁月"},{"en":"her confinement to a wheelchair","cn":"半步离不开轮椅对她的束缚"}],"oxford":{"phon":"kənˈfaɪnmənt","pos":"noun","senses":[{"en":"the state of being forced to stay in a closed space, prison, etc.; the act of putting somebody there","cn":"禁闭；监禁；关押","g":"[uncountable]","ex":{"en":"her confinement to a wheelchair","cn":"半步离不开轮椅对她的束缚"}},{"en":"the time when a woman gives birth to a baby","cn":"分娩；产期","g":"[uncountable, countable]","lab":"formal or old-fashioned","ex":{"en":"the expected date of confinement","cn":"预产期"}}]}},"complicate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使难以理解；使复杂化","en":"To complicate something means to make it more difficult to understand or deal with.","ex":{"en":"What complicates the issue is the burden of history","cn":"历史的重负使问题复杂化了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a situation worse or harder to deal with","cn":""},{"en":"to make a situation, problem etc more difficult by making it more complicated","cn":""},{"en":"to make a problem or situation more difficult","cn":"使更复杂"}]},"vocab":{"pos":"v","senses":[{"en":"To complicate things is to make them more complex, confusing, or difficult. So if you've already accepted two party invitations for Saturday night, don't complicate the situation by accepting a third."}]},"collocations":{"phrases":["ADV. enormously, greatly These events will greatly complicate the situation. | further","PHRASES be complicated by the fact that The issue is complicated by the fact that a vital document is missing."]},"media":{"uk":"media/ldoce/hwd/bre/d/complicate0205.mp3","us":"media/ldoce/hwd/ame/8/complicate.mp3"},"examples":[{"en":"To complicate matters further, there will be no transport available till 8 o'clock.","cn":"使事情更难办的是 8 点钟之前不会有交通工具。"},{"en":"The issue is complicated by the fact that a vital document is missing.","cn":"一份重要文件的丢失使这个问题复杂化了。"}],"oxford":{"phon":"ˈkɒmplɪkeɪt","pos":"verb","senses":[{"en":"to make something more difficult to do, understand or deal with","cn":"使复杂化","ex":{"en":"I do not wish to complicate the task more than is necessary.","cn":"我不想使这项任务不必要地复杂化。"}}]}},"coincidental":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"巧合的;碰巧的","en":"Something that is coincidental is the result of a coincidence and has not been deliberately arranged.","ex":{"en":"Any resemblance to actual persons, places or events is purely coincidental","cn":"如与真人、真实地点或真实事件有雷同之处，纯属巧合。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"happening completely by chance without being planned","cn":"巧合的﹐碰巧的"},{"en":"→ coincidence purely/completely/entirely coincidental Any similarity between this film and real events is purely coincidental.","cn":"本片如与真实事件有任何雷同纯属巧合。"}]},"vocab":{"pos":"adj","senses":[{"en":"Things that are coincidental take place at the same time, but there isn't any connection. It's just chance — a coincidence."}]},"collocations":{"phrases":["VERBS be","ADV. entirely, merely, purely, quite These parallels cannot be merely coincidental. | largely"]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41coincidental.mp3","us":"media/ldoce/hwd/ame/7/coincidental.mp3"},"examples":[{"en":"It's purely coincidental that we both chose to call our daughters Emma.","cn":"我们俩都给自己的女儿取名叫埃玛，这完全是巧合。"},{"en":"I suppose your presence here today is not entirely coincidental.","cn":"我认为你今天来这里不完全是碰巧。"}],"oxford":{"phon":"kəʊˌɪnsɪˈdentl","pos":"adjective","senses":[{"en":"happening by chance; not planned","cn":"巧合；碰巧；非计划之中","ex":{"en":"I suppose your presence here today is not entirely coincidental.","cn":"我认为你今天来这里不完全是碰巧。"}}]}},"colander":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(淘洗食物用的)滤器，漏勺","en":"A colander is a container in the shape of a bowl with holes in it which you wash or drain food in."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a metal or plastic bowl with a lot of small holes in the bottom and sides, used to separate liquid from food","cn":"滤盆﹐滤器"}]},"vocab":{"pos":"n","senses":[{"en":"Most cooks would agree that a colander is an essential piece of equipment for even the most basic kitchen. It's a bowl, usually made of plastic or metal, with holes in it to allow liquid to drain away from the food."}]},"media":{"img":["media/ldoce/img/colander.jpg","media/thumb/colander.jpg"],"uk":"media/ldoce/hwd/bre/f/colander0205.mp3","us":"media/ldoce/hwd/ame/b/colander.mp3"},"oxford":{"phon":"ˈkʌləndə(r)","pos":"noun","senses":[{"en":"a metal or plastic bowl with a lot of small holes in it, used for draining water from vegetables, etc. after washing or cooking","cn":"滤器；滤锅"}]}},"concluding":{"lemma":"conclude","media":{"uk":"media/ldoce/hwd/bre/8/concluding0205.mp3","us":"media/ldoce/hwd/ame/a/laadconcluding.mp3"}},"controlling":{"lemma":"control","media":{"uk":"media/ldoce/hwd/bre/0/ld5_controlling.mp3","us":"media/ldoce/hwd/ame/1/controlling_adj.mp3"}},"conceptualization":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to form an idea","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41conceptualize.mp3","us":"media/ldoce/hwd/ame/4/conceptualize.mp3"},"examples":[{"en":"How do older people conceptualize their health?","cn":""}]},"continuing":{"lemma":"continue"},"cosmetics":{"lemma":"cosmetic","media":{"uk":"media/ldoce/hwd/bre/3/cosmetics0205.mp3","us":"media/ldoce/hwd/ame/6/laadcosmetics.mp3"}},"compact":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"小而紧凑的","en":"Compact things are small or take up very little space. You use this word when you think this is a good quality.","ex":{"en":"...my compact office in Washington.","cn":"我在华盛顿小而紧凑的办公室"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"矮小结实的;矮壮的","en":"A compact person is small but strong.","ex":{"en":"He was compact, probably no taller than me","cn":"他矮小壮实，可能并不比我高。"}},{"pos":"ADJ 形容词","cn":"小巧的;袖珍的","en":"A compact cassette, camera, or car is a small type of cassette, camera, or car."},{"pos":"VERB 动词","cn":"把…压实(或压紧)","en":"To compact something means to press it so that it becomes more solid.","ex":{"en":"The Smith boy was compacting the trash","cn":"史密斯家的男孩在把垃圾压紧。"}},{"pos":"N-COUNT 可数名词","cn":"(内有镜子的)化妆粉盒","en":"A compact is a small, flat case that contains face powder and a mirror."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not large in size, amount, or effect","cn":""},{"en":"small – used about objects, places, and living things. Used especially with other adjectives to show how you feel about someone or something","cn":""},{"en":"used about prices, rents, levels, or standards","cn":""}]},"vocab":{"pos":"1 adj v n 2 n","senses":[{"en":"A compact is a signed written agreement that binds you to do what you've promised. It also refers to something small or closely grouped together, like the row of compact rental cars you see when you wanted a van."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld44compact.mp3","us":"media/ldoce/hwd/ame/6/ld44compact.mp3"},"examples":[{"en":"The kitchen was compact but well equipped.","cn":"这间厨房虽然空间小但设备齐全。"},{"en":"He had a compact and muscular body.","cn":"他个子矮小健壮。"}],"oxford":{"phon":"kəmˈpækt","pos":"adjective","senses":[{"en":"smaller than is usual for things of the same kind","cn":"小型的；袖珍的","lab":"usually approving","ex":{"en":"a compact camera","cn":"袖珍照相机"}},{"en":"using or filling only a small amount of space","cn":"紧凑的；体积小的","ex":{"en":"The kitchen was compact but well equipped.","cn":"这间厨房虽然空间小但设备齐全。"}},{"en":"closely packed together","cn":"紧密的；坚实的","ex":{"en":"a compact mass of earth","cn":"一堆压得很结实的泥土"}},{"en":"small and strong","cn":"矮小而健壮的","ex":{"en":"He had a compact and muscular body.","cn":"他个子矮小，身体健壮。"}},{"en":"a small car","cn":"小汽车","lab":"North American English","pos":"noun"},{"en":"a small flat box with a mirror, containing powder that women use on their faces","cn":"（化妆用的）粉饼","pos":"noun"},{"en":"a formal agreement between two or more people or countries","cn":"协定；协议；契约；合约","lab":"formal","ex":{"en":"The government has signed a compact of free association.","cn":"政府签署了自由联合契约。"},"pos":"noun"},{"en":"to press something tightly together","cn":"把…紧压在一起（或压实）","ex":{"en":"a layer of compacted snow","cn":"压紧的一层雪"},"pos":"verb"}]}}});
